#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADS1115 I2C address (0x48)
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// ADS1115 configuration values
#define ADS1115_CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define ADS1115_CONFIG_PGA_4_096V 0x0060  // PGA ±4.096V
#define ADS1115_CONFIG_DR_128SPS 0x0080  // 128 SPS

// MLX91219 sensitivity (40mV/A)
#define MLX91219_SENSITIVITY 0.04

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to configure the ADS1115
int configure_ads1115(int handle)
{
    // Build the configuration register value
    int config_value = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_DR_128SPS;

    // Write the configuration to the ADS1115
    if (i2cWriteI2CBlockData(handle, ADS1115_REG_CONFIG, &config_value, 1) != 0) {
        fprintf(stderr, "Error writing to ADS1115 configuration register\n");
        return -1;
    }

    return 0;
}

// Function to read the current from the MLX91219
float read_current(int handle)
{
    // Read the conversion register (2 bytes)
    char data[2];
    if (i2cReadI2CBlockData(handle, ADS1115_REG_CONVERT, data, 2) != 2) {
        fprintf(stderr, "Error reading from ADS1115 conversion register\n");
        return -1.0;
    }

    // Combine the two bytes into a 16-bit value
    int16_t raw_value = (data[0] << 8) | data[1];

    // Convert the raw value to voltage (assuming ±4.096V range)
    float voltage = (float)raw_value * (4.096 / 32768.0);

    // Convert the voltage to current using the MLX91219 sensitivity
    float current = voltage / MLX91219_SENSITIVITY;

    return current;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus 1
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure the ADS1115
    if (configure_ads1115(i2c_handle) != 0) {
        fprintf(stderr, "ADS1115 configuration failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate) {
        // Read the current from the MLX91219
        float current = read_current(i2c_handle);

        if (current >= 0) {
            // Print the current value
            printf("Current: %.3f A\n", current);
        } else {
            fprintf(stderr, "Failed to read current\n");
        }

        // Wait 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

