#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <math.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define GPIO_CHIP "gpiochip4" // Or "gpiochip0" if gpiochip4 is not available
#define GPIO_PIN 18
#define DEFAULT_SENSITIVITY 100.0 // mV/A
#define DEFAULT_THRESHOLD 5.0 // A
#define LOG_FILE "current_log.txt"

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static float sensitivity = DEFAULT_SENSITIVITY;
static float threshold = DEFAULT_THRESHOLD;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device);
int spi_read_adc(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_current(float voltage, float sensitivity);
void gpio_init(const char *chip, int pin);
void gpio_set_value(int value);
void gpio_uninit(void);
void log_data(float current);
void signal_handler(int sig);

// SPI initialization function
int spi_init(const char *device) {
    int fd;
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS_PER_WORD;
    uint32_t speed = SPI_SPEED;

    fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

