    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read raw 16-bit value from ADS1115
int read_ads1115(int handle, uint16_t *raw_value) {
    char buf[2];
    int16_t temp_value;

    // Configure ADS1115 for single-ended reading (adjust configuration as needed)
    // Example: Set single-ended channel 0, 4.096V range, single-shot mode
    char config_buf[3];
    config_buf[0] = 0x01; // Configuration register
    config_buf[1] = 0xC3; // MSB: 11000011 (Single-ended AIN0, +/-4.096V, Single-shot)
    config_buf[2] = 0x83; // LSB: 10000011 (128 SPS, Disable comparator)

    if (i2cWriteDevice(handle, config_buf, 3) != 0) {
        fprintf(stderr, "Failed to write configuration to ADS1115\n");
        return -1;
