    // Combine the two bytes into a 16-bit value
    temp_value = (buf[0] << 8) | buf[1];

    // Sign extend if necessary (ADS1115 is 16-bit)
    if (temp_value & 0x8000) {
        temp_value |= 0xFFFF0000;
    }

    *raw_value = (uint16_t)temp_value;

    return 0;
}

