// Constants
#define I2C_BUS 1
#define MICS4514_ADDR 0x48
#define CO_REG 0x00
#define NO2_REG 0x02
#define ALERT_THRESHOLD 25.0
#define LOG_FILE_CO "co_log.txt"
#define LOG_FILE_ALERT "alert_log.txt"

// Global variables
int i2c_handle;
FILE *co_log_file, *alert_log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int *ox, int *no2);
float calculate_co_ppm(int ox_raw);
void log_co_data(float co_ppm);
void check_alert_threshold(float co_ppm);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// I2C initialization
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MICS4514_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int *ox, int *no2) {
    char buf[4];
    int result = i2cReadI2CBlockData(i2c_handle, CO_REG, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    *ox = (buf[0] << 8) | buf[1];
    *no2 = (buf[2] << 8) | buf[3];

    return 0;
}

// Calculate CO PPM
float calculate_co_ppm(int ox_raw) {
    // Simple linear conversion (replace with actual calibration data)
    return (float)ox_raw * 0.1; // Example: 0.1 PPM per raw unit
}

// Log CO data
void log_co_data(float co_ppm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(co_log_file, "%s, CO: %.2f PPM\n", timestamp, co_ppm);
    fflush(co_log_file); // Ensure data is written to file immediately
}

// Check alert threshold
void check_alert_threshold(float co_ppm) {
    if (co_ppm > ALERT_THRESHOLD) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

        fprintf(alert_log_file, "%s, ALERT: CO level exceeded %.2f PPM\n", timestamp, ALERT_THRESHOLD);
        fflush(alert_log_file);
    }
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (co_log_file != NULL) {
        fclose(co_log_file);
    }
    if (alert_log_file != NULL) {
        fclose(alert_log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log files
    co_log_file = fopen(LOG_FILE_CO, "a");
    if (co_log_file == NULL) {
        fprintf(stderr, "Error opening CO log file\n");
        cleanup();
        return 1;
    }

    alert_log_file = fopen(LOG_FILE_ALERT, "a");
    if (alert_log_file == NULL) {
        fprintf(stderr, "Error opening alert log file\n");
        cleanup();
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int ox_raw, no2_raw;
    float co_ppm;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&ox_raw, &no2_raw) == 0) {
            co_ppm = calculate_co_ppm(ox_raw);
            log_co_data(co_ppm);
            check_alert_threshold(co_ppm);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }
        gpioDelay(5000); // 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

