#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define I2C addresses for the microphones
#define MIC1_ADDR 0x48
#define MIC2_ADDR 0x49

// Define the I2C bus number
#define I2C_BUS 1

// Define the sampling rate (in milliseconds)
#define SAMPLING_RATE 100

// Define the log file name
#define LOG_FILE "audio_log.txt"

// Define the sensitivity of the microphones (in dBV/Pa)
#define SENSITIVITY -38.0

// Define the reference pressure (in Pa)
#define REFERENCE_PRESSURE 20e-6

// Global variables for I2C handles
int i2c_handle1 = -1;
int i2c_handle2 = -1;

// Function prototypes
int read_microphone(int i2c_handle);
float calculate_sound_pressure_level(int raw_data);
void log_data(float s1_db, float s2_db);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Close I2C handles if they are open
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to read data from a microphone
int read_microphone(int i2c_handle) {
    char buffer[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -999; // Indicate an error
    }

    // Combine the two bytes into a 16-bit signed integer
    int16_t raw_data = (buffer[0] << 8) | buffer[1];

    return raw_data;
}

// Function to calculate the sound pressure level
float calculate_sound_pressure_level(int raw_data) {
    // Convert raw data to voltage (assuming 3.3V reference)
    float voltage = (float)raw_data / 65535.0 * 3.3;

    // Convert voltage to sound pressure level (dB)
    float sound_pressure_level = 20 * log10(voltage / REFERENCE_PRESSURE) + SENSITIVITY;

    return sound_pressure_level;
}

// Function to log the data to a file
void log_data(float s1_db, float s2_db) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    // Format the timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Open the log file in append mode
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    // Write the timestamp and sound pressure levels to the log file
    fprintf(fp, "%s, Sensor 1: %.2f dB, Sensor 2: %.2f dB\n", timestamp, s1_db, s2_db);

    // Close the log file
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles for both microphones
    i2c_handle1 = i2cOpen(I2C_BUS, MIC1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, MIC2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read data from both microphones
        int raw_data1 = read_microphone(i2c_handle1);
        int raw_data2 = read_microphone(i2c_handle2);

        // Calculate sound pressure levels
        float s1_db = calculate_sound_pressure_level(raw_data1);
        float s2_db = calculate_sound_pressure_level(raw_data2);

        // Log the data
        log_data(s1_db, s2_db);

        // Wait for the next sample
        gpioDelay(SAMPLING_RATE * 1000); // Convert ms to microseconds
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to avoid compiler warnings.
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioTerminate();

    return 0;
}

