    mic1_data.sample_count = 0;
    mic2_data.sample_count = 0;

    // Main loop
    while (!terminate) {
        // Sample microphone 1
        int mic1_adc_value = read_mcp3008(0);
        if (mic1_adc_value >= 0) {
            mic1_data.mic1_samples[mic1_data.sample_count] = (int16_t)(mic1_adc_value * 1000000 / 1024); // Scale to 16-bit range
            mic1_data.sample_count++;
