        }

        // Check if sampling window is complete
        if (mic1_data.sample_count >= SAMPLING_WINDOW_MS && mic2_data.sample_count >= SAMPLING_WINDOW_MS) {
            // Calculate RMS values
            double mic1_rms = calculate_rms(mic1_data.mic1_samples, SAMPLING_WINDOW_MS);
            double mic2_rms = calculate_rms(mic2_data.mic2_samples, SAMPLING_WINDOW_MS);

            // Check if RMS threshold is exceeded
            if (mic1_rms > RMS_THRESHOLD || mic2_rms > RMS_THRESHOLD) {
                printf("RMS threshold exceeded! mic1_rms=%.2f, mic2_rms=%.2f\n", mic1_rms, mic2_rms);
