#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define GPIO_LED 17
#define SAMPLE_RATE_HZ 10
#define BUFFER_SIZE 100
#define OVERCURRENT_THRESHOLD 50.0
#define SENSOR_MIN_VOLTAGE 0.5
#define SENSOR_MAX_VOLTAGE 4.5
#define SENSOR_MIN_CURRENT 0.0
#define SENSOR_MAX_CURRENT 100.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

CircularBuffer current_buffer;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int read_ads1115(int *raw_value);
float convert_to_current(int raw_value);
void add_to_buffer(float current);
float calculate_average();
void control_led(float average_current);
void signal_handler(int signal);
void cleanup();

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read raw ADC value from ADS1115
int read_ads1115(int *raw_value) {
    char config[3];
    config[0] = CONFIG_REG;
    config[1] = 0x40; // Single-ended A0, 4.096V, 128 SPS, Disable comparator
    config[2] = 0x83; // Start single conversion

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "I2C write config failed\n");
        return 1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    char read_reg[1];
    read_reg[0] = CONVERSION_REG;

    if (i2cWriteDevice(i2c_handle, read_reg, 1) != 0) {
        fprintf(stderr, "I2C write read reg failed\n");
        return 1;
    }

    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "I2C read failed\n");
        return 1;
    }

    *raw_value = (data[0] << 8) | data[1];
    return 0;
}

// Convert raw ADC value to current (Amperes)
float convert_to_current(int raw_value) {
    float voltage = (float)raw_value * 4.096 / 32768.0; // 4.096V range
    float current = (voltage - SENSOR_MIN_VOLTAGE) / (SENSOR_MAX_VOLTAGE - SENSOR_MIN_VOLTAGE) * SENSOR_MAX_CURRENT;
    return current;
}

// Add current reading to circular buffer
void add_to_buffer(float current) {
    current_buffer.buffer[current_buffer.head] = current;
    current_buffer.head = (current_buffer.head + 1) % BUFFER_SIZE;
    if (current_buffer.count < BUFFER_SIZE) {
        current_buffer.count++;
    }
}

// Calculate average current from circular buffer
float calculate_average() {
    if (current_buffer.count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < current_buffer.count; i++) {
        sum += current_buffer.buffer[i];
    }
    return sum / current_buffer.count;
}

// Control LED based on average current
void control_led(float average_current) {
    if (average_current > OVERCURRENT_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    gpioWrite(GPIO_LED, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (initialize_pigpio()) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c()) {
        cleanup();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize circular buffer
    init_circular_buffer(&current_buffer);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int raw_value;
    float current;
    float average_current;

    // Main loop
    while (!terminate) {
        // Read ADC value
        if (read_ads1115(&raw_value)) {
            fprintf(stderr, "Error reading ADC, retrying...\n");
            gpioDelay(100000); // 100ms delay before retry
            continue;
        }

        // Convert to current
        current = convert_to_current(raw_value);

        // Add to circular buffer
        add_to_buffer(current);

        // Calculate average
        average_current = calculate_average();

        // Control LED
        control_led(average_current);

        // Print current reading and average
        printf("Current: %.2f A, Average: %.2f A\n", current, average_current);

        // Wait for next sample
        gpioDelay(1000000 / SAMPLE_RATE_HZ); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

