    return sum / current_buffer.count;
}

// Control LED based on average current
void control_led(float average_current) {
    if (average_current > OVERCURRENT_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    gpioWrite(GPIO_LED, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (initialize_pigpio()) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c()) {
        cleanup();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize circular buffer
    init_circular_buffer(&current_buffer);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int raw_value;
    float current;
    float average_current;

    // Main loop
    while (!terminate) {
        // Read ADC value
        if (read_ads1115(&raw_value)) {
            fprintf(stderr, "Error reading ADC, retrying...\n");
            gpioDelay(100000); // 100ms delay before retry
            continue;
        }

        // Convert to current
        current = convert_to_current(raw_value);

        // Add to circular buffer
        add_to_buffer(current);

        // Calculate average
        average_current = calculate_average();

        // Control LED
        control_led(average_current);

        // Print current reading and average
        printf("Current: %.2f A, Average: %.2f A\n", current, average_current);

        // Wait for next sample
        gpioDelay(1000000 / SAMPLE_RATE_HZ); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
