#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define TCS34725_ADDR 0x29
#define ENABLE_REG 0x00
#define ID_REG 0x12
#define ATIME_REG 0x01
#define AGAIN_REG 0x0F
#define CDATA_REG 0x14
#define RDATA_REG 0x16
#define GDATA_REG 0x18
#define BDATA_REG 0x1A
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define LOG_FILE "color_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c(int bus, int addr);
int verify_sensor_id(int handle);
int configure_sensor(int handle);
int read_color_data(int handle, unsigned int *clear, unsigned int *red, unsigned int *green, unsigned int *blue);
int log_color_data(FILE *fp, unsigned int clear, unsigned int red, unsigned int green, unsigned int blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize I2C bus
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02x: %d\n", bus, addr, handle);
        return 1;
    }
    return 0;
}

// Verify sensor ID
int verify_sensor_id(int handle) {
    char id;
    if (i2cReadI2CBlockData(handle, ID_REG, &id, 1) != 1) {
        fprintf(stderr, "Failed to read sensor ID\n");
        return 1;
    }
    if (id != 0x44) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02x\n", id);
        return 1;
    }
    return 0;
}

// Configure sensor
int configure_sensor(int handle) {
    if (i2cWriteByteData(handle, ATIME_REG, 0xFF) < 0) {
        fprintf(stderr, "Failed to write ATIME register\n");
        return 1;
    }
    if (i2cWriteByteData(handle, AGAIN_REG, 0x01) < 0) {
        fprintf(stderr, "Failed to write AGAIN register\n");
        return 1;
    }
    if (i2cWriteByteData(handle, ENABLE_REG, 0x01 | 0x02) < 0) {
        fprintf(stderr, "Failed to write ENABLE register\n");
        return 1;
    }
    return 0;
}

// Read color data
int read_color_data(int handle, unsigned int *clear, unsigned int *red, unsigned int *green, unsigned int *blue) {
    char data[8];
    if (i2cReadI2CBlockData(handle, CDATA_REG, data, 8) != 8) {
        fprintf(stderr, "Failed to read color data\n");
        return 1;
    }

    *clear = (data[1] << 8) | data[0];
    *red   = (data[3] << 8) | data[2];
    *green = (data[5] << 8) | data[4];
    *blue  = (data[7] << 8) | data[6];

    return 0;
}

// Log color data to CSV file
int log_color_data(FILE *fp, unsigned int clear, unsigned int red, unsigned int green, unsigned int blue) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c(I2C_BUS, TCS34725_ADDR) != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify sensor ID
    if (verify_sensor_id(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Clear,Red,Green,Blue\n");
    }
    rewind(log_file);

    // Main loop
    int retry_counter = 0;
    while (!terminate) {
        unsigned int clear, red, green, blue;

        if (read_color_data(i2c_handle, &clear, &red, &green, &blue) == 0) {
            log_color_data(log_file, clear, red, green, blue);
        } else {
            fprintf(stderr, "Transient I2C read failure. Retrying...\n");
            retry_counter++;
            if (retry_counter >= RETRY_COUNT) {
                fprintf(stderr, "Too many consecutive I2C read failures. Exiting.\n");
                break;
            }
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retry_counter = 0;
        }

        gpioDelay(1000000); // Delay for 1 second (1000000 microseconds)
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

