    }

    // Open log file
    log_file = fopen("moisture_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Moisture1,Moisture2\n");
    }

    // Main loop
    while (program_running) {
        // Read sensor values
        int adc_value1 = read_mcp3008(0);
        int adc_value2 = read_mcp3008(1);

        if (adc_value1 < 0 || adc_value2 < 0) {
            fprintf(stderr, "Error reading sensor values. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Map ADC values to moisture percentages
        float moisture1 = map_adc_to_moisture(adc_value1);
