int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len);
int read_mcp3008(int fd, int channel);
float adc_to_voltage(int adc_value);
float voltage_to_current(float voltage);
void log_current(float current);
void shutdown_motor(int gpio_pin);
void enable_motor(int gpio_pin);
void signal_handler(int sig);
int setup_gpio(int gpio_pin);
int cleanup_gpio(int gpio_pin);

// SPI transfer function
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    int ret = ioctl(fd, SPI_IOC_MESSAGE(1), &transfer);
    if (ret < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read MCP3008 function
int read_mcp3008(int fd, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // MCP3008 command: start bit (1), single-ended mode (1), channel (3 bits), don't care (3 bits)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended + channel
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(fd, tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "Failed to read MCP3008 channel %d\n", channel);
        return -1;
    }

    // Extract the 10-bit ADC value from the response
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return (float)adc_value * 3.3 / 1024.0;
}

// Convert voltage to current
float voltage_to_current(float voltage) {
    return (voltage - SENSOR_OFFSET) / SENSOR_SENSITIVITY;
