#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x40
#define PRESSURE_REGISTER 0x00
#define PRESSURE_SCALE 500.0
#define PRESSURE_OFFSET 0.0
#define LOG_FILE "pressure_log.csv"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_pressure_sensor(int *raw_pressure);
float convert_to_kPa(int raw_pressure);
int log_pressure_data(float pressure_kPa);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Pressure sensor reading function
int read_pressure_sensor(int *raw_pressure) {
    char buffer[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REGISTER, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading pressure sensor: %d\n", result);
        return -1;
    }

    *raw_pressure = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Pressure conversion function
float convert_to_kPa(int raw_pressure) {
    return (float)raw_pressure / 65535.0 * PRESSURE_SCALE + PRESSURE_OFFSET;
}

// Data logging function
int log_pressure_data(float pressure_kPa) {
    time_t now = time(NULL);
    struct tm *tstruct = gmtime(&now);
    char timestamp[30];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a+");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
            return -1;
        }
        fprintf(log_file, "timestamp,pressure_kPa\n"); // Write header if file is newly created
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure_kPa);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    int raw_pressure;
    float pressure_kPa;
    int retries;

    // Main loop
    while (!terminate) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (read_pressure_sensor(&raw_pressure) == 0) {
                pressure_kPa = convert_to_kPa(raw_pressure);
                if (log_pressure_data(pressure_kPa) != 0) {
                    fprintf(stderr, "Error logging pressure data\n");
                }
                break; // Exit retry loop on success
            } else {
                retries++;
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            }
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Max retries reached, skipping logging\n");
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

