#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register settings
#define CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define CONFIG_MUX_AIN0_GND 0x4000 // AIN0 single-ended, GND
#define CONFIG_PGA_2_3 0x0060   // +/- 6.144V, 2/3 gain
#define CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define CONFIG_DR_128 0x0080    // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_ACT_LOW 0x0000 // Active low comparator
#define CONFIG_COMP_LAT_NON_LATCH 0x0000 // Non-latching comparator
#define CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// GPIO pin for warning LED
#define WARNING_LED_PIN 17

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_ads1115(int i2c_handle, int *pressure_adc, int *temperature_adc);
float adc_to_pressure(int adc_value);
float adc_to_temperature(int adc_value);
void display_data(float pressure, float temperature);
void check_pressure_threshold(float pressure);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read pressure and temperature from ADS1115
int read_ads1115(int i2c_handle, int *pressure_adc, int *temperature_adc) {
    char config[3];
    char data[2];
    int retries = 3;
    int result;

    // Configure ADS1115 for single-ended AIN0 and AIN1
    config[0] = CONFIG_OS_SINGLE | CONFIG_MUX_AIN0_GND | CONFIG_PGA_2_3 | CONFIG_MODE_SINGLE | CONFIG_DR_128 | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_ACT_LOW | CONFIG_COMP_LAT_NON_LATCH | CONFIG_COMP_QUE_DISABLE;
    config[1] = 0x00; // Dummy byte
    config[2] = 0x00; // Dummy byte

    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, config, 3);
        if (result == 0) {
            break; // Configuration successful
        } else {
            fprintf(stderr, "Error writing to ADS1115 configuration register: %d, retrying...\n", result);
            gpioDelay(1000); // Wait 1 ms before retrying
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to write to ADS1115 configuration register after multiple retries.\n");
        return -1; // Indicate failure
    }

    gpioDelay(10); // Wait for conversion to complete

    retries = 3;
    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, data, 2);
        if (result == 2) {
            break; // Read successful
        } else {
            fprintf(stderr, "Error reading from ADS1115 conversion register: %d, retrying...\n", result);
            gpioDelay(1000); // Wait 1 ms before retrying
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to read from ADS1115 conversion register after multiple retries.\n");
        return -1; // Indicate failure
    }

    // Combine the two bytes to form the 16-bit ADC value
    *pressure_adc = (data[0] << 8) | data[1];
    *temperature_adc = (data[0] << 8) | data[1]; // Assuming same value for temperature for simplicity

    return 0; // Indicate success
}

// Function to convert ADC value to pressure (kPa)
float adc_to_pressure(int adc_value) {
    float pressure = (float)adc_value * 400.0 / 4095.0; // Linear transfer function
    return pressure;
}

// Function to convert ADC value to temperature (°C)
float adc_to_temperature(int adc_value) {
    float temperature = (float)adc_value * 100.0 / 4095.0; // Simplified linear approximation
    return temperature;
}

// Function to display pressure and temperature data
void display_data(float pressure, float temperature) {
    printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);
}

// Function to check pressure threshold and control LED
void check_pressure_threshold(float pressure) {
    if (pressure > 105.0) {
        gpioWrite(WARNING_LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(WARNING_LED_PIN, 0); // Turn LED off
    }
}

int main() {
    int pressure_adc, temperature_adc;
    float pressure, temperature;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure warning LED pin as output
    gpioSetMode(WARNING_LED_PIN, PI_OUTPUT);
    gpioWrite(WARNING_LED_PIN, 0); // Initially turn LED off

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read pressure and temperature from ADS1115
        if (read_ads1115(i2c_handle, &pressure_adc, &temperature_adc) == 0) {
            // Convert ADC values to pressure and temperature
            pressure = adc_to_pressure(pressure_adc);
            temperature = adc_to_temperature(temperature_adc);

            // Display data
            display_data(pressure, temperature);

            // Check pressure threshold and control LED
            check_pressure_threshold(pressure);
        } else {
            fprintf(stderr, "Error reading ADS1115 data.\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Clean up and exit
    i2cClose(i2c_handle);
    gpioWrite(WARNING_LED_PIN, 0); // Turn LED off
    gpioTerminate();

    return 0;
}

