#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define VCC 3.3
#define SENSITIVITY 0.066 // 66 mV/A
#define OVERCURRENT_THRESHOLD 10.0 // 10A
#define SHUTDOWN_GPIO 27
#define SAMPLE_INTERVAL_MS 100

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_current(float voltage);
void log_current(float current);
void check_overcurrent(float current);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate error
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (result = %d)\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * VCC;
}

// Function to convert voltage to current
float voltage_to_current(float voltage) {
    return (voltage / (VCC / 2.0)) * SENSITIVITY;
}

// Function to log current reading with timestamp
void log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Current: %.2f A\n", timestamp, current);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to check for overcurrent condition
void check_overcurrent(float current) {
    if (current > OVERCURRENT_THRESHOLD) {
        fprintf(stderr, "Overcurrent detected: %.2f A\n", current);
        log_current(current); // Log the event

        // Trigger motor shutdown
        gpioWrite(SHUTDOWN_GPIO, 1); // Set GPIO HIGH
        fprintf(log_file, "OVERCURRENT EVENT\n");
        fflush(log_file);

        // Stop the program
        terminate = 1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("current_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO27 as output
    gpioSetMode(SHUTDOWN_GPIO, PI_OUTPUT);
    gpioWrite(SHUTDOWN_GPIO, 0); // Initially LOW

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage and current
        float voltage = adc_to_voltage(adc_value);
        float current = voltage_to_current(voltage);

        // Log current reading
        log_current(current);

        // Check for overcurrent condition
        check_overcurrent(current);

        // Wait for the next sample interval
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioWrite(SHUTDOWN_GPIO, 0); // Reset GPIO27 to LOW
    gpioTerminate();

    return 0;
}

