    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Reads the ADC value from the ADS1115
int read_ads1115(int16_t *raw_value) {
    // Configure ADS1115 for single-ended AIN0, 16-bit resolution, continuous conversion
    // and 128 SPS.  Single shot mode is not suitable for continuous monitoring.
    // Refer to ADS1115 datasheet for register configuration details.
    // This example assumes the configuration is already set up externally (e.g., via a microcontroller).

    // Read the conversion register (0x00)
    char config[3];
    config[0] = 0x01; // Configuration register address
    config[1] = 0xC3; // Configuration value (single-ended AIN0, 16-bit, continuous, 128 SPS)
    config[2] = 0x83; // MSB first, 16-bit resolution

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for conversion to complete (adjust delay as needed)
    gpioDelay(10000); // 10ms

    // Read the conversion register (0x00)
    config[0] = 0x00; // Conversion register address
    if (i2cWriteDevice(i2c_handle, config, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    *raw_value = (data[0] << 8) | data[1];
    return 0;
}

// Converts the raw ADC value to a voltage
float convert_to_voltage(int16_t raw_value) {
    // Assuming 3.3V reference voltage for the ADS1115
    return ((float)raw_value / 32768.0) * 3.3;
}

// Converts the voltage to a pressure in kPa
float convert_to_pressure(float voltage) {
    return (voltage - OFFSET_VOLTAGE) / SENSITIVITY;
}

// Validates the pressure reading
int validate_pressure(float pressure) {
    if (pressure >= MIN_PRESSURE && pressure <= MAX_PRESSURE) {
        return 1;
    } else {
        fprintf(stderr, "Pressure out of range: %.2f kPa\n", pressure);
        return 0;
    }
}

// Logs the pressure reading to a file
int log_pressure(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s, %.2f kPa\n", timestamp, pressure);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int16_t raw_value;
        if (read_ads1115(&raw_value) == 0) {
            float voltage = convert_to_voltage(raw_value);
            float pressure = convert_to_pressure(voltage);

            if (validate_pressure(pressure)) {
                if (log_pressure(pressure) != 0) {
                    fprintf(stderr, "Error logging pressure\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading ADC value\n");
        }

        gpioDelay(1000000); // 1 second delay
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Pressure monitoring stopped.\n");
    return 0;
}

