#include <pigpio.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3208_CHANNEL 0 // Channel 0 for humidity, Channel 1 for temperature
#define HUMIDITY_THRESHOLD 80.0
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345
#define LOG_FILE "humidity_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3208(int channel);
float calculate_humidity(int adc_value);
float calculate_temperature(int adc_value);
void log_data(float humidity, float temperature);
void send_data_to_server(float humidity, float temperature);
void signal_handler(int signal);

// Function to read from MCP3208 ADC
int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3208 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3208 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calculate humidity
float calculate_humidity(int adc_value) {
    float humidity = (adc_value / 1023.0) * 100.0;
    return humidity;
}

// Function to calculate temperature (using a simplified model)
float calculate_temperature(int adc_value) {
    // This is a placeholder.  A real implementation would use
    // the thermistor's resistance to calculate temperature using
    // the Steinhart-Hart equation or a similar model.
    // For now, we'll just return a linear approximation.
    float temperature = (adc_value / 1023.0) * 25.0; // Linear approximation
    return temperature;
}

// Function to log data to file
void log_data(float humidity, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fflush(log_file); // Ensure data is written immediately
}

// Function to send data to server
void send_data_to_server(float humidity, float temperature) {
    int sockfd;
    struct sockaddr_in servaddr;
    char message[256];

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Error: Socket creation failed");
        return;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &servaddr.sin_addr) <= 0) {
        perror("Error: Invalid address/ Address not supported");
        close(sockfd);
        return;
    }

    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("Error: Connection Failed");
        close(sockfd);
        return;
    }

    snprintf(message, sizeof(message), "Timestamp:%ld,Humidity:%.2f,Temperature:%.2f", time(NULL), humidity, temperature);
    send(sockfd, message, strlen(message), 0);
    close(sockfd);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stdout, "Humidity and Temperature Monitoring Started...\n");

    while (!terminate) {
        // Read ADC values
        int humidity_adc = read_mcp3208(MCP3208_CHANNEL);
        int temperature_adc = read_mcp3208(MCP3208_CHANNEL + 8); // Channel 1 for temperature

        if (humidity_adc == -1 || temperature_adc == -1) {
            fprintf(stderr, "Error: Failed to read ADC values\n");
            continue; // Skip to the next iteration
        }

        // Calculate humidity and temperature
        float humidity = calculate_humidity(humidity_adc);
        float temperature = calculate_temperature(temperature_adc);

        // Log data
        log_data(humidity, temperature);

        // Check humidity threshold and send alert
        if (humidity > HUMIDITY_THRESHOLD) {
            fprintf(stdout, "Humidity exceeds threshold (%.2f%% > %.2f%%), sending alert...\n", humidity, HUMIDITY_THRESHOLD);
            send_data_to_server(humidity, temperature);
        }

        // Print data to console
        printf("Humidity: %.2f%%, Temperature: %.2f°C\n", humidity, temperature);

        // Wait for 5 seconds
        sleep(5);
    }

    // Clean up
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    fprintf(stdout, "Humidity and Temperature Monitoring Stopped.\n");
    return 0;
}

