#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000
#define MCP3208_CS_PIN 8 // GPIO8 on gpiochip4
#define VREF 3.3f
#define TMP36_SENSITIVITY 0.01f
#define TMP36_OFFSET 0.5f
#define TMP36_MIN_VOLTAGE -40.0f
#define TMP36_MAX_VOLTAGE 125.0f
#define LOG_FILE "temperature_log.csv"
#define READ_INTERVAL_SEC 1

// Global variables (minimize usage)
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device);
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len);
int read_mcp3208(int cs_pin, int channel);
float adc_to_voltage(int adc_value, float vref);
float voltage_to_celsius(float voltage);
int log_temperature(float temperature);
void signal_handler(int sig);
void cleanup();

// SPI Initialization
int spi_init(const char *device) {
    int fd;
    unsigned int mode = SPI_MODE;
    unsigned int bits = SPI_BITS_PER_WORD;
    unsigned int speed = SPI_MAX_SPEED_HZ;

    fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_MODE, &mode) == -1) {
        perror("Error getting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_BITS_PER_WORD, &bits) == -1) {
        perror("Error getting bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error getting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_MAX_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Read MCP3208
int read_mcp3208(int cs_pin, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    int adc_value;

    // Construct SPI message (MCP3208 datasheet)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    // Assert CS line
    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("Error setting CS low");
        return -1;
    }

    // Perform SPI transfer
    if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // De-assert CS line
    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("Error setting CS high");
        return -1;
    }

    // Extract ADC value from response
    adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// ADC to Voltage
float adc_to_voltage(int adc_value, float vref) {
    return ((float)adc_value / 4095.0f) * vref;
}

// Voltage to Celsius
float voltage_to_celsius(float voltage) {
    return (voltage - TMP36_OFFSET) / TMP36_SENSITIVITY;
}

// Log Temperature
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "w");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
        fprintf(log_file, "Timestamp,Temperature_Celsius\n");
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file);

    return 0;
}

// Signal Handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup
void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    int adc_value;
    float voltage;
    float temperature;

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // SPI Initialization
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // GPIO Initialization
    gpio_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        cleanup();
        return 1;
    }

    cs_line = gpiod_chip_get_line(gpio_chip, MCP3208_CS_PIN);
    if (!cs_line) {
        perror("Error getting CS line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "temperature_sensor", 0) < 0) {
        perror("Error requesting CS line as output");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        adc_value = read_mcp3208(MCP3208_CS_PIN, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Try again
        }

        // Convert ADC value to voltage
        voltage = adc_to_voltage(adc_value, VREF);

        // Convert voltage to temperature
        temperature = voltage_to_celsius(voltage);

        // Log temperature
        if (log_temperature(temperature) < 0) {
            fprintf(stderr, "Error logging temperature\n");
        }

        // Validate temperature
        if (temperature < TMP36_MIN_VOLTAGE || temperature > TMP36_MAX_VOLTAGE) {
            fprintf(stderr, "Temperature out of range: %.2f C\n", temperature);
        }

        // Wait for the next reading
        sleep(READ_INTERVAL_SEC);
    }

    // Cleanup
    cleanup();

    return 0;
}

