#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define CS_PIN 8
#define ADC_CHANNEL_X 0
#define ADC_CHANNEL_Y 1
#define ADC_CHANNEL_Z 2
#define VCC 3.3
#define ZERO_G_VOLTAGE 1.65
#define SENSITIVITY 300.0
#define IMPACT_THRESHOLD 2.0
#define SAMPLE_RATE 100 // Hz
#define SAMPLE_PERIOD 10000000 / SAMPLE_RATE // microseconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_acceleration(float voltage);
float calculate_magnitude(float x, float y, float z);
void log_data(float x, float y, float z, float magnitude);
void impact_detected(float x, float y, float z, float magnitude);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    gpioWrite(CS_PIN, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008

    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * VCC;
}

// Function to convert voltage to acceleration (g)
float voltage_to_acceleration(float voltage) {
    return (voltage - ZERO_G_VOLTAGE) / SENSITIVITY;
}

// Function to calculate acceleration magnitude
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Function to log data to file
void log_data(float x, float y, float z, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to detect impacts
void impact_detected(float x, float y, float z, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,IMPACT DETECTED,%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect MCP3008 initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        // Read ADC values
        int adc_x = read_mcp3008(ADC_CHANNEL_X);
        int adc_y = read_mcp3008(ADC_CHANNEL_Y);
        int adc_z = read_mcp3008(ADC_CHANNEL_Z);

        if (adc_x == -1 || adc_y == -1 || adc_z == -1) {
            fprintf(stderr, "Error: Failed to read ADC values\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC values to voltages
        float voltage_x = adc_to_voltage(adc_x);
        float voltage_y = adc_to_voltage(adc_y);
        float voltage_z = adc_to_voltage(adc_z);

        // Convert voltages to accelerations
        float acceleration_x = voltage_to_acceleration(voltage_x);
        float acceleration_y = voltage_to_acceleration(voltage_y);
        float acceleration_z = voltage_to_acceleration(voltage_z);

        // Calculate acceleration magnitude
        float magnitude = calculate_magnitude(acceleration_x, acceleration_y, acceleration_z);

        // Log data
        log_data(acceleration_x, acceleration_y, acceleration_z, magnitude);

        // Check for impact
        if (magnitude > IMPACT_THRESHOLD) {
            impact_detected(acceleration_x, acceleration_y, acceleration_z, magnitude);
        }

        // Delay for sampling rate
        gpioDelay(SAMPLE_PERIOD);
    }

    // Close SPI and log file
    spiClose(spi_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

