#define LOG_FILE "biometric_log.csv"
#define SAMPLE_INTERVAL_SEC 1

// Si1172 Register Addresses
#define SI1172_REG_COMMAND 0xC0
#define SI1172_REG_FIFO_DATA 0xC1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int *ir_adc, int *red_adc);
int log_data(time_t timestamp, int hr, int spo2, int error_flag);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize the Si1172 sensor
int initialize_sensor() {
    // Example initialization sequence (replace with actual Si1172 init sequence)
    // This is a placeholder and needs to be replaced with the correct initialization sequence
    // from the Si1172 datasheet.
    if (i2cWriteByteData(i2c_handle, SI1172_REG_COMMAND, 0x01) < 0) { // Example command
        fprintf(stderr, "Error writing to command register during initialization.\n");
        return 1; // Sensor absent/uninitialized
    }
    gpioDelay(10000); // 10ms delay
    if (i2cWriteByteData(i2c_handle, SI1172_REG_COMMAND, 0x02) < 0) { // Example command
        fprintf(stderr, "Error writing to command register during initialization.\n");
        return 1; // Sensor absent/uninitialized
    }
    gpioDelay(10000); // 10ms delay

    return 0; // Sensor initialized
}

// Read sensor data
int read_sensor_data(int *ir_adc, int *red_adc) {
    char buffer[4];
    int bytes_read;

    // Trigger measurement (replace with actual command if needed)
    if (i2cWriteByteData(i2c_handle, SI1172_REG_COMMAND, 0x03) < 0) { // Example command
        fprintf(stderr, "Error writing to command register to trigger measurement.\n");
        return 1; // I2C error
    }
    gpioDelay(10000); // 10ms delay

    // Read FIFO data (4 bytes: IR, RED, IR, RED)
    bytes_read = i2cReadI2CBlockData(i2c_handle, SI1172_REG_FIFO_DATA, buffer, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error reading FIFO data: %d\n", bytes_read);
        return 2; // I2C read error
    }

    // Extract IR and RED ADC values (assuming 16-bit values)
    *ir_adc = (buffer[0] << 8) | buffer[1];
    *red_adc = (buffer[2] << 8) | buffer[3];

    return 0; // Success
}

