int log_data(time_t timestamp, int hr, int spo2, int error_flag) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp_str, hr, spo2, error_flag);
    fflush(log_file); // Flush the buffer to ensure data is written to the file

    return 0;
}

