    int ir_adc, red_adc, error_flag;
    time_t current_time;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed. Check I2C connection and sensor configuration.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,HR(bpm),SpO2(%),ErrorFlag\n");
    }
    rewind(log_file);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        current_time = time(NULL);

        // Read sensor data
        error_flag = read_sensor_data(&ir_adc, &red_adc);

        // Log data
        if (error_flag == 0) {
            // Placeholder: Replace with actual HR/SpO2 calculation using Si1172 datasheet
            // For now, use the raw ADC values as proxy values
            int hr = ir_adc; // Proxy HR
            int spo2 = red_adc; // Proxy SpO2

            log_data(current_time, hr, spo2, 0); // Error flag 0 for success
        } else {
            log_data(current_time, 0, 0, error_flag); // Log error
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Sample every second
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

