#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define MCP3008 channel assignments
#define MIC1_CHANNEL 0
#define MIC2_CHANNEL 1

// Define gain control parameters
#define GAIN_MIN 0.1
#define GAIN_MAX 10.0

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold audio data
typedef struct {
    int16_t mic1;
    int16_t mic2;
} audio_data_t;

// Function prototypes
int initialize_pigpio();
int configure_spi();
int read_mcp3008(int channel);
int16_t convert_to_int16(int adc_value);
audio_data_t sample_audio();
audio_data_t subtract_audio(audio_data_t mic1_data, audio_data_t mic2_data);
void apply_gain(audio_data_t audio_data, float gain);
void output_csv(audio_data_t audio_data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Configure SPI interface
int configure_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Convert ADC value to int16_t
int16_t convert_to_int16(int adc_value) {
    return (int16_t)((float)adc_value / 1023.0 * 32767.0);
}

