audio_data_t sample_audio() {
    audio_data_t audio_data;
    int adc_value1 = read_mcp3008(MIC1_CHANNEL);
    int adc_value2 = read_mcp3008(MIC2_CHANNEL);

    if (adc_value1 < 0 || adc_value2 < 0) {
        fprintf(stderr, "Error reading ADC values\n");
        audio_data.mic1 = 0; // Set to zero to avoid garbage output
        audio_data.mic2 = 0;
        return audio_data;
    }

    audio_data.mic1 = convert_to_int16(adc_value1);
    audio_data.mic2 = convert_to_int16(adc_value2);

    return audio_data;
}

// Subtract audio streams
audio_data_t subtract_audio(audio_data_t mic1_data, audio_data_t mic2_data) {
    audio_data_t diff_data;
    diff_data.mic1 = mic1_data.mic1 - mic2_data.mic1;
    diff_data.mic2 = mic1_data.mic2 - mic2_data.mic2;
    return diff_data;
}

// Apply gain to audio data
void apply_gain(audio_data_t audio_data, float gain) {
    audio_data.mic1 = (int16_t)(audio_data.mic1 * gain);
    audio_data.mic2 = (int16_t)(audio_data.mic2 * gain);
}

