void output_csv(audio_data_t audio_data) {
    printf("%d,%d\n", audio_data.mic1, audio_data.mic2);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments for gain
    float gain = GAIN_MIN;
    if (argc > 1) {
        gain = atof(argv[1]);
        if (gain < GAIN_MIN || gain > GAIN_MAX) {
            fprintf(stderr, "Gain value out of range (0.1 to 10.0). Using default gain.\n");
            gain = GAIN_MIN;
        }
    }

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Configure SPI
    if (configure_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        audio_data_t audio_data = sample_audio();
        audio_data_t diff_audio = subtract_audio(audio_data, audio_data);
        apply_gain(diff_audio, gain);
        output_csv(diff_audio);
        gpioDelay(10000); // 10 ms delay (adjust as needed)
    }

    // Clean up
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

