#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define BUZZER_GPIO 18
#define ADC_CHANNEL 0
#define ADC_START_BIT 0x01
#define ADC_SINGLE_ENDED 0x80
#define ADC_DUMMY_BYTE 0x00
#define ADC_MAX_VALUE 1023.0
#define TEMPERATURE_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"
#define FLAME_THRESHOLD 1.0
#define MAX_RETRIES 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
float calculate_voltage(int adc_value);
float calculate_compensated_voltage(float voltage, float temperature);
int detect_flame(float compensated_voltage);
void control_buzzer(int flame_detected);
float read_ambient_temperature();
void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected);
void signal_handler(int signal);

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];
    int count, adc_value;

    // Construct SPI message
    tx_buffer[0] = ADC_START_BIT;
    tx_buffer[1] = (channel << 4) | ADC_SINGLE_ENDED;
    tx_buffer[2] = ADC_DUMMY_BYTE;

    for (count = 0; count < MAX_RETRIES; count++) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 3) {
            // Extract ADC value
            adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            if (adc_value >= 0 && adc_value <= ADC_MAX_VALUE) {
                return adc_value;
            } else {
                fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
                fprintf(log_file, "Error: ADC value out of range: %d\n", adc_value);
                fflush(log_file);
            }
        } else {
            fprintf(stderr, "Error: SPI transfer failed (attempt %d)\n", count + 1);
            fprintf(log_file, "Error: SPI transfer failed (attempt %d)\n", count + 1);
            fflush(log_file);
        }
        gpioDelay(1000); // Wait 1ms before retrying
    }

    fprintf(stderr, "Error: Failed to read ADC value after %d retries\n", MAX_RETRIES);
    fprintf(log_file, "Error: Failed to read ADC value after %d retries\n", MAX_RETRIES);
    fflush(log_file);
    return -1; // Indicate failure
}

// Function to calculate voltage from ADC value
float calculate_voltage(int adc_value) {
    return (adc_value / ADC_MAX_VALUE) * 3.3;
}

// Function to calculate compensated voltage
float calculate_compensated_voltage(float voltage, float temperature) {
    return voltage + (temperature - 25.0) * 0.001;
}

// Function to detect flame
int detect_flame(float compensated_voltage) {
    return (compensated_voltage > FLAME_THRESHOLD) ? 1 : 0;
}

// Function to control the buzzer
void control_buzzer(int flame_detected) {
    gpioWrite(BUZZER_GPIO, flame_detected);
}

// Function to read ambient temperature from file
float read_ambient_temperature() {
    FILE *fp = fopen(TEMPERATURE_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open temperature file. Using default temperature.\n");
        fprintf(log_file, "Error: Could not open temperature file. Using default temperature.\n");
        fflush(log_file);
        return 25.0;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error: Could not read temperature from file. Using default temperature.\n");
        fprintf(log_file, "Error: Could not read temperature from file. Using default temperature.\n");
        fflush(log_file);
        fclose(fp);
        return 25.0;
    }

    fclose(fp);
    float temperature = atof(line);
    return temperature;
}

// Function to log data to file
void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%d,%.3f,%.3f,%.1f,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            raw_adc, voltage, compensated_voltage, temperature, flame_detected);
    fflush(log_file);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    fprintf(log_file, "Caught signal %d, terminating...\n", signal);
    fflush(log_file);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        gpioTerminate();
        return 1;
    }

    // Configure SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        fprintf(log_file, "Error: SPI open failed\n");
        fflush(log_file);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

