    fseek(json_file, 0, SEEK_END);
    long file_size = ftell(json_file);
    if (file_size == 0) {
        fprintf(json_file, "[");
    } else {
        // If the file is not empty, check if the last character is a closing bracket.
        fseek(json_file, -1, SEEK_END);
        int last_char = fgetc(json_file);
        if (last_char == ']') {
            // If the last character is a closing bracket, remove it.
            fseek(json_file, -1, SEEK_SET);
        } else {
            // If the last character is not a closing bracket, add one.
            fprintf(json_file, ",");
        }
        fprintf(json_file, "]]");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read water level
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            // Error reading ADC, skip this iteration
            gpioDelay(100); // Small delay to avoid spamming errors
            continue;
        }

        // Convert to percentage
        float water_level = convert_to_percentage(adc_value);

        // Control LED
        control_led(water_level);

        // Log to JSON
        log_to_json(water_level);

        // Print to console
        printf("Water Level: %.2f%%\n", water_level);

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Cleanup
    spiClose(spi_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
    fclose(json_file);

    return 0;
}

