float calculate_moisture_percentage(int adc_value) {
    if (adc_value < 0) return 0.0;
    if (adc_value > 1023) return 100.0;
    return (float)adc_value / 1023.0 * 100.0;
}

// Function to log data to file
void log_data(int adc_value, float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s, %d, %.2f\n", timestamp, adc_value, moisture_percentage);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int sample_interval = SAMPLE_INTERVAL_SEC;
    if (argc > 1) {
        sample_interval = atoi(argv[1]);
        if (sample_interval <= 0) {
            fprintf(stderr, "Error: Invalid sample interval. Using default (%d seconds).\n", SAMPLE_INTERVAL_SEC);
            sample_interval = SAMPLE_INTERVAL_SEC;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (error code %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("soil_moisture.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring started. Logging to soil_moisture.log. Sample interval: %d seconds. Press Ctrl+C to exit.\n", sample_interval);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            float moisture_percentage = calculate_moisture_percentage(adc_value);
            log_data(adc_value, moisture_percentage);
        } else {
            fprintf(stderr, "Error: Failed to read ADC value. Logging warning.\n");
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);
            fprintf(log_file, "%s, ERROR, Failed to read ADC value\n", timestamp);
            fflush(log_file);
        }

        gpioDelay(sample_interval * 1000); // Delay in milliseconds
    }

    // Cleanup
    printf("Closing SPI, flushing log file, and terminating pigpio...\n");
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

