#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // MCP3008 channel connected to MLX90823
#define VREF 3.3 // Reference voltage
#define MIN_PRESSURE 10.0 // Minimum pressure in kPa
#define MAX_PRESSURE 150.0 // Maximum pressure in kPa
#define MIN_VOLTAGE 0.5 // Minimum voltage in volts
#define MAX_VOLTAGE 4.5 // Maximum voltage in volts
#define MIN_ADC 0 // Minimum ADC value
#define MAX_ADC 1023 // Maximum ADC value

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_pressure(float voltage);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    if (adc_value < MIN_ADC || adc_value > MAX_ADC) {
        fprintf(stderr, "Error: ADC value out of range (%d)\n", adc_value);
        return -1.0;
    }

    return ((float)adc_value / MAX_ADC) * VREF;
}

// Function to convert voltage to pressure
float voltage_to_pressure(float voltage) {
    if (voltage < MIN_VOLTAGE || voltage > MAX_VOLTAGE) {
        fprintf(stderr, "Error: Voltage out of range (%.2fV)\n", voltage);
        return -1.0;
    }

    // Linear mapping
    float pressure = MIN_PRESSURE + (voltage - MIN_VOLTAGE) * (MAX_PRESSURE - MIN_PRESSURE) / (MAX_VOLTAGE - MIN_VOLTAGE);
    return pressure;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure SPI0 bus
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);
        if (voltage < 0) {
            fprintf(stderr, "Error: Failed to convert ADC to voltage\n");
            continue; // Skip to the next iteration
        }

        // Convert voltage to pressure
        float pressure = voltage_to_pressure(voltage);
        if (pressure < 0) {
            fprintf(stderr, "Error: Failed to convert voltage to pressure\n");
            continue; // Skip to the next iteration
        }

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[20]; // YYYY-MM-DDTHH:MM:SSZ\0

        time(&rawtime);
        timeinfo = gmtime(&rawtime); // Use gmtime for UTC time
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

        // Log pressure reading with timestamp
        printf("%s Pressure: %.2f kPa\n", timestamp, pressure);

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Close SPI bus
    spiClose(spi_handle);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

