// Global variables
int spi_handle;
int pump_state = 0; // 0 = off, 1 = on
int log_buffer[BUFFER_SIZE][3]; // Timestamp, Moisture, Pump State
int buffer_index = 0;
int buffer_count = 0;

// Function prototypes
int read_mcp3008(int channel);
void control_pump(int state);
void log_data(int moisture, int pump_state);
void send_data_to_server(int moisture, int pump_state);
void timer_callback(int timer_id, void *user_data);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to control the water pump
void control_pump(int state) {
    if (state != pump_state) {
        gpioWrite(PUMP_PIN, state);
        pump_state = state;
        log_data(-1, pump_state); // Log pump state change
    }
}

// Function to log data to the circular buffer
void log_data(int moisture, int pump_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    log_buffer[buffer_index][0] = now;
    log_buffer[buffer_index][1] = moisture;
    log_buffer[buffer_index][2] = pump_state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

// Function to send data to the server
void send_data_to_server(int moisture, int pump_state) {
    int sockfd;
    struct sockaddr_in serv_addr;
    char message[100];

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        return;
    }

    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &serv_addr.sin_addr) <= 0) {
        perror("inet_pton failed");
        close(sockfd);
        return;
    }

    snprintf(message, sizeof(message), "%d,%d", moisture, pump_state);

    if (sendto(sockfd, (const char *)message, strlen(message), 0, (const struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("sendto failed");
    }

    close(sockfd);
}

// Timer callback function
void timer_callback(int timer_id, void *user_data) {
    int moisture = read_mcp3008(0);
    if (moisture < 0) {
        fprintf(stderr, "Error reading moisture, skipping pump control.\n");
        return;
    }

    // Pump control logic with hysteresis
    if (moisture < LOW_THRESHOLD && pump_state == 0) {
        control_pump(1); // Turn pump on
    } else if (moisture > HIGH_THRESHOLD && pump_state == 1) {
        control_pump(0); // Turn pump off
    }

    log_data(moisture, pump_state);
    send_data_to_server(moisture, pump_state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    control_pump(0); // Turn pump off
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output for pump control
    gpioSetMode(PUMP_PIN, PI_OUTPUT);
    control_pump(0); // Ensure pump is off at startup

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer
    gpioSetTimerFuncEx(0, 5000, timer_callback, NULL); // Timer 0, every 5 seconds

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        sleep(1); // Sleep to reduce CPU usage
    }

    return 0;
}

