#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define MAX30102_ADDR 0x57
#define FIFO_DATA_REG 0x07
#define MODE_CONFIG_REG 0x06
#define SPO2_CONFIG_REG 0x08
#define LED1_PA_REG 0x09
#define LED2_PA_REG 0x0A
#define PART_ID_REG 0xFF
#define PART_ID_VALUE 0x15
#define FIFO_DATA_LENGTH 6
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int verify_sensor();
int init_max30102();
int read_fifo_data(uint8_t *data);
int process_fifo_data(uint8_t *data, float *spo2, float *hr);
int calculate_spo2(uint8_t *ir_data, uint8_t *red_data);
int calculate_hr(uint8_t *ir_data);
int log_data(float spo2, float hr);
void signal_handler(int signal);
void cleanup();

// Helper function to write a register
int write_register(int handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Helper function to read a register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    if (i2cWriteDevice(handle, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, value, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

int main() {
    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    if (init_i2c() != 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    if (verify_sensor() != 0) {
        fprintf(stderr, "Sensor not found. Exiting.\n");
        cleanup();
        return 1;
    }

    if (init_max30102() != 0) {
        fprintf(stderr, "Failed to initialize MAX30102. Exiting.\n");
        cleanup();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t fifo_data[FIFO_DATA_LENGTH];
    float spo2, hr;

    while (!terminate) {
        if (read_fifo_data(fifo_data) == 0) {
            if (process_fifo_data(fifo_data, &spo2, &hr) == 0) {
                if (log_data(spo2, hr) != 0) {
                    fprintf(stderr, "Failed to log data.\n");
                }
            } else {
                fprintf(stderr, "Failed to process FIFO data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read FIFO data.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Delay for 1 second
    }

    cleanup();
    return 0;
}

int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

int verify_sensor() {
    uint8_t part_id;
    if (read_register(i2c_handle, PART_ID_REG, &part_id) != 0) {
        return -1;
    }
    if (part_id != PART_ID_VALUE) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X (expected 0x%02X)\n", part_id, PART_ID_VALUE);
        return -1;
    }
    return 0;
}

int init_max30102() {
    // Reset the sensor
    if (write_register(i2c_handle, MODE_CONFIG_REG, 0x40) != 0) {
        return -1;
    }
    gpioDelay(100000); // Wait for reset to complete

    // Clear interrupts
    if (write_register(i2c_handle, 0x04, 0x00) != 0) {
        return -1;
    }

    // Configure SpO2 mode
    if (write_register(i2c_handle, MODE_CONFIG_REG, 0x03) != 0) {
        return -1;
    }

    // Configure SPO2_CONFIG
    if (write_register(i2c_handle, SPO2_CONFIG_REG, 0x27) != 0) {
        return -1;
    }

    // Configure LED pulse amplitudes
    if (write_register(i2c_handle, LED1_PA_REG, 0x24) != 0) {
        return -1;
    }
    if (write_register(i2c_handle, LED2_PA_REG, 0x24) != 0) {
        return -1;
    }

    return 0;
}

int read_fifo_data(uint8_t *data) {
    if (i2cReadDevice(i2c_handle, data, FIFO_DATA_LENGTH) != FIFO_DATA_LENGTH) {
        fprintf(stderr, "Failed to read FIFO data\n");
        return -1;
    }
    return 0;
}

int process_fifo_data(uint8_t *data, float *spo2, float *hr) {
    uint8_t ir_data[3];
    uint8_t red_data[3];

    // Extract IR and Red data from FIFO
    memcpy(ir_data, data, 3);
    memcpy(red_data, data + 3, 3);

    // Calculate SpO2
    *spo2 = calculate_spo2(ir_data, red_data);

    // Calculate Heart Rate
    *hr = calculate_hr(ir_data);

    return 0;
}

int calculate_spo2(uint8_t *ir_data, uint8_t *red_data) {
    // Implement ratio-of-ratios algorithm here
    // This is a placeholder; replace with actual implementation
    // For demonstration purposes, return a dummy value
    return 98.0; // Example SpO2 value
}

int calculate_hr(uint8_t *ir_data) {
    // Implement peak detection algorithm here
    // This is a placeholder; replace with actual implementation
    // For demonstration purposes, return a dummy value
    return 70.0; // Example Heart Rate value
}

int log_data(float spo2, float hr) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fp = fopen("health_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    fprintf(fp, "%s, SpO2: %.2f%%, HR: %.2f BPM\n", timestamp, spo2, hr);
    fclose(fp);

    return 0;
}

void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

