// Define constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define BUZZER_GPIO 24
#define GAS_THRESHOLD 500

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
void control_buzzer(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Cleaning up and exiting.\n");
        terminate = 1;
    }
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    // Validate ADC value
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value %d\n", adc_value);
        return -1;
    }

    return adc_value;
}

// Function to control the buzzer
void control_buzzer(int state) {
    if (gpioWrite(BUZZER_GPIO, state) != 0) {
        fprintf(stderr, "Error: Failed to write to GPIO %d\n", BUZZER_GPIO);
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure SPI communication
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // SPI0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Configure buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Set initial buzzer state to OFF
    control_buzzer(0);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Gas sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read gas sensor value
        int gas_value = read_mcp3008(0);
        if (gas_value < 0) {
            fprintf(stderr, "Error: Failed to read gas sensor value\n");
        } else {
            printf("Gas sensor value: %d\n", gas_value);

            // Control buzzer based on gas threshold
            if (gas_value < GAS_THRESHOLD) {
                control_buzzer(0); // Turn buzzer OFF
            } else {
                control_buzzer(1); // Turn buzzer ON
            }
        }

        // Wait 500 ms
        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    // Cleanup and exit
    spiClose(spi_handle);
    control_buzzer(0); // Ensure buzzer is OFF before exiting
    gpioTerminate();

    return 0;
}

