#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <poll.h>
#include <stdbool.h>

// Configuration
#define I2C_DEVICE "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_REG_STATUS 0x00
#define ADS1115_REG_LOW_THRESH 0x02
#define ADS1115_REG_HIGH_THRESH 0x03

#define RELAY_GPIO 17
#define REED_SENSOR_GPIO 27

#define NUM_BASELINE_SAMPLES 10
#define BASELINE_SAMPLE_DELAY_MS 50

#define POLL_INTERVAL_MS 200

#define LOG_FILE "/var/log/door_events.log"

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *relay_line = NULL;
static struct gpiod_line *reed_sensor_line = NULL;
static float distance_threshold = 0.0;
static bool running = true;

// Function prototypes
int i2c_read_adc(int fd, uint8_t reg);
int i2c_write_adc(int fd, uint8_t reg, uint16_t value);
float read_distance(int fd);
void control_relay(struct gpiod_line *line, int value);
int read_reed_sensor(struct gpiod_line *line);
void log_event(const char *event_type);
void signal_handler(int sig);
int setup_gpio(struct gpiod_chip *chip, int relay_gpio, int reed_sensor_gpio);
int cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *relay_line, struct gpiod_line *reed_sensor_line);

// I2C read function
int i2c_read_adc(int fd, uint8_t reg) {
    uint8_t buf[2];
    int ret;

    buf[0] = reg;
    ret = write(fd, buf, 1);
    if (ret != 1) {
        perror("I2C write (reg select)");
        return -1;
    }

    ret = read(fd, buf, 2);
    if (ret != 2) {
        perror("I2C read");
        return -1;
    }

    return (buf[0] << 8) | buf[1];
}

// I2C write function
int i2c_write_adc(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    int ret;

    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;

    ret = write(fd, buf, 3);
    if (ret != 3) {
        perror("I2C write (config)");
        return -1;
    }

    return 0;
}

// Read distance from ADS1115
float read_distance(int fd) {
    int16_t adc_value;
    float voltage, distance;

    adc_value = i2c_read_adc(fd, ADS1115_REG_CONVERT);
    if (adc_value < 0) {
        fprintf(stderr, "Error reading ADC value\n");
        return -1.0;
    }

    // Convert ADC value to voltage (assuming +/- 4.096V range)
    voltage = (float)adc_value * 4.096 / 32768.0;

    // Convert voltage to distance (using GP2Y0A21YK0F formula)
    // distance = 27.0 / (voltage + 0.25); // Simplified formula for demonstration
    distance = 27.0 / (voltage + 0.25); // More accurate formula

    return distance;
}

// Control the relay
void control_relay(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("gpiod_line_set_value");
    }
}

// Read the reed sensor
int read_reed_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("gpiod_line_get_value");
        return -1;
    }
    return value;
}

// Log an event
void log_event(const char *event_type) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event_type);
    fclose(fp);
}

// Signal handler
void signal_handler(int sig) {
    printf("Caught signal %d, exiting...\n", sig);
    running = false;
}

// Setup GPIO lines
int setup_gpio(struct gpiod_chip *chip, int relay_gpio, int reed_sensor_gpio) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "door_control";

    relay_line = gpiod_chip_get_line(chip, relay_gpio);
    if (!relay_line) {
        perror("gpiod_chip_get_line (relay)");
        return -1;
    }

    reed_sensor_line = gpiod_chip_get_line(chip, reed_sensor_gpio);
    if (!reed_sensor_line) {
        perror("gpiod_chip_get_line (reed sensor)");
        return -1;
    }

    if (gpiod_line_request(relay_line, &config, 0) < 0) {
        perror("gpiod_line_request (relay)");
        return -1;
    }

    if (gpiod_line_request(reed_sensor_line, &config, 0) < 0) {
        perror("gpiod_line_request (reed sensor)");
        return -1;
    }

    return 0;
}

// Cleanup GPIO lines
int cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *relay_line, struct gpiod_line *reed_sensor_line) {
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (reed_sensor_line) {
        gpiod_line_release(reed_sensor_line);
    }
    return 0;
}

int main(int argc, char *argv[]) {
    int i;
    float baseline_sum = 0.0;
    float baseline_samples[NUM_BASELINE_SAMPLES];
    int i2c_retry_count = 0;
    const int max_i2c_retries = 3;

    // Parse command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <distance_threshold_percentage>\n", argv[0]);
        return 1;
    }

    distance_threshold = atof(argv[1]);
    if (distance_threshold <= 0.0 || distance_threshold >= 100.0) {
        fprintf(stderr, "Invalid distance threshold. Must be between 0 and 100.\n");
        return 1;
    }

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

