    for (i = 0; i < NUM_BASELINE_SAMPLES; i++) {
        baseline_avg += baseline_samples[i];
    }
    baseline_avg /= NUM_BASELINE_SAMPLES;

    printf("Baseline average distance: %.2f\n", baseline_avg);
    distance_threshold = baseline_avg * (distance_threshold / 100.0);
    printf("Distance threshold: %.2f\n", distance_threshold);

