    while (running) {
        float distance = read_distance(i2c_fd);
        if (distance < 0) {
            fprintf(stderr, "Error reading distance\n");
            usleep(POLL_INTERVAL_MS * 1000); // Delay in microseconds
            continue;
        }

        printf("Distance: %.2f\n", distance);

        if (distance < distance_threshold) {
            printf("Distance below threshold, activating relay...\n");
            control_relay(relay_line, 1); // Energize relay
            usleep(3000000); // 3 seconds
            control_relay(relay_line, 0); // De-energize relay

            // Read reed sensor
            int reed_state = read_reed_sensor(reed_sensor_line);
            if (reed_state < 0) {
                fprintf(stderr, "Error reading reed sensor\n");
