    printf("Cleaning up...\n");
    control_relay(relay_line, 0); // Ensure relay is off
    cleanup_gpio(gpio_chip, relay_line, reed_sensor_line);
    close(i2c_fd);
    gpiod_chip_close(gpio_chip);

