#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Define GPIO pins for chip select lines
#define CS0_PIN 8
#define CS1_PIN 7
#define CS2_PIN 25

// Define SPI device and mode
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0

// Define log file name
#define LOG_FILE "soil_moisture_log.csv"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int spi_init(const char *device);
int spi_read_adc(int chip_select_pin, int channel);
int log_data(FILE *fp, int sensor1_value, int sensor2_value, int sensor3_value);
void signal_handler(int signal);
int setup_gpio(int chip_select_pin);
int cleanup_gpio(int chip_select_pin);

// Structure to hold GPIO line and chip data
struct gpiod_chip {
    int chip;
};

struct gpiod_line {
    int line;
    struct gpiod_chip *chip;
};

// Function to initialize the GPIO line
int setup_gpio(int chip_select_pin) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, chip_select_pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line, "soil_moisture_sensor", 0); // Initial value LOW
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Function to cleanup the GPIO line
int cleanup_gpio(int chip_select_pin) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip for cleanup");
        return -1;
    }

    line = gpiod_chip_get_line(chip, chip_select_pin);
    if (!line) {
        perror("Error getting GPIO line for cleanup");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_release(line);
    if (ret < 0) {
        perror("Error releasing GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// Function to initialize the SPI device
int spi_init(const char *device) {
    int fd;
    unsigned int mode = SPI_MODE;
    unsigned int bits = 8;
    unsigned int speed = 1000000; // 1 MHz

    fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_BITS_PER_WORD, &bits) < 0) {
        perror("Error getting SPI bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read from the MCP3008 ADC
int spi_read_adc(int chip_select_pin, int channel) {
    int fd, ret;
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct gpiod_line *cs_line;

    // Construct the SPI message to send to the MCP3008
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    // Request the chip select line
    cs_line = gpiod_chip_get_line(gpiod_chip_open_by_name("gpiochip0"), chip_select_pin);
    if (!cs_line) {
        perror("Error getting chip select line");
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("Error setting chip select line low");
        gpiod_line_release(cs_line);
        return -1;
    }

    // Perform the SPI transaction
    fd = spi_init(SPI_DEVICE);
    if (fd < 0) {
        fprintf(stderr, "SPI initialization failed, retrying...\n");
        sleep(1); // Wait before retrying
        continue;
    }

    ret = ioctl(fd, SPI_IOC_MESSAGE(1), tx_buf);
    if (ret < 0) {
        perror("Error during SPI transaction");
        close(fd);
        gpiod_line_release(cs_line);
        return -1;
    }

    close(fd);

    // Release the chip select line
    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("Error setting chip select line high");
        gpiod_line_release(cs_line);
        return -1;
    }

    gpiod_line_release(cs_line);

    // Extract the ADC value from the received data
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

    return adc_value;
}

// Function to log the data to a CSV file
int log_data(FILE *fp, int sensor1_value, int sensor2_value, int sensor3_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1_value, sensor2_value, sensor3_value) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    FILE *fp;
    int sensor1_value, sensor2_value, sensor3_value;
    int cs0_fd, cs1_fd, cs2_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *cs0_line, *cs1_line, *cs2_line;
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO lines for chip select
    if (setup_gpio(CS0_PIN) < 0 || setup_gpio(CS1_PIN) < 0 || setup_gpio(CS2_PIN) < 0) {
        fprintf(stderr, "GPIO initialization failed, exiting...\n");
        return 1;
    }

    cs0_line = gpiod_chip_get_line(gpiod_chip_open_by_name("gpiochip0"), CS0_PIN);
    cs1_line = gpiod_chip_get_line(gpiod_chip_open_by_name("gpiochip0"), CS1_PIN);
    cs2_line = gpiod_chip_get_line(gpiod_chip_open_by_name("gpiochip0"), CS2_PIN);

    if (!cs0_line || !cs1_line || !cs2_line) {
        perror("Error getting chip select lines");
        cleanup_gpio(CS0_PIN);
        cleanup_gpio(CS1_PIN);
        cleanup_gpio(CS2_PIN);
        return 1;
    }

    // Open the log file
    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        cleanup_gpio(CS0_PIN);
        cleanup_gpio(CS1_PIN);
        cleanup_gpio(CS2_PIN);
        return 1;
    }

    // Check if the file is newly created and write the header if needed
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,sensor1,sensor2,sensor3\n");
    }
    fseek(fp, 0, SEEK_END);

    // Main loop
    while (program_running) {
        // Read sensor values
        sensor1_value = spi_read_adc(CS0_PIN, 0);
        sensor2_value = spi_read_adc(CS1_PIN, 0);
        sensor3_value = spi_read_adc(CS2_PIN, 0);

        // Log the data
        if (sensor1_value == -1 || sensor2_value == -1 || sensor3_value == -1) {
            fprintf(stderr, "Error reading sensor data, logging -1\n");
            log_data(fp, -1, -1, -1);
        } else {
            if (log_data(fp, sensor1_value, sensor2_value, sensor3_value) < 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup resources
    fclose(fp);
    cleanup_gpio(CS0_PIN);
    cleanup_gpio(CS1_PIN);
    cleanup_gpio(CS2_PIN);

    return 0;
}

