        close(fd);
        return -1;
    }

    return fd;
}

// Function to read from the MCP3008 ADC
int spi_read_adc(int chip_select_pin, int channel) {
    int fd, ret;
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct gpiod_line *cs_line;

    // Construct the SPI message to send to the MCP3008
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    // Request the chip select line
    cs_line = gpiod_chip_get_line(gpiod_chip_open_by_name("gpiochip0"), chip_select_pin);
    if (!cs_line) {
        perror("Error getting chip select line");
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("Error setting chip select line low");
        gpiod_line_release(cs_line);
        return -1;
    }

    // Perform the SPI transaction
    fd = spi_init(SPI_DEVICE);
    if (fd < 0) {
        fprintf(stderr, "SPI initialization failed, retrying...\n");
        sleep(1); // Wait before retrying
        continue;
    }

    ret = ioctl(fd, SPI_IOC_MESSAGE(1), tx_buf);
    if (ret < 0) {
        perror("Error during SPI transaction");
        close(fd);
        gpiod_line_release(cs_line);
        return -1;
    }

    close(fd);

    // Release the chip select line
    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("Error setting chip select line high");
        gpiod_line_release(cs_line);
        return -1;
    }

    gpiod_line_release(cs_line);

    // Extract the ADC value from the received data
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

    return adc_value;
}

// Function to log the data to a CSV file
int log_data(FILE *fp, int sensor1_value, int sensor2_value, int sensor3_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1_value, sensor2_value, sensor3_value) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    FILE *fp;
    int sensor1_value, sensor2_value, sensor3_value;
    int cs0_fd, cs1_fd, cs2_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *cs0_line, *cs1_line, *cs2_line;
    int ret;

