#include <getopt.h>

// Constants
#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_CE 8
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define VH400_DRY_ADC 200
#define VH400_WET_ADC 800
#define DEFAULT_THRESHOLD 30
#define DEFAULT_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60

// Global variables
int spi_handle;
int threshold = DEFAULT_THRESHOLD;
int duration = DEFAULT_DURATION;
int sleep_interval = DEFAULT_SLEEP_INTERVAL;
FILE *log_file;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
void control_pump(int state);
void log_data(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    int count = 0;
    while (count < 3) {
        char tx_buf[3];
        char rx_buf[3];

        tx_buf[0] = 0x01; // Start bit
        tx_buf[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
        tx_buf[2] = 0x00;

        if (spiXfer(spi_handle, tx_buf, rx_buf, 3) == 3) {
            int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI read failed, retrying...\n");
            log_data("SPI read failed, retrying...");
            gpioDelay(1000); // Wait 1 ms before retry
            count++;
        }
    }
    fprintf(stderr, "SPI read failed after 3 retries.\n");
    log_data("SPI read failed after 3 retries.");
    return -1; // Indicate error
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    float percentage = 100.0 * (adc_value - VH400_DRY_ADC) / (VH400_WET_ADC - VH400_DRY_ADC);
    if (percentage < 0.0) {
        percentage = 0.0;
    } else if (percentage > 100.0) {
        percentage = 100.0;
    }
    return percentage;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    char message[50];
    sprintf(message, "Pump %s", state ? "ON" : "OFF");
    log_data(message);
}

// Function to log data to file
void log_data(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_data("Received signal, shutting down...");
    cleanup();
    exit(0);
}

// Cleanup function to turn off pump and close SPI
void cleanup() {
    control_pump(0); // Turn off pump
    spiClose(spi_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            case 's':
                sleep_interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s sleep_interval]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        log_data("SPI open failed");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("irrigation.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_data("Irrigation system started");

    // Main loop
    while (1) {
        // Read soil moisture
        int adc_value = read_mcp3008(0);
        if (adc_value == -1) {
            fprintf(stderr, "Failed to read ADC value, skipping irrigation cycle.\n");
            log_data("Failed to read ADC value, skipping irrigation cycle.");
            gpioDelay(sleep_interval * 1000); // Wait before next attempt
            continue;
        }

        // Calculate moisture percentage
        float moisture_percentage = calculate_moisture_percentage(adc_value);
        char message[50];
        sprintf(message, "Moisture: %.2f%%", moisture_percentage);
        log_data(message);

        // Check if irrigation is needed
        if (moisture_percentage < threshold) {
            log_data("Moisture below threshold, activating pump");
            control_pump(1); // Turn on pump
            gpioDelay(duration * 1000); // Run pump for specified duration
            control_pump(0); // Turn off pump
            log_data("Pump deactivated");
        }

        // Wait before next reading
        gpioDelay(sleep_interval * 1000);
    }

    return 0;
}

