#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL_MS 10
#define EMA_ALPHA 0.1
#define PEAK_THRESHOLD_PERCENT 20.0
#define LOG_FILE "/var/log/sound_events.log"
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345

// Global variables
int spi_handle;
double ema = 0.0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_read_adc(int channel);
double calculate_ema(double current_value, double ema);
int detect_peak(int raw_value, double ema);
void log_peak(int raw_value);
void send_data_to_server(int raw_value);
void signal_handler(int signal);

// SPI read ADC function
int spi_read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // MCP3008 command: start bit (1), single-ended mode (1), channel (3 bits), don't care (3 bits)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract the 10-bit ADC value from the response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// EMA calculation function
double calculate_ema(double current_value, double ema) {
    return ema * EMA_ALPHA + current_value * (1 - EMA_ALPHA);
}

// Peak detection function
int detect_peak(int raw_value, double ema) {
    double threshold = ema * (1 + PEAK_THRESHOLD_PERCENT / 100.0);
    if (raw_value > threshold) {
        return 1;
    }
    return 0;
}

// Logging function
void log_peak(int raw_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm);

    fprintf(fp, "%s: Peak detected: %d\n", timestamp, raw_value);
    fclose(fp);
}

// Data transmission function
void send_data_to_server(int raw_value) {
    int sockfd;
    struct sockaddr_in servaddr;

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        fprintf(stderr, "Error: Socket creation failed\n");
        return;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &servaddr.sin_addr) <= 0) {
        fprintf(stderr, "Error: Invalid address/ Address not supported\n");
        close(sockfd);
        return;
    }

    char buffer[64];
    snprintf(buffer, sizeof(buffer), "%d", raw_value);

    if (sendto(sockfd, (const char *)buffer, strlen(buffer), 0, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        fprintf(stderr, "Error: Sendto failed\n");
    }

    close(sockfd);
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int raw_value = spi_read_adc(ADC_CHANNEL);
        if (raw_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Calculate EMA
        ema = calculate_ema(raw_value, ema);

        // Detect peak
        if (detect_peak(raw_value, ema)) {
            log_peak(raw_value);
            send_data_to_server(raw_value);
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Convert ms to us
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

