#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define PCF8591_ADDR 0x48
#define CONTROL_BYTE 0x40 // Single-ended AIN0, analog output disabled

int i2c_fd;

void cleanup(int signal) {
    printf("\nCleaning up and exiting...\n");
    close(i2c_fd);
    exit(0);
}

int main() {
    int i2c_address = PCF8591_ADDR;
    int control_byte = CONTROL_BYTE;
    int dummy_read;
    int sample;

    // Register signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    printf("PCF8591 AIN0 monitor started. Press Ctrl+C to exit.\n");

    while (1) {
        // Dummy read to clear previous value
        dummy_read = i2c_smbus_read_byte_data(i2c_fd, 0);
        if (dummy_read < 0) {
            perror("Error during dummy read");
            close(i2c_fd);
            return 1;
        }

        // Write control byte
        if (i2c_smbus_write_byte_data(i2c_fd, 0, control_byte) < 0) {
            perror("Error writing control byte");
            close(i2c_fd);
            return 1;
        }

        // Read sample
        sample = i2c_smbus_read_byte_data(i2c_fd, 0);
        if (sample < 0) {
            perror("Error reading sample");
            close(i2c_fd);
            return 1;
        }

        // Print sample value
        printf("AIN0: %d\n", sample);

        // Delay
        usleep(100000); // 100 ms
    }

    return 0;
}

