#include <string.h>

// Constants
#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MOISTURE_THRESHOLD 300
#define PUMP_DURATION 10 // seconds
#define LOG_FILE "watering_events.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
void control_pump(int state);
void log_event(int moisture_level);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1; // Indicate error
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    // Validate ADC value
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value %d\n", adc_value);
        return -1; // Indicate error
    }

    return adc_value;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state); // HIGH to activate, LOW to deactivate
}

// Function to log events to file
void log_event(int moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Moisture level: %d\n", timestamp, moisture_level);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for pump control
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stdout, "Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read soil moisture
        int moisture_level = read_mcp3008(0);
        if (moisture_level == -1) {
            fprintf(stderr, "Error: Failed to read moisture level\n");
            // Attempt to recover by re-initializing SPI
            spiClose(spi_handle);
            spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
            if (spi_handle < 0) {
                fprintf(stderr, "Error: SPI re-initialisation failed\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
            gpioDelay(1000); // Wait before retrying
            continue; // Skip to the next iteration
        }

        // Check if watering is needed
        if (moisture_level < MOISTURE_THRESHOLD) {
            // Activate pump
            control_pump(1);

            // Log event
            log_event(moisture_level);

            // Wait for pump duration
            gpioDelay(PUMP_DURATION * 1000); // Convert seconds to milliseconds

            // Deactivate pump
            control_pump(0);
        }

        // Wait before next reading
        gpioDelay(60000); // 60 seconds
    }

    // Cleanup
    fprintf(stdout, "Shutting down...\n");
    control_pump(0); // Ensure pump is off
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

