// Define constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define RAIN_SENSOR_CHANNEL 0
#define VDD 3.3
#define ADC_RESOLUTION 1024.0
#define RAINFALL_INTENSITY_MAX 10.0

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float map_adc_to_intensity(int adc_value);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        terminate = 1;
    }
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to map ADC value to rainfall intensity
float map_adc_to_intensity(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: ADC value out of range (%d)\n", adc_value);
        return -1.0; // Indicate error
    }

    // Map 10-bit ADC value (0-1023) to rainfall intensity (0-10)
    return (float)adc_value / ADC_RESOLUTION * RAINFALL_INTENSITY_MAX;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(RAIN_SENSOR_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Map ADC value to rainfall intensity
        float intensity = map_adc_to_intensity(adc_value);
        if (intensity < 0) {
            fprintf(stderr, "Error: Failed to map ADC value to intensity\n");
            continue; // Skip to the next iteration
        }

        // Get current timestamp
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char buf[80];
        strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

        // Log data to stdout
        printf("%s, ADC Value: %d, Rainfall Intensity: %.2f\n", buf, adc_value, intensity);

        // Wait for 1 second
        sleep(1);
    }

    // Close SPI and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

