#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <string.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_REG_STATUS 0x00
#define ADS1115_REG_WHO_AM_I 0x01
#define ADS1115_WHO_AM_I 0x48
#define ADS1115_PGA 4.096 // +/- 4.096V
#define ADS1115_FULL_SCALE_VOLTAGE 4.096
#define ADS1115_RESOLUTION 4096.0 // 12-bit ADC
#define ADS1115_DEFAULT_THRESHOLD 100.0
#define LED_GPIO 17
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
double threshold = ADS1115_DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_ads1115();
int read_ads1115(int *raw_value);
double adc_to_voltage(int raw_value);
double voltage_to_gauss(double voltage);
void control_led(int on);
void signal_handler(int signal);
void cleanup();

// Structure for ADS1115 configuration
typedef struct {
    uint8_t config[3];
} ads1115_config_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize ADS1115
int init_ads1115() {
    // Verify device ID
    uint8_t who_am_i;
    if (i2cReadI2CBlockData(i2c_handle, ADS1115_REG_WHO_AM_I, (char*)&who_am_i, 1) != 1) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != ADS1115_WHO_AM_I) {
        fprintf(stderr, "ADS1115 not found. WHO_AM_I = 0x%02X\n", who_am_i);
        return -1;
    }

    // Configure ADS1115 for single-ended AIN0, PGA=4.096V, 128 SPS
    ads1115_config_t config;
    config.config[0] = 0x01; // Configuration register
    config.config[1] = 0xC3; // MSB: Start single conversion, AIN0, PGA=4.096V, 128 SPS
    config.config[2] = 0x83; // LSB: Single-shot mode, Disable comparator, Disable comparator in single-conversion mode

    if (i2cWriteI2CBlockData(i2c_handle, ADS1115_REG_CONFIG, (char*)&config.config[1], 2) != 2) {
        fprintf(stderr, "Error writing to configuration register\n");
        return -1;
    }

    return 0;
}

// Function to read from ADS1115
int read_ads1115(int *raw_value) {
    uint8_t data[2];
    if (i2cReadI2CBlockData(i2c_handle, ADS1115_REG_CONVERT, (char*)data, 2) != 2) {
        fprintf(stderr, "Error reading conversion register\n");
        return -1;
    }

    *raw_value = (data[0] << 8) | data[1];
    return 0;
}

// Function to convert ADC value to voltage
double adc_to_voltage(int raw_value) {
    return ((double)raw_value / ADS1115_RESOLUTION) * ADS1115_FULL_SCALE_VOLTAGE;
}

// Function to convert voltage to Gauss
double voltage_to_gauss(double voltage) {
    return voltage / 0.001; // 1.0 mV/Gauss = 0.001 V/Gauss
}

// Function to control the LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    control_led(0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize ADS1115
    if (init_ads1115() != 0) {
        cleanup();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int raw_value;
    double voltage, gauss;

    // Main loop
    while (!terminate) {
        if (read_ads1115(&raw_value) == 0) {
            voltage = adc_to_voltage(raw_value);
            gauss = voltage_to_gauss(voltage);

            printf("Magnetic Field: %.2f Gauss\n", gauss);

            if (gauss > threshold) {
                printf("Threshold exceeded! Blinking LED...\n");
                control_led(1); // Turn on LED
                gpioDelay(50000); // 50 ms
                control_led(0); // Turn off LED
                gpioDelay(50000); // 50 ms
                control_led(1); // Turn on LED
                gpioDelay(50000); // 50 ms
                control_led(0); // Turn off LED
                terminate = 1; // Exit blinking loop
            }
        } else {
            fprintf(stderr, "Error reading ADC value\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

