#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <stdarg.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define RELAY_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define MQTT_TOPIC "soil_moisture"
#define MQTT_PUMP_CONTROL_TOPIC "pump_control"
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "soil_moisture_monitor"
#define MQTT_KEEPALIVE 60
#define SENSOR_READ_INTERVAL 60 // seconds

// Global variables
int spi_handle;
struct mosquitto *mosq = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void control_relay(int state);
void publish_moisture(float moisture);
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result);
void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc);
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void signal_handler(int sig);
void log_message(int priority, const char *format, ...);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_message(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        log_message(LOG_ERR, "SPI transfer failed");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        log_message(LOG_ERR, "Invalid ADC value: %d", adc_value);
        return -1.0;
    }

    // Assuming HL-69 output is inversely proportional to moisture
    // Calibration needed for specific sensor and soil type
    float moisture = 100.0 - ((float)adc_value / 1023.0) * 100.0;
    return moisture;
}

// Function to control the relay
void control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        log_message(LOG_ERR, "Failed to write to GPIO %d", RELAY_GPIO);
    }
}

// Function to publish moisture reading to MQTT
void publish_moisture(float moisture) {
    char payload[50];
    snprintf(payload, sizeof(payload), "Moisture: %.2f%%", moisture);

    int rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_message(LOG_ERR, "Failed to publish message: %s", mosquitto_strerror(rc));
    }
}

// MQTT connect callback
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (!result) {
        log_message(LOG_INFO, "Connected to MQTT broker");
        mosquitto_subscribe(mosq, NULL, MQTT_PUMP_CONTROL_TOPIC, 0);
    } else {
        log_message(LOG_ERR, "MQTT connection failed: %s", mosquitto_strerror(result));
    }
}

// MQTT disconnect callback
void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    log_message(LOG_INFO, "Disconnected from MQTT broker");
}

// MQTT message callback
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        if (strcmp(payload, "pump_on") == 0) {
            control_relay(1); // Turn pump on
        } else if (strcmp(payload, "pump_off") == 0) {
            control_relay(0); // Turn pump off
        } else {
            log_message(LOG_WARNING, "Received unknown MQTT message: %s", (char *)message->payload);
        }
    }
}

// Signal handler
void signal_handler(int sig) {
    log_message(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Logging function
void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);
    vsyslog(priority, format, args);
    va_end(args);
}

int main() {
    // Initialize syslog
    openlog("soil_moisture_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    control_relay(0); // Ensure relay is off initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        log_message(LOG_ERR, "SPI open failed");
        gpioTerminate();
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_message(LOG_ERR, "Failed to create mosquitto instance");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, mqtt_connect_callback);
    mosquitto_disconnect_callback_set(mosq, mqtt_disconnect_callback);
    mosquitto_message_callback_set(mosq, mqtt_message_callback);

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_message(LOG_ERR, "MQTT connection error: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            log_message(LOG_ERR, "Failed to read ADC value");
