#include <linux/spi/spidev.h>
#include <stdint.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3

volatile sig_atomic_t keep_running = 1;

void int_handler(int dummy) {
    keep_running = 0;
}

int spi_init(int *fd) {
    *fd = open(SPI_DEVICE, O_RDWR);
    if (*fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(*fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(*fd);
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(*fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting SPI bits per word");
        close(*fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(*fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(*fd);
        return -1;
    }

    return 0;
}

int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }
    return 0;
}

int main() {
    int fd;
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    int raw_value;
    float voltage;

    signal(SIGINT, int_handler);

    if (spi_init(&fd) < 0) {
        return EXIT_FAILURE;
    }

    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x80; // Single-ended, channel 0
    tx_buf[2] = 0x00; // Dummy byte

    while (keep_running) {
        if (spi_transfer(fd, tx_buf, rx_buf, 3) < 0) {
            fprintf(stderr, "SPI transfer failed. Exiting.\n");
            break;
        }

        raw_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
        voltage = (float)raw_value * VREF / 1024.0;

        printf("Raw Value: %d, Voltage: %.3f V\n", raw_value, voltage);
        usleep(500000); // 500 ms
    }

    close(fd);
    return EXIT_SUCCESS;
}

