#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define SOUND_LEVEL_FILE "tamper_log.csv"
#define ERROR_LOG_FILE "error_log.txt"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x11
#define MAX_SOUND_LEVEL 100.0 // dB
#define MAX_LIGHT_LEVEL 1000.0 // lux

// Global variables
int spi_fd = -1;
int i2c_fd = -1;
FILE *log_file = NULL;
FILE *error_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_adc_to_db(int adc_value);
float read_bh1750();
void log_data(float sound_level, float light_level, int error_code);
void log_error(const char *message);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));
    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        log_error("SPI transaction failed");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to dB
float convert_adc_to_db(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        log_error("Invalid ADC value");
        return -1.0;
    }
    return (float)adc_value / 1023.0 * MAX_SOUND_LEVEL;
}

// Function to read light level from BH1750
float read_bh1750() {
    unsigned char buf[2];
    int result;

    // Send measurement command
    buf[0] = BH1750_CONTINUOUS_HIGH_RES_MODE;
    if (write(i2c_fd, buf, 1) != 1) {
        log_error("Failed to write to BH1750");
        return -1.0;
    }

    // Wait for measurement (at least 180ms)
    usleep(200000); // 200ms

    // Read 2 bytes of data
    if (read(i2c_fd, buf, 2) != 2) {
        log_error("Failed to read from BH1750");
        return -1.0;
    }

    // Convert to lux
    unsigned int raw_value = (buf[0] << 8) | buf[1];
    return (float)raw_value / 1.2;
}

// Function to log data to CSV file
void log_data(float sound_level, float light_level, int error_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, sound_level, light_level, error_code);
    fflush(log_file);
}

// Function to log errors to error log file
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(error_file, "%s: %s (errno: %d)\n", timestamp, message, errno);
    fflush(error_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Configure SPI mode
    unsigned char mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Configure SPI bits per word
    unsigned char bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Configure SPI speed
    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, 0x23) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(SOUND_LEVEL_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Open error log file
    error_file = fopen(ERROR_LOG_FILE, "a");
    if (error_file == NULL) {
        fprintf(stderr, "Failed to open error log file: %s\n", strerror(errno));
        fclose(log_file);
        close(i2c_fd);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            float sound_level = convert_adc_to_db(adc_value);
            float light_level = read_bh1750();

            if (sound_level >= 0 && light_level >= 0) {
                log_data(sound_level, light_level, 0);
            } else {
                log_data(-1.0, -1.0, 1); // Log error
            }
        } else {
            log_data(-1.0, -1.0, 2); // Log ADC read error
        }

        sleep(5);
    }

    // Cleanup
    close(spi_fd);
    close(i2c_fd);
    fclose(log_file);
    fclose(error_file);
    gpioTerminate();

    return 0;
}

