        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, 0x23) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(SOUND_LEVEL_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Open error log file
    error_file = fopen(ERROR_LOG_FILE, "a");
    if (error_file == NULL) {
        fprintf(stderr, "Failed to open error log file: %s\n", strerror(errno));
        fclose(log_file);
        close(i2c_fd);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            float sound_level = convert_adc_to_db(adc_value);
            float light_level = read_bh1750();

            if (sound_level >= 0 && light_level >= 0) {
                log_data(sound_level, light_level, 0);
            } else {
                log_data(-1.0, -1.0, 1); // Log error
            }
        } else {
            log_data(-1.0, -1.0, 2); // Log ADC read error
        }

        sleep(5);
    }

    // Cleanup
    close(spi_fd);
    close(i2c_fd);
    fclose(log_file);
    fclose(error_file);
    gpioTerminate();

    return 0;
}

