            // Attempt to recover by re-initializing SPI
            spiClose(spi_handle);
            spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
            if (spi_handle < 0) {
                fprintf(stderr, "Error: SPI re-initialization failed: %d\n", spi_handle);
                terminate = 1; // Exit if re-initialization fails
                continue; // Skip to next iteration
            }
            continue; // Skip to next iteration
