#include <unistd.h>
#include <pigpio.h>

// Constants
#define VALVE_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PWM_FREQUENCY 100 // 100 Hz
#define PWM_RANGE 100
#define NUM_SENSORS 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float average_adc_values(int *adc_values, int num_sensors);
int map_adc_to_valve_position(float average_adc);
void set_valve_position(int valve_position);
void log_data(int adc_values[NUM_SENSORS], float average_adc, int valve_position);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate error
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 single-ended read)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate the average of an array of ADC values
float average_adc_values(int *adc_values, int num_sensors) {
    float sum = 0.0;
    int valid_count = 0;
    for (int i = 0; i < num_sensors; i++) {
        if (adc_values[i] != -1) { // Check for error value
            sum += adc_values[i];
            valid_count++;
        }
    }
    if (valid_count > 0) {
        return sum / valid_count;
    } else {
        return -1.0; // Indicate no valid readings
    }
}

// Function to map the average ADC value to a valve position (0-100%)
int map_adc_to_valve_position(float average_adc) {
    if (average_adc < 0) {
        return 0; // Handle invalid ADC value
    }
    if (average_adc > 1023) {
        return 100; // Handle invalid ADC value
    }
    return 100 - (int)((average_adc / 1023.0) * 100.0); // Invert mapping
}

// Function to set the valve position using PWM
void set_valve_position(int valve_position) {
    if (valve_position < 0) valve_position = 0;
    if (valve_position > 100) valve_position = 100;
    gpioPWM(VALVE_GPIO, valve_position);
}

// Function to log data to a file
void log_data(int adc_values[NUM_SENSORS], float average_adc, int valve_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %d, %d, %.2f, %d\n", timestamp, adc_values[0], adc_values[1], adc_values[2], average_adc, valve_position);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output for PWM
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_GPIO, PWM_RANGE);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("irrigation.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int adc_values[NUM_SENSORS];
    float average_adc;
    int valve_position;

    // Main loop
    while (!terminate) {
        // Read ADC values from sensors
        adc_values[0] = read_mcp3008(0);
        adc_values[1] = read_mcp3008(1);
        adc_values[2] = read_mcp3008(2);

        // Check for errors during ADC readings
        if (adc_values[0] == -1 || adc_values[1] == -1 || adc_values[2] == -1) {
            fprintf(stderr, "Error: Failed to read ADC values, skipping iteration\n");
            sleep(5);
            continue;
        }

        // Calculate average ADC value
        average_adc = average_adc_values(adc_values, NUM_SENSORS);

        // Map ADC value to valve position
        if (average_adc != -1.0) {
            valve_position = map_adc_to_valve_position(average_adc);
        } else {
            valve_position = 0; // Default to closed position if average ADC is invalid
        }

        // Set valve position
        set_valve_position(valve_position);

        // Log data
        log_data(adc_values, average_adc, valve_position);

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup
    set_valve_position(0); // Close valve
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

