#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define LOG_FILE "soil_data.txt"
#define MAX_RETRIES 5
#define RETRY_DELAY_MS 100
#define RETRY_BACKOFF_FACTOR 2

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
void log_data(float moisture_percentage);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    int count = 0;
    int adc_value = -1; // Initialize to an invalid value

    while (count < MAX_RETRIES) {
        char tx_buffer[3];
        char rx_buffer[3];

        // Construct SPI message
        tx_buffer[0] = 0x01; // Start bit
        tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended, channel selection
        tx_buffer[2] = 0x00; // Don't care

        // Transfer SPI data
        int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

        if (result == 3) {
            // Extract ADC value
            adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI transfer failed (attempt %d): %d\n", count + 1, result);
            gpioDelay(RETRY_DELAY_MS * (RETRY_BACKOFF_FACTOR ** count)); // Exponential backoff
            count++;
        }
    }

    fprintf(stderr, "Failed to read MCP3008 after %d retries.\n", MAX_RETRIES);
    return -1; // Indicate failure
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1.0; // Indicate error
    }
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

// Function to log data to file
void log_data(float moisture_percentage) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f\n", s, moisture_percentage);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read soil moisture
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value != -1) {
            // Calculate moisture percentage
            float moisture_percentage = calculate_moisture_percentage(adc_value);
            if (moisture_percentage >= 0.0) {
                // Log data
                log_data(moisture_percentage);
                printf("Moisture: %.2f%%\n", moisture_percentage);
            } else {
                fprintf(stderr, "Error calculating moisture percentage.\n");
            }
        } else {
            fprintf(stderr, "Failed to read soil moisture.\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Close SPI and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    printf("Soil moisture monitoring stopped.\n");
    return 0;
}

