#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

// Define SPI parameters
#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_SPEED 1000000 // 1 MHz

// Define PWM parameters
#define PWM_CHANNEL 0
#define PWM_PERIOD 1000000 // 1 ms period (1 kHz)

// Define distance range and frequency mapping
#define MIN_DISTANCE 2.0  // cm
#define MAX_DISTANCE 20.0 // cm
#define MIN_FREQUENCY 220.0 // Hz
#define MAX_FREQUENCY 880.0 // Hz

// Define LDR calibration parameters
#define LDR_MIN_VALUE 0
#define LDR_MAX_VALUE 1023
#define LDR_MIN_DUTY_CYCLE 0
#define LDR_MAX_DUTY_CYCLE 1000000 // 100% duty cycle

// Global variables
static volatile int running = 1;
static float last_distance = 50.0; // Initial distance
static int last_ldr_value = 512; // Initial LDR value
static int pwm_duty_cycle = 0;

// Function prototypes
float read_distance();
int read_ldr();
float map_distance_to_frequency(float distance);
int map_ldr_to_duty_cycle(int ldr_value);
void set_pwm_frequency(int frequency);
void set_pwm_duty_cycle(int duty_cycle);
void signal_handler(int signal);
int load_config();
int save_config();

// Function to read distance from HC-SR04 sensor
float read_distance() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIG_PIN, 0);

    uint32_t start = 0, end = 0;

    // Wait for echo to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < 10000) {
        count++;
        gpioDelay(1); // Check every 1 us
    }
    if (count >= 10000) return -1.0; // Timeout

    start = gpioTick();

    // Wait for echo to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < 10000) {
        count++;
        gpioDelay(1); // Check every 1 us
    }
    if (count >= 10000) return -1.0; // Timeout

    end = gpioTick();

    uint32_t diff = end - start;
    float distance = (float)diff / 2.0 / 29.1; // Speed of sound: 29.1 us/cm

    return distance;
}

// Function to read LDR value from MCP3008 ADC
int read_ldr() {
    int fd;
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer tr;

    fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x80; // Single-ended mode, channel 0
    tx_buf[2] = 0x00; // Dummy byte

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = 8;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error sending SPI message");
        close(fd);
        return -1;
    }

    close(fd);

    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to map distance to frequency
float map_distance_to_frequency(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        return MAX_FREQUENCY;
    } else {
        return MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

// Function to map LDR value to PWM duty cycle
int map_ldr_to_duty_cycle(int ldr_value) {
    if (ldr_value < LDR_MIN_VALUE) {
        return LDR_MIN_DUTY_CYCLE;
    } else if (ldr_value > LDR_MAX_VALUE) {
        return LDR_MAX_DUTY_CYCLE;
    } else {
        return LDR_MIN_DUTY_CYCLE + (ldr_value - LDR_MIN_VALUE) * (LDR_MAX_DUTY_CYCLE - LDR_MIN_DUTY_CYCLE) / (LDR_MAX_VALUE - LDR_MIN_VALUE);
    }
}

// Function to set PWM frequency
void set_pwm_frequency(int frequency) {
    int period = PWM_PERIOD / frequency;
    gpioSetPWMfrequency(PWM_PIN, frequency);
    gpioSetPWMrange(PWM_PIN, 1000000); // Set range to match period
    gpioPWM(PWM_PIN, period); // Set duty cycle to match period
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    gpioPWM(PWM_PIN, duty_cycle);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to load configuration from file
int load_config() {
    FILE *fp = fopen("theremin_config.txt", "r");
    if (fp == NULL) {
        perror("Error opening config file, using default values.");
        return -1;
    }

    float last_distance_saved;
    int last_ldr_value_saved;
    int pwm_duty_cycle_saved;

    if (fscanf(fp, "%f %d %d", &last_distance_saved, &last_ldr_value_saved, &pwm_duty_cycle_saved) != 3) {
        fprintf(stderr, "Error reading config file, using default values.\n");
        fclose(fp);
        return -1;
    }

    last_distance = last_distance_saved;
    last_ldr_value = last_ldr_value_saved;
    pwm_duty_cycle = pwm_duty_cycle_saved;

    fclose(fp);
    return 0;
}

// Function to save configuration to file
int save_config() {
    FILE *fp = fopen("theremin_config.txt", "w");
    if (fp == NULL) {
        perror("Error opening config file for writing.");
        return -1;
    }

    fprintf(fp, "%f %d %d", last_distance, last_ldr_value, pwm_duty_cycle);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Initialize SPI
    int spi_fd;
    unsigned char mode = 0; // SPI mode 0
    unsigned char bits = 8; // 8 bits per word
    unsigned char speed = SPI_SPEED;

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        gpioTerminate();
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting SPI bits per word");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI max speed");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    close(spi_fd);

    // Load configuration
    if (load_config() != 0) {
        printf("Using default configuration.\n");
    }

    // Set PWM frequency
    set_pwm_frequency((int)map_distance_to_frequency(last_distance));

    // Set initial PWM duty cycle
    set_pwm_duty_cycle(map_ldr_to_duty_cycle(last_ldr_value));

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Theremin started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read sensor data
        float distance = read_distance();
        int ldr_value = read_ldr();

        if (distance < 0) {
            distance = last_distance; // Use last valid distance
        }
        if (ldr_value < 0) {
            ldr_value = last_ldr_value; // Use last valid LDR value
        }

        // Map sensor data to frequency and duty cycle
        float frequency = map_distance_to_frequency(distance);
        int duty_cycle = map_ldr_to_duty_cycle(ldr_value);

        // Update last sensor values
        last_distance = distance;
        last_ldr_value = ldr_value;

        // Set PWM frequency and duty cycle
        set_pwm_frequency((int)frequency);
        set_pwm_duty_cycle(duty_cycle);

        // Print sensor data (optional)
        printf("Distance: %.2f cm, LDR: %d, Frequency: %.2f Hz, Duty Cycle: %d\n", distance, ldr_value, frequency, duty_cycle);

        // Delay
        gpioDelay(50); // 50 ms delay
    }

    // Save configuration before exiting
    if (save_config() != 0) {
        fprintf(stderr, "Error saving configuration.\n");
    }

    // Stop PWM
    gpioPWM(PWM_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    printf("Theremin stopped.\n");

    return 0;
}

