#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define PPM_THRESHOLD_HIGH 50.0
#define PPM_THRESHOLD_LOW 20.0
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define LOG_FILE "alcohol_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_ppm(int adc_value);
const char *classify_reading(float ppm);
void log_data(float ppm, const char *classification);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to hold SPI configuration
typedef struct {
    int channel;
    int baud_rate;
    int mode;
} spi_config_t;

// Structure to hold sensor configuration
typedef struct {
    int channel;
    float ppm_threshold_high;
    float ppm_threshold_low;
} sensor_config_t;

// Function to initialize the system
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Function to read from MCP3008
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];
    int count, i;

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (channel << 4) | 0x80; // Single-ended mode
    tx_buffer[2] = 0x00;

    for (i = 0; i < MAX_RETRIES; i++) {
        count = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
        if (count == 3) {
            // Extract ADC value
            int adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI transfer failed (attempt %d): %d\n", i + 1, count);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read MCP3008 after %d retries\n", MAX_RETRIES);
    return -1; // Indicate error
}

// Function to calculate PPM
float calculate_ppm(int adc_value) {
    return (adc_value * 0.5) - 10.0;
}

// Function to classify reading
const char *classify_reading(float ppm) {
    if (ppm > PPM_THRESHOLD_HIGH) {
        return "Alcohol detected! Limit exceeded.";
    } else if (ppm < PPM_THRESHOLD_LOW) {
        return "Sobriety confirmed.";
    } else {
        return "Alcohol level within acceptable range.";
    }
}

// Function to log data
void log_data(float ppm, const char *classification) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %.2f PPM, %s\n", timestamp, ppm, classification);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to clean up resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    if (initialize()) {
        return 1;
    }

    sensor_config_t sensor_config = {
        .channel = MCP3008_CHANNEL,
        .ppm_threshold_high = PPM_THRESHOLD_HIGH,
        .ppm_threshold_low = PPM_THRESHOLD_LOW
    };

    while (!terminate) {
        int adc_value = read_mcp3008(sensor_config.channel);
        if (adc_value != -1) {
            float ppm = calculate_ppm(adc_value);
            const char *classification = classify_reading(ppm);
            log_data(ppm, classification);
        } else {
            fprintf(stderr, "Failed to read ADC value, skipping logging.\n");
        }

        gpioDelay(1000000); // Sample every 1 second (1000000 microseconds)
    }

    cleanup();
    return 0;
}

