float map_pot_to_speed(int pot_value) {
    if (pot_value < 0) pot_value = 0;
    if (pot_value > 1023) pot_value = 1023;

    // Logarithmic mapping
    float speed_factor = MIN_SPEED + (MAX_SPEED - MIN_SPEED) * log10((float)pot_value / 1023.0) / log10((float)MAX_SPEED / MIN_SPEED);

