#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define CS_PIN 8
#define MOSI_PIN 10
#define MISO_PIN 9
#define SCLK_PIN 11
#define LED_PIN 17

// Define SPI channel
#define SPI_CHANNEL 0

// Define sampling parameters
#define SAMPLE_RATE 1000 // Hz
#define SAMPLING_PERIOD 1000000 / SAMPLE_RATE // microseconds

// Define calibration parameters
#define CALIBRATION_TIME 5 // seconds
#define NUM_CALIBRATION_SAMPLES (CALIBRATION_TIME * SAMPLE_RATE)

// Define threshold parameters
#define THRESHOLD_PERCENTAGE 10.0
#define THRESHOLD_MULTIPLIER (1.0 + THRESHOLD_PERCENTAGE / 100.0)

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_mcp3008(int channel);
int calibrate_sound_level();
int is_above_threshold(int sound_level, int average_ambient_level);
void control_led(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Cleaning up and exiting.\n");
        terminate = 1;
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioSetMode(MOSI_PIN, PI_OUTPUT);
    gpioSetMode(MISO_PIN, PI_INPUT);
    gpioSetMode(SCLK_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    gpioWrite(CS_PIN, 1); // Ensure CS is initially high

    return 0;
}

// Initialize SPI communication
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, 1000000, 0); // Channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        return 1;
    }
    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    spi_data[2] = 0x00;

    gpioWrite(CS_PIN, 0); // Select the ADC
    spiXfer(spi_handle, spi_data, spi_data, 3);
    gpioWrite(CS_PIN, 1); // Deselect the ADC

    int adc_value = ((spi_data[1] & 0x03) << 8) + spi_data[2];
    return adc_value;
}

// Calibrate sound level
int calibrate_sound_level() {
    int sum = 0;
    for (int i = 0; i < NUM_CALIBRATION_SAMPLES; i++) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) return -1; // Error reading ADC
        sum += adc_value;
        gpioDelay(SAMPLING_PERIOD); // Wait for sampling period
    }
    int average_ambient_level = sum / NUM_CALIBRATION_SAMPLES;
    return average_ambient_level;
}

// Check if sound level is above threshold
int is_above_threshold(int sound_level, int average_ambient_level) {
    return sound_level > (average_ambient_level * THRESHOLD_MULTIPLIER);
}

// Control LED state
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO and SPI
    if (initialize_gpio() != 0 || initialize_spi() != 0) {
        return 1;
    }

    // Calibrate sound level
    int average_ambient_level = calibrate_sound_level();
    if (average_ambient_level < 0) {
        fprintf(stderr, "Calibration failed. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    printf("Average ambient sound level: %d\n", average_ambient_level);

    // Main loop
    while (!terminate) {
        int sound_level = read_mcp3008(0);
        if (sound_level < 0) {
            fprintf(stderr, "Error reading sound level. Continuing.\n");
            gpioDelay(10000); // Wait 10ms before next attempt
            continue;
        }

        if (is_above_threshold(sound_level, average_ambient_level)) {
            control_led(1); // Turn LED on
            gpioDelay(10000); // Debounce for 10ms
            control_led(0); // Turn LED off
        }

        gpioDelay(10000); // Delay for 10ms (adjust as needed)
    }

    // Cleanup
    control_led(0); // Turn LED off
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

