#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <poll.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <sys/select.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define SAMPLE_RATE 1000 // 1 kHz
#define SAMPLE_PERIOD_NS (1000000000 / SAMPLE_RATE)
#define CS_CHIP 0
#define CS_LINE 8
#define CS_CHIP_NAME "gpiochip0"
#define LOG_FILE "audio_log.txt"

static volatile int keep_running = 1;
static int spi_fd = -1;
static int log_fd = -1;
static struct gpiod_chip *cs_chip = NULL;
static struct gpiod_line *cs_line = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the GPIO line for CS
int init_gpio_cs(struct gpiod_chip *chip, int line)
{
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "audio_sampling";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    struct gpiod_line_request *req = NULL;
    int ret = gpiod_line_request(chip, line, &config, &req);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", line, strerror(-ret));
        return ret;
    }

    cs_chip = chip;
    cs_line = req->line;

    return 0;
}

// Function to release the GPIO line
void release_gpio_cs(struct gpiod_chip *chip, struct gpiod_line *line)
{
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Function to initialize the SPI device
int init_spi(const char *device)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", device, strerror(errno));
        return -1;
    }

    int mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    int bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    int speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read from the MCP3008 ADC
int read_mcp3008(int spi_fd, int channel)
{
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended, channel select
    tx_buf[2] = 0x00; // Dummy byte

    struct gpiod_line_request_config cs_config;
    memset(&cs_config, 0, sizeof(cs_config));
    cs_config.consumer = "audio_sampling";
    cs_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    struct gpiod_line_request *cs_req = NULL;
    int ret = gpiod_line_request(cs_chip, cs_line, &cs_config, &cs_req);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", cs_line, strerror(-ret));
        return -1;
    }

    // Drive CS low
    ret = gpiod_line_set_value(cs_req->line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting CS low: %s\n", strerror(-ret));
        gpiod_line_release(cs_req->line);
        close(spi_fd);
        return -1;
    }

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer);
    if (ret < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        gpiod_line_release(cs_req->line);
        close(spi_fd);
        return -1;
    }

    // Drive CS high
    ret = gpiod_line_set_value(cs_req->line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting CS high: %s\n", strerror(-ret));
        gpiod_line_release(cs_req->line);
        close(spi_fd);
        return -1;
    }

    gpiod_line_release(cs_req->line);

    // Extract the 10-bit ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Function to log the audio data to a file
int log_audio_data(int raw_adc_value)
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC_RAW, &ts);
    long timestamp_ns = ts.tv_sec * 1000000000L + ts.tv_nsec;

    dprintf(log_fd, "%ld|%d\n", timestamp_ns, raw_adc_value);
    fsync(log_fd); // Ensure data is written to disk
    return 0;
}

int main()
{
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO for CS
    if (init_gpio_cs(NULL, CS_LINE) < 0) {
        return EXIT_FAILURE;
    }

    // Initialize SPI
    spi_fd = init_spi(SPI_DEVICE);
    if (spi_fd < 0) {
        release_gpio_cs(cs_chip, cs_line);
        return EXIT_FAILURE;
    }

    // Open the log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(spi_fd);
        release_gpio_cs(cs_chip, cs_line);
        return EXIT_FAILURE;
    }

    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = SAMPLE_PERIOD_NS;

    // Main loop
    while (keep_running) {
        int raw_adc_value = read_mcp3008(spi_fd, 0);
        if (raw_adc_value >= 0) {
            log_audio_data(raw_adc_value);
        } else {
            fprintf(stderr, "Error reading ADC value\n");
        }

        if (nanosleep(&sleep_time, NULL) != 0) {
            if (errno == EINTR) {
                // Interrupted by signal, exit loop
                break;
            } else {
                fprintf(stderr, "nanosleep interrupted: %s\n", strerror(errno));
                break;
            }
        }
    }

    // Cleanup
    close(spi_fd);
    release_gpio_cs(cs_chip, cs_line);
    close(log_fd);

    return EXIT_SUCCESS;
}

