    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Function to log the audio data to a file
int log_audio_data(int raw_adc_value)
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC_RAW, &ts);
    long timestamp_ns = ts.tv_sec * 1000000000L + ts.tv_nsec;

    dprintf(log_fd, "%ld|%d\n", timestamp_ns, raw_adc_value);
    fsync(log_fd); // Ensure data is written to disk
    return 0;
}

int main()
{
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO for CS
    if (init_gpio_cs(NULL, CS_LINE) < 0) {
        return EXIT_FAILURE;
    }

    // Initialize SPI
    spi_fd = init_spi(SPI_DEVICE);
    if (spi_fd < 0) {
        release_gpio_cs(cs_chip, cs_line);
        return EXIT_FAILURE;
    }

    // Open the log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(spi_fd);
        release_gpio_cs(cs_chip, cs_line);
        return EXIT_FAILURE;
    }

    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = SAMPLE_PERIOD_NS;

    // Main loop
    while (keep_running) {
        int raw_adc_value = read_mcp3008(spi_fd, 0);
        if (raw_adc_value >= 0) {
            log_audio_data(raw_adc_value);
        } else {
            fprintf(stderr, "Error reading ADC value\n");
        }

        if (nanosleep(&sleep_time, NULL) != 0) {
            if (errno == EINTR) {
                // Interrupted by signal, exit loop
                break;
            } else {
                fprintf(stderr, "nanosleep interrupted: %s\n", strerror(errno));
                break;
            }
        }
    }

    // Cleanup
    close(spi_fd);
    release_gpio_cs(cs_chip, cs_line);
    close(log_fd);

    return EXIT_SUCCESS;
}

