#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define MCP3008 pins
#define MCP3008_CS 8
#define MCP3008_MOSI 10
#define MCP3008_MISO 9
#define MCP3008_SCLK 11

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI baud rate
#define SPI_BAUD 1000000 // 1 MHz

// Define Kalman filter parameters
#define PROCESS_NOISE 0.01
#define MEASUREMENT_NOISE 0.1

// Define ADXL335 sensitivity and zero-g bias
#define ADXL335_SENSITIVITY 0.3 // 300 mV/g
#define ADXL335_ZERO_G_VOLTAGE 1.5 // 1.5V

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Kalman filter state variables
float x_hat = 0.0;
float p = 1.0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_acceleration(float voltage);
float kalman_filter(float measurement);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    gpioWrite(MCP3008_CS, 0); // Select MCP3008
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    gpioWrite(MCP3008_CS, 1); // Deselect MCP3008

    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (result = %d)\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * 3.3;
}

// Function to convert voltage to acceleration (in g)
float voltage_to_acceleration(float voltage) {
    float acceleration = (voltage - ADXL335_ZERO_G_VOLTAGE) / ADXL335_SENSITIVITY;
    return acceleration;
}

// Kalman filter implementation
float kalman_filter(float measurement) {
    // Prediction step
    float x_hat_pred = x_hat;
    float p_pred = p + PROCESS_NOISE;

    // Update step
    float kalman_gain = p_pred / (p_pred + MEASUREMENT_NOISE);
    x_hat = x_hat_pred + kalman_gain * (measurement - x_hat_pred);
    p = (1 - kalman_gain) * p_pred;

    return x_hat;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MCP3008_CS, PI_OUTPUT);
    gpioSetMode(MCP3008_MOSI, PI_OUTPUT);
    gpioSetMode(MCP3008_MISO, PI_INPUT);
    gpioSetMode(MCP3008_SCLK, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC values
        int adc_x = read_mcp3008(0);
        int adc_y = read_mcp3008(1);
        int adc_z = read_mcp3008(2);

        if (adc_x == -1 || adc_y == -1 || adc_z == -1) {
            fprintf(stderr, "Error: Failed to read ADC values\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC values to voltages
        float voltage_x = adc_to_voltage(adc_x);
        float voltage_y = adc_to_voltage(adc_y);
        float voltage_z = adc_to_voltage(adc_z);

        // Convert voltages to accelerations
        float acceleration_x = voltage_to_acceleration(voltage_x);
        float acceleration_y = voltage_to_acceleration(voltage_y);
        float acceleration_z = voltage_to_acceleration(voltage_z);

        // Apply Kalman filter
        float filtered_x = kalman_filter(acceleration_x);
        float filtered_y = kalman_filter(acceleration_y);
        float filtered_z = kalman_filter(acceleration_z);

        // Print filtered acceleration values
        printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", filtered_x, filtered_y, filtered_z);

        // Delay for 100 ms (10 Hz sampling rate)
        gpioDelay(100000); // 100 ms
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

