#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

// Define the chip name
#define CHIP_NAME "gpiochip0"

// Define the log file name
#define LOG_FILE "magnetic_log.txt"

// Define the sampling interval in milliseconds
#define SAMPLING_INTERVAL_MS 100

// Define the VCC voltage
#define VCC 3.3

// Define the quiescent voltage
#define V_QUIESCENT (VCC / 2.0)

// Define the sensitivity
#define SENSITIVITY 0.025

// Define the magnetic field range for warning
#define MIN_MAGNETIC_FIELD -100.0
#define MAX_MAGNETIC_FIELD 100.0

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *sensor1_line;
struct gpiod_line *sensor2_line;
struct gpiod_line *sensor3_line;

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read the sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(errno));
        return -1; // Indicate an error
    }
    return value;
}

// Function to calculate the magnetic field strength in millitesla
float calculate_magnetic_field(int sensor_value) {
    float voltage = (float)sensor_value * VCC;
    float magnetic_field = (voltage - V_QUIESCENT) / SENSITIVITY;
    return magnetic_field * 1000.0; // Convert to mT
}

// Function to log the sensor readings to a file
int log_sensor_data(float sensor1_mT, float sensor2_mT, float sensor3_mT) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1; // Indicate an error
    }

    // Get current timestamp
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Write the data to the file
    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, sensor1_mT, sensor2_mT, sensor3_mT);

    // Flush the file buffer
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        fclose(fp);
        return -1; // Indicate an error
    }

    fclose(fp);
    return 0;
}

// Function to check if the magnetic field is within the expected range
void check_magnetic_field(float sensor1_mT, float sensor2_mT, float sensor3_mT) {
    if (sensor1_mT < MIN_MAGNETIC_FIELD || sensor1_mT > MAX_MAGNETIC_FIELD) {
        fprintf(stderr, "Warning: Sensor 1 magnetic field out of range: %.2f mT\n", sensor1_mT);
    }
