#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "watering.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
void control_pump(float moisture_percentage);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_event("Error: Invalid MCP3008 channel.");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        log_event("Error: SPI transfer failed.");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        log_event("Error: Invalid ADC value.");
        return -1.0;
    }
    return (float)adc_value / 1023.0 * 100.0;
}

// Function to control the water pump
void control_pump(float moisture_percentage) {
    if (moisture_percentage < MOISTURE_THRESHOLD) {
        gpioWrite(PUMP_GPIO, 1); // Turn pump ON (active high)
        log_event("Pump ON");
    } else {
        gpioWrite(PUMP_GPIO, 0); // Turn pump OFF
        log_event("Pump OFF");
    }
}

// Function to log events to file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    log_event("Signal received, shutting down...");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    log_event("Program started");

    // Configure GPIO17 as output for pump control
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is OFF on startup

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 500kHz, Mode 0
    if (spi_handle < 0) {
        log_event("Error: SPI open failed.");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value from channel 0
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            log_event("Error: Failed to read ADC value.");
        } else {
            // Calculate moisture percentage
            float moisture_percentage = calculate_moisture_percentage(adc_value);
            if (moisture_percentage < 0) {
                log_event("Error: Failed to calculate moisture percentage.");
            } else {
                // Control the pump
                control_pump(moisture_percentage);

                // Log moisture percentage
                char log_message[100];
                snprintf(log_message, sizeof(log_message), "Moisture: %.2f%% (ADC: %d)", moisture_percentage, adc_value);
                log_event(log_message);
            }
        }

        // Wait 60 seconds
        gpioDelay(60000); // pigpio's delay function (milliseconds)
    }

    // Clean up
    log_event("Program exiting...");
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is OFF
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

