// Configuration structure
typedef struct {
    char mqtt_broker_address[256];
    int mqtt_broker_port;
    char mqtt_client_id[64];
    char mqtt_topic[256];
    int led_gpio;
    int led_initial_state;
    int reconnection_delay_max;
    char log_file_path[256];
} Config;

// Global variables
static volatile int running = 1;
static Config config;
static struct mosquitto *mosq = NULL;
static int led_gpio = 17;
static int led_initial_state = 0;
static int reconnection_delay_max = 60; // seconds
static char log_file_path[] = "/var/log/led_control.log";

// Function prototypes
void load_config(const char *config_file);
void signal_handler(int sig);
int mqtt_connect_with_backoff(struct mosquitto **mosq, const char *client_id, const char *host, int port, int keepalive);
void on_connect(struct mosquitto *mosq, void *userdata, int result);
void on_disconnect(struct mosquitto *mosq, void *userdata, int rc);
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
int parse_json_payload(const char *payload, int *led_state);
void set_led_state(int led_state);
void log_message(const char *format, ...);

// Function to load configuration from file
void load_config(const char *config_file) {
    FILE *fp = fopen(config_file, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        exit(EXIT_FAILURE);
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Skip comments and empty lines
        if (line[0] == '#' || line[0] == '\0') continue;

        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (key == NULL || value == NULL) continue;

        if (strcmp(key, "mqtt_broker_address") == 0) {
            strncpy(config.mqtt_broker_address, value, sizeof(config.mqtt_broker_address) - 1);
            config.mqtt_broker_address[sizeof(config.mqtt_broker_address) - 1] = '\0';
        } else if (strcmp(key, "mqtt_broker_port") == 0) {
            config.mqtt_broker_port = atoi(value);
        } else if (strcmp(key, "mqtt_client_id") == 0) {
            strncpy(config.mqtt_client_id, value, sizeof(config.mqtt_client_id) - 1);
            config.mqtt_client_id[sizeof(config.mqtt_client_id) - 1] = '\0';
        } else if (strcmp(key, "mqtt_topic") == 0) {
            strncpy(config.mqtt_topic, value, sizeof(config.mqtt_topic) - 1);
            config.mqtt_topic[sizeof(config.mqtt_topic) - 1] = '\0';
        } else if (strcmp(key, "led_gpio") == 0) {
            config.led_gpio = atoi(value);
        } else if (strcmp(key, "led_initial_state") == 0) {
            config.led_initial_state = atoi(value);
        } else if (strcmp(key, "reconnection_delay_max") == 0) {
            config.reconnection_delay_max = atoi(value);
        } else if (strcmp(key, "log_file_path") == 0) {
            strncpy(config.log_file_path, value, sizeof(config.log_file_path) - 1);
            config.log_file_path[sizeof(config.log_file_path) - 1] = '\0';
        }
    }

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    running = 0;
    log_message("Signal received, shutting down...");
}

// MQTT connect function with exponential backoff
int mqtt_connect_with_backoff(struct mosquitto **mosq, const char *client_id, const char *host, int port, int keepalive) {
    int rc = mosquitto_connect(*mosq, host, port, keepalive);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_message("Error connecting to MQTT broker: %s", mosquitto_strerror(rc));
        int delay = 1;
        while (running) {
            sleep(delay);
            delay *= 2;
            if (delay > reconnection_delay_max) {
                delay = reconnection_delay_max;
            }
            rc = mosquitto_connect(*mosq, host, port, keepalive);
            if (rc == MOSQ_ERR_SUCCESS) {
                log_message("Reconnected to MQTT broker.");
                return MOSQ_ERR_SUCCESS;
            }
        }
        return MOSQ_ERR_ERROR; // Return error if still disconnected after max retries
    }
    return MOSQ_ERR_SUCCESS;
}

// MQTT on connect callback
void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        log_message("Connected to MQTT broker.");
        mosquitto_subscribe(mosq, NULL, config.mqtt_topic, 0);
    } else {
        log_message("Connection failed: %s", mosquitto_strerror(result));
    }
}

// MQTT on disconnect callback
void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    log_message("Disconnected from MQTT broker with code %d", rc);
}

// MQTT on message callback
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen) {
        int led_state;
        if (parse_json_payload((char *)message->payload, &led_state) == 0) {
            set_led_state(led_state);
        } else {
            log_message("Invalid JSON payload received.");
        }
    } else {
        log_message("Empty message received.");
    }
}

// Function to parse JSON payload
int parse_json_payload(const char *payload, int *led_state) {
    cJSON *json = cJSON_Parse(payload);
    if (json == NULL) {
        const char *error_ptr = cJSON_GetErrorPtr();
        if (error_ptr != NULL) {
            log_message("Error parsing JSON: %s", error_ptr);
        }
        return -1;
    }

    cJSON *led_state_json = cJSON_GetObjectItemCaseSensitive(json, "led_state");
    if (cJSON_IsBoolean(led_state_json)) {
        *led_state = cJSON_GetBooleanValue(led_state_json);
        cJSON_Delete(json);
        return 0;
    } else {
        cJSON_Delete(json);
        return -1;
    }
}

// Function to set LED state
void set_led_state(int led_state) {
    gpioWrite(led_gpio, led_state);
    log_message("LED set to %d", led_state);
}

// Function to log messages with timestamp
void log_message(const char *format, ...) {
    va_list args;
    va_start(args, format);
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(stderr, "%s ", timestamp);
    vfprintf(stderr, format, args);
    fprintf(stderr, "\n");

    // Also log to file
    FILE *fp = fopen(config.log_file_path, "a");
    if (fp != NULL) {
        va_list args_file;
        va_copy(args_file, args);
        fprintf(fp, "%s ", timestamp);
        vfprintf(fp, format, args_file);
        fprintf(fp, "\n");
        va_end(args_file);
        fclose(fp);
    }
}

int main() {
    // Load configuration
    load_config("led_control.conf");

    // Initialize syslog
    openlog("led_control", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return 1;
    }

    gpioSetMode(led_gpio, PI_OUTPUT);
    gpioWrite(led_gpio, led_initial_state);

    // Initialize mosquitto
    mosquitto_lib_init();
    mosq = mosquitto_new(config.mqtt_client_id, true, NULL);
    if (!mosq) {
        log_message("Error creating mosquitto instance.");
        gpioTerminate();
        mosquitto_lib_cleanup();
        return 1;
    }

    // Set callbacks
    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);

    // Connect to MQTT broker with backoff
    if (mqtt_connect_with_backoff(mosq, config.mqtt_client_id, config.mqtt_broker_address, config.mqtt_broker_port, 60) != MOSQ_ERR_SUCCESS) {
        gpioTerminate();
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Start mosquitto loop
    mosquitto_loop_start(mosq);

    // Main loop
    while (running) {
        sleep(1);
    }

    // Clean up
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();

    // Close syslog
    closelog();

    return 0;
}

