#include <pigpio.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO17 as input for the sound sensor
    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);

    // Set GPIO18 as output for the alarm LED
    gpioSetMode(ALARM_LED_PIN, PI_OUTPUT);

    return 0;
}

// Function to read the sound sensor value
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Function to control the alarm LED
void control_alarm_led(int on) {
    gpioWrite(ALARM_LED_PIN, on);
}

// Function to blink the alarm LED for 1 second
void blink_alarm_led() {
    control_alarm_led(1); // Turn LED ON
    gpioDelay(1000);      // Wait for 1 second
    control_alarm_led(0); // Turn LED OFF
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioWrite(ALARM_LED_PIN, 0); // Ensure LED is OFF
    gpioTerminate();             // Terminate pigpio
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sound_level = read_sound_sensor();
        printf("Sound level: %d\n", sound_level);

        if (sound_level == 0) {
            blink_alarm_led();
        }

        gpioDelay(100); // Delay for 100 ms
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

