#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/file.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "/var/log/vibration_shutdown.log"
#define DEBOUNCE_DELAY_NS 100000000 // 100ms

static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static int log_fd = -1;

void signal_handler(int sig) {
    terminate = 1;
}

int log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_fd == -1) {
        fprintf(stderr, "Error: Log file not opened.\n");
        return -1;
    }

    if (flock(log_fd, LOCK_EX) == -1) {
        perror("flock");
        return -1;
    }

    if (fprintf(stdout, "%s: %s\n", timestamp, message) < 0) {
        perror("fprintf");
        flock(log_fd, LOCK_UN);
        return -1;
    }

    if (flock(log_fd, LOCK_UN) == -1) {
        perror("flock");
        return -1;
    }

    if (fflush(stdout) != 0) {
        perror("fflush");
        return -1;
    }

    if (fflush(stderr) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

int main() {
    struct timespec debounce_delay = {0, DEBOUNCE_DELAY_NS};
    int ret;

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd == -1) {
        perror("open");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        close(log_fd);
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        close(log_fd);
        return EXIT_FAILURE;
    }

    // Request falling edge event
    ret = gpiod_line_request_rising_edge_events(line, "vibration-monitor");
    if (ret < 0) {
        perror("gpiod_line_request_rising_edge_events");
        gpiod_chip_close(chip);
        close(log_fd);
        return EXIT_FAILURE;
    }

    printf("Vibration monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Wait for falling edge event
        ret = gpiod_line_event_wait(line, &debounce_delay);
        if (ret < 0) {
            perror("gpiod_line_event_wait");
            break;
        }

        // Read event
        ret = gpiod_line_event_read(line);
        if (ret < 0) {
            perror("gpiod_line_event_read");
            break;
        }

        if (ret < 0) {
            fprintf(stderr, "Error reading event.\n");
            break;
        }

        // Log message
        if (log_message("Vibration detected!") != 0) {
            fprintf(stderr, "Error logging message.\n");
            break;
        }

        // Shutdown command
        if (system("sudo shutdown -h now") != 0) {
            perror("system");
            fprintf(stderr, "Shutdown command failed.\n");
            break;
        }

        break; // Exit the loop after shutdown command
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_fd != -1) {
        close(log_fd);
    }

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

