#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_CHIP_ID_REG 0xD0
#define BMP280_CALIB_DATA_START 0x88
#define BMP280_PRESSURE_MSB_REG 0xF7
#define BMP280_TEMP_MSB_REG 0xFA
#define BMP280_CTRL_MEAS_REG 0xF4

// Calibration data structure
typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

// Global variables
int i2c_handle;
bmp280_calib_data calib;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_calibration_data(bmp280_calib_data *calib);
int read_raw_data(int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t adc_T, bmp280_calib_data calib);
double compensate_pressure(int32_t adc_P, double t_fine, bmp280_calib_data calib);
double calculate_altitude(double pressure);
int log_data(double altitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0); // I2C bus 1, address 0x76, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read calibration data from the BMP280
int read_calibration_data(bmp280_calib_data *calib) {
    char data[24];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_CALIB_DATA_START, data, 24) != 24) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    calib->dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib->dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib->dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib->dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib->dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib->dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib->dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib->dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib->dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib->dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib->dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib->dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);

    return 0;
}

// Read raw temperature and pressure data from the BMP280
int read_raw_data(int32_t *temperature, int32_t *pressure) {
    char data[6];

    // Set the control register to trigger a measurement
    if (i2cWriteByteData(i2c_handle, BMP280_CTRL_MEAS_REG, 0xF4) != 0) {
        fprintf(stderr, "Error writing to control register\n");
        return -1;
    }

    // Wait for the measurement to complete (adjust as needed)
    gpioDelay(10); // 10 ms delay

    if (i2cReadI2CBlockData(i2c_handle, BMP280_PRESSURE_MSB_REG, data, 6) != 6) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *pressure = (int32_t)data[0] << 12 | (int32_t)data[1] << 4 | (int32_t)data[2] >> 4;
    *temperature = (int32_t)data[3] << 12 | (int32_t)data[4] << 4 | (int32_t)data[5] >> 4;

    return 0;
}

// Compensate temperature using Bosch formula
double compensate_temperature(int32_t adc_T, bmp280_calib_data calib) {
    double var1, var2, T;
    var1 = (((double)adc_T) / 16384.0 - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2);
    var2 = ((((double)adc_T) / 131072.0 - ((double)calib.dig_T1) / 8192.0) * (((double)adc_T) / 131072.0 - ((double)calib.dig_T1) / 8192.0)) * ((double)calib.dig_T3);
    double t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// Compensate pressure using Bosch formula
double compensate_pressure(int32_t adc_P, double t_fine, bmp280_calib_data calib) {
    double var1, var2, p;
    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)calib.dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)calib.dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)calib.dig_P4) * 65536.0);
    var1 = (((double)calib.dig_P3) * var1 * var1 / 524288.0 + ((double)calib.dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)calib.dig_P1);
    if (var1 == 0)
    {
        return 0;
    }
    p = 1048576.0 - (double)adc_P;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)calib.dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)calib.dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)calib.dig_P7)) / 16.0;
    return p;
}

// Calculate altitude using the barometric formula
double calculate_altitude(double pressure) {
    double sea_level_pressure = 101325.0; // Standard sea-level pressure in Pa
    return 44330.0 * (1.0 - pow(pressure / sea_level_pressure, 0.1903));
}

// Log data to a file
int log_data(double altitude) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fp = fopen("altitude_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    fprintf(fp, "%s,%.2f\n", timestamp, altitude);
    fflush(fp); // Ensure data is written to disk immediately
    fclose(fp);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify BMP280 chip ID
    char chip_id;
    if (i2cReadByteData(i2c_handle, BMP280_CHIP_ID_REG) < 0) {
        fprintf(stderr, "Error reading chip ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    chip_id = i2cReadByteData(i2c_handle, BMP280_CHIP_ID_REG);

    if (chip_id != 0x58) {
        fprintf(stderr, "Incorrect chip ID: 0x%x\n", chip_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(&calib) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure the BMP280 (optional, using default settings)
    // i2cWriteByteData(i2c_handle, BMP280_CTRL_MEAS_REG, 0xF4); // Set ctrl_meas register

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int32_t raw_temperature, raw_pressure;
    double temperature, pressure, altitude;

    // Main loop
    while (!terminate) {
        // Read raw data
        if (read_raw_data(&raw_temperature, &raw_pressure) == 0) {
            // Compensate temperature and pressure
            temperature = compensate_temperature(raw_temperature, calib);
            pressure = compensate_pressure(raw_pressure, temperature, calib);

            // Calculate altitude
            altitude = calculate_altitude(pressure);

            // Log data
            if (log_data(altitude) != 0) {
                fprintf(stderr, "Error logging data\n");
            }

            printf("Altitude: %.2f m\n", altitude);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

