#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define MCP3008_VREF 3.3
#define LM35_SENSITIVITY 0.01 // 10mV/°C = 0.01 V/°C
#define BUFFER_SIZE 120
#define LOG_FILE "temp_log.dat"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

CircularBuffer temp_buffer;

// Function prototypes
int initialize();
int read_mcp3008(int channel);
float convert_to_celsius(int adc_value);
void add_to_buffer(float temperature);
void save_to_file();
void signal_handler(int signal);
void cleanup();

// Initialize the circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Function to add a temperature reading to the circular buffer
void add_to_buffer(float temperature) {
    temp_buffer.buffer[temp_buffer.head] = temperature;
    temp_buffer.head = (temp_buffer.head + 1) % BUFFER_SIZE;
    if (temp_buffer.count < BUFFER_SIZE) {
        temp_buffer.count++;
    }
}

// Function to save the circular buffer to a file
void save_to_file() {
    FILE *fp = fopen(LOG_FILE, "wb");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    size_t elements_written = fwrite(temp_buffer.buffer, sizeof(float), temp_buffer.count, fp);
    if (elements_written != temp_buffer.count) {
        fprintf(stderr, "Error writing to log file: wrote %zu elements, expected %d\n", elements_written, temp_buffer.count);
    }

    fclose(fp);
}

// Function to read from the MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct the SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode + channel number
    tx_buffer[2] = 0x00; // Don't care

    // Perform the SPI transaction
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transaction failed: %d\n", result);
        return -1;
    }

    // Extract the ADC value from the received data
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to Celsius
float convert_to_celsius(int adc_value) {
    float voltage = (float)adc_value * MCP3008_VREF / 1024.0;
    float temperature = voltage / LM35_SENSITIVITY;
    return temperature;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close SPI and terminate pigpio
void cleanup() {
    spiClose(spi_handle);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    init_circular_buffer(&temp_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

int main() {
    if (initialize()) {
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read temperature from MCP3008
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Skipping this reading.\n");
            sleep(5);
            continue;
        }

        // Convert ADC value to Celsius
        float temperature = convert_to_celsius(adc_value);

        // Add temperature to circular buffer
        add_to_buffer(temperature);

        // Log temperature to console
        printf("Temperature: %.2f °C\n", temperature);

        // Save buffer to file every 5 seconds
        save_to_file();

        // Wait for 5 seconds
        sleep(5);
    }

    cleanup();
    return 0;
}

