        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to log data to file
int log_data(FILE *fp, float lux, int sound_level) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, Light: %.2f lux, Sound: %d\n", timestamp, lux, sound_level) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_DEVICE);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed, exiting.\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = init_spi(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed, exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        close(spi_fd);
        return 1;
    }

    float lux;
    int sound_level;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_bh1750(i2c_fd, &lux) == 0 && read_mcp3008(spi_fd, MCP3008_CHANNEL) >= 0) {
            // Log data
            if (log_data(log_file, lux, sound_level) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    close(i2c_fd);
    close(spi_fd);
    fclose(log_file);

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

