#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define LOG_FILE "flame_events.log"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the GPIO line
int initialize_gpio(struct gpiod_chip *chip, int pin) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "flame_sensor";

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", pin, strerror(errno));
        return -1;
    }

    int ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", pin, strerror(errno));
        gpiod_line_release(line);
        return -1;
    }

    // Enable pull-down resistor
    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting pull-down resistor on GPIO line %d: %s\n", pin, strerror(errno));
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Function to read the flame sensor value
int read_flame_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Function to log the flame event
int log_flame_event(FILE *log_file, int pin, int state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    if (t == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, %d, %d\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
            t->tm_hour, t->tm_min, t->tm_sec, pin, state);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to print an alarm message
void print_alarm(int pin) {
    printf("ALARM: Flame detected on GPIO %d!\n", pin);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Initialize the GPIO line
    if (initialize_gpio(chip, GPIO_PIN) < 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    fprintf(stderr, "Flame sensor monitoring started on GPIO %d...\n", GPIO_PIN);

    // Main loop
    while (!terminate) {
        int sensor_value = read_flame_sensor(line);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor value, retrying...\n");
            // Attempt to re-initialize the GPIO line
            gpiod_line_release(line);
            if (initialize_gpio(chip, GPIO_PIN) < 0) {
                fprintf(stderr, "GPIO re-initialization failed.\n");
                break; // Exit loop if re-initialization fails
            }
            sleep(1); // Wait before retrying
            continue;
        }

        if (sensor_value == 1) {
            print_alarm(GPIO_PIN);
        }

        if (log_flame_event(log_file, GPIO_PIN, sensor_value) < 0) {
            fprintf(stderr, "Error logging flame event.\n");
        }

        sleep(1);
    }

    // Cleanup
    fprintf(stderr, "Cleaning up...\n");
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);

    fprintf(stderr, "Exiting.\n");
    return EXIT_SUCCESS;
}

