#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 500000
#define SPI_FLAGS 0
#define MCP3008_CHANNEL 0
#define MCP4725_I2C_ADDR 0x62
#define VREF 3.3
#define TEMP_MIN 0.0
#define TEMP_MAX 50.0
#define VOLTAGE_MIN 0.0
#define VOLTAGE_MAX 3.3
#define LOG_FILE "temperature_log.txt"

// Global variables
int spi_handle;
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_celsius(int adc_value);
float celsius_to_voltage(float celsius);
int write_dac(float voltage);
int log_data(int adc_value, float celsius, float voltage);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error during SPI transfer: %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to Celsius
float convert_to_celsius(int adc_value) {
    float voltage = (adc_value / 1023.0) * VREF;
    float celsius = (voltage - 0.5) * 100; // TMP36: 10mV/°C, 500mV offset
    return celsius;
}

// Function to convert Celsius to voltage
float celsius_to_voltage(float celsius) {
    return (celsius / 50.0) * VREF;
}

// Function to write to MCP4725 DAC
int write_dac(float voltage) {
    int dac_value = (int)((voltage / VREF) * 4095);
    char tx_buffer[3];
    tx_buffer[0] = 0x80; // Write command
    tx_buffer[1] = (dac_value >> 4) & 0xFF; // MSB
    tx_buffer[2] = (dac_value << 4) & 0xF0; // LSB

    int result = i2cWriteDevice(i2c_handle, tx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error during I2C write: %d\n", result);
        return -1; // Indicate error
    }
    return 0;
}

// Function to log data to file
int log_data(int adc_value, float celsius, float voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %.2f, %.2f\n", timestamp, adc_value, celsius, voltage);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MCP4725_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert to Celsius
        float celsius = convert_to_celsius(adc_value);

        // Convert to voltage
        float voltage = celsius_to_voltage(celsius);

        // Write to DAC
        if (write_dac(voltage) != 0) {
            fprintf(stderr, "Error writing to DAC, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Log data
        log_data(adc_value, celsius, voltage);

        // Print to stdout
        printf("ADC: %d, Celsius: %.2f, Voltage: %.2f\n", adc_value, celsius, voltage);

        // Wait 0.5 seconds
        gpioDelay(500);
    }

    // Cleanup
    i2cClose(i2c_handle);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

