#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define the GPIO pins connected to the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

// Define the chip name for the GPIO chip
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *relay1_line, *relay2_line, *relay3_line, *relay4_line;

// Function prototypes
int initialize_gpio(void);
void activate_relay(struct gpiod_line *line);
void deactivate_relay(struct gpiod_line *line);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Function to initialize the GPIO lines
int initialize_gpio(void) {
    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Request each GPIO line as an output
    relay1_line = gpiod_chip_get_line(chip, RELAY1_PIN);
    if (!relay1_line) {
        perror("Error getting GPIO line for relay 1");
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_request_output(relay1_line, "relay1", 0) < 0) {
        perror("Error requesting GPIO line for relay 1");
        gpiod_chip_close(chip);
        return -1;
    }

    relay2_line = gpiod_chip_get_line(chip, RELAY2_PIN);
    if (!relay2_line) {
        perror("Error getting GPIO line for relay 2");
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_request_output(relay2_line, "relay2", 0) < 0) {
        perror("Error requesting GPIO line for relay 2");
        gpiod_chip_close(chip);
        return -1;
    }

    relay3_line = gpiod_chip_get_line(chip, RELAY3_PIN);
    if (!relay3_line) {
        perror("Error getting GPIO line for relay 3");
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_request_output(relay3_line, "relay3", 0) < 0) {
        perror("Error requesting GPIO line for relay 3");
        gpiod_chip_close(chip);
        return -1;
    }

    relay4_line = gpiod_chip_get_line(chip, RELAY4_PIN);
    if (!relay4_line) {
        perror("Error getting GPIO line for relay 4");
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_request_output(relay4_line, "relay4", 0) < 0) {
        perror("Error requesting GPIO line for relay 4");
        gpiod_chip_close(chip);
        return -1;
    }

    // Set all relays to the inactive state (LOW)
    gpiod_line_set_value(relay1_line, 0);
    gpiod_line_set_value(relay2_line, 0);
    gpiod_line_set_value(relay3_line, 0);
    gpiod_line_set_value(relay4_line, 0);

    return 0;
}

// Function to activate a relay
void activate_relay(struct gpiod_line *line) {
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Error setting GPIO line value");
    }
}

// Function to deactivate a relay
void deactivate_relay(struct gpiod_line *line) {
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Error setting GPIO line value");
    }
}

// Function to cleanup the GPIO lines
void cleanup_gpio(void) {
    // Deactivate all relays
    deactivate_relay(relay1_line);
    deactivate_relay(relay2_line);
    deactivate_relay(relay3_line);
    deactivate_relay(relay4_line);

    // Release the GPIO lines
    gpiod_line_release(relay1_line);
    gpiod_line_release(relay2_line);
    gpiod_line_release(relay3_line);
    gpiod_line_release(relay4_line);

    // Close the GPIO chip
    gpiod_chip_close(chip);
}

int main(void) {
    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the GPIO lines
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Activate and deactivate each relay in sequence
        activate_relay(relay1_line);
        usleep(1000000); // 1 second
        deactivate_relay(relay1_line);
        usleep(1000000); // 1 second

        activate_relay(relay2_line);
        usleep(1000000); // 1 second
        deactivate_relay(relay2_line);
        usleep(1000000); // 1 second

        activate_relay(relay3_line);
        usleep(1000000); // 1 second
        deactivate_relay(relay3_line);
        usleep(1000000); // 1 second

        activate_relay(relay4_line);
        usleep(1000000); // 1 second
        deactivate_relay(relay4_line);
        usleep(1000000); // 1 second
    }

    return 0;
}

