    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0); // Read from channel 0
        if (adc_value >= 0) {
            if (adc_value > THRESHOLD) {
                control_led(1); // Turn on LED
                log_event(adc_value);
                gpioDelay(500); // Keep LED on for 500 ms
                control_led(0); // Turn off LED
            }
        } else {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        }

        gpioDelay(10); // Read every 10 ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

