// Function to read the rain sensor from MCP3008 ADC
int read_rain_sensor(int spi_handle) {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];
    int adc_value;

    // Construct SPI message to read from channel 0
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | 0) << 4; // Single-ended mode, channel 0
    tx_buffer[2] = 0x00; // Don't care

