        log_rain_data(rain_level);

        // Control motor based on rain level
        if (rain_level >= RAIN_THRESHOLD) {
            control_motor(MOTOR_IN1, MOTOR_IN2, MOTOR_ENA, 1, MOTOR_SPEED); // Close window
        } else {
            control_motor(MOTOR_IN1, MOTOR_IN2, MOTOR_ENA, 0, MOTOR_SPEED); // Open window
        }

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // Cleanup resources before exiting
    printf("Cleaning up...\n");
    control_motor(MOTOR_IN1, MOTOR_IN2, MOTOR_ENA, 0, 0); // Stop motor
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

