#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define AUDIO_INPUT_PIN 26
#define LED_OUTPUT_PIN 16

// Define constants
#define ADC_SAMPLING_TIME_US 1000 // 1 ms sampling time
#define THRESHOLD 700             // ADC reading threshold
#define DEBOUNCE_DELAY_MS 50
#define LED_ON_TIME_MS 500

// Global variables
static volatile int running = 1;
static volatile unsigned long last_detection_time = 0;

// Function prototypes
int initialize_gpio();
int read_adc();
int is_clap_detected(int adc_value);
void control_led(int state);
void print_detection_message();
void debounce_delay();
void signal_handler(int signal);

// Signal handler for clean shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        running = 0;
        control_led(0); // Turn off LED
        gpioTerminate(); // Terminate pigpio
        exit(0);
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(AUDIO_INPUT_PIN, PI_INPUT); // Set audio input pin as input
    gpioSetMode(LED_OUTPUT_PIN, PI_OUTPUT);  // Set LED output pin as output
    control_led(0); // Ensure LED is off initially

    return 0; // Indicate success
}

// Read ADC value using bit-banging
int read_adc() {
    int adc_value = 0;
    int i;

    gpioSetMode(AUDIO_INPUT_PIN, PI_OUTPUT); // Set as output
    gpioWrite(AUDIO_INPUT_PIN, 0);           // Set low
    gpioDelay(10);                           // Wait 10 us

    gpioSetMode(AUDIO_INPUT_PIN, PI_INPUT);  // Set as input

    for (i = 0; i < 10; i++) {
        // Measure the time the pin is high (approximates ADC value)
        unsigned int start_time = gpioTick();
        while (gpioRead(AUDIO_INPUT_PIN) == 0) {
            if (gpioTick() - start_time > ADC_SAMPLING_TIME_US) {
                // Timeout, assume low value
                adc_value++;
                break;
            }
        }
        adc_value++;
    }

    return adc_value;
}

// Check if a clap is detected
int is_clap_detected(int adc_value) {
    return (adc_value > THRESHOLD);
}

// Control the LED state
void control_led(int state) {
    gpioWrite(LED_OUTPUT_PIN, state);
}

// Print detection message with timestamp
void print_detection_message() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s - Clap detected!\n", timestamp);
}

// Debounce delay
void debounce_delay() {
    gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to us
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Clap detector started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_adc();
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            gpioDelay(100000); // Wait 100 ms before retrying
            continue;
        }

        if (is_clap_detected(adc_value)) {
            unsigned long current_time = gpioTick();
            if (current_time - last_detection_time > 50000) { // 50 ms debounce
                print_detection_message();
                control_led(1); // Turn on LED
                gpioDelay(LED_ON_TIME_MS * 1000); // Keep LED on for 500 ms
                control_led(0); // Turn off LED
                last_detection_time = current_time;
            }
        }

        gpioDelay(10000); // Check every 10 ms
    }

    return 0;
}

