#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

#define GPIO_PIN 17
#define GPIO_PATH "/sys/class/gpio"
#define LOG_FILE "distance_log.txt"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", signal);
}

// Function to export the GPIO pin
int export_gpio(int gpio) {
    char export_path[64];
    int fd;

    snprintf(export_path, sizeof(export_path), GPIO_PATH "/export");
    fd = open(export_path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open GPIO export file");
        return -1;
    }

    char gpio_str[4];
    snprintf(gpio_str, sizeof(gpio_str), "%d", gpio);
    if (write(fd, gpio_str, strlen(gpio_str)) < 0) {
        perror("Failed to write GPIO number to export file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to unexport the GPIO pin
int unexport_gpio(int gpio) {
    char unexport_path[64];
    int fd;

    snprintf(unexport_path, sizeof(unexport_path), GPIO_PATH "/unexport");
    fd = open(unexport_path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open GPIO unexport file");
        return -1;
    }

    char gpio_str[4];
    snprintf(gpio_str, sizeof(gpio_str), "%d", gpio);
    if (write(fd, gpio_str, strlen(gpio_str)) < 0) {
        perror("Failed to write GPIO number to unexport file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to set the GPIO direction
int set_gpio_direction(int gpio, const char *direction) {
    char direction_path[64];
    int fd;

    snprintf(direction_path, sizeof(direction_path), GPIO_PATH "/gpio%d/direction", gpio);
    fd = open(direction_path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open GPIO direction file");
        return -1;
    }

    if (write(fd, direction, strlen(direction)) < 0) {
        perror("Failed to write direction to GPIO direction file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to read the GPIO value
int read_gpio_value(int gpio) {
    char value_path[64];
    int fd;
    char value_str[3];

    snprintf(value_path, sizeof(value_path), GPIO_PATH "/gpio%d/value", gpio);
    fd = open(value_path, O_RDONLY);
    if (fd < 0) {
        perror("Failed to open GPIO value file");
        return -1;
    }

    if (read(fd, value_str, 3) < 0) {
        perror("Failed to read GPIO value");
        close(fd);
        return -1;
    }

    close(fd);
    return atoi(value_str);
}

// Function to log the distance to a file
int log_distance(const char *timestamp, int distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    fprintf(fp, "%s, Distance: %d mm\n", timestamp, distance);
    fclose(fp);
    return 0;
}

// Function to calculate the distance
double calculate_distance(double voltage) {
    double A = 26.0;
    double B = -6.0;
    return A / voltage + B;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export GPIO pin
    if (export_gpio(GPIO_PIN) < 0) {
        fprintf(stderr, "Failed to export GPIO %d.  Try running with sudo.\n", GPIO_PIN);
        return 1;
    }

    // Set GPIO direction to input
    if (set_gpio_direction(GPIO_PIN, "in") < 0) {
        unexport_gpio(GPIO_PIN);
        return 1;
    }

    printf("Distance sensor program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read GPIO value
        int gpio_value = read_gpio_value(GPIO_PIN);
        if (gpio_value < 0) {
            fprintf(stderr, "Failed to read GPIO %d value. Retrying in 1 second.\n", GPIO_PIN);
            sleep(1);
            continue;
        }

        // Convert GPIO value to voltage (0V or 3.3V)
        double voltage = (double)gpio_value;

        // Calculate distance
        double distance = calculate_distance(voltage);

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[20];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log distance
        if (log_distance(timestamp, (int)distance) < 0) {
            fprintf(stderr, "Failed to log distance.\n");
        }

        // Check proximity and print feeder status
        if (distance < 200) {
