#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 17
#define DRY_ADC_VALUE 800
#define WET_ADC_VALUE 300
#define MOISTURE_THRESHOLD 30.0
#define LOG_FILE "soil_moisture.log"

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *pump_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device);
int spi_read_adc(int channel);
float calculate_moisture_percentage(int adc_value);
int control_pump(int state);
int log_data(float moisture_percentage, int pump_state);
void signal_handler(int sig);
int gpio_init(int pin);
int gpio_set_value(int pin, int value);
int gpio_uninit(int pin);

// SPI Initialization
int spi_init(const char *device) {
    int fd;
    unsigned int mode = SPI_MODE;
    unsigned int bits = SPI_BITS_PER_WORD;
    unsigned int speed = SPI_SPEED;

    fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_MODE, &mode) == -1) {
        perror("Error getting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_BITS_PER_WORD, &bits) == -1) {
        perror("Error getting bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error getting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Read ADC
int spi_read_adc(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // MCP3008 command: start bit (1), single-ended mode (1), channel (3 bits), don't care (4 bits)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended + channel
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));
    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Calculate Moisture Percentage
float calculate_moisture_percentage(int adc_value) {
    float percentage = 100.0 - ((float)(adc_value - WET_ADC_VALUE) / (float)(DRY_ADC_VALUE - WET_ADC_VALUE) * 100.0);
    if (percentage < 0.0) percentage = 0.0;
    if (percentage > 100.0) percentage = 100.0;
    return percentage;
}

// Control Water Pump
int control_pump(int state) {
    if (gpio_set_value(PUMP_GPIO, state) != 0) {
        fprintf(stderr, "Error setting pump state\n");
        return -1;
    }
    return 0;
}

// Log Data
int log_data(float moisture_percentage, int pump_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f, %s\n", timestamp, moisture_percentage, pump_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal Handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// GPIO Initialization
int gpio_init(int pin) {
    char chipname[20];
    int ret;

    snprintf(chipname, sizeof(chipname), "gpiochip0");
    gpio_chip = gpiod_chip_open_by_name(chipname);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    pump_line = gpiod_chip_get_line(gpio_chip, pin);
    if (!pump_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    ret = gpiod_line_request_output(pump_line, "soil_moisture_app", 0); // Initial value LOW
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// GPIO Set Value
int gpio_set_value(int pin, int value) {
    int ret;
    ret = gpiod_line_set_value(pump_line, value);
    if (ret < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// GPIO Uninit
int gpio_uninit(int pin) {
    if (pump_line) {
        gpiod_line_release(pump_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    return 0;
}

int main() {
    int adc_value;
    float moisture_percentage;
    int pump_state = 0; // 0 = OFF, 1 = ON
    struct timespec sleep_time;

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(PUMP_GPIO) != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpio_uninit(PUMP_GPIO);
        close(spi_fd);
        return 1;
    }

    sleep_time.tv_sec = 60; // 60 seconds
    sleep_time.tv_nsec = 0;

    // Main loop
    while (!terminate) {
        // Read ADC value
        adc_value = spi_read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            fprintf(log_file, "Error reading ADC value\n");
        } else {
            // Calculate moisture percentage
            moisture_percentage = calculate_moisture_percentage(adc_value);

            // Control pump
            if (moisture_percentage < MOISTURE_THRESHOLD && pump_state == 0) {
                if (control_pump(1) == 0) {
                    pump_state = 1;
                    fprintf(log_file, "Moisture below threshold, turning pump ON\n");
                }
            } else if (moisture_percentage >= MOISTURE_THRESHOLD && pump_state == 1) {
                if (control_pump(0) == 0) {
                    pump_state = 0;
                    fprintf(log_file, "Moisture above threshold, turning pump OFF\n");
                }
            }

            // Log data
            log_data(moisture_percentage, pump_state);
        }

        // Sleep for 60 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    fprintf(log_file, "Program terminated\n");
    fclose(log_file);
    gpio_uninit(PUMP_GPIO);
    close(spi_fd);

    return 0;
}

