#include <signal.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define VREF 3300.0       // VREF = 3.3 V * 1000 mV/V = 3300 mV
#define DRV5055_SENSITIVITY 100.0 // mV/mT
#define DRV5055_QUIESCENT_VOLTAGE 1650.0 // mV
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_MS 500

// Global variables
int spi_fd = -1;
int gpio_line = 8;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_transfer(int spi_fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int read_mcp3008(int spi_fd, int channel);
float adc_to_voltage(int adc_value);
float voltage_to_magnetic_field(float voltage);
int log_magnetic_field(float magnetic_field);
void signal_handler(int signal);

// SPI transfer function
int spi_transfer(int spi_fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
