float voltage_to_field(float voltage) {
    float field_strength = (voltage - VCC / 2.0) * 1000.0 / SENSITIVITY;
    return field_strength;
}

// Log field strength to file
void log_field_strength(float field_strength) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.3f mT\n", timestamp, field_strength);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Control LED based on field strength
void control_led(float field_strength) {
    if (field_strength > config.threshold) {
        gpioWrite(config.led_gpio, 1); // Turn LED on
    } else {
        gpioWrite(config.led_gpio, 0); // Turn LED off
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed, exiting...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(config.led_gpio, 0); // Turn off LED
    gpioTerminate();
}

