void signal_handler(int signal) {
    if (signal == SIGINT) {
        terminate = 1;
        printf("Ctrl+C detected. Exiting gracefully.\n");
    }
}

// Function to read from MCP3008
int read_mcp3008(int channel) {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];
    int result;

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = 0x80 | (channel << 4); // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    // Transfer data
    result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    if (result != 3) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1; // Indicate error
    }

    // Extract 10-bit result
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];

    return adc_value;
}

