    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Open file in append mode
    fp = fopen("current_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening current_log.txt for writing!\n");
        return;
    }

    // Write to file
    fprintf(fp, "%s %.2f A\n", timestamp, current);

    // Close file
    fclose(fp);
}

