#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17

// Debounce parameters
#define DEBOUNCE_SAMPLES 5
#define DEBOUNCE_DELAY_MS 2

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor(int gpio_pin);
int debounce_read(int gpio_pin);
void log_sensor_data(int sensor_id, int state);
void check_alert(int sensor1_state, int sensor2_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to read the sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to debounce the sensor readings
int debounce_read(int gpio_pin) {
    int samples[DEBOUNCE_SAMPLES];
    int i, sum = 0;

    // Sample the sensor multiple times
    for (i = 0; i < DEBOUNCE_SAMPLES; i++) {
        samples[i] = read_sensor(gpio_pin);
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Delay in microseconds
    }

    // Calculate the majority value
    for (i = 0; i < DEBOUNCE_SAMPLES; i++) {
        if (samples[i] == 0) {
            sum++;
        }
    }

    return (sum >= DEBOUNCE_SAMPLES / 2) ? 0 : 1;
}

// Function to log the sensor data
void log_sensor_data(int sensor_id, int state) {
    printf("Sensor %d: %d\n", sensor_id, state);
}

// Function to check for an alert condition
void check_alert(int sensor1_state, int sensor2_state) {
    if (sensor1_state == 0 && sensor2_state == 0) {
        printf("ALERT: Both sensors detect object\n");
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read and debounce sensor 1
        int sensor1_state = debounce_read(SENSOR_1_PIN);
        log_sensor_data(1, sensor1_state);

        // Read and debounce sensor 2
        int sensor2_state = debounce_read(SENSOR_2_PIN);
        log_sensor_data(2, sensor2_state);

        // Check for alert condition
        check_alert(sensor1_state, sensor2_state);

        // Wait for 1 second
        sleep(1);
    }

    // Release GPIO resources
    gpioTerminate();

    return 0;
}

