#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>
#include <errno.h>

#define GPIO_PIN 17
#define IMAGE_WIDTH 1280
#define IMAGE_HEIGHT 720
#define DEBOUNCE_DELAY_MS 200
#define IMAGE_DIR "/home/pi/security_cam/"

static volatile int running = 1;

void signal_handler(int sig);
int initialize_gpio();
int capture_image(const char *filename);
int create_timestamped_filename(char *filename, size_t filename_size);
int log_event(const char *message);

int main() {
    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed. Exiting.");
        closelog();
        return 1;
    }

    log_event("Motion detector started.");

    int last_state = 0;
    int current_state;

    while (running) {
        current_state = gpioRead(GPIO_PIN);

        if (current_state != last_state) {
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce
            int confirmed_state = gpioRead(GPIO_PIN);
            if (confirmed_state == current_state) {
                if (current_state == 1) {
                    char filename[256];
                    if (create_timestamped_filename(filename, sizeof(filename)) == 0) {
                        if (capture_image(filename) == 0) {
                            log_event("Motion detected. Image captured.");
                        } else {
                            log_event("Image capture failed.");
                        }
                    } else {
                        log_event("Failed to create filename.");
                    }
                }
                last_state = current_state;
            }
        }
        gpioDelay(50 * 1000); // Poll every 50 ms
    }

    gpioTerminate();
    log_event("Motion detector stopped.");
    closelog();
    return 0;
}

void signal_handler(int sig) {
    running = 0;
    log_event("Signal received. Stopping...");
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    return 0;
}

int capture_image(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s -w %d -h %d --iso 800 --quality 85", filename, IMAGE_WIDTH, IMAGE_HEIGHT);

    pid_t pid = fork();
    if (pid == 0) {
        // Child process
        execlp("sh", "sh", "-c", command, (char *)NULL);
        perror("execlp failed");
        exit(1);
    } else if (pid < 0) {
        perror("fork failed");
        return 1;
    } else {
        // Parent process
        int status;
        waitpid(pid, &status, 0);
        if (WIFEXITED(status)) {
            if (WEXITSTATUS(status) != 0) {
                log_event("libcamera-still exited with status");
                return 1;
            }
        } else {
            log_event("libcamera-still terminated abnormally");
            return 1;
        }
    }
}

int create_timestamped_filename(char *filename, size_t filename_size) {
    time_t rawtime;
    struct tm *timeinfo;
    struct timespec ts;

    clock_gettime(CLOCK_REALTIME, &ts);
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    if (strftime(filename, filename_size, IMAGE_DIR "%Y%m%d_%H%M%S.jpg", timeinfo) == 0) {
        log_event("Failed to format filename");
        return 1;
    }

    return 0;
}

int log_event(const char *message) {
    syslog(LOG_INFO, "%s", message);
    return 0;
}

