#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/select.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define PIXEL_FORMAT V4L2_PIX_FMT_GREY
#define MEMORY_TYPE V4L2_MEMORY_MMAP
#define NUM_BUFFERS 1

static int device_fd = -1;
static int buffer_index = 0;
static FILE *error_log = NULL;
static volatile sig_atomic_t keep_running = 1;

// Structure to hold camera configuration
typedef struct {
    int fd;
    void *buffer;
    size_t buffer_size;
} camera_config_t;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        fprintf(stderr, "\nSignal received, stopping...\n");
        keep_running = 0;
    }
}

// Function to log errors to a file
void log_error(const char *message) {
    if (error_log != NULL) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        fprintf(error_log, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
                t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
                t->tm_hour, t->tm_min, t->tm_sec, message);
        fflush(error_log);
    } else {
        fprintf(stderr, "Error log not initialized!\n");
    }
}

// Function to initialize the camera
int init_camera(camera_config_t *config) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    // Open the device
    config->fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (config->fd < 0) {
        log_error("Failed to open device");
        return -1;
    }

    // Check capabilities
    if (ioctl(config->fd, VIDIOC_QUERYCAP, &cap) < 0) {
        log_error("Failed to query capabilities");
        close(config->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        log_error("Device does not support video capture");
        close(config->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        log_error("Device does not support streaming");
        close(config->fd);
        return -1;
    }

    // Set the format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = PIXEL_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(config->fd, VIDIOC_S_FMT, &fmt) < 0) {
        log_error("Failed to set format");
        close(config->fd);
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = MEMORY_TYPE;

    if (ioctl(config->fd, VIDIOC_REQBUFS, &req) < 0) {
        log_error("Failed to request buffers");
        close(config->fd);
        return -1;
    }

    // Map the buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = MEMORY_TYPE;
    buf.index = 0;

    if (ioctl(config->fd, VIDIOC_QUERYBUF, &buf) < 0) {
        log_error("Failed to query buffer");
        close(config->fd);
        return -1;
    }

    config->buffer_size = buf.length;
    config->buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, config->fd, buf.m.offset);
    if (config->buffer == MAP_FAILED) {
        log_error("Failed to map buffer");
        close(config->fd);
        return -1;
    }

    // Queue the buffer
    if (ioctl(config->fd, VIDIOC_QBUF, &buf) < 0) {
        log_error("Failed to queue buffer");
        munmap(config->buffer, config->buffer_size);
        close(config->fd);
        return -1;
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(config->fd, VIDIOC_STREAMON, &type) < 0) {
        log_error("Failed to start streaming");
        munmap(config->buffer, config->buffer_size);
        close(config->fd);
        return -1;
    }

    return 0;
}

// Function to capture a frame
int capture_frame(camera_config_t *config, FILE *fp) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(config->fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(config->fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        log_error("select() failed");
        return -1;
    } else if (r == 0) {
        log_error("select() timeout");
        return -1;
    }

    // Dequeue the buffer
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = MEMORY_TYPE;
    buf.index = 0;

    if (ioctl(config->fd, VIDIOC_DQBUF, &buf) < 0) {
        log_error("Failed to dequeue buffer");
        return -1;
    }

    // Save the frame to a file
