// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        fprintf(stderr, "\nSignal received, stopping...\n");
        keep_running = 0;
    }
}

// Function to log errors to a file
void log_error(const char *message) {
    if (error_log != NULL) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        fprintf(error_log, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
                t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
                t->tm_hour, t->tm_min, t->tm_sec, message);
        fflush(error_log);
    } else {
        fprintf(stderr, "Error log not initialized!\n");
    }
}

// Function to initialize the camera
int init_camera(camera_config_t *config) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    // Open the device
    config->fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (config->fd < 0) {
        log_error("Failed to open device");
        return -1;
    }

    // Check capabilities
    if (ioctl(config->fd, VIDIOC_QUERYCAP, &cap) < 0) {
        log_error("Failed to query capabilities");
        close(config->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        log_error("Device does not support video capture");
        close(config->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        log_error("Device does not support streaming");
        close(config->fd);
        return -1;
    }

    // Set the format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = PIXEL_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(config->fd, VIDIOC_S_FMT, &fmt) < 0) {
        log_error("Failed to set format");
        close(config->fd);
        return -1;
    }

