    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = MEMORY_TYPE;

    if (ioctl(config->fd, VIDIOC_REQBUFS, &req) < 0) {
        log_error("Failed to request buffers");
        close(config->fd);
        return -1;
    }

