#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define FRAME_RATE 30
#define LOG_FILE "frame_log.txt"

// Structure to hold video capture parameters
typedef struct {
    int fd;
    void *buffer;
    size_t buffer_size;
    fd_set readfds;
} video_context_t;

// Function prototypes
int init_video_capture(video_context_t *ctx);
int start_capturing(video_context_t *ctx);
int stop_capturing(video_context_t *ctx);
int capture_frame(video_context_t *ctx);
void log_timestamp(const char *filename, struct timeval tv);
void cleanup(video_context_t *ctx);
void signal_handler(int sig);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

int main() {
    video_context_t ctx;

    // Initialize the video context
    if (init_video_capture(&ctx) != 0) {
        fprintf(stderr, "Failed to initialize video capture. Exiting.\n");
        return 1;
    }

    // Set up signal handling for graceful shutdown
    signal(SIGINT, signal_handler);

    // Start capturing frames
    if (start_capturing(&ctx) != 0) {
        fprintf(stderr, "Failed to start capturing. Exiting.\n");
        cleanup(&ctx);
        return 1;
    }

    printf("Capturing frames. Press Ctrl+C to stop.\n");

    // Main loop to capture and log frames
    while (program_running) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(ctx.fd, &readfds);

        struct timeval tv;
        int r = select(ctx.fd + 1, &readfds, NULL, NULL, NULL);

        if (r == -1) {
            perror("select");
            break;
        } else if (r == 0) {
            // Timeout occurred, no frame ready yet
            usleep(10000); // Sleep for 10ms
            continue;
        }

        if (FD_ISSET(ctx.fd, &readfds)) {
            if (capture_frame(&ctx) != 0) {
                fprintf(stderr, "Failed to capture frame. Continuing.\n");
            }
        }
    }

    // Stop capturing and cleanup
    printf("Stopping capturing and cleaning up.\n");
    stop_capturing(&ctx);
    cleanup(&ctx);

    printf("Exiting.\n");
    return 0;
}

// Initialize video capture
int init_video_capture(video_context_t *ctx) {
    int fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("open");
        return -1;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(fd);
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        close(fd);
        return -1;
    }

    struct v4l2_streamparm streamparm;
    memset(&streamparm, 0, sizeof(streamparm));
    streamparm.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    streamparm.parm.capture.timeperframe.numerator = 1;
    streamparm.parm.capture.timeperframe.denominator = FRAME_RATE;

    if (ioctl(fd, VIDIOC_S_PARM, &streamparm) == -1) {
        perror("VIDIOC_S_PARM");
        close(fd);
        return -1;
    }

    ctx->fd = fd;
    ctx->buffer_size = WIDTH * HEIGHT / 2; // Approximate buffer size
    ctx->buffer = mmap(NULL, ctx->buffer_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (ctx->buffer == MAP_FAILED) {
        perror("mmap");
        close(fd);
        return -1;
    }

    return 0;
}

// Start capturing frames
int start_capturing(video_context_t *ctx) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer for simplicity
    req.type = type;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(ctx->fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        return -1;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = type;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(ctx->fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("VIDIOC_QUERYBUF");
        return -1;
    }

    if (ioctl(ctx->fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF");
        return -1;
    }

    enum v4l2_eo_pad_cap eopc = V4L2_EOPAD_CAP_LINE;
    if (ioctl(ctx->fd, VIDIOC_EXT_CTRL, &eopc) == -1) {
        perror("VIDIOC_EXT_CTRL");
        return -1;
    }

    if (ioctl(ctx->fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        return -1;
    }

    return 0;
}

// Stop capturing frames
int stop_capturing(video_context_t *ctx) {
    if (ioctl(ctx->fd, VIDIOC_STREAMOFF, &V4L2_BUF_TYPE_VIDEO_CAPTURE) == -1) {
        perror("VIDIOC_STREAMOFF");
        return -1;
    }
    return 0;
}

// Capture a single frame
int capture_frame(video_context_t *ctx) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(ctx->fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    // Log the timestamp
    log_timestamp(LOG_FILE, buf.bytesused);

    if (ioctl(ctx->fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF");
        return -1;
    }

    return 0;
}

// Log the timestamp to a file
void log_timestamp(const char *filename, struct timeval tv) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("fopen");
        return;
    }

    fprintf(fp, "%ld.%ld\n", tv.tv_sec, tv.tv_usec);
    fclose(fp);
}

// Cleanup resources
void cleanup(video_context_t *ctx) {
    if (ctx->fd != -1) {
        if (ioctl(ctx->fd, VIDIOC_STREAMOFF, &V4L2_BUF_TYPE_VIDEO_CAPTURE) == -1) {
            perror("VIDIOC_STREAMOFF");
        }
        munmap(ctx->buffer, ctx->buffer_size);
        close(ctx->fd);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    program_running = 0;
}

