#define UDP_PORT 8000
#define BUFFER_COUNT 4

// Structure to hold camera buffer information
struct buffer {
    void   *start;
    size_t  length;
};

// Global variables (try to minimize)
static int                    fd                    = -1;
static struct buffer           *buffers               = NULL;
static unsigned int            n_buffers             = 0;
static volatile sig_atomic_t  running               = 1;
static int                    sockfd                = -1;
static struct sockaddr_in      dest_addr             = {0};

// Function prototypes
int init_camera(void);
int start_streaming(void);
int stop_streaming(void);
int capture_frame(unsigned char **frame_data);
int send_udp_packet(unsigned char *frame_data, int frame_index, int fragment_index, int total_fragments, int payload_size);
void signal_handler(int sig);
int init_socket(const char *server_ip, int server_port);
void cleanup(void);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    running = 0;
    fprintf(stderr, "\nCaught signal %d, stopping...\n", sig);
}

// Initialize the camera
int init_camera(void) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;

    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }

    // Check capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        close(fd);
        return -1;
    }

