        perror("Error dequeuing buffer");
        return -1;
    }

    *frame_data = buffers[buf.index].start;
    return 0;
}

// Send UDP packet
int send_udp_packet(unsigned char *frame_data, int frame_index, int fragment_index, int total_fragments, int payload_size) {
    unsigned char header[16];
    struct sockaddr_in dest_addr = dest_addr; // Use the global dest_addr

    // Create header
    header[0] = (frame_index >> 8) & 0xFF;
    header[1] = frame_index & 0xFF;
    header[2] = (fragment_index >> 8) & 0xFF;
    header[3] = fragment_index & 0xFF;
    header[4] = (total_fragments >> 8) & 0xFF;
    header[5] = total_fragments & 0xFF;
    header[6] = (payload_size >> 8) & 0xFF;
    header[7] = payload_size & 0xFF;

    // Calculate payload size
    int data_size = payload_size - sizeof(header);

    // Copy frame data to payload
    memcpy(frame_data + sizeof(header), frame_data, data_size);

    // Send data
    ssize_t bytes_sent = sendto(sockfd, frame_data, sizeof(header) + data_size, 0, (struct sockaddr *)&dest_addr, sizeof(dest_addr));
    if (bytes_sent < 0) {
        perror("Error sending UDP packet");
        return -1;
    }

    return 0;
}

