                break;
            }

            total_fragments++;
            payload_size -= UDP_MAX_PACKET_SIZE;
            fragment_index++;
        }

        if (payload_size > 0) {
            fprintf(stderr, "Frame too large for UDP packet\n");
            break;
        }

        frame_index++;
        fragment_index = 0;

        // Dequeue buffer
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
