    fp = fopen(IMAGE_FILENAME, "wb");
    if (fp == NULL) {
        perror("Error opening file");
        close(fd);
        return EXIT_FAILURE;
    }

    bytes_written = fwrite(buffers[buf.index], 1, buf.bytesused, fp);
    if (bytes_written != (size_t)buf.bytesused) {
        fprintf(stderr, "Error writing to file: wrote %zd bytes, expected %zu\n", bytes_written, buf.bytesused);
        fclose(fp);
        close(fd);
        return EXIT_FAILURE;
    }

    fclose(fp);

    // Stop streaming
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        close(fd);
        return EXIT_FAILURE;
    }

