    for (int i = 0; i < NUM_BUFFERS; ++i) {
        if (munmap(buffers[i], buf.length) < 0) {
            perror("Error unmapping buffer");
            close(fd);
            return EXIT_FAILURE;
        }
    }

    // Free buffer array
    free(buffers);

    // Close device
    if (close(fd) < 0) {
        perror("Error closing device");
        return EXIT_FAILURE;
    }

    printf("Image saved to %s\n", IMAGE_FILENAME);
    return EXIT_SUCCESS;
