#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

// Define servo limits
#define MIN_PULSE_WIDTH 1000
#define MAX_PULSE_WIDTH 2000

// Define PWM frequency and range
#define PWM_FREQUENCY 50 // Hz
#define PWM_RANGE 1000

// Global variables for servo positions
int pan_position = 75;
int tilt_position = 75;

// Function prototypes
int initialize_gpio();
void set_servo_position(int gpio_pin, int position);
int read_button(int gpio_pin);
void handle_button_press(int gpio_pin, int position);
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Cleaning up and exiting.\n");
        cleanup_gpio();
        exit(0);
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO modes
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(UP_BUTTON_PIN, PI_INPUT);
    gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT);

    // Enable pull-up resistors
    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);

    return 0; // Indicate success
}

// Set servo position using PWM
void set_servo_position(int gpio_pin, int position) {
    // Calculate pulse width based on position
    int pulse_width = MIN_PULSE_WIDTH + (int)(((float)position / 100.0) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));

    // Set PWM duty cycle
    gpioPWM(gpio_pin, pulse_width);
}

// Read button state
int read_button(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Handle button press
void handle_button_press(int gpio_pin, int position) {
    if (gpio_pin == UP_BUTTON_PIN) {
        tilt_position += 5;
        if (tilt_position > 125) {
            tilt_position = 125;
        }
    } else if (gpio_pin == DOWN_BUTTON_PIN) {
        tilt_position -= 5;
        if (tilt_position < 25) {
            tilt_position = 25;
        }
    } else if (gpio_pin == LEFT_BUTTON_PIN) {
        pan_position -= 5;
        if (pan_position < 25) {
            pan_position = 25;
        }
    } else if (gpio_pin == RIGHT_BUTTON_PIN) {
        pan_position += 5;
        if (pan_position > 125) {
            pan_position = 125;
        }
    }

    // Clamp positions to [25, 125]
    if (pan_position < 25) {
        pan_position = 25;
    } else if (pan_position > 125) {
        pan_position = 125;
    }

    if (tilt_position < 25) {
        tilt_position = 25;
    } else if (tilt_position > 125) {
        tilt_position = 125;
    }

    set_servo_position(TILT_SERVO_PIN, tilt_position);
    set_servo_position(PAN_SERVO_PIN, pan_position);
}

// Cleanup GPIO resources
void cleanup_gpio() {
    // Stop PWM signals
    gpioPWM(PAN_SERVO_PIN, 0);
    gpioPWM(TILT_SERVO_PIN, 0);

    // Release GPIO pins
    gpioSetMode(PAN_SERVO_PIN, PI_INPUT); // Set to input to release
    gpioSetMode(TILT_SERVO_PIN, PI_INPUT);
    gpioSetMode(UP_BUTTON_PIN, PI_INPUT);
    gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT);

    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Set initial servo positions
    set_servo_position(PAN_SERVO_PIN, pan_position);
    set_servo_position(TILT_SERVO_PIN, tilt_position);

    // Main loop
    while (1) {
        // Read button states
        int up_pressed = read_button(UP_BUTTON_PIN);
        int down_pressed = read_button(DOWN_BUTTON_PIN);
        int left_pressed = read_button(LEFT_BUTTON_PIN);
        int right_pressed = read_button(RIGHT_BUTTON_PIN);

        // Handle button presses
        if (up_pressed) {
            handle_button_press(UP_BUTTON_PIN, tilt_position);
        }
        if (down_pressed) {
            handle_button_press(DOWN_BUTTON_PIN, tilt_position);
        }
        if (left_pressed) {
            handle_button_press(LEFT_BUTTON_PIN, pan_position);
        }
        if (right_pressed) {
            handle_button_press(RIGHT_BUTTON_PIN, pan_position);
        }

        // Delay for 50 ms
        gpioDelay(50000); // 50 ms = 50000 microseconds
    }

    return 0;
}

