    struct v4l2_buffer buf;
} camera_params_t;

// Global variables for signal handling
volatile sig_atomic_t keep_running = 1;
camera_params_t camera1_params, camera2_params;

// Function prototypes
int init_camera(camera_params_t *params);
int capture_frame(camera_params_t *params, unsigned char **frame);
void apply_box_blur(unsigned char *frame, int width, int height, int radius, unsigned char *output_frame);
