        return -1;
    }
    return fd;
}

// Function to query camera capabilities
int query_capabilities(int fd, camera_capabilities_t *capabilities) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities\n");
        return -1;
    }

    strncpy(capabilities->description, cap.driver, sizeof(cap.driver) - 1);
    capabilities->driver[sizeof(cap.driver) - 1] = '\0';
    capabilities->description += sizeof(cap.driver);
    strncpy(capabilities->description, cap.card, sizeof(cap.card) - 1);
    capabilities->card[sizeof(cap.card) - 1] = '\0';
    capabilities->description += sizeof(cap.card);
    strncpy(capabilities->description, cap.bus_info, sizeof(cap.bus_info) - 1);
    capabilities->bus_info[sizeof(cap.bus_info) - 1] = '\0';
    capabilities->description += sizeof(cap.bus_info);

    capabilities->width = 640; // Default width
    capabilities->height = 480; // Default height
    capabilities->frame_rate = 30; // Default frame rate
    capabilities->focus_auto = 0; // Default focus auto

    return 0;
}

// Function to enumerate frame sizes
int enumerate_frame_sizes(int fd, int *num_sizes, struct v4l2_frmsizeenum *sizes) {
