int enumerate_frame_intervals(int fd, int *num_intervals, struct v4l2_frmi2lenum *intervals) {
    if (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, intervals) < 0) {
        fprintf(stderr, "Error enumerating frame intervals\n");
        return -1;
    }
    *num_intervals = intervals->count;
    return 0;
}

