    focus_auto.id = V4L2_CID_FOCUS_AUTO;

    if (ioctl(fd, VIDIOC_QUERYCTRL, &focus_auto) < 0) {
        fprintf(stderr, "Error querying focus auto control\n");
        return -1;
    }

    if (focus_auto.value == 0) {
        return 0; // Not supported
    } else {
        return 1; // Supported
    }
}

