        handle_error("Failed to open device");
    }

    // Query capabilities
    if (query_capabilities(fd, &capabilities) < 0) {
        close(fd);
        handle_error("Failed to query capabilities");
    }

    // Enumerate frame sizes
    if (enumerate_frame_sizes(fd, &num_frame_sizes, frame_sizes) < 0) {
        close(fd);
        handle_error("Failed to enumerate frame sizes");
    }

    // Enumerate frame intervals
    if (enumerate_frame_intervals(fd, &num_frame_intervals, frame_intervals) < 0) {
        close(fd);
        handle_error("Failed to enumerate frame intervals");
    }

    // Check autofocus support
    capabilities.focus_auto = check_autofocus_support(fd);

    // Print capabilities
    print_capabilities(&capabilities);

    // Close the device
    close(fd);

