#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define servo and button pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

// Define servo pulse width range
#define MIN_PULSE_WIDTH 1000
#define MAX_PULSE_WIDTH 2000

// Define loop delay in milliseconds
#define LOOP_DELAY 50

// Global variables for servo positions
int pan_position = 1500;
int tilt_position = 1500;

// Function prototypes
void signal_handler(int signal);
void move_servo(int servo_pin, int direction, int increment);
void button_callback(int gpio, int level, uint32_t tick);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    // Stop PWM on servo pins
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    // Terminate pigpio
    gpioTerminate();
    exit(0);
}

// Function to move a servo
void move_servo(int servo_pin, int direction, int increment) {
    int current_position = gpioServo(servo_pin, 0); // Read current position
    if (current_position < 0) {
        fprintf(stderr, "Error reading servo position for pin %d\n", servo_pin);
        return;
    }

    int new_position = current_position + direction * increment;

    // Clamp the position to the valid range
    if (new_position < MIN_PULSE_WIDTH) {
        new_position = MIN_PULSE_WIDTH;
    } else if (new_position > MAX_PULSE_WIDTH) {
        new_position = MAX_PULSE_WIDTH;
    }

    if (gpioServo(servo_pin, new_position) != 0) {
        fprintf(stderr, "Error setting servo position for pin %d to %d\n", servo_pin, new_position);
    }
}

// Callback function for button presses
void button_callback(int gpio, int level, uint32_t tick) {
    // Check which button was pressed
    if (gpio == UP_BUTTON_PIN && level == 0) {
        move_servo(PAN_SERVO_PIN, 1, 10); // Move pan servo up
    } else if (gpio == DOWN_BUTTON_PIN && level == 0) {
        move_servo(PAN_SERVO_PIN, -1, 10); // Move pan servo down
    } else if (gpio == LEFT_BUTTON_PIN && level == 0) {
        move_servo(TILT_SERVO_PIN, 1, 10); // Move tilt servo left
    } else if (gpio == RIGHT_BUTTON_PIN && level == 0) {
        move_servo(TILT_SERVO_PIN, -1, 10); // Move tilt servo right
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Print startup message
    printf("Pan-Tilt Camera Control\n");
    printf("Pan Servo: GPIO%d\n", PAN_SERVO_PIN);
    printf("Tilt Servo: GPIO%d\n", TILT_SERVO_PIN);
    printf("UP Button: GPIO%d\n", UP_BUTTON_PIN);
    printf("DOWN Button: GPIO%d\n", DOWN_BUTTON_PIN);
    printf("LEFT Button: GPIO%d\n", LEFT_BUTTON_PIN);
    printf("RIGHT Button: GPIO%d\n", RIGHT_BUTTON_PIN);
    printf("Center Position: Pan=%d us, Tilt=%d us\n", pan_position, tilt_position);

    // Set servo pins as outputs
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);

    // Set button pins as inputs with pull-up resistors
    gpioSetMode(UP_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);

    // Set up signal handlers for Ctrl+C and termination signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt handlers for button presses
    gpioSetAlertFuncEx(UP_BUTTON_PIN, button_callback, NULL);
    gpioSetAlertFuncEx(DOWN_BUTTON_PIN, button_callback, NULL);
    gpioSetAlertFuncEx(LEFT_BUTTON_PIN, button_callback, NULL);
    gpioSetAlertFuncEx(RIGHT_BUTTON_PIN, button_callback, NULL);

    // Main loop
    while (1) {
        gpioDelay(LOOP_DELAY * 1000); // Delay for 50 ms
    }

    return 0;
}

