#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <curl/curl.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 2000
#define POLL_INTERVAL_MS 100
#define JPEG_QUALITY 85
#define CAPTURE_WIDTH 640
#define CAPTURE_HEIGHT 480

// Global variables
static volatile int running = 1;
static char *server_ip = NULL;
static int server_port = 0;
static char *image_dir = NULL;
static CURL *curl = NULL;
static size_t total_size = 0;
static char *image_filename = NULL;

// Structure to hold the JSON payload
typedef struct {
    char filename[256];
    char timestamp[32];
    char motion_status[16];
    int gpio_pin;
} json_payload_t;

// Function prototypes
int init_gpio();
int init_curl();
int init_image_dir();
int capture_image(char *filename);
int send_data(const char *filename, const char *timestamp, int motion_status, int gpio_pin);
void cleanup();
void signal_handler(int signal);
char* get_iso8601_timestamp(char* buffer, size_t buf_size);

// Signal handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    return 0;
}

// Initialize curl
int init_curl() {
    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "libcurl initialization failed\n");
        return -1;
    }
    return 0;
}

// Initialize image directory
int init_image_dir() {
    if (mkdir(image_dir, 0777) == -1 && errno != EEXIST) {
        fprintf(stderr, "Failed to create image directory: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Capture image using libcamera-still
int capture_image(char *filename) {
    char command[512];
    snprintf(command, sizeof(command), "libcamera-still -o %s -w %d -h %d --quality %d", filename, CAPTURE_WIDTH, CAPTURE_HEIGHT, JPEG_QUALITY);
    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error executing libcamera-still command\n");
        return -1;
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "libcamera-still command failed with status %d\n", WEXITSTATUS(status));
        return -1;
    }
    return 0;
}

// Send data to server
int send_data(const char *filename, const char *timestamp, int motion_status, int gpio_pin) {
    json_payload_t payload;
    strncpy(payload.filename, filename, sizeof(payload.filename) - 1);
    payload.filename[sizeof(payload.filename) - 1] = '\0'; // Ensure null termination
    strncpy(payload.timestamp, timestamp, sizeof(payload.timestamp) - 1);
    payload.timestamp[sizeof(payload.timestamp) - 1] = '\0'; // Ensure null termination
    payload.motion_status[0] = motion_status ? '1' : '0';
    payload.gpio_pin = gpio_pin;

    char json_string[2048];
    snprintf(json_string, sizeof(json_string), "{\"filename\":\"%s\",\"timestamp\":\"%s\",\"motion_status\":\"%s\",\"gpio_pin\":%d}",
             payload.filename, payload.timestamp, payload.motion_status, payload.gpio_pin);

    curl_easy_setopt(curl, CURLOPT_URL, "http://localhost:8080/upload"); // Replace with actual server URL
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_string);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_string));

    CURLcode res = curl_easy_perform();
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        return -1;
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (curl) {
        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
    gpioTerminate();
    if (image_dir) {
        rmdir(image_dir);
    }
    if (server_ip) free(server_ip);
    if (image_filename) free(image_filename);
}

// Get ISO 8601 timestamp with microseconds
char* get_iso8601_timestamp(char* buffer, size_t buf_size) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    strftime(buffer, buf_size, "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(buffer + strlen(buffer), buf_size - strlen(buffer), ".%06ldZ", ts.tv_nsec / 1000);
    return buffer;
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port> <image_directory>\n", argv[0]);
        return 1;
    }

    server_ip = strdup(argv[1]);
    server_port = atoi(argv[2]);
    image_dir = strdup(argv[3]);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    if (init_curl() != 0) {
        cleanup();
        return 1;
    }

    if (init_image_dir() != 0) {
        cleanup();
        return 1;
    }

    int motion_detected = 0;
    time_t last_motion_time = 0;

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_state = gpioRead(GPIO_PIN);

        if (current_state == 1 && !motion_detected) {
            time_t now = time(NULL);
            if (difftime(now, last_motion_time) * 1000 >= DEBOUNCE_DELAY_MS) {
                printf("Motion detected!\n");
                motion_detected = 1;
                last_motion_time = now;

                // Capture image
                image_filename = strdup(image_dir);
                snprintf(image_filename, strlen(image_dir) + 15, "%s/motion_%ld.jpg", image_dir, time(NULL));
                if (capture_image(image_filename) == 0) {
                    printf("Image captured: %s\n", image_filename);

                    // Send data
