#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

// Configuration
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x48 // Example address for BH1750
#define SERVER_IP "127.0.0.1" // Loopback for testing
#define SERVER_PORT 12345
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"
#define DEBOUNCE_DELAY_MS 50
#define CAPTURE_WIDTH 640
#define CAPTURE_HEIGHT 480
#define QUALITY 85
#define TIMEOUT 2000
#define NO_PREVIEW

// Global variables
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(const char *chip, int pin);
int init_i2c(const char *bus, int address);
int read_light_level(int i2c_fd);
int capture_image(const char *filename);
int send_data(const char *filename, int light_level);
int log_event(const char *message);
void signal_handler(int sig);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    log_event("Received signal, cleaning up...");
}

// Cleanup function
void cleanup() {
    log_event("Cleaning up resources...");

    // Release GPIO resources
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    // Close I2C file descriptor
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    log_event("Cleanup complete.");
}

// Initialize GPIO
int init_gpio(const char *chip, int pin) {
    gpio_chip = gpiod_chip_open_by_name(chip);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, pin);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_input(gpio_line, "motion_sensor") < 0) {
        perror("Error requesting GPIO line as input");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Initialize I2C
int init_i2c(const char *bus, int address) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read light level from BH1750
int read_light_level(int i2c_fd) {
    unsigned char config[1] = {0x10}; // Continuous high resolution mode
    if (write(i2c_fd, config, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    usleep(200000); // Wait for measurement (at least 180ms)

    unsigned char buffer[2];
    if (read(i2c_fd, buffer, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    unsigned int lux = (buffer[0] << 8) | buffer[1];
    return lux;
}

// Capture image using libcamera-still
int capture_image(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s --width %d --height %d -q %d --timeout %d --nopreview", filename, CAPTURE_WIDTH, CAPTURE_HEIGHT, QUALITY, TIMEOUT);

    int status = system(command);
    if (status == -1) {
        perror("Error executing libcamera-still");
        return -1;
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "libcamera-still exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }

    return 0;
}

// Send data to server
int send_data(const char *filename, int light_level) {
    int sockfd;
    struct sockaddr_in serv_addr;
    char message[256];

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Error creating socket");
        return -1;
    }

    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(SERVER_PORT);

    if (inet_pton(AF_INET, SERVER_IP, &serv_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("Error connecting to server");
        close(sockfd);
        return -1;
    }

    snprintf(message, sizeof(message), "%s,%d", filename, light_level);
    if (send(sockfd, message, strlen(message), 0) < 0) {
        perror("Error sending data");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

// Log event to file
int log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return 1;
    }

    log_event("Starting motion capture system...");

    // Initialize GPIO
    if (init_gpio(GPIO_CHIP, GPIO_PIN) < 0) {
        log_event("GPIO initialization failed, exiting...");
        cleanup();
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        log_event("I2C initialization failed, exiting...");
        cleanup();
        return 1;
    }

    // Create image directory if it doesn't exist
    struct stat st = {0};
    if (stat(IMAGE_DIR, &st) == -1) {
        if (mkdir(IMAGE_DIR, 0777) != 0) {
            perror("Error creating image directory");
            log_event("Error creating image directory, exiting...");
            cleanup();
            return 1;
        }
        log_event("Created image directory.");
    }

    // Main loop
    while (!terminate) {
        // Read GPIO state
        int level = gpiod_line_get_value(gpio_line);
        if (level < 0) {
            perror("Error reading GPIO value");
            log_event("Error reading GPIO value, exiting...");
            break;
        }

        // Motion detected
        if (level == 0) {
            log_event("Motion detected!");

            // Generate filename
            time_t t = time(NULL);
            struct tm tm = *localtime(&t);
            char filename[64];
            strftime(filename, sizeof(filename), IMAGE_DIR "/%Y%m%d_%H%M%S_%03d.jpg", &tm);

            // Capture image
            if (capture_image(filename) < 0) {
                log_event("Image capture failed.");
            } else {
                log_event("Image captured.");
            }

            // Read light level
            int light_level = read_light_level(i2c_fd);
            if (light_level < 0) {
                log_event("Failed to read light level.");
            } else {
                log_event("Light level: " + light_level);
            }

            // Send data to server
            if (send_data(filename, light_level) < 0) {
                log_event("Failed to send data to server.");
            } else {
                log_event("Data sent to server.");
            }

            // Debounce delay
            usleep(DEBOUNCE_DELAY_MS * 1000);
        }

        // Small delay to avoid busy-waiting
        usleep(10000); // 10ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

