    params->fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (params->fd < 0) {
        perror("Error opening device");
        return -1;
    }

    // Query capabilities
    if (ioctl(params->fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(params->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        close(params->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        close(params->fd);
        return -1;
    }

    // Set the format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = PIX_FMT;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(params->fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(params->fd);
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(params->fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(params->fd);
        return -1;
    }

    // Allocate memory for the buffer
    params->buffer_count = req.count;
    params->buffer = mmap(NULL, req.length, PROT_READ | PROT_WRITE, MAP_SHARED, params->fd, 0);
    if (params->buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(params->fd);
        return -1;
    }

    // Configure the first buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(params->fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        munmap(params->buffer, req.length);
        close(params->fd);
        return -1;
    }

