    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(params->fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        munmap(params->buffer, req.length);
        close(params->fd);
        return -1;
    }

    return 0;
