int capture_frame(camera_params_t *params, unsigned char *frame_buffer, int frame_size) {
    struct v4l2_buffer buf;
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(params->fd, &fds);

    tv.tv_sec = SELECT_TIMEOUT;
    tv.tv_usec = 0;

    r = select(params->fd + 1, &fds, NULL, NULL, &tv);

    if (r < 0) {
        perror("select() error");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "select timeout\n");
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(params->fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    memcpy(frame_buffer, params->buffer, buf.bytesused);

    if (ioctl(params->fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    return buf.bytesused;
}

