int crop_frame(unsigned char *frame, int width, int height, int x, int y, int crop_width, int crop_height, unsigned char *cropped_frame) {
    if (width == crop_width && height == crop_height) {
        memcpy(cropped_frame, frame, width * height * 2);
        return 0;
    }

    int i, j;
    for (i = 0; i < crop_height; i++) {
        for (j = 0; j < crop_width; j++) {
            int pixel_index = (i * width + j) * 2;
            int source_pixel_index = (y + i) * width + x + j;
            if (source_pixel_index >= 0 && source_pixel_index < width * height * 2) {
                cropped_frame[i * crop_width * 2 + j * 2] = frame[source_pixel_index * 2];
                cropped_frame[i * crop_width * 2 + j * 2 + 1] = frame[source_pixel_index * 2 + 1];
