                cropped_frame[i * crop_width * 2 + j * 2 + 1] = 0;
            }
        }
    }
    return 0;
}

// Function to save the cropped frame to a file
int save_frame(unsigned char *frame, int width, int height, const char *filename) {
    output_file = fopen(filename, "wb");
    if (output_file == NULL) {
        perror("Error opening output file");
        return -1;
    }

    size_t bytes_written = fwrite(frame, 1, width * height * 2, output_file);
    if (bytes_written != width * height * 2) {
        perror("Error writing to output file");
        fclose(output_file);
        return -1;
    }

