    return 0;
}

// Function to cleanup resources
void cleanup(camera_params_t *params) {
    if (params->fd != -1) {
        if (ioctl(params->fd, VIDIOC_STREAMOFF, V4L2_BUF_TYPE_VIDEO_CAPTURE) < 0) {
            perror("Error stopping stream");
        }
        munmap(params->buffer, params->buffer_count * v4l2_get_buffer_size(WIDTH, HEIGHT, PIX_FMT));
        close(params->fd);
    }
}

int main() {
    camera_params_t camera_params;
    unsigned char *frame_buffer = NULL;
    unsigned char *cropped_frame = NULL;
    int frame_size;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the camera
    if (init_camera(&camera_params) < 0) {
        fprintf(stderr, "Camera initialization failed\n");
        return EXIT_FAILURE;
    }

    // Allocate memory for the frame buffer
    frame_size = WIDTH * HEIGHT * 2;
    frame_buffer = (unsigned char *)malloc(frame_size);
    if (frame_buffer == NULL) {
        perror("Error allocating memory for frame buffer");
        cleanup(&camera_params);
        return EXIT_FAILURE;
    }

    // Allocate memory for the cropped frame
    int crop_width = 200;
    int crop_height = 150;
    cropped_frame = (unsigned char *)malloc(crop_width * crop_height * 2);
    if (cropped_frame == NULL) {
        perror("Error allocating memory for cropped frame");
        free(frame_buffer);
        cleanup(&camera_params);
        return EXIT_FAILURE;
    }

    // Capture a frame
    if (capture_frame(&camera_params, frame_buffer, frame_size) < 0) {
        fprintf(stderr, "Frame capture failed\n");
        free(frame_buffer);
        free(cropped_frame);
        cleanup(&camera_params);
        return EXIT_FAILURE;
    }

    // Crop the frame
    if (crop_frame(frame_buffer, WIDTH, HEIGHT, 100, 50, crop_width, crop_height, cropped_frame) < 0) {
        fprintf(stderr, "Frame cropping failed\n");
        free(frame_buffer);
        free(cropped_frame);
        cleanup(&camera_params);
        return EXIT_FAILURE;
    }

    // Save the cropped frame
    if (save_frame(cropped_frame, crop_width, crop_height, "cropped.yuv") < 0) {
        fprintf(stderr, "Frame saving failed\n");
        free(frame_buffer);
        free(cropped_frame);
        cleanup(&camera_params);
        return EXIT_FAILURE;
    }

    // Cleanup resources
    free(frame_buffer);
    free(cropped_frame);
    cleanup(&camera_params);

    printf("Frame captured, cropped, and saved successfully.\n");

    return EXIT_SUCCESS;
}

