#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for pan and tilt servos
#define PAN_GPIO 17
#define TILT_GPIO 18

// Define PWM frequency and range
#define PWM_FREQUENCY 50
#define PWM_RANGE 1000

// Define angle increment
#define ANGLE_INCREMENT 5

// Define neutral angle
#define NEUTRAL_ANGLE 90

// Global variables for servo angles
int pan_angle = NEUTRAL_ANGLE;
int tilt_angle = NEUTRAL_ANGLE;

// Function prototypes
int set_pan_angle(int angle);
int set_tilt_angle(int angle);
int validate_angle(int angle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Setting servos to neutral and exiting.\n");
        set_pan_angle(NEUTRAL_ANGLE);
        set_tilt_angle(NEUTRAL_ANGLE);
        gpioTerminate();
        exit(0);
    }
}

// Function to set the pan angle
int set_pan_angle(int angle) {
    if (validate_angle(angle) != 0) {
        fprintf(stderr, "Error: Invalid pan angle. Angle must be between 0 and 180.\n");
        return -1;
    }

    // Calculate pulse width based on angle
    int pulse_width = (int)(((float)angle / 180.0) * PWM_RANGE);

    // Set PWM duty cycle
    gpioPWM(PAN_GPIO, pulse_width);

    return 0;
}

// Function to set the tilt angle
int set_tilt_angle(int angle) {
    if (validate_angle(angle) != 0) {
        fprintf(stderr, "Error: Invalid tilt angle. Angle must be between 0 and 180.\n");
        return -1;
    }

    // Calculate pulse width based on angle
    int pulse_width = (int)(((float)angle / 180.0) * PWM_RANGE);

    // Set PWM duty cycle
    gpioPWM(TILT_GPIO, pulse_width);

    return 0;
}

// Function to validate the angle
int validate_angle(int angle) {
    if (angle < 0 || angle > 180) {
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for pan and tilt servos
    gpioSetMode(PAN_GPIO, PI_OUTPUT);
    gpioSetMode(TILT_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_GPIO, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PAN_GPIO, PWM_RANGE);
    gpioSetPWMrange(TILT_GPIO, PWM_RANGE);

    // Set initial angles
    set_pan_angle(NEUTRAL_ANGLE);
    set_tilt_angle(NEUTRAL_ANGLE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    char input;
    while (1) {
        // Read user input
        input = getchar();

        // Check for 'q' input to exit
        if (input == 'q') {
            set_pan_angle(NEUTRAL_ANGLE);
            set_tilt_angle(NEUTRAL_ANGLE);
            gpioTerminate();
            return 0;
        }

        // Handle arrow key input
        switch (input) {
            case 'w':
                pan_angle += ANGLE_INCREMENT;
                if (set_pan_angle(pan_angle) != 0) {
                    fprintf(stderr, "Error setting pan angle.\n");
                }
                break;
            case 's':
                pan_angle -= ANGLE_INCREMENT;
                if (set_pan_angle(pan_angle) != 0) {
                    fprintf(stderr, "Error setting pan angle.\n");
                }
                break;
            case 'a':
                tilt_angle += ANGLE_INCREMENT;
                if (set_tilt_angle(tilt_angle) != 0) {
                    fprintf(stderr, "Error setting tilt angle.\n");
                }
                break;
            case 'd':
                tilt_angle -= ANGLE_INCREMENT;
                if (set_tilt_angle(tilt_angle) != 0) {
                    fprintf(stderr, "Error setting tilt angle.\n");
                }
                break;
            default:
                // Ignore other input
                break;
        }

        // Delay to prevent excessive CPU usage
        usleep(100000); // 100 ms
    }

    // This point should not be reached due to the signal handler
    return 0;
}

