// Function to read CPU temperature from file
float read_cpu_temp() {
    FILE *fp;
    char buffer[10];
    float temp;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open temperature file.\n");
        return -1.0;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fprintf(stderr, "Error: Could not read temperature from file.\n");
        fclose(fp);
        return -1.0;
    }

    fclose(fp);
    temp = atoi(buffer) / 1000.0;
    return temp;
}

// Function to read CPU usage from /proc/stat
float read_cpu_usage() {
    FILE *fp;
    char buffer[128];
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    float usage;

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open /proc/stat file.\n");
        return -1.0;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fprintf(stderr, "Error: Could not read /proc/stat file.\n");
        fclose(fp);
        return -1.0;
    }

    fclose(fp);

    if (sscanf(buffer, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &prev_user, &prev_nice, &prev_system, &prev_idle, &prev_iowait, &prev_irq, &prev_softirq, &prev_steal, &prev_guest, &prev_guest_nice) != 10) {
        fprintf(stderr, "Error: Could not parse /proc/stat file.\n");
        return -1.0;
    }

    sleep(1);

    if (sscanf(buffer, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error: Could not parse /proc/stat file.\n");
        return -1.0;
    }

    unsigned long long prev_total = prev_user + prev_nice + prev_system + prev_idle + prev_iowait;
    unsigned long long total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;

    usage = (float)(total - prev_total) / (float)prev_total * 100.0;
    return usage;
}

// Function to initialize the OLED display
void oled_init() {
    // Initialization sequence (SSD1306 datasheet)
    unsigned char init_commands[] = {
        0xAE,       // Display off
        0xD5, 0x80, // Clock divide ratio/oscillator frequency
        0xA8, 0x3F, // Multiplex ratio
        0xD3, 0x00, // Display offset
        0x40,       // Start line
        0x8D, 0x14, // Charge pump setting
        0x20, 0x00, // Memory addressing mode
        0xA1,       // Segment remap
        0xC8,       // COM output scan direction
        0xDA, 0x12, // COM pins hardware configuration
        0x81, 0xCF, // Contrast control
        0xD9, 0xF1, // Pre-charge period
        0xDB, 0x40, // VCOM deselect level
        0xA4,       // Entire display ON/OFF
        0xA6,       // Normal/Inverse display
        0xAF        // Display on
    };

    for (int i = 0; i < sizeof(init_commands); i++) {
        if (i2cWriteByteData(i2c_handle, 0x00, init_commands[i]) < 0) {
            fprintf(stderr, "Error: I2C write failed during initialization.\n");
            terminate = 1;
            return;
        }
        gpioDelay(100); // Delay for initialization
    }
}

// Function to clear the OLED display
void oled_clear() {
    for (int i = 0; i < OLED_WIDTH * OLED_HEIGHT / 8; i++) {
        if (i2cWriteByteData(i2c_handle, 0x40, 0x00) < 0) {
            fprintf(stderr, "Error: I2C write failed during clear.\n");
            terminate = 1;
            return;
        }
    }
}

// Function to draw a character to the OLED display
void oled_draw_char(int x, int y, char c) {
    if (c < 32 || c > 126) {
        c = 0; // Use space for out-of-range characters
    }
    c -= 32; // Adjust index to font array

    for (int i = 0; i < 5; i++) {
        unsigned char byte = font[c][i];
        for (int j = 0; j < 8; j++) {
            if ((byte >> j) & 0x01) {
                // Set pixel (x + j, y + i)
                if (i2cWriteByteData(i2c_handle, 0x40, 0x01) < 0) {
                    fprintf(stderr, "Error: I2C write failed during char draw.\n");
                    terminate = 1;
                    return;
                }
            } else {
                // Clear pixel (x + j, y + i)
                if (i2cWriteByteData(i2c_handle, 0x40, 0x00) < 0) {
                    fprintf(stderr, "Error: I2C write failed during char draw.\n");
                    terminate = 1;
                    return;
                }
            }
        }
    }
}

// Function to draw a string to the OLED display
void oled_draw_string(int x, int y, const char *str) {
    while (*str) {
        oled_draw_char(x, y, *str);
        x += 6; // Character width + 1 pixel spacing
        str++;
    }
}

// Function to update the OLED display with the buffer
void oled_update() {
    unsigned char buffer[OLED_WIDTH * OLED_HEIGHT / 8];
    int page = 0;

    for (int i = 0; i < OLED_WIDTH * OLED_HEIGHT / 8; i++) {
        buffer[i] = i2cReadByteData(i2c_handle, 0x40);
        if (buffer[i] < 0) {
            fprintf(stderr, "Error: I2C read failed during update.\n");
            terminate = 1;
            return;
        }
    }

    for (int i = 0; i < OLED_WIDTH * OLED_HEIGHT / 8; i++) {
        if (i2cWriteByteData(i2c_handle, 0x40, buffer[i]) < 0) {
            fprintf(stderr, "Error: I2C write failed during update.\n");
            terminate = 1;
            return;
        }
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, OLED_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize OLED display
    oled_init();
    oled_clear();

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read CPU temperature and usage
        float temp = read_cpu_temp();
        float usage = read_cpu_usage();

        // Format the strings
        char temp_str[20];
        char usage_str[20];

        if (temp < 0) {
            snprintf(temp_str, sizeof(temp_str), "Temp: Error");
        } else {
            snprintf(temp_str, sizeof(temp_str), "Temp: %.1f C", temp);
        }

        if (usage < 0) {
            snprintf(usage_str, sizeof(usage_str), "Usage: Error");
        } else {
            snprintf(usage_str, sizeof(usage_str), "Usage: %.1f %%", usage);
        }

        // Clear the display
        oled_clear();

        // Draw the strings
        oled_draw_string(0, 0, temp_str);
        oled_draw_string(0, 16, usage_str);

        // Update the display
        oled_update();

        // Wait for 1 second
        sleep(1);
    }

    // Clean up and exit
    i2cClose(i2c_handle);
    gpioTerminate();
    fprintf(stderr, "Program terminated cleanly.\n");
    return 0;
}

