#include <wiringPiI2C.h>

// Define GPIO pin for the water flow sensor
#define FLOW_SENSOR_GPIO 17

// Define I2C address for the LCD
#define LCD_ADDR 0x27

// Define LCD dimensions
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0

// Global variables
volatile int pulse_count = 0;
float flow_rate = 0.0;
float total_volume = 0.0;
int lcd_fd;

// Function prototypes
void pulse_counter(int gpio, int level, uint32_t tick, void *user);
void update_lcd(float flow_rate, float total_volume);
void signal_handler(int signal);

// LCD functions
void lcd_init();
void lcd_byte(int bits, int mode);
void lcd_string(const char *s);
void lcd_clear();

// Callback function for pulse counting
void pulse_counter(int gpio, int level, uint32_t tick, void *user)
{
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user; // unused
    pulse_count++;
}

// Function to update the LCD display
void update_lcd(float flow_rate, float total_volume)
{
    char buffer[32];
    char volume_str[16];

    // Format the volume string
    snprintf(volume_str, sizeof(volume_str), "Vol: %.2f L", total_volume);

    // Clear the LCD
    lcd_clear();

    // Display the flow rate and volume on the LCD
    lcd_string("Flow: ");
    lcd_byte(0x40, LCD_CHR); // Move cursor to the second line
    lcd_string(buffer);
    lcd_byte(0xC0, LCD_CHR); // Move cursor to the third line
    lcd_string(volume_str);
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    if (lcd_fd >= 0) {
        close(lcd_fd);
    }
    exit(0);
}

// LCD initialization function
void lcd_init()
{
    lcd_fd = wiringPiI2CSetup(LCD_ADDR);
    if (lcd_fd == -1)
    {
        fprintf(stderr, "Error initializing I2C LCD!\n");
        exit(1);
    }

    // Initialise display
    lcd_byte(0x33, LCD_CMD); // Initialise
    lcd_byte(0x32, LCD_CMD); // Initialise
    lcd_byte(0x06, LCD_CMD); // Cursor move direction
    lcd_byte(0x0C, LCD_CMD); // 0x0F = Display on,Cursor on, Blink on
    lcd_byte(0x28, LCD_CMD); // Data length, number of lines, font size
    lcd_byte(0x01, LCD_CMD); // Clear display
    gpioDelay(2000); // Wait 2ms
}

// Function to send a byte to the LCD
void lcd_byte(int bits, int mode)
{
    // Send byte to data pins
    // bits = the data
    // mode = 1 for data, 0 for command

    int bits_high = mode | (bits & 0xF0) | 0x04; // Enable bit
    int bits_low = mode | ((bits << 4) & 0xF0) | 0x08; // Enable bit

    wiringPiI2CWrite(lcd_fd, bits_high);
    wiringPiI2CWrite(lcd_fd, bits_low);
}

// Function to send a string to the LCD
void lcd_string(const char *s)
{
    while (*s) {
        lcd_byte(*s++, LCD_CHR);
    }
}

// Function to clear the LCD
void lcd_clear()
{
    lcd_byte(0x01, LCD_CMD); // Clear display
    gpioDelay(2000); // Wait 2ms
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);

    // Set up interrupt on GPIO17
    gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_counter, NULL);

    // Initialize LCD
    lcd_init();

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1)
    {
        // Calculate flow rate
        flow_rate = (float)pulse_count / 450.0 * 60.0; // pulses/liter * 60 seconds/minute
        total_volume += flow_rate;

        // Print flow rate and total volume to console
        printf("Flow Rate: %.2f LPM, Total Volume: %.2f L\n", flow_rate, total_volume);

        // Update LCD
        update_lcd(flow_rate, total_volume);

        // Reset pulse count
        pulse_count = 0;

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

