// Configuration
#define ANEMOMETER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define I2C_BUS 1
#define I2C_ADDR 0x27
#define SAMPLE_INTERVAL_MS 500
#define SAMPLE_WINDOW_MS 50
#define PULSES_PER_METER_PER_SECOND 0.5
#define ADC_CHANNEL 0
#define ADC_MAX 1023.0
#define ADC_MIN 0.0
#define DEBOUNCE_DELAY_US 5000 // 5 ms debounce

// Global variables
volatile int pulse_count = 0;
int i2c_handle;
int spi_handle;
int lcd_handle;
int anemometer_enabled = 1;
int wind_vane_enabled = 1;

// Function prototypes
void anemometer_interrupt_handler(int gpio, int level, uint32_t tick, void *user);
float calculate_wind_speed(int pulse_count);
int read_wind_vane();
void display_data(float wind_speed, int wind_direction);
void signal_handler(int signal);
int initialize_i2c();
int initialize_spi();
void cleanup();

// LCD functions (bit-banging)
void lcd_init();
void lcd_byte(int bits, int mode);
void lcd_string(const char *s);
void lcd_clear();

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to initialize LCD
void lcd_init() {
    // Initialization sequence for PCF8574-based LCD
    gpioDelay(50000); // Wait 50ms
    lcd_byte(0x33, 0); // Initialize
    gpioDelay(5000);   // Wait 5ms
    lcd_byte(0x32, 0); // Initialize
    gpioDelay(1000);   // Wait 1ms
    lcd_byte(0x28, 0); // 4-bit mode, 2 lines, 5x8 font
    gpioDelay(1000);   // Wait 1ms
    lcd_byte(0x0C, 0); // Display on, cursor off, blink off
    gpioDelay(1000);   // Wait 1ms
    lcd_byte(0x06, 0); // Increment cursor, no shift
    gpioDelay(1000);   // Wait 1ms
    lcd_byte(0x01, 0); // Clear display
    gpioDelay(2000);   // Wait 2ms
}

// Function to send a byte to the LCD
void lcd_byte(int bits, int mode) {
    // Send byte to data pins
    // bits = the data
    // mode = 1 for data, 0 for command

    int bits_high = mode | (bits & 0xF0) | 0x04; // Enable bit
    int bits_low = mode | ((bits << 4) & 0xF0) | 0x08; // Enable bit

    gpioWrite(4, 0); // RS low for command
    gpioWrite(5, 0); // RW low for write
    gpioWrite(6, 0); // DEN low for internal data

    gpioWrite(2, bits_high & 0x01); // D4
    gpioWrite(3, bits_high & 0x02); // D5
    gpioWrite(4, bits_high & 0x04); // D6
    gpioWrite(5, bits_high & 0x08); // D7

    gpioDelay(1); // Enable pulse width

    gpioWrite(2, bits_high & 0x01); // D4
    gpioWrite(3, bits_high & 0x02); // D5
