// Pulse counter callback function
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick;  // unused
    (void)user_data; // unused
    pulse_count++;
}

// Function to display flow rate on LCD
void display_flow_rate(float flow_rate) {
    char buffer[LCD_WIDTH + 1];

    // Clear the LCD
    wiringPiI2CWriteReg8(i2c_fd, 0x08, 0x01); // Clear display
    wiringPiI2CWriteReg8(i2c_fd, 0x08, 0x02); // Return to home

    // Display "Flow Rate:"
    sprintf(buffer, "Flow Rate:");
    for (int i = 0; i < strlen(buffer); i++) {
        wiringPiI2CWriteReg8(i2c_fd, 0x08, buffer[i]);
    }

    // Display flow rate
    sprintf(buffer, " %.2f L/min", flow_rate);
    for (int i = 0; i < strlen(buffer); i++) {
        wiringPiI2CWriteReg8(i2c_fd, 0x08, buffer[i]);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(PCF8574_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up interrupt on GPIO17
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_counter, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Reset pulse count
        pulse_count = 0;
        gpioDelay(1000); // Wait for 1 second

        // Calculate flow rate
        float flow_rate = (float)pulse_count / PULSES_PER_LITER * 60.0;

        // Display flow rate
        display_flow_rate(flow_rate);

        // Print flow rate to console
        printf("Flow Rate: %.2f L/min\n", flow_rate);

        // Reset pulse count
        pulse_count = 0;
    }

    // Clean up
    gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, NULL, NULL); // Disable ISR
    gpioTerminate();
    close(i2c_fd);

    return 0;
