#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for rows and columns
#define ROWS_PINS {17, 18, 27, 22, 23, 24, 25, 4}
#define COLS_PINS {5, 6, 12, 13, 19, 16, 26, 20}

// Define wave pattern data
const unsigned char left_wave[8] = {0x7E, 0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40};
const unsigned char right_wave[8] = {0x40, 0x20, 0x10, 0x08, 0x04, 0x02, 0x01, 0x7E};

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void scan_row(int row_pin);
void display_wave(const unsigned char *wave_data, int direction);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set row pins as outputs
    for (int i = 0; i < 8; i++) {
        int row_pin = ROWS_PINS[i];
        if (gpioSetMode(row_pin, PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", row_pin);
            cleanup_gpio();
            return 1;
        }
    }

    // Set column pins as outputs
    for (int i = 0; i < 8; i++) {
        int col_pin = COLS_PINS[i];
        if (gpioSetMode(col_pin, PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", col_pin);
            cleanup_gpio();
            return 1;
        }
    }

    return 0;
}

// Cleanup GPIO pins
void cleanup_gpio() {
    // Set all row pins LOW
    for (int i = 0; i < 8; i++) {
        int row_pin = ROWS_PINS[i];
        gpioWrite(row_pin, 0);
    }

    // Set all column pins HIGH
    for (int i = 0; i < 8; i++) {
        int col_pin = COLS_PINS[i];
        gpioWrite(col_pin, 1);
    }

    gpioTerminate();
}

// Scan a single row
void scan_row(int row_pin) {
    gpioWrite(row_pin, 1); // Set row HIGH
    for (int i = 0; i < 8; i++) {
        int col_pin = COLS_PINS[i];
        gpioWrite(col_pin, (i == row_pin) ? 0 : 1); // Light LED if column is the row pin
    }
    gpioDelay(800); // Delay for 800 microseconds
    gpioWrite(row_pin, 0); // Set row LOW
}

// Display a wave pattern
void display_wave(const unsigned char *wave_data, int direction) {
    for (int i = 0; i < 8; i++) {
        int row_pin = ROWS_PINS[i];
        int col_pin = COLS_PINS[direction == 1 ? i : 7 - i]; // Correct column pin based on direction

        gpioWrite(row_pin, 1); // Set row HIGH
        gpioWrite(col_pin, (i == row_pin) ? 0 : 1); // Light LED if column is the row pin
        gpioDelay(800); // Delay for 800 microseconds
        gpioWrite(row_pin, 0); // Set row LOW
    }
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Left-to-right wave
        display_wave(left_wave, 1);
        gpioDelay(10000); // Delay for 10 milliseconds

        // Right-to-left wave
        display_wave(right_wave, 0);
        gpioDelay(10000); // Delay for 10 milliseconds
    }

    // Cleanup GPIO and exit
    cleanup_gpio();
    return 0;
}

