#include <pigpio.h>

// Define GPIO pins for rows and columns
const int row_pins[] = {2, 3, 4, 17, 27, 22, 10, 9};
const int col_pins[] = {14, 15, 18, 23, 24, 25, 8, 7};
const int num_pins = sizeof(row_pins) / sizeof(row_pins[0]);

// Chip number (adjust if needed)
const int chip_number = 0;

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal)
{
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize a GPIO pin as output
int initialize_gpio(int pin)
{
    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", pin);
        return -1;
    }
    return 0;
}

// Function to set the state of a GPIO pin
void set_gpio_state(int pin, int state)
{
    gpioWrite(pin, state);
}

// Function to clear the matrix (set all rows LOW and all columns HIGH)
void clear_matrix()
{
    for (int i = 0; i < num_pins; i++) {
        set_gpio_state(row_pins[i], 1); // Turn off row anodes
        set_gpio_state(col_pins[i], 0); // Turn on column cathodes
    }
}

// Function to display a column (set the corresponding column cathode LOW and all row anodes HIGH)
void display_column(int col_index)
{
    for (int i = 0; i < num_pins; i++) {
        set_gpio_state(row_pins[i], 1); // Turn on row anodes
        set_gpio_state(col_pins[i], (i == col_index) ? 0 : 1); // Turn on the selected column cathode
    }
}

int main()
{
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the GPIO chip
    int chip = gpiod_chip_open_by_number(chip_number);
    if (chip < 0) {
        fprintf(stderr, "Error opening GPIO chip %d\n", chip_number);
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO pins
    for (int i = 0; i < num_pins; i++) {
        if (initialize_gpio(row_pins[i]) != 0 || initialize_gpio(col_pins[i]) != 0) {
            fprintf(stderr, "Error initializing GPIO pin %d\n", row_pins[i]);
            gpiod_chip_close(chip);
            gpioTerminate();
            return 1;
        }
    }

    // Main loop
    while (!terminate) {
        // Clear the matrix
        clear_matrix();

        // Display each column with a delay
        for (int col = 0; col < num_pins; col++) {
            display_column(col);
            gpioDelay(150000); // 150 ms delay
        }
    }

    // Clean up GPIO lines
    for (int i = 0; i < num_pins; i++) {
        set_gpio_state(row_pins[i], 0); // Turn off row anodes
        set_gpio_state(col_pins[i], 0); // Turn off column cathodes
    }

    // Close the GPIO chip
    gpiod_chip_close(chip);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

