#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x4C
#define DISTANCE_REGISTER 0x0D
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "depth_log.csv"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int read_distance_register(int *distance);
int log_distance(int distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
        if (i2c_handle >= 0) {
            i2cClose(i2c_handle);
        }
        if (log_file != NULL) {
            fclose(log_file);
        }
        gpioTerminate();
        exit(0);
    }
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c_connection() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance register
int read_distance_register(int *distance) {
    char buf[2];
    int result;

    result = i2cWriteByteData(i2c_handle, DISTANCE_REGISTER, 0); // Write register address
    if (result < 0) {
        fprintf(stderr, "Failed to write register address: %d\n", result);
        return -1;
    }

    result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REGISTER, buf, 2); // Read 2 bytes
    if (result < 0) {
        fprintf(stderr, "Failed to read distance data: %d\n", result);
        return -1;
    }

    // Convert big-endian to little-endian
    *distance = (buf[1] << 8) | buf[0];

    return 0;
}

// Log distance to file
int log_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "w");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file for writing\n");
            return -1;
        }
        fprintf(log_file, "Timestamp,Distance\n"); // Write header
    }

    fprintf(log_file, "%s,%d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

int main() {
    int distance;

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    if (open_i2c_connection() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        if (read_distance_register(&distance) == 0) {
            if (log_distance(distance) != 0) {
                fprintf(stderr, "Failed to log distance\n");
