// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
        if (i2c_handle >= 0) {
            i2cClose(i2c_handle);
        }
        if (log_file != NULL) {
            fclose(log_file);
        }
        gpioTerminate();
        exit(0);
    }
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c_connection() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance register
int read_distance_register(int *distance) {
    char buf[2];
    int result;

    result = i2cWriteByteData(i2c_handle, DISTANCE_REGISTER, 0); // Write register address
    if (result < 0) {
        fprintf(stderr, "Failed to write register address: %d\n", result);
        return -1;
    }

    result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REGISTER, buf, 2); // Read 2 bytes
    if (result < 0) {
        fprintf(stderr, "Failed to read distance data: %d\n", result);
        return -1;
    }

    // Convert big-endian to little-endian
    *distance = (buf[1] << 8) | buf[0];

    return 0;
}

