#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIOCHIP4 "gpiochip4"
#define GPIOCHIP0 "gpiochip0"
#define GPIO_SENSOR 4
#define GPIO_LED 17

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor_line = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to get current timestamp in ISO 8601 UTC format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log an event to the log file
void log_event(const char *timestamp, const char *message) {
    if (log_file != NULL) {
        fprintf(log_file, "%s %s\n", timestamp, message);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize GPIO lines
int initialize_gpio() {
    chip = gpiod_chip_open_by_name(GPIOCHIP4);
    if (chip == NULL) {
        chip = gpiod_chip_open_by_name(GPIOCHIP0);
        if (chip == NULL) {
            fprintf(stderr, "Error: Could not open GPIO chip %s or %s: %s\n", GPIOCHIP4, GPIOCHIP0, strerror(errno));
            return -1;
        }
    }

    sensor_line = gpiod_chip_get_line(chip, GPIO_SENSOR);
    if (!sensor_line) {
        fprintf(stderr, "Error: Could not get GPIO line %d: %s\n", GPIO_SENSOR, strerror(errno));
        if (chip) gpiod_chip_close(chip);
        return -1;
    }

    led_line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led_line) {
        fprintf(stderr, "Error: Could not get GPIO line %d: %s\n", GPIO_LED, strerror(errno));
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(sensor_line, "proximity_sensor") < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d as input: %s\n", GPIO_SENSOR, strerror(errno));
        gpiod_line_release(sensor_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(led_line, "proximity_led", 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d as output: %s\n", GPIO_LED, strerror(errno));
        gpiod_line_release(sensor_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    struct gpiod_line_event event;
    int prev_sensor_value = 1; // Assume no object initially

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("proximity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup_gpio();
        return 1;
    }

    fprintf(stdout, "Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int current_sensor_value = gpiod_line_get_value(sensor_line);

        if (current_sensor_value < 0) {
            fprintf(stderr, "Error reading sensor value: %s\n", strerror(errno));
            break; // Exit loop on error
        }

        // Detect falling edge (object entering range)
        if (prev_sensor_value == 1 && current_sensor_value == 0) {
            // Object detected
            char *timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                log_event(timestamp, "Object detected");
                free(timestamp);
            }

            // Blink LED
            gpiod_line_set_value(led_line, 1); // Turn LED ON
            usleep(50000); // 50 ms
            gpiod_line_set_value(led_line, 0); // Turn LED OFF
            usleep(50000); // 50 ms
        }

        prev_sensor_value = current_sensor_value;
        usleep(100000); // 100 ms delay
    }

    // Cleanup and exit
    cleanup_gpio();
    if (log_file != NULL) {
        fclose(log_file);
    }
    fprintf(stdout, "Exiting.\n");
    return 0;
}

