#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define APDS9960_ADDR 0x39
#define SENSOR_ID 0xAB
#define PROX_THRESHOLD 200
#define CSV_FILE "color_proximity_log.csv"

// APDS9960 Registers
#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0xF1
#define APDS9960_CONFIG2 0x90
#define APDS9960_RDATA 0x96
#define APDS9960_GDATA 0x98
#define APDS9960_BDATA 0x9A
#define APDS9960_PDATA 0x9C

// Global variables
int i2c_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int verify_sensor_id();
int configure_apds9960();
int read_apds9960_data(int *red, int *green, int *blue, int *proximity);
int log_data(int red, int green, int blue, int proximity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Verify sensor ID function
int verify_sensor_id() {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, 0x92, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading sensor ID: %d\n", result);
        return -1;
    }
    if (buf[0] != 0xAB) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", buf[0]);
        return -1;
    }
    return 0;
}

// Configure APDS9960 function
int configure_apds9960() {
    // Enable the sensor
    if (i2cWriteByteData(i2c_handle, APDS9960_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error writing to ENABLE register\n");
        return -1;
    }

    // Set ATIME
    if (i2cWriteByteData(i2c_handle, APDS9960_ATIME, 0xDB) < 0) {
        fprintf(stderr, "Error writing to ATIME register\n");
        return -1;
    }

    // Set WTIME
    if (i2cWriteByteData(i2c_handle, APDS9960_WTIME, 0xF6) < 0) {
        fprintf(stderr, "Error writing to WTIME register\n");
        return -1;
    }

    // Set PPULSE
    if (i2cWriteByteData(i2c_handle, APDS9960_PPULSE, 0x87) < 0) {
        fprintf(stderr, "Error writing to PPULSE register\n");
        return -1;
    }

    // Set CONTROL
    if (i2cWriteByteData(i2c_handle, APDS9960_CONTROL, 0x03) < 0) {
        fprintf(stderr, "Error writing to CONTROL register\n");
        return -1;
    }

    // Set CONFIG2
    if (i2cWriteByteData(i2c_handle, APDS9960_CONFIG2, 0x01) < 0) {
        fprintf(stderr, "Error writing to CONFIG2 register\n");
        return -1;
    }

    return 0;
}

// Read APDS9960 data function
int read_apds9960_data(int *red, int *green, int *blue, int *proximity) {
    char buf[2];
    char pbuf[1];

    // Read RGB values
    if (i2cReadI2CBlockData(i2c_handle, APDS9960_RDATA, buf, 2) < 0) {
        fprintf(stderr, "Error reading RGB data\n");
        return -1;
    }
    *red = buf[0] | (buf[1] << 8);

    if (i2cReadI2CBlockData(i2c_handle, APDS9960_GDATA, buf, 2) < 0) {
        fprintf(stderr, "Error reading G data\n");
        return -1;
    }
    *green = buf[0] | (buf[1] << 8);

    if (i2cReadI2CBlockData(i2c_handle, APDS9960_BDATA, buf, 2) < 0) {
        fprintf(stderr, "Error reading B data\n");
        return -1;
    }
    *blue = buf[0] | (buf[1] << 8);

    // Read proximity value
    if (i2cReadI2CBlockData(i2c_handle, APDS9960_PDATA, pbuf, 1) < 0) {
        fprintf(stderr, "Error reading proximity data\n");
        return -1;
    }
    *proximity = pbuf[0];

    return 0;
}

// Log data to CSV file function
int log_data(int red, int green, int blue, int proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(csv_file, "%s,%d,%d,%d,%d\n", timestamp, red, green, blue, proximity);
    fflush(csv_file); // Ensure data is written to file immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, APDS9960_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify sensor ID
    if (verify_sensor_id() != 0) {
        fprintf(stderr, "Sensor ID verification failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure APDS9960
    if (configure_apds9960() != 0) {
        fprintf(stderr, "APDS9960 configuration failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to CSV file if it's a new file
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,Red,Green,Blue,Proximity\n");
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int red, green, blue, proximity;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_apds9960_data(&red, &green, &blue, &proximity) == 0) {
            // Log data if proximity exceeds threshold
            if (proximity > PROX_THRESHOLD) {
                log_data(red, green, blue, proximity);
            }
        } else {
            fprintf(stderr, "Error reading sensor data, attempting to re-initialize...\n");
            // Attempt to re-initialize I2C and sensor
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, APDS9960_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (verify_sensor_id() != 0) {
                    fprintf(stderr, "Sensor ID verification failed after re-initialization\n");
                    terminate = 1;
                }
                if (configure_apds9960() != 0) {
                    fprintf(stderr, "APDS9960 configuration failed after re-initialization\n");
                    terminate = 1;
                }
            }
        }

        // Delay
        gpioDelay(100); // 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(csv_file);
    gpioTerminate();

    return 0;
}

