    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, APDS9960_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify sensor ID
    if (verify_sensor_id() != 0) {
        fprintf(stderr, "Sensor ID verification failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure APDS9960
    if (configure_apds9960() != 0) {
        fprintf(stderr, "APDS9960 configuration failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to CSV file if it's a new file
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,Red,Green,Blue,Proximity\n");
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int red, green, blue, proximity;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_apds9960_data(&red, &green, &blue, &proximity) == 0) {
            // Log data if proximity exceeds threshold
            if (proximity > PROX_THRESHOLD) {
                log_data(red, green, blue, proximity);
            }
        } else {
            fprintf(stderr, "Error reading sensor data, attempting to re-initialize...\n");
            // Attempt to re-initialize I2C and sensor
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, APDS9960_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (verify_sensor_id() != 0) {
                    fprintf(stderr, "Sensor ID verification failed after re-initialization\n");
                    terminate = 1;
                }
                if (configure_apds9960() != 0) {
                    fprintf(stderr, "APDS9960 configuration failed after re-initialization\n");
                    terminate = 1;
                }
            }
        }

        // Delay
        gpioDelay(100); // 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(csv_file);
    gpioTerminate();

    return 0;
}

