    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Verify sensor ID
    if (verify_sensor_id() < 0) {
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() < 0) {
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    printf("Sensor initialized and configured.  Starting data acquisition...\n");

    // Main loop
    int proximity;
    float bpm;
    while (running) {
        if (read_proximity_data(&proximity) == 0) {
            bpm = calculate_bpm(proximity);
            if (log_data(bpm) != 0) {
                fprintf(stderr, "Error logging data\n");
