#define DISTANCE_REG_LOW 0x11
#define TIMEOUT_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_sensor();
int read_distance(int *distance);
void log_distance(int distance);
void interrupt_handler(int gpio, int level, uint32_t tick);
void signal_handler(int signal);
void cleanup();

// Structure for sensor configuration (example)
typedef struct {
    int i2c_address;
    int interrupt_pin;
    int timeout_ms;
} sensor_config_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

