#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x45
#define TRIGGER_COMMAND 0x00
#define SAMPLE_INTERVAL_MS 200

int i2c_handle;
FILE *log_file;

// Function to get the current timestamp in YYYY-MM-DD HH:MM:SS format
void get_timestamp(char *timestamp)
{
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

// Function to log the distance reading to a file
void log_distance(int distance_mm)
{
    char timestamp[20];
    get_timestamp(timestamp);

    fprintf(log_file, "%s, %d\n", timestamp, distance_mm);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to read the distance from the sensor
int read_distance()
{
    char trigger_command[1] = {TRIGGER_COMMAND};
    char buffer[2];
    int result;

    result = i2cWriteDevice(i2c_handle, trigger_command, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1; // Indicate error
    }

    gpioDelay(50); // Wait for measurement

    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1; // Indicate error
    }

    // Combine the two bytes into a 16-bit integer
    int distance_mm = (buffer[0] << 8) | buffer[1];
    return distance_mm;
}

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        int distance_mm = read_distance();
        if (distance_mm >= 0) {
            log_distance(distance_mm);
            printf("%s, %d\n", distance_mm == 0 ? "Distance: " : "Distance: ", distance_mm);
        } else {
            fprintf(stderr, "Failed to read distance. Retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    return 0; // This line will never be reached due to the infinite loop, but it's good practice to include it.
}

