#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define LOG_FILE "obstacle_log.txt"

volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int read_sensor(int gpio) {
    int reading = gpioRead(gpio);
    if (reading < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d: %d\n", gpio, reading);
        return -1; // Indicate an error
    }
    return reading;
}

int log_data(FILE *fp, int sensor1_value, int sensor2_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s, Sensor1: %d, Sensor2: %d\n", timestamp, sensor1_value, sensor2_value) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Obstacle detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        if (sensor1_value != -1 && sensor2_value != -1) {
            if (log_data(log_file, sensor1_value, sensor2_value) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping log.\n");
        }

        gpioDelay(100); // 100 milliseconds
    }

    printf("Cleaning up...\n");

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

