void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to read sensor data with retries
int read_sensor_data(int handle, int reg, int *data) {
    int result, retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cReadWordData(handle, reg);
        if (result >= 0) {
            *data = result;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading register 0x%02X: %d, retry %d\n", reg, result, retries + 1);
            retries++;
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }
    fprintf(stderr, "Failed to read register 0x%02X after %d retries.\n", reg, RETRY_COUNT);
    return -1; // Failure
}

// Function to log data to file
int log_data(FILE *fp, int proximity, int ambient_light) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, Proximity: %d, Ambient Light: %d\n", timestamp, proximity, ambient_light) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

