#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x50
#define CMD_FRAME {0x50, 0x0A, 0x00, 0x01}
#define RESP_FRAME_SIZE 15
#define SAMPLE_COUNT 10
#define DELAY_MS 100
#define INTRUSION_THRESHOLD 1000

int i2c_fd = -1;
FILE *log_file = NULL;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(int bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to send a command to the sensor
