#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L0X_ADDR 0x29
#define SYSRANGE_START 0x00
#define RESULT_INTERRUPT_STATUS 0x13
#define RESULT_RANGE_STATUS 0x14
#define SYSTEM_INTERRUPT_CLEAR 0x0B
#define VL53L0X_MODEL_ID 0xC0

int i2c_handle;

// Function to handle signals (Ctrl+C, termination)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to initialize the VL53L0X sensor
int init_vl53l0x() {
    // Check if the sensor is present by reading the model ID
    char model_id;
    if (i2cReadI2CBlockData(i2c_handle, VL53L0X_MODEL_ID, &model_id, 1) != 1) {
        fprintf(stderr, "Error reading model ID: %s\n", strerror(errno));
        return -1;
    }

    if (model_id != 0xEE) {
        fprintf(stderr, "Error: Incorrect model ID (0x%02X). Expected 0xEE.\n", model_id);
        return -1;
    }

    // Start continuous ranging (example, adjust as needed)
    if (i2cWriteByteData(i2c_handle, SYSRANGE_START, 0x01) != 0) {
        fprintf(stderr, "Error starting ranging: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read the distance from the VL53L0X sensor
int read_distance(int *distance) {
    char data[2];
    int timeout_start = gpioTick();

    // Wait for the interrupt to be set
    while (gpioRead(RESULT_INTERRUPT_STATUS) == 0) {
        if (gpioTick() - timeout_start > 100000) { // 100 ms timeout
            fprintf(stderr, "Timeout waiting for interrupt.\n");
            return -1;
        }
        gpioDelay(1000); // Check every 1 ms
    }

    // Read the distance data
    if (i2cReadI2CBlockData(i2c_handle, RESULT_RANGE_STATUS, data, 2) != 2) {
        fprintf(stderr, "Error reading distance: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    *distance = (data[0] << 8) | data[1];

    // Clear the interrupt
    if (i2cWriteByteData(i2c_handle, SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        fprintf(stderr, "Error clearing interrupt: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the VL53L0X sensor
    if (init_vl53l0x() != 0) {
        fprintf(stderr, "VL53L0X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C and termination signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int distance;
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        // Read the distance
        if (read_distance(&distance) == 0) {
            // Get current time
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Print the distance
            printf("%s Distance: %d mm\n", timestamp, distance);
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        // Wait 500 ms
        gpioDelay(500000);
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

