#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Si1182 I2C address
#define SI1182_ADDR 0x39

// Si1182 register addresses
#define SI1182_CONFIG_REG 0x18
#define SI1182_IRQ_STATUS_REG 0x25
#define SI1182_PROX_LSB_REG 0x2A
#define SI1182_PROX_MSB_REG 0x2B

// I2C handle
int i2c_handle;

// Function prototypes
int si1182_init();
int si1182_read_proximity();
void signal_handler(int signal);

// Structure to hold sensor configuration
typedef struct {
    int i2c_address;
    int config_value;
} sensor_config_t;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C pressed. Exiting...\n");
        program_running = 0;
    }
}

// Function to initialize the Si1182 sensor
int si1182_init() {
    // Write the configuration value to the CONFIG register
    int result = i2cWriteByteData(i2c_handle, SI1182_CONFIG_REG, 0x01); // Enable proximity mode
    if (result != 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read the proximity data from the Si1182 sensor
int si1182_read_proximity() {
    int prox_lsb, prox_msb;
    int proximity_value;

    // Read the LSB of the proximity data
    prox_lsb = i2cReadByteData(i2c_handle, SI1182_PROX_LSB_REG);
    if (prox_lsb < 0) {
        fprintf(stderr, "Error reading proximity LSB: %d\n", prox_lsb);
        return -1;
    }

    // Read the MSB of the proximity data
    prox_msb = i2cReadByteData(i2c_handle, SI1182_PROX_MSB_REG);
    if (prox_msb < 0) {
        fprintf(stderr, "Error reading proximity MSB: %d\n", prox_msb);
        return -1;
    }

    // Combine the LSB and MSB to form the 16-bit proximity value
    proximity_value = (prox_msb << 8) | prox_lsb;

    return proximity_value;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1182_ADDR, 0); // Bus 1, address 0x39, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the Si1182 sensor
    if (si1182_init() != 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read proximity data
        int proximity_value = si1182_read_proximity();
        if (proximity_value >= 0) {
            // Print the proximity value
            printf("Proximity: %d\n", proximity_value);
        } else {
            fprintf(stderr, "Failed to read proximity data\n");
        }

        // Wait 500 ms
        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

