        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the Si1182 sensor
    if (si1182_init() != 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read proximity data
        int proximity_value = si1182_read_proximity();
        if (proximity_value >= 0) {
            // Print the proximity value
            printf("Proximity: %d\n", proximity_value);
        } else {
            fprintf(stderr, "Failed to read proximity data\n");
        }

        // Wait 500 ms
        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

