#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX75030_ADDR 0x4C
#define DISTANCE_REG 0x00
#define MM_PER_COUNT 0.125

volatile sig_atomic_t keep_running = 1;

void sigint_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
}

int main() {
    int i2c_fd;
    struct timespec sleep_time;
    int distance_raw;
    float distance_mm;
    unsigned char buf[2];

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Verify device presence
    buf[0] = 0x00; // Dummy register address
    if (write(i2c_fd, buf, 1) != 1) {
        perror("Error writing to I2C device");
        close(i2c_fd);
        return 1;
    }

    if (read(i2c_fd, buf, 1) != 1) {
        perror("Error reading from I2C device");
        close(i2c_fd);
        return 1;
    }

    if (buf[0] != 0x01) { // Example response, adjust as needed
        fprintf(stderr, "Error: MLX75030 not responding. Check I2C connection.\n");
        close(i2c_fd);
        return 1;
    }

    // Configure sleep time
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 500 * 1000 * 1000; // 500 ms

    // Main loop
    while (keep_running) {
        // Read distance data
        distance_raw = i2c_smb_read_word_data(i2c_fd, DISTANCE_REG);
        if (distance_raw < 0) {
            perror("Error reading distance data");
            // Attempt to recover by retrying the next cycle
            nanosleep(&sleep_time, NULL);
            continue;
        }

        // Convert to millimetres
        distance_mm = (float)distance_raw * MM_PER_COUNT;

        // Print distance
        printf("Distance: %.2f mm\n", distance_mm);

        // Sleep for 500 ms
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    close(i2c_fd);
    printf("Exiting cleanly.\n");
    return 0;
}

