// Define the I2C bus and address for the OPT3101
#define I2C_BUS 1
#define OPT3101_ADDR 0x44

// Define register addresses (replace with actual values from datasheet)
#define REG_DISTANCE_CH0 0x00
#define REG_AMBIENT_LIGHT 0x02
#define REG_ERROR_FLAGS 0x04

// Global variable for I2C handle
int i2c_handle;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to read a 16-bit value from the OPT3101
int read_opt3101_register(int handle, unsigned char reg_addr) {
    int value = i2cReadWordData(handle, reg_addr);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg_addr, value);
        return -1; // Indicate an error
    }
    return value;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, OPT3101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read data from the OPT3101
        int distance_ch0 = read_opt3101_register(i2c_handle, REG_DISTANCE_CH0);
        int ambient_light = read_opt3101_register(i2c_handle, REG_AMBIENT_LIGHT);
        int error_flags = read_opt3101_register(i2c_handle, REG_ERROR_FLAGS);

        // Check for errors
        if (distance_ch0 < 0 || ambient_light < 0 || error_flags < 0) {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Print the data
        printf("Distance Ch0: %d, Ambient Light: %d, Error Flags: %d\n", distance_ch0, ambient_light, error_flags);

        // Wait 500ms
        gpioDelay(500000);
    }

    // The following lines will never be reached due to the infinite loop
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

