#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 200000       // 200 ms timeout in microseconds
#define MAX_PULSE_DURATION_US 38000 // 38 ms in microseconds

// Global variables
volatile int pulse_start = 0;
volatile int pulse_end = 0;
volatile int valid_pulse = 0;

// Function prototypes
void trigger_sensor();
int measure_pulse_width();
float calculate_distance(int pulse_width);
void log_distance(float distance);
void echo_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (gpio == ECHO_PIN) {
        if (level == 1) {
            pulse_start = tick;
            valid_pulse = 0; // Reset valid pulse flag
        } else if (level == 0) {
            pulse_end = tick;
            valid_pulse = 1; // Set valid pulse flag
        }
    }
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width of the echo signal
int measure_pulse_width() {
    int pulse_width = 0;
    int start_time = gpioTick();

    // Wait for the echo pin to go high
    while (pulse_end == 0 && (gpioTick() - start_time) < TIMEOUT_US) {
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (pulse_end == 0) {
        fprintf(stderr, "Error: Echo rising edge timeout\n");
        return -1; // Indicate timeout error
    }

    // Wait for the echo pin to go low
    start_time = gpioTick();
    while (pulse_end == 1 && (gpioTick() - start_time) < TIMEOUT_US) {
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (pulse_end == 1) {
        fprintf(stderr, "Error: Echo falling edge timeout\n");
        return -1; // Indicate timeout error
    }

    pulse_width = pulse_end - pulse_start;
    return pulse_width;
}

// Function to calculate the distance in centimeters
float calculate_distance(int pulse_width) {
    if (pulse_width <= 0 || pulse_width > MAX_PULSE_DURATION_US) {
        fprintf(stderr, "Error: Invalid pulse duration: %d us\n", pulse_width);
        return -1.0; // Indicate invalid pulse duration
    }
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s
}

// Function to log the distance with a timestamp
void log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Distance: %.2f cm\n", timestamp, distance);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        trigger_sensor();
        int pulse_width = measure_pulse_width();

        if (pulse_width > 0) {
            float distance = calculate_distance(pulse_width);
            if (distance >= 0) {
                log_distance(distance);
            }
        }

        gpioDelay(1000000); // Wait for 1 second
    }

    return 0; // This line will never be reached due to the infinite loop
}

