#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define GPIO_LED 17
#define THRESHOLD_DISTANCE 1.0
#define LED_ON_TIME 2
#define RANGE_BINS 64
#define RANGE_RESOLUTION 0.0486
#define MAGIC_WORD_SIZE 8
#define DATA_SIZE (RANGE_BINS * 2)
#define DATA_ALIGNMENT 4

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;
FILE *log_file = NULL;

// Structure to hold UART configuration
typedef struct {
    int fd;
    struct termios options;
} uart_config_t;

// Function prototypes
int initialize_uart(uart_config_t *config);
int read_radar_data(int fd, unsigned char *buffer, int max_length);
int validate_magic_word(const unsigned char *buffer, int length);
int parse_range_profile(const unsigned char *data, int data_length, float *range_profile);
int detect_intrusion(const float *range_profile, int num_bins);
int control_led(int gpio_pin, int on);
int log_intrusion(float distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize UART
int initialize_uart(uart_config_t *config) {
    config->fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (config->fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    if (tcgetattr(config->fd, &config->options) != 0) {
        perror("Error getting termios options");
        close(config->fd);
        return -1;
    }

    config->options.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 8 data bits, no parity, 1 stop bit
    config->options.c_iflag = IGNPAR;                           // Ignore parity errors
    config->options.c_oflag = 0;
    config->options.c_lflag = 0; // Non-canonical mode
    config->options.c_cc[VMIN] = 0;  // Read doesn't block
    config->options.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(config->fd, TCSANOW, &config->options) != 0) {
        perror("Error setting termios options");
        close(config->fd);
        return -1;
    }

    return 0;
}

// Read data from radar sensor
int read_radar_data(int fd, unsigned char *buffer, int max_length) {
    int bytes_read = read(fd, buffer, max_length);
    if (bytes_read < 0) {
        perror("Error reading from UART");
        return -1;
    } else if (bytes_read == 0) {
        //fprintf(stderr, "Timeout reading from UART\n");
        return 0; // No data received
    }
    return bytes_read;
}

// Validate magic word
int validate_magic_word(const unsigned char *buffer, int length) {
    if (length != MAGIC_WORD_SIZE) {
        fprintf(stderr, "Invalid magic word length: %d\n", length);
        return 0;
    }

    unsigned short magic_word = 0;
    for (int i = 0; i < MAGIC_WORD_SIZE; i++) {
        magic_word = (magic_word << 8) | buffer[i];
    }

    if (magic_word != 0x0706050403020102) {
        fprintf(stderr, "Invalid magic word: 0x%04X\n", magic_word);
        return 0;
    }

    return 1;
}

// Parse range profile data
int parse_range_profile(const unsigned char *data, int data_length, float *range_profile) {
    if (data_length != DATA_SIZE) {
        fprintf(stderr, "Invalid data length: %d\n", data_length);
        return 0;
    }

    for (int i = 0; i < RANGE_BINS; i++) {
        int16_t raw_value = (data[2 * i + 1] << 8) | data[2 * i];
        range_profile[i] = (float)raw_value * RANGE_RESOLUTION;
    }

    return 1;
}

// Detect intrusion
int detect_intrusion(const float *range_profile, int num_bins) {
    for (int i = 0; i < num_bins; i++) {
        if (range_profile[i] > THRESHOLD_DISTANCE) {
            return 1; // Intrusion detected
        }
    }
    return 0; // No intrusion detected
}

// Control LED
int control_led(int gpio_pin, int on) {
    gpioWrite(gpio_pin, on);
    return 0;
}

// Log intrusion
int log_intrusion(float distance) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
