#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define SENSOR_PIN 17
#define BUZZER_PIN 18

static struct gpiod_chip *chip;
static struct gpiod_line *sensor_line;
static struct gpiod_line *buzzer_line;
static volatile sig_atomic_t terminate = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize a GPIO line
int init_gpio(struct gpiod_chip *chip, int pin, int direction) {
    struct gpiod_line *line;
    int ret;

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting line %d: %s\n", pin, strerror(errno));
        return -1;
    }

    ret = gpiod_line_request(line, NULL, direction);
    if (ret < 0) {
        fprintf(stderr, "Error requesting line %d: %s\n", pin, strerror(errno));
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Function to read the sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading line: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Function to control the buzzer
int control_buzzer(struct gpiod_line *line, int state) {
    int ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting line value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to log the event with ISO 8601 timestamp
int log_event(const char *event) {
    FILE *fp;
    time_t rawtime;
    struct tm *info;
    char timestamp[30];

    time(&rawtime);
    info = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", info);

    fp = fopen("obstacle_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(fp, "%s: %s\n", timestamp, event);
    fclose(fp);
    return 0;
}

int main() {
    int sensor_value;
    int buzzer_state = 0; // 0 = off, 1 = on

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    // Initialize sensor and buzzer lines
    if (init_gpio(chip, SENSOR_PIN, GPIOD_LINE_REQUEST_DIRECTION_INPUT) < 0) {
        gpiod_chip_close(chip);
        return 1;
    }

    if (init_gpio(chip, BUZZER_PIN, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT) < 0) {
        gpiod_chip_close(chip);
        return 1;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);

    // Main loop
    while (!terminate) {
        sensor_value = read_sensor(sensor_line);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting...\n");
            break;
        }

        if (sensor_value == 0 && buzzer_state == 0) {
            // Obstacle detected, activate buzzer
            if (control_buzzer(buzzer_line, 1) < 0) {
                fprintf(stderr, "Error controlling buzzer, exiting...\n");
                break;
            }
            buzzer_state = 1;
            log_event("Obstacle detected, buzzer activated");
        } else if (sensor_value == 1 && buzzer_state == 1) {
            // Obstacle removed, deactivate buzzer
            if (control_buzzer(buzzer_line, 0) < 0) {
                fprintf(stderr, "Error controlling buzzer, exiting...\n");
                break;
            }
            buzzer_state = 0;
            log_event("Obstacle removed, buzzer deactivated");
        }

        gpiod_line_release(sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_request(sensor_line, NULL, GPIOD_LINE_REQUEST_DIRECTION_INPUT);
        gpiod_line_request(buzzer_line, NULL, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);

        struct timespec delay = {0, 100000000}; // 100 ms
        nanosleep(&delay, NULL);
    }

    // Cleanup
    gpiod_line_release(sensor_line);
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);

    return 0;
}

