#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x69
#define GPIO_ALERT 17
#define DISTANCE_THRESHOLD 10.0 // cm
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_distance(int *distance);
float convert_to_cm(int raw_distance);
int log_distance(float distance);
void trigger_alert(float distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance(int *distance) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, 0x31, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading distance data: %d\n", result);
        return -1;
    }

    *distance = (buf[0] << 8) | buf[1];
    return 0;
}

// Convert raw distance to centimeters
float convert_to_cm(int raw_distance) {
    // Assuming 1 LSB = 0.5 mm, and 1 cm = 10 mm
    return (float)raw_distance * 0.5 / 10.0;
}

// Log distance to file
int log_distance(float distance) {
    FILE *fp = fopen("distance_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm);

    fprintf(fp, "%s, %.2f cm\n", timestamp, distance);
    fclose(fp);
    return 0;
}

// Trigger alert based on distance
void trigger_alert(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(GPIO_ALERT, 1); // Set GPIO HIGH
    } else {
        gpioWrite(GPIO_ALERT, 0); // Set GPIO LOW
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(GPIO_ALERT, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting distance measurement... Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int raw_distance;
        if (read_distance(&raw_distance) == 0) {
            float distance = convert_to_cm(raw_distance);
            log_distance(distance);
            trigger_alert(distance);
        } else {
            fprintf(stderr, "Failed to read distance. Retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_ALERT, 0); // Ensure GPIO is LOW on exit
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

