// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_START 0x0000
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x013
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x078
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x014
#define VL53L1X_REG_SYSTEM_MODE_START 0x007

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance();
void log_distance(int distance);
void parking_guidance(int distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// VL53L1X initialization function
int vl53l1x_init() {
    // Check if the sensor is present
    int model_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", model_id);
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Perform software reset
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_START, 0x00) < 0) {
        fprintf(stderr, "Error writing to SYSTEM_START register\n");
        return -1;
    }
    gpioDelay(2); // Wait 2 ms

    // Start continuous back-to-back ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01) < 0) {
        fprintf(stderr, "Error writing to SYSTEM_MODE_START register\n");
        return -1;
    }

    return 0;
}

// VL53L1X read distance function
int vl53l1x_read_distance() {
    int distance = -1;
    int timeout_count = 0;

    // Wait for data ready
    while (i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS) & 0x01) {
        gpioDelay(1); // Wait 1 ms
        timeout_count++;
        if (timeout_count > 100) {
            fprintf(stderr, "Timeout waiting for data ready\n");
            return -1;
        }
    }

    // Read distance
    int range_status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
    if (range_status < 0) {
        fprintf(stderr, "Error reading range status\n");
        return -1;
    }

    distance = (range_status & 0xFF) | ((range_status >> 8) & 0xFF00); // Combine high and low bytes

    // Clear interrupt
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "Error writing to SYSTEM_INTERRUPT_CLEAR register\n");
        return -1;
    }

    return distance;
}

