#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define CH201_ADDR 0x45
#define LED_GPIO 18
#define BLINK_PERIOD_MS 100
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// CH201 Register Addresses (Example - Adjust based on datasheet)
#define CH201_REG_WHO_AM_I 0x00
#define CH201_REG_DISTANCE_HIGH 0x01
#define CH201_REG_DISTANCE_LOW 0x02
#define CH201_REG_CONFIG 0x03

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_ch201();
int read_distance(int *distance);
void set_led_frequency(int distance);
void log_data(int distance, int frequency);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// CH201 initialization function
int init_ch201() {
    // Example: Write to a configuration register (adjust based on datasheet)
    char buf[2];
    buf[0] = CH201_REG_CONFIG; // Register address
    buf[1] = 0x01; // Configuration value (example)

    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, buf, 2) == 0) {
            return 0; // Success
        }
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }
    fprintf(stderr, "Error writing to CH201 config register after %d retries.\n", MAX_RETRIES);
    return -1;
}

// Distance reading function with retries
int read_distance(int *distance) {
    char buf[1];
    char read_buf[2];
    int retries = 0;

    // Read distance high byte
    buf[0] = CH201_REG_DISTANCE_HIGH;
    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, buf, 1) == 0) {
            if (i2cReadDevice(i2c_handle, read_buf, 1) == 1) {
                *distance = (read_buf[0] << 8) | ((char)i2cReadDevice(i2c_handle, read_buf, 1)[0]);
                return 0; // Success
            }
        }
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }
    fprintf(stderr, "Error reading distance high byte after %d retries.\n", MAX_RETRIES);
    return -1;
}

// LED blink frequency setting function
void set_led_frequency(int distance) {
    // Map distance to blink frequency (50 mm -> 10 Hz, 500 mm -> 1 Hz)
    float frequency = 10.0 - ((float)distance - 50.0) / (500.0 - 50.0);

    // Clamp frequency between 0.1 Hz and 10 Hz
    if (frequency < 0.1) frequency = 0.1;
    if (frequency > 10.0) frequency = 10.0;

    // Calculate on and off times in microseconds
    int on_time_us = (int)(BLINK_PERIOD_MS * 1000000 / 20.0); // 20 Hz (10 on, 10 off)
    int off_time_us = (int)(BLINK_PERIOD_MS * 1000000 / 20.0);

    // Calculate number of half-cycles to perform in the blink period
    int num_cycles = (int)(frequency * BLINK_PERIOD_MS);

    // Calculate on and off times per cycle
    int on_time_per_cycle_us = on_time_us / num_cycles;
    int off_time_per_cycle_us = off_time_us / num_cycles;

    // Set LED state
    gpioWrite(LED_GPIO, 1);
    gpioDelay(on_time_per_cycle_us);
    gpioWrite(LED_GPIO, 0);
    gpioDelay(off_time_per_cycle_us);
}

// Data logging function
void log_data(int distance, int frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s, Distance: %d mm, Frequency: %.2f Hz\n", timestamp, distance, frequency);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize CH201 sensor
    if (init_ch201() != 0) {
        fprintf(stderr, "CH201 initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int distance;
    int frequency;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            frequency = 10.0 - ((float)distance - 50.0) / (500.0 - 50.0);
            if (frequency < 0.1) frequency = 0.1;
            if (frequency > 10.0) frequency = 10.0;

            set_led_frequency(distance);
            log_data(distance, frequency);
        } else {
            fprintf(stderr, "Failed to read distance. Retrying...\n");
        }

        gpioDelay(BLINK_PERIOD_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

