#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_DELAY_MS 50
#define POLLING_INTERVAL_MS 10

volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log an event to the file
void log_event(int sensor_id, const char *event_type) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp, skipping log entry.\n");
        return;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s, %d, %s\n", timestamp, sensor_id, event_type);
        fflush(log_file); // Ensure the data is written to the file immediately
    } else {
        fprintf(stderr, "Log file is not open, skipping log entry.\n");
    }
    free(timestamp);
}

// Function to read the sensor value with debouncing
int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay in microseconds
    return value;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int sensor1_state = read_sensor(SENSOR_1_GPIO);
    int sensor2_state = read_sensor(SENSOR_2_GPIO);

    // Main loop
    while (program_running) {
        int new_sensor1_state = read_sensor(SENSOR_1_GPIO);
        int new_sensor2_state = read_sensor(SENSOR_2_GPIO);

        if (new_sensor1_state != sensor1_state) {
            if (new_sensor1_state == 0) {
                log_event(1, "DETECTED");
            } else {
                log_event(1, "CLEARED");
            }
            sensor1_state = new_sensor1_state;
        }

        if (new_sensor2_state != sensor2_state) {
            if (new_sensor2_state == 0) {
                log_event(2, "DETECTED");
            } else {
                log_event(2, "CLEARED");
            }
            sensor2_state = new_sensor2_state;
        }

        gpioDelay(POLLING_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

