int i2c_write_read(int fd, unsigned char reg, unsigned char *data, int len);
int trigger_measurement(int fd);
int read_measurement(int fd, int *distance);
int log_data(FILE *fp, int distance);
void signal_handler(int sig);

// Helper function to write a register and read data
int i2c_write_read(int fd, unsigned char reg, unsigned char *data, int len) {
    if (fd < 0) {
        fprintf(stderr, "Error: Invalid I2C file descriptor.\n");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_DEVICE_ADDRESS) < 0) {
        fprintf(stderr, "Error: Could not set I2C slave address: %s\n", strerror(errno));
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error: Could not write to I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, data, len) != len) {
        fprintf(stderr, "Error: Could not read from I2C device: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to trigger a measurement
int trigger_measurement(int fd) {
    unsigned char trigger_data[1] = {0x01};
    if (i2c_write_read(fd, MEAS_TRIGGER_REG, trigger_data, 1) < 0) {
        fprintf(stderr, "Error: Failed to trigger measurement.\n");
        return -1;
    }
    return 0;
}

// Function to read the measurement data
int read_measurement(int fd, int *distance) {
    unsigned char status_data[1];
    unsigned char distance_data[2];
    int retries = 3;
    int delay_ms = 1;

    while (retries > 0) {
        if (i2c_write_read(fd, MEAS_STATUS_REG, status_data, 1) < 0) {
            fprintf(stderr, "Error: Failed to read status register. Retrying...\n");
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
            retries--;
            continue;
        }

        if (status_data[0] & DATA_READY_BIT) {
            if (i2c_write_read(fd, DIST_HIGH_REG, distance_data, 2) < 0) {
                fprintf(stderr, "Error: Failed to read distance data. Retrying...\n");
                usleep(delay_ms * 1000); // Exponential backoff
                delay_ms *= 2;
                retries--;
                continue;
            }

            *distance = (distance_data[0] << 8) | distance_data[1];
            return 0; // Success
        } else {
            fprintf(stderr, "Error: Data not ready yet. Waiting...\n");
            usleep(10000); // Wait 10 ms
            retries--;
        }
    }

    fprintf(stderr, "Error: Timeout waiting for data ready.\n");
    return -1; // Timeout
}

// Function to log the data to a CSV file
int log_data(FILE *fp, int distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    if (fprintf(fp, "%s,%d\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error: Could not write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,distance_mm\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        int distance;
        if (trigger_measurement(i2c_fd) == 0 && read_measurement(i2c_fd, &distance) == 0) {
            if (log_data(log_file, distance) != 0) {
                fprintf(stderr, "Error: Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read distance.\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000); // Sleep for 500 ms
    }

    // Clean up
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

