// Define the I2C bus and address for the MLX75030 sensor
#define I2C_BUS 1
#define MLX75030_ADDR 0x4C

// Define the register address for the distance measurement (replace with actual value)
#define DISTANCE_REG 0x00 // Example address, check datasheet

// Define the retry count and delay for I2C transactions
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10

// Global variable to store the I2C handle
int i2c_handle = -1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read the distance from the MLX75030 sensor
int read_distance() {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < I2C_RETRY_COUNT) {
        result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);
        if (result >= 0) {
            // Combine the two bytes into a single distance value
            int distance = (buf[0] << 8) | buf[1];
            return distance;
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "I2C read failed after %d retries.\n", I2C_RETRY_COUNT);
    return -1; // Indicate an error
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

