    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop to read and log the distance measurement
    while (1) {
        int distance = read_distance();
        if (distance >= 0) {
            // Get the current timestamp
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

            // Log the distance measurement with the timestamp
            printf("Timestamp: %ld ms, Distance: %d\n", timestamp_ms, distance);
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }

        // Delay for 100 ms
        gpioDelay(100 * 1000); // Delay in microseconds
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

