void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the VL53L4CX sensor
int init_vl53l4cx() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, VL53L4CX_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write soft reset command.\n");
        return -1;
    }
    gpioDelay(10000); // 10 ms delay

    // Start ranging
    if (i2cWriteByteData(i2c_handle, VL53L4CX_START_RANGING, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to start ranging.\n");
        return -1;
    }
    gpioDelay(10000); // 10 ms delay

    return 0;
}

// Function to read the distance from the VL53L4CX sensor
int read_distance(int *distance) {
    int status;
    int high_byte, low_byte;

    // Poll interrupt status
    status = i2cReadByteData(i2c_handle, VL53L4CX_INTERRUPT_STATUS);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to read interrupt status.\n");
        return -1;
    }

    if (status & 0x01) {
        // Read distance data
        high_byte = i2cReadByteData(i2c_handle, VL53L4CX_DISTANCE_HIGH);
        if (high_byte < 0) {
            fprintf(stderr, "Error: Failed to read high byte of distance.\n");
            return -1;
