        low_byte = i2cReadByteData(i2c_handle, VL53L4CX_DISTANCE_LOW);
        if (low_byte < 0) {
            fprintf(stderr, "Error: Failed to read low byte of distance.\n");
            return -1;
        }

        *distance = (high_byte << 8) | low_byte;
        return 0;
    } else {
        return -1; // Interrupt not set
    }
