void activate_buzzer(int gpio);
void deactivate_buzzer(int gpio);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// VL53L1X initialization function
int vl53l1x_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, VL53L1X_SOFT_RESET, 0x01) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(10000); // Wait 10 ms

    // Set I2C address
    if (i2cWriteByteData(i2c_handle, VL53L1X_I2C_SLAVE_DEVICE_ADDRESS, VL53L1X_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to set I2C address\n");
        return -1;
    }

    // Start continuous ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_SYSTEM_MODE_START, 0x04) < 0) {
        fprintf(stderr, "Error: Failed to start continuous ranging\n");
        return -1;
    }

    return 0;
}

// VL53L1X distance reading function
int vl53l1x_read_distance(int *distance) {
    int distance_mm;

    // Read distance from the sensor
    distance_mm = i2cReadWordData(i2c_handle, VL53L1X_RESULT_FINAL_CROSSTALK_CORRECTED_DISTANCE_MM);
    if (distance_mm < 0) {
        fprintf(stderr, "Error: Failed to read distance\n");
        return -1;
    }

    *distance = distance_mm;
    return 0;
}

// Buzzer activation function
void activate_buzzer(int gpio) {
    gpioWrite(gpio, 1); // Turn buzzer on
}

// Buzzer deactivation function
void deactivate_buzzer(int gpio) {
    gpioWrite(gpio, 0); // Turn buzzer off
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    int distance;
    int buzzer_active = 0;

    // Main loop
    while (!terminate) {
        // Read distance from VL53L1X sensor
        if (vl53l1x_read_distance(&distance) == 0) {
            printf("Distance: %d mm\n", distance);

            // Check if distance is below threshold
            if (distance < DISTANCE_THRESHOLD && !buzzer_active) {
                activate_buzzer(BUZZER_GPIO);
                buzzer_active = 1;
                gpioDelay(BUZZER_DURATION * 1000); // Keep buzzer on for 500 ms
                deactivate_buzzer(BUZZER_GPIO);
                buzzer_active = 0; // Reset buzzer state
            } else if (distance >= DISTANCE_THRESHOLD && buzzer_active) {
                deactivate_buzzer(BUZZER_GPIO);
                buzzer_active = 0; // Reset buzzer state
            }
        } else {
            fprintf(stderr, "Error: Failed to read distance, attempting re-initialization\n");
            // Attempt to re-initialize the sensor
            if (vl53l1x_init() < 0) {
                fprintf(stderr, "Error: VL53L1X re-initialisation failed\n");
            }
        }

        gpioDelay(500000); // Wait 500 ms
    }

    // Clean up resources
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

