#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17

// Define constants
#define SPEED_OF_SOUND 343.0  // m/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define MIN_PULSE_WIDTH 1.0   // ms
#define MAX_PULSE_WIDTH 2.0   // ms
#define TIMEOUT_US 50000       // 50 ms

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
void signal_handler(int signal);
void log_data(float distance, int angle);
float measure_distance();
int map_distance_to_angle(float distance);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
    gpioServo(SERVO_PIN, 0); // Stop the servo
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to log data to a file
void log_data(float distance, int angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f cm, %d degrees\n", timestamp, distance, angle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to measure distance using the HC-SR04 sensor
float measure_distance() {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Measure echo pulse width with timeout
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout: Echo low for too long\n");
            return -1.0; // Indicate timeout error
        }
    }
    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout: Echo high for too long\n");
            return -1.0; // Indicate timeout error
        }
    }
    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Convert us to s, divide by 2 for one-way distance

    return distance;
}

// Function to map distance to servo angle
int map_distance_to_angle(float distance) {
    if (distance < MIN_DISTANCE) {
        return 0; // Closest
    } else if (distance > MAX_DISTANCE) {
        return 180; // Farthest
    } else {
        // Linear mapping
        return (int)(((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE)) * 180.0);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Initialize log file
    log_file = fopen("sensor_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        float distance = measure_distance();
        int angle;

        if (distance > 0) {
            angle = map_distance_to_angle(distance);
            gpioServo(SERVO_PIN, angle * 1000 / 180 + 1000); // Convert angle to pulse width (1000-2000 us)
            log_data(distance, angle);
        } else {
            fprintf(stderr, "Error: Invalid distance measurement\n");
        }

        gpioDelay(200); // 200 ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioServo(SERVO_PIN, 0); // Stop the servo
    fclose(log_file);
    gpioTerminate();

    return 0;
}

