#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ipc.h>
#include <sys/types.h>
#include <sys/msg.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 23
#define MESSAGE_QUEUE_KEY 1234
#define MESSAGE_QUEUE_SIZE 10
#define DISTANCE_THRESHOLD 100 // mm
#define POLLING_INTERVAL_MS 50

// VL53L1X Register Addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_START 0x0000
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0003
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Global Variables
int i2c_handle;
int message_queue_id;

// Structure for message queue
struct message {
    long mtype;          // Message type
    int distance;        // Distance in mm
};

// Function Prototypes
int init_i2c();
int check_model_id();
int software_reset();
int configure_timing_budget();
int start_ranging();
int read_distance();
void control_buzzer(int distance);
void send_distance(int distance);
void cleanup(int signal);

// Signal handler for Ctrl+C
void cleanup(int signal) {
    printf("\nCleaning up and exiting...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (message_queue_id >= 0) {
        msgctl(message_queue_id, IPC_RMID, NULL);
    }
    gpioTerminate();
    exit(0);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Check VL53L1X Model ID
int check_model_id() {
    char model_id;
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 1) {
        fprintf(stderr, "Error reading model ID\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }
    return 0;
}

// Software Reset
int software_reset() {
    char reset_cmd[2] = {0x00, 0x01};
    if (i2cWriteI2CBlockData(i2c_handle, VL53L1X_REG_SYSTEM_START, &reset_cmd[0], 1) != 1) {
        fprintf(stderr, "Error writing reset command 1\n");
        return -1;
    }
    gpioDelay(10000); // 10 ms delay
    if (i2cWriteI2CBlockData(i2c_handle, VL53L1X_REG_SYSTEM_START, &reset_cmd[1], 1) != 1) {
        fprintf(stderr, "Error writing reset command 2\n");
        return -1;
    }
    gpioDelay(10000); // 10 ms delay
    return 0;
}

// Configure Timing Budget
int configure_timing_budget() {
    char timing_budget_msb = 50;
    char timing_budget_lsb = 0;
    char timing_budget[2];
    timing_budget[0] = timing_budget_msb;
    timing_budget[1] = timing_budget_lsb;

    if (i2cWriteI2CBlockData(i2c_handle, 0x002D, timing_budget, 2) != 2) {
        fprintf(stderr, "Error writing timing budget\n");
        return -1;
    }
    return 0;
}

// Start Ranging
int start_ranging() {
    char start_ranging_cmd = 0x01;
    if (i2cWriteI2CBlockData(i2c_handle, VL53L1X_REG_SYSTEM_START, &start_ranging_cmd, 1) != 1) {
        fprintf(stderr, "Error starting ranging\n");
        return -1;
    }
    return 0;
}

// Read Distance
int read_distance() {
    char range_msb, range_lsb;
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &range_msb, 1) != 1) {
        fprintf(stderr, "Error reading range MSB\n");
        return -1;
    }
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 1, &range_lsb, 1) != 1) {
        fprintf(stderr, "Error reading range LSB\n");
        return -1;
    }

    int distance = (range_msb << 8) | range_lsb;
    return distance;
}

// Control Buzzer
void control_buzzer(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(BUZZER_GPIO, 1); // Activate buzzer
    } else {
        gpioWrite(BUZZER_GPIO, 0); // Deactivate buzzer
    }
}

// Send Distance to Message Queue
void send_distance(int distance) {
    struct message msg;
    msg.mtype = 1; // Message type
    msg.distance = distance;

    if (msgsnd(message_queue_id, &msg, sizeof(msg) - sizeof(long), 0) == -1) {
        fprintf(stderr, "Error sending message\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Check Model ID
    if (check_model_id() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Software Reset
    if (software_reset() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure Timing Budget
    if (configure_timing_budget() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Start Ranging
    if (start_ranging() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure Buzzer GPIO
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Initialize Message Queue
    message_queue_id = msgget(MESSAGE_QUEUE_KEY, 0666 | IPC_CREAT);
    if (message_queue_id == -1) {
        fprintf(stderr, "Error getting message queue\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Main loop
    while (1) {
        // Poll Data Ready Bit
        char range_status;
        if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, &range_status, 1) != 1) {
            fprintf(stderr, "Error polling data ready bit\n");
            continue; // Continue to the next iteration
        }

        if (range_status & 0x01) {
            // Read Distance
            int distance = read_distance();
            if (distance != -1) {
                // Control Buzzer
                control_buzzer(distance);

                // Send Distance to Message Queue
                send_distance(distance);

                // Print Distance
                printf("Distance: %d mm\n", distance);
            } else {
                fprintf(stderr, "Error reading distance\n");
            }
        }

        gpioDelay(POLLING_INTERVAL_MS * 1000); // Delay for polling interval
    }

    return 0;
}

