    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 1, &range_lsb, 1) != 1) {
        fprintf(stderr, "Error reading range LSB\n");
        return -1;
    }

    int distance = (range_msb << 8) | range_lsb;
    return distance;
}

// Control Buzzer
void control_buzzer(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(BUZZER_GPIO, 1); // Activate buzzer
    } else {
        gpioWrite(BUZZER_GPIO, 0); // Deactivate buzzer
    }
}

// Send Distance to Message Queue
void send_distance(int distance) {
    struct message msg;
    msg.mtype = 1; // Message type
    msg.distance = distance;

    if (msgsnd(message_queue_id, &msg, sizeof(msg) - sizeof(long), 0) == -1) {
        fprintf(stderr, "Error sending message\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Check Model ID
    if (check_model_id() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Software Reset
    if (software_reset() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure Timing Budget
    if (configure_timing_budget() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Start Ranging
    if (start_ranging() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure Buzzer GPIO
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Initialize Message Queue
    message_queue_id = msgget(MESSAGE_QUEUE_KEY, 0666 | IPC_CREAT);
    if (message_queue_id == -1) {
        fprintf(stderr, "Error getting message queue\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Main loop
    while (1) {
        // Poll Data Ready Bit
        char range_status;
        if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, &range_status, 1) != 1) {
            fprintf(stderr, "Error polling data ready bit\n");
            continue; // Continue to the next iteration
        }

        if (range_status & 0x01) {
            // Read Distance
            int distance = read_distance();
            if (distance != -1) {
                // Control Buzzer
                control_buzzer(distance);

                // Send Distance to Message Queue
                send_distance(distance);

                // Print Distance
                printf("Distance: %d mm\n", distance);
            } else {
                fprintf(stderr, "Error reading distance\n");
            }
        }

        gpioDelay(POLLING_INTERVAL_MS * 1000); // Delay for polling interval
    }

    return 0;
}

