#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 50000       // 50ms timeout
#define BUZZER_ON_THRESHOLD 30 // cm
#define BUZZER_OFF_THRESHOLD 31 // cm

// Global variables
volatile int echo_start_tick = 0;
volatile int echo_end_tick = 0;
volatile int echo_valid = 0;
volatile int buzzer_state = 0; // 0 = off, 1 = on

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
float calculate_distance(uint32_t pulse_width);
void control_buzzer(float distance);
void signal_handler(int signal);

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate();           // Terminate pigpio
    exit(0);
}

// Function to send a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
        echo_valid = 0; // Reset validity flag
    } else if (level == 0) {
        echo_end_tick = tick;
        echo_valid = 1; // Set validity flag
    }
}

// Function to calculate distance in centimeters
float calculate_distance(uint32_t pulse_width) {
    if (pulse_width < TIMEOUT_US) {
        fprintf(stderr, "Error: Timeout occurred (pulse width: %u us)\n", pulse_width);
        return -1.0; // Indicate timeout error
    }

    float time_taken = (float)pulse_width / 1000000.0; // Time in seconds
    float distance = (time_taken * SPEED_OF_SOUND) / 2.0;

    if (distance < 2.0 || distance > 400.0) {
        fprintf(stderr, "Error: Invalid distance reading (distance: %.2f cm)\n", distance);
        return -1.0; // Indicate invalid reading
    }

    return distance;
}

// Function to control the buzzer
void control_buzzer(float distance) {
    if (distance < BUZZER_ON_THRESHOLD && buzzer_state == 0) {
        gpioWrite(BUZZER_PIN, 1); // Turn on buzzer
        buzzer_state = 1;
        printf("Buzzer ON (Distance: %.2f cm)\n", distance);
    } else if (distance >= BUZZER_OFF_THRESHOLD && buzzer_state == 1) {
        gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
        buzzer_state = 0;
        printf("Buzzer OFF (Distance: %.2f cm)\n", distance);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register interrupt callback for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set alert function for echo pin\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        trigger_pulse();
        gpioDelay(100); // Wait 100ms

        if (echo_valid) {
            uint32_t pulse_width = echo_end_tick - echo_start_tick;
            float distance = calculate_distance(pulse_width);

            if (distance >= 0.0) {
                printf("Distance: %.2f cm\n", distance);
            } else {
                fprintf(stderr, "Error: Invalid distance calculation\n");
            }
        } else {
            fprintf(stderr, "Error: No valid echo received\n");
        }

        control_buzzer(distance);
    }

    return 0; // This line will never be reached due to the infinite loop
}

