#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define OPEN_ANGLE 1000
#define CLOSED_ANGLE 1500
#define DISTANCE_THRESHOLD 200 // mm
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "gate_control"
#define MQTT_CLIENT_ID "gate_controller"
#define MQTT_KEEPALIVE 60

// Global variables
int i2c_handle;
FILE *log_file;
struct mosquitto *mqtt_client = NULL;

// Function prototypes
int init_i2c();
int init_gpio();
int init_mqtt();
int read_distance();
void set_servo_angle(int angle);
void open_gate();
void close_gate();
void log_event(const char *event);
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result);
void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc);
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void signal_handler(int signal);

// VL53L1X register addresses (example, adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0050
#define VL53L1X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0070
#define VL53L1X_REG_SYSTEM_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// VL53L1X Initialization Sequence (Simplified)
int init_vl53l1x() {
    // Example initialization sequence (adjust as needed)
    char data[2];

    // Reset the sensor
    data[0] = VL53L1X_REG_SYSTEM_START;
    data[1] = 0x01; // Software reset
    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        log_event("Error: VL53L1X reset failed");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    // Check sensor ID (optional)
    data[0] = VL53L1X_REG_IDENTIFICATION_MODEL_ID;
    if (i2cWriteDevice(i2c_handle, data, 1) != 0) {
        log_event("Error: Failed to write to VL53L1X_REG_IDENTIFICATION_MODEL_ID");
        return -1;
    }
    char sensor_id;
    if (i2cReadDevice(i2c_handle, &sensor_id, 1) != 0) {
        log_event("Error: Failed to read VL53L1X_REG_IDENTIFICATION_MODEL_ID");
        return -1;
    }

    if (sensor_id != 0xEA) {
        log_event("Error: Incorrect VL53L1X sensor ID");
        return -1;
    }

    // Configure ranging (example)
    data[0] = VL53L1X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI;
    data[1] = 0x00; // Example value
    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        log_event("Error: Failed to write to VL53L1X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI");
        return -1;
    }

    data[0] = VL53L1X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI;
    data[1] = 0x00; // Example value
    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        log_event("Error: Failed to write to VL53L1X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI");
        return -1;
    }

    // Start ranging
    data[0] = VL53L1X_REG_SYSTEM_START;
    data[1] = 0x03; // Start ranging
    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        log_event("Error: Failed to start ranging");
        return -1;
    }

    return 0;
}

int main() {
    // Initialize
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_mqtt() != 0) {
        fprintf(stderr, "MQTT initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int distance = read_distance();
        if (distance > 0) {
            printf("Distance: %d mm\n", distance);
            if (distance < DISTANCE_THRESHOLD) {
                open_gate();
            } else {
                close_gate();
            }
        } else {
            log_event("Error: Failed to read distance");
        }

        gpioDelay(100000); // 100ms delay
    }

    return 0;
}

int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

int init_gpio() {
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, 50); // 50Hz
    gpioSetPWMrange(SERVO_PIN, 20000); // Range for 20ms period (50Hz)
    return 0;
}

int init_mqtt() {
    mosquitto_lib_init();

    mqtt_client = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mqtt_client) {
        fprintf(stderr, "Error: Out of memory.\n");
        return -1;
    }

    mosquitto_connect_callback_set(mqtt_client, mqtt_connect_callback);
    mosquitto_disconnect_callback_set(mqtt_client, mqtt_disconnect_callback);
    mosquitto_message_callback_set(mqtt_client, mqtt_message_callback);

    int rc = mosquitto_connect(mqtt_client, MQTT_BROKER, MQTT_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: Could not connect to MQTT broker: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mqtt_client);
        mosquitto_lib_cleanup();
        return -1;
    }

    rc = mosquitto_loop_start(mqtt_client);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: Could not start MQTT loop: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mqtt_client);
        mosquitto_lib_cleanup();
        return -1;
    }

    return 0;
}

int read_distance() {
    char data[1];
    char result[2];
    int distance = -1;
    int retries = 3;

    data[0] = VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0;

    while (retries > 0) {
        if (i2cWriteDevice(i2c_handle, data, 1) != 0) {
            log_event("Error: Failed to write to VL53L1X register");
            retries--;
            gpioDelay(10000); // 10ms delay
            continue;
        }

        if (i2cReadDevice(i2c_handle, result, 2) == 0) {
            distance = (result[0] << 8) | result[1];
            break;
        } else {
            log_event("Error: Failed to read distance from VL53L1X");
            retries--;
            gpioDelay(10000); // 10ms delay
        }
    }

    if (distance == -1) {
        log_event("Error: Failed to read distance after multiple retries");
    }

    return distance;
}

void set_servo_angle(int angle) {
    gpioPWM(SERVO_PIN, angle);
}

void open_gate() {
    log_event("Gate opening");
    set_servo_angle(OPEN_ANGLE);
    gpioDelay(500000); // 500ms delay
}

void close_gate() {
    log_event("Gate closing");
    set_servo_angle(CLOSED_ANGLE);
    gpioDelay(500000); // 500ms delay
}

void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (!result) {
        printf("Connected to MQTT broker\n");
    } else {
        fprintf(stderr, "MQTT connection error: %s\n", mosquitto_connack_string(result));
    }
}

void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    printf("Disconnected from MQTT broker\n");
}

void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        printf("Received message on topic %s: %s\n", message->topic, (char *)message->payload);
        if (strcmp(message->topic, MQTT_TOPIC) == 0) {
            if (strcmp((char *)message->payload, "force_open") == 0) {
                open_gate();
            } else if (strcmp((char *)message->payload, "force_close") == 0) {
                close_gate();
            } else if (strcmp((char *)message->payload, "status_request") == 0) {
                int distance = read_distance();
                if (distance > 0) {
                    char payload[50];
                    snprintf(payload, sizeof(payload), "Gate is %s", (distance < DISTANCE_THRESHOLD) ? "open" : "closed");
                    int rc = mosquitto_publish(mosq, NULL, "gate_status", strlen(payload), payload, 0, false);
                    if (rc != MOSQ_ERR_SUCCESS) {
                        fprintf(stderr, "Error publishing status: %s\n", mosquitto_strerror(rc));
                    }
                } else {
                    int rc = mosquitto_publish(mosq, NULL, "gate_status", strlen("Error reading distance"), "Error reading distance", 0, false);
                    if (rc != MOSQ_ERR_SUCCESS) {
                        fprintf(stderr, "Error publishing status: %s\n", mosquitto_strerror(rc));
                    }
                }
            }
        }
    }
}

void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    log_event("Program terminated");

    // Close gate
    close_gate();

    // Stop servo
    set_servo_angle(0);

    // Close I2C
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    // Disconnect MQTT
    if (mqtt_client) {
        mosquitto_disconnect(mqtt_client);
        mosquitto_destroy(mqtt_client);
        mosquitto_lib_cleanup();
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    exit(0);
}

