#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define TIMEOUT_US 30000       // Timeout in microseconds
#define MIN_PULSE_WIDTH_US 100 // Minimum pulse width in microseconds
#define MAX_PULSE_WIDTH_US TIMEOUT_US // Maximum pulse width in microseconds
#define MEASUREMENT_INTERVAL_MS 200 // Measurement interval in milliseconds
#define TIMEOUT_MS 60           // Timeout in milliseconds

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold timestamp data
typedef struct {
    uint32_t rising_edge;
    uint32_t falling_edge;
} timestamp_t;

// Function prototypes
int initialize_gpio();
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick, void *user_data);
float calculate_distance(uint32_t pulse_width_us);
void log_distance(float distance_cm);
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN); // Enable pull-down resistor

    return 0;
}

// Function to generate a 10 microsecond trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 us pulse
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick, void *user_data) {
    static timestamp_t last_tick = 0;
    static int first_tick = 0;
    static int valid_pulse = 0;
    static uint32_t last_valid_tick = 0;
    static uint32_t last_invalid_tick = 0;
    static int timeout_count = 0;

    if (level == 1) {
        // Rising edge
        if (first_tick == 0) {
            first_tick = tick;
        }
        last_tick = tick;
    } else if (level == 0) {
        // Falling edge
        if (first_tick != 0) {
            uint32_t pulse_width = tick - first_tick;

            if (pulse_width >= MIN_PULSE_WIDTH_US && pulse_width <= MAX_PULSE_WIDTH_US) {
                if (!valid_pulse) {
                    valid_pulse = 1;
                    last_valid_tick = tick;
                }
            } else {
                if (valid_pulse) {
                    valid_pulse = 0;
                    last_valid_tick = 0;
                }
                if (last_invalid_tick == 0) {
                    last_invalid_tick = tick;
                } else {
                    if (last_invalid_tick > last_valid_tick) {
                        last_invalid_tick = last_valid_tick;
                    }
                    if (last_invalid_tick < last_valid_tick) {
                        last_invalid_tick = last_valid_tick;
                    }
                    if (last_invalid_tick == last_valid_tick) {
                        last_invalid_tick = last_valid_tick;
                    }
                }
            }
        }
    }
}

// Function to calculate distance in centimeters
float calculate_distance(uint32_t pulse_width_us) {
    return (float)pulse_width_us * SPEED_OF_SOUND / 2.0;
}

// Function to log distance with timestamp
void log_distance(float distance_cm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    printf("%s Distance: %.2f cm\n", timestamp, distance_cm);

    if (log_file != NULL) {
        fprintf(log_file, "%s Distance: %.2f cm\n", timestamp, distance_cm);
        fflush(log_file); // Ensure data is written to file immediately
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up callback function
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Main loop
    while (running) {
        trigger_pulse();

        // Wait for echo or timeout
        int timeout = 0;
        uint32_t last_tick = gpioTick();
        while (!((gpioRead(ECHO_PIN) == 0) || (gpioTick() - last_tick) > TIMEOUT_MS)) {
            gpioDelay(1); // Small delay to avoid busy-waiting
            if (timeout == 0) {
                timeout = 1;
            } else {
                timeout++;
            }
            if (timeout > TIMEOUT_MS) {
                break;
            }
        }

        if (timeout > TIMEOUT_MS) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);
            fprintf(stderr, "%s: Timeout occurred! No echo received within %d ms\n", timestamp, TIMEOUT_MS);
            fprintf(log_file, "%s: Timeout occurred! No echo received within %d ms\n", timestamp, TIMEOUT_MS);
            fflush(log_file);
        } else {
            // Calculate pulse width and distance
            uint32_t pulse_width = gpioTick() - last_tick;
            float distance = calculate_distance(pulse_width);

            // Log distance
            log_distance(distance);
        }

        gpioDelay(MEASUREMENT_INTERVAL_MS); // Wait before next measurement
    }

    // Clean up (should not reach here if signal handler works correctly)
    fclose(log_file);
    gpioTerminate();

    return 0;
}

