#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_OPEN 18
#define GPIO_CLOSE 19
#define DISTANCE_THRESHOLD 200 // mm
#define POLLING_INTERVAL 500 // ms
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345
#define LOG_FILE "gate_events.log"

// VL53L1X Register Addresses (Example - Refer to Datasheet for correct values)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0050
#define VL53L1X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0070
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG 0x0081
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance();
void control_gate(int distance);
void log_event(const char *event);
void send_data_to_server(int distance);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// VL53L1X Initialization
int vl53l1x_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x00, 0x01) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(10000); // Wait 10 ms

    // Check sensor ID (Example - Refer to Datasheet for correct value)
    int sensor_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (sensor_id < 0) {
        fprintf(stderr, "Error: Failed to read sensor ID\n");
        return -1;
    }
    if (sensor_id != 0xEA) {
        fprintf(stderr, "Error: Incorrect sensor ID: 0x%02x\n", sensor_id);
        return -1;
    }

    // Configure timing budget (Example - Refer to Datasheet for correct values)
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write pre-range timeout\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write final range timeout\n");
        return -1;
    }

    // Start ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG, 0x04) < 0) {
        fprintf(stderr, "Error: Failed to start ranging\n");
        return -1;
    }

    return 0;
}

// VL53L1X Read Distance
int vl53l1x_read_distance() {
    // Read range status
    int range_status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
    if (range_status < 0) {
        fprintf(stderr, "Error: Failed to read range status\n");
        return -1;
    }

    // Read distance (16-bit register)
    int distance = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (distance < 0) {
        fprintf(stderr, "Error: Failed to read distance\n");
        return -1;
    }

    return distance;
}

// Gate Control
void control_gate(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(GPIO_OPEN, 0);
        gpioWrite(GPIO_CLOSE, 1);
        log_event("Gate Closed");
    } else {
        gpioWrite(GPIO_OPEN, 1);
        gpioWrite(GPIO_CLOSE, 0);
        log_event("Gate Opened");
    }
}

// Log Event
void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure immediate write
}

// Send Data to Server
void send_data_to_server(int distance) {
    int sockfd;
    struct sockaddr_in servaddr;
    char buffer[1024];

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        fprintf(stderr, "Error: Socket creation failed\n");
        return;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &servaddr.sin_addr) <= 0) {
        fprintf(stderr, "Error: Invalid address/ Address not supported\n");
        close(sockfd);
        return;
    }

    snprintf(buffer, sizeof(buffer), "%d", distance);

    if (sendto(sockfd, (const char *)buffer, strlen(buffer), 0, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        fprintf(stderr, "Error: Sendto failed\n");
    }

    close(sockfd);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GPIO_OPEN, PI_OUTPUT);
    gpioSetMode(GPIO_CLOSE, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = vl53l1x_read_distance();
        if (distance >= 0) {
            control_gate(distance);
            send_data_to_server(distance);
        } else {
            fprintf(stderr, "Error: Failed to read distance, retrying...\n");
        }

        gpioDelay(POLLING_INTERVAL);
    }

    // Cleanup
    gpioWrite(GPIO_OPEN, 0);
    gpioWrite(GPIO_CLOSE, 0);
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

