// Define GPIO pins
#define MOTOR_FORWARD_PIN 17
#define MOTOR_BACKWARD_PIN 18
#define TRIGGER_PIN 24

// Define I2C bus and address
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29

// Define distance thresholds (in mm)
#define MIN_DISTANCE 100
#define MAX_DISTANCE 300

// Define VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x0110
#define VL53L1X_REG_SYSRANGE_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Global variables
int i2c_handle;
volatile int running = 1;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance();
void control_motor(int distance);
void trigger_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Function to initialize the VL53L1X sensor
int vl53l1x_init() {
    // Check sensor ID
    int sensor_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (sensor_id < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", sensor_id);
        return -1;
    }
    if (sensor_id != 0xEACC) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    // Start continuous ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error starting continuous ranging\n");
        return -1;
    }

    return 0;
}

// Function to read the distance from the VL53L1X sensor
int vl53l1x_read_distance() {
    int distance = -1;
    int retries = 3;
    int delay_ms = 10;

    while (retries > 0) {
        // Wait for data ready
        int timeout_count = 0;
        while (i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS) & 0x01) {
            gpioDelay(1); // Wait 1 ms
            timeout_count++;
            if (timeout_count > 1000) { // 1 second timeout
                fprintf(stderr, "Timeout waiting for data ready\n");
                break;
            }
        }

        if (timeout_count > 1000) {
            fprintf(stderr, "Timeout waiting for data ready\n");
            continue; // Retry
        }

        // Read distance
        distance = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
        if (distance >= 0) {
            break; // Success
        } else {
            fprintf(stderr, "Error reading distance: %d\n", distance);
            retries--;
            gpioDelay(delay_ms);
            delay_ms *= 2; // Exponential backoff
        }
    }

    if (distance < 0) {
        fprintf(stderr, "Failed to read distance after multiple retries\n");
    }

    return distance;
}

// Function to control the motor based on the distance
void control_motor(int distance) {
    static int motor_state = 0; // 0: stop, 1: forward, 2: backward

    if (distance < MIN_DISTANCE) {
        if (motor_state != 1) {
            gpioWrite(MOTOR_FORWARD_PIN, 1);
            gpioWrite(MOTOR_BACKWARD_PIN, 0);
            motor_state = 1;
            printf("Moving forward\n");
        }
    } else if (distance > MAX_DISTANCE) {
        if (motor_state != 2) {
            gpioWrite(MOTOR_FORWARD_PIN, 0);
            gpioWrite(MOTOR_BACKWARD_PIN, 1);
            motor_state = 2;
            printf("Moving backward\n");
        }
    } else {
        if (motor_state != 0) {
            gpioWrite(MOTOR_FORWARD_PIN, 0);
            gpioWrite(MOTOR_BACKWARD_PIN, 0);
            motor_state = 0;
            printf("Stopping\n");
        }
    }
}

// Interrupt service routine for the trigger pin
void trigger_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge
        int distance = vl53l1x_read_distance();
        if (distance >= 0) {
            control_motor(distance);
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() < 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_FORWARD_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD_PIN, PI_OUTPUT);
    gpioSetMode(TRIGGER_PIN, PI_INPUT);
    gpioSetPullUpDown(TRIGGER_PIN, PI_PUD_UP); // Enable pull-up resistor

    // Set interrupt service routine for trigger pin
    gpioSetISRFuncEx(TRIGGER_PIN, RISING_EDGE, 0, trigger_callback, NULL);

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("VL53L1X distance sensor and motor control program started\n");

    // Main loop
    while (running) {
        // Do other tasks here if needed
        gpioDelay(100); // Sleep for 100 ms
    }

    // Clean up resources
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated\n");
    return 0;
}

