// Function to read a register from the MPR121
int mpr121_read_register(int fd, uint8_t reg, uint8_t *value) {
    int retries = I2C_RETRY_COUNT;
    int result;

    while (retries > 0) {
        result = i2c_smbus_read_byte_data(fd, reg);
        if (result >= 0) {
            *value = (uint8_t)result;
            return 0; // Success
        }
        retries--;
        usleep(I2C_RETRY_DELAY * 1000); // Delay in microseconds
    }

    fprintf(stderr, "Error: Failed to read register 0x%02X after multiple retries.\n", reg);
    return -1; // Failure
}

// Function to write a register to the MPR121
int mpr121_write_register(int fd, uint8_t reg, uint8_t value) {
    int retries = I2C_RETRY_COUNT;
    int result;

    while (retries > 0) {
        result = i2c_smbus_write_byte_data(fd, reg, value);
        if (result == 0) {
            return 0; // Success
        }
        retries--;
        usleep(I2C_RETRY_DELAY * 1000); // Delay in microseconds
    }

    fprintf(stderr, "Error: Failed to write register 0x%02X with value 0x%02X after multiple retries.\n", reg, value);
    return -1; // Failure
}

// Function to read the touch status from the MPR121
int mpr121_read_touch_status(int fd, uint16_t *touch_status) {
    uint8_t touch_status_l, touch_status_h;

    if (mpr121_read_register(fd, MPR121_TOUCHSTATUS_L, &touch_status_l) != 0) {
        return -1;
    }
    if (mpr121_read_register(fd, MPR121_TOUCHSTATUS_H, &touch_status_h) != 0) {
        return -1;
    }

    *touch_status = (touch_status_h << 8) | touch_status_l;
    return 0;
}

// Function to set the LED pattern
void set_led_pattern(int gpio_pin, int pattern) {
    if (gpio_write(gpio_pin, (pattern & 0x01) ? 1 : 0) != 0) {
        fprintf(stderr, "Error setting LED %d.\n", gpio_pin);
    }
    if (gpio_write(gpio_pin + 1, (pattern & 0x02) ? 1 : 0) != 0) {
        fprintf(stderr, "Error setting LED %d.\n", gpio_pin + 1);
    }
    if (gpio_write(gpio_pin + 2, (pattern & 0x04) ? 1 : 0) != 0) {
        fprintf(stderr, "Error setting LED %d.\n", gpio_pin + 2);
    }
    if (gpio_write(gpio_pin + 3, (pattern & 0x08) ? 1 : 0) != 0) {
        fprintf(stderr, "Error setting LED %d.\n", gpio_pin + 3);
    }
}

// Function to log an event
void log_event(int electrode, int pattern) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Electrode %d touched, LED pattern %d\n", timestamp, electrode, pattern);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    uint16_t touch_status;
    uint8_t electrode_status;
    int electrode_number;
    int led_pattern;
    int debounce_count = 0;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_fd) != 0) {
        fprintf(stderr, "Error initializing MPR121 sensor.\n");
        close(i2c_fd);
        return 1;
    }

    // Initialize GPIO
    if (gpio_init() != 0) {
        fprintf(stderr, "Error initializing GPIO lines.\n");
        close(i2c_fd);
        return 1;
    }

    // Set GPIO direction to output
    gpio_set_direction(LED1_PIN, "out");
    gpio_set_direction(LED2_PIN, "out");
    gpio_set_direction(LED3_PIN, "out");
    gpio_set_direction(LED4_PIN, "out");

    // Main loop
    while (program_running) {
        // Read touch status
        if (mpr121_read_touch_status(i2c_fd, &touch_status) == 0) {
            // Debounce and log events
            electrode_status = touch_status;
            for (electrode_number = 0; electrode_number < 12; electrode_number++) {
                if ((electrode_status & (1 << electrode_number)) && (debounce_count == 0)) {
                    led_pattern = (electrode_number == 0) ? LED_PATTERN_1 : ((electrode_number == 1) ? LED_PATTERN_2 : ((electrode_number == 2) ? LED_PATTERN_3 : LED_PATTERN_4));
                    set_led_pattern(LED1_PIN, led_pattern);
                    log_event(electrode_number, led_pattern);
                    debounce_count = DEBOUNCE_DELAY / 10; // Debounce for 50ms
                } else if ((electrode_status & (1 << electrode_number)) == 0 && (debounce_count > 0)) {
                    debounce_count--;
                } else {
                    debounce_count = 0;
                }
            }

            // Check if no electrodes are active
            if (debounce_count == 0 && (touch_status == 0)) {
                log_event(-1, 0); // Log no electrode active
            }
        } else {
            fprintf(stderr, "Error reading touch status.\n");
        }

        usleep(DEBOUNCE_DELAY * 1000); // Delay in microseconds
    }

    // Clean up
    close(i2c_fd);
    gpiod_line_release(led1_line);
    gpiod_line_release(led2_line);
    gpiod_line_release(led3_line);
    gpiod_line_release(led4_line);
    gpiod_chip_close(gpio_chip);

    return 0;
}

