// Function to initialize the MPR121
int mpr121_init() {
    // Verify device ID
    int device_id = i2cReadByteData(i2c_handle, 0x00); // Read device ID
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", device_id);
        return -1;
    }
    if (device_id != 0x5A) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", device_id);
        return -1;
    }

    // Configure electrode 0 touch and release thresholds
    if (i2cWriteByteData(i2c_handle, MPR121_TOUCHTH_0, 0x0A) < 0) {
        fprintf(stderr, "Error writing touch threshold for electrode 0\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_RELEASETH_0, 0x05) < 0) {
        fprintf(stderr, "Error writing release threshold for electrode 0\n");
        return -1;
    }

    // Configure FFI, SFI, and ESI
    if (i2cWriteByteData(i2c_handle, MPR121_FFI, 0x01) < 0) {
        fprintf(stderr, "Error writing FFI\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_SFI, 0x01) < 0) {
        fprintf(stderr, "Error writing SFI\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_ESI, 0x01) < 0) {
        fprintf(stderr, "Error writing ESI\n");
        return -1;
    }

    // Configure debounce
    if (i2cWriteByteData(i2c_handle, MPR121_DEBOUNCE, 0x10) < 0) {
        fprintf(stderr, "Error writing debounce\n");
        return -1;
    }

    // Configure AFE
    if (i2cWriteByteData(i2c_handle, MPR121_AFE_CONFIG, 0x04) < 0) {
        fprintf(stderr, "Error writing AFE config\n");
        return -1;
    }

    // Configure baseline filtering
    if (i2cWriteByteData(i2c_handle, MPR121_BASELINE_FILTER, 0x05) < 0) {
        fprintf(stderr, "Error writing baseline filter\n");
        return -1;
    }

    // Enable electrode 0
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Error writing electrode config\n");
        return -1;
    }

    return 0;
}

// Function to read the touch status from the MPR121
int read_touch_status() {
    int touch_status_l = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_L);
    int touch_status_h = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_H);

    if (touch_status_l < 0 || touch_status_h < 0) {
        fprintf(stderr, "Error reading touch status\n");
        return -1;
    }

    return (touch_status_h << 8) | touch_status_l;
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Function to log an event to the log file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("proximity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Proximity detector started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int touch_status = read_touch_status();
        if (touch_status < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            gpioDelay(100); // Wait 100ms before retrying
            continue;
        }

        // Check if electrode 0 is touched
        if (touch_status & 0x01) {
            printf("Electrode 0 touched!\n");
            log_event("Electrode 0 touched");
            control_led(1); // Turn on LED
            gpioDelay(1000); // Wait 1 second
            control_led(0); // Turn off LED
        }

        gpioDelay(50); // Small delay to avoid busy-waiting
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_led(0); // Ensure LED is off
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

