#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TRIG_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 343.0  // Speed of sound in meters per second
#define VOLTAGE_DIVIDER_RATIO 2.0 // 2 kOhm / (2 kOhm + 1 kOhm)
#define LOG_FILE "distance_log.txt"

// Global variables
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static FILE *log_file = NULL;
static int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t pulse_width);
void log_distance(double distance);
void signal_handler(int signal);

// Function to generate a 10 microsecond trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin interrupts
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1; // Indicate that echo has started
    } else if (level == 0 && echo_received) {
        end_tick = tick;
        echo_received = 0; // Reset echo received flag
    }
}

// Function to calculate distance in meters
double calculate_distance(uint32_t pulse_width) {
    // Validate pulse width
    if (pulse_width < 58000 || pulse_width > 2500000) {
        fprintf(stderr, "Error: Invalid pulse width: %u us\n", pulse_width);
        return -1.0; // Indicate an error
    }

    // Calculate distance
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to log distance to file with timestamp
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.3f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;

    // Disable ISR
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO_PIN
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt callback
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL);

    // Main loop
    while (running) {
        trigger_pulse();
        gpioDelay(1000); // Wait 1 second

        // Wait for echo to be received
        while (!echo_received && running) {
            gpioDelay(100); // Check every 100 microseconds
        }

        if (!running) break; // Exit loop if signal received

        // Calculate pulse width and distance
        uint32_t pulse_width = end_tick - start_tick;

        // Handle tick wrap-around
        if (end_tick < start_tick) {
            pulse_width = (0xFFFFFFFF - start_tick) + end_tick; // Correct for wrap-around
        }

        double distance = calculate_distance(pulse_width);

        if (distance >= 0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Error: Could not calculate distance.\n");
        }
    }

    // Clean up (should not reach here if signal handler works correctly)
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

