#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x0110
#define VL53L1X_REG_SYSRANGE_START 0x00
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050
#define VL53L1X_REG_I2C_SLAVE_DEVICE_ADDRESS 0x008A
#define VL53L1X_REG_ANALOG_GLOBAL_CONFIG_TIMEOUT_MACROP_HI 0x0020
#define VL53L1X_REG_ANALOG_GLOBAL_CONFIG_TIMEOUT_MACROP_LO 0x0021
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG 0x0081
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L1X_REG_RESULT_PEAK_SIGNAL_RATE_MSB 0x004E
#define VL53L1X_REG_RESULT_PEAK_SIGNAL_RATE_LSB 0x004F
#define VL53L1X_REG_RESULT_SIGNAL_RATE_MSB 0x0050
#define VL53L1X_REG_RESULT_SIGNAL_RATE_LSB 0x0051
#define VL53L1X_REG_RESULT_AMBIENT_RATE_MSB 0x0052
#define VL53L1X_REG_RESULT_AMBIENT_RATE_LSB 0x0053
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD1 0x0051
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD2 0x0052
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD3 0x0053
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD4 0x0054
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD5 0x0055
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD6 0x0056
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD7 0x0057

// GPIO pin for trigger
#define TRIGGER_PIN 27

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init(int i2c_handle);
int vl53l1x_read_distance(int i2c_handle, int *distance);
int vl53l1x_read_status(int i2c_handle, int *status);
void log_data(int distance, int status);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, exiting...");
    terminate = 1;
}

// VL53L1X initialization function
int vl53l1x_init(int i2c_handle) {
    // Check sensor ID
    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, data, 2) != 2) {
        syslog(LOG_ERR, "Failed to read sensor ID: %s", strerror(errno));
        return -1;
    }
    if (data[0] != 0xEA || data[1] != 0xAA) {
        syslog(LOG_ERR, "Incorrect sensor ID: 0x%02X 0x%02X", data[0], data[1]);
        return -1;
    }

    // Set I2C address (optional, but recommended)
    char addr_data[2];
    addr_data[0] = VL53L1X_REG_I2C_SLAVE_DEVICE_ADDRESS;
    addr_data[1] = VL53L1X_ADDR;
    if (i2cWriteI2CBlockData(i2c_handle, addr_data[0], &addr_data[1], 1) != 1) {
        syslog(LOG_ERR, "Failed to set I2C address: %s", strerror(errno));
        return -1;
    }

    // Configure for continuous ranging
    char config_data[2];
    config_data[0] = 0x0018;
    config_data[1] = 0x00; // Continuous mode
    if (i2cWriteI2CBlockData(i2c_handle, config_data[0], &config_data[1], 1) != 1) {
        syslog(LOG_ERR, "Failed to set continuous mode: %s", strerror(errno));
        return -1;
    }

    // Set timeout
    config_data[0] = VL53L1X_REG_ANALOG_GLOBAL_CONFIG_TIMEOUT_MACROP_HI;
    config_data[1] = 0x00; // 0ms timeout
    if (i2cWriteI2CBlockData(i2c_handle, config_data[0], &config_data[1], 1) != 1) {
        syslog(LOG_ERR, "Failed to set timeout: %s", strerror(errno));
        return -1;
    }
    config_data[0] = VL53L1X_REG_ANALOG_GLOBAL_CONFIG_TIMEOUT_MACROP_LO;
    config_data[1] = 0x00; // 0ms timeout
    if (i2cWriteI2CBlockData(i2c_handle, config_data[0], &config_data[1], 1) != 1) {
        syslog(LOG_ERR, "Failed to set timeout: %s", strerror(errno));
        return -1;
    }

    // Start ranging
    config_data[0] = VL53L1X_REG_SYSRANGE_START;
    config_data[1] = 0x01; // Start ranging
    if (i2cWriteI2CBlockData(i2c_handle, config_data[0], &config_data[1], 1) != 1) {
        syslog(LOG_ERR, "Failed to start ranging: %s", strerror(errno));
        return -1;
    }

    return 0;
}

// VL53L1X read distance function
int vl53l1x_read_distance(int i2c_handle, int *distance) {
    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 2) != 2) {
        syslog(LOG_ERR, "Failed to read distance: %s", strerror(errno));
        return -1;
    }

    *distance = (data[1] << 8) | data[0];
    return 0;
}

// VL53L1X read status function
int vl53l1x_read_status(int i2c_handle, int *status) {
    char data[1];
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, data, 1) != 1) {
        syslog(LOG_ERR, "Failed to read status: %s", strerror(errno));
        return -1;
    }

    *status = data[0];
    return 0;
}

// Logging function
void log_data(int distance, int status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    syslog(LOG_INFO, "%s Distance: %d mm, Status: %d", timestamp, distance, status);
}

int main() {
    // Initialize syslog
    openlog("vl53l1x_reader", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set trigger pin as output
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioWrite(TRIGGER_PIN, 1); // Enable sensor

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        gpioTerminate();
        closelog();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init(i2c_handle) != 0) {
        syslog(LOG_ERR, "VL53L1X initialisation failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Main loop
    int distance, status;
    while (!terminate) {
        if (vl53l1x_read_distance(i2c_handle, &distance) == 0 &&
            vl53l1x_read_status(i2c_handle, &status) == 0) {
            log_data(distance, status);
        } else {
            syslog(LOG_ERR, "Failed to read sensor data");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    // Close syslog
    closelog();

    return 0;
}

