    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 2) != 2) {
        syslog(LOG_ERR, "Failed to read distance: %s", strerror(errno));
        return -1;
    }

    *distance = (data[1] << 8) | data[0];
    return 0;
}

// VL53L1X read status function
int vl53l1x_read_status(int i2c_handle, int *status) {
    char data[1];
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, data, 1) != 1) {
        syslog(LOG_ERR, "Failed to read status: %s", strerror(errno));
        return -1;
    }

    *status = data[0];
    return 0;
}

// Logging function
void log_data(int distance, int status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    syslog(LOG_INFO, "%s Distance: %d mm, Status: %d", timestamp, distance, status);
}

int main() {
    // Initialize syslog
    openlog("vl53l1x_reader", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set trigger pin as output
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioWrite(TRIGGER_PIN, 1); // Enable sensor

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        gpioTerminate();
        closelog();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init(i2c_handle) != 0) {
        syslog(LOG_ERR, "VL53L1X initialisation failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Main loop
    int distance, status;
    while (!terminate) {
        if (vl53l1x_read_distance(i2c_handle, &distance) == 0 &&
            vl53l1x_read_status(i2c_handle, &status) == 0) {
            log_data(distance, status);
        } else {
            syslog(LOG_ERR, "Failed to read sensor data");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    // Close syslog
    closelog();

    return 0;
}

