int read_distance();
void control_gate(int distance);
void log_data(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    log_data("Received signal, shutting down...");
    gpioWrite(GPIO_GATE, 0); // Close the gate
    i2cClose(i2c_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    int status;

    // Check model ID
    status = i2cReadByteData(i2c_handle, 0x010F);
    if (status < 0) {
        log_data("Error reading model ID");
        return -1;
    }
    if (status != 0xEA) {
        log_data("Incorrect model ID");
        return -1;
    }

    // Set ranging mode to short
    status = i2cWriteByteData(i2c_handle, 0x0021, 0x00);
    if (status < 0) {
        log_data("Error setting ranging mode");
        return -1;
    }

    // Start ranging
    status = i2cWriteByteData(i2c_handle, 0x0015, 0x01);
    if (status < 0) {
        log_data("Error starting ranging");
        return -1;
    }

    log_data("VL53L1X sensor initialized successfully");
    return 0;
}

// Read distance from VL53L1X sensor
int read_distance() {
    int status;
    unsigned short distance;

    // Read distance from registers 0x0089 and 0x008A
    status = i2cReadWordData(i2c_handle, 0x0089);
    if (status < 0) {
        log_data("Error reading distance");
        return -1;
    }
    distance = status; // pigpio handles endianness

    // Convert mm to cm
    distance = distance / 10;

    return distance;
}

