void control_gate(int distance) {
    static int gate_open = 0; // Track gate state

    if (distance < DISTANCE_THRESHOLD && !gate_open) {
        gpioWrite(GPIO_GATE, 1); // Open the gate
        gate_open = 1;
        log_data("Gate opened");
    } else if (distance >= DISTANCE_THRESHOLD && gate_open) {
        gpioWrite(GPIO_GATE, 0); // Close the gate
        gate_open = 0;
        log_data("Gate closed");
    }
}

