    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        log_data("Error opening I2C bus");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        log_data("VL53L1X initialization failed");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        distance = read_distance();
        if (distance >= 0) {
            char log_message[100];
            snprintf(log_message, sizeof(log_message), "Distance: %d cm", distance);
            log_data(log_message);
            control_gate(distance);
        } else {
            log_data("Failed to read distance");
        }

        gpioDelay(100); // 100 ms delay
    }

    return 0;
}

