#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define SERVO_MIN_PULSE_WIDTH 500 // us
#define SERVO_MAX_PULSE_WIDTH 2500 // us
#define SAMPLE_RATE 100       // ms
#define MOVING_AVG_SIZE 5
#define TIMEOUT_US 30000       // 30 ms

// Global variables
volatile sig_atomic_t program_running = 1;
volatile int pulse_width_ready = 0;
int pulse_width = 0;

// Function prototypes
void triggerSensor();
void echoCallback(int gpio, int level, uint32_t tick);
double calculateDistance(uint32_t pulseWidth);
double applyMovingAverage(double distance, double *history, int historySize, int historyIndex);
double mapDistanceToAngle(double distance);
int mapAngleToPulseWidth(double angle);
void setServoAngle(int angle);
void logData(double distance, double angle);
void signalHandler(int signal);

// Signal handler
void signalHandler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Exiting gracefully.\n");
        program_running = 0;
    }
}

// Trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echoCallback(int gpio, int level, uint32_t tick) {
    static uint32_t start_tick = 0;
    static int echo_active = 0;

    if (level == 1) {
        start_tick = tick;
        echo_active = 1;
    } else if (level == 0 && echo_active) {
        uint32_t end_tick = tick;
        pulse_width = end_tick - start_tick;
        pulse_width_ready = 1;
        echo_active = 0;
    }
}

// Calculate distance from pulse width
double calculateDistance(uint32_t pulseWidth) {
    if (pulseWidth < 0 || pulseWidth > TIMEOUT_US) {
        return -1.0; // Invalid reading
    }
    double time_taken = (double)pulseWidth / 1000000.0; // in seconds
    double distance = (time_taken * SPEED_OF_SOUND) / 2.0; // cm
    return distance;
}

// Apply moving average filter
double applyMovingAverage(double distance, double *history, int historySize, int historyIndex) {
    double sum = 0.0;
    int count = 0;

    if (historyIndex < historySize) {
        // Fill the history array with zeros if it's not full
        for (int i = 0; i < historySize; i++) {
            history[i] = 0.0;
        }
    }

    for (int i = 0; i < historySize; i++) {
        sum += history[i];
        count++;
    }

    history[historyIndex] = distance;
    sum -= history[historyIndex - historySize];
    sum += distance;

    return sum / historySize;
}

// Map distance to angle using logarithmic function
double mapDistanceToAngle(double distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1.0; // Invalid distance
    }
    double angle = (log10(distance + 1) - log10(MIN_DISTANCE + 1)) / (log10(MAX_DISTANCE + 1) - log10(MIN_DISTANCE + 1)) * 180.0;
    return angle;
}

// Map angle to pulse width
int mapAngleToPulseWidth(double angle) {
    if (angle < 0 || angle > 180) {
        return -1; // Invalid angle
    }
    return (int)(SERVO_MIN_PULSE_WIDTH + (angle / 180.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));
}

// Set servo angle
void setServoAngle(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Invalid servo angle: %d\n", angle);
        return;
    }
    gpioServo(SERVO_PIN, angle * 1000 / 180 + 500); // Convert angle to pulse width and set servo
}

// Log data to CSV file
void logData(double distance, double angle) {
    FILE *fp = fopen("distance_log.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for writing!\n");
        return;
    }

    // Write header if the file is new
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,Distance (cm),Angle (deg)\n");
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, distance, angle);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Initialize servo to a safe position
    setServoAngle(90);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    // Set up alert callback for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echoCallback, NULL);

    double distance_history[MOVING_AVG_SIZE] = {0}; // Initialize history
    int history_index = 0;

    printf("Starting distance measurement and servo control...\n");

    while (program_running) {
        triggerSensor();
        gpioDelay(SAMPLE_RATE); // Wait for echo

        if (pulse_width_ready) {
            double distance = calculateDistance(pulse_width);
            if (distance < 0) {
                fprintf(stderr, "Error: Invalid distance reading. Setting servo to 90 degrees.\n");
                setServoAngle(90);
                logData(-1.0, -1.0); // Log error
            } else {
                distance = applyMovingAverage(distance, distance_history, MOVING_AVG_SIZE, history_index);
                history_index = (history_index + 1) % MOVING_AVG_SIZE;

                double angle = mapDistanceToAngle(distance);
                if (angle < 0) {
                    fprintf(stderr, "Error: Invalid angle reading. Setting servo to 90 degrees.\n");
                    setServoAngle(90);
                    logData(-1.0, -1.0); // Log error
                } else {
                    int pulse_width = mapAngleToPulseWidth(angle);
                    if (pulse_width < 0) {
                        fprintf(stderr, "Error: Invalid pulse width. Setting servo to 90 degrees.\n");
                        setServoAngle(90);
                        logData(-1.0, -1.0); // Log error
                    } else {
                        setServoAngle((int)angle);
                        logData(distance, angle);
                    }
                }
            }
        } else {
            fprintf(stderr, "Error: No echo received. Setting servo to 90 degrees.\n");
            setServoAngle(90);
            logData(-1.0, -1.0); // Log error
        }
    }

    // Stop servo and terminate pigpio
    setServoAngle(90); // Set to a safe position before exiting
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

