// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_LED 17
#define BUFFER_SIZE 10

// VL53L1X register addresses (Example - refer to datasheet for complete list)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_PRE_RANGE_CONFIG_VCSEL_PERIOD 0x0050
#define VL53L1X_REG_FINAL_RANGE_CONFIG_VCSEL_PERIOD 0x0070
#define VL53L1X_REG_SYSTEM_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    int buffer[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

circular_buffer_t distance_buffer;

// Function prototypes
int init_vl53l1x();
int read_distance();
void update_led(int distance);
void add_to_buffer(int distance);
int get_from_buffer(int index);
void signal_handler(int signal);
void init_circular_buffer(circular_buffer_t *cb);

// Initialize circular buffer
void init_circular_buffer(circular_buffer_t *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Add a value to the circular buffer
void add_to_buffer(int distance) {
    distance_buffer.buffer[distance_buffer.head] = distance;
    distance_buffer.head = (distance_buffer.head + 1) % BUFFER_SIZE;
    if (distance_buffer.count < BUFFER_SIZE) {
        distance_buffer.count++;
    }
}

// Get a value from the circular buffer (not used in this example, but included for completeness)
int get_from_buffer(int index) {
    if (index < 0 || index >= distance_buffer.count) {
        return -1; // Indicate an invalid index
    }
    int actual_index = (distance_buffer.head - distance_buffer.count + index + BUFFER_SIZE) % BUFFER_SIZE;
    return distance_buffer.buffer[actual_index];
}

// Initialize the VL53L1X sensor
int init_vl53l1x() {
    // Check sensor ID (Example - refer to datasheet for correct value)
    int sensor_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (sensor_id != 0xEACC) {
        fprintf(stderr, "Error: VL53L1X sensor not found (ID: 0x%04X)\n", sensor_id);
        return -1;
    }

    // Example configuration (refer to datasheet for recommended settings)
    i2cWriteByteData(i2c_handle, VL53L1X_REG_PRE_RANGE_CONFIG_VCSEL_PERIOD, 0x00); // Example value
    i2cWriteByteData(i2c_handle, VL53L1X_REG_FINAL_RANGE_CONFIG_VCSEL_PERIOD, 0x00); // Example value

    // Start ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_START, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start ranging\n");
        return -1;
    }

    return 0;
}

// Read distance from the VL53L1X sensor
int read_distance() {
    int distance = -1;
    int range_status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);

    if (range_status < 0) {
        fprintf(stderr, "Error: Failed to read range status\n");
        return -1;
    }

    if ((range_status & 0x1F) == 0) {
        distance = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
        if (distance < 0) {
            fprintf(stderr, "Error: Failed to read distance\n");
            return -1;
        }
    } else {
        fprintf(stderr, "Error: Invalid range status\n");
        return -1;
    }

    return distance;
}

// Update the LED based on the distance
void update_led(int distance) {
    if (distance < 200) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize circular buffer
    init_circular_buffer(&distance_buffer);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            add_to_buffer(distance);
            update_led(distance);
        } else {
            fprintf(stderr, "Error: Failed to read distance, retrying...\n");
        }

        gpioDelay(50); // Delay for 50 ms
    }

    // Cleanup
    gpioWrite(GPIO_LED, 0); // Turn LED off
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

