#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define DEFAULT_I2C_ADDRESS 0x60
#define DEFAULT_THRESHOLD 1000
#define GPIO_INTERRUPT 27
#define PROXIMITY_HIGH_REG 0x08
#define PROXIMITY_LOW_REG 0x09
#define PROXIMITY_VALUE_REG 0x0A
#define PROXIMITY_RESULT_REG 0x0B
#define PROXIMITY_CONFIG_REG 0x0C
#define PROXIMITY_IRQ_STATUS_REG 0x03

// Global variables
int i2c_handle;
int i2c_address = DEFAULT_I2C_ADDRESS;
int threshold = DEFAULT_THRESHOLD;
FILE *log_file = NULL;
volatile int running = 1;

// Function prototypes
int init_i2c(int address);
int init_gpio(int gpio_pin);
int init_logging(const char *filename);
int read_proximity(int *proximity);
void log_data(int proximity, const char *status);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c(int address) {
    i2c_handle = i2cOpen(I2C_BUS, address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Si1102 Initialization sequence (example, adjust as needed)
    if (i2cWriteByteData(i2c_handle, PROXIMITY_CONFIG_REG, 0x01) < 0) { // Example config
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }
    gpioDelay(10); // Small delay after write

    return 0;
}

// Function to initialize GPIO
int init_gpio(int gpio_pin) {
    if (gpioSetMode(gpio_pin, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }

    if (gpioSetPullUpDown(gpio_pin, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting GPIO pull-up\n");
        return -1;
    }

    if (gpioSetISRFuncEx(gpio_pin, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting ISR function\n");
        return -1;
    }

    return 0;
}

// Function to initialize logging
int init_logging(const char *filename) {
    log_file = fopen(filename, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }
    return 0;
}

// Function to read proximity value
int read_proximity(int *proximity) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, PROXIMITY_HIGH_REG, buf, 2) != 2) {
        fprintf(stderr, "Error reading proximity data\n");
        return -1;
    }

    *proximity = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to log data
void log_data(int proximity, const char *status) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %d, %s\n", timestamp, proximity, status);
    fflush(log_file); // Ensure data is written to file immediately
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    int proximity;
    if (read_proximity(&proximity) == 0) {
        if (proximity > threshold) {
            log_data(proximity, "ALERT");
        } else {
            log_data(proximity, "SAFE");
        }
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        char *endptr;
        long addr = strtol(argv[1], &endptr, 0);
        if (*endptr == '\0' && addr >= 0 && addr <= 255) {
            i2c_address = (int)addr;
        } else {
            fprintf(stderr, "Invalid I2C address\n");
            return 1;
        }
    }
    if (argc > 2) {
        threshold = strtol(argv[2], &endptr, 0);
        if (*endptr == '\0' && threshold >= 0) {
            // Threshold is valid
        } else {
            fprintf(stderr, "Invalid threshold value\n");
            return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c(i2c_address) != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(GPIO_INTERRUPT) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize logging
    if (init_logging("proximity.log") != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(100); // Check every 100ms
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

