        gpioSetPWMfrequency(SPEAKER_PIN, frequency);
        gpioSetPWMrange(SPEAKER_PIN, pwm_range);
        gpioPWM(SPEAKER_PIN, pwm_range / 2); // 50% duty cycle
    } else {
        gpioPWM(SPEAKER_PIN, 0); // Stop the sound
    }
}

