    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SPEAKER_PIN, PI_OUTPUT);

    // Set PWM frequency for the speaker pin
    gpioSetPWMfrequency(SPEAKER_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(SPEAKER_PIN, 1000000); // Set PWM range to 1MHz

