            set_pwm_frequency(0.0); // Stop the sound
        }
        gpioDelay(50); // Delay to avoid excessive CPU usage
    }

    // Cleanup
    gpioPWM(SPEAKER_PIN, 0); // Stop the sound
    gpioTerminate();

