// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 5.0      // Minimum distance in cm
#define MAX_DISTANCE 50.0     // Maximum distance in cm
#define MIN_FREQUENCY 200.0   // Minimum frequency in Hz
#define MAX_FREQUENCY 2000.0  // Maximum frequency in Hz
#define TIMEOUT_US 100000      // Timeout in microseconds (100 ms)

// Global variables
static volatile int running = 1;
static volatile unsigned int start_tick, end_tick;
static volatile int echo_received = 0;

// Function prototypes
void trigger_sensor();
float get_distance();
float map_distance_to_frequency(float distance);
void set_buzzer_frequency(float frequency);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Stopping PWM and terminating pigpio.\n");
        running = 0;
        gpioHardwarePWM(BUZZER_PIN, 0, 0); // Stop PWM
        gpioTerminate(); // Terminate pigpio
        exit(0);
    }
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance using the ultrasonic sensor
float get_distance() {
    start_tick = gpioTick();
    echo_received = 0; // Reset flag
    while (!echo_received && (gpioTick() - start_tick) < TIMEOUT_US) {
        if (gpioRead(ECHO_PIN) == 1) {
            start_tick = gpioTick();
            echo_received = 1;
        }
    }

    if (!echo_received) {
        fprintf(stderr, "Error: Timeout waiting for echo.\n");
        return -1.0; // Indicate timeout error
    }

    start_tick = gpioTick();
    echo_received = 0;
    while (!echo_received && (gpioTick() - start_tick) < TIMEOUT_US) {
        if (gpioRead(ECHO_PIN) == 0) {
            end_tick = gpioTick();
            echo_received = 1;
        }
    }

    if (!echo_received) {
        fprintf(stderr, "Error: Timeout waiting for echo end.\n");
        return -1.0; // Indicate timeout error
    }

    unsigned int pulse_width = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 1000000.0 to convert us to s

    return distance;
}

// Function to map the distance to a frequency
float map_distance_to_frequency(float distance) {
    float frequency;

    // Clamp distance to the defined range
    if (distance < MIN_DISTANCE) {
        distance = MIN_DISTANCE;
    } else if (distance > MAX_DISTANCE) {
        distance = MAX_DISTANCE;
    }

    // Linear mapping
    frequency = MIN_FREQUENCY + (MAX_FREQUENCY - MIN_FREQUENCY) * (MAX_DISTANCE - distance) / (MAX_DISTANCE - MIN_DISTANCE);

    return frequency;
}

// Function to set the buzzer frequency using gpioHardwarePWM
void set_buzzer_frequency(float frequency) {
    int dutycycle = 128; // 50% duty cycle
    gpioHardwarePWM(BUZZER_PIN, dutycycle, frequency);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set pull-down resistor on ECHO_PIN
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Trigger the sensor
        trigger_sensor();

        // Measure the distance
        float distance = get_distance();

        // Map the distance to a frequency
        float frequency = map_distance_to_frequency(distance);

        // Set the buzzer frequency
        set_buzzer_frequency(frequency);

        // Print the distance and frequency
        printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);

        // Delay for 10 ms
        gpioDelay(10000); // 10 ms
    }

    // Stop PWM and terminate pigpio (should not reach here if signal handler works)
    gpioHardwarePWM(BUZZER_PIN, 0, 0);
    gpioTerminate();

    return 0;
}

