#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioWrite(TRIGGER_PIN, 0);

    signal(SIGINT, signal_handler);

    while (!terminate) {
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10);
        gpioWrite(TRIGGER_PIN, 0);

        int start_time = gpioTick();
        int end_time = start_time;
        int timeout = 50000; // 50 ms timeout in microseconds

        while (gpioRead(ECHO_PIN) == 0 && timeout > 0) {
            start_time = gpioTick();
            timeout--;
        }

        timeout = 50000;
        while (gpioRead(ECHO_PIN) == 1 && timeout > 0) {
            end_time = gpioTick();
            timeout--;
        }

        if (timeout <= 0) {
            fprintf(stderr, "Timeout waiting for echo\n");
            gpioDelay(500);
            continue;
        }

        int pulse_width = end_time - start_time;
        if (pulse_width < 0) {
            pulse_width += 0xFFFFFFFF; // Handle timer wrap-around
        }

        float distance = (float)pulse_width / 2 / 29.1;

        if (distance < 2 || distance > 400) {
            printf("Invalid reading: %.2f cm\n", distance);
        } else {
            printf("Distance: %.2f cm", distance);
            if (distance < 10) {
                printf(" Too close!\n");
            } else {
                printf("\n");
            }
        }

        gpioDelay(500);
    }

    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

