#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 0
#define CS_PIN 8

// Define sensor registers
#define REG_MODE 0x01
#define REG_RANGE 0x02
#define REG_TRIGGER 0x00
#define REG_DISTANCE_LOW 0x0C
#define REG_DISTANCE_HIGH 0x0D

// Global variables
int spi_handle;
FILE *log_file;

// Function prototypes
int init_sensor();
int read_distance();
void log_distance(int distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Initialize the sensor
int init_sensor() {
    char tx_buf[2];
    char rx_buf[2];

    // Set continuous measurement mode
    tx_buf[0] = REG_MODE | 0x80; // Write command
    tx_buf[1] = 0x01;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error writing to mode register: %d\n", spi_handle);
        return -1;
    }

    // Set range to 5 meters
    tx_buf[0] = REG_RANGE | 0x80; // Write command
    tx_buf[1] = 0x00;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error writing to range register: %d\n", spi_handle);
        return -1;
    }

    // Trigger a measurement
    tx_buf[0] = REG_TRIGGER | 0x80; // Write command
    tx_buf[1] = 0x01;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error writing to trigger register: %d\n", spi_handle);
        return -1;
    }

    return 0;
}

// Read the distance from the sensor
int read_distance() {
    char tx_buf[1];
    char rx_buf[2];

    // Read distance data (low byte first)
    tx_buf[0] = REG_DISTANCE_LOW | 0x00; // Read command
    if (spiXfer(spi_handle, tx_buf, rx_buf, 1) != 0) {
        fprintf(stderr, "Error reading low byte from distance register: %d\n", spi_handle);
        return -1;
    }

    tx_buf[0] = REG_DISTANCE_HIGH | 0x00; // Read command
    if (spiXfer(spi_handle, tx_buf, rx_buf, 1) != 0) {
        fprintf(stderr, "Error reading high byte from distance register: %d\n", spi_handle);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    int distance = (rx_buf[0] << 8) | rx_buf[1];

    // Validate the distance reading
    if (distance < 200 || distance > 5000) {
        fprintf(stderr, "Invalid distance reading: %d\n", distance);
        return -1;
    }

    return distance;
}

// Log the distance to a file
void log_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

