#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1175_ADDR 0x60
#define ALS_VIS_DATA_LOW 0x22
#define ALS_VIS_DATA_HIGH 0x23

static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize the I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read a 16-bit value from the Si1175
uint16_t read_als_visible(int fd) {
    uint8_t low_byte, high_byte;
    int retries = 3;

    while (retries > 0) {
        if (write(fd, &ALS_VIS_DATA_LOW, 1) != 1) {
            perror("Error writing to I2C device");
            retries--;
            usleep(10000); // Wait 10ms before retry
            continue;
        }

        if (read(fd, &low_byte, 1) != 1) {
            perror("Error reading low byte from I2C device");
            retries--;
            usleep(10000); // Wait 10ms before retry
            continue;
        }

        if (write(fd, &ALS_VIS_DATA_HIGH, 1) != 1) {
            perror("Error writing to I2C device");
            retries--;
            usleep(10000); // Wait 10ms before retry
            continue;
        }

        if (read(fd, &high_byte, 1) != 1) {
            perror("Error reading high byte from I2C device");
            retries--;
            usleep(10000); // Wait 10ms before retry
            continue;
        }

        return (uint16_t)((high_byte << 8) | low_byte);
    }

    fprintf(stderr, "Failed to read ALS_VIS_DATA after multiple retries.\n");
    return 0; // Return 0 on failure
}

// Function to get the current timestamp in ISO-8601 format
void get_iso8601_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *info;
    time(&rawtime);
    info = gmtime(&rawtime);
    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%SZ", info);
}

// Function to log the data to a CSV file
int log_data(const char *timestamp, uint16_t als_visible) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%u\n", timestamp, als_visible);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to close the I2C bus and log file
void cleanup(int fd, FILE *log_file) {
    if (fd != -1) {
        close(fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    char timestamp[21];
    uint16_t als_visible;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("proximity_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup(i2c_fd, NULL);
        return 1;
    }

    // Write the header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,als_visible\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        // Read the ambient light value
        als_visible = read_als_visible(i2c_fd);

        // Get the current timestamp
        get_iso8601_timestamp(timestamp);

        // Log the data
        if (log_data(timestamp, als_visible) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    cleanup(i2c_fd, log_file);
    return 0;
}

