#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1120_ADDR 0x60
#define ALS_REG_LOW 0x22
#define ALS_REG_HIGH 0x23
#define PS1_REG_LOW 0x18
#define PS1_REG_HIGH 0x19
#define PART_ID_REG 0x00
#define PART_ID_VALUE 0x41
#define RESET_REG 0x30
#define RESET_VALUE 0x01
#define SAMPLE_INTERVAL_MS 500

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_als(int *als_value);
int read_ps1(int *ps1_value);
int log_data(int als_value, int ps1_value);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Initialize the Si1120 sensor
int initialize_sensor() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, RESET_REG, RESET_VALUE) < 0) {
        fprintf(stderr, "Error: Failed to reset Si1120 sensor.\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Verify part ID
    int part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error: Failed to read part ID from Si1120 sensor.\n");
        return -1;
    }
    if (part_id != PART_ID_VALUE) {
        fprintf(stderr, "Error: Incorrect part ID (0x%02X) for Si1120 sensor. Expected 0x41.\n", part_id);
        return -1;
    }

    return 0;
}

// Read ALS data from the sensor
int read_als(int *als_value) {
    int retries = 3;
    while (retries > 0) {
        int low = i2cReadByteData(i2c_handle, ALS_REG_LOW);
        if (low < 0) {
            fprintf(stderr, "Error: Failed to read ALS low byte.\n");
            retries--;
            gpioDelay(10);
            continue;
        }

        int high = i2cReadByteData(i2c_handle, ALS_REG_HIGH);
        if (high < 0) {
            fprintf(stderr, "Error: Failed to read ALS high byte.\n");
            retries--;
            gpioDelay(10);
            continue;
        }

        *als_value = (high << 8) | low;
        return 0; // Success
    }
    fprintf(stderr, "Error: Failed to read ALS data after multiple retries.\n");
    return -1; // Failure
}

// Read PS1 data from the sensor
int read_ps1(int *ps1_value) {
    int retries = 3;
    while (retries > 0) {
        int low = i2cReadByteData(i2c_handle, PS1_REG_LOW);
        if (low < 0) {
            fprintf(stderr, "Error: Failed to read PS1 low byte.\n");
            retries--;
            gpioDelay(10);
            continue;
        }

        int high = i2cReadByteData(i2c_handle, PS1_REG_HIGH);
        if (high < 0) {
            fprintf(stderr, "Error: Failed to read PS1 high byte.\n");
            retries--;
            gpioDelay(10);
            continue;
        }

        *ps1_value = (high << 8) | low;
        return 0; // Success
    }
    fprintf(stderr, "Error: Failed to read PS1 data after multiple retries.\n");
    return -1; // Failure
}

// Log data to file
int log_data(int als_value, int ps1_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ALS: %d, PS1: %d\n", timestamp, als_value, ps1_value);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C connection. %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Error: Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    int als_value, ps1_value;
    while (!terminate) {
        if (read_als(&als_value) == 0 && read_ps1(&ps1_value) == 0) {
            log_data(als_value, ps1_value);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

