#define PROXIMITY_REG_LOW 0x16
#define PROXIMITY_REG_HIGH 0x17
#define PROXIMITY_REG_CONFIG 0x08
#define PROXIMITY_REG_COMMAND 0x80
#define PROXIMITY_REG_HW_KEY 0x07
#define PROXIMITY_REG_MEAS_RATE 0x06
#define PROXIMITY_REG_PS_LED21 0x0C
#define PROXIMITY_REG_PS_ADC_GAIN 0x0D
#define PROXIMITY_REG_PS_ADC_MISC 0x11
#define PROXIMITY_REG_PS_FORCE 0x80

#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_si1145();
int read_proximity();
void log_data(unsigned int proximity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize Si1145 sensor
int init_si1145() {
    int retries = 0;
    int status;

    // Hardware Key
    status = i2cWriteByteData(i2c_handle, PROXIMITY_REG_HW_KEY, 0x17);
    if (status < 0) {
        fprintf(stderr, "Error writing to HW_KEY register: %d\n", status);
        return -1;
    }
    retries++;

    // Measurement Rate
    status = i2cWriteByteData(i2c_handle, PROXIMITY_REG_MEAS_RATE, 0x02);
    if (status < 0) {
        fprintf(stderr, "Error writing to MEAS_RATE register: %d\n", status);
        return -1;
    }
    retries++;

    // PS_LED21
    status = i2cWriteByteData(i2c_handle, PROXIMITY_REG_PS_LED21, 0x3F); // 180mA
    if (status < 0) {
        fprintf(stderr, "Error writing to PS_LED21 register: %d\n", status);
        return -1;
    }
    retries++;

    // PS_ADC_GAIN
    status = i2cWriteByteData(i2c_handle, PROXIMITY_REG_PS_ADC_GAIN, 0x07); // 7.7x
    if (status < 0) {
        fprintf(stderr, "Error writing to PS_ADC_GAIN register: %d\n", status);
        return -1;
    }
    retries++;

    // PS_ADC_MISC
    status = i2cWriteByteData(i2c_handle, PROXIMITY_REG_PS_ADC_MISC, 0x03); // Small IR
    if (status < 0) {
        fprintf(stderr, "Error writing to PS_ADC_MISC register: %d\n", status);
        return -1;
    }
    retries++;

    // PS_FORCE
    status = i2cWriteByteData(i2c_handle, PROXIMITY_REG_COMMAND, 0x01); // Force proximity measurement
    if (status < 0) {
        fprintf(stderr, "Error writing to PS_FORCE register: %d\n", status);
        return -1;
    }
    retries++;

    return 0;
}

// Read proximity data from Si1145
int read_proximity() {
    int retries = 0;
    int status;
    unsigned int proximity;

    // Read proximity data (low and high bytes)
    while (retries < MAX_RETRIES) {
        int low_byte = i2cReadByteData(i2c_handle, PROXIMITY_REG_LOW);
        if (low_byte < 0) {
            fprintf(stderr, "Error reading low byte from proximity register: %d\n", low_byte);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        int high_byte = i2cReadByteData(i2c_handle, PROXIMITY_REG_HIGH);
        if (high_byte < 0) {
            fprintf(stderr, "Error reading high byte from proximity register: %d\n", high_byte);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        proximity = (high_byte << 8) | low_byte;
        return proximity;
    }

    fprintf(stderr, "Failed to read proximity data after %d retries.\n", MAX_RETRIES);
    return -1; // Indicate failure
}

