// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define DISTANCE_THRESHOLD 20.0 // cm
#define BUZZER_DURATION 500 // ms

// Global variables
volatile unsigned int rising_edge_time = 0;
volatile unsigned int falling_edge_time = 0;
volatile int echo_received = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, unsigned int tick, void *user);
float calculate_distance(unsigned int pulse_width);
void control_buzzer(float distance);
void signal_handler(int signal);

