    exit(0);
}

// Function to generate a 10 us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin interrupts
void echo_callback(int gpio, int level, unsigned int tick, void *user) {
    if (level == 1) {
        rising_edge_time = tick;
        echo_received = 1; // Indicate rising edge received
    } else if (level == 0 && echo_received == 1) {
        falling_edge_time = tick;
        echo_received = 0; // Reset flag after falling edge
    }
}

// Function to calculate distance in centimeters
float calculate_distance(unsigned int pulse_width) {
    return pulse_width * SPEED_OF_SOUND / 2.0;
}

// Function to control the buzzer based on distance
void control_buzzer(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(BUZZER_PIN, 1); // Turn on buzzer
    } else {
        gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    }
}

