        fprintf(stderr, "Failed to set TRIGGER_PIN to output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN to input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set BUZZER_PIN to output\n");
        gpioTerminate();
        return 1;
    }

    // Set up interrupt callback for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for ECHO_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Generate trigger pulse
        trigger_pulse();

        // Wait for echo to be received
        while (rising_edge_time == 0 && falling_edge_time == 0) {
            gpioDelay(100); // Wait 100 us
        }

        // Calculate pulse width
        unsigned int pulse_width = falling_edge_time - rising_edge_time;

        // Calculate distance
        float distance = calculate_distance(pulse_width);

        // Control buzzer
        control_buzzer(distance);

        // Print distance
        printf("Distance: %.2f cm\n", distance);

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 us
    }

    return 0;
}

