#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MAX_DISTANCE 200.0     // Maximum measurable distance in cm
#define MIN_DISTANCE 20.0      // Minimum measurable distance in cm
#define MAX_PULSE_WIDTH 2500    // Maximum pulse width for servo (us)
#define MIN_PULSE_WIDTH 500     // Minimum pulse width for servo (us)
#define TIMEOUT_US 50000        // Timeout for echo pulse (us)

// Global variables
volatile int echo_start_tick = 0;
volatile int echo_end_tick = 0;
volatile int echo_timeout = 0;

// Function prototypes
void trigger_pulse();
float measure_distance();
void set_servo_angle(float distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();         // Terminate pigpio
    exit(0);                 // Exit the program
}

// Function to send a trigger pulse to the HC-SR04 sensor
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance using the HC-SR04 sensor
float measure_distance() {
    echo_timeout = 0;
    echo_start_tick = 0;
    echo_end_tick = 0;

    trigger_pulse();

    // Wait for echo to start
    int start_time = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            echo_timeout = 1;
            return -1.0; // Timeout
        }
    }
    echo_start_tick = gpioTick();

    // Wait for echo to end
    start_time = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            echo_timeout = 1;
            return -1.0; // Timeout
        }
    }
    echo_end_tick = gpioTick();

    if (echo_timeout) {
        return -1.0; // Timeout
    }

    // Calculate pulse width in microseconds
    int pulse_width = echo_end_tick - echo_start_tick;

    // Calculate distance in centimeters
    float distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0;

    return distance;
}

// Function to set the servo angle based on the measured distance
void set_servo_angle(float distance) {
    int pulse_width;

    if (distance > MAX_DISTANCE) {
        pulse_width = MIN_PULSE_WIDTH;
    } else if (distance < MIN_DISTANCE) {
        pulse_width = MAX_PULSE_WIDTH;
    } else {
        // Map distance to pulse width linearly
        pulse_width = MIN_PULSE_WIDTH + (int)(((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE)) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));
    }

    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM range for servo (optional, but recommended)
    gpioSetPWMrange(SERVO_PIN, 2000); // Set range to 2000 for finer control

    // Set PWM frequency for servo (optional, but recommended)
    gpioSetPWMfrequency(SERVO_PIN, 50); // Set frequency to 50 Hz

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        float distance = measure_distance();

        if (distance < 0) {
            fprintf(stderr, "Error: Distance measurement failed\n");
        } else {
            printf("Distance: %.2f cm\n", distance);
            set_servo_angle(distance);
        }

        gpioDelay(100); // Wait 100 ms
    }

    return 0; // This line will never be reached due to the infinite loop
}

