#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_GPIO 18
#define OPEN_THRESHOLD 200
#define CLOSE_THRESHOLD 250
#define SERVO_OPEN_PULSEWIDTH 2000
#define SERVO_CLOSED_PULSEWIDTH 1000
#define LOG_FILE "gate_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void control_gate(int distance);
void log_event(const char *event);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    // Verify model ID
    char model_id;
    if (i2cReadI2CBlockData(i2c_handle, 0x010F, &model_id, 1) != 1) {
        fprintf(stderr, "Error reading model ID\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Set timing budget (example: 50ms)
    char timing_budget[2] = {0x00, 0x05}; // Example value, adjust as needed
    if (i2cWriteI2CBlockData(i2c_handle, 0x001E, timing_budget, 2) != 2) {
        fprintf(stderr, "Error writing timing budget\n");
        return -1;
    }

    // Start ranging (example: continuous mode)
    char ranging_mode[1] = {0x01}; // Example value, adjust as needed
    if (i2cWriteI2CBlockData(i2c_handle, 0x0016, ranging_mode, 1) != 1) {
        fprintf(stderr, "Error writing ranging mode\n");
        return -1;
    }

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance() {
    char buffer[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x0089, buffer, 2) != 2) {
        fprintf(stderr, "Error reading distance\n");
        return -1;
    }
    return (buffer[0] << 8) | buffer[1];
}

// Control the gate based on distance
void control_gate(int distance) {
    static int gate_open = 0; // Track gate state

    if (distance < OPEN_THRESHOLD && !gate_open) {
        // Open the gate
        for (int pulsewidth = SERVO_CLOSED_PULSEWIDTH; pulsewidth > SERVO_OPEN_PULSEWIDTH; pulsewidth--) {
            gpioServo(SERVO_GPIO, pulsewidth);
            gpioDelay(10000); // 10ms delay
        }
        gate_open = 1;
        log_event("Gate opened");
    } else if (distance > CLOSE_THRESHOLD && gate_open) {
        // Close the gate
        for (int pulsewidth = SERVO_OPEN_PULSEWIDTH; pulsewidth < SERVO_CLOSED_PULSEWIDTH; pulsewidth++) {
            gpioServo(SERVO_GPIO, pulsewidth);
            gpioDelay(10000); // 10ms delay
        }
        gate_open = 0;
        log_event("Gate closed");
    }
}

// Log gate events to file
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file); // Ensure immediate write
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set servo GPIO to PWM mode
    gpioSetMode(SERVO_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_GPIO, 50); // 50Hz

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            printf("Distance: %d mm\n", distance);
            control_gate(distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }
        gpioDelay(50000); // 50ms delay
    }

    // Cleanup
    gpioServo(SERVO_GPIO, 0); // Stop PWM
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

