#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 343.0  // m/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define MIN_ANGLE 0.0         // degrees
#define MAX_ANGLE 180.0       // degrees
#define MIN_PULSE_WIDTH 500   // us
#define MAX_PULSE_WIDTH 2500  // us
#define TIMEOUT_US 50000      // us (50 ms)

// Global variables
volatile int echo_start_tick = 0;
volatile int echo_end_tick = 0;
volatile int echo_timeout = 0;

// Function prototypes
void triggerSensor();
int measurePulseWidth();
float calculateDistance(int pulseWidth);
float mapDistanceToAngle(float distance);
void setServoAngle(float angle);
void signalHandler(int signal);

// Signal handler for Ctrl+C
void signalHandler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();         // Terminate pigpio
    exit(0);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
int measurePulseWidth() {
    int start_time = gpioTick();
    int end_time;

    // Wait for rising edge with timeout
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            echo_timeout = -1.0;
            return -1; // Timeout
        }
    }
    echo_start_tick = gpioTick();

    // Wait for falling edge with timeout
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            echo_timeout = -1.0;
            return -1; // Timeout
        }
    }
    echo_end_tick = gpioTick();

    return echo_end_tick - echo_start_tick;
}

// Function to calculate the distance in centimeters
float calculateDistance(int pulseWidth) {
    if (pulseWidth <= 0) return -1.0; // Avoid division by zero
    return (float)pulseWidth * 0.0343 / 2.0;
}

// Function to map the distance to an angle
float mapDistanceToAngle(float distance) {
    if (distance < MIN_DISTANCE) return MIN_ANGLE;
    if (distance > MAX_DISTANCE) return MAX_ANGLE;
    return MIN_ANGLE + (distance - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE);
}

// Function to set the servo angle
void setServoAngle(float angle) {
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;

    int pulseWidth = MIN_PULSE_WIDTH + (int)((angle - MIN_ANGLE) / (MAX_ANGLE - MIN_ANGLE) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));
    gpioServo(SERVO_PIN, pulseWidth);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    printf("Parking Assist System running. Press Ctrl+C to exit.\n");

    while (1) {
        // Trigger the sensor
        triggerSensor();

        // Measure the pulse width
        int pulseWidth = measurePulseWidth();

        if (pulseWidth < 0) {
            fprintf(stderr, "Timeout occurred\n");
        } else {
            // Calculate the distance
            float distance = calculateDistance(pulseWidth);

            if (distance < 0) {
                fprintf(stderr, "Invalid distance reading\n");
            } else {
                // Map the distance to an angle
                float angle = mapDistanceToAngle(distance);

                // Set the servo angle
                setServoAngle(angle);

                // Print the distance and angle
                printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, angle);
            }
        }

        // Delay for 100 ms
        gpioDelay(100);
    }

    return 0;
}

