#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7005_ADDR 0x40
#define CONFIG_REG 0x03
#define TEMP_REG 0x01
#define HUMID_REG 0x02

int i2c_handle;

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02x: %d\n", bus, addr, handle);
        return -1;
    }
    return handle;
}

// Function to configure the Si7005 sensor
int configure_sensor(int handle) {
    char buf[1];
    buf[0] = CONFIG_REG;
    int result = i2cWriteDevice(handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to config register: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait 10 ms
    return 0;
}

// Function to read temperature and humidity
int read_sensor(int handle, float *temperature, float *humidity) {
    char buf[1];
    char data[2];
    int result;

    // Read temperature
    buf[0] = TEMP_REG;
    result = i2cWriteDevice(handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to temperature register: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait 10 ms
    result = i2cReadDevice(handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read temperature data: %d\n", result);
        return -1;
    }
    int raw_temp = (data[0] << 8) | data[1];
    *temperature = (175.72 * raw_temp) / 65536.0 - 46.85;

    // Read humidity
    buf[0] = HUMID_REG;
    result = i2cWriteDevice(handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to humidity register: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait 10 ms
    result = i2cReadDevice(handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read humidity data: %d\n", result);
        return -1;
    }
    int raw_humidity = (data[0] << 8) | data[1];
    *humidity = (125.0 * raw_humidity) / 65536.0 - 6.0;

    return 0;
}

// Function to log the sensor data
void log_data(float temperature, float humidity) {
    printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, SI7005_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    float temperature, humidity;

    // Main loop
    while (1) {
        if (read_sensor(i2c_handle, &temperature, &humidity) == 0) {
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Attempting to re-initialize...\n");
            i2cClose(i2c_handle);
            i2c_handle = open_i2c_bus(I2C_BUS, SI7005_ADDR);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C bus. Exiting.\n");
                break;
            }
            if (configure_sensor(i2c_handle) != 0) {
                fprintf(stderr, "Failed to re-configure sensor. Exiting.\n");
                break;
            }
        }
        gpioDelay(2000); // Wait 2 seconds
    }

    // Cleanup (should not reach here if signal handler works)
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

