#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize the MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }
    gpioDelay(100); // Wait for the device to stabilize

    // Set sample rate divider
    if (i2cWriteByteData(i2c_handle, SMPLRT_DIV, 7) < 0) {
        fprintf(stderr, "Error: Could not set sample rate divider\n");
        return -1;
    }

    // Configure accelerometer range
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not configure accelerometer range\n");
        return -1;
    }

    // Configure gyroscope range
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not configure gyroscope range\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer and gyroscope data
int read_mpu6050_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buf[14];

    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 14) < 0) {
        fprintf(stderr, "Error: Could not read MPU-6050 data\n");
        return -1;
    }

    // Parse the data (big-endian)
    *accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    *accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    *accel_z = (int16_t)((buf[4] << 8) | buf[5]);
    *gyro_x = (int16_t)((buf[8] << 8) | buf[9]);
    *gyro_y = (int16_t)((buf[10] << 8) | buf[11]);
    *gyro_z = (int16_t)((buf[12] << 8) | buf[13]);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    int who_am_i = i2cReadByteData(i2c_handle, 0x75); //WHO_AM_I register
    if (who_am_i < 0) {
        fprintf(stderr, "Error: Could not read WHO_AM_I register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (who_am_i != 0x68) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%x\n", who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    while (!terminate) {
        if (read_mpu6050_data(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            printf("Accel: X=%6d, Y=%6d, Z=%6d  Gyro: X=%6d, Y=%6d, Z=%6d\n", accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data. Retrying...\n");
        }
        gpioDelay(100); // 100 ms delay
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    // Print shutdown message
    printf("Program terminated cleanly.\n");

    return 0;
}

