#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdint.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD

int i2c_handle;

// CRC-8-ATM polynomial
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT_VALUE 0xFF

// Function to calculate CRC-8 checksum
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature and humidity from SHT40
int read_sht40(int i2c_handle, float *temperature, float *humidity) {
    uint8_t data[6];
    uint16_t raw_temperature, raw_humidity;

    // Send measurement command
    if (i2cWriteByteData(i2c_handle, 0, MEASURE_CMD) != 0) {
        fprintf(stderr, "Error: Failed to send measurement command.\n");
        return -1;
    }

    // Wait for at least 10 ms
    gpioDelay(10000); // 10 ms

    // Read 6 bytes of data
    if (i2cReadI2CBlockData(i2c_handle, 0, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: Failed to read data from SHT40.\n");
        return -1;
    }

    // Validate CRC checksums
    if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "Error: CRC checksum failure.\n");
        return -1;
    }

    // Convert raw values to temperature and humidity
    raw_temperature = (data[0] << 8) | data[1];
    raw_humidity = (data[3] << 8) | data[4];

    *temperature = -45 + 175 * (float)raw_temperature / 65535.0;
    *humidity = -6 + 125 * (float)raw_humidity / 65535.0;

    // Clamp humidity to 0-100%
    if (*humidity < 0.0) *humidity = 0.0;
    if (*humidity > 100.0) *humidity = 100.0;

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    float temperature, humidity;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus. %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        if (read_sht40(i2c_handle, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error: Failed to read temperature and humidity.\n");
        }

        gpioDelay(5000000); // 5 seconds
    }

    return 0;
}

