#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07

int i2c_fd;
FILE *log_file;

// Function to handle Ctrl+C signal
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_fd >= 0) {
        i2cClose(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to read temperature from the sensor
int read_temperature(int i2c_fd, int reg) {
    int raw_data = i2cReadWordData(i2c_fd, reg);
    if (raw_data < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, raw_data);
        return -1;
    }
    return raw_data;
}

// Function to convert raw data to Celsius
float convert_to_celsius(int raw_data) {
    return (float)raw_data * 0.02 - 273.15;
}

// Function to log temperature data to a file
int log_temperature(FILE *log_file, float ambient_temp, float object_temp) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, ambient_temp, object_temp) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("temperature_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        int ambient_raw = read_temperature(i2c_fd, AMBIENT_TEMP_REG);
        int object_raw = read_temperature(i2c_fd, OBJECT_TEMP_REG);

        if (ambient_raw >= 0 && object_raw >= 0) {
            float ambient_temp = convert_to_celsius(ambient_raw);
            float object_temp = convert_to_celsius(object_raw);

            if (log_temperature(log_file, ambient_temp, object_temp) != 0) {
                fprintf(stderr, "Error logging temperature data\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature data\n");
        }

        gpioSleep(PI_TIME_RELATIVE, 5, 0); // Sleep for 5 seconds
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness in case the loop condition is changed.
    i2cClose(i2c_fd);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

