#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define MEASURE_CMD 0x2C06
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"

int i2c_handle;
FILE *log_file;
FILE *error_log_file;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to read temperature from the STS30-DIS sensor
float read_temperature() {
    char buf[2];
    int result;
    unsigned int raw_temperature;
    float temperature;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, MEASURE_CMD >> 8, MEASURE_CMD & 0xFF);
    if (result != 0) {
        fprintf(error_log_file, "%s I2C write error: %d\n", __func__, result);
        fflush(error_log_file);
        return -1000.0; // Indicate error
    }

    // Wait for measurement (at least 20 ms)
    gpioDelay(20000); // 20 ms

    // Read 2 bytes of temperature data
    result = i2cReadI2CBlockData(i2c_handle, 0, buf, 2);
    if (result != 2) {
        fprintf(error_log_file, "%s I2C read error: %d\n", __func__, result);
        fflush(error_log_file);
        return -1000.0; // Indicate error
    }

    // Convert raw data to temperature (Celsius)
    raw_temperature = (buf[0] << 8) | buf[1];
    temperature = -45.0 + (175.0 * raw_temperature / 65535.0);

    return temperature;
}

// Function to log temperature data to a file
void log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to log errors to a file
void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(error_log_file, "%s, %s\n", timestamp, message);
    fflush(error_log_file);
}

int main() {
    float temperature;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open error log file
    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        fprintf(stderr, "Failed to open error log file\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        temperature = read_temperature();

        if (temperature > -999.0) { // Check for valid temperature reading
            log_temperature(temperature);
        } else {
            log_error("Failed to read temperature");
        }

        sleep(5);
    }

    // The following lines will never be reached because of the infinite loop.
    // However, they are included for completeness and to avoid compiler warnings.
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

