#include <string.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define CRC_POLYNOMIAL 0x31

int i2c_fd = -1;
FILE *log_file = NULL;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature and humidity from SHT40
int read_sht40(int fd, float *temperature, float *humidity) {
    uint8_t data[6];
    uint8_t cmd = MEASURE_CMD;

    // Send measurement command
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Wait for measurement to complete (at least 10 ms)
    usleep(10000); // 10 ms

    // Read 6 bytes of data
    if (read(fd, data, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // CRC validation
    if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    uint16_t raw_temperature = (data[0] << 8) | data[1];
    uint16_t raw_humidity = (data[3] << 8) | data[4];

    *temperature = -45 + 175 * (float)raw_temperature / 65535.0;
    *humidity = 100 * (float)raw_humidity / 65535.0;

    return 0;
}

// Function to log temperature and humidity to a file
void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, closing I2C and log file...\n", signum);
        if (i2c_fd != -1) {
            close(i2c_fd);
        }
        if (log_file != NULL) {
            fclose(log_file);
        }
        exit(0);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("sht40_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    float temperature, humidity;
    int retries = 3; // Number of retries for sensor readings

    while (1) {
        // Retry loop for sensor readings
        for (int i = 0; i < retries; i++) {
            if (read_sht40(i2c_fd, &temperature, &humidity) == 0) {
                log_data(temperature, humidity);
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "Sensor read failed, retrying (%d/%d)...\n", i + 1, retries);
                sleep(1); // Wait before retrying
            }
        }

        sleep(5); // Wait 5 seconds
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    close(i2c_fd);
    fclose(log_file);
    return 0;
}

