int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02x: %s\n", bus, addr, strerror(errno));
        return -1;
    }
    return handle;
}

// Function to read temperature from the Si7015
int read_temperature(int handle, float *temperature) {
    char buf[2];
    int result;
    int retries = RETRY_COUNT;

    while (retries > 0) {
        result = i2cWriteByteData(handle, 0, TEMP_CMD);
        if (result < 0) {
            fprintf(stderr, "Failed to write temperature command: %s\n", strerror(errno));
            retries--;
            gpioDelay(1000); // Wait 1 ms before retrying
            continue;
        }

        gpioDelay(20); // Wait for measurement (at least 15ms)

        result = i2cReadI2CBlockData(handle, 0, buf, 2);
        if (result < 0) {
            fprintf(stderr, "Failed to read temperature data: %s\n", strerror(errno));
            retries--;
            gpioDelay(1000); // Wait 1 ms before retrying
            continue;
        }

        if (result == 2) {
            unsigned int raw_temp = (buf[0] << 8) | buf[1];
            *temperature = (175.72 * raw_temp / 65536.0) - 46.85;
            return 0; // Success
        } else {
            fprintf(stderr, "Failed to read temperature data (short read): %s\n", strerror(errno));
            retries--;
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }

    fprintf(stderr, "Failed to read temperature after multiple retries\n");
    return -1; // Failure
}

