            retries--;
            gpioDelay(1000); // Wait 1 ms before retrying
            continue;
        }

        if (result == 2) {
            unsigned int raw_humidity = (buf[0] << 8) | buf[1];
            *humidity = (125.0 * raw_humidity / 65536.0) - 6.0;
            if (*humidity < 0) *humidity = 0;
            if (*humidity > 100) *humidity = 100;
            return 0; // Success
        } else {
            fprintf(stderr, "Failed to read humidity data (short read): %s\n", strerror(errno));
            retries--;
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }

    fprintf(stderr, "Failed to read humidity after multiple retries\n");
    return -1; // Failure
}

