#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define MEASURE_CMD 0x362F
#define DATA_LENGTH 9
#define HEADER_ROW "Timestamp,Pressure(Pa),Temperature(C)\n"

int i2c_handle;
FILE *log_file;

// CRC-8-H2F checksum calculation
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the sensor
int read_sensor_data(int handle, unsigned char *data) {
    if (i2cWriteByteData(handle, 0, MEASURE_CMD >> 8) < 0) {
        fprintf(stderr, "Error writing MSB of command.\n");
        return -1;
    }
    if (i2cWriteByteData(handle, 0, MEASURE_CMD & 0xFF) < 0) {
        fprintf(stderr, "Error writing LSB of command.\n");
        return -1;
    }
    gpioDelay(45); // Wait for measurement (45 ms)

    if (i2cReadI2CBlockData(handle, 0, (char *)data, DATA_LENGTH) != DATA_LENGTH) {
        fprintf(stderr, "Error reading data from sensor.\n");
        return -1;
    }
    return 0;
}

// Function to process the raw data
int process_sensor_data(const unsigned char *data, float *pressure, float *temperature) {
    // Checksums
    unsigned char pressure_data[3] = {data[0], data[1], data[2]};
    unsigned char temperature_data[3] = {data[3], data[4], data[5]};
    unsigned char scale_factor_data[3] = {data[6], data[7], data[8]};

    if (crc8(pressure_data, 2) != pressure_data[2] ||
        crc8(temperature_data, 2) != temperature_data[2] ||
        crc8(scale_factor_data, 2) != scale_factor_data[2]) {
        fprintf(stderr, "Checksum error.\n");
        return -1;
    }

    // Convert raw data to physical units
