    float temperature;
    time_t timestamp;
} sensor_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("enclosure_temp_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open error log file
    error_file = fopen("error_log.txt", "a");
    if (error_file == NULL) {
        perror("Error opening error log file");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Send measurement command
        if (send_command(i2c_handle, MEASURE_CMD_HIGH | MEASURE_CMD_LOW) != 0) {
            log_error("Failed to send measurement command");
            continue; // Skip to the next iteration
        }

