            continue; // Skip to the next iteration
        }

        // Convert to Celsius
        unsigned short raw_value = (data[0] << 8) | data[1];
        float temperature = convert_to_celsius(raw_value);

        // Log temperature
        log_temperature(temperature);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    fclose(error_file);
    gpioTerminate();

    return 0;
}

