int send_command(int handle, unsigned short command) {
    unsigned char cmd_msb = (command >> 8) & 0xFF;
    unsigned char cmd_lsb = command & 0xFF;

    int result = i2cWriteByteData(handle, cmd_msb, cmd_lsb);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return 1;
    }
    return 0;
}

