int read_data(int handle, unsigned char *data, int count) {
    int result = i2cReadI2CBlockData(handle, 0, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return 1;
    }
    return 0;
}

// CRC-8 checksum calculation
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Convert raw value to Celsius
float convert_to_celsius(unsigned short raw_value) {
    return -45 + 175 * (raw_value / 65535.0);
}

