    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(error_file, "%s, %s\n", timestamp, message);
    fflush(error_file); // Ensure data is written to disk immediately
}

