    }
    return crc;
}

// Function to read temperature and humidity from SHT40
int read_sht40(int fd, float *temperature, float *humidity) {
    uint8_t data[6];
    uint8_t cmd = MEASURE_CMD;

    // Send measurement command
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Wait for measurement (at least 8.5 ms)
    usleep(10000); // 10 ms

    // Read 6 bytes of data
    if (read(fd, data, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // CRC validation
    if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    int32_t raw_temperature = (data[0] << 8) | data[1];
    int32_t raw_humidity = (data[3] << 8) | data[4];

    *temperature = -45 + 175 * (float)raw_temperature / 65535.0;
    *humidity = 100 * (float)raw_humidity / 65535.0;

    return 0;
}

// Function to log data to file
void log_data(float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f C, Humidity: %.2f %%\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, humidity);
    fflush(log_file);
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("Closing I2C device and log file...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    float temperature, humidity;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("sht40_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        if (read_sht40(i2c_fd, &temperature, &humidity) == 0) {
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Error reading SHT40 sensor\n");
        }
        sleep(5);
    }

    return 0;
}

