#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define BUFFER_SIZE 60

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float temperature[BUFFER_SIZE];
    float humidity[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

CircularBuffer buffer;

// Function prototypes
int init_i2c();
int read_sensor(float *temperature, float *humidity);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
void control_fan(float temperature);
void log_data(float temperature, float humidity);
void signal_handler(int signal);
void init_circular_buffer(CircularBuffer *cb);
void add_to_circular_buffer(CircularBuffer *cb, float temperature, float humidity);
void print_circular_buffer(CircularBuffer *cb);

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Add data to circular buffer
void add_to_circular_buffer(CircularBuffer *cb, float temperature, float humidity) {
    cb->temperature[cb->head] = temperature;
    cb->humidity[cb->head] = humidity;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Print circular buffer contents
void print_circular_buffer(CircularBuffer *cb) {
    printf("\n--- Circular Buffer Contents ---\n");
    for (int i = 0; i < cb->count; i++) {
        int index = (cb->head - cb->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("Index: %d, Temperature: %.2f, Humidity: %.2f\n", index, cb->temperature[index], cb->humidity[index]);
    }
    printf("--- End of Buffer ---\n");
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor(float *temperature, float *humidity) {
    uint16_t raw_temp, raw_humidity;
    int result;

    // Trigger temperature measurement
    result = i2cWriteByte(i2c_handle, 0xE3);
    if (result != 0) {
        fprintf(stderr, "Error writing temperature command: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait 10 ms

    result = i2cReadWordData(i2c_handle, 0);
    if (result < 0) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1;
    }
    raw_temp = result;

    // Trigger humidity measurement
    result = i2cWriteByte(i2c_handle, 0xE5);
    if (result != 0) {
        fprintf(stderr, "Error writing humidity command: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait 10 ms

    result = i2cReadWordData(i2c_handle, 0);
    if (result < 0) {
        fprintf(stderr, "Error reading humidity data: %d\n", result);
        return -1;
    }
    raw_humidity = result;

    *temperature = convert_temperature(raw_temp);
    *humidity = convert_humidity(raw_humidity);

    return 0;
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temp) {
    return 175.72 * raw_temp / 65536.0 - 46.85;
}

// Convert raw humidity to percentage
float convert_humidity(uint16_t raw_humidity) {
    return 125.0 * raw_humidity / 65536.0 - 6.0;
}

// Control the cooling fan
void control_fan(float temperature) {
    if (temperature > TEMP_THRESHOLD_HIGH) {
        gpioWrite(FAN_GPIO, 1); // Turn fan ON
    } else if (temperature < TEMP_THRESHOLD_LOW) {
        gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    }
}

// Log data to circular buffer
void log_data(float temperature, float humidity) {
    add_to_circular_buffer(&buffer, temperature, humidity);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is initially OFF

    // Initialize circular buffer
    init_circular_buffer(&buffer);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature, humidity;
    int retries;

    // Main loop
    while (!terminate) {
        retries = 0;
        while (retries < 3) {
            if (read_sensor(&temperature, &humidity) == 0) {
                // Validate sensor readings
                if (temperature > -50.0 && temperature < 100.0 && humidity > 0.0 && humidity < 100.0) {
                    log_data(temperature, humidity);
                    control_fan(temperature);
                    break; // Exit retry loop on success
                } else {
                    fprintf(stderr, "Invalid sensor readings: Temperature=%.2f, Humidity=%.2f\n", temperature, humidity);
                }
            } else {
                fprintf(stderr, "I2C read failed, retrying... (%d/3)\n", retries + 1);
            }
            retries++;
            gpioDelay(100); // Wait 100 ms before retrying
        }

        if (retries == 3) {
            fprintf(stderr, "Failed to read sensor after 3 retries. Skipping.\n");
        }

        gpioDelay(2000); // Wait 2 seconds
    }

    // Cleanup
    gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    i2cClose(i2c_handle);
    gpioTerminate();

    print_circular_buffer(&buffer);

    return 0;
}

