#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Constants
#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define LED_GPIO 17
#define BUFFER_SIZE 20
#define CO2_THRESHOLD 1000

// SCD40 Commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86
#define CMD_GET_DATA_READY_STATUS 0xE4B8
#define CMD_READ_MEASUREMENT 0xEC05

// Data structure for sensor readings
typedef struct {
    time_t timestamp;
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer
sensor_data_t sensor_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int start_periodic_measurement();
int stop_periodic_measurement();
int read_sensor_data(uint16_t *co2, float *temperature, float *humidity);
uint8_t crc8(const uint8_t *data, int len);
void add_to_buffer(uint16_t co2, float temperature, float humidity);
void print_buffer();
void signal_handler(int signal);

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to start periodic measurement
int start_periodic_measurement() {
    char buf[2];
    buf[0] = (CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_START_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error starting periodic measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to stop periodic measurement
int stop_periodic_measurement() {
    char buf[2];
    buf[0] = (CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_STOP_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error stopping periodic measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint16_t *co2, float *temperature, float *humidity) {
    char buf[2];
    buf[0] = (CMD_READ_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_READ_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error sending read measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(1); // Small delay before reading

    char data[9];
    result = i2cReadDevice(i2c_handle, data, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // CRC validation
    if (crc8(data, 2) != data[2] ||
        crc8(data + 3, 2) != data[5] ||
        crc8(data + 6, 2) != data[8]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    *co2 = (uint16_t)((data[0] << 8) | data[1]);
    *temperature = -45 + 175 * ((float)((data[3] << 8) | data[4])) / 65535;
    *humidity = 100 * ((float)((data[6] << 8) | data[7])) / 65535;

    return 0;
}

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to add data to the circular buffer
void add_to_buffer(uint16_t co2, float temperature, float humidity) {
    sensor_buffer[buffer_index].timestamp = time(NULL);
    sensor_buffer[buffer_index].co2 = co2;
    sensor_buffer[buffer_index].temperature = temperature;
    sensor_buffer[buffer_index].humidity = humidity;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Sensor Readings ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Corrected index calculation
        printf("Timestamp: %ld, CO2: %d ppm, Temperature: %.2f °C, Humidity: %.2f %%\n",
               sensor_buffer[index].timestamp, sensor_buffer[index].co2, sensor_buffer[index].temperature, sensor_buffer[index].humidity);
    }
    printf("-------------------------\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Start periodic measurement
    if (start_periodic_measurement() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure LED GPIO
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        uint16_t co2;
        float temperature, humidity;

        // Check data ready status
        char buf[2];
        buf[0] = (CMD_GET_DATA_READY_STATUS >> 8) & 0xFF;
        buf[1] = CMD_GET_DATA_READY_STATUS & 0xFF;
        i2cWriteDevice(i2c_handle, buf, 2);
        gpioDelay(1); // Small delay

        char data[3];
        int result = i2cReadDevice(i2c_handle, data, 3);
        if (result != 3) {
            fprintf(stderr, "Error reading data ready status: %d\n", result);
            continue; // Skip to the next iteration
        }

        if (data[1] & 0x01) {
            // Read sensor data
            if (read_sensor_data(&co2, &temperature, &humidity) == 0) {
                // Add data to buffer
                add_to_buffer(co2, temperature, humidity);

                // Control LED
                if (co2 > CO2_THRESHOLD) {
                    gpioWrite(LED_GPIO, 1); // Turn LED on
                } else {
                    gpioWrite(LED_GPIO, 0); // Turn LED off
                }

                // Print buffer
                print_buffer();
            } else {
                fprintf(stderr, "Failed to read sensor data\n");
            }
        } else {
            // Data not ready, wait and try again
            gpioDelay(1000); // Wait 1 second
        }
    }

    // Stop periodic measurement
    if (stop_periodic_measurement() != 0) {
        fprintf(stderr, "Failed to stop periodic measurement\n");
    }

    // Close I2C
    i2cClose(i2c_handle);

    // Release GPIO
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioSetMode(LED_GPIO, PI_INPUT); // Set GPIO to input mode

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

