#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL 5 // seconds
#define TH_TIMEOUT 50      // milliseconds
#define TL_TIMEOUT 50      // milliseconds
#define MAX_CONSECUTIVE_FAILURES 3

volatile int terminate = 0;

void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log temperature reading to file
int log_temperature(const char* timestamp, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%s, %.2f\n", timestamp, temperature);
    fclose(fp);
    return 0;
}

// Function to read temperature from TMP05 sensor
float read_temperature() {
    int high_time = 0;
    int total_time = 0;
    int last_state = 0;
    int current_state;
    struct timespec start, end;
    double elapsed_time;

    // Wait for the start of a new cycle (low to high transition)
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        current_state = gpioRead(GPIO_PIN);
        if (current_state != last_state) {
            if (current_state == 0) { // Falling edge
                clock_gettime(CLOCK_MONOTONIC, &start);
                break;
            }
            last_state = current_state;
        }
        clock_gettime(CLOCK_MONOTONIC, &end);
        elapsed_time = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1000000000.0;
        if (elapsed_time > (double)TH_TIMEOUT / 1000.0) {
            fprintf(stderr, "Error: Timeout waiting for high time.\n");
            return -1000.0; // Indicate timeout error
        }
    }

    // Measure high time
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        current_state = gpioRead(GPIO_PIN);
        if (current_state != last_state) {
            if (current_state == 1) { // Rising edge
                clock_gettime(CLOCK_MONOTONIC, &end);
                elapsed_time = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1000000000.0;
                high_time = (int)elapsed_time;
                break;
            }
            last_state = current_state;
        }
        clock_gettime(CLOCK_MONOTONIC, &end);
        elapsed_time = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1000000000.0;
        if (elapsed_time > (double)TH_TIMEOUT / 1000.0) {
            fprintf(stderr, "Error: Timeout waiting for high time.\n");
            return -1000.0; // Indicate timeout error
        }
    }

    // Wait for the end of the cycle (high to low transition)
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        current_state = gpioRead(GPIO_PIN);
        if (current_state != last_state) {
            if (current_state == 0) { // Falling edge
                clock_gettime(CLOCK_MONOTONIC, &end);
                elapsed_time = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1000000000.0;
                total_time = (int)elapsed_time;
                break;
            }
            last_state = current_state;
        }
        clock_gettime(CLOCK_MONOTONIC, &end);
        elapsed_time = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1000000000.0;
        if (elapsed_time > (double)TL_TIMEOUT / 1000.0) {
            fprintf(stderr, "Error: Timeout waiting for total time.\n");
            return -1000.0; // Indicate timeout error
        }
    }

    // Calculate temperature
    float temperature = 4215.0 - (2143.0 * (float)high_time / (float)total_time);

    // Validate temperature
    if (temperature < -40.0 || temperature > 150.0) {
        fprintf(stderr, "Error: Temperature out of range: %.2f\n", temperature);
        return -1000.0; // Indicate out-of-range error
    }

    return temperature;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int consecutive_failures = 0;
    int valid_readings = 0;

    while (!terminate) {
        float temperature = read_temperature();

        if (temperature > -999.0) { // Valid reading
            valid_readings++;
            consecutive_failures = 0; // Reset failure count
            if (valid_readings >= 3) {
                char* timestamp = get_iso8601_timestamp();
                if (timestamp != NULL) {
                    if (log_temperature(timestamp, temperature) == 0) {
                        printf("Temperature: %.2f °C\n", temperature);
                    } else {
                        fprintf(stderr, "Error logging temperature.\n");
                    }
                    free(timestamp);
                } else {
                    fprintf(stderr, "Error getting timestamp.\n");
                }
            }
        } else {
            consecutive_failures++;
            if (consecutive_failures >= MAX_CONSECUTIVE_FAILURES) {
                char* timestamp = get_iso8601_timestamp();
                if (timestamp != NULL) {
                    if (log_temperature(timestamp, temperature) == 0) {
                        printf("SENSOR MALFUNCTION\n");
                    } else {
                        fprintf(stderr, "Error logging SENSOR MALFUNCTION.\n");
                    }
                    free(timestamp);
                } else {
                    fprintf(stderr, "Error getting timestamp for SENSOR MALFUNCTION.\n");
                }
                consecutive_failures = MAX_CONSECUTIVE_FAILURES; // Prevent further logging of SENSOR MALFUNCTION
            }
        }

        sleep(SAMPLE_INTERVAL);
    }

    gpioTerminate();
    return 0;
}

