#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_CMD 0x2400
#define CRC_POLYNOMIAL 0x31
#define SINE_PERIOD 3600 // 1 hour
#define SINE_AMPLITUDE 2.0
#define SINE_PHASE_SHIFT 0.0
#define LOG_FILE "environmental_data.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sht35(int i2c_handle, float *temperature, float *humidity);
float calculate_temperature(unsigned short raw_temperature);
float calculate_humidity(unsigned short raw_humidity);
float apply_sine_offset(float value, float amplitude, float phase_shift);
int log_data(float temperature, float humidity);
void signal_handler(int signal);

// CRC calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature and humidity from SHT35-DIS-B
int read_sht35(int i2c_handle, float *temperature, float *humidity) {
    unsigned char cmd[2] = {MEASURE_CMD >> 8, MEASURE_CMD & 0xFF};
    unsigned char data[6];
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
        if (result == 0) break; // Success
        fprintf(stderr, "I2C write failed (attempt %d): %d\n", 4 - retries, result);
        gpioDelay(1000); // 1 second delay
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "I2C write failed after 3 retries.\n");
        return -1;
    }

    gpioDelay(15); // Wait for measurement (at least 15 ms)

    retries = 3;
    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, (char *)data, 6);
        if (result == 6) break; // Success
        fprintf(stderr, "I2C read failed (attempt %d): %d\n", 4 - retries, result);
        gpioDelay(1000); // 1 second delay
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "I2C read failed after 3 retries.\n");
        return -1;
    }

    // CRC validation
    if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "CRC validation failed.\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    unsigned short raw_temperature = (data[0] << 8) | data[1];
    unsigned short raw_humidity = (data[3] << 8) | data[4];

    *temperature = calculate_temperature(raw_temperature);
    *humidity = calculate_humidity(raw_humidity);

    return 0;
}

// Function to calculate temperature in degrees Celsius
float calculate_temperature(unsigned short raw_temperature) {
    return -45.0 + (175.0 * (float)raw_temperature / 65535.0);
}

// Function to calculate relative humidity in %RH
float calculate_humidity(unsigned short raw_humidity) {
    return 100.0 * (float)raw_humidity / 65535.0;
}

// Function to apply a sinusoidal offset
float apply_sine_offset(float value, float amplitude, float phase_shift) {
    return value + amplitude * sin(2 * M_PI * (time_t)(time(NULL) % SINE_PERIOD) / SINE_PERIOD + phase_shift);
}

// Function to log data to a file
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    float temperature, humidity;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        result = read_sht35(i2c_handle, &temperature, &humidity);
        if (result == 0) {
            temperature = apply_sine_offset(temperature, SINE_AMPLITUDE, SINE_PHASE_SHIFT);
            humidity = apply_sine_offset(humidity, SINE_AMPLITUDE, SINE_PHASE_SHIFT);
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Logging NaN values.\n");
            log_data(NAN, NAN);
        }
        sleep(5);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

