        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        result = read_sht35(i2c_handle, &temperature, &humidity);
        if (result == 0) {
            temperature = apply_sine_offset(temperature, SINE_AMPLITUDE, SINE_PHASE_SHIFT);
            humidity = apply_sine_offset(humidity, SINE_AMPLITUDE, SINE_PHASE_SHIFT);
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Logging NaN values.\n");
            log_data(NAN, NAN);
        }
        sleep(5);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

