#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_CMD 0x2400
#define CSV_FILE "environment.csv"

int i2c_handle;

// Function to calculate CRC-8 checksum
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature and humidity from SHT35
int read_sht35(int i2c_handle, float *temperature, float *humidity) {
    unsigned char data[6];
    int result;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, 0, MEASURE_CMD >> 8);
    if (result < 0) {
        fprintf(stderr, "Error writing MSB of measurement command: %d\n", result);
        return -1;
    }
    result = i2cWriteByteData(i2c_handle, 0, MEASURE_CMD & 0xFF);
    if (result < 0) {
        fprintf(stderr, "Error writing LSB of measurement command: %d\n", result);
        return -1;
    }

    // Wait for measurement (at least 15 ms)
    gpioDelay(15000); // 15 ms

    // Read 6 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0, (char *)data, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    // Validate CRC checksums
    if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "CRC checksum error\n");
        return -1;
    }

    // Convert raw values to temperature and humidity
    int raw_temperature = (data[0] << 8) | data[1];
    int raw_humidity = (data[3] << 8) | data[4];

    *temperature = -45 + 175 * raw_temperature / 65535.0;
    *humidity = 100 * raw_humidity / 65535.0;

    return 0;
}

// Function to log data to CSV file
int log_data(const char *timestamp, float temperature, float humidity) {
    FILE *fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s\n", CSV_FILE);
        return -1;
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,temperature_c,humidity_pct\n");
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    float temperature, humidity;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read temperature and humidity
        if (read_sht35(i2c_handle, &temperature, &humidity) == 0) {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            // Log data to CSV file
            if (log_data(timestamp, temperature, humidity) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading SHT35 sensor\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    return 0;
}

