#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SI7021_ADDR 0x40
#define SI7021_MEASURE_TEMP 0xF3
#define SI7021_MEASURE_HUMIDITY 0xF5
#define SI7021_RESET 0xFE
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0x00

int i2c_fd;

// Function to calculate CRC8 checksum
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature and humidity from Si7021
int read_si7021(int fd, float *temperature, float *humidity) {
    unsigned char cmd[1] = {SI7021_MEASURE_HUMIDITY};
    unsigned char data[3];
    int retries = 3;
    int bytes_read;

    while (retries > 0) {
        if (write(fd, cmd, 1) != 1) {
            fprintf(stderr, "Error writing humidity command: %s\n", strerror(errno));
            retries--;
            usleep(10000); // 10ms delay
            continue;
        }

        usleep(10000); // Wait for measurement (10ms)

        bytes_read = read(fd, data, 3);
        if (bytes_read == 3) {
            if (crc8(data, 2) != data[2]) {
                fprintf(stderr, "CRC check failed for humidity\n");
                retries--;
                usleep(10000);
                continue;
            }

            unsigned int raw_humidity = (data[0] << 8) | data[1];
            *humidity = 125.0 * raw_humidity / 65536.0 - 6.0;

            cmd[0] = SI7021_MEASURE_TEMP;
            retries = 3; // Reset retries for temperature
            continue;
        } else if (bytes_read > 0) {
            fprintf(stderr, "Partial read for humidity, retrying...\n");
            retries--;
            usleep(10000);
            continue;
        } else {
            fprintf(stderr, "Error reading humidity data: %s\n", strerror(errno));
            retries--;
            usleep(10000);
            continue;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to read humidity after multiple retries\n");
        return -1;
    }

    retries = 3;
    while (retries > 0) {
        if (write(fd, cmd, 1) != 1) {
            fprintf(stderr, "Error writing temperature command: %s\n", strerror(errno));
            retries--;
            usleep(10000);
            continue;
        }

        usleep(10000); // Wait for measurement (10ms)

        bytes_read = read(fd, data, 3);
        if (bytes_read == 3) {
            if (crc8(data, 2) != data[2]) {
                fprintf(stderr, "CRC check failed for temperature\n");
                retries--;
                usleep(10000);
                continue;
            }

            unsigned int raw_temperature = (data[0] << 8) | data[1];
            *temperature = 175.72 * raw_temperature / 65536.0 - 46.85;

            return 0; // Success
        } else if (bytes_read > 0) {
            fprintf(stderr, "Partial read for temperature, retrying...\n");
            retries--;
            usleep(10000);
            continue;
        } else {
            fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
            retries--;
            usleep(10000);
            continue;
        }
    }

    fprintf(stderr, "Failed to read temperature after multiple retries\n");
    return -1;
}

// Function to log data to a CSV file
void log_data(float temperature, float humidity) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fp = fopen("environment.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, exiting gracefully...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    float temperature, humidity;
    int status;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        status = read_si7021(i2c_fd, &temperature, &humidity);
        if (status == 0) {
            log_data(temperature, humidity);
        } else {
            log_data(-999.0, -999.0); // Log error values
        }

        sleep(5);
    }

    // The following lines will never be reached due to the infinite loop.
    close(i2c_fd);
    return 0;
}

