#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define CONTINUOUS_MEASUREMENT_COMMAND 0x362F
#define SAMPLE_INTERVAL_SEC 1
#define FILENAME "airflow.dat"

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus(int bus, int address);
int write_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
int validate_crc(uint8_t data[], int count, uint8_t crc);
float convert_pressure(int16_t raw_pressure, int16_t scale_factor);
float convert_temperature(int16_t raw_temperature, int16_t scale_factor);
int log_data(FILE *fp, float pressure, float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus(int bus, int address) {
    int handle = i2cOpen(bus, address, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02x: %d\n", bus, address, handle);
        return -1;
    }
    return handle;
}

// Write command to the sensor
int write_command(int handle, uint16_t command) {
    uint8_t buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, (char *)buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate CRC-8 checksum
int validate_crc(uint8_t data[], int count, uint8_t crc) {
    uint8_t crc_calculated = 0xFF;
    for (int i = 0; i < count - 1; i++) {
        crc_calculated ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ 0x31;
            } else {
                crc_calculated <<= 1;
            }
        }
    }
    return (crc_calculated == crc);
}

// Convert raw pressure to Pascals
float convert_pressure(int16_t raw_pressure, int16_t scale_factor) {
    return (float)raw_pressure / scale_factor - 1000.0;
}

// Convert raw temperature to Celsius
float convert_temperature(int16_t raw_temperature, int16_t scale_factor) {
    return (float)raw_temperature / 200.0 - 45.0;
}

// Log data to file
int log_data(FILE *fp, float pressure, float temperature) {
    if (fwrite(&pressure, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Failed to write pressure to file\n");
        return -1;
    }
    if (fwrite(&temperature, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Failed to write temperature to file\n");
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, I2C_ADDRESS);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open file for logging
    fp = fopen(FILENAME, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for logging\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[9];
        int16_t raw_pressure, raw_temperature, scale_factor;
        float pressure, temperature;

        // Write continuous measurement command
        if (write_command(i2c_handle, CONTINUOUS_MEASUREMENT_COMMAND) != 0) {
            fprintf(stderr, "Failed to write continuous measurement command, retrying...\n");
            gpioDelay(100000); // Wait 0.1 seconds before retrying
            continue;
        }

        // Wait for conversion time (at least 20ms)
        gpioDelay(20000); // 20ms

        // Read data from sensor
        if (read_data(i2c_handle, data, 9) != 0) {
            fprintf(stderr, "Failed to read data from sensor, retrying...\n");
            gpioDelay(100000); // Wait 0.1 seconds before retrying
            continue;
        }

        // Validate CRC for pressure data
        if (!validate_crc(data, 2, data[2])) {
            fprintf(stderr, "CRC validation failed for pressure data\n");
            continue;
        }

        // Validate CRC for temperature data
        if (!validate_crc(data + 3, 2, data[5])) {
            fprintf(stderr, "CRC validation failed for temperature data\n");
            continue;
        }

        // Extract raw pressure and temperature values
        raw_pressure = (data[0] << 8) | data[1];
        raw_temperature = (data[3] << 8) | data[4];
        scale_factor = (data[6] << 8) | data[7];

        // Convert raw values to physical units
        pressure = convert_pressure(raw_pressure, scale_factor);
        temperature = convert_temperature(raw_temperature, scale_factor);

        // Log data to file
        if (log_data(fp, pressure, temperature) != 0) {
            fprintf(stderr, "Failed to log data to file\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Close I2C bus and file
    i2cClose(i2c_handle);
    fclose(fp);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

