int read_data(int handle, char *data, int count) {
    int result = i2cReadDevice(handle, data, count);
    if (result != count) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate CRC-8 checksum
int validate_crc(const char *data, int index, unsigned char crc) {
    unsigned char crc_calculated = 0xFF;
    unsigned char data_byte = data[index];

    for (int i = 0; i < 8; i++) {
        if (crc_calculated & 0x80) {
            crc_calculated = (crc_calculated << 1) ^ CRC_POLYNOMIAL;
        } else {
            crc_calculated <<= 1;
        }
        if (data_byte & 0x80) {
            crc_calculated ^= 1;
        }
        data_byte <<= 1;
    }

    return (crc_calculated != crc);
}

