            fprintf(stderr, "CRC validation failed, discarding data\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Convert data
        raw_pressure = (data[0] << 8) | data[1];
        raw_temperature = (data[3] << 8) | data[4];

        pressure = convert_pressure(raw_pressure);
        temperature = convert_temperature(raw_temperature);

        // Log data
        if (log_data(log_file, pressure, temperature) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

