#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor(int i2c_handle);
float convert_to_flow_rate(int raw_flow);
void set_fan_speed(float flow_rate);
void log_data(float flow_rate);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to read the sensor data
int read_sensor(int i2c_handle) {
    char buffer[2];
    int result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1; // Indicate error
    }
    return (buffer[0] << 8) | buffer[1];
}

// Function to convert raw flow reading to flow rate (SLPM)
float convert_to_flow_rate(int raw_flow) {
    return ((float)raw_flow / 1638.0) * 10.0;
}

// Function to set the fan speed based on flow rate
void set_fan_speed(float flow_rate) {
    int duty_cycle = (int)((flow_rate / 10.0) * 255.0);
    gpioPWM(FAN_GPIO, duty_cycle);
}

// Function to log the data to a file
void log_data(float flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency for the fan
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Airflow sensor and fan control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int raw_flow = read_sensor(i2c_handle);
        if (raw_flow >= 0) {
            float flow_rate = convert_to_flow_rate(raw_flow);
            set_fan_speed(flow_rate);
            log_data(flow_rate);
        } else {
            fprintf(stderr, "Error reading sensor, skipping this iteration.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 100 ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioPWM(FAN_GPIO, 0); // Turn off the fan
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

