#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define LPS33HW_ADDR 0x5D
#define CTRL_REG1 0x10
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C
#define WHO_AM_I 0x0F
#define ERROR_LOG_FILE "error.log"
#define DATA_LOG_FILE "environmental_data.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_lps33hw();
int read_lps33hw(int32_t *pressure, int16_t *temperature);
float convert_pressure(int32_t raw_pressure);
float convert_temperature(int16_t raw_temperature);
int log_data(float pressure, float temperature);
void signal_handler(int signal);
int log_error(const char *message);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize LPS33HW sensor
int init_lps33hw() {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        log_error("Failed to read WHO_AM_I register");
        return -1;
    }
    if (who_am_i != 0xB1) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%X\n", who_am_i);
        log_error("Incorrect WHO_AM_I value");
        return -1;
    }

    // Configure CTRL_REG1
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0xB0) < 0) {
        log_error("Failed to write to CTRL_REG1");
        return -1;
    }

    return 0;
}

// Read pressure and temperature data
int read_lps33hw(int32_t *pressure, int16_t *temperature) {
    char buffer[5];

    // Read pressure data (3 bytes)
    if (i2cReadI2CBlockData(i2c_handle, PRESS_OUT_XL, buffer, 3) < 0) {
        log_error("Failed to read pressure data");
        return -1;
    }

    *pressure = (int32_t)buffer[0] | ((int32_t)buffer[1] << 8) | ((int32_t)buffer[2] << 16);

    // Read temperature data (2 bytes)
    if (i2cReadI2CBlockData(i2c_handle, TEMP_OUT_L, buffer, 2) < 0) {
        log_error("Failed to read temperature data");
        return -1;
    }

    *temperature = (int16_t)buffer[0] | ((int16_t)buffer[1] << 8);

    return 0;
}

// Convert raw pressure to hPa
float convert_pressure(int32_t raw_pressure) {
    return (float)raw_pressure / 4096.0;
}

// Convert raw temperature to Celsius
float convert_temperature(int16_t raw_temperature) {
    return 42.5 + (float)raw_temperature / 480.0;
}

// Log data to file
int log_data(float pressure, float temperature) {
    FILE *fp = fopen(DATA_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure, temperature);
    if (ferror(fp)) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("Error flushing log file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Log errors to file
int log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening error log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Error: %s\n", timestamp, message);
    if (ferror(fp)) {
        perror("Error writing to error log file");
        fclose(fp);
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("Error flushing error log file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LPS33HW sensor
    if (init_lps33hw() != 0) {
        fprintf(stderr, "LPS33HW initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int32_t raw_pressure;
    int16_t raw_temperature;
    float pressure_hpa;
    float temperature_celsius;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_lps33hw(&raw_pressure, &raw_temperature) == 0) {
            // Convert data
            pressure_hpa = convert_pressure(raw_pressure);
            temperature_celsius = convert_temperature(raw_temperature);

            // Log data
            if (log_data(pressure_hpa, temperature_celsius) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // 1000 ms = 1 second
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

