#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define STLM75_ADDR 0x48
#define TEMP_REG 0x00
#define LED_GPIO 17
#define BUFFER_SIZE 10
#define TEMP_THRESHOLD 28.0

// Global variables
int i2c_handle;
double temp_buffer[BUFFER_SIZE];
int buffer_index = 0;
double running_average = 0.0;

// Function prototypes
int read_temperature(int i2c_handle);
void update_circular_buffer(double temperature);
double calculate_average(void);
void control_led(double average_temperature);
void signal_handler(int signal);

// Function to read temperature from STLM75 sensor
int read_temperature(int i2c_handle) {
    int raw_temp;
    int bytes_read;

    bytes_read = i2cReadWordData(i2c_handle, TEMP_REG);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", bytes_read);
        return -1; // Indicate error
    }

    raw_temp = bytes_read; // pigpio's i2cReadWordData returns the data directly.

    // Swap bytes (pigpio returns little-endian)
    raw_temp = ((raw_temp & 0xFF) << 8) | ((raw_temp & 0xFF00) >> 8);

    // Extract temperature value and convert to Celsius
    raw_temp = raw_temp >> 7; // Shift right by 7 bits
    double temperature = (double)raw_temp * 0.125; // Each LSB is 0.125 degrees C

    return (int)(temperature * 100); // Return as integer * 100 for precision
}

// Function to update the circular buffer
void update_circular_buffer(double temperature) {
    temp_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the running average
double calculate_average(void) {
    double sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temp_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Function to control the LED based on the average temperature
void control_led(double average_temperature) {
    if (average_temperature > TEMP_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, STLM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize temperature buffer with 0.0
    for (int i = 0; i < BUFFER_SIZE; i++) {
        temp_buffer[i] = 0.0;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int raw_temp = read_temperature(i2c_handle);
        if (raw_temp != -1) {
            double temperature = (double)raw_temp / 100.0; // Convert back from integer * 100
            update_circular_buffer(temperature);
            running_average = calculate_average();
            control_led(running_average);
            printf("Temperature: %.2f °C, Average: %.2f °C, LED: %s\n", temperature, running_average, gpioRead(LED_GPIO) ? "ON" : "OFF");
        }

        gpioDelay(1000); // Wait 1 second
    }

    return 0;
}

