#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// SCD30 I2C address
#define SCD30_ADDR 0x61

// I2C bus
#define I2C_BUS 1

// Measurement interval (seconds)
#define MEASUREMENT_INTERVAL 2

// Log file name
#define LOG_FILE "air_quality.log"

// Ventilation system control
#define CO2_THRESHOLD_LOW 800
#define CO2_THRESHOLD_HIGH 1200

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT_VALUE 0xFF

// Function prototypes
int scd30_init();
int scd30_read_data(float *co2, float *temperature, float *humidity);
void log_data(float co2, float temperature, float humidity);
void control_ventilation(float co2);
void signal_handler(int signal);
int crc8(const unsigned char *data, int len, unsigned char checksum);

// CRC-8 calculation function
int crc8(const unsigned char *data, int len, unsigned char checksum) {
    unsigned char crc = checksum;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// SCD30 initialization function
int scd30_init() {
    // Start periodic measurement (CO2, Temperature, Humidity, Pressure)
    unsigned char init_cmd[2] = {0x21, 0xB1};
    if (i2cWriteDevice(i2c_handle, (char *)init_cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to send start periodic measurement command: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(100); // Wait for initialization

    // Set measurement interval
    init_cmd[0] = 0x36;
    init_cmd[1] = (MEASUREMENT_INTERVAL >> 8) & 0xFF;
    init_cmd[2] = MEASUREMENT_INTERVAL & 0xFF;
    if (i2cWriteDevice(i2c_handle, (char *)init_cmd, 3) != 0) {
        fprintf(stderr, "Error: Failed to send set measurement interval command: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(100); // Wait for interval setting

    // Disable ambient pressure compensation
    init_cmd[0] = 0x46;
    init_cmd[1] = 0x00;
    if (i2cWriteDevice(i2c_handle, (char *)init_cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to send disable ambient pressure compensation command: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(100); // Wait for compensation setting

    return 0;
}

// SCD30 data reading function
int scd30_read_data(float *co2, float *temperature, float *humidity) {
    unsigned char data[18];
    unsigned char read_cmd[2] = {0x03, 0x00};
    unsigned char ready_cmd[2] = {0x02, 0x02};
    unsigned char ready_data[2];

    // Poll data-ready flag
    if (i2cWriteDevice(i2c_handle, (char *)ready_cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to send data ready command: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10); // Wait for response

    if (i2cReadDevice(i2c_handle, (char *)ready_data, 2) != 2) {
        fprintf(stderr, "Error: Failed to read data ready response: %s\n", strerror(errno));
        return -1;
    }

    if (ready_data[0] != 0x00 || ready_data[1] != 0x01) {
        fprintf(stderr, "Error: Data not ready\n");
        return -1;
    }

    // Read measurement data
    if (i2cWriteDevice(i2c_handle, (char *)read_cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to send read measurement command: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10); // Wait for response

    if (i2cReadDevice(i2c_handle, (char *)data, 18) != 18) {
        fprintf(stderr, "Error: Failed to read measurement data: %s\n", strerror(errno));
        return -1;
    }

    // CRC check
    if (crc8(data, 2, data[2]) != data[2] ||
        crc8(data + 3, 2, data[5]) != data[5] ||
        crc8(data + 6, 2, data[8]) != data[8] ||
        crc8(data + 9, 2, data[11]) != data[11] ||
        crc8(data + 12, 2, data[14]) != data[14] ||
        crc8(data + 15, 2, data[17]) != data[17]) {
        fprintf(stderr, "Error: CRC check failed\n");
        return -1;
    }

    // Convert data to float
    *co2 = (float)((data[0] << 8) | data[1]);
    *temperature = (float)((data[3] << 8) | data[4]);
    *humidity = (float)((data[6] << 8) | data[7]);

    return 0;
}

// Data logging function
void log_data(float co2, float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fflush(log_file);
}

// Ventilation control function
void control_ventilation(float co2) {
    if (co2 < CO2_THRESHOLD_LOW) {
        printf("Ventilation: OFF\n");
    } else if (co2 < CO2_THRESHOLD_HIGH) {
        printf("Ventilation: LOW\n");
    } else {
        printf("Ventilation: HIGH\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SCD30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize SCD30 sensor
    if (scd30_init() != 0) {
        fprintf(stderr, "Error: SCD30 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float co2, temperature, humidity;

    // Main loop
    while (!terminate) {
        if (scd30_read_data(&co2, &temperature, &humidity) == 0) {
            log_data(co2, temperature, humidity);
            control_ventilation(co2);
        } else {
            fprintf(stderr, "Error: Failed to read data\n");
        }

        gpioDelay(MEASUREMENT_INTERVAL * 1000); // Wait for measurement interval
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

