#define SDP32_ADDR 0x21

// I2C bus
#define I2C_BUS 1

// Continuous measurement command
#define MEASURE_CMD_MSB 0x36
#define MEASURE_CMD_LSB 0x2F

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables for I2C handle and program termination
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t raw_pressure;
    int16_t raw_temperature;
    uint16_t scale_factor;
    float pressure_pa;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int start_continuous_measurement();
int read_sensor_data(sensor_data_t *data);
uint8_t crc8(const uint8_t *data, int len);
float convert_pressure(int16_t raw_pressure, uint16_t scale_factor);
void log_data(const sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP32_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Start continuous measurement on the SDP32
int start_continuous_measurement() {
    char cmd[2] = {MEASURE_CMD_MSB, MEASURE_CMD_LSB};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data from the SDP32
int read_sensor_data(sensor_data_t *data) {
    char buffer[9];
    int result = i2cReadDevice(i2c_handle, buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }

    // Extract raw data
    data->raw_pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->raw_temperature = (int16_t)((buffer[3] << 8) | buffer[4]);
    data->scale_factor = (uint16_t)((buffer[6] << 8) | buffer[7]);

    // CRC validation
    if (crc8(buffer, 3) != buffer[2] ||
        crc8(buffer + 3, 3) != buffer[5] ||
        crc8(buffer + 6, 3) != buffer[8]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

