#include <errno.h>

// Sensor I2C address
#define SDP810_ADDR 0x25

// I2C bus
#define I2C_BUS 1

// Continuous measurement command
#define MEASURE_CMD 0x3615

// CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
uint8_t crc8(const uint8_t *data, int len);
sensor_data_t process_data(const uint8_t *data);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Send command to sensor
int send_command(int handle, uint16_t command) {
    uint8_t buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write command: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read data from sensor
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// CRC-8 calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Process sensor data
sensor_data_t process_data(const uint8_t *data) {
    sensor_data_t result;
    // Extract raw values and scale factors
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];
    int16_t scale_factor_pressure = (data[6] << 8) | data[7];
    int16_t scale_factor_temperature = (data[8] << 8) | data[9];

    // Validate CRC
    if (crc8(data, 3) != data[2] || crc8(data + 3, 3) != data[5] || crc8(data + 6, 3) != data[8]) {
        fprintf(stderr, "CRC mismatch\n");
        result.pressure = -999.0; // Indicate error
        result.temperature = -999.0; // Indicate error
        return result;
    }

    // Convert raw values
    result.pressure = (float)raw_pressure / (float)scale_factor_pressure;
    result.temperature = (float)raw_temperature / 200.0;

    return result;
}

// Log sensor data
void log_data(sensor_data_t data) {
    printf("Pressure: %.2f Pa, Temperature: %.2f C\n", data.pressure, data.temperature);
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[9];
        sensor_data_t sensor_data;

        // Send measurement command
        if (send_command(i2c_handle, MEASURE_CMD) != 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            continue; // Try again
        }

        // Wait for conversion (at least 45 ms)
        gpioDelay(50000); // 50 ms

        // Read data from sensor
        if (read_data(i2c_handle, data, 9) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue; // Try again
        }

        // Process data
        sensor_data = process_data(data);

        // Log data
        if (sensor_data.pressure != -999.0 && sensor_data.temperature != -999.0) {
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data, skipping logging\n");
        }

        // Wait 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

