        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[9];
        sensor_data_t sensor_data;

        // Send measurement command
        if (send_command(i2c_handle, MEASURE_CMD) != 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            continue; // Try again
        }

        // Wait for conversion (at least 45 ms)
        gpioDelay(50000); // 50 ms

        // Read data from sensor
        if (read_data(i2c_handle, data, 9) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue; // Try again
        }

        // Process data
        sensor_data = process_data(data);

        // Log data
        if (sensor_data.pressure != -999.0 && sensor_data.temperature != -999.0) {
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data, skipping logging\n");
        }

        // Wait 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

