#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define HDC1000_ADDR 0x40
#define CONFIG_REG 0x02
#define TEMP_REG 0x00

int i2c_fd;

void signal_handler(int sig);
int init_i2c(void);
int configure_sensor(void);
int read_sensor_data(uint16_t *temperature, uint16_t *humidity);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
int log_data(float temperature, float humidity);

int main()
{
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_i2c() < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    if (configure_sensor() < 0) {
        fprintf(stderr, "Failed to configure sensor. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    uint16_t raw_temperature, raw_humidity;
    float temperature, humidity;

    while (1) {
        if (read_sensor_data(&raw_temperature, &raw_humidity) == 0) {
            temperature = convert_temperature(raw_temperature);
            humidity = convert_humidity(raw_humidity);
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying.\n");
        }

        sleep(5);
    }

    return 0;
}

int init_i2c(void)
{
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int configure_sensor(void)
{
    uint8_t config_data = 0x00; // Default configuration: 14-bit resolution, enable temperature and humidity
    uint8_t buf[3];

    buf[0] = CONFIG_REG;
    buf[1] = (config_data >> 8) & 0xFF;
    buf[2] = config_data & 0xFF;

    if (write(i2c_fd, buf, 3) != 3) {
        perror("Error writing to configuration register");
        return -1;
    }

    return 0;
}

int read_sensor_data(uint16_t *temperature, uint16_t *humidity)
{
    uint8_t buf[4];
    uint8_t temp_buf[2];
    uint8_t hum_buf[2];

    // Trigger measurement by writing to the temperature register
    uint8_t trigger_buf[1];
    trigger_buf[0] = TEMP_REG;
    if (write(i2c_fd, trigger_buf, 1) != 1) {
        perror("Error triggering measurement");
        return -1;
    }

    usleep(20000); // Wait for at least 20 ms

    // Read 4 bytes: 2 bytes temperature, 2 bytes humidity
    if (read(i2c_fd, buf, 4) != 4) {
        perror("Error reading sensor data");
        return -1;
    }

    temp_buf[0] = buf[0];
    temp_buf[1] = buf[1];
    hum_buf[0] = buf[2];
    hum_buf[1] = buf[3];

    *temperature = (temp_buf[0] << 8) | temp_buf[1];
    *humidity = (hum_buf[0] << 8) | hum_buf[1];

    return 0;
}

float convert_temperature(uint16_t raw_temp)
{
    return ((float)raw_temp / 65536.0) * 165.0 - 40.0;
}

float convert_humidity(uint16_t raw_humidity)
{
    return ((float)raw_humidity / 65536.0) * 100.0;
}

int log_data(float temperature, float humidity)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Timestamp: %s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    return 0;
}

void signal_handler(int sig)
{
    printf("Caught signal %d. Cleaning up and exiting.\n", sig);
    close(i2c_fd);
    exit(0);
}

