int read_pressure() {
    char buffer[2]; // Assuming 2 bytes for pressure data
    int result;

    result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REGISTER, buffer, 2);

    if (result < 0) {
        fprintf(stderr, "Error reading pressure data: %d\n", result);
        return -1; // Indicate error
    }

    // Combine the two bytes into a single integer (assuming little-endian)
    int pressure = (buffer[1] << 8) | buffer[0];

    return pressure;
}

