#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Sensor I2C address
#define ICP10101_ADDR 0x63

// I2C bus
#define I2C_BUS 1

// Calibration data registers
#define CALIB_REG_START 0x10
#define CALIB_DATA_LENGTH 8

// Measurement command
#define MEASURE_CMD 0x40

// Measurement delay
#define MEASUREMENT_DELAY_US 7000

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Calibration coefficients
double c0, c1, c00, c10, c01, c11, c20, c21, c30;

// Function prototypes
int read_calibration_data();
double calculate_scale_factor(double c0, double c1, double c00, double c10, double c01, double c11, double c20, double c21, double c30, double temperature);
double calculate_pressure(double c0, double c1, double c00, double c10, double c01, double c11, double c20, double c21, double c30, double temperature, double raw_pressure);
double calculate_temperature(double c0, double c1, double c00, double c10, double c01, double c11, double c20, double c21, double c30, double raw_temperature);
void log_data(double temperature, double pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read calibration data from the sensor
int read_calibration_data() {
    char buf[CALIB_DATA_LENGTH];
    int result = i2cReadI2CBlockData(i2c_handle, CALIB_REG_START, buf, CALIB_DATA_LENGTH);

    if (result < 0) {
        fprintf(stderr, "Error reading calibration data: %d\n", result);
        return -1;
    }

    c0 = (double)((uint16_t)buf[0] | ((uint16_t)buf[1] << 8));
    c1 = (double)((int16_t)buf[2] | ((int16_t)buf[3] << 8));
    c00 = (double)((uint16_t)buf[4] | ((uint16_t)buf[5] << 8));
    c10 = (double)((int16_t)buf[6] | ((int16_t)buf[7] << 8));

    return 0;
}

// Function to calculate the pressure scale factor
double calculate_scale_factor(double c0, double c1, double c00, double c10, double c01, double c11, double c20, double c21, double c30, double temperature) {
    double temp_double = temperature;
    double temp_squared = temp_double * temp_double;
    double temp_cubed = temp_squared * temp_double;
    double temp_fourth = temp_cubed * temp_double;

    return c0 + c1 * temp_double + c00 + c10 * temp_squared + c01 * temp_cubed + c11 * temp_fourth + c20 * temp_cubed + c21 * temp_fourth + c30 * temp_squared;
}

// Function to calculate the pressure in Pascals
double calculate_pressure(double c0, double c1, double c00, double c10, double c01, double c11, double c20, double c21, double c30, double temperature, double raw_pressure) {
    double scale_factor = calculate_scale_factor(c0, c1, c00, c10, c01, c11, c20, c21, c30, temperature);
    return raw_pressure * scale_factor;
}

// Function to calculate the temperature in Celsius
double calculate_temperature(double c0, double c1, double c00, double c10, double c01, double c11, double c20, double c21, double c30, double raw_temperature) {
    return raw_temperature;
}

// Function to log the data with an ISO-8601 timestamp
void log_data(double temperature, double pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
