    int raw_pressure;
    float pressure_kPa;

    // Trigger measurement (replace MEASURE_CMD with the actual command)
    result = i2cWriteByteData(i2c_handle, 0x00, MEASURE_CMD); // Assuming register 0x00 for command
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1.0; // Indicate error
    }
    gpioDelay(10); // Wait for measurement to complete (adjust as needed)

    // Read pressure data (MSB and LSB)
    result = i2cReadI2CBlockData(i2c_handle, PRESSURE_MSB_REG, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1.0; // Indicate error
    }

    // Combine MSB and LSB to get the raw pressure value
    raw_pressure = (buf[0] << 8) | buf[1];

    // Convert raw value to kPa
    pressure_kPa = raw_pressure * SCALING_FACTOR;

    return pressure_kPa;
}

