#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASURE_CMD 0x362F
#define SAMPLE_INTERVAL_MS 500

int i2c_handle;

// CRC-8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SDP800 sensor
int read_sdp800(int i2c_handle, float *pressure, float *temperature) {
    unsigned char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    unsigned char data[9];
    int result;

    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(45); // Wait 45 ms

    result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // CRC validation
    if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5] || crc8(data + 6, 2) != data[8]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert raw data to pressure and temperature
    int raw_pressure = (data[0] << 8) | data[1];
    int raw_temperature = (data[3] << 8) | data[4];

    *pressure = (float)raw_pressure / 60.0;
    *temperature = (float)raw_temperature / 200.0;

    return 0;
}

// Function to log data to a file
int log_data(const char *filename, float pressure, float temperature) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s\n", filename);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    float pressure, temperature;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        result = read_sdp800(i2c_handle, &pressure, &temperature);
        if (result == 0) {
            result = log_data("pressure_log.txt", pressure, temperature);
            if (result != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

