int initialize_i2c();
int read_pressure_sensor(unsigned short *raw_pressure);
float convert_to_kPa(unsigned short raw_pressure);
void log_pressure_data(float pressure_kPa);
void check_pressure_range(float pressure_kPa);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
