    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read pressure sensor data
int read_pressure_sensor(unsigned short *raw_pressure) {
    char buffer[2];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, PRESSURE_REGISTER, buffer, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Failed to read pressure data: %d\n", bytes_read);
        i2cClose(i2c_handle);
        i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
        if (i2c_handle < 0) {
            fprintf(stderr, "Failed to reopen I2C device: %d\n", i2c_handle);
            return -1;
        }
        return -1; // Indicate failure
    }

    *raw_pressure = (buffer[0] << 8) | buffer[1];
    return 0;
}

