    if (pressure_kPa < SAFE_MIN_PRESSURE || pressure_kPa > SAFE_MAX_PRESSURE) {
        fprintf(stderr, "WARNING: Pressure is outside the safe range: %.2f kPa\n", pressure_kPa);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    unsigned short raw_pressure;
    float pressure_kPa;

    // Main loop
    while (1) {
