#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define DEVICE_ID_REG 0x0F
#define TEMP_REG 0x00
#define TEMP_SCALE 0.0078125
#define DATA_FILE "greenhouse_temps.dat"

// Global variables
int i2c_handle;
FILE *data_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int verify_device_id(int handle);
float read_temperature(int handle);
int write_data_to_file(FILE *file, float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to verify the TMP117 device ID
int verify_device_id(int handle) {
    int device_id = i2cReadByteData(handle, DEVICE_ID_REG);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", device_id);
        return -1;
    }

    if (device_id != 0x0117) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", device_id);
        return -1;
    }

    printf("Device ID verified: 0x%02X\n", device_id);
    return 0;
}

// Function to read the temperature from the TMP117
float read_temperature(int handle) {
    int16_t raw_temp = i2cReadWordData(handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", raw_temp);
        return -1000.0; // Indicate an error with a very low temperature
    }

    // Convert raw temperature to Celsius
    float temperature = (float)raw_temp * TEMP_SCALE;
    return temperature;
}

// Function to write the temperature data to a file
int write_data_to_file(FILE *file, float temperature) {
    size_t bytes_written = fwrite(&temperature, sizeof(float), 1, file);
    if (bytes_written != 1) {
        fprintf(stderr, "Error writing to file\n");
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify device ID
    if (verify_device_id(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open data file for appending
    data_file = fopen(DATA_FILE, "ab");
    if (data_file == NULL) {
        fprintf(stderr, "Error opening file for writing\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read temperature
        float temperature = read_temperature(i2c_handle);
        if (temperature > -999.0) { // Check for valid temperature reading
            // Write data to file
            if (write_data_to_file(data_file, temperature) != 0) {
                fprintf(stderr, "Error writing temperature to file, but continuing...\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature, but continuing...\n");
        }

        // Wait 60 seconds
        sleep(60);
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(data_file);
    gpioTerminate();

    return 0;
}

