#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_SEC 5
#define LOG_FILE "temperature_log.dat"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_pigpio();
int init_i2c();
float read_temperature();
void add_to_buffer(CircularBuffer *cb, float temp);
void flush_buffer_to_file(CircularBuffer *cb, const char *filename);
void signal_handler(int signal);
void cleanup();

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from TMP117
float read_temperature() {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1000.0; // Indicate error with a very low temperature
    }

    // Convert big-endian to little-endian
    uint16_t raw_temp = (buf[1] << 8) | buf[0];

    // Convert to Celsius
    float temperature = raw_temp * 0.0078125;
    return temperature;
}

// Add temperature to circular buffer
void add_to_buffer(CircularBuffer *cb, float temp) {
    cb->buffer[cb->head] = temp;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Flush buffer to file
void flush_buffer_to_file(CircularBuffer *cb, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for writing\n");
        return;
    }

    size_t bytes_written = fwrite(cb->buffer, sizeof(float), cb->count, fp);
    if (bytes_written != cb->count) {
        fprintf(stderr, "Error writing to file\n");
    }

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    i2cClose(i2c_handle);
    gpioTerminate();
    fprintf(stderr, "Resources released.\n");
}

int main() {
    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    CircularBuffer buffer = {{0.0}, 0, 0};

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for valid temperature reading
            add_to_buffer(&buffer, temperature);
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping sample.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Flush buffer to file before exiting
    flush_buffer_to_file(&buffer, LOG_FILE);

    // Cleanup resources
    cleanup();

    return 0;
}

