#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define LOG_FILE "temperature_log.txt"

int i2c_handle;

// Function to handle Ctrl+C signal
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Exiting gracefully...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read temperature from TMP117 sensor
float read_temperature() {
    char buf[2];
    int result;
    short raw_temp;
    float temperature;

    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -273.15; // Return absolute zero on error
    }

    raw_temp = (buf[0] << 8) | buf[1];
    temperature = raw_temp * 0.0078125;

    return temperature;
}

// Function to log temperature to file
void log_temperature(float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    char log_entry[50];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    snprintf(log_entry, sizeof(log_entry), "%s, Temperature: %.2f C\n", timestamp, temperature);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    if (fputs(log_entry, fp) == EOF) {
        fprintf(stderr, "Error writing to log file!\n");
    }

    fclose(fp);
}

int main() {
    int result;
    float temperature;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        temperature = read_temperature();
        if (temperature > -273.0) {
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Check sensor connection.\n");
        }
        gpioDelay(1000); // Wait for 1 second
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

