#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x49
#define FLOW_SCALE 16384.0
#define TEMP_SCALE 4096.0
#define FLOW_OFFSET 0.1
#define TEMP_OFFSET 0.1
#define FLOW_SLOPE 0.8
#define TEMP_SLOPE 0.8
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor_data(int i2c_handle, unsigned char *data);
float convert_flow(unsigned int raw_flow);
float convert_temperature(unsigned int raw_temp);
void log_data(float flow_rate, float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Function to read sensor data from I2C
int read_sensor_data(int i2c_handle, unsigned char *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 4);
    if (bytes_read != 4) {
        fprintf(log_file, "%s I2C read error: %d bytes read\n", __func__, bytes_read);
        fflush(log_file);
        return -1; // Indicate error
    }
    return 0; // Indicate success
}

// Function to convert raw flow data to SLPM
float convert_flow(unsigned int raw_flow) {
    return ((float)raw_flow / FLOW_SCALE) - FLOW_OFFSET;
}

// Function to convert raw temperature data to Celsius
float convert_temperature(unsigned int raw_temp) {
    return ((float)raw_temp / TEMP_SCALE) - TEMP_OFFSET;
}

// Function to log data to file
void log_data(float flow_rate, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Flow: %.2f SLPM, Temperature: %.2f °C\n", timestamp, flow_rate, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned char sensor_data[4];
    int first_read = 1;
    int second_read = 0;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, sensor_data) == 0) {
            unsigned int raw_flow = (sensor_data[0] << 8) | sensor_data[1];
            unsigned int raw_temp = (sensor_data[2] << 8) | sensor_data[3];

            // Convert data
            float flow_rate = convert_flow(raw_flow);
            float temperature = convert_temperature(raw_temp);

            // Log data
            log_data(flow_rate, temperature);

            // Discard the first two reads
            if (first_read) {
                first_read = 0;
            } else if (second_read) {
                second_read = 0;
            }
        } else {
            fprintf(log_file, "%s I2C read failed, attempting re-initialization...\n", __func__);
            fflush(log_file);
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
            }
        }

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

