#include <pigpio.h>

#define DHT11_GPIO 4
#define START_SIGNAL_LOW 18000
#define START_SIGNAL_HIGH 18000
#define DATA_BIT_LOW 50
#define DATA_BIT_HIGH_MIN 26
#define DATA_BIT_HIGH_MAX 70
#define CHECKSUM_THRESHOLD 2
#define TIMEOUT_US 50000 // 50ms

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;
FILE *log_file = NULL;

// Structure to hold DHT11 data
typedef struct {
    int humidity;
    int temperature;
} DHT11Data;

// Function prototypes
int init_gpio();
int send_start_signal();
int read_response();
int read_data_bits();
int validate_checksum(int data[]);
DHT11Data process_data(int data[]);
void log_data(DHT11Data data);
void signal_handler(int signal);
void cleanup();

// Function to initialize the GPIO library and set the GPIO pin mode
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(DHT11_GPIO, PI_OUTPUT);
    return 0;
}

// Function to send the start signal to the DHT11 sensor
int send_start_signal() {
    gpioSetMode(DHT11_GPIO, PI_OUTPUT);
    gpioWrite(DHT11_GPIO, 0); // Low
    gpioDelay(START_SIGNAL_LOW);
    gpioWrite(DHT11_GPIO, 1); // High
    gpioDelay(START_SIGNAL_HIGH);
    gpioSetMode(DHT11_GPIO, PI_INPUT); // Release the line
    gpioDelay(10); // Small delay after releasing the line
    return 0;
}

// Function to read the sensor's response to the start signal
int read_response() {
    int response_low = 0;
    int response_high = 0;
    int timeout_count = 0;

    // Wait for the low response
    while (gpioRead(DHT11_GPIO) == 1 && timeout_count < TIMEOUT_US) {
        gpioDelay(1); // Wait 1 us
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT_US) {
        fprintf(log_file, "Error: Timeout waiting for low response\n");
        fflush(log_file);
        return -1;
    }

    response_low = 1; // Mark as received

    // Wait for the high response
    timeout_count = 0;
    while (gpioRead(DHT11_GPIO) == 0 && timeout_count < TIMEOUT_US) {
        gpioDelay(1); // Wait 1 us
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT_US) {
        fprintf(log_file, "Error: Timeout waiting for high response\n");
        fflush(log_file);
        return -1;
    }

    response_high = 1; // Mark as received

    return (response_low << 1) | response_high; // Return combined response
}

// Function to read the 40 data bits from the DHT11 sensor
int read_data_bits() {
    int data[40];
    int bit_index = 0;
    int timeout_count = 0;

    while (bit_index < 40 && !terminate) {
        // Wait for the low bit
        while (gpioRead(DHT11_GPIO) == 1 && timeout_count < TIMEOUT_US) {
            gpioDelay(1); // Wait 1 us
            timeout_count++;
        }

        if (timeout_count >= TIMEOUT_US) {
            fprintf(log_file, "Error: Timeout waiting for low bit %d\n", bit_index + 1);
            fflush(log_file);
            return -1; // Indicate error
        }

        // Measure the high pulse duration
        timeout_count = 0;
        while (gpioRead(DHT11_GPIO) == 0 && timeout_count < TIMEOUT_US) {
            gpioDelay(1); // Wait 1 us
            timeout_count++;
        }

        if (timeout_count >= TIMEOUT_US) {
            fprintf(log_file, "Error: Timeout waiting for high bit %d\n", bit_index + 1);
            fflush(log_file);
            return -1; // Indicate error
        }

        // Determine the bit value based on the high pulse duration
        if (timeout_count < 30) { // Empirical threshold
            data[bit_index] = 0; // Short pulse -> '0'
        } else if (timeout_count < 100) { // Long pulse -> '1'
            data[bit_index] = 1;
        } else {
            fprintf(log_file, "Error: Invalid high pulse duration for bit %d\n", bit_index + 1);
            fflush(log_file);
            return -1; // Indicate error
        }

        bit_index++;
    }

    return 0; // Indicate success
}

// Function to validate the checksum of the received data
int validate_checksum(int data[]) {
    int checksum = 0;
    for (int i = 0; i < 4; i++) {
        checksum += data[i];
    }

    int calculated_checksum = (data[4] % 256);

    if (checksum != calculated_checksum) {
        fprintf(log_file, "Error: Checksum mismatch. Expected %d, got %d\n", checksum, calculated_checksum);
        fflush(log_file);
        return -1;
    }

    return 0;
}

// Function to process the raw data and extract temperature and humidity
DHT11Data process_data(int data[]) {
    DHT11Data dht11_data;

    dht11_data.humidity = (data[0] << 8) | data[1];
    dht11_data.temperature = (data[2] << 8) | data[3];

    return dht11_data;
}

// Function to log the temperature and humidity data to a file
void log_data(DHT11Data data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, Humidity: %d, Temperature: %d\n", timestamp, data.humidity, data.temperature);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(log_file, "Received signal %d, terminating...\n", signal);
    fflush(log_file);
    terminate = 1;
}

// Cleanup function to release GPIO resources and close the log file
void cleanup() {
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the GPIO library
    if (init_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("dht11_readings.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    fprintf(log_file, "Starting DHT11 sensor readings...\n");
    fflush(log_file);

    while (!terminate) {
        // Send the start signal
        if (send_start_signal() != 0) {
            fprintf(log_file, "Error: Failed to send start signal\n");
            fflush(log_file);
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Read the sensor's response
        int response = read_response();
        if (response < 0) {
            fprintf(log_file, "Error: Failed to read sensor response\n");
            fflush(log_file);
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Read the data bits
        if (read_data_bits() != 0) {
            fprintf(log_file, "Error: Failed to read data bits\n");
            fflush(log_file);
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Validate the checksum
        if (validate_checksum((int[]){data[0], data[1], data[2], data[3], data[4]}) != 0) {
            fprintf(log_file, "Error: Checksum validation failed\n");
            fflush(log_file);
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Process the data
        DHT11Data dht11_data = process_data((int[]){data[0], data[1], data[2], data[3], data[4]});

        // Log the data
        log_data(dht11_data);

        // Wait for 2 seconds
        gpioDelay(2000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

