// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x60
#define PRESSURE_REGISTER 0x0A2C
#define TEMPERATURE_REGISTER 0x0A2E
#define PRESSURE_MIN 0
#define PRESSURE_MAX 800.0
#define OUTPUT_MIN 0
#define OUTPUT_MAX 32768
#define TEMPERATURE_SCALE 0.01
#define TEMPERATURE_OFFSET -40.0
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_pressure(int i2c_handle, uint16_t *raw_pressure);
int read_temperature(int i2c_handle, int16_t *raw_temperature);
float convert_pressure(uint16_t raw_pressure);
float convert_temperature(int16_t raw_temperature);
int log_data(float pressure_kPa, float temperature_C);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Function to read pressure from the sensor
int read_pressure(int i2c_handle, uint16_t *raw_pressure) {
    char buffer[2];
    int result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REGISTER, buffer, 2);
    if (result != 2) {
        fprintf(log_file, "%s Error reading pressure: %d\n", get_timestamp(), result);
        fflush(log_file);
        return -1;
    }
    *raw_pressure = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Function to read temperature from the sensor
int read_temperature(int i2c_handle, int16_t *raw_temperature) {
    char buffer[2];
    int result = i2cReadI2CBlockData(i2c_handle, TEMPERATURE_REGISTER, buffer, 2);
    if (result != 2) {
        fprintf(log_file, "%s Error reading temperature: %d\n", get_timestamp(), result);
        fflush(log_file);
        return -1;
    }
    *raw_temperature = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Function to convert raw pressure to kPa
float convert_pressure(uint16_t raw_pressure) {
    return (raw_pressure - OUTPUT_MIN) * (PRESSURE_MAX - PRESSURE_MIN) / (OUTPUT_MAX - OUTPUT_MIN) + PRESSURE_MIN;
}

// Function to convert raw temperature to Celsius
float convert_temperature(int16_t raw_temperature) {
    return raw_temperature * TEMPERATURE_SCALE + TEMPERATURE_OFFSET;
}

