    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s Pressure: %.2f kPa, Temperature: %.2f C\n", timestamp, pressure_kPa, temperature_C);
    fflush(log_file);
    return 0;
}

