#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define STTS2004_ADDR 0x4A
#define TEMP_REG 0x00
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define TEMP_HYSTERESIS 0.1
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10
#define LOG_INTERVAL_SEC 1

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_reg(int fd, uint8_t reg, uint8_t *data, int len);
float read_temperature(int fd);
void control_led(float temperature);
void log_temperature(float temperature);
void signal_handler(int sig);
int setup_gpio(const char *chipname, int pin);
int cleanup_gpio(void);

// I2C read function with retry
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len) {
    int retries = I2C_RETRY_COUNT;
    int delay_ms = I2C_RETRY_DELAY_MS;
    int result;

    while (retries > 0) {
        result = i2c_smbus_read_i2c_block_data(fd, reg, len, data);
        if (result >= 0) {
            return 0; // Success
        }
        fprintf(stderr, "I2C read error (reg 0x%02X, len %d): %s\n", reg, len, strerror(errno));
        retries--;
        usleep(delay_ms * 1000); // Exponential backoff
    }

    fprintf(stderr, "I2C read failed after %d retries (reg 0x%02X, len %d)\n", I2C_RETRY_COUNT, reg, len);
    return -1; // Failure
}

// I2C write function with retry
int i2c_write_reg(int fd, uint8_t reg, uint8_t *data, int len) {
    int retries = I2C_RETRY_COUNT;
    int delay_ms = I2C_RETRY_DELAY_MS;
    int result;

    while (retries > 0) {
        result = i2c_smbus_write_i2c_block_data(fd, reg, data, len);
        if (result >= 0) {
            return 0; // Success
        }
        fprintf(stderr, "I2C write error (reg 0x%02X, len %d): %s\n", reg, len, strerror(errno));
        retries--;
        usleep(delay_ms * 1000); // Exponential backoff
    }

    fprintf(stderr, "I2C write failed after %d retries (reg 0x%02X, len %d)\n", I2C_RETRY_COUNT, reg, len);
    return -1; // Failure
}

// Read temperature from STTS2004
float read_temperature(int fd) {
    uint8_t data[2];
    int16_t raw_temp;
    float temperature;

    if (i2c_read_reg(fd, TEMP_REG, data, 2) != 0) {
        fprintf(stderr, "Failed to read temperature data\n");
        return -1000.0; // Indicate error
    }

    raw_temp = (data[0] << 8) | data[1];
    raw_temp = raw_temp >> 4; // Right-shift by 4 bits

    temperature = raw_temp * 0.0625; // Convert to Celsius

    return temperature;
}

// Control LED based on temperature
void control_led(float temperature) {
    if (temperature > TEMP_THRESHOLD_HIGH) {
        gpiod_line_set_value(gpio_line, 1); // Turn LED on
    } else if (temperature < TEMP_THRESHOLD_LOW) {
        gpiod_line_set_value(gpio_line, 0); // Turn LED off
    }
}

// Log temperature to stdout
void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s Temperature: %.2f °C\n", timestamp, temperature);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Setup GPIO line
int setup_gpio(const char *chipname, int pin) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name(chipname);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", chipname, strerror(errno));
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", pin, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line, "temperature_control", 0); // Initial value 0
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", pin, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    gpio_line = line;
    return 0;
}

// Cleanup GPIO line
int cleanup_gpio(void) {
    if (gpio_line) {
        gpiod_line_release(gpio_line);
        gpio_line = NULL;
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
    }
    return 0;
}

int main() {
    float temperature;
    int retry_count = 0;
    int max_i2c_retries = 3;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", STTS2004_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Setup GPIO
    if (setup_gpio(GPIO_CHIP, GPIO_PIN) != 0) {
        fprintf(stderr, "Failed to setup GPIO\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        retry_count = 0;
        temperature = read_temperature(i2c_fd);

        if (temperature < -999.0) {
            fprintf(stderr, "Error reading temperature, retrying I2C setup...\n");
            close(i2c_fd);
            sleep(1);
            i2c_fd = open(I2C_DEVICE, O_RDWR);
            if (i2c_fd < 0) {
                fprintf(stderr, "Error re-opening I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
                terminate = 1; // Exit if re-opening fails
                continue;
            }
            if (ioctl(i2c_fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
                fprintf(stderr, "Error re-setting I2C slave address 0x%02X: %s\n", STTS2004_ADDR, strerror(errno));
                terminate = 1; // Exit if re-setting fails
                continue;
            }
            if (setup_gpio(GPIO_CHIP, GPIO_PIN) != 0) {
                fprintf(stderr, "Failed to re-setup GPIO\n");
                terminate = 1; // Exit if re-setup fails
                continue;
            }
            continue; // Retry I2C setup
        }

        if (temperature > -999.0) {
            log_temperature(temperature);
            control_led(temperature);
        }

        retry_count++;
        if (retry_count >= max_i2c_retries) {
            fprintf(stderr, "Max I2C retries reached, exiting...\n");
            terminate = 1;
        }

        sleep(LOG_INTERVAL_SEC);
    }

    // Cleanup
    cleanup_gpio();
    close(i2c_fd);

    return 0;
}

