        }

        retry_count++;
        if (retry_count >= max_i2c_retries) {
            fprintf(stderr, "Max I2C retries reached, exiting...\n");
            terminate = 1;
        }

        sleep(LOG_INTERVAL_SEC);
    }

    // Cleanup
    cleanup_gpio();
    close(i2c_fd);

    return 0;
}

