            // Validate CRC
            if (validate_crc(data, DATA_LENGTH - 1, data[2]) &&
                validate_crc(data + 3, DATA_LENGTH - 4, data[5])) {

                // Convert data
                float pressure = convert_pressure(raw_pressure, scale_factor);
