#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define ISO8601_FORMAT "%Y-%m-%dT%H:%M:%SZ"

int i2c_handle;

// Function to handle signals (Ctrl+C, termination)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read temperature and humidity from the Si7021 sensor
int read_si7021(int i2c_handle, float *temperature, float *humidity) {
    unsigned char buf[2];
    int result;
    unsigned short raw_humidity, raw_temperature;

    // Measure Relative Humidity, No Master Hold (0xF5)
    result = i2cWriteByte(i2c_handle, 0xF5);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    gpioDelay(20); // Wait at least 20 ms

    result = i2cReadDevice(i2c_handle, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }
    raw_humidity = (buf[0] << 8) | buf[1];

    // Measure Temperature, No Master Hold (0xF3)
    result = i2cWriteByte(i2c_handle, 0xF3);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    gpioDelay(20); // Wait at least 20 ms

    result = i2cReadDevice(i2c_handle, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }
    raw_temperature = (buf[0] << 8) | buf[1];

    // Convert raw values to temperature and humidity
    *temperature = 175.72 * raw_temperature / 65536.0 - 46.85;
    *humidity = 125.0 * raw_humidity / 65536.0 - 6.0;

    // Clamp humidity to 0-100%
    if (*humidity < 0.0) *humidity = 0.0;
    if (*humidity > 100.0) *humidity = 100.0;

    return 0;
}

// Function to log data to a file
void log_data(const char *timestamp, float temperature, float humidity) {
    FILE *fp = fopen("environment.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
}

// Function to get the current timestamp in ISO 8601 format
void get_iso8601_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    strftime(timestamp, 21, ISO8601_FORMAT, timeinfo);
}

// Function to validate the sensor's presence by reading the electronic ID
int validate_sensor(int i2c_handle) {
    unsigned char buf[2];
    int result;

    result = i2cReadByte(i2c_handle, 0x00); // Read the first byte of the ID
    if (result != 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", result);
        return -1;
    }
    buf[0] = (unsigned char)result;

    result = i2cReadByte(i2c_handle, 0x01); // Read the second byte of the ID
    if (result != 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", result);
        return -1;
    }
    buf[1] = (unsigned char)result;

    if (buf[0] == 0x28 && buf[1] == 0x00) {
        printf("Sensor ID: 0x2800\n");
        return 0; // Sensor found
    } else {
        fprintf(stderr, "Error: Invalid sensor ID: 0x%02X%02X\n", buf[0], buf[1]);
        return -1; // Sensor not found
    }
}

int main() {
    float temperature, humidity;
    char timestamp[21];
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Validate sensor presence
    if (validate_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Error: Sensor not found!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read temperature and humidity
        if (read_si7021(i2c_handle, &temperature, &humidity) == 0) {
            // Get timestamp
            get_iso8601_timestamp(timestamp);

            // Log data
            log_data(timestamp, temperature, humidity);
            printf("%s,%.2f,%.2f\n", timestamp, temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor data!\n");
        }

        // Wait 60 seconds
        sleep(60);
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

