#define MEASUREMENT_REG 0x00
#define I2C_BUS 1

int i2c_handle;

// Function to handle signals (Ctrl+C, termination)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to initialize the HDC1080 sensor
int hdc1080_init(int i2c_handle) {
    // Configure for 14-bit temperature and humidity
    if (i2cWriteByteData(i2c_handle, CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Error writing to config register.\n");
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity from the HDC1080
int hdc1080_read(int i2c_handle, float *temperature, float *humidity) {
    unsigned char data[4];
    int raw_temp, raw_humidity;

    // Trigger measurement
    if (i2cWriteByte(i2c_handle, MEASUREMENT_REG) < 0) {
        fprintf(stderr, "Error triggering measurement.\n");
        return -1;
    }

    // Wait for conversion (at least 20 ms)
    gpioDelay(20000); // 20 ms

    // Read 4 bytes of data
    if (i2cReadI2CBlockData(i2c_handle, MEASUREMENT_REG, (char *)data, 4) != 4) {
        fprintf(stderr, "Error reading data from sensor.\n");
        return -1;
