#define I2C_BUS 1
#define STS40_ADDR 0x44
#define MEASURE_CMD 0x2C
#define MEASURE_ARG 0xE0
#define CRC_POLYNOMIAL 0x31
#define LOG_FILE "temperature_log.txt"

int i2c_fd = -1;
FILE *log_fp = NULL;

// Function to calculate CRC8 checksum
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature from STS40 sensor
float read_temperature() {
    unsigned char cmd[2] = {MEASURE_CMD, MEASURE_ARG};
    unsigned char data[3];
    int result;

    result = i2cWriteDevice(i2c_fd, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1000.0; // Indicate error
    }

    gpioDelay(10); // Wait for conversion

    result = i2cReadDevice(i2c_fd, data, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1000.0; // Indicate error
    }

    // CRC validation
    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "CRC validation failed!\n");
        return -1000.0; // Indicate error
    }

    // Convert raw data to Celsius
    unsigned int raw = (data[0] << 8) | data[1];
    float temperature = -45.0 + 175.0 * raw / 65535.0;
    return temperature;
}

// Function to log temperature to file
void log_temperature(float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(log_fp, "%s, %.2f\n", timestamp, temperature);
    fflush(log_fp); // Ensure data is written to disk immediately
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        i2cClose(i2c_fd);
    }
    if (log_fp != NULL) {
        fclose(log_fp);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = i2cOpen(I2C_BUS, STS40_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for valid temperature reading
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping logging.\n");
        }
        sleep(5);
    }

    return 0;
}

