#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define CONTINUOUS_MEASUREMENT_COMMAND 0x3615
#define SAMPLE_INTERVAL_SEC 1
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
uint8_t crc8(const uint8_t *data, int len);
float convert_pressure(int16_t raw_pressure, int16_t raw_scale_factor);
float convert_temperature(int16_t raw_temperature, int16_t raw_scale_factor);
int log_data(float pressure, float temperature);
void signal_handler(int signal);

// Structure for sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("hvac_pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        uint8_t data[9];
        int16_t raw_pressure, raw_temperature, raw_scale_factor;
        float pressure, temperature;

        // Send continuous measurement command
        if (send_command(i2c_handle, CONTINUOUS_MEASUREMENT_COMMAND) != 0) {
            fprintf(stderr, "Failed to send continuous measurement command\n");
            log_data(-999.0, -999.0); // Log error
        } else {
            // Wait for at least 50 ms
            gpioDelay(50000); // 50 ms

            // Read data from sensor
            if (read_data(i2c_handle, data, 9) != 0) {
                fprintf(stderr, "Failed to read data from sensor\n");
                log_data(-999.0, -999.0); // Log error
            } else {
                // Validate CRC for pressure
                if (crc8(data, 2) != data[2]) {
                    fprintf(stderr, "CRC validation failed for pressure\n");
                    log_data(-999.0, -999.0); // Log error
                } else {
                    // Extract raw pressure and scale factor
                    raw_pressure = (data[0] << 8) | data[1];
                    raw_scale_factor = (data[3] << 8) | data[4];

                    // Validate CRC for temperature
                    if (crc8(data + 5, 2) != data[7]) {
                        fprintf(stderr, "CRC validation failed for temperature\n");
                        log_data(-999.0, -999.0); // Log error
                    } else {
                        // Extract raw temperature
                        raw_temperature = (data[5] << 8) | data[6];

                        // Convert raw data to physical units
                        pressure = convert_pressure(raw_pressure, raw_scale_factor);
                        temperature = convert_temperature(raw_temperature, raw_scale_factor);

                        // Log data
                        if (log_data(pressure, temperature) != 0) {
                            fprintf(stderr, "Failed to log data\n");
                        }
                    }
                }
            }
        }

        // Wait for 1 second
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Send command to sensor
int send_command(int handle, uint16_t command) {
    uint8_t buffer[2];
    buffer[0] = (command >> 8) & 0xFF;
    buffer[1] = command & 0xFF;

    if (i2cWriteDevice(handle, (char *)buffer, 2) != 2) {
        fprintf(stderr, "Failed to write command to I2C device\n");
        return 1;
    }
    return 0;
}

// Read data from sensor
int read_data(int handle, uint8_t *data, int count) {
    if (i2cReadDevice(handle, (char *)data, count) != count) {
        fprintf(stderr, "Failed to read data from I2C device\n");
        return 1;
    }
    return 0;
}

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Convert raw pressure to Pascals
float convert_pressure(int16_t raw_pressure, int16_t raw_scale_factor) {
    return (float)raw_pressure / (float)raw_scale_factor;
}

// Convert raw temperature to Celsius
float convert_temperature(int16_t raw_temperature, int16_t raw_scale_factor) {
    return (float)raw_temperature / 200.0;
}

// Log data to file
int log_data(float pressure, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed, exiting...\n");
        terminate = 1;
    }
}

