#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Configuration
#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define CSV_DIR "/var/log/scd40_data/"
#define ERROR_LOG "/var/log/scd40_error.log"
#define BUFFER_CAPACITY 100
#define LOGGING_INTERVAL 60 // seconds

// SCD40 Commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86
#define CMD_READ_MEASUREMENT 0xE000

// Data Structure
typedef struct {
    time_t timestamp;
    uint16_t co2;
    float temperature;
    float humidity;
} SensorData;

// Circular Buffer
typedef struct {
    SensorData data[BUFFER_CAPACITY];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} CircularBuffer;

// Global Variables
static volatile sig_atomic_t running = 1;
static int i2c_handle;
static CircularBuffer buffer;

// Function Prototypes
int init_i2c();
int start_periodic_measurement();
int stop_periodic_measurement();
int read_measurement(uint16_t *co2, float *temperature, float *humidity);
void validate_crc(uint8_t data[], uint8_t crc, uint8_t polynomial, uint8_t initial_value);
void convert_data(uint16_t raw_co2, uint16_t raw_temp, uint16_t raw_humidity, float *co2_ppm, float *temperature, float *humidity);
void add_to_buffer(CircularBuffer *buffer, SensorData data);
int get_from_buffer(CircularBuffer *buffer, int index, SensorData *data);
void *logging_thread_func(void *arg);
void signal_handler(int signal);
void log_error(const char *message);

// CRC-8 Implementation
void validate_crc(uint8_t data[], uint8_t crc, uint8_t polynomial, uint8_t initial_value) {
    uint8_t crc_calc = initial_value;
    for (int i = 0; i < 2; i++) {
        crc_calc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calc & 0x80) {
                crc_calc = (crc_calc << 1) ^ polynomial;
            } else {
                crc_calc <<= 1;
            }
        }
    }
    if (crc_calc != crc) {
        log_error("CRC check failed");
    }
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Start Periodic Measurement
int start_periodic_measurement() {
    char buf[2];
    buf[0] = (CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_START_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_error("Failed to send start periodic measurement command");
        return -1;
    }
    return 0;
}

// Stop Periodic Measurement
int stop_periodic_measurement() {
    char buf[2];
    buf[0] = (CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_STOP_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_error("Failed to send stop periodic measurement command");
        return -1;
    }
    return 0;
}

// Read Measurement
int read_measurement(uint16_t *co2, float *temperature, float *humidity) {
    char buf[2];
    buf[0] = (CMD_READ_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_READ_MEASUREMENT & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        log_error("Failed to send read measurement command");
        return -1;
    }

    gpioDelay(1); // Small delay before reading

    char data[9];
    int result = i2cReadDevice(i2c_handle, data, 9);
    if (result != 9) {
        log_error("Failed to read measurement data");
        return -1;
    }

    // Validate CRC for each byte
    for (int i = 0; i < 9; i++) {
        uint8_t crc_data[1] = {data[i]};
        validate_crc(crc_data, data[i], 0x31, 0xFF);
    }

    // Extract data
    *co2 = (data[0] << 8) | data[1];
    uint16_t raw_temp = (data[3] << 8) | data[4];
    uint16_t raw_humidity = (data[6] << 8) | data[7];

    // Convert data
    convert_data(raw_co2, raw_temp, raw_humidity, co2, temperature, humidity);

    return 0;
}

// Convert Raw Data to Physical Units
void convert_data(uint16_t raw_co2, uint16_t raw_temp, uint16_t raw_humidity, float *co2_ppm, float *temperature, float *humidity) {
    *co2_ppm = (float)raw_co2;
    *temperature = -45 + 175 * (float)raw_temp / 65535.0;
    *humidity = 100 * (float)raw_humidity / 65535.0;
}

// Add Data to Circular Buffer
void add_to_buffer(CircularBuffer *buffer, SensorData data) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_CAPACITY;
    if (buffer->count < BUFFER_CAPACITY) {
        buffer->count++;
    } else {
        buffer->tail = (buffer->tail + 1) % BUFFER_CAPACITY;
    }
    pthread_mutex_unlock(&buffer->mutex);
}

// Get Data from Circular Buffer
int get_from_buffer(CircularBuffer *buffer, int index, SensorData *data) {
    pthread_mutex_lock(&buffer->mutex);
    if (index < 0 || index >= buffer->count) {
        pthread_mutex_unlock(&buffer->mutex);
        return -1; // Invalid index
    }
    int actual_index = (buffer->tail + index) % BUFFER_CAPACITY;
    *data = buffer->data[actual_index];
    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

// Logging Thread Function
void *logging_thread_func(void *arg) {
    while (running) {
        pthread_mutex_lock(&buffer.mutex);
        int num_readings = buffer.count;
        pthread_mutex_unlock(&buffer.mutex);

        if (num_readings > 0) {
            FILE *fp = fopen(CSV_DIR "scd40_data.csv", "a");
            if (fp == NULL) {
                log_error("Failed to open CSV file for writing");
            } else {
                // Write header if the file is newly created
                fseek(fp, 0, SEEK_END);
                long fsize = ftell(fp);
                if (fsize == 0) {
                    fprintf(fp, "timestamp,CO2 (ppm),temperature (C),humidity (%%RH)\n");
                }

                for (int i = 0; i < num_readings; i++) {
                    SensorData data;
                    if (get_from_buffer(&buffer, i, &data) == 0) {
                        char timestamp_str[30];
                        struct tm *tm_info = localtime(&data.timestamp);
                        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", tm_info);
                        fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp_str, data.co2, data.temperature, data.humidity);
                    } else {
                        log_error("Failed to read data from buffer in logging thread");
                    }
                }
                fclose(fp);
            }
        }
        sleep(LOGGING_INTERVAL);
    }
    return NULL;
}

// Signal Handler
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        running = 0;
    }
}

// Log Error
void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG, "a");
    if (fp == NULL) {
        perror("Failed to open error log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

int main() {
    // Initialize
    if (init_i2c() != 0) {
        return 1;
    }

    // Start periodic measurement
    if (start_periodic_measurement() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    pthread_mutex_init(&buffer.mutex, NULL);
    buffer.head = 0;
    buffer.tail = 0;
    buffer.count = 0;

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Create logging thread
    pthread_t logging_thread;
    if (pthread_create(&logging_thread, NULL, logging_thread_func, NULL) != 0) {
        log_error("Failed to create logging thread");
        stop_periodic_measurement();
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        uint16_t co2;
        float temperature, humidity;

        if (read_measurement(&co2, &temperature, &humidity) == 0) {
            time_t now = time(NULL);
            SensorData data;
            data.timestamp = now;
            data.co2 = co2;
            data.temperature = temperature;
            data.humidity = humidity;
            add_to_buffer(&buffer, data);
        } else {
            log_error("Failed to read sensor data");
        }

        gpioDelay(5000); // 5 seconds
    }

    // Cleanup
    pthread_join(logging_thread, NULL);
    stop_periodic_measurement();
    i2cClose(i2c_handle);
    gpioTerminate();

    pthread_mutex_destroy(&buffer.mutex);

    return 0;
}

