    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send measurement command
int send_measurement_command(int handle, uint16_t command) {
    uint8_t command_bytes[2];
    command_bytes[0] = (command >> 8) & 0xFF;
    command_bytes[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, (char *)command_bytes, 2);
    if (result != 0) {
        fprintf(stderr, "Error sending measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    return 0;
