// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define MEASUREMENT_COMMAND 0x362F
#define CRC_POLYNOMIAL 0x31
#define LOG_FILE "sdp810_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float pressure_Pa;
    float temperature_C;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_measurement_command(int handle, uint16_t command);
int read_sensor_data(int handle, uint8_t *data, int count);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
float convert_pressure(int16_t raw_pressure, float scale_factor);
float convert_temperature(int16_t raw_temperature, float scale_factor);
int log_data(FILE *fp, float pressure, float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send measurement command
int send_measurement_command(int handle, uint16_t command) {
    uint8_t command_bytes[2];
    command_bytes[0] = (command >> 8) & 0xFF;
    command_bytes[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, (char *)command_bytes, 2);
    if (result != 0) {
        fprintf(stderr, "Error sending measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate CRC-8
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc = calculate_crc(data, len - 1);
    return (crc == data[len - 1]);
}

