// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICP10110_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Verify sensor ID
int verify_sensor_id() {
    char buf[1];
    if (i2cReadI2CBlockData(i2c_handle, 0x08, buf, 1) != 1) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return 1;
    }
    if (buf[0] != 0x08) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X\n", buf[0]);
        return 1;
    }
    return 0;
}

// Read calibration coefficients
int read_calibration_coefficients() {
    char buf[8];
    if (i2cReadI2CBlockData(i2c_handle, 0x05, buf, 8) != 8) {
        fprintf(stderr, "Failed to read calibration coefficients\n");
        return 1;
    }

    c0 = (double)((int16_t)buf[0] | ((int16_t)buf[1] << 8));
    c1 = (double)((int16_t)buf[2] | ((int16_t)buf[3] << 8));
    c00 = (double)((int16_t)buf[4] | ((int16_t)buf[5] << 8));
    c10 = (double)((int16_t)buf[6] | ((int16_t)buf[7] << 8));
    c01 = (double)((int16_t)buf[4] | ((int16_t)buf[5] << 8));
    c11 = (double)((int16_t)buf[6] | ((int16_t)buf[7] << 8));
    c20 = (double)((int16_t)buf[4] | ((int16_t)buf[5] << 8));

    return 0;
}

// Trigger measurement
int trigger_measurement() {
    char cmd[1];
    cmd[0] = MEASURE_CMD;
    if (i2cWriteI2CBlockData(i2c_handle, 0x00, cmd, 1) != 1) {
        fprintf(stderr, "Failed to trigger measurement\n");
        return 1;
    }
    return 0;
}

// Read raw pressure and temperature data
int read_raw_data(int32_t *pressure, int32_t *temperature) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 6) != 6) {
        fprintf(stderr, "Failed to read raw data\n");
        return 1;
    }

    *pressure = (int32_t)((((uint32_t)buf[0]) << 16) | (((uint32_t)buf[1]) << 8) | (uint32_t)buf[2]);
    *temperature = (int32_t)((((uint32_t)buf[3]) << 16) | (((uint32_t)buf[4]) << 8) | (uint32_t)buf[5]);

    return 0;
}

// Convert raw pressure to hPa
double convert_pressure(int32_t raw_pressure) {
    double pressure;
    pressure = c0 + raw_pressure * (c1 / (1 << 21));
    return pressure;
}

// Convert raw temperature to Celsius
double convert_temperature(int32_t raw_temperature) {
    double temperature;
    temperature = c00 + raw_temperature * (c10 / (1 << 21)) + raw_temperature * (raw_temperature * (c20 / (1 << 42)));
    return temperature;
}

// Log data to file
int log_data(double pressure, double temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", &tm);

    fprintf(log_file, "%s, %.2f hPa, %.2f C\n", timestamp, pressure, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    printf("%s, %.2f hPa, %.2f C\n", timestamp, pressure, temperature);
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed, exiting...\n");
        terminate = 1;
    }
}

