#include <errno.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ICP10125_OTP_ADDR 0x66
#define ICP10125_MEAS_CMD 0x4011
#define LED_GPIO_PIN 17
#define PRESSURE_THRESHOLD 95000.0 // Pa
#define WARNING_LED_FREQ 5.0      // Hz
#define NORMAL_LED_FREQ 1.0       // Hz
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Calibration coefficients
static int16_t c0, c1, c2, c3;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg_addr, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg_addr, uint8_t data);
int read_calibration_coefficients(int fd);
int trigger_measurement(int fd);
int read_sensor_data(int fd, uint16_t *pressure, uint16_t *temperature);
double calculate_pressure(uint16_t raw_pressure);
double calculate_temperature(uint16_t raw_temperature);
void control_led(double pressure);
void signal_handler(int sig);

// I2C read function with retry
int i2c_read_bytes(int fd, uint8_t reg_addr, uint8_t *data, int len) {
    int retries = I2C_RETRY_COUNT;
    int result;

    while (retries > 0) {
        result = read(fd, data, len);
        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X, len %d): %s\n", reg_addr, len, strerror(errno));
            retries--;
            usleep(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }
    fprintf(stderr, "I2C read failed after %d retries (reg 0x%02X, len %d)\n", I2C_RETRY_COUNT, reg_addr, len);
    return -1; // Failure
}

// I2C write function
int i2c_write_byte(int fd, uint8_t reg_addr, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg_addr;
    buf[1] = data;
