#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x5A
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 30.0
#define TEMP_THRESHOLD_LOW 28.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_temperature(int i2c_handle, int register_address, float *temperature);
float convert_to_celsius(int raw_temperature);
void log_temperature(float ambient_temp, float object_temp);
void control_fan(float object_temp);
void signal_handler(int signal);

// Function to read temperature from the sensor
int read_temperature(int i2c_handle, int register_address, float *temperature) {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cReadI2CBlockData(i2c_handle, register_address, buf, 2);
        if (result == 2) {
            // Combine the two bytes into a 16-bit value
            int raw_temperature = (buf[0] << 8) | buf[1];
            *temperature = convert_to_celsius(raw_temperature);
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "I2C read failed after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Function to convert raw temperature to Celsius
float convert_to_celsius(int raw_temperature) {
    return raw_temperature * 0.02 - 273.15;
}

// Function to log temperature data to a file
void log_temperature(float ambient_temp, float object_temp) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    FILE *fp = fopen("temperature_log.txt", "a");
    if (fp != NULL) {
        fprintf(fp, "%s, Ambient: %.2f °C, Object: %.2f °C\n", timestamp, ambient_temp, object_temp);
        fclose(fp);
    } else {
        fprintf(stderr, "Error opening temperature_log.txt for writing.\n");
    }
}

// Function to control the cooling fan
void control_fan(float object_temp) {
    static int fan_on = 0; // Track fan state

    if (object_temp > TEMP_THRESHOLD_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Fan turned ON\n");
    } else if (object_temp < TEMP_THRESHOLD_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan turned OFF\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 18 as output for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off initially

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float ambient_temp, object_temp;
    int read_result;

    // Main loop
    while (!terminate) {
        read_result = read_temperature(i2c_handle, 0x06, &ambient_temp);
        if (read_result == 0) {
            read_result = read_temperature(i2c_handle, 0x07, &object_temp);
            if (read_result == 0) {
                log_temperature(ambient_temp, object_temp);
                control_fan(object_temp);
            } else {
                fprintf(stderr, "Failed to read object temperature.\n");
            }
        } else {
            fprintf(stderr, "Failed to read ambient temperature.\n");
        }

        gpioDelay(2000000); // Wait 2 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    gpioTerminate();

    return 0;
}

