#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define PORT 8080
#define MAX_RETRIES 3

int i2c_handle;
int server_fd;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (server_fd >= 0) {
        close(server_fd);
    }
    gpioTerminate();
    exit(0);
}

// Function to read temperature and humidity from SHT40 sensor
int read_sht40(float *temperature, float *humidity) {
    unsigned char buf[6];
    int result;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        // Send measurement command
        result = i2cWriteByteData(i2c_handle, 0, MEASURE_CMD);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C: %d\n", result);
            retries++;
            gpioDelay(10000); // Wait 10ms before retry
            continue;
        }

        gpioDelay(10000); // Wait for measurement (at least 10ms)

        // Read 6 bytes of data
        result = i2cReadI2CBlockData(i2c_handle, 0, (char *)buf, 6);
        if (result != 6) {
            fprintf(stderr, "Error reading from I2C: %d\n", result);
            retries++;
            gpioDelay(10000); // Wait 10ms before retry
            continue;
        }

        // Convert raw data to temperature and humidity
        unsigned int raw_temperature = (buf[0] << 8) | buf[1];
        unsigned int raw_humidity = (buf[3] << 8) | buf[4];

        *temperature = -45 + 175 * (raw_temperature / 65535.0);
        *humidity = -6 + 125 * (raw_humidity / 65535.0);
        if (*humidity < 0) *humidity = 0;
        if (*humidity > 100) *humidity = 100;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read SHT40 after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to handle HTTP requests
void handle_request(int client_socket) {
    float temperature, humidity;
    char response[256];

    if (read_sht40(&temperature, &humidity) == 0) {
        snprintf(response, sizeof(response), "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\n\r\n<!DOCTYPE html><html><head><title>SHT40 Data</title></head><body><h1>Temperature: %.2f °C, Humidity: %.2f %%</h1></body></html>", temperature, humidity);
        send(client_socket, response, strlen(response), 0);
    } else {
        const char *error_response = "HTTP/1.1 500 Internal Server Error\r\nContent-Type: text/html\r\n\r\n<!DOCTYPE html><html><head><title>Error</title></head><body><h1>Error reading sensor data</h1></body></html>";
        send(client_socket, error_response, strlen(error_response), 0);
    }

    close(client_socket);
}

int main() {
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);
    int new_socket;
    char buffer[1024] = {0};

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        gpioTerminate();
        return 1;
    }

    // Set socket options to reuse address
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        gpioTerminate();
        return 1;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Bind socket to address
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d\n", PORT);

    // Main loop to accept connections
    while (1) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            continue; // Continue listening for new connections
        }

        handle_request(new_socket);
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle);
    close(server_fd);
    gpioTerminate();
    return 0;
}

