#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define TMP102_ADDR 0x48
#define TEMP_REG 0x00
#define CSV_FILE "temperature_log.csv"

int i2c_handle;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read temperature from TMP102
float read_temperature() {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -1000.0; // Indicate error with a very low temperature
    }

    // Combine the two bytes into a 16-bit value
    int16_t raw_temp = (buf[0] << 8) | buf[1];

    // Shift right by 4 bits to get the 12-bit temperature value
    raw_temp = raw_temp >> 4;

    // Convert to Celsius (0.0625 degrees Celsius per LSB)
    float temperature = raw_temp * 0.0625;

    return temperature;
}

// Function to log temperature to CSV file
void log_temperature(float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    FILE *fp;

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        return;
    }

    fprintf(fp, "%s,%.2f\n", timestamp, temperature);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, TMP102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        float temperature = read_temperature();

        if (temperature > -999.0) { // Check for valid temperature reading
            log_temperature(temperature);
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    return 0;
}

