#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// HDC2010 I2C address
#define HDC2010_ADDR 0x40

// HDC2010 register addresses
#define MEASUREMENT_CONFIG 0x0E
#define TEMPERATURE_MSB 0x00
#define TEMPERATURE_LSB 0x01
#define HUMIDITY_MSB 0x02
#define HUMIDITY_LSB 0x03

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig)
{
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Function to write a byte to an I2C register
int write_register(int handle, int reg, int val)
{
    int result = i2cWriteByteData(handle, reg, val);
    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C register
int read_register(int handle, int reg)
{
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Function to trigger a temperature and humidity measurement
int trigger_measurement(int handle)
{
    // Write 0x01 to the MEASUREMENT_CONFIG register
    if (write_register(handle, MEASUREMENT_CONFIG, 0x01) != 0) {
        return -1;
    }
    return 0;
}

// Function to read the temperature and humidity data
int read_data(int handle, float *temperature, float *humidity)
{
    int temp_msb, temp_lsb, hum_msb, hum_lsb;
    int retry_count = 0;
    int delay_ms = 1;

    // Poll the MEASUREMENT_CONFIG register until bit 0 clears
    while (read_register(handle, MEASUREMENT_CONFIG) & 0x01 && retry_count < 100) {
        gpioDelay(delay_ms * 1000); // Delay in microseconds
        delay_ms *= 2; // Exponential backoff
        if (delay_ms > 500) delay_ms = 500;
        retry_count++;
    }

    if (retry_count >= 100) {
        fprintf(stderr, "Timeout waiting for measurement to complete.\n");
        return -1;
    }

    // Read the temperature data
    temp_msb = read_register(handle, TEMPERATURE_MSB);
    temp_lsb = read_register(handle, TEMPERATURE_LSB);
    if (temp_msb < 0 || temp_lsb < 0) {
        return -1;
    }

    // Read the humidity data
    hum_msb = read_register(handle, HUMIDITY_MSB);
    hum_lsb = read_register(handle, HUMIDITY_LSB);
    if (hum_msb < 0 || hum_lsb < 0) {
        return -1;
    }

    // Combine the MSB and LSB values
    int temp_raw = (temp_msb << 8) | temp_lsb;
    int hum_raw = (hum_msb << 8) | hum_lsb;

    // Convert the raw values to temperature and humidity
    *temperature = (float)temp_raw / 65536.0 * 165.0 - 40.0;
    *humidity = (float)hum_raw / 65536.0 * 100.0;

    return 0;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus 1
    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature, humidity;

    // Main loop
    while (!terminate) {
        // Trigger a temperature and humidity measurement
        if (trigger_measurement(i2c_handle) != 0) {
            fprintf(stderr, "Error triggering measurement\n");
        } else {
            gpioDelay(10000); // Wait for measurement to complete (10ms)

            // Read the temperature and humidity data
            if (read_data(i2c_handle, &temperature, &humidity) == 0) {
                // Print the temperature and humidity values
                printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            } else {
                fprintf(stderr, "Error reading data\n");
            }
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

