#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define GPIO_RELAY 17
#define PROFILE_FILE "profile.txt"
#define LOG_FILE "reflow_log.csv"
#define SAMPLE_INTERVAL_MS 1000 // 1 Hz sampling

// PID Constants
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Global Variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_fp;

// Structure for PID controller
typedef struct {
    double kp;
    double ki;
    double kd;
    double integral;
    double previous_error;
} PIDController;

// Function Prototypes
double read_temperature();
int load_profile(const char *filename, double **profile, int *profile_size);
double calculate_pid(double setpoint, double actual_temperature, PIDController *pid);
void set_relay_duty_cycle(double duty_cycle);
void log_data(double temperature, double duty_cycle);
void signal_handler(int signal);
void cleanup();

// PID Controller Functions
void pid_init(PIDController *pid, double kp, double ki, double kd) {
    pid->kp = kp;
    pid->ki = ki;
    pid->kd = kd;
    pid->integral = 0.0;
    pid->previous_error = 0.0;
}

double pid_update(PIDController *pid, double setpoint, double actual_temperature) {
    double error = setpoint - actual_temperature;
    pid->integral += error;
    double derivative = error - pid->previous_error;
    double output = pid->kp * error + pid->ki * pid->integral + pid->kd * derivative;
    pid->previous_error = error;
    return output;
}

// Temperature Reading Function
double read_temperature() {
    unsigned char data[2];
    int result;
    int raw_temp;
    double temperature;

    result = spiRead(spi_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading SPI data: %d\n", result);
        return -1.0; // Indicate error
    }

    raw_temp = (data[0] << 8) | data[1];

    // Check for fault
    if (raw_temp & 0x0004) {
        fprintf(stderr, "Thermocouple fault detected!\n");
        return -2.0; // Indicate fault
    }

    // Extract temperature (bits 3-14)
    raw_temp >>= 3; // Shift right to remove status bits
    temperature = raw_temp * 0.25; // Each bit is 0.25 degrees C

    return temperature;
}

// Profile Loading Function
int load_profile(const char *filename, double **profile, int *profile_size) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening profile file");
        return -1;
    }

    char line[256];
    *profile_size = 0;
    while (fgets(line, sizeof(line), fp) != NULL) {
        double time, temp;
        if (sscanf(line, "%lf,%lf", &time, &temp) == 2) {
            (*profile_size)++;
            (*profile) = realloc(*profile, (*profile_size) * sizeof(double));
            if ((*profile) == NULL) {
                perror("Memory allocation error");
                fclose(fp);
                return -1;
            }
            (*profile)[*profile_size - 1] = temp;
        } else {
            fprintf(stderr, "Invalid line in profile file: %s", line);
        }
    }

    fclose(fp);
    return 0;
}

// PID Calculation Function
double calculate_pid(double setpoint, double actual_temperature, PIDController *pid) {
    return pid_update(pid, setpoint, actual_temperature);
}

// Relay Control Function
void set_relay_duty_cycle(double duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 1.0) duty_cycle = 1.0;

    int on_time_ms = (int)(duty_cycle * 500.0); // 50% duty cycle, 1 second period
    int off_time_ms = 500 - on_time_ms;

    gpioWrite(GPIO_RELAY, 1); // Turn relay on
    gpioDelay(on_time_ms * 1000); // Delay in microseconds
    gpioWrite(GPIO_RELAY, 0); // Turn relay off
    gpioDelay(off_time_ms * 1000);
}

// Logging Function
void log_data(double temperature, double duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_fp, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_fp); // Ensure data is written to file immediately
}

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, exiting...\n", signal);
    running = 0;
}

// Cleanup Function
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(GPIO_RELAY, 0); // Ensure relay is off
    gpioSetMode(GPIO_RELAY, PI_INPUT); // Set back to input
    gpioTerminate(); // Terminate pigpio

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

    if (log_fp != NULL) {
        fclose(log_fp);
    }
}

int main() {
    double *temperature_profile = NULL;
    int profile_size = 0;
    double target_temperature;
    double actual_temperature;
    double pid_output;
    double setpoint;
    double integral;
    double previous_error;
    int i;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioWrite(GPIO_RELAY, 0); // Initially off

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Load temperature profile
    if (load_profile(PROFILE_FILE, &temperature_profile, &profile_size) != 0) {
        fprintf(stderr, "Failed to load temperature profile\n");
        cleanup();
        return 1;
    }

    // Initialize PID controller
    PIDController pid;
    pid_init(&pid, KP, KI, KD);

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Write header if the file is new
    fseek(log_fp, 0, SEEK_END);
    long file_size = ftell(log_fp);
    if (file_size == 0) {
        fprintf(log_fp, "Timestamp,Temperature(C),DutyCycle\n");
    }
    rewind(log_fp);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Reflow controller started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read temperature
        actual_temperature = read_temperature();
        if (actual_temperature < 0.0) {
            fprintf(stderr, "Error reading temperature, using previous value or exiting.\n");
            // Consider adding a mechanism to handle sensor failure more gracefully
            // For now, just continue with the previous temperature or exit
            if (actual_temperature == -2.0) {
                running = 0;
                break;
            }
            //If the error is due to a previous read, use the previous value
            if (actual_temperature == -1.0) {
                actual_temperature = 0.0; // Use a default value
            }
        }

        // Calculate PID output
        setpoint = temperature_profile[i];
        pid_output = calculate_pid(setpoint, actual_temperature, &pid);

        // Set relay duty cycle
        set_relay_duty_cycle(pid_output);

        // Log data
        log_data(actual_temperature, pid_output);

        // Increment profile index
        i = (i + 1) % profile_size;

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

