#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>

// Configuration
#define I2C_BUS "/dev/i2c-1"
#define DS18B20_ADDR 0x50
#define RELAY_GPIO 17
#define PWM_GPIO 18
#define PWM_CHIP "gpiochip0"
#define PWM_CHIP_NUM 0
#define PWM_NUM 0
#define PWM_PERIOD 1000000 // 1ms period
#define LOG_FILE "greenhouse.log"

// Global variables (minimize usage)
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;
static struct gpiod_line *pwm_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// PID gains
static double Kp = 1.0;
static double Ki = 0.1;
static double Kd = 0.01;

// Function prototypes
int init_i2c();
int read_ds18b20(double *temperature);
double calculate_pid(double setpoint, double current_temperature, double *integral, double *previous_error);
int set_relay_state(int state);
int set_pwm_duty_cycle(int duty_cycle);
int log_data(double temperature, double setpoint, double pid_output, int duty_cycle);
void signal_handler(int sig);
int init_gpio();
int cleanup_gpio();

// Helper function to read a byte from I2C
int i2c_read_byte(int fd, unsigned char reg)
{
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }
    char buf[1];
    if (read(fd, buf, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return (int)buf[0];
}

// Helper function to write a byte to I2C
int i2c_write_byte(int fd, unsigned char reg, unsigned char value)
{
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    double setpoint;
    double integral = 0.0, previous_error = 0.0;
    double pid_output;
    int duty_cycle;
    int i;

    // Parse command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <setpoint_temperature>\n", argv[0]);
        return 1;
    }

    setpoint = atof(argv[1]);

    // Initialize signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        cleanup_gpio();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (!terminate) {
        double temperature;
        if (read_ds18b20(&temperature) == 0) {
            pid_output = calculate_pid(setpoint, temperature, &integral, &previous_error);

            // Limit PID output to 0-100% duty cycle
            if (pid_output < 0) pid_output = 0;
            if (pid_output > 100) pid_output = 100;

            duty_cycle = (int)pid_output;

            set_pwm_duty_cycle(duty_cycle);
            set_relay_state(duty_cycle > 0); // Enable relay if heater is on

            log_data(temperature, setpoint, pid_output, duty_cycle);
        } else {
            fprintf(stderr, "Failed to read temperature. Retrying in 5 seconds.\n");
            log_data(-999, setpoint, -999, -1); // Log error
        }

        sleep(5);
    }

    // Cleanup and exit
    cleanup_gpio();
    fclose(log_file);
    return 0;
}

int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, DS18B20_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int read_ds18b20(double *temperature) {
    unsigned char buf[2];
    int retries = 3;

    // Send skip ROM command
    if (i2c_write_byte(i2c_fd, 0x00, 0xCC) < 0) return -1;
    usleep(10000); // Wait for conversion

    // Read 6 bytes of data
    for (i = 0; i < retries; i++) {
        if (read(i2c_fd, buf, 2) == 2) {
            // Check CRC
            if ((buf[0] & 0x80) == 0) {
                unsigned char crc = buf[1];
                unsigned char data[15] = {buf[0], buf[1]};
                for (int j = 0; j < 15; j++) {
                    unsigned char crc_calc = 0;
                    for (int k = 0; k < 8; k++) {
                        if ((data[j] >> (7 - k)) & 0x01) {
                            crc_calc ^= 0x131; // CRC polynomial
                        }
                    }
                    if (crc != crc_calc) {
                        fprintf(stderr, "CRC error at byte %d\n", j);
                        return -1;
                    }
                }

                // Extract temperature
                int16_t raw_temp = (buf[0] << 8) | buf[1];
                raw_temp >>= 5; // Shift right by 5 bits
                *temperature = (double)raw_temp * 0.125;
                return 0;
            } else {
                fprintf(stderr, "Invalid skip ROM command response\n");
                return -1;
            }
        } else {
            fprintf(stderr, "I2C read failed, retrying (%d/%d)\n", i + 1, retries);
            usleep(10000); // Wait before retrying
        }
    }

    fprintf(stderr, "Failed to read DS18B20 after multiple retries\n");
    return -1;
}

double calculate_pid(double setpoint, double current_temperature, double *integral, double *previous_error) {
    double error = setpoint - current_temperature;
    *integral += error;
    double derivative = error - *previous_error;
    double output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;
    return output;
}

int set_relay_state(int state) {
    if (gpiod_line_set_value(relay_line, state) < 0) {
        perror("Failed to set relay state");
        return -1;
    }
    return 0;
}

int set_pwm_duty_cycle(int duty_cycle) {
    if (gpiod_line_set_value(pwm_line, duty_cycle > 0) < 0) {
        perror("Failed to set PWM duty cycle");
        return -1;
    }

    // Calculate period and on-time
    int period = PWM_PERIOD;
    int on_time = (int)((double)period * duty_cycle / 100.0);

    // Set PWM period
    if (gpiod_line_set_max_pulse_width(pwm_line, period) < 0) {
        perror("Failed to set PWM period");
        return -1;
    }

    // Set PWM on-time
    if (gpiod_line_set_value(pwm_line, 1) < 0) {
        perror("Failed to set PWM on-time");
        return -1;
    }
    usleep(on_time);
    if (gpiod_line_set_value(pwm_line, 0) < 0) {
        perror("Failed to set PWM off-time");
        return -1;
    }
    usleep(period - on_time);

    return 0;
}

int log_data(double temperature, double setpoint, double pid_output, int duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    if (log_file != NULL) {
        fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, %.2f, %.2f, %.2f, %d\n",
                t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec,
                temperature, setpoint, pid_output, duty_cycle);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }
}

void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int init_gpio() {
    chip = gpiod_chip_open_by_name(PWM_CHIP);
    if (!chip) {
