#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define AHT20_ADDR 0x38
#define INIT_CMD 0xBE
#define MEASURE_CMD 0xAC
#define GPIO_RELAY 17
#define HUMIDITY_THRESHOLD_HIGH 60.0
#define HUMIDITY_THRESHOLD_LOW 55.0
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10
#define POLL_INTERVAL_S 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int aht20_init(int i2c_handle);
int aht20_read_data(int i2c_handle, float *humidity);
void control_relay(int gpio_pin, int state);
void log_data(float humidity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// AHT20 Initialization function
int aht20_init(int i2c_handle) {
    char init_cmd[2] = {INIT_CMD, 0x08};
    int result;

    for (int i = 0; i < I2C_RETRY_COUNT; ++i) {
        result = i2cWriteDevice(i2c_handle, init_cmd, 2);
        if (result == 0) {
            return 0; // Success
        }
        gpioDelay(I2C_RETRY_DELAY_MS);
    }

    fprintf(stderr, "Error: AHT20 initialization failed after %d retries.\n", I2C_RETRY_COUNT);
    return -1; // Failure
}

// AHT20 Read Data function
int aht20_read_data(int i2c_handle, float *humidity) {
    char measure_cmd[2] = {MEASURE_CMD, 0x33};
    char data[6];
    int result;
    unsigned int raw_humidity;
    unsigned int raw_temperature;
    unsigned int status;

    for (int i = 0; i < I2C_RETRY_COUNT; ++i) {
        result = i2cWriteDevice(i2c_handle, measure_cmd, 2);
        if (result != 0) {
            gpioDelay(I2C_RETRY_DELAY_MS);
            continue;
        }

        gpioDelay(80); // Wait for measurement

        result = i2cReadDevice(i2c_handle, data, 6);
        if (result != 6) {
            gpioDelay(I2C_RETRY_DELAY_MS);
            continue;
        }

        status = (data[0] << 8) | data[1];
        if (status & 0x8000) {
            fprintf(stderr, "Error: AHT20 busy or calibration failed.\n");
            return -1; // Indicate failure
        }

        raw_humidity = ((unsigned int)data[2] << 12) | ((unsigned int)data[3] << 4) | ((unsigned int)data[4] >> 4);
        raw_temperature = ((unsigned int)data[2] >> 4) | ((unsigned int)data[3] << 4) | ((unsigned int)data[4] >> 8);

        *humidity = ((float)raw_humidity / 0x100000) * 100;

        return 0; // Success
    }

    fprintf(stderr, "Error: AHT20 read failed after %d retries.\n", I2C_RETRY_COUNT);
    return -1; // Indicate failure
}

// Control Relay function
void control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Log Data function
void log_data(float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s - Humidity: %.2f%%\n", timestamp, humidity);
}

int main() {
    float humidity;
    int relay_state = 0; // 0 = off, 1 = on

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus. %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize AHT20 sensor
    if (aht20_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: AHT20 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        if (aht20_read_data(i2c_handle, &humidity) == 0) {
            log_data(humidity);

            if (humidity > HUMIDITY_THRESHOLD_HIGH && relay_state == 0) {
                control_relay(GPIO_RELAY, 1);
                relay_state = 1;
            } else if (humidity < HUMIDITY_THRESHOLD_LOW && relay_state == 1) {
                control_relay(GPIO_RELAY, 0);
                relay_state = 0;
            }
        } else {
            fprintf(stderr, "Error: Failed to read humidity data.\n");
        }

        gpioDelay(POLL_INTERVAL_S * 1000); // Poll every 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_RELAY, 0); // Turn off relay on exit
    gpioTerminate();

    return 0;
}

