        syslog(LOG_ERR, "Failed to acquire bus access and/or talk to slave: %s", strerror(errno));
        return -1;
    }

    if (write(fd, &command, 1) != 1) {
        syslog(LOG_ERR, "Failed to write command to I2C device: %s", strerror(errno));
        return -1;
    }

    if (read(fd, data, len) != len) {
        syslog(LOG_ERR, "Failed to read data from I2C device: %s", strerror(errno));
        return -1;
    }

    return 0;
}

// I2C write function
int i2c_write_bytes(int fd, uint8_t device_address, uint8_t command, uint8_t *data, int len) {
    if (ioctl(fd, I2C_SLAVE, device_address) < 0) {
        syslog(LOG_ERR, "Failed to acquire bus access and/or talk to slave: %s", strerror(errno));
        return -1;
    }

    if (write(fd, data, len) != len) {
        syslog(LOG_ERR, "Failed to write data to I2C device: %s", strerror(errno));
        return -1;
    }

    if (write(fd, &command, 1) != 1) {
        syslog(LOG_ERR, "Failed to write command to I2C device: %s", strerror(errno));
        return -1;
    }

    return 0;
}

// Read humidity from HTU21D sensor
float read_humidity(int fd) {
    uint8_t data[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_read_bytes(fd, HTU21D_ADDR, TRIGGER_HUMID_MEASURE, data, 3) == 0) {
            uint16_t raw_humidity = (data[0] << 8) | data[1];
            float humidity = -6.0 + 125.0 * (raw_humidity / 65536.0);
            return humidity;
        } else {
            syslog(LOG_WARNING, "I2C read failed, retrying (%d/%d)", retries + 1, MAX_RETRIES);
            retries++;
            sleep(1); // Wait before retrying
        }
    }

    syslog(LOG_ERR, "Failed to read humidity after %d retries", MAX_RETRIES);
    return -1.0; // Indicate failure
}

