#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_CHIP_ID_REG 0xD0
#define BMP280_CALIB_START_REG 0x88
#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_DATA_START_REG 0xF7

// Pressure thresholds (hPa)
#define PRESSURE_HIGH_THRESHOLD 1020.0
#define PRESSURE_LOW_THRESHOLD 980.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

bmp280_calib_data calib;

// Function prototypes
int init_i2c();
int verify_chip_id();
int read_calibration_data(bmp280_calib_data *cal);
int read_raw_data(int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temperature);
double compensate_pressure(int32_t raw_pressure, double t_fine);
void log_pressure_breach(double pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, shutting down...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0); // I2C bus 1
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verify the BMP280 chip ID
int verify_chip_id() {
    char chip_id;
    if (i2cReadI2CBlockData(i2c_handle, BMP280_CHIP_ID_REG, &chip_id, 1) != 1) {
        fprintf(stderr, "Error reading chip ID\n");
        return -1;
    }

    if (chip_id != 0x58) {
        fprintf(stderr, "Incorrect chip ID: 0x%02X\n", chip_id);
        return -1;
    }

    return 0;
}

// Read calibration data from the BMP280
int read_calibration_data(bmp280_calib_data *cal) {
    char data[24];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_CALIB_START_REG, data, 24) != 24) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    cal->dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    cal->dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    cal->dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    cal->dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    cal->dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    cal->dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    cal->dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    cal->dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    cal->dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    cal->dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    cal->dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    cal->dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);

    return 0;
}

// Read raw temperature and pressure data from the BMP280
int read_raw_data(int32_t *temperature, int32_t *pressure) {
    char data[6];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_DATA_START_REG, data, 6) != 6) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);

    return 0;
}

// Compensate temperature using Bosch formula
double compensate_temperature(int32_t raw_temperature) {
    double var1, var2, T;
    double T_fine;

    var1 = (((double)raw_temperature / 16384.0) - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2);
    var2 = ((((double)raw_temperature / 131072.0) - ((double)calib.dig_T1) / 8192.0) * (((double)raw_temperature / 131072.0) - ((double)calib.dig_T1) / 8192.0)) * ((double)calib.dig_T3);
    T_fine = (var1 + var2);
    T = (var1 + var2) / 5120.0;
    return T;
}

// Compensate pressure using Bosch formula
double compensate_pressure(int32_t raw_pressure, double t_fine) {
    double var1, var2, p;

    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)calib.dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)calib.dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)calib.dig_P4) * 65536.0);
    var1 = (((double)calib.dig_P3) * var1 * var1 / 524288.0 + ((double)calib.dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)calib.dig_P1);

    if (var1 == 0)
    {
        return 0;
    }

    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)calib.dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)calib.dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)calib.dig_P7)) / 16.0;

    return p;
}

// Log pressure breach to file
void log_pressure_breach(double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s Pressure breach: %.2f hPa\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify chip ID
    if (verify_chip_id() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(&calib) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int32_t raw_temperature, raw_pressure;
        double temperature, pressure;
        int retries = 3;

        // Configure ctrl_meas register
        if (i2cWriteByteData(i2c_handle, BMP280_CTRL_MEAS_REG, 0x27) != 0) { // Forced mode, 1x oversampling
            fprintf(stderr, "Error writing to ctrl_meas register\n");
            retries--;
            if (retries <= 0) {
                fprintf(stderr, "Max retries reached, exiting\n");
                break;
            }
            i2cClose(i2c_handle);
            gpioDelay(100); // Wait before retrying
            i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C: %d\n", i2c_handle);
                break;
            }
            continue; // Retry the entire loop
        }

        gpioDelay(10); // Wait for measurement to complete

        // Read raw data
        retries = 3;
        while (retries > 0) {
            if (read_raw_data(&raw_temperature, &raw_pressure) == 0) {
                break; // Success, exit retry loop
            }
            fprintf(stderr, "Error reading raw data, retrying...\n");
            retries--;
            gpioDelay(10); // Wait before retrying
        }

        if (retries == 0) {
            fprintf(stderr, "Max retries reached for raw data, exiting\n");
            break;
        }

        // Compensate temperature and pressure
        temperature = compensate_temperature(raw_temperature);
        pressure = compensate_pressure(raw_pressure, temperature);

        // Log pressure breach if necessary
        if (pressure > PRESSURE_HIGH_THRESHOLD || pressure < PRESSURE_LOW_THRESHOLD) {
            log_pressure_breach(pressure);
        }

        gpioDelay(2000); // Sample every 2 seconds
    }

    // Close I2C and terminate pigpio
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

