#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <stdbool.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO 17
#define GPIO_CHIP "gpiochip4"
#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES 3
#define BACKOFF_DELAY_MS 10
#define CSV_FILE_NAME "sensor_data.csv"

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *pir_line = NULL;
static FILE *log_file = NULL;
static bool running = true;

// Function prototypes
int init_i2c(const char *bus);
int init_gpio(const char *chip, int line);
int read_tmp117(int fd, float *temperature);
int read_aht20(int fd, float *humidity, float *temperature);
int read_pir(struct gpiod_line *line);
int log_data(FILE *fp, float temperature, float humidity, int motion);
void signal_handler(int sig);
void cleanup();

// Helper function to write to I2C
int i2c_write_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    uint8_t buf[len + 1];
    buf[0] = reg;
    memcpy(buf + 1, data, len);
    if (write(fd, buf, len + 1) != (len + 1)) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// Helper function to read from I2C
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Initialize I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        perror("Failed to set TMP117 I2C address");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize GPIO line
int init_gpio(const char *chip, int line) {
    gpio_chip = gpiod_chip_open_by_name(chip);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "sensor_logger";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    pir_line = gpiod_chip_get_line(gpio_chip, line);
    if (!pir_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request(pir_line, &config, 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Read temperature from TMP117 sensor
int read_tmp117(int fd, float *temperature) {
    uint8_t data[2];
    int retries = 0;
    int delay_ms = BACKOFF_DELAY_MS;

    while (retries < MAX_RETRIES) {
        if (i2c_read_bytes(fd, 0x00, data, 2) == 0) {
            int16_t raw_temp = (data[1] << 8) | data[0];
            *temperature = raw_temp * 0.0078125;
            return 0;
        } else {
            fprintf(stderr, "I2C read failed, retrying (%d/%d)...\n", retries + 1, MAX_RETRIES);
            retries++;
            usleep(delay_ms * 1000); // Convert ms to microseconds
            delay_ms *= 2; // Exponential backoff
        }
    }

    fprintf(stderr, "Failed to read TMP117 after %d retries\n", MAX_RETRIES);
    return -1;
}

// Read humidity and temperature from AHT20 sensor
int read_aht20(int fd, float *humidity, float *temperature) {
    uint8_t init_cmd[3] = {0xBE, 0x08, 0x00};
    uint8_t measure_cmd[3] = {0xAC, 0x33, 0x00};
    uint8_t data[7];
    int retries = 0;
    int delay_ms = BACKOFF_DELAY_MS;

    // Initialize AHT20
    while (retries < MAX_RETRIES) {
        if (i2c_write_bytes(fd, 0x00, init_cmd, 3) == 0) {
            usleep(10000); // Wait for initialization (10ms)
            break;
        } else {
            fprintf(stderr, "AHT20 init failed, retrying (%d/%d)...\n", retries + 1, MAX_RETRIES);
            retries++;
            usleep(delay_ms * 1000); // Convert ms to microseconds
            delay_ms *= 2; // Exponential backoff
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to initialize AHT20 after %d retries\n", MAX_RETRIES);
        return -1;
    }

    // Measure humidity and temperature
    retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2c_write_bytes(fd, 0x00, measure_cmd, 3) == 0) {
            usleep(80000); // Wait for measurement (80ms)
            break;
        } else {
            fprintf(stderr, "AHT20 measure failed, retrying (%d/%d)...\n", retries + 1, MAX_RETRIES);
            retries++;
            usleep(delay_ms * 1000); // Convert ms to microseconds
            delay_ms *= 2; // Exponential backoff
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to measure AHT20 after %d retries\n", MAX_RETRIES);
        return -1;
    }

    // Read 7 bytes of data
    retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2c_read_bytes(fd, 0x00, data, 7) == 0) {
            break;
        } else {
            fprintf(stderr, "AHT20 read failed, retrying (%d/%d)...\n", retries + 1, MAX_RETRIES);
            retries++;
            usleep(delay_ms * 1000); // Convert ms to microseconds
            delay_ms *= 2; // Exponential backoff
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read AHT20 data after %d retries\n", MAX_RETRIES);
        return -1;
    }

    // Check busy bit
    if (data[0] & 0x80) {
        fprintf(stderr, "AHT20 not ready\n");
        return -1;
    }

    // Extract humidity and temperature
    uint32_t raw_humidity = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | (data[3] >> 4);
    uint32_t raw_temperature = ((uint32_t)data[3] & 0x0F) << 16 | ((uint32_t)data[4] << 8) | data[5];

    *humidity = ((float)raw_humidity / 0x100000) * 100;
    *temperature = ((float)raw_temperature / 0x100000) * 200 - 50;

    return 0;
}

// Read PIR sensor value
int read_pir(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Failed to read PIR value");
        return -1;
    }
    return value;
}

// Log data to CSV file
int log_data(FILE *fp, float temperature, float humidity, int motion) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion);
    fflush(fp); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    running = false;
    printf("Received signal %d, shutting down...\n", sig);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    if (pir_line) {
        gpiod_line_release(pir_line);
    }

    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    if (log_file) {
        fclose(log_file);
    }

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(GPIO_CHIP, PIR_GPIO) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(CSV_FILE_NAME, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),Humidity(%),MotionDetected\n");
    }

    // Main loop
    while (running) {
        float temperature_tmp117, humidity_aht20;
        int motion_detected = read_pir(pir_line);

        if (motion_detected < 0) {
            fprintf(stderr, "Failed to read PIR sensor\n");
        } else {
            if (read_tmp117(i2c_fd, &temperature_tmp117) == 0 &&
                read_aht20(i2c_fd, &humidity_aht20, &temperature_tmp117) == 0) {
                log_data(log_file, temperature_tmp117, humidity_aht20, motion_detected);
            } else {
                fprintf(stderr, "Failed to read sensor data\n");
            }
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Daily log file rotation
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char new_file_name[20];
    strftime(new_file_name, sizeof(new_file_name), "%Y-%m-%d.csv", timeinfo);

    if (now % (24 * 60 * 60) == 0) {
        printf("Midnight, closing current log file and creating new one.\n");
        fclose(log_file);
        log_file = fopen(new_file_name, "a");
        if (!log_file) {
            perror("Failed to open new log file");
            running = false; // Exit if new file creation fails
        } else {
            fprintf(log_file, "Timestamp,Temperature(C),Humidity(%),MotionDetected\n");
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

