        fprintf(stderr, "Failed to initialize AHT20 after %d retries\n", MAX_RETRIES);
        return -1;
    }

    // Measure humidity and temperature
    retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2c_write_bytes(fd, 0x00, measure_cmd, 3) == 0) {
            usleep(80000); // Wait for measurement (80ms)
            break;
        } else {
            fprintf(stderr, "AHT20 measure failed, retrying (%d/%d)...\n", retries + 1, MAX_RETRIES);
            retries++;
            usleep(delay_ms * 1000); // Convert ms to microseconds
            delay_ms *= 2; // Exponential backoff
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to measure AHT20 after %d retries\n", MAX_RETRIES);
        return -1;
    }

    // Read 7 bytes of data
    retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2c_read_bytes(fd, 0x00, data, 7) == 0) {
            break;
        } else {
            fprintf(stderr, "AHT20 read failed, retrying (%d/%d)...\n", retries + 1, MAX_RETRIES);
            retries++;
            usleep(delay_ms * 1000); // Convert ms to microseconds
            delay_ms *= 2; // Exponential backoff
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read AHT20 data after %d retries\n", MAX_RETRIES);
        return -1;
    }

    // Check busy bit
    if (data[0] & 0x80) {
        fprintf(stderr, "AHT20 not ready\n");
        return -1;
    }

    // Extract humidity and temperature
    uint32_t raw_humidity = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | (data[3] >> 4);
    uint32_t raw_temperature = ((uint32_t)data[3] & 0x0F) << 16 | ((uint32_t)data[4] << 8) | data[5];

    *humidity = ((float)raw_humidity / 0x100000) * 100;
    *temperature = ((float)raw_temperature / 0x100000) * 200 - 50;

    return 0;
}

// Read PIR sensor value
int read_pir(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Failed to read PIR value");
        return -1;
    }
    return value;
}

// Log data to CSV file
int log_data(FILE *fp, float temperature, float humidity, int motion) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion);
    fflush(fp); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    running = false;
    printf("Received signal %d, shutting down...\n", sig);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    if (pir_line) {
        gpiod_line_release(pir_line);
    }

    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    if (log_file) {
        fclose(log_file);
    }

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(GPIO_CHIP, PIR_GPIO) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(CSV_FILE_NAME, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),Humidity(%),MotionDetected\n");
    }

    // Main loop
    while (running) {
        float temperature_tmp117, humidity_aht20;
        int motion_detected = read_pir(pir_line);

        if (motion_detected < 0) {
            fprintf(stderr, "Failed to read PIR sensor\n");
        } else {
            if (read_tmp117(i2c_fd, &temperature_tmp117) == 0 &&
                read_aht20(i2c_fd, &humidity_aht20, &temperature_tmp117) == 0) {
                log_data(log_file, temperature_tmp117, humidity_aht20, motion_detected);
            } else {
                fprintf(stderr, "Failed to read sensor data\n");
            }
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Daily log file rotation
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char new_file_name[20];
    strftime(new_file_name, sizeof(new_file_name), "%Y-%m-%d.csv", timeinfo);

    if (now % (24 * 60 * 60) == 0) {
        printf("Midnight, closing current log file and creating new one.\n");
        fclose(log_file);
        log_file = fopen(new_file_name, "a");
        if (!log_file) {
            perror("Failed to open new log file");
            running = false; // Exit if new file creation fails
        } else {
            fprintf(log_file, "Timestamp,Temperature(C),Humidity(%),MotionDetected\n");
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

