#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal) {
    program_running = 0;
    printf("\nCaught SIGINT, exiting gracefully...\n");
}

// Signal handler for SIGTERM (e.g., from kill command)
void sigterm_handler(int signal) {
    program_running = 0;
    printf("\nCaught SIGTERM, exiting gracefully...\n");
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set rain sensor pin as input
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);

    // Set motor control pins as outputs
    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    // Ensure all pins are initially low
    gpioWrite(MOTOR_ENA_PIN, 0);
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);

    return 0;
}

// Function to read the rain sensor value
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

// Function to control the motor
void control_motor(int run_forward) {
    if (run_forward) {
        gpioWrite(MOTOR_ENA_PIN, 1); // Enable motor
        gpioWrite(MOTOR_IN1_PIN, 1); // Forward
        gpioWrite(MOTOR_IN2_PIN, 0); // Backward
        printf("Motor running forward\n");
    } else {
        gpioWrite(MOTOR_ENA_PIN, 0); // Disable motor
        gpioWrite(MOTOR_IN1_PIN, 0); // Stop
        gpioWrite(MOTOR_IN2_PIN, 0); // Stop
        printf("Motor stopped\n");
    }
}

// Function to log events with timestamp
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

int main() {
    // Register signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    log_event("Program started");

    // Main loop
    while (program_running) {
        int rain_detected = read_rain_sensor();

        if (rain_detected == 0) {
            log_event("Rain detected!");
            control_motor(1); // Run motor forward
            gpioDelay(5000); // Wait 5 seconds
            control_motor(0); // Stop motor
            log_event("Motor stopped after 5 seconds");
        } else {
            // No rain detected
            gpioDelay(2000); // Poll every 2 seconds
        }
    }

    // Cleanup GPIO
    log_event("Cleaning up GPIO...");
    gpioWrite(MOTOR_ENA_PIN, 0); // Disable motor
    gpioWrite(MOTOR_IN1_PIN, 0); // Stop
    gpioWrite(MOTOR_IN2_PIN, 0); // Stop
    gpioTerminate(); // Release GPIO resources

    log_event("Program finished");

    return 0;
}

