#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define SPI_MODE 0
#define FAN_GPIO 18
#define PWM_FREQUENCY 1000 // 1 kHz
#define BUFFER_SIZE 20

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure for temperature readings
typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} Reading;

// Circular buffer
Reading temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_max31855(int spi_handle, float *temperature);
int calculate_fan_duty_cycle(float temperature);
void add_reading(float temperature, int duty_cycle);
void print_buffer();
void signal_handler(int signal);

// Function to read temperature from MAX31855
int read_max31855(int spi_handle, float *temperature) {
    char tx_buf[4] = {0, 0, 0, 0}; // Dummy data for reading
    char rx_buf[4];
    int result;

    result = spiXfer(spi_handle, tx_buf, rx_buf, 4);
    if (result != 4) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1; // Indicate error
    }

    // Extract thermocouple temperature (bits 14-31, signed 14-bit)
    int32_t raw_temp = ((int32_t)rx_buf[0] << 24) | ((int32_t)rx_buf[1] << 16) | ((int32_t)rx_buf[2] << 8) | (int32_t)rx_buf[3];

    // Check for fault bits (bits 16-18)
    if (raw_temp & 0x00000004) {
        fprintf(stderr, "MAX31855 Fault: Open Circuit (OC)\n");
        return -1;
    }
    if (raw_temp & 0x00000008) {
        fprintf(stderr, "MAX31855 Fault: Short to GND (SCG)\n");
        return -1;
    }
    if (raw_temp & 0x00000010) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC (SCV)\n");
        return -1;
    }

    // Extract thermocouple temperature (bits 14-31, signed 14-bit)
    int16_t thermocouple_temp = (raw_temp >> 18) & 0x3FFF; // Mask to get 14 bits
    if (thermocouple_temp & 0x2000) {
        thermocouple_temp |= 0xC000; // Sign extend if negative
    }

    *temperature = thermocouple_temp * 0.25; // Each LSB is 0.25 degrees C

    return 0; // Indicate success
}

// Function to calculate fan duty cycle based on temperature
int calculate_fan_duty_cycle(float temperature) {
    int duty_cycle = 0;

    if (temperature < 25.0) {
        duty_cycle = 0;
    } else if (temperature >= 25.0 && temperature <= 40.0) {
        duty_cycle = (int)((temperature - 25.0) * 50.0);
    } else if (temperature >= 40.0 && temperature <= 60.0) {
        duty_cycle = 50 + (int)((temperature - 40.0) * 150.0);
    } else {
        duty_cycle = 255;
    }

    return duty_cycle;
}

// Function to add a reading to the circular buffer
void add_reading(float temperature, int duty_cycle) {
    temperature_buffer[buffer_index].timestamp = time(NULL);
    temperature_buffer[buffer_index].temperature = temperature;
    temperature_buffer[buffer_index].duty_cycle = duty_cycle;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
