#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_BUS 0
#define SPI_CHIP_SELECT 0
#define SPI_DEVICE_PATH "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define LOG_FILE "rtd_log.csv"
#define SLEEP_SECONDS 5

// MAX31865 Registers
#define MAX31865_RTD_MSB 0x01
#define MAX31865_RTD_LSB 0x02
#define MAX31865_FAULT_REG 0x00

// RTD Parameters (PT100)
#define RREF 430.0
#define A 3.9083e-3
#define B -5.775e-7
#define T0 0.0

// Global Variables
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_init(const char *device_path, int bus, int chip_select);
int spi_read_register(int fd, uint8_t reg, uint8_t *data, int len);
int spi_write_register(int fd, uint8_t reg, uint8_t data);
int max31865_init(int fd);
float read_rtd_temperature(int fd);
void log_data(float temperature);
void signal_handler(int sig);
void cleanup(void);

// SPI Initialization
int spi_init(const char *device_path, int bus, int chip_select) {
    int fd;
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS_PER_WORD;
    uint32_t speed = SPI_SPEED;

    fd = open(device_path, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_BITS_PER_WORD, &bits) == -1) {
        perror("Error getting SPI bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Read Register
int spi_read_register(int fd, uint8_t reg, uint8_t *data, int len) {
    uint8_t tx[1] = {reg};
    uint8_t rx[len];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error reading SPI register");
        return -1;
    }

    memcpy(data, rx, len);
    return 0;
}

// SPI Write Register
int spi_write_register(int fd, uint8_t reg, uint8_t data) {
    uint8_t tx[2] = {reg, data};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = NULL,
        .len = 2,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error writing SPI register");
        return -1;
    }

    return 0;
}

// MAX31865 Initialization
int max31865_init(int fd) {
    // Enable 3-wire RTD mode with bias voltage
    if (spi_write_register(fd, 0x00, 0x04) < 0) {
        fprintf(stderr, "Error enabling 3-wire RTD mode\n");
        return -1;
    }

    // Set fault detection to active low
    if (spi_write_register(fd, 0x01, 0x00) < 0) {
        fprintf(stderr, "Error setting fault detection\n");
        return -1;
    }

    return 0;
}

// Read RTD Temperature
float read_rtd_temperature(int fd) {
    uint8_t rtd_data[2];
    uint16_t rtd_raw;
    float rtd_resistance;
    float temperature;

    if (spi_read_register(fd, MAX31865_RTD_MSB, rtd_data, 2) < 0) {
        fprintf(stderr, "Error reading RTD data\n");
        return -1000.0; // Indicate error
    }

    rtd_raw = (rtd_data[0] << 8) | rtd_data[1];
    rtd_raw = rtd_raw >> 1; // Remove fault bit

    rtd_resistance = ((float)rtd_raw * RREF) / 32768.0;

    // Callendar-Van Dusen equation
    temperature = T0 + (A * rtd_resistance) + (B * rtd_resistance * rtd_resistance * rtd_resistance);

    return temperature;
}

// Log Data
void log_data(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal Handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup
void cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (cs_line != NULL) {
        gpiod_line_set_value(cs_line, 0);
        gpiod_line_release(cs_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
}

int main() {
    struct gpiod_line_request_config config;
    int ret;

    // Signal Handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // SPI Initialization
    spi_fd = spi_init(SPI_DEVICE_PATH, SPI_BUS, SPI_CHIP_SELECT);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // MAX31865 Initialization
    if (max31865_init(spi_fd) < 0) {
        fprintf(stderr, "MAX31865 initialization failed\n");
        close(spi_fd);
        return 1;
    }

    // Open Log File
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        return 1;
    }

    // Chip Select GPIO Initialization
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        close(spi_fd);
        fclose(log_file);
        return 1;
    }

    cs_line = gpiod_chip_get_line(chip, SPI_CHIP_SELECT);
    if (!cs_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        fclose(log_file);
        return 1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "rtd_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(cs_line, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        fclose(log_file);
        return 1;
    }

    // Main Loop
    while (!terminate) {
        float temperature = read_rtd_temperature(spi_fd);
        if (temperature > -999.0) { // Check for valid temperature reading
            log_data(temperature);
        } else {
            fprintf(stderr, "Error reading temperature, skipping log\n");
        }

        sleep(SLEEP_SECONDS);
    }

    // Cleanup
    cleanup();

    return 0;
}

