#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

// BME280 I2C address
#define BME280_I2C_ADDR 0x76

// BME280 register addresses
#define BME280_REG_TEMP_MSB 0xFA
#define BME280_REG_PRESSURE_MSB 0xF7
#define BME280_REG_HUMIDITY_MSB 0xFD
#define BME280_REG_CONTROL_MEAS 0xF4
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_CONTROL_HUM 0xF2
#define BME280_REG_CHIPID 0xD0

// Calibration data registers
#define BME280_REG_CALIB_00 0x88

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Calibration data structure
struct bme280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
    uint8_t dig_H1;
    int16_t dig_H2;
    uint8_t dig_H3;
    int16_t dig_H4;
    int16_t dig_H5;
    int8_t dig_H6;
};

static struct bme280_calib_data calib;

// Function prototypes
int bme280_init(int i2c_bus, int i2c_addr);
int bme280_read_calibration_data(int i2c_bus, int i2c_addr, struct bme280_calib_data *calib);
int bme280_read_data(int i2c_bus, int i2c_addr, int32_t *temperature, int32_t *pressure, int32_t *humidity);
double bme280_compensate_temperature(int32_t adc_T, struct bme280_calib_data *calib);
double bme280_compensate_pressure(int32_t adc_P, struct bme280_calib_data *calib, double t_fine);
double bme280_compensate_humidity(int32_t adc_H, struct bme280_calib_data *calib, double t_fine);
int log_data(FILE *fp, double temperature, double humidity, double pressure);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// BME280 initialization function
int bme280_init(int i2c_bus, int i2c_addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", i2c_bus);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, i2c_addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return -1;
    }

    // Check the chip ID
    uint8_t chip_id;
    if (i2c_smbus_read_byte_data(i2c_fd, BME280_REG_CHIPID) < 0) {
        fprintf(stderr, "Error reading chip ID: %s\n", strerror(errno));
        close(i2c_fd);
        return -1;
    }
    chip_id = i2c_smbus_read_byte_data(i2c_fd, BME280_REG_CHIPID);

    if (chip_id != 0x60) {
        fprintf(stderr, "Incorrect chip ID: 0x%02X\n", chip_id);
        close(i2c_fd);
        return -1;
    }

    // Read calibration data
    if (bme280_read_calibration_data(i2c_bus, i2c_addr, &calib) != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        close(i2c_fd);
        return -1;
    }

    // Set oversampling and mode
    uint8_t config = (0x00 << 5) | (0x05 << 2) | 0x00; // t_sb = 0.5ms, filter = 16
    if (i2c_smbus_write_byte_data(i2c_fd, BME280_REG_CONFIG, config) < 0) {
        fprintf(stderr, "Error writing config register: %s\n", strerror(errno));
        close(i2c_fd);
        return -1;
    }

    uint8_t ctrl_hum = 0x01; // Humidity oversampling x1
    if (i2c_smbus_write_byte_data(i2c_fd, BME280_REG_CONTROL_HUM, ctrl_hum) < 0) {
        fprintf(stderr, "Error writing humidity control register: %s\n", strerror(errno));
        close(i2c_fd);
        return -1;
    }

