    if (read_raw_temperature(&ut) != 0) {
        fprintf(stderr, "Error reading raw temperature in interrupt\n");
        return;
    }

    if (read_raw_pressure(&up) != 0) {
        fprintf(stderr, "Error reading raw pressure in interrupt\n");
        return;
    }

