#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"
#define PWM_FREQUENCY 25000
#define MIN_TEMP 40.0
#define MAX_TEMP 70.0

static volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int read_cpu_temp() {
    FILE *fp;
    int temp;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Failed to open temperature file");
        return -1;
    }

    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Failed to read temperature from file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp / 1000; // Convert to degrees Celsius
}

int calculate_duty_cycle(float temperature) {
    int duty_cycle;

    if (temperature <= MIN_TEMP) {
        duty_cycle = 0;
    } else if (temperature >= MAX_TEMP) {
        duty_cycle = 255;
    } else {
        duty_cycle = (int)(((temperature - MIN_TEMP) / (MAX_TEMP - MIN_TEMP)) * 255.0);
    }

    return duty_cycle;
}

int set_fan_speed(int duty_cycle) {
    if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Failed to set fan speed\n");
        return -1;
    }
    return 0;
}

int log_data(float temperature, int duty_cycle) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f°C, Duty Cycle: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, duty_cycle);

    if (ferror(fp)) {
        fprintf(stderr, "Error writing to log file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main() {
    int pigpio_init_result;
    float temperature;
    int duty_cycle;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pigpio_init_result);
        return 1;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, 255);

    while (running) {
        temperature = read_cpu_temp();
        if (temperature == -1) {
            fprintf(stderr, "Failed to read temperature, using previous value or exiting.\n");
            // Consider exiting if temperature reading consistently fails.
            sleep(5);
            continue;
        }

        duty_cycle = calculate_duty_cycle(temperature);
        if (set_fan_speed(duty_cycle) != 0) {
            fprintf(stderr, "Failed to set fan speed, exiting.\n");
            running = 0; // Exit the loop if setting fan speed fails.
        }

        if (log_data(temperature, duty_cycle) != 0) {
            fprintf(stderr, "Failed to log data, continuing.\n");
        }

        sleep(5);
    }

    gpioPWM(FAN_GPIO, 0); // Stop the fan
    gpioTerminate(); // Terminate pigpio

    return 0;
}

