#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <errno.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <gpiod.h>
#include <math.h>

// Configuration
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define LED_GPIO 18
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0
#define SLEEP_DURATION_MS 1000

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static struct gpiod_line *i2c_line = NULL;
static struct gpiod_line *reset_line = NULL;
static struct gpiod_chip_close_reason close_reason = GPIOD_CHIP_CLOSE_REASON_UNKNOWN;
static pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
static float temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static int i2c_fd = -1;
static int socket_fd = -1;

// Function prototypes
int init_i2c();
int init_gpio();
int init_socket();
void *sensor_reading_thread(void *arg);
float read_temperature();
void add_temperature(float temperature);
float calculate_average();
void control_led(float average_temperature);
void signal_handler(int sig);
void cleanup();

// I2C functions
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (i2c_smbus_write_byte_data(fd, reg, 0) < 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return i2c_smbus_read_i2c_block_data(fd, reg, len);
}

int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    if (i2c_smbus_write_byte_data(fd, reg, value) < 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// GPIO functions
int gpio_set_value(int line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int gpio_get_value(int line) {
    return gpiod_line_get_value(line);
}

int gpio_set_direction(int line, int direction) {
    if (gpiod_line_request_output(line, "sensor_control", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO output: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Sensor reading thread
void *sensor_reading_thread(void *arg) {
    while (1) {
        float temperature = read_temperature();
        if (temperature != -1000.0) {
            pthread_mutex_lock(&buffer_mutex);
            add_temperature(temperature);
            pthread_mutex_unlock(&buffer_mutex);
        } else {
            fprintf(stderr, "Error reading temperature.\n");
        }
        sleep(SLEEP_DURATION_MS / 1000);
    }
    return NULL;
}

// Temperature reading function
float read_temperature() {
    uint8_t buf[2];
    int16_t raw_temperature;

    if (i2c_fd < 0) {
        fprintf(stderr, "I2C not initialized.\n");
        return -1000.0;
    }

    if (i2c_read_bytes(i2c_fd, 0x00, buf, 2) < 0) {
        fprintf(stderr, "Error reading temperature data from I2C.\n");
        return -1000.0;
    }

    raw_temperature = (buf[0] << 8) | buf[1];
    return (float)raw_temperature / 256.0;
}

// Circular buffer functions
void add_temperature(float temperature) {
    pthread_mutex_lock(&buffer_mutex);
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
    pthread_mutex_unlock(&buffer_mutex);
}

float calculate_average() {
    pthread_mutex_lock(&buffer_mutex);
    if (buffer_count == 0) {
        pthread_mutex_unlock(&buffer_mutex);
        return 0.0;
    }

    float sum = 0.0;
    for (int i = 0; i < buffer_count; i++) {
        sum += temperature_buffer[i];
    }
    pthread_mutex_unlock(&buffer_mutex);
    return sum / buffer_count;
}

// LED control function
void control_led(float average_temperature) {
    if (average_temperature > TEMP_THRESHOLD) {
        gpio_set_value(led_line, 1); // Turn LED on
    } else {
        gpio_set_value(led_line, 0); // Turn LED off
    }
}

// Signal handler
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    cleanup();
    exit(0);
}

// Cleanup function
void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (led_line) {
        gpiod_line_set_value(led_line, 0); // Turn off LED
        gpiod_line_release(led_line);
    }
    if (i2c_line) {
        gpiod_line_release(i2c_line);
    }
    if (reset_line) {
        gpiod_line_release(reset_line);
    }
    if (chip) {
        gpiod_chip_close(chip, &close_reason);
    }
    if (socket_fd >= 0) {
        close(socket_fd);
    }
    pthread_mutex_destroy(&buffer_mutex);
}

int main() {
    // Signal handling
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed.\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        cleanup();
        return 1;
    }

    // Initialize socket
    if (init_socket() < 0) {
        fprintf(stderr, "Socket initialization failed.\n");
        cleanup();
        return 1;
    }

    // Create sensor reading thread
    pthread_t sensor_thread;
    if (pthread_create(&sensor_thread, NULL, sensor_reading_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create sensor reading thread.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (1) {
        float average_temperature = calculate_average();
        control_led(average_temperature);

        // Send data to server
        char buffer[256];
        snprintf(buffer, sizeof(buffer), "Temperature: %.2f C, Average: %.2f C", average_temperature, average_temperature);
        if (send(socket_fd, buffer, strlen(buffer), 0) < 0) {
