// I2C functions
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (i2c_smbus_write_byte_data(fd, reg, 0) < 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return i2c_smbus_read_i2c_block_data(fd, reg, len);
}

