        return -1;
    }
    return 0;
}

// Sensor reading thread
void *sensor_reading_thread(void *arg) {
    while (1) {
        float temperature = read_temperature();
        if (temperature != -1000.0) {
            pthread_mutex_lock(&buffer_mutex);
            add_temperature(temperature);
            pthread_mutex_unlock(&buffer_mutex);
        } else {
            fprintf(stderr, "Error reading temperature.\n");
        }
        sleep(SLEEP_DURATION_MS / 1000);
    }
    return NULL;
}

// Temperature reading function
float read_temperature() {
    uint8_t buf[2];
    int16_t raw_temperature;

    if (i2c_fd < 0) {
        fprintf(stderr, "I2C not initialized.\n");
        return -1000.0;
    }

    if (i2c_read_bytes(i2c_fd, 0x00, buf, 2) < 0) {
        fprintf(stderr, "Error reading temperature data from I2C.\n");
        return -1000.0;
    }

    raw_temperature = (buf[0] << 8) | buf[1];
    return (float)raw_temperature / 256.0;
}

