#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <jansson.h>
#include <math.h>

// Configuration structure
typedef struct {
    double target_temperature;
    double Kp;
    double Ki;
    double Kd;
} Config;

// Global variables
int spi_handle;
double r_ref = 430.0; // Reference resistor value
double r0 = 100.0;    // PT100 resistance at 0°C
double A = 3.9083e-3; // Callendar-Van Dusen coefficients
double B = -5.775e-7;
double C = 2.4411e-12;
double D = -5.2614e-18;
double target_temperature = 25.0; // Default target temperature
double Kp = 1.0;
double Ki = 0.1;
double Kd = 0.01;

// PID variables
double integral = 0.0;
double previous_error = 0.0;

// Global flag for graceful shutdown
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_config(const char *filename, Config *config);
int init_spi();
int init_pwm();
double read_rtd();
double rtd_to_resistance(double rtd_code);
double resistance_to_temperature(double resistance);
double calculate_pid(double current_temperature);
void set_pwm_duty(double duty_cycle);
void signal_handler(int signal);
void log_error(const char *message);

// Function to read configuration from JSON file
int read_config(const char *filename, Config *config) {
    json_t *root;
    json_error_t error;

    root = json_load_file(filename, 0, &error);
    if (!root) {
        fprintf(stderr, "Error: Could not load config file: %s\n", error.text);
        fprintf(stderr, "Using default configuration.\n");
        config->target_temperature = 25.0;
        config->Kp = 1.0;
        config->Ki = 0.1;
        config->Kd = 0.01;
        return -1; // Indicate failure, but continue with defaults
    }

    json_t *target = json_object_get(root, "target_temperature");
    if (!target || !json_is_real(target)) {
        fprintf(stderr, "Error: 'target_temperature' not found or invalid in config file.\n");
        json_decref(root);
        return -1;
    }
    config->target_temperature = json_real_value(target);

    json_t *Kp_val = json_object_get(root, "Kp");
    if (!Kp_val || !json_is_real(Kp_val)) {
        fprintf(stderr, "Error: 'Kp' not found or invalid in config file.\n");
        json_decref(root);
        return -1;
    }
    config->Kp = json_real_value(Kp_val);

    json_t *Ki_val = json_object_get(root, "Ki");
    if (!Ki_val || !json_is_real(Ki_val)) {
        fprintf(stderr, "Error: 'Ki' not found or invalid in config file.\n");
        json_decref(root);
        return -1;
    }
    config->Ki = json_real_value(Ki_val);

    json_t *Kd_val = json_object_get(root, "Kd");
    if (!Kd_val || !json_is_real(Kd_val)) {
        fprintf(stderr, "Error: 'Kd' not found or invalid in config file.\n");
        json_decref(root);
        return -1;
    }
    config->Kd = json_real_value(Kd_val);

    json_decref(root);
    return 0; // Indicate success
}

// Function to initialize SPI
int init_spi() {
    spi_handle = spiOpen(0, 500000, 0); // SPI0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: Could not open SPI device: %d\n", spi_handle);
        return -1;
    }

    // Initialize MAX31865 (0x80 -> 0xC1)
    char config_data[2] = {0x80, 0xC1};
    int result = spiWrite(spi_handle, (char *)config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error: Could not write to MAX31865 config register: %d\n", result);
        spiClose(spi_handle);
        return -1;
    }

    return 0;
}

// Function to initialize PWM
int init_pwm() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(18, PI_OUTPUT); // Set GPIO18 as output
    gpioSetPWMfrequency(18, 1000); // Set PWM frequency to 1 kHz
    gpioSetPWMrange(18, 1000);   // Set PWM range to 0-1000 (100%)
    gpioPWM(18, 0);             // Initially turn off the heater

    return 0;
}

// Function to read RTD code from MAX31865
double read_rtd() {
    char tx_buf[2] = {0x00, 0x00}; // Dummy data for reading
    char rx_buf[2];
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 2);

    if (result != 0) {
        fprintf(stderr, "Error: SPI read failed: %d\n", result);
        return -1.0; // Indicate error
    }

    int rtd_code = ((rx_buf[0] & 0x3F) << 8) | rx_buf[1]; // Extract 15-bit RTD code

    // Check fault bit (D0 of MSB)
    if (rx_buf[0] & 0x01) {
        fprintf(stderr, "Error: RTD fault detected!\n");
        return -1.0; // Indicate error
    }

    return (double)rtd_code;
}

// Function to convert RTD code to resistance
double rtd_to_resistance(double rtd_code) {
    return (rtd_code / 32768.0) * r_ref;
}

// Function to convert resistance to temperature (Callendar-Van Dusen)
double resistance_to_temperature(double resistance) {
    double t;
    double temp = resistance / r0;

    if (temp <= 0) {
        return 0;
    }

    double t1 = temp / (A + B * temp + C * temp * temp + D * temp * temp * temp);
    return t1;
}

// Function to calculate PID output
double calculate_pid(double current_temperature) {
    double error = target_temperature - current_temperature;

    integral += error;
    double derivative = error - previous_error;

    double output = Kp * error + Ki * integral + Kd * derivative;

    previous_error = error;

    // Limit the output to 0-100%
    if (output < 0) {
        output = 0;
    } else if (output > 100) {
        output = 100;
    }

    return output;
}

// Function to set PWM duty cycle
void set_pwm_duty(double duty_cycle) {
    int pwm_value = (int)(duty_cycle * 1000.0 / 100.0); // Convert percentage to range 0-1000
    gpioPWM(18, pwm_value);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, shutting down...\n");
    terminate = 1;
}

// Function to log errors to stderr
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Read configuration from file
    if (read_config("config.json", &target_temperature) != 0) {
        fprintf(stderr, "Using default configuration.\n");
    }

    // Initialize SPI
    if (init_spi() != 0) {
        log_error("SPI initialization failed");
        return 1;
    }

    // Initialize PWM
    if (init_pwm() != 0) {
        log_error("PWM initialization failed");
        spiClose(spi_handle);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read RTD value
        double rtd_code = read_rtd();
        if (rtd_code < 0) {
            log_error("Failed to read RTD value");
            spiClose(spi_handle);
            gpioPWM(18, 0); // Turn off heater
            gpioTerminate(); // Terminate pigpio
            return 1;
        }

        // Convert RTD code to resistance
        double resistance = rtd_to_resistance(rtd_code);

        // Convert resistance to temperature
        double temperature = resistance_to_temperature(resistance);

        // Calculate PID output
        double duty_cycle = calculate_pid(temperature);

        // Set PWM duty cycle
        set_pwm_duty(duty_cycle);

        // Check for failsafe conditions
        if (temperature > 80.0 || rtd_code < 0) {
            fprintf(stderr, "Failsafe triggered! Shutting down.\n");
            spiClose(spi_handle);
            gpioPWM(18, 0); // Turn off heater
            gpioTerminate(); // Terminate pigpio
            return 1;
        }

        // Wait for 100ms
        gpioDelay(100000); // 100ms
    }

    // Shutdown sequence
    fprintf(stderr, "Shutting down...\n");
    spiClose(spi_handle);
    gpioPWM(18, 0); // Turn off heater
    gpioTerminate(); // Terminate pigpio

    return 0;
}

