int init_pwm() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(18, PI_OUTPUT); // Set GPIO18 as output
    gpioSetPWMfrequency(18, 1000); // Set PWM frequency to 1 kHz
    gpioSetPWMrange(18, 1000);   // Set PWM range to 0-1000 (100%)
    gpioPWM(18, 0);             // Initially turn off the heater

    return 0;
}

// Function to read RTD code from MAX31865
double read_rtd() {
    char tx_buf[2] = {0x00, 0x00}; // Dummy data for reading
    char rx_buf[2];
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 2);

    if (result != 0) {
        fprintf(stderr, "Error: SPI read failed: %d\n", result);
        return -1.0; // Indicate error
    }

    int rtd_code = ((rx_buf[0] & 0x3F) << 8) | rx_buf[1]; // Extract 15-bit RTD code

    // Check fault bit (D0 of MSB)
    if (rx_buf[0] & 0x01) {
        fprintf(stderr, "Error: RTD fault detected!\n");
        return -1.0; // Indicate error
    }

    return (double)rtd_code;
}

// Function to convert RTD code to resistance
double rtd_to_resistance(double rtd_code) {
    return (rtd_code / 32768.0) * r_ref;
}

// Function to convert resistance to temperature (Callendar-Van Dusen)
double resistance_to_temperature(double resistance) {
    double t;
    double temp = resistance / r0;

    if (temp <= 0) {
        return 0;
    }

    double t1 = temp / (A + B * temp + C * temp * temp + D * temp * temp * temp);
    return t1;
}

// Function to calculate PID output
double calculate_pid(double current_temperature) {
    double error = target_temperature - current_temperature;

    integral += error;
    double derivative = error - previous_error;

    double output = Kp * error + Ki * integral + Kd * derivative;

    previous_error = error;

    // Limit the output to 0-100%
    if (output < 0) {
        output = 0;
    } else if (output > 100) {
        output = 100;
    }

    return output;
}

// Function to set PWM duty cycle
void set_pwm_duty(double duty_cycle) {
    int pwm_value = (int)(duty_cycle * 1000.0 / 100.0); // Convert percentage to range 0-1000
    gpioPWM(18, pwm_value);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, shutting down...\n");
    terminate = 1;
}

// Function to log errors to stderr
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Read configuration from file
    if (read_config("config.json", &target_temperature) != 0) {
        fprintf(stderr, "Using default configuration.\n");
    }

    // Initialize SPI
    if (init_spi() != 0) {
        log_error("SPI initialization failed");
        return 1;
    }

    // Initialize PWM
    if (init_pwm() != 0) {
        log_error("PWM initialization failed");
        spiClose(spi_handle);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read RTD value
        double rtd_code = read_rtd();
        if (rtd_code < 0) {
            log_error("Failed to read RTD value");
            spiClose(spi_handle);
            gpioPWM(18, 0); // Turn off heater
            gpioTerminate(); // Terminate pigpio
            return 1;
        }

        // Convert RTD code to resistance
        double resistance = rtd_to_resistance(rtd_code);

        // Convert resistance to temperature
        double temperature = resistance_to_temperature(resistance);

        // Calculate PID output
        double duty_cycle = calculate_pid(temperature);

        // Set PWM duty cycle
        set_pwm_duty(duty_cycle);

        // Check for failsafe conditions
        if (temperature > 80.0 || rtd_code < 0) {
            fprintf(stderr, "Failsafe triggered! Shutting down.\n");
            spiClose(spi_handle);
            gpioPWM(18, 0); // Turn off heater
            gpioTerminate(); // Terminate pigpio
            return 1;
        }

        // Wait for 100ms
        gpioDelay(100000); // 100ms
    }

    // Shutdown sequence
    fprintf(stderr, "Shutting down...\n");
    spiClose(spi_handle);
    gpioPWM(18, 0); // Turn off heater
    gpioTerminate(); // Terminate pigpio

    return 0;
}

