// I2C read function with retry
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    int retries = 3;
    int delay_ms = 10;
    int result;

    while (retries > 0) {
        result = read(fd, data, len);
        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X, len %d): %s. Retrying...\n", reg, len, strerror(errno));
            retries--;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries (reg 0x%02X, len %d).\n", reg, len);
    return -1; // Failure
}

// I2C write function with retry
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    int retries = 3;
    int delay_ms = 10;
    int result;

    while (retries > 0) {
        result = write(fd, &value, 1);
        if (result == 1) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error (reg 0x%02X, value 0x%02X): %s. Retrying...\n", reg, value, strerror(errno));
            retries--;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
        }
    }

    fprintf(stderr, "I2C write failed after multiple retries (reg 0x%02X, value 0x%02X).\n", reg, value);
    return -1; // Failure
