// Read calibration data from the BMP180
int read_calibration_data(int fd) {
    uint8_t data[22];

    if (i2c_read_bytes(fd, BMP180_REG_CAL_AC1, data, 22) != 0) {
        fprintf(stderr, "Failed to read calibration data.\n");
        return -1;
    }

    ac1 = (data[0] << 8) | data[1];
    ac2 = (data[2] << 8) | data[3];
    ac3 = (data[4] << 8) | data[5];
    ac4 = (data[6] << 8) | data[7];
    ac5 = (data[8] << 8) | data[9];
    ac6 = (data[10] << 8) | data[11];
    b1 = (data[12] << 8) | data[13];
    b2 = (data[14] << 8) | data[15];
    mb = (data[16] << 8) | data[17];
    mc = (data[18] << 8) | data[19];
    md = (data[20] << 8) | data[21];

    return 0;
}

// Read raw temperature value from the BMP180
int read_raw_temperature(int fd, int32_t *raw_temperature) {
    uint8_t data[2];
    uint8_t reg = BMP180_REG_CONTROL;
    uint8_t value = 0x2E; // Temperature measurement command

    if (i2c_write_byte(fd, reg, value) != 0) {
        fprintf(stderr, "Failed to write temperature measurement command.\n");
        return -1;
    }

    usleep(5000); // Wait 4.5ms

    reg = BMP180_REG_MSB;
    if (i2c_read_bytes(fd, reg, data, 2) != 0) {
        fprintf(stderr, "Failed to read raw temperature data.\n");
        return -1;
    }

    *raw_temperature = (data[0] << 8) | data[1];
    return 0;
}

// Read raw pressure value from the BMP180
int read_raw_pressure(int fd, int32_t *raw_pressure) {
    uint8_t data[3];
    uint8_t reg = BMP180_REG_CONTROL;
    uint8_t value = 0x34 + (OSS << 6); // Pressure measurement command

    if (i2c_write_byte(fd, reg, value) != 0) {
        fprintf(stderr, "Failed to write pressure measurement command.\n");
        return -1;
    }

    usleep(26000); // Wait 25.5ms for OSS = 0

    reg = BMP180_REG_MSB;
    if (i2c_read_bytes(fd, reg, data, 3) != 0) {
        fprintf(stderr, "Failed to read raw pressure data.\n");
        return -1;
    }

    *raw_pressure = ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - OSS);
    return 0;
}

// Calculate temperature in degrees Celsius
double calculate_temperature(int32_t ut) {
    int32_t x1 = (((int32_t)ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    int32_t b5 = x1 + x2;
    double temperature = ((b5 + 8) >> 4) / 10.0;
    return temperature;
}

// Calculate pressure in hPa
double calculate_pressure(int32_t up, int32_t ut) {
    int32_t x1 = (((int32_t)ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    int32_t b5 = x1 + x2;

    int32_t b6 = b5 - 4000;
    x1 = (b2 * (b6 * b6) >> 12) >> 11;
    x2 = (ac2 * b6) >> 11;
