    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire bus access and/or talk to slave: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("breach_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_fd) != 0) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    int32_t raw_temperature, raw_pressure;
    double temperature, pressure;

    // Main loop
    while (!terminate) {
        // Read raw temperature
        if (read_raw_temperature(i2c_fd, &raw_temperature) != 0) {
            fprintf(stderr, "Failed to read raw temperature. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        // Read raw pressure
        if (read_raw_pressure(i2c_fd, &raw_pressure) != 0) {
            fprintf(stderr, "Failed to read raw pressure. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        // Calculate temperature and pressure
        temperature = calculate_temperature(raw_temperature);
        pressure = calculate_pressure(raw_pressure, raw_temperature);

        // Check for breaches
        if (temperature > TEMP_THRESHOLD_HIGH || pressure < PRESSURE_THRESHOLD_LOW) {
            log_breach(temperature, pressure);
        }

        // Wait 1 second
        sleep(1);
    }

    // Close resources
    fclose(log_file);
    close(i2c_fd);

    return 0;
}

