#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Fan GPIO pin
#define FAN_PIN 18

// Timer interval (milliseconds)
#define TIMER_INTERVAL 500

// Circular buffer size
#define BUFFER_SIZE 60

// Structure to hold sensor data
typedef struct {
    time_t timestamp;
    float temperature;
    float pressure;
} sensor_data_t;

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Circular buffer
sensor_data_t buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_calibration_data();
int read_raw_temperature(int32_t *raw_temperature);
int read_raw_pressure(int32_t *raw_pressure);
float calculate_temperature(int32_t ut);
float calculate_pressure(int32_t up, float temperature);
void add_reading(float temperature, float pressure);
void print_buffer();
void timer_callback();
void signal_handler(int signal);

// Function to read calibration data from BMP180
int read_calibration_data() {
    char data[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, data, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    ac1 = (data[0] << 8) | data[1];
    ac2 = (data[2] << 8) | data[3];
    ac3 = (data[4] << 8) | data[5];
    ac4 = (data[6] << 8) | data[7];
    ac5 = (data[8] << 8) | data[9];
    ac6 = (data[10] << 8) | data[11];
    b1 = (data[12] << 8) | data[13];
    b2 = (data[14] << 8) | data[15];
    mb = (data[16] << 8) | data[17];
    mc = (data[18] << 8) | data[19];
    md = (data[20] << 8) | data[21];

    return 0;
}

// Function to read raw temperature data from BMP180
int read_raw_temperature(int32_t *raw_temperature) {
    char buf[1];
    buf[0] = 0x2E; // Temperature measurement command

    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 1) {
        fprintf(stderr, "Error writing temperature measurement command\n");
        return -1;
    }

    gpioDelay(5000); // Wait 5ms

    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    *raw_temperature = (data[0] << 8) | data[1];
    return 0;
}

// Function to read raw pressure data from BMP180
int read_raw_pressure(int32_t *raw_pressure) {
    char buf[1];
    buf[0] = 0x34; // Pressure measurement command (OSS = 0)

    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 1) {
        fprintf(stderr, "Error writing pressure measurement command\n");
        return -1;
    }

    gpioDelay(5000); // Wait 5ms

    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 2) != 2) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    *raw_pressure = (data[0] << 8) | data[1];
    return 0;
}

// Function to calculate true temperature (°C)
float calculate_temperature(int32_t ut) {
    int32_t x1 = (((int32_t)ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    int32_t b5 = x1 + x2;
    float temperature = ((b5 + 8) >> 4) / 10.0f;
    return temperature;
}

// Function to calculate true pressure (Pa)
float calculate_pressure(int32_t up, float temperature) {
    int32_t b6 = ((int32_t)temperature * 10) - 4000;
    int32_t x1 = ((int32_t)b2 * (b6 * b6) >> 12) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << 0) + 2) >> 2;
    uint32_t x1_u = ((uint32_t)ac3 * b6) >> 13;
    uint32_t x2_u = ((uint32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    uint32_t x3_u = ((x1_u + x2_u) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (x3_u + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    float pressure = p + ((x1 + x2 + 3791) >> 4);
    return pressure;
}

// Function to add a reading to the circular buffer
void add_reading(float temperature, float pressure) {
    buffer[buffer_index].timestamp = time(NULL);
    buffer[buffer_index].temperature = temperature;
    buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Sensor Readings ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Corrected index calculation
        printf("Timestamp: %ld, Temperature: %.2f °C, Pressure: %.2f Pa\n",
               buffer[index].timestamp, buffer[index].temperature, buffer[index].pressure);
    }
    printf("-------------------------\n");
}

// Timer callback function
void timer_callback() {
    int32_t ut, up;
    float temperature, pressure;

    if (read_raw_temperature(&ut) == 0 && read_raw_pressure(&up) == 0) {
        temperature = calculate_temperature(ut);
        pressure = calculate_pressure(up, temperature);

        add_reading(temperature, pressure);
        print_buffer();

        if (temperature > 30.0f) {
            gpioWrite(FAN_PIN, 1); // Turn fan on
        } else {
            gpioWrite(FAN_PIN, 0); // Turn fan off
        }
    } else {
        fprintf(stderr, "Error reading sensor data\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data, exiting\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set FAN_PIN as output
    gpioSetMode(FAN_PIN, PI_OUTPUT);
    gpioWrite(FAN_PIN, 0); // Ensure fan is off initially

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer callback
    gpioSetTimerFuncEx(0, TIMER_INTERVAL, timer_callback, 0);

    // Main loop
    while (!terminate) {
        gpioDelay(100); // Sleep for 100ms
    }

    // Cleanup
    gpioWrite(FAN_PIN, 0); // Turn fan off
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

