#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (0, 1, 2, or 3)
#define BMP180_OSS 0

// GPIO pin for toggle switch
#define TOGGLE_GPIO 27

// Debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t logging_enabled = 0;
volatile sig_atomic_t program_running = 1;

// Calibration data
short ac1, ac2, ac3, b1, b2, mb, mc, md;
unsigned short ac4, ac5, ac6;

// Function prototypes
int read_calibration_data();
int read_raw_temperature(long *raw_temperature);
int read_raw_pressure(long *raw_pressure);
double calculate_pressure(long raw_temperature, long raw_pressure);
void log_data(double pressure);
void toggle_logging();
void signal_handler(int signal);

// Function to read a short (2 bytes) from I2C
int read_short(int handle, char reg, short *value)
{
    char buf[2];
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading short from I2C\n");
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read an unsigned short (2 bytes) from I2C
int read_ushort(int handle, char reg, unsigned short *value)
{
    char buf[2];
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading unsigned short from I2C\n");
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read calibration data from BMP180
int read_calibration_data()
{
    if (read_short(i2c_handle, BMP180_REG_CAL_AC1, &ac1) != 0) return -1;
    if (read_short(i2c_handle, BMP180_REG_CAL_AC2, &ac2) != 0) return -1;
    if (read_short(i2c_handle, BMP180_REG_CAL_AC3, &ac3) != 0) return -1;
    if (read_ushort(i2c_handle, BMP180_REG_CAL_AC4, &ac4) != 0) return -1;
    if (read_ushort(i2c_handle, BMP180_REG_CAL_AC5, &ac5) != 0) return -1;
    if (read_ushort(i2c_handle, BMP180_REG_CAL_AC6, &ac6) != 0) return -1;
    if (read_short(i2c_handle, BMP180_REG_CAL_B1, &b1) != 0) return -1;
    if (read_short(i2c_handle, BMP180_REG_CAL_B2, &b2) != 0) return -1;
    if (read_short(i2c_handle, BMP180_REG_CAL_MB, &mb) != 0) return -1;
    if (read_short(i2c_handle, BMP180_REG_CAL_MC, &mc) != 0) return -1;
    if (read_short(i2c_handle, BMP180_REG_CAL_MD, &md) != 0) return -1;

    return 0;
}

// Function to read raw temperature data from BMP180
int read_raw_temperature(long *raw_temperature)
{
    char buf[1];
    buf[0] = 0x2E; // Temperature measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 1) {
        fprintf(stderr, "Error writing temperature measurement command\n");
        return -1;
    }
    gpioDelay(5000); // Wait 5ms

    if (read_short(i2c_handle, BMP180_REG_MSB, (short *)raw_temperature) != 0) return -1;
    return 0;
}

// Function to read raw pressure data from BMP180
