#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define HEATER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000 // 2 MHz
#define TARGET_TEMPERATURE 25.0
#define MAX_DUTY_CYCLE 80
#define MIN_DUTY_CYCLE 0
#define MAX_PWM_RANGE 1000000 // 100% duty cycle
#define KP 1.0
#define KI 0.1
#define MAX_ERROR_COUNT 5

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for PI controller state
typedef struct {
    double integral;
    int error_count;
} PIControllerState;

PIControllerState pi_state = {0.0, 0};

// Function prototypes
double read_temperature();
void set_heater_duty_cycle(int duty_cycle);
double pi_controller(double setpoint, double actual_temperature, PIControllerState *state);
void log_data(double temperature, int duty_cycle);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read temperature from MAX31855
double read_temperature() {
    unsigned char buffer[4];
    int result;

    result = spiRead(spi_handle, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "SPI read failed: %d\n", result);
        return -1000.0; // Indicate error
    }

    // Check for fault bits
    if (buffer[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Open circuit\n");
        return -1000.0;
    }
    if (buffer[3] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        return -1000.0;
    }
    if (buffer[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        return -1000.0;
    }

    // Extract temperature data (bits 3-14)
    int16_t raw_temp = ((buffer[0] << 8) | buffer[1]) >> 2;
    double temperature = raw_temp * 0.25;

    return temperature;
}

// Function to set heater duty cycle using PWM
void set_heater_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > MAX_DUTY_CYCLE) duty_cycle = MAX_DUTY_CYCLE;

    int pwm_range = MAX_PWM_RANGE; // Use a fixed PWM range
    int pwm_value = (int)(((double)duty_cycle / 100.0) * pwm_range);

    gpioPWM(HEATER_GPIO, pwm_value);
}

// PI controller function
double pi_controller(double setpoint, double actual_temperature, PIControllerState *state) {
    double error = setpoint - actual_temperature;
    state->integral += error;

    // Anti-windup
    if (state->integral > 100) state->integral = 100;
    if (state->integral < -100) state->integral = -100;

    double output = KP * error + KI * state->integral;

    // Limit output to 0-100
    if (output < 0) output = 0;
    if (output > 100) output = 100;

    return output;
}

// Function to log data to CSV file
void log_data(double temperature, int duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output for heater control
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(HEATER_GPIO, MAX_PWM_RANGE);

    // Set PWM frequency (not directly configurable with gpioPWM, but important for SPI timing)
    //gpioSetPWMfrequency(HEATER_GPIO, 2000); // 2 kHz

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 2 MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("heater_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),DutyCycle(%%)\n");
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Turn off heater
    set_heater_duty_cycle(0);

    // Close SPI
    spiClose(spi_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    double temperature, setpoint;
    int duty_cycle;
    double pi_output;
    int error_count = 0;

    // Main loop
    while (!terminate) {
        // Read temperature
        temperature = read_temperature();

        if (temperature < -999.0) {
            fprintf(stderr, "Error reading temperature, setting duty cycle to 0\n");
            set_heater_duty_cycle(0);
            error_count++;
            if (error_count > MAX_ERROR_COUNT) {
                fprintf(stderr, "Too many errors, shutting down\n");
                break;
            }
            sleep(1); // Wait before retrying
            continue;
        }

        // PI controller
        pi_output = pi_controller(TARGET_TEMPERATURE, temperature, &pi_state);

        // Set duty cycle
        duty_cycle = (int)pi_output;
        set_heater_duty_cycle(duty_cycle);

        // Log data
        log_data(temperature, duty_cycle);

        // Wait
        sleep(1);
    }

    // Cleanup
    cleanup();

    return 0;
}

