int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output for heater control
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(HEATER_GPIO, MAX_PWM_RANGE);

    // Set PWM frequency (not directly configurable with gpioPWM, but important for SPI timing)
    //gpioSetPWMfrequency(HEATER_GPIO, 2000); // 2 kHz

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 2 MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("heater_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),DutyCycle(%%)\n");
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Turn off heater
    set_heater_duty_cycle(0);

    // Close SPI
    spiClose(spi_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    double temperature, setpoint;
    int duty_cycle;
    double pi_output;
    int error_count = 0;

    // Main loop
    while (!terminate) {
        // Read temperature
        temperature = read_temperature();

        if (temperature < -999.0) {
            fprintf(stderr, "Error reading temperature, setting duty cycle to 0\n");
            set_heater_duty_cycle(0);
            error_count++;
            if (error_count > MAX_ERROR_COUNT) {
                fprintf(stderr, "Too many errors, shutting down\n");
                break;
            }
            sleep(1); // Wait before retrying
            continue;
        }

        // PI controller
        pi_output = pi_controller(TARGET_TEMPERATURE, temperature, &pi_state);

        // Set duty cycle
        duty_cycle = (int)pi_output;
        set_heater_duty_cycle(duty_cycle);

        // Log data
        log_data(temperature, duty_cycle);

        // Wait
        sleep(1);
    }

    // Cleanup
    cleanup();

    return 0;
}

