#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <curl/curl.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 1000
#define SERVER_URL "http://yourserver.com/api/humidity"

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
    int valid;
} DHT22Data;

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to initialize pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to send a start signal to the DHT22 sensor
int send_start_signal() {
    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0); // Low for at least 1ms
    gpioDelay(1); // Wait 1ms
    gpioWrite(DHT22_GPIO, 1); // High
    gpioDelay(30); // Wait 30us
    return 0;
}

// Function to read data from the DHT22 sensor
int read_dht22_data(unsigned char *data) {
    gpioSetMode(DHT22_GPIO, PI_INPUT);

    unsigned int laststate = gpioRead(DHT22_GPIO);
    unsigned int counter = 0;
    unsigned int j = 0, i;

    // Wait for the DHT22 to start sending data
    while (gpioRead(DHT22_GPIO) == laststate) {
        counter++;
        if (counter > 200) {
            fprintf(stderr, "DHT22 timeout waiting for start signal\n");
            return -1;
        }
        gpioDelay(1); // Delay 1us
    }

    laststate = gpioRead(DHT22_GPIO);
    counter = 0;

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        // Wait for the DHT22 to start sending data for each bit
        while (gpioRead(DHT22_GPIO) == laststate) {
            counter++;
            if (counter > 200) {
                fprintf(stderr, "DHT22 timeout waiting for bit start signal\n");
                return -1;
            }
            gpioDelay(1); // Delay 1us
        }

        // Measure the duration of the high pulse
        unsigned int start = gpioTick();
        while (gpioRead(DHT22_GPIO) == laststate) {
            if (gpioTick() - start > 200) {
                fprintf(stderr, "DHT22 timeout waiting for bit end signal\n");
                return -1;
            }
            gpioDelay(1); // Delay 1us
        }
        unsigned int end = gpioTick();

        // Determine if the bit is 0 or 1 based on the pulse duration
        if ((end - start) > 40) {
            data[j / 8] |= (1 << (7 - (j % 8)));
        }
        j++;
    }

    return 0;
}

// Function to parse the DHT22 data and validate the checksum
DHT22Data parse_dht22_data(const unsigned char *data) {
    DHT22Data result;
    result.valid = 0; // Initialize as invalid

    // Checksum validation
    if (((data[0] + data[1] + data[2] + data[3]) & 0xFF) != data[4]) {
        fprintf(stderr, "DHT22 checksum error\n");
        return result; // Return invalid data
    }

    // Calculate temperature
    int humidity = (data[0] << 8) + data[1];
    float temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        temperature *= -1;
    }

    result.temperature = temperature;
    result.humidity = humidity;
    result.valid = 1; // Mark as valid

    return result;
}

// Function to format the data as a JSON string
char *format_json(float temperature, float humidity) {
    char *json_string = malloc(100); // Allocate memory for the JSON string
    if (json_string == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    snprintf(json_string, 100, "{\"temperature\": %.2f, \"humidity\": %.2f}", temperature, humidity);
    return json_string;
}

// Function to send the data to the server using libcurl
int send_data_to_server(const char *json_string) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_string);

        // Set content type to application/json
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
    }
    curl_global_cleanup();
    return (res == CURLE_OK) ? 0 : -1;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    unsigned char data[5] = {0, 0, 0, 0, 0};
    DHT22Data dht22_data;
    char *json_string;
    int retries = 0;

    while (!terminate) {
        // Retry loop
        while (retries < MAX_RETRIES) {
            // Send start signal
            if (send_start_signal() != 0) {
                fprintf(stderr, "Failed to send start signal, retrying...\n");
                retries++;
                sleep(RETRY_DELAY_MS / 1000); // Sleep for retry delay
                continue;
            }

            // Read data from DHT22
            if (read_dht22_data(data) == 0) {
                // Parse data
                dht22_data = parse_dht22_data(data);

                if (dht22_data.valid) {
                    // Format JSON
                    json_string = format_json(dht22_data.temperature, dht22_data.humidity);

                    if (json_string != NULL) {
                        // Send data to server
                        if (send_data_to_server(json_string) != 0) {
                            fprintf(stderr, "Failed to send data to server, retrying...\n");
                        } else {
                            printf("Data sent successfully: %s\n", json_string);
                        }

                        free(json_string); // Free allocated memory
                    } else {
                        fprintf(stderr, "Failed to format JSON data\n");
                    }
                } else {
                    fprintf(stderr, "DHT22 data invalid, retrying...\n");
                }
            } else {
                fprintf(stderr, "Failed to read DHT22 data, retrying...\n");
            }

            // Reset retries if successful
            retries = 0;
            break; // Exit retry loop on success
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Max retries reached, skipping data collection.\n");
        }

        sleep(5); // Wait 5 seconds before next reading
    }

    // Clean up pigpio
    gpioTerminate();

    return 0;
}

