#include <pigpio.h>
#include <errno.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// BMP180 commands
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34 // OSS = 0
#define BMP180_CMD_PRESSURE1 0x74 // OSS = 1
#define BMP180_CMD_PRESSURE2 0xB4 // OSS = 2
#define BMP180_CMD_PRESSURE3 0xF4 // OSS = 3

// GPIO pin for interrupt
#define INTERRUPT_GPIO 4

// Global variables
int i2c_handle;
FILE *log_file;
volatile int logging_enabled = 0;
volatile unsigned int last_interrupt_tick = 0;

// Calibration coefficients
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int read_calibration_data();
int read_raw_temperature(int32_t *raw_temp);
int read_raw_pressure(int32_t *raw_pressure);
double calculate_pressure(int32_t raw_temp, int32_t raw_pressure);
void log_data(double pressure);
void interrupt_handler(int gpio, int level, unsigned int tick, void *user);
void signal_handler(int signal);

// Function to read a 16-bit value from the BMP180
int16_t read_16(int handle, uint8_t reg)
{
    char buf[2];
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading 16-bit value from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return (int16_t)((buf[0] << 8) | buf[1]);
}

// Function to read an unsigned 16-bit value from the BMP180
uint16_t read_u16(int handle, uint8_t reg)
{
    char buf[2];
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading unsigned 16-bit value from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return (uint16_t)((buf[0] << 8) | buf[1]);
}

// Function to read calibration data from the BMP180
int read_calibration_data()
{
    ac1 = read_16(i2c_handle, 0xAA);
    ac2 = read_16(i2c_handle, 0xAC);
    ac3 = read_16(i2c_handle, 0xAE);
    ac4 = read_u16(i2c_handle, 0xB0);
    ac5 = read_u16(i2c_handle, 0xB2);
    ac6 = read_u16(i2c_handle, 0xB4);
    b1 = read_16(i2c_handle, 0xB6);
    b2 = read_16(i2c_handle, 0xB8);
    mb = read_16(i2c_handle, 0xBA);
    mc = read_16(i2c_handle, 0xBC);
    md = read_16(i2c_handle, 0xBE);

    if (ac1 == -1 || ac2 == -1 || ac3 == -1 || ac4 == -1 || ac5 == -1 || ac6 == -1 ||
        b1 == -1 || b2 == -1 || mb == -1 || mc == -1 || md == -1) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int32_t *raw_temp)
{
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) != 0) {
        fprintf(stderr, "Error writing temperature command: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(5000); // Wait 5ms

    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data: %s\n", strerror(errno));
        return -1;
    }

    *raw_temp = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int32_t *raw_pressure)
{
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE3) != 0) {
        fprintf(stderr, "Error writing pressure command: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(26000); // Wait 26ms

    char buf[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data: %s\n", strerror(errno));
        return -1;
    }

    *raw_pressure = (int32_t)(((uint32_t)buf[0] << 16 | (uint32_t)buf[1] << 8 | (uint32_t)buf[2]) >> 8);
    return 0;
}

// Function to calculate pressure in hPa using the Bosch BMP180 compensation algorithm
double calculate_pressure(int32_t raw_temp, int32_t raw_pressure)
{
    int32_t X1, X2, X3, B3, B5, B6, p;
    uint32_t B4, B7;

    B5 = (((int32_t)raw_temp - (int32_t)ac6) * (int32_t)ac5) >> 15;
    X1 = ((int32_t)mc << 11) / (B5 + md);
    B6 = B5 + X1 - 4000;
    X2 = ((B6 * B6) >> 12) * (int32_t)ac2;
    X3 = ((int32_t)ac1 * B6) >> 11;
    B3 = (((((int32_t)ac3) * 4 + X3) << 3) + 2) / 4;
    X1 = ((int32_t)ac1 * B6) >> 13;
    X2 = ((B6 * B6) >> 12) * (int32_t)ac2;
    X3 = ((int32_t)ac1 * B6) >> 13;
    B4 = ((uint32_t)ac4 * (uint32_t)(X1 + X2 + X3 + 32768)) >> 15;
    B7 = ((uint32_t)raw_pressure - B3) * (uint32_t)(50000 >> 3);
    if (B7 < 0x80000000)
    {
        p = (B7 * 2) / B4;
    }
    else
    {
        p = (B7 / B4) * 2;
    }
    X1 = (p >> 8) * (p >> 8);
    X1 = (X1 * 3038) >> 16;
    X2 = (-7357 * p) >> 16;
    p = p + ((X1 + X2 + 3791) >> 4);

    return (double)p / 100.0; // Convert to hPa
}

// Function to log data to a file
void log_data(double pressure)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f hPa\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, unsigned int tick, void *user)
{
    unsigned int current_tick = gpioTick();
    if (current_tick - last_interrupt_tick > 200000) {
        logging_enabled = !logging_enabled;
        last_interrupt_tick = current_tick;
        if (logging_enabled) {
            printf("Data logging enabled\n");
        } else {
            printf("Data logging disabled\n");
        }
    }
}

// Signal handler function
void signal_handler(int signal)
{
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Close I2C handle
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Release pigpio resources
    gpioTerminate();

    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO4 as input with pull-up resistor
    gpioSetMode(INTERRUPT_GPIO, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_GPIO, PI_PUD_UP);

    // Set interrupt handler
    if (gpioSetISRFuncEx(INTERRUPT_GPIO, FALLING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting interrupt handler: %s\n", strerror(errno));
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int32_t raw_temp, raw_pressure;
    double pressure;

    // Main loop
    while (1) {
        if (logging_enabled) {
            // Read raw temperature and pressure
            if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(&raw_pressure) == 0) {
                // Calculate pressure
                pressure = calculate_pressure(raw_temp, raw_pressure);

                // Log data
                log_data(pressure);
            } else {
                fprintf(stderr, "Error reading sensor data. Retrying...\n");
            }
        } else {
            gpioDelay(2000000); // Wait 2 seconds
        }
    }

    return 0;
}

