#define DHT22_PIN 4
#define MAX_RETRIES 3
#define BACKOFF_DELAY 2
#define JSON_BUFFER_SIZE 64

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
    int checksum;
} DHT22Data;

// Global variables
static volatile int running = 1;
static char *server_url = "http://your-server.com/api/humidity";
static int curl_init_retries = 0;
static int curl_http_retries = 0;

// Function prototypes
int read_dht22(int pin, DHT22Data *data);
int validate_checksum(const DHT22Data *data);
int post_humidity(const char *url, float humidity);
void signal_handler(int signal);
void cleanup();
void log_message(int priority, const char *message);

// Signal handler
void signal_handler(int signal) {
    running = 0;
    log_message(LOG_INFO, "Signal received, exiting...");
}

// Cleanup function
void cleanup() {
    log_message(LOG_INFO, "Cleaning up...");
    gpioTerminate();
    curl_global_cleanup();
    closelog();
}

// Log message to syslog
void log_message(int priority, const char *message) {
    openlog("dht22_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, message);
    closelog();
}

// Read DHT22 sensor data
int read_dht22(int pin, DHT22Data *data) {
    int i, j;
    unsigned int raw_data[5] = {0, 0, 0, 0, 0};
    unsigned int checksum = 0;
    long start_time, end_time;

    // 1. Pull the data line low for at least 1 ms
    gpioSetMode(pin, PI_OUTPUT);
    gpioWrite(pin, 0);
    gpioDelay(1000); // 1 ms
    gpioWrite(pin, 1);
    gpioSetMode(pin, PI_INPUT);

    // 2. Wait for the DHT22 to pull the line low (approx. 80us)
    start_time = gpioTick();
    while (gpioRead(pin) == 1) {
        if (gpioTick() - start_time > 100) {
            log_message(LOG_ERR, "DHT22: Timeout waiting for start signal.");
            return -1;
        }
    }

    // 3. Wait for the DHT22 to pull the line high (approx. 20-40 us)
    start_time = gpioTick();
    while (gpioRead(pin) == 0) {
        if (gpioTick() - start_time > 50) {
            log_message(LOG_ERR, "DHT22: Timeout waiting for start signal high.");
            return -1;
        }
    }

    // 4. Wait for the DHT22 to pull the line low again (approx. 80 us)
    start_time = gpioTick();
    while (gpioRead(pin) == 1) {
        if (gpioTick() - start_time > 100) {
            log_message(LOG_ERR, "DHT22: Timeout waiting for start signal low.");
            return -1;
        }
    }

    // 5. Read 40 bits of data
    for (i = 0; i < 40; i++) {
        // Each bit is represented by a 1-2 us pulse
        start_time = gpioTick();
        while (gpioRead(pin) == 0) {
            if (gpioTick() - start_time > 3) {
                log_message(LOG_ERR, "DHT22: Timeout waiting for bit start.");
                return -1;
            }
        }

        end_time = gpioTick();
        while (gpioRead(pin) == 1) {
            if (gpioTick() - end_time > 3) {
                log_message(LOG_ERR, "DHT22: Timeout waiting for bit end.");
                return -1;
            }
        }

        // Determine if the bit is 0 or 1 based on the pulse length
        if (end_time - start_time > 2) {
            raw_data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    // 6. Validate checksum
    checksum = (raw_data[0] + raw_data[1] + raw_data[2] + raw_data[3]) & 0xFF;
    if (checksum != raw_data[4]) {
        log_message(LOG_ERR, "DHT22: Checksum failure.");
        return -1;
    }

    // Convert data to temperature and humidity
    data->humidity = (float)((raw_data[0] << 8) + raw_data[1]) / 10.0;
    data->temperature = (float)(((raw_data[2] & 0x7F) << 8) + raw_data[3]) / 10.0;
    if (raw_data[2] & 0x80) {
        data->temperature *= -1.0;
    }

    data->checksum = checksum;

    return 0;
}

// Post humidity reading to server
int post_humidity(const char *url, float humidity) {
    CURL *curl;
    CURLcode res;
    char json_data[JSON_BUFFER_SIZE];
    int retry = 0;

    snprintf(json_data, JSON_BUFFER_SIZE, "{\"humidity\": %.2f}", humidity);

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_data));
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, NULL); // Remove Content-Type header

        while (retry < MAX_RETRIES) {
            res = curl_easy_perform(curl);
            if (res == CURLE_OK) {
                long response_code;
                curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
                if (response_code >= 200 && response_code < 300) {
                    log_message(LOG_INFO, "Humidity posted successfully.");
                    curl_easy_cleanup(curl);
                    curl_global_cleanup();
                    return 0;
                } else {
                    log_message(LOG_ERR, "HTTP request failed with code: %ld", response_code);
                }
            } else {
                log_message(LOG_ERR, curl_easy_strerror(res));
            }

            retry++;
            if (retry < MAX_RETRIES) {
                sleep(BACKOFF_DELAY);
            }
        }

        log_message(LOG_ERR, "Failed to post humidity after %d retries.", MAX_RETRIES);
    } else {
        log_message(LOG_ERR, "Failed to initialize libcurl.");
    }

    curl_easy_cleanup(curl);
    curl_global_cleanup();
    return -1;
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
