#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define MAX_RETRIES 3

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_temperature();
int set_fan_speed(int speed);
int log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to read CPU temperature from file
int read_temperature() {
    FILE *fp;
    char buffer[10];
    int temperature = -1;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        fp = fopen(TEMP_FILE, "r");
        if (fp == NULL) {
            fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
            retries++;
            sleep(1); // Wait before retrying
            continue;
        }

        if (fgets(buffer, sizeof(buffer), fp) == NULL) {
            fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
            fclose(fp);
            retries++;
            sleep(1);
            continue;
        }

        fclose(fp);
        temperature = atoi(buffer) / 1000; // Convert millidegrees to degrees Celsius
        break; // Exit retry loop on success
    }

    if (temperature == -1) {
        fprintf(stderr, "Failed to read temperature after %d retries.\n", MAX_RETRIES);
        return -1; // Indicate failure
    }

    return temperature;
}

// Function to set fan speed using sysfs
int set_fan_speed(int speed) {
    FILE *fp;
    char state_str[2];

    // Validate the requested fan speed
    if (speed < 0 || speed > 3) {
        fprintf(stderr, "Invalid fan speed: %d. Must be between 0 and 3.\n", speed);
        return -1;
    }

    // Convert speed to string
    snprintf(state_str, sizeof(state_str), "%d", speed);

    fp = fopen(FAN_STATE_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening fan state file: %s\n", strerror(errno));
        return -1;
    }

    if (fputs(state_str, fp) == EOF) {
        fprintf(stderr, "Error writing fan state: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to log events to file
int log_event(const char *message) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
    return 0;
}

int main() {
    int current_speed = 0; // Initial fan speed (off)
    int temperature;
    int new_speed;

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        temperature = read_temperature();

        if (temperature == -1) {
            fprintf(stderr, "Failed to read temperature, using previous value.\n");
        } else {
            // Determine fan speed based on temperature
            if (temperature < 45) {
                new_speed = 0;
            } else if (temperature < 55) {
                new_speed = 1;
            } else if (temperature < 65) {
                new_speed = 2;
            } else {
                new_speed = 3;
            }

            // Check if fan speed needs to be changed
            if (new_speed != current_speed) {
                if (set_fan_speed(new_speed) == 0) {
                    current_speed = new_speed;
                    char log_message[50];
                    snprintf(log_message, sizeof(log_message), "Fan speed changed to %d", new_speed);
                    log_event(log_message);
                } else {
                    fprintf(stderr, "Failed to set fan speed.\n");
                }
            }
        }

        sleep(5);
    }

    // Shutdown sequence
    printf("Shutting down fan and exiting.\n");
    set_fan_speed(0); // Stop the fan
    log_event("Fan stopped.");

    return 0;
}

