#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_BAUD 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000000 // 100% duty cycle
#define TARGET_TEMPERATURE 50.0
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01
#define MAX_TEMPERATURE 100.0
#define MIN_TEMPERATURE 0.0
#define SAMPLE_INTERVAL_MS 100

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// PID variables
double integral = 0.0;
double previous_error = 0.0;

// Function prototypes
double read_temperature();
double pid_control(double current_temperature);
void set_pwm_duty_cycle(double duty_cycle);
void log_data(double temperature, double duty_cycle, double pid_output);
void signal_handler(int signal);

// Function to read temperature from MAX31855
double read_temperature() {
    char tx_buf[4] = {0, 0, 0, 0};
    char rx_buf[4];
    int result;

    result = spiXfer(spi_handle, tx_buf, rx_buf, 4);
    if (result != 4) {
        fprintf(log_file, "%ld, SPI read error: %d\n", time(NULL), result);
        fflush(log_file);
        return -1000.0; // Indicate error
    }

    // Check for fault bits
    if (rx_buf[3] & 0x01) {
        fprintf(log_file, "%ld, Thermocouple open circuit\n", time(NULL));
        fflush(log_file);
        return -1000.0; // Indicate error
    }
    if (rx_buf[3] & 0x02) {
        fprintf(log_file, "%ld, Thermocouple shorted to GND\n", time(NULL));
        fflush(log_file);
        return -1000.0; // Indicate error
    }
    if (rx_buf[3] & 0x04) {
        fprintf(log_file, "%ld, Thermocouple shorted to VCC\n", time(NULL));
        fflush(log_file);
        return -1000.0; // Indicate error
    }

    // Extract temperature data
    int16_t raw_temp = ((rx_buf[0] << 8) | rx_buf[1]) >> 2;
    double temperature = raw_temp * 0.25;

    return temperature;
}

// Function to implement PID control
double pid_control(double current_temperature) {
    double error = TARGET_TEMPERATURE - current_temperature;

    integral += error;
    double derivative = error - previous_error;

    double output = Kp * error + Ki * integral + Kd * derivative;

    previous_error = error;

    // Limit the output to 0-100% duty cycle
    if (output < 0.0) {
        output = 0.0;
    } else if (output > 100.0) {
        output = 100.0;
    }

    return output;
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(double duty_cycle) {
    int pwm_value = (int)(duty_cycle * PWM_RANGE);
    gpioPWM(HEATER_GPIO, pwm_value);
}

// Function to log data to file
void log_data(double temperature, double duty_cycle, double pid_output) {
    fprintf(log_file, "%ld, %.2f, %.2f, %.2f\n", time(NULL), temperature, duty_cycle, pid_output);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(log_file, "%ld, Received signal %d, shutting down...\n", time(NULL), signal);
    fflush(log_file);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set PWM frequency and range
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("heater_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "%ld, Program started\n", time(NULL));
    fflush(log_file);

    // Main loop
    while (!terminate) {
        double temperature = read_temperature();
        if (temperature < -999.0) {
            fprintf(log_file, "%ld, Error reading temperature, disabling heater\n", time(NULL));
            fflush(log_file);
            set_pwm_duty_cycle(0.0);
        } else {
            // PID control
            double duty_cycle = pid_control(temperature);

            // Set PWM duty cycle
            set_pwm_duty_cycle(duty_cycle);

            // Log data
            log_data(temperature, duty_cycle, duty_cycle);

            // Failsafe
            if (temperature > MAX_TEMPERATURE || temperature < MIN_TEMPERATURE) {
                fprintf(log_file, "%ld, Temperature out of range: %.2f, disabling heater\n", time(NULL), temperature);
                fflush(log_file);
                set_pwm_duty_cycle(0.0);
            }
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    fprintf(log_file, "%ld, Program shutting down\n", time(NULL));
    fflush(log_file);
    set_pwm_duty_cycle(0.0);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

