#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"
#define PWM_FREQUENCY 25000
#define PWM_RANGE 1000000 // 100% duty cycle = 1000000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("Received signal %d, shutting down...\n", sig);
}

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    int temp;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1; // Indicate error
    }

    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1; // Indicate error
    }

    fclose(fp);
    return temp / 1000; // Return temperature in degrees Celsius
}

// Function to calculate PWM duty cycle based on temperature
int calculate_duty_cycle(int temperature) {
    int duty_cycle;

    if (temperature <= 40) {
        duty_cycle = 0;
    } else if (temperature >= 70) {
        duty_cycle = 100;
    } else {
        duty_cycle = (int)(((float)(temperature - 40) / (70 - 40)) * 100);
    }

    return duty_cycle;
}

// Function to set PWM duty cycle
int set_pwm_duty_cycle(int gpio, int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;

    int pwm_value = (int)(((float)duty_cycle / 100.0) * PWM_RANGE);
    gpioPWM(gpio, pwm_value);
    return 0;
}

// Function to log data to CSV file
int log_data(int temperature, int duty_cycle) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1; // Indicate error
    }

    fprintf(fp, "%s,%d,%d\n", timestamp, temperature, duty_cycle);
    fclose(fp);
    return 0;
}

int main() {
    int temperature, duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin to output mode
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_PIN, PWM_RANGE);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read CPU temperature
        temperature = read_cpu_temp();
        if (temperature == -1) {
            fprintf(stderr, "Error reading temperature, using previous value or exiting.\n");
            // Consider exiting if temperature reading consistently fails
            continue; // Skip to the next iteration
        }

        // Calculate PWM duty cycle
        duty_cycle = calculate_duty_cycle(temperature);

        // Set PWM duty cycle
        if (set_pwm_duty_cycle(GPIO_PIN, duty_cycle) != 0) {
            fprintf(stderr, "Error setting PWM duty cycle\n");
        }

        // Log data
        if (log_data(temperature, duty_cycle) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Shutdown sequence
    printf("Shutting down fan and releasing resources...\n");
    set_pwm_duty_cycle(GPIO_PIN, 0); // Turn off fan
    gpioTerminate(); // Release pigpio resources

    printf("Fan control stopped.\n");
    return 0;
}

