#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Sensor I2C addresses
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09

// I2C bus
#define I2C_BUS 1

// Measurement command
#define MEASURE_CMD 0x3608

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables for I2C handles
int i2c_handle1 = -1;
int i2c_handle2 = -1;

// Function prototypes
int read_sensor(int i2c_handle, float *flow_rate);
int validate_crc(unsigned char data[], unsigned char crc);
void log_flow_rates(float flow1, float flow2);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    gpioTerminate();
    exit(0);
}

// Function to read flow rate from a sensor
int read_sensor(int i2c_handle, float *flow_rate) {
    unsigned char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    unsigned char data[3];
    int result;
    int retries = 3;

    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
        if (result == 0) break; // Success
        fprintf(stderr, "I2C write error (sensor %d): %d, retries left: %d\n", i2c_handle, result, retries);
        gpioDelay(10000); // 10ms delay
        retries--;
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to write to sensor %d after multiple retries.\n", i2c_handle);
        return -1;
    }

    gpioDelay(10000); // Wait for conversion (10ms)

    retries = 3;
    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, (char *)data, 3);
        if (result == 3) break; // Success
        fprintf(stderr, "I2C read error (sensor %d): %d, retries left: %d\n", i2c_handle, result, retries);
        gpioDelay(10000); // 10ms delay
        retries--;
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to read from sensor %d after multiple retries.\n", i2c_handle);
        return -1;
    }

    // Validate CRC
    if (!validate_crc(data, data[2])) {
        fprintf(stderr, "CRC validation failed for sensor %d.\n", i2c_handle);
        return -1;
    }

    // Convert raw value to flow rate
    int raw_value = (data[0] << 8) | data[1];
    *flow_rate = (float)raw_value * 0.01;

    return 0;
}

// Function to validate CRC-8 checksum
int validate_crc(unsigned char data[], unsigned char crc) {
    unsigned char crc_calculated = 0xFF;
    unsigned char data_to_crc[2] = {data[0], data[1]};

    for (int i = 0; i < 2; i++) {
        crc_calculated ^= data_to_crc[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc_calculated <<= 1;
            }
        }
    }

    return (crc_calculated == crc);
}

// Function to log flow rates to a file
void log_flow_rates(float flow1, float flow2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    FILE *fp = fopen("flow_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening flow_log.txt for writing.\n");
        return;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles for both sensors
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float flow_rate1, flow_rate2;

    // Main loop
    while (1) {
        if (read_sensor(i2c_handle1, &flow_rate1) == 0) {
            if (read_sensor(i2c_handle2, &flow_rate2) == 0) {
                log_flow_rates(flow_rate1, flow_rate2);
            } else {
                fprintf(stderr, "Failed to read from sensor 2.\n");
            }
        } else {
            fprintf(stderr, "Failed to read from sensor 1.\n");
        }

        gpioDelay(1000000); // 1 second delay
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioTerminate();
    return 0;
}

