// Define GPIO pins for the rotary encoder
#define ENCODER_A_PIN 17
#define ENCODER_B_PIN 18

// Define the number of pulses per revolution
#define PULSES_PER_REVOLUTION 360

// Define the quadrature state machine states
typedef enum {
    QUINTET_00,
    QUINTET_01,
    QUINTET_10,
    QUINTET_11,
    QUINTET_00_ERROR
} QuintetState;

// Global variables
static volatile int pulse_count = 0;
static volatile QuintetState current_state = QUINTET_00;
static FILE *log_file = NULL;
static int running = 1;

// Function prototypes
void encoder_callback(int gpio, int level, uint32_t tick, void *user_data);
void log_data(double angular_position);
void signal_handler(int signal);

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to log data to a file
void log_data(double angular_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, angular_position);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Callback function for encoder pulses
void encoder_callback(int gpio, int level, uint32_t tick, void *user_data) {
    static uint32_t last_tick = 0;
    uint32_t diff;

    if (last_tick != 0) {
        diff = tick - last_tick;
        if (diff > 1000) {
            // Debounce: Ignore pulses that are too far apart
            return;
        }
    }

    last_tick = tick;

    if (gpio == ENCODER_A_PIN) {
        if (level == 0) { // Falling edge
            // Determine the current state based on the state of ENCODER_B_PIN
            int b_level = gpioRead(ENCODER_B_PIN);
            switch (current_state) {
                case QUINTET_00:
                    if (b_level == 0) {
                        current_state = QUINTET_01;
                    } else {
                        current_state = QUINTET_10;
                    }
                    break;
                case QUINTET_01:
                    if (b_level == 0) {
                        current_state = QUINTET_11;
                    } else {
                        current_state = QUINTET_00;
                    }
                    break;
                case QUINTET_10:
                    if (b_level == 0) {
                        current_state = QUINTET_11;
                    } else {
                        current_state = QUINTET_00;
                    }
                    break;
                case QUINTET_11:
                    if (b_level == 0) {
                        current_state = QUINTET_01;
                    } else {
                        current_state = QUINTET_00;
                    }
                    break;
                case QUINTET_00_ERROR:
                    fprintf(stderr, "Error: Invalid encoder state.\n");
                    current_state = QUINTET_00; // Reset to a known state
                    break;
                default:
                    fprintf(stderr, "Error: Unknown encoder state.\n");
                    current_state = QUINTET_00; // Reset to a known state
                    break;
            }
        }
    }

    pulse_count++;

    // Calculate angular position (0.00 to 360.00 degrees)
    double angular_position = (double)pulse_count / PULSES_PER_REVOLUTION * 360.00;

    // Log the data
    log_data(angular_position);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(ENCODER_A_PIN, PI_INPUT);
    gpioSetMode(ENCODER_B_PIN, PI_INPUT);

    // Enable pull-up resistors
    gpioSetPullUpDown(ENCODER_A_PIN, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_PIN, PI_PUD_UP);

    // Open the log file
    log_file = fopen("encoder_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up the quadrature state machine
    current_state = QUINTET_00;

    // Set up the callback function
    gpioSetAlertFuncEx(ENCODER_A_PIN, encoder_callback, NULL);

    printf("Rotary encoder monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    // Clean up and exit
    gpioSetAlertFuncEx(ENCODER_A_PIN, NULL, NULL); // Disable callback
    fclose(log_file);
    gpioTerminate();

    printf("Rotary encoder monitoring stopped.\n");
    return 0;
}

