#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define ADPD144RI_ADDR 0x39
#define FIFO_REG 0x60
#define RED_REG 0x62
#define IR_REG 0x64
#define LED_GPIO 17
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_adpd144ri_data(int *red, int *ir);
int control_led(int state);
int log_data(int red, int ir);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, ADPD144RI_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_fd);
        return -1;
    }
    return 0;
}

// Read data from ADPD144RI sensor
int read_adpd144ri_data(int *red, int *ir) {
    char buf[2];
    int result;

    // Read Red channel
    result = i2cReadI2CBlockData(i2c_fd, RED_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading Red channel: %d\n", result);
        return -1;
    }
    *red = (buf[1] << 8) | buf[0];

    // Read IR channel
    result = i2cReadI2CBlockData(i2c_fd, IR_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading IR channel: %d\n", result);
        return -1;
    }
    *ir = (buf[1] << 8) | buf[0];

    return 0;
}

// Control the LED
int control_led(int state) {
    gpioWrite(LED_GPIO, state);
    return 0;
}

// Log data to file
int log_data(int red, int ir) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, red, ir);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    int red, ir;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("adpd144ri_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("ADPD144RI data acquisition started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        if (read_adpd144ri_data(&red, &ir) == 0) {
            log_data(red, ir);

            if (ir > IR_THRESHOLD) {
                control_led(1); // Turn LED on
            } else {
                control_led(0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 100 ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_led(0); // Turn off LED
    fclose(log_file);
    i2cClose(i2c_fd);
    gpioTerminate();

    return 0;
}

