#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL_SEC 1

static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the log file
FILE *open_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return NULL;
    }
    return log_file;
}

// Function to log RPM data
void log_rpm(double rpm) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f RPM\n", timestamp, rpm);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Interrupt service routine (ISR)
void isr_callback(int gpio, int level, uint32_t tick, void *user) {
    if (level == PI_HIGH) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

// Function to calculate RPM
double calculate_rpm(int pulses) {
    if (pulses == 0) {
        return 0.00;
    }
    return (double)pulses / SAMPLE_INTERVAL_SEC * 60.00;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = open_log_file();
    if (log_file == NULL) {
        gpioTerminate();
        return 1;
    }

    // Configure GPIO pin as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Register the ISR
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, isr_callback, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Wait for 1 second
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // pigpio uses microseconds

        // Calculate RPM
        int pulses = 0;
        pthread_mutex_lock(&pulse_mutex);
        pulses = pulse_count;
        pulse_count = 0; // Reset pulse count
        pthread_mutex_unlock(&pulse_mutex);

        double rpm = calculate_rpm(pulses);

        // Log RPM
        log_rpm(rpm);

        printf("RPM: %.2f\n", rpm);
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL); // Disable ISR
    fclose(log_file);
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

