        log_rpm(rpm);

        printf("RPM: %.2f\n", rpm);
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL); // Disable ISR
