#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADPD144RI_ADDR 0x39
#define PART_ID_REG 0x00
#define FIFO_REG_ADDR 0x01
#define FIFO_SIZE 64 // Example FIFO size
#define RED_DATA_REG_ADDR 0x02
#define IR_DATA_REG_ADDR 0x04
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_register(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_register(int fd, uint8_t reg, uint8_t data);
int read_adpd144ri_data(int fd, uint16_t *red, uint16_t *ir);
void control_led(int gpio_line, int value);
void log_data(FILE *fp, uint16_t red, uint16_t ir);
void signal_handler(int sig);
int init_gpio(const char *chipname, int pin);
int cleanup_gpio(struct gpiod_line *line);

// I2C read register function
int i2c_read_register(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

// I2C write register function
int i2c_write_register(int fd, uint8_t reg, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = data;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// Read ADPD144RI data
int read_adpd144ri_data(int fd, uint16_t *red, uint16_t *ir) {
    uint8_t buffer[4]; // 2 bytes for red, 2 bytes for IR

    if (i2c_read_register(fd, FIFO_REG_ADDR, buffer, 4) != 0) {
        fprintf(stderr, "Error reading FIFO data\n");
        return -1;
    }

    *red = (buffer[0] << 8) | buffer[1];
    *ir = (buffer[2] << 8) | buffer[3];

    return 0;
}

// Control LED
void control_led(int gpio_line, int value) {
    if (gpiod_line_set_value(gpio_line, value) < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", strerror(errno));
    }
}

// Log data to file
void log_data(FILE *fp, uint16_t red, uint16_t ir) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    time_t nowtime = tv.tv_sec;
    struct tm *nowtm = localtime(&nowtime);
    char tmbuf[64], buf[64];
    strftime(tmbuf, sizeof(tmbuf), "%Y-%m-%d %H:%M:%S", nowtm);
    snprintf(buf, sizeof(buf), "%s.%06ld", tmbuf, tv.tv_usec);

    fprintf(fp, "%s,%u,%u\n", buf, red, ir);
    fflush(fp);
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize GPIO
int init_gpio(const char *chipname, int pin) {
    gpio_chip = gpiod_chip_open_by_name(chipname);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, pin);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "adpd144ri_led";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Cleanup GPIO
int cleanup_gpio(struct gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    return 0;
}

int main() {
    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio(GPIO_CHIP, GPIO_PIN) != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        cleanup_gpio(NULL);
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        cleanup_gpio(NULL);
        return 1;
    }

    // Verify sensor presence
    uint8_t part_id;
    if (i2c_read_register(i2c_fd, PART_ID_REG, &part_id, 1) != 0) {
        fprintf(stderr, "Failed to read PART_ID, assuming sensor absent\n");
        close(i2c_fd);
        cleanup_gpio(NULL);
        return 1;
    }

    if (part_id != 0x44) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02x, expected 0x44\n", part_id);
        close(i2c_fd);
        cleanup_gpio(NULL);
        return 1;
    }

    // Open log file
    log_file = fopen("adpd144ri_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        cleanup_gpio(NULL);
        return 1;
    }

    // Main loop
    uint16_t red, ir;
    while (!terminate) {
        if (read_adpd144ri_data(i2c_fd, &red, &ir) == 0) {
            log_data(log_file, red, ir);

            if (ir > IR_THRESHOLD) {
                control_led(gpio_line, 1); // Turn LED on
            } else {
                control_led(gpio_line, 0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000); // Sleep for 100 ms
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);
    cleanup_gpio(gpio_line);
    gpiod_chip_close(gpio_chip);

    return 0;
}

