#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins
#define AUDIO_INPUT_PIN 17
#define GAIN_CONTROL_PIN 18

// Define sampling interval (10 ms)
#define SAMPLING_INTERVAL_NS 10000000

// Define log file name
#define LOG_FILE "audio_log.txt"

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *audio_line;
static struct gpiod_line *gain_line;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
int set_gain(int gain);
int sample_audio(void);
int log_event(const char *timestamp);
void cleanup(int signal);

// Signal handler
void cleanup(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;

    // Release GPIO resources
    if (audio_line) {
        gpiod_line_release(audio_line);
    }
    if (gain_line) {
        gpiod_line_release(gain_line);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    // Close chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Initialize GPIO pins
int initialize_gpio(void) {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get audio input line
    audio_line = gpiod_chip_get_line(chip, AUDIO_INPUT_PIN);
    if (!audio_line) {
        perror("Error getting audio input line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get gain control line
    gain_line = gpiod_chip_get_line(chip, GAIN_CONTROL_PIN);
    if (!gain_line) {
        perror("Error getting gain control line");
        gpiod_line_release(audio_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request audio input line as input
    if (gpiod_line_request_input(audio_line, "audio_input") < 0) {
        perror("Error requesting audio input line");
        gpiod_line_release(audio_line);
        gpiod_line_release(gain_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request gain control line as output
    if (gpiod_line_request_output(gain_line, "gain_control", 0) < 0) {
        perror("Error requesting gain control line");
        gpiod_line_release(audio_line);
        gpiod_line_release(gain_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Set gain control line LOW
    if (gpiod_line_set_value(gain_line, 0) < 0) {
        perror("Error setting gain control line LOW");
        gpiod_line_release(audio_line);
        gpiod_line_release(gain_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Set gain control pin
int set_gain(int gain) {
    if (gain != 0 && gain != 1) {
        fprintf(stderr, "Invalid gain value: %d.  Must be 0 or 1.\n", gain);
        return -1;
    }

    if (gpiod_line_set_value(gain_line, gain) < 0) {
        perror("Error setting gain control line");
        return -1;
    }

    return 0;
}

// Sample audio input
int sample_audio(void) {
    int value;
    struct timespec ts;

    // Read audio input value
    value = gpiod_line_get_value(audio_line);
    if (value < 0) {
        perror("Error reading audio input value");
        return -1;
    }

    // Get current timestamp
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("Error getting current timestamp");
        return -1;
    }

    // Log event
    if (log_event(ts.tv_sec, ts.tv_nsec) < 0) {
        fprintf(stderr, "Error logging event.\n");
        return -1;
    }

    return 0;
}

// Log event to file
int log_event(const char *timestamp, long long nanoseconds) {
    char buffer[64];
    struct tm *tm_info;

    // Format timestamp
    tm_info = localtime(&timestamp);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);
    snprintf(buffer + strlen(buffer), sizeof(buffer) - strlen(buffer), ".%09lld", nanoseconds);

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return -1;
    }

    // Write timestamp to log file
    fprintf(log_file, "%s LEVEL\n", buffer);

    // Close log file
    fclose(log_file);

    return 0;
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Audio sampling started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Sample audio
        if (sample_audio() < 0) {
            fprintf(stderr, "Audio sampling failed. Continuing...\n");
        }

        // Wait for the next sampling interval
        nanosleep((const struct timespec[]){{0, SAMPLING_INTERVAL_NS}}, NULL);
    }

    // Cleanup and exit
    cleanup(0);

    return 0;
}

