#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_PIN 17
#define POLL_INTERVAL_NS 100000000 // 100 ms
#define INTRUSION_THRESHOLD_S 5

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
}

int main() {
    struct timespec start_time, current_time;
    int ret;

    // Register signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line as input
    ret = gpiod_line_request_input(line, "ttp223_tamper");
    if (ret < 0) {
        perror("gpiod_line_request_input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Monitoring GPIO %d for tamper events...\n", GPIO_PIN);

    while (!terminate) {
        // Read GPIO value
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("gpiod_line_get_value");
            break; // Exit loop on error
        }

        // Check for tamper event (HIGH signal)
        if (value == 1) {
            clock_gettime(CLOCK_MONOTONIC, &start_time);
            printf("Tamper event detected!\n");
        }

        // Check for release (LOW signal)
        if (value == 0) {
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            double elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1e9;

            if (elapsed_time > INTRUSION_THRESHOLD_S) {
                printf("Intrusion alert: Tamper event duration exceeded threshold.\n");
            }
        }

        // Wait for the next poll interval
        ret = nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = POLL_INTERVAL_NS}, NULL);
        if (ret < 0) {
            perror("nanosleep");
            break; // Exit loop on error
        }
    }

    // Cleanup
    printf("Cleaning up and exiting...\n");
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

