            double elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1e9;

            if (elapsed_time > INTRUSION_THRESHOLD_S) {
                printf("Intrusion alert: Tamper event duration exceeded threshold.\n");
            }
        }

        // Wait for the next poll interval
        ret = nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = POLL_INTERVAL_NS}, NULL);
        if (ret < 0) {
            perror("nanosleep");
            break; // Exit loop on error
        }
    }

    // Cleanup
    printf("Cleaning up and exiting...\n");
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

