#include <gpiod.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define SAMPLE_RATE 44100
#define NUM_CHANNELS 1
#define FORMAT SND_PCM_FORMAT_S24_LE
#define PERIOD_SIZE 1024
#define FILENAME "audio_capture.pcm"

static volatile int keep_running = 1;
static snd_pcm_t *pcm_handle = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *fp = NULL;

void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully.\n");
    keep_running = 0;
}

int init_gpio() {
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "audio_capture";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

int set_gpio_value(int value) {
    int ret = gpiod_line_set_value(gpio_line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %d value: %s\n", GPIO_PIN, strerror(errno));
        return -1;
    }
    return 0;
}

int init_alsa() {
    snd_pcm_hw_params_t *hw_params;
    int err;

    if ((err = snd_pcm_open(&pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    if ((err = snd_pcm_hw_params_malloc(&hw_params)) < 0) {
        fprintf(stderr, "Error allocating hardware parameter structure: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_any(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting hardware parameter structure: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        snd_pcm_hw_params_free(hw_params);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access type: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        snd_pcm_hw_params_free(hw_params);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(pcm_handle, hw_params, FORMAT)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        snd_pcm_hw_params_free(hw_params);
        return -1;
    }

    unsigned int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        snd_pcm_hw_params_free(hw_params);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(pcm_handle, hw_params, NUM_CHANNELS)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        snd_pcm_hw_params_free(hw_params);
        return -1;
    }

    if ((err = snd_pcm_hw_params(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        snd_pcm_hw_params_free(hw_params);
        return -1;
    }

    snd_pcm_hw_params_free(hw_params);

    if ((err = snd_pcm_prepare(pcm_handle)) < 0) {
        fprintf(stderr, "Error preparing PCM device: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    return 0;
}

int main() {
    signal(SIGINT, signal_handler);

    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        return 1;
    }

    if (init_alsa() < 0) {
        fprintf(stderr, "ALSA initialization failed.\n");
        set_gpio_value(0); // Set GPIO low on exit
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    set_gpio_value(1); // Select left channel

    fp = fopen(FILENAME, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening file for writing: %s\n", strerror(errno));
        set_gpio_value(0); // Set GPIO low on exit
        snd_pcm_close(pcm_handle);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    char buffer[PERIOD_SIZE * 2]; // 2 bytes per 24-bit sample
    int bytes_read;

    while (keep_running) {
        bytes_read = snd_pcm_readi(pcm_handle, buffer, PERIOD_SIZE);
        if (bytes_read < 0) {
            fprintf(stderr, "Error reading PCM data: %s\n", snd_strerror(bytes_read));
            break;
        }

        // Convert 24-bit data to 16-bit PCM
        for (int i = 0; i < bytes_read; i += 2) {
            unsigned int raw_sample = ((unsigned int)buffer[i] << 8) | (unsigned int)buffer[i + 1];
            unsigned int pcm_sample = raw_sample >> 8; // Right-shift to get 16-bit PCM
            fwrite(&pcm_sample, 1, 1, fp);
        }

        fflush(fp); // Flush the buffer to ensure data is written to file
    }

    set_gpio_value(0); // Set GPIO low on exit
    snd_pcm_close(pcm_handle);
    fclose(fp);
    gpiod_chip_close(gpio_chip);

    return 0;
}

