#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18

// Define constants
#define PWM_FREQUENCY 100
#define DEBOUNCE_DELAY_MS 50
#define FLAME_DURATION_MAX_MS 5000 // Maximum flame duration to avoid infinite loop
#define LOG_FILE "flame_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
int control_fan(int flame_detected);
int log_event(const char *event_type, const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_PIN, 100); // Set PWM range to 100 for percentage control

    return 0;
}

// Function to read the flame sensor
int read_flame_sensor() {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value != 0 && value != 1) {
        fprintf(stderr, "Error: Invalid GPIO read value: %d\n", value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to control the fan
int control_fan(int flame_detected) {
    if (flame_detected == 0) { // Flame detected (LOW signal)
        // Exponential scaling: duty cycle = 100 * (1 - exp(-t/T))
        // where t is the flame duration in ms and T is a scaling constant (e.g., 1000 ms)
        int flame_duration = 0;
        int duty_cycle = 0;
        double t = 0;

        while (flame_detected == 0 && t < FLAME_DURATION_MAX_MS) {
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce
            flame_duration += DEBOUNCE_DELAY_MS;
            t++;
            duty_cycle = (int)(100.0 * (1.0 - exp(-(double)flame_duration / 1000.0)));
            if (duty_cycle > 100) duty_cycle = 100; // Ensure duty cycle is within bounds
            gpioPWM(FAN_PIN, duty_cycle);
        }

        if (flame_detected == 0) {
            gpioPWM(FAN_PIN, 0); // Turn off fan after max duration
        }
    } else {
        gpioPWM(FAN_PIN, 0); // Turn off fan if no flame is detected
    }
    return 0;
}

// Function to log events
int log_event(const char *event_type, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write to file
        return 0;
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
        return 1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioPWM(FAN_PIN, 0); // Turn off the fan
    gpioSetMode(FAN_PIN, PI_INPUT); // Set FAN_PIN to input mode
    gpioTerminate(); // Terminate pigpio

    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup(); // Exit if log file cannot be opened
        return 1;
    }

    log_event("System Start", "System started successfully.");

    int flame_detected = 1; // Assume no flame initially
    int last_flame_state = 1; // Initialize to no flame detected

    while (running) {
        int sensor_value = read_flame_sensor();

        if (sensor_value == -1) {
            log_event("Error", "Invalid GPIO read value.");
            gpioDelay(100 * 1000); // Wait 100ms before retrying
            continue;
        }

        if (sensor_value != last_flame_state) {
            if (sensor_value == 0) { // Flame detected
                log_event("Flame Detected", "Flame detected by sensor.");
                control_fan(0); // Turn on the fan
                flame_detected = 0; // Update flame state
            } else { // No flame detected
                log_event("Flame Ended", "Flame ended.");
                control_fan(1); // Turn off the fan
                flame_detected = 1; // Update flame state
            }
            last_flame_state = sensor_value;
        }

        gpioDelay(10 * 1000); // Check every 10ms
    }

    cleanup(); // Ensure resources are released before exiting
    return 0;
}

