    }

    gpioSetMode(TRIGGER_GPIO, PI_OUTPUT);
    gpioSetMode(DATA_READY_GPIO, PI_INPUT);
    gpioSetPullUpDown(DATA_READY_GPIO, PI_PUD_DOWN);

    return 0;
}

