    uint64_t timestamp;
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    timestamp = (uint64_t)ts.tv_sec * 1000000000ULL + (uint64_t)ts.tv_nsec;

    fwrite(magic_number, 1, 4, log_file);
    fwrite(&timestamp, 8, 1, log_file);
    fwrite(&config, sizeof(config_t), 1, log_file);

