#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 20
#define LOG_FILE "flame_log.txt"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the GPIO line
int init_gpio(struct gpiod_chip *chip, int pin) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "flame_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line %d\n", pin);
        return -1;
    }

    if (gpiod_line_request(line, &config, 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d\n", pin);
        return -1;
    }

    return 0;
}

// Function to read the flame sensor value
int read_flame_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error: Could not read GPIO line value\n");
        return -1;
    }
    return value;
}

// Function to log the flame event
int log_flame_event(const char *timestamp, const char *event) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s - %s\n", timestamp, event);
    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

// Function to get the current timestamp in ISO 8601 format
int get_iso8601_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *info;
    struct timespec ts;

    clock_gettime(CLOCK_REALTIME, &ts);
    time(&rawtime);
    info = gmtime(&rawtime);

    if (strftime(timestamp, 30, "%Y-%m-%dT%H:%M:%SZ", info) == 0) {
        fprintf(stderr, "Error: Could not format timestamp\n");
        return -1;
    }
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s\n", GPIO_CHIP);
        return EXIT_FAILURE;
    }

    // Initialize the GPIO line
    if (init_gpio(chip, GPIO_PIN) < 0) {
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    int previous_value = -1; // Initialize to an invalid value
    char timestamp[30];

    // Main loop
    while (!terminate) {
        int current_value = read_flame_sensor(line);
        if (current_value < 0) {
            fprintf(stderr, "Error reading sensor, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        if (current_value != previous_value) {
            if (get_iso8601_timestamp(timestamp) == 0) {
                if (current_value == 0) {
                    if (log_flame_event(timestamp, "Flame Detected") != 0) {
                        fprintf(stderr, "Error logging flame detected\n");
                    }
                } else {
                    if (log_flame_event(timestamp, "Flame Cleared") != 0) {
                        fprintf(stderr, "Error logging flame cleared\n");
                    }
                }
                previous_value = current_value;
            }
        }

        usleep(100000); // 100 milliseconds
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    if (log_file != NULL) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}

