#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_opt3001();
int read_opt3001(uint16_t *result);
float calculate_lux(uint16_t result);
void log_data(float lux);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the OPT3001 sensor
int init_opt3001() {
    int retries = RETRY_COUNT;
    while (retries > 0) {
        // Continuous conversion mode, auto range, 100ms conversion time
        uint16_t config_value = 0xCB01; // Continuous mode, auto range, 100ms conversion time
        char buf[3];
        buf[0] = CONFIG_REG;
        buf[1] = (config_value >> 8) & 0xFF; // MSB
        buf[2] = config_value & 0xFF;        // LSB

        if (i2cWriteDevice(i2c_handle, buf, 3) == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing to OPT3001 config register. Retrying...\n");
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        }
    }
    fprintf(stderr, "Failed to initialize OPT3001 after multiple retries.\n");
    return -1; // Failure
}

// Reads the 16-bit result from the OPT3001 sensor
int read_opt3001(uint16_t *result) {
    char buf[1];
    buf[0] = RESULT_REG;

    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to OPT3001 result register.\n");
        return -1;
    }

    char read_buf[2];
    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        fprintf(stderr, "Error reading from OPT3001 result register.\n");
        return -1;
    }

    *result = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

// Calculates the lux value from the raw sensor reading
float calculate_lux(uint16_t result) {
    int exponent = (result >> 12) & 0x0F;
    int mantissa = result & 0x0FFF;
    return 0.01 * (1 << exponent) * mantissa;
}

// Logs the lux value with an ISO-8601 timestamp to 'light_data.txt'
void log_data(float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    FILE *fp = fopen("light_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening light_data.txt for writing.\n");
        return;
    }

    fprintf(fp, "%s, %.2f\n", timestamp, lux);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize OPT3001 sensor
    if (init_opt3001() != 0) {
        fprintf(stderr, "OPT3001 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C and termination signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t result;
    float lux;

    // Main loop
    while (!terminate) {
        if (read_opt3001(&result) == 0) {
            lux = calculate_lux(result);
            log_data(lux);
        } else {
            fprintf(stderr, "Failed to read OPT3001 data.\n");
        }

        gpioDelay(500000); // 0.5 second delay
    }

    // Clean up and exit
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

