#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the sensor
#define LEFT_PIN 17
#define CENTER_PIN 18
#define RIGHT_PIN 27

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    if (gpioSetMode(LEFT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", LEFT_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(CENTER_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", CENTER_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RIGHT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", RIGHT_PIN);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop to read sensor values
    while (!terminate) {
        // Read sensor values
        int left_value = gpioRead(LEFT_PIN);
        int center_value = gpioRead(CENTER_PIN);
        int right_value = gpioRead(RIGHT_PIN);

        // Print sensor values to console
        printf("Left: %d, Center: %d, Right: %d\n", left_value, center_value, right_value);

        // Wait for 50 ms
        usleep(50000);
    }

    // Terminate pigpio library before exiting
    gpioTerminate();
    fprintf(stderr, "pigpio terminated\n");

    return 0;
}

