#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define the GPIO pins connected to the TTP226 channels
const int gpio_pins[] = {2, 3, 4, 5, 6, 7, 8, 9};
const int num_channels = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
    fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
}

int main()
{
    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for SIGINT
    signal(SIGINT, sigint_handler);

    // Configure the GPIO pins as inputs
    for (int i = 0; i < num_channels; i++)
    {
        if (gpioSetMode(gpio_pins[i], PI_INPUT) != 0)
        {
            fprintf(stderr, "Failed to set GPIO %d as input\n", gpio_pins[i]);
            gpioTerminate();
            return 1;
        }
    }

    // Main loop to read and log the sensor data
    while (!terminate)
    {
        // Read the state of each channel
        for (int i = 0; i < num_channels; i++)
        {
            int state = gpioRead(gpio_pins[i]);
            if (state < 0)
            {
                fprintf(stderr, "Failed to read GPIO %d\n", gpio_pins[i]);
                gpioTerminate();
                return 1;
            }

            // Log the state to the console
            printf("Channel %d: %d\n", i + 1, state);
        }

        // Wait for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();
    return 0;
}

