#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define the GPIO pins connected to the TTP226 channels
const int touch_pins[8] = {2, 3, 4, 5, 6, 7, 8, 9};

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int signal)
{
    printf("\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main()
{
    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure each GPIO pin as an input with a pull-down resistor
    for (int i = 0; i < 8; i++)
    {
        if (gpioSetMode(touch_pins[i], PI_INPUT) != 0)
        {
            fprintf(stderr, "Failed to set mode for GPIO %d\n", touch_pins[i]);
            gpioTerminate();
            return 1;
        }
        if (gpioSetPullUpDown(touch_pins[i], PI_PUD_DOWN) != 0)
        {
            fprintf(stderr, "Failed to set pull-down for GPIO %d\n", touch_pins[i]);
            gpioTerminate();
            return 1;
        }
    }

    // Set up signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main sampling loop
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);
    while (!terminate)
    {
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        long elapsed_ms = (current_time.tv_sec - start_time.tv_sec) * 1000 + (current_time.tv_nsec - start_time.tv_nsec) / 1000000;

        // Read the state of each touch sensor channel
        int sensor_states[8];
        for (int i = 0; i < 8; i++)
        {
            sensor_states[i] = gpioRead(touch_pins[i]);
        }

        // Print the sensor states with a timestamp
        printf("[+%ld ms] ", elapsed_ms);
        for (int i = 0; i < 8; i++)
        {
            printf("CH%d=%d ", i + 1, sensor_states[i]);
        }
        printf("\n");

        // Delay for 100 ms
        gpioDelay(100000);
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

