#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_PIN 4
#define SENSOR2_PIN 5

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nCtrl+C detected. Exiting gracefully...\n");
    }
}

// Function to read the state of a sensor
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to log the sensor states to the console
void log_sensor_states(int sensor1_state, int sensor2_state) {
    printf("Sensor 1: %s, Sensor 2: %s\n",
           sensor1_state == 0 ? "LOW" : "HIGH",
           sensor2_state == 0 ? "LOW" : "HIGH");
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as inputs
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);

    // Set pull-up resistors on the GPIO pins
    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read the states of the sensors
        int sensor1_state = read_sensor(SENSOR1_PIN);
        int sensor2_state = read_sensor(SENSOR2_PIN);

        // Log the sensor states
        log_sensor_states(sensor1_state, sensor2_state);

        // Wait for 500 ms
        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

