#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define GPIO_PIN 4
#define POLL_INTERVAL_MS 100

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

int main() {
    int current_state, previous_state = -1; // Initialize to an invalid state
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    int pigpio_init_result;

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pigpio_init_result);
        return 1;
    }

    // Configure GPIO 4 as an input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    printf("Tilt Sensor Monitoring Started (GPIO %d). Press Ctrl+C to exit.\n", GPIO_PIN);

    while (!terminate) {
        current_state = gpioRead(GPIO_PIN);

        if (current_state == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading GPIO %d\n", GPIO_PIN);
            gpioTerminate();
            return 1;
        }

        if (current_state != previous_state) {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            if (current_state == 0) {
                printf("%s - Tilted\n", timestamp);
            } else {
                printf("%s - Not Tilted\n", timestamp);
            }

            previous_state = current_state;
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Clean up and terminate pigpio
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

