#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define PART_ID_REG 0x00
#define PART_ID 0x45
#define HW_KEY_REG 0x17
#define HW_KEY_VALUE 0x17
#define CHLIST_REG 0x01
#define ALS_FORCE_CMD 0x06
#define ALS_VIS_REG 0x22
#define ALS_UV_REG 0x24
#define CSV_FILE "uv_als_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_si1145();
int read_si1145_data(float *uv_index, int *als_visible);
void log_data(float uv_index, int als_visible);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize Si1145 sensor
int init_si1145() {
    int result;

    // Verify PART ID
    result = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading PART ID: %d\n", result);
        return -1;
    }
    if (result != PART_ID) {
        fprintf(stderr, "Incorrect PART ID: 0x%02X (expected 0x%02X)\n", result, PART_ID);
        return -1;
    }

    // Write HW_KEY
    result = i2cWriteByteData(i2c_handle, HW_KEY_REG, HW_KEY_VALUE);
    if (result < 0) {
        fprintf(stderr, "Error writing HW_KEY: %d\n", result);
        return -1;
    }

    // Configure CHLIST (enable UV and ALS_VIS)
    result = i2cWriteByteData(i2c_handle, CHLIST_REG, 0x01); // Enable UV and ALS_VIS
    if (result < 0) {
        fprintf(stderr, "Error writing CHLIST: %d\n", result);
        return -1;
    }

    return 0;
}

// Read UV index and ALS data from Si1145
int read_si1145_data(float *uv_index, int *als_visible) {
    int result;
    unsigned char data[2];

    // Trigger measurement
    result = i2cWriteByteData(i2c_handle, ALS_FORCE_CMD, 0x00);
    if (result < 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (adjust as needed)
    gpioDelay(10); // 10 ms delay

    // Read ALS_VIS data
    result = i2cReadI2CBlockData(i2c_handle, ALS_VIS_REG, (char *)data, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading ALS_VIS data: %d\n", result);
        return -1;
    }
    *als_visible = (data[1] << 8) | data[0];

    // Read UV data
    result = i2cReadI2CBlockData(i2c_handle, ALS_UV_REG, (char *)data, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading UV data: %d\n", result);
        return -1;
    }
    *uv_index = (float)((data[1] << 8) | data[0]) / 100.0; // Scale UV index

    return 0;
}

// Log data to CSV file
void log_data(float uv_index, int als_visible) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, uv_index, als_visible);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    float uv_index;
    int als_visible;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize Si1145 sensor
    if (init_si1145() != 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,UV Index,ALS Visible\n");
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_si1145_data(&uv_index, &als_visible) == 0) {
            // Print data to console
            printf("UV Index: %.2f, ALS Visible: %d\n", uv_index, als_visible);

            // Log data to CSV file
            log_data(uv_index, als_visible);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Clean up resources
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

