#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define FLOW_SCALE_FACTOR 0.036
#define ALARM_THRESHOLD 0.5
#define ALARM_GPIO_CHIP "gpiochip0"
#define ALARM_GPIO_PIN 17
#define ALARM_DURATION_MS 500
#define MEASUREMENT_INTERVAL_S 1

// Sensor Addresses
#define SENSOR1_ADDR 0x36
#define SENSOR2_ADDR 0x37

// CRC Polynomial
#define CRC_POLYNOMIAL 0x31

// Global Variables
static int i2c_fd1 = -1;
static int i2c_fd2 = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *alarm_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int init_i2c(int address);
int start_measurement(int i2c_fd);
int read_sensor_data(int i2c_fd, uint8_t *data);
int validate_crc(const uint8_t *data, int len);
float convert_flow_rate(int16_t raw_flow);
float calculate_average_flow(float flow1, float flow2);
int control_alarm(float average_flow);
int log_data(float flow1, float flow2, float average_flow);
void signal_handler(int sig);
int cleanup();

// CRC Calculation Function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int init_i2c(int address) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Start Measurement
