#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_PIN 4
#define BUFFER_SIZE 100

// Structure to hold timestamp and sensor reading
typedef struct {
    char timestamp[30];
    int reading;
} SensorData;

// Circular buffer
SensorData buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0; // Number of elements in the buffer

// Function prototypes
int initialize_gpio();
int read_sensor();
void add_to_buffer(int reading);
void print_buffer();
void signal_handler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    printf("Obstacle detection program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sensor_value = read_sensor();

        if (sensor_value == 0) {
            add_to_buffer(sensor_value);
            printf("Obstacle detected!\n");
        }

        gpioDelay(50000); // 50 ms delay
    }

    // Cleanup and exit
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

// Initializes the pigpio library and configures the GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Reads the sensor value from the GPIO pin
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Adds a timestamp and sensor reading to the circular buffer
void add_to_buffer(int reading) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    strcpy(buffer[buffer_index].timestamp, timestamp);
    buffer[buffer_index].reading = reading;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

// Prints the contents of the circular buffer in chronological order
void print_buffer() {
    printf("\n--- Obstacle Detection Log ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int index = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE; // Calculate correct index
        printf("%s - Reading: %d\n", buffer[index].timestamp, buffer[index].reading);
    }
    printf("--- End of Log ---\n\n");
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Exiting...\n");
        program_running = 0;
        print_buffer(); // Print the buffer before exiting
        gpioTerminate(); // Release pigpio resources
        exit(0);
    }
}

