#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define I2C_DEVICE_ADDRESS 0x55
#define MODE_CONTROL_REGISTER 0x1D
#define OPERATING_STATUS_REGISTER 0x1B
#define ACCELERATION_X_LSB 0x2A
#define ACCELERATION_X_MSB 0x2B
#define ACCELERATION_Y_LSB 0x2C
#define ACCELERATION_Y_MSB 0x2D
#define ACCELERATION_Z_LSB 0x2E
#define ACCELERATION_Z_MSB 0x2F
#define SAMPLE_INTERVAL_MS 500
#define MODE_CONTROL_VALUE 0x10
#define OPERATING_STATUS_BIT 0
#define RETRY_COUNT 3

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int init_d7s_sensor(int fd);
int read_acceleration_data(int fd, int16_t *x, int16_t *y, int16_t *z);
float convert_to_g(int16_t raw_value);
int log_data(FILE *fp, float x, float y, float z);
void signal_handler(int signal);

// I2C write function with retry
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    int retries = RETRY_COUNT;
    while (retries > 0) {
        if (write(fd, buf, 2) == 2) {
            return 0; // Success
        }
        perror("I2C write failed");
        retries--;
        usleep(10000); // 10ms delay
    }
    fprintf(stderr, "I2C write failed after multiple retries.\n");
    return -1; // Failure
}

// I2C read function with retry
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    int retries = RETRY_COUNT;
    while (retries > 0) {
        if (write(fd, &reg, 1) == 1) {
            if (read(fd, data, len) == len) {
                return 0; // Success
            }
            perror("I2C read failed");
            retries--;
            usleep(10000); // 10ms delay
        }
        retries--;
        usleep(10000); // 10ms delay
    }
    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1; // Failure
}

// Initialize D7S sensor
int init_d7s_sensor(int fd) {
    if (i2c_write_byte(fd, MODE_CONTROL_REGISTER, MODE_CONTROL_VALUE) != 0) {
        fprintf(stderr, "Failed to set MODE_CONTROL register.\n");
        return -1;
    }
    usleep(100000); // Wait for mode change (100ms)
    return 0;
}

// Read acceleration data
int read_acceleration_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    if (i2c_read_bytes(fd, ACCELERATION_X_LSB, data, 6) != 0) {
