#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define STALL_DURATION_MS 2000
#define LOG_FILE "stall_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to handle signals (Ctrl+C, termination)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to read sensor value with validation
int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value != 0 && value != 1) {
        fprintf(stderr, "Error: Invalid sensor reading from GPIO %d\n", gpio);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log stall event with timestamp
int log_stall_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Stall detected!\n", timestamp);
        fflush(log_file); // Ensure immediate write to file
        return 0; // Success
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1; // Failure
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int stall_detected = 0;
    time_t stall_start_time = 0;

    printf("Conveyor belt monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        if (sensor1_value == -1 || sensor2_value == -1) {
            // Error reading sensor, continue to next iteration
            gpioDelay(100); // Small delay to avoid busy-waiting
            continue;
        }

        if (sensor1_value == 0 && sensor2_value == 0) {
            if (!stall_detected) {
                stall_detected = 1;
                stall_start_time = time(NULL);
            } else {
                time_t current_time = time(NULL);
                if (difftime(current_time, stall_start_time) >= STALL_DURATION_MS / 1000.0) {
                    if (log_stall_event() == 0) {
                        printf("Stall logged.\n");
                    } else {
                        fprintf(stderr, "Error logging stall event.\n");
                    }
                    stall_detected = 0; // Reset stall detection
                }
            }
        } else {
            stall_detected = 0; // Reset stall detection if either sensor is clear
        }

        gpioDelay(100); // Check every 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

