#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 23
#define LOG_FILE "flood_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get the current timestamp in the specified format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log an event to the log file
void log_event(const char *message) {
    char *timestamp = get_timestamp();
    if (log_file != NULL) {
        fprintf(log_file, "%s %s\n", timestamp, message);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to handle the water detection event
void handle_water_detection() {
    char *timestamp = get_timestamp();
    printf("ALERT: Water detected at %s\n", timestamp);
    log_event("ALERT: Water detected");
}

// Function to handle the pigpio initialization failure
void handle_pigpio_init_failure() {
    char *timestamp = get_timestamp();
    fprintf(stderr, "%s pigpio initialization failed. Attempting to re-initialize...\n", timestamp);
    log_event("pigpio initialization failed. Attempting to re-initialize...");
    gpioTerminate();
    if (gpioInitialise() < 0) {
        fprintf(stderr, "%s pigpio re-initialization failed. Exiting.\n", timestamp);
        log_event("pigpio re-initialization failed. Exiting.");
        exit(1);
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
    log_event("Caught signal, exiting gracefully...");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        handle_pigpio_init_failure();
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN); // Use pull-down resistor

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");
    log_event("Water level monitoring started");

    // Main loop
    while (running) {
        int level = gpioRead(GPIO_PIN);
        if (level < 0) {
            char *timestamp = get_timestamp();
            fprintf(stderr, "%s Error reading GPIO level. Attempting to re-initialize pigpio...\n", timestamp);
            log_event("Error reading GPIO level. Attempting to re-initialize pigpio...");
            gpioTerminate();
            if (gpioInitialise() < 0) {
                fprintf(stderr, "%s pigpio re-initialization failed. Exiting.\n", timestamp);
                log_event("pigpio re-initialization failed. Exiting.");
                fclose(log_file);
                gpioTerminate();
                return 1;
            }
            continue; // Skip to the next iteration after re-initialization attempt
        }

        if (level == 1) {
            handle_water_detection();
        }

        sleep(2);
    }

    // Clean up resources
    printf("Cleaning up resources...\n");
    log_event("Cleaning up resources...");
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

