#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define SAMPLE_INTERVAL_SEC 1
#define SAMPLE_INTERVAL_NS SAMPLE_INTERVAL_SEC * 1000000000L

volatile int pulse_count = 0;
FILE *log_file = NULL;

// Function to get the current timestamp in YYYY-MM-DD HH:MM:SS format
void get_timestamp(char *timestamp)
{
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

// Function to log the RPM to a file
void log_rpm(int rpm)
{
    char timestamp[20];
    get_timestamp(timestamp);

    if (log_file != NULL)
    {
        fprintf(log_file, "%s %d\n", timestamp, rpm);
        fflush(log_file); // Ensure data is written to disk immediately
    }
    else
    {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to print the RPM to stdout
void print_rpm(int rpm)
{
    char timestamp[20];
    get_timestamp(timestamp);
    printf("%s RPM: %d\n", timestamp, rpm);
}

// Callback function for GPIO interrupts
void pulse_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    pulse_count++;
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    (void)signal; // unused
    printf("Caught signal, exiting gracefully.\n");

    // Disable the timer and alert callback
    gpioSetTimerFuncEx(0, 0, NULL, NULL);

    // Close the log file
    if (log_file != NULL)
    {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Open the log file
    log_file = fopen("rpm_log.txt", "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for Ctrl+C and termination signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up the timer callback function
    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_NS, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Error setting timer function!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1)
    {
        // Wait for the timer to trigger
        gpioDelay(SAMPLE_INTERVAL_NS);

        // Disable the timer callback
        gpioSetTimerFuncEx(0, 0, NULL, NULL);

        // Calculate RPM
        int rpm = (pulse_count * 60);

        // Log the RPM
        log_rpm(rpm);

        // Print the RPM
        print_rpm(rpm);

        // Reset the pulse count
        pulse_count = 0;

        // Re-enable the timer callback
        gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_NS, pulse_callback, NULL);
    }

    return 0;
}

