// Define the quadrature state enumeration
typedef enum {
    QSTATE_IDLE,
    QSTATE_A_RISING,
    QSTATE_A_FALLING,
    QSTATE_B_RISING,
    QSTATE_B_FALLING
} QuadratureState;

// Global variable to store the current quadrature state
QuadratureState current_state = QSTATE_IDLE;

// Function prototypes
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user_data);
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user_data);
