#define LED_PIN 18

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void control_led(int state);
void log_event(const char *message);
void signal_handler(int signal);

int main() {
    // Open syslog for logging
    openlog("touch_led_app", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio library.");
        closelog();
        return 1;
    }

    log_event("Application started.");

    // Main loop
    while (program_running) {
        // Read the touch sensor
        int touch_detected = read_touch_sensor();

        // Control the LED based on the touch sensor state
        control_led(touch_detected);

        // Small delay to avoid busy-waiting
        gpioDelay(50000); // 50 ms
    }

    // Cleanup and exit
    log_event("Application shutting down.");
    gpioTerminate();
    closelog();
    return 0;
}

