    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);

    // Configure the LED pin as an output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Ensure LED is off initially
    control_led(0);

    return 0;
}

