#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <errno.h>
#include <string.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18

// Debounce time in microseconds
#define DEBOUNCE_TIME 5000

// Number of pulses per revolution
#define PULSES_PER_REVOLUTION 2

// Global variables
volatile int running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio);
double calculate_rpm(int pulses);
void log_data(int sensor1_state, int sensor2_state);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int sensor1_state;
    int sensor2_state;
} sensor_data_t;

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("shaft_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s. Exiting.\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    sensor_data_t sensor_data;
    int sensor1_state_prev = 0;
    int sensor2_state_prev = 0;
    int sensor1_pulses = 0;
    int sensor2_pulses = 0;
    struct timespec start_time, current_time;
    double elapsed_time;

    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (running) {
        // Read sensor states
        sensor_data.sensor1_state = read_sensor(SENSOR1_GPIO);
        sensor_data.sensor2_state = read_sensor(SENSOR2_GPIO);

        // Debounce and count pulses
        if (sensor_data.sensor1_state != sensor1_state_prev) {
            gpioDelay(DEBOUNCE_TIME);
            sensor1_state_prev = sensor_data.sensor1_state;
            if (sensor_data.sensor1_state != sensor1_state_prev) {
                sensor1_pulses++;
            }
        }

        if (sensor_data.sensor2_state != sensor2_state_prev) {
            gpioDelay(DEBOUNCE_TIME);
            sensor2_state_prev = sensor_data.sensor2_state;
            if (sensor_data.sensor2_state != sensor2_state_prev) {
                sensor2_pulses++;
            }
        }

        // Calculate RPM every second
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1000000000.0;
        if (elapsed_time >= 1.0) {
            double rpm = calculate_rpm(sensor1_pulses + sensor2_pulses);
            printf("RPM: %.2f\n", rpm);

            // Log data to file
            log_data(sensor_data.sensor1_state, sensor_data.sensor2_state);

            // Reset pulse counters
            sensor1_pulses = 0;
            sensor2_pulses = 0;
            clock_gettime(CLOCK_MONOTONIC, &start_time);
        }

        gpioDelay(100); // Small delay to reduce CPU usage
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    return 0;
}

// Read sensor state with debounce
int read_sensor(int gpio) {
    int state = gpioRead(gpio);
    gpioDelay(DEBOUNCE_TIME);
    return state;
}

// Calculate RPM
double calculate_rpm(int pulses) {
    return (double)pulses * 60.0 / PULSES_PER_REVOLUTION;
}

// Log data to CSV file
void log_data(int sensor1_state, int sensor2_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("Ctrl+C pressed. Exiting...\n");
}

// Cleanup resources
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

