    if (i2cReadI2CBlockData(i2c_handle, SPO2_REG, spo2_data, 2) != 2) {
        fprintf(stderr, "Error reading SpO2 data\n");
        return -1;
    }

    return (spo2_data[0] << 8) | spo2_data[1];
