// Define GPIO pins
#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define ALARM_GPIO 27

// Define alarm duration (in seconds)
#define ALARM_DURATION 5

// Define tilt threshold (seconds)
#define TILT_THRESHOLD 2

// Global variables
FILE *log_file = NULL;
int alarm_active = 0;

// Function prototypes
int read_sensor(int gpio);
void activate_alarm();
void deactivate_alarm();
void log_event(const char *event_type, int sensor_number);
void signal_handler(int signal);

// Function to read sensor value
int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to activate the alarm
void activate_alarm() {
    if (!alarm_active) {
        gpioWrite(ALARM_GPIO, 1); // Set GPIO HIGH
        alarm_active = 1;
        printf("Alarm activated!\n");
    }
}

// Function to deactivate the alarm
void deactivate_alarm() {
    if (alarm_active) {
        gpioWrite(ALARM_GPIO, 0); // Set GPIO LOW
        alarm_active = 0;
        printf("Alarm deactivated!\n");
    }
}

// Function to log events to a file
void log_event(const char *event_type, int sensor_number) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Sensor %d: %s\n", timestamp, sensor_number, event_type);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    deactivate_alarm(); // Ensure alarm is off
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);

    // Enable pull-down resistors
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_DOWN);

    // Open log file
    log_file = fopen("bridge_integrity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate(); // Terminate pigpio before exiting
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int sensor1_count = 0;
    int sensor2_count = 0;

    // Main loop
    while (1) {
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        if (sensor1_value < 0 || sensor2_value < 0) {
            fprintf(stderr, "Error reading sensors, exiting.\n");
            break;
        }

        if (sensor1_value == 1) {
            sensor1_count++;
            if (sensor1_count >= TILT_THRESHOLD) {
                log_event("threshold_exceeded", 1);
                activate_alarm();
            }
        } else {
            sensor1_count = 0;
        }

        if (sensor2_value == 1) {
            sensor2_count++;
            if (sensor2_count >= TILT_THRESHOLD) {
                log_event("threshold_exceeded", 2);
                activate_alarm();
            }
        } else {
            sensor2_count = 0;
        }

        if (sensor1_count == 0 && sensor2_count == 0) {
            deactivate_alarm();
        }

        gpioDelay(100); // Poll every 100 ms
    }

    // Clean up (should not reach here under normal circumstances due to signal handler)
    deactivate_alarm();
    fclose(log_file);
    gpioTerminate();

    return 0;
}

