// Define GPIO pins
#define SENSOR_1 4
#define SENSOR_2 17
#define SENSOR_3 27
#define SENSOR_4 22
#define LED_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(SENSOR_1, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR_1\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR_2, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR_2\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR_3, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR_3\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR_4, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR_4\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for LED_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor values
        int sensor1_value = gpioRead(SENSOR_1);
        int sensor2_value = gpioRead(SENSOR_2);
        int sensor3_value = gpioRead(SENSOR_3);
        int sensor4_value = gpioRead(SENSOR_4);

        // Check if any sensor detects an object
        if (sensor1_value == 0 || sensor2_value == 0 || sensor3_value == 0 || sensor4_value == 0) {
            // Turn on the LED
            gpioWrite(LED_PIN, 1);
        } else {
            // Turn off the LED
            gpioWrite(LED_PIN, 0);
        }

        // Delay for 50 ms
        gpioDelay(50000); // 50 ms = 50000 microseconds
    }

    // Clean up and terminate
    gpioWrite(LED_PIN, 0); // Ensure LED is off before exiting
    gpioTerminate();
    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

