#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define the GPIO chip and line numbers
#define GPIOCHIP "gpiochip0"
#define NUM_SENSORS 8

// Define the GPIO pins for each sensor
const int sensor_pins[NUM_SENSORS] = {5, 6, 13, 19, 26, 12, 16, 20};

// Global variables
struct gpiod_chip *chip;
struct gpiod_line *lines[NUM_SENSORS];
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
int read_sensor_state(int sensor_index, int *current_state, int *previous_state);
void log_state_change(int sensor_index, int pin, int state);
void cleanup(void);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to initialize the GPIO chip and lines
int initialize_gpio(void) {
    int i;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIOCHIP, strerror(errno));
        return -1;
    }

    // Get the line resources for each sensor
    for (i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line %d: %s\n", sensor_pins[i], strerror(errno));
            cleanup();
            return -1;
        }

        // Request the line for input
        if (gpiod_line_request_input(lines[i], "touch_sensor_" + (char)('0' + i)) < 0) {
            fprintf(stderr, "Error requesting line %d for input: %s\n", sensor_pins[i], strerror(errno));
            cleanup();
            return -1;
        }
    }

    return 0;
}

// Function to read the state of a sensor
int read_sensor_state(int sensor_index, int *current_state, int *previous_state) {
    int value;

    value = gpiod_line_get_value(lines[sensor_index]);
    if (value < 0) {
        fprintf(stderr, "Error reading line %d: %s\n", sensor_pins[sensor_index], strerror(errno));
        return -1;
    }

    *current_state = value;

    // Detect state change
    if (*current_state != *previous_state) {
        *previous_state = *current_state;
        return 0; // State changed
    }

    return -1; // No state change
}

// Function to log a state change
void log_state_change(int sensor_index, int pin, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s - Sensor %d (Pin %d): %s\n", timestamp, sensor_index, pin, state ? "Touched" : "Released");
}

// Function to cleanup GPIO resources
void cleanup(void) {
    int i;

    // Release the GPIO lines
    for (i = 0; i < NUM_SENSORS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    int i, current_state, previous_state;

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        for (i = 0; i < NUM_SENSORS; i++) {
            if (read_sensor_state(i, &current_state, &previous_state) == 0) {
                log_state_change(i, sensor_pins[i], current_state);
            }
        }

        // Delay for 50 milliseconds
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 50000000; // 50 milliseconds
        nanosleep(&delay, NULL);
    }

    // Cleanup and exit
    cleanup();
    printf("Touch sensor monitoring stopped.\n");
    return 0;
}

