#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x10
#define CONFIG_REG 0x00
#define ALS_DATA_REG 0x04
#define GPIO_LED 18
#define PWM_FREQ 1000
#define PWM_RANGE 100
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int config_veml7700();
int read_veml7700(unsigned int *lux);
int set_led_brightness(int brightness);
int log_data(int lux, int brightness, int error_code);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure VEML7700
int config_veml7700() {
    char buf[2];
    buf[0] = (0x00 << 4) | 0x00; // ALS gain 1/8, ALS integration time 100ms
    buf[1] = 0x00;

    int result = i2cWriteI2CBlockData(i2c_handle, CONFIG_REG, buf, 2);
    if (result < 0) {
        fprintf(stderr, "VEML7700 config write failed: %d\n", result);
        return -1;
    }
    return 0;
}

// Read VEML7700 data
int read_veml7700(unsigned int *lux) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, ALS_DATA_REG, buf, 2);
    if (result < 0) {
        fprintf(stderr, "VEML7700 read failed: %d\n", result);
        return -1;
    }

    *lux = (buf[1] << 8) | buf[0];
    return 0;
}

// Set LED brightness using PWM
int set_led_brightness(int brightness) {
    gpioSetPWMfrequency(GPIO_LED, PWM_FREQ);
    gpioSetPWMrange(GPIO_LED, PWM_RANGE);
    gpioPWM(GPIO_LED, brightness);
    return 0;
}

// Log data to file
int log_data(int lux, int brightness, int error_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, Lux: %u, Brightness: %d, Error: %d\n", timestamp, lux, brightness, error_code);
    fflush(log_file);
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure VEML7700
    if (config_veml7700() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        unsigned int raw_lux;
        int error_code = 0;

        // Read lux value
        if (read_veml7700(&raw_lux) != 0) {
            error_code = -1; // Sensor read error
        }

        // Calculate lux
        float lux = (float)raw_lux * 0.0576;

        // Determine brightness
        int brightness = 0;
        if (lux < 100) {
            brightness = 100;
        } else if (lux < 500) {
