#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for touch sensors and LED
#define NUM_CHANNELS 8
const int touch_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};
const int led_pin = 17;

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_touch_sensors(int *sensor_states);
int log_touch_event(int channel);
int control_led(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    running = 0;
    control_led(0); // Turn off LED
    gpioTerminate(); // Release pigpio resources
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure touch sensor pins as inputs with pull-down resistors
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpioSetMode(touch_pins[i], PI_INPUT);
        gpioSetPullUpDown(touch_pins[i], PI_PUD_DOWN);
    }

    // Configure LED pin as output
    gpioSetMode(led_pin, PI_OUTPUT);
    control_led(0); // Ensure LED is off initially

    return 0;
}

// Read touch sensor states with debouncing
int read_touch_sensors(int *sensor_states) {
    int current_states[NUM_CHANNELS];
    for (int i = 0; i < NUM_CHANNELS; i++) {
        current_states[i] = gpioRead(touch_pins[i]);
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (current_states[i] != sensor_states[i]) {
            gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
            current_states[i] = gpioRead(touch_pins[i]);
            if (current_states[i] != sensor_states[i]) {
                sensor_states[i] = current_states[i];
            }
        }
    }

    return 0;
}

// Log touch event to file
int log_touch_event(int channel) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }

    fprintf(log_file, "%s - Channel %d Touched\n", timestamp, channel);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Control LED state
int control_led(int state) {
    gpioWrite(led_pin, state);
    return 0;
}

int main() {
    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate(); // Release pigpio resources
        return 1;
    }

    int sensor_states[NUM_CHANNELS] = {0}; // Initialize all channels to untouched
    int previous_sensor_states[NUM_CHANNELS] = {0};

    printf("Security Keypad Simulation started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_touch_sensors(sensor_states) == 0) {
            for (int i = 0; i < NUM_CHANNELS; i++) {
                if (sensor_states[i] == 1 && previous_sensor_states[i] == 0) {
                    log_touch_event(i + 1);
                    control_led(1); // Turn on LED
                } else if (sensor_states[i] == 0 && previous_sensor_states[i] == 1) {
                    control_led(0); // Turn off LED if all channels are released
                }
            }
            memcpy(previous_sensor_states, sensor_states, sizeof(sensor_states));
        }
        gpioDelay(50000); // Poll every 50 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_file);
    gpioTerminate();
    return 0;
}

