    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the OPT3001 sensor
int config_opt3001() {
    char buf[2];
    buf[0] = CONFIG_REG;
    buf[1] = (CONFIG_WORD >> 8) & 0xFF; // MSB
    if (i2cWriteWordData(i2c_handle, buf[0], buf[1]) < 0) {
        fprintf(stderr, "Error writing to config register (MSB): %d\n", i2c_handle);
        return -1;
    }
    buf[0] = CONFIG_REG + 1;
    buf[1] = CONFIG_WORD & 0xFF; // LSB
    if (i2cWriteWordData(i2c_handle, buf[0], buf[1]) < 0) {
        fprintf(stderr, "Error writing to config register (LSB): %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read the OPT3001 result register and convert to lux
int read_opt3001(float *lux) {
    char buf[2];
    char result_buf[2];
    int raw_result;

    // Read the result register
    buf[0] = RESULT_REG;
    if (i2cWriteWordData(i2c_handle, buf[0], 0) < 0) {
        fprintf(stderr, "Error writing to result register: %d\n", i2c_handle);
        return -1;
    }
    result_buf[0] = i2cReadByteData(i2c_handle, RESULT_REG);
    result_buf[1] = i2cReadByteData(i2c_handle, RESULT_REG + 1);

    // Byte swap the result
    raw_result = (result_buf[0] << 8) | result_buf[1];

    // Extract exponent and mantissa
    int exponent = (raw_result >> 12) & 0x0F;
    int mantissa = raw_result & 0x0FFF;

    // Calculate lux
    *lux = (float)mantissa * 0.01 * (2.0 * (1 << exponent));

    return 0;
}

