#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 4
#define DEBOUNCE_DELAY_NS 50000000 // 50 ms

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to get current timestamp in YYYY-MM-DD HH:MM:SS format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log touch event to file
int log_touch_event(const char *event_type) {
    char *timestamp = get_timestamp();
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s: %s\n", timestamp, event_type) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to release GPIO resources
void cleanup() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    int ret;
    struct timespec delay = {0, DEBOUNCE_DELAY_NS};

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    // Request GPIO line as input with pull-down bias
    ret = gpiod_line_request_input(line, "touch_sensor");
    if (ret < 0) {
        perror("Error requesting GPIO line as input");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(stderr, "Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("Error reading GPIO line value");
            break;
        }

        if (value == 0) { // Touch released
            if (log_touch_event("Touch Released") != 0) {
                fprintf(stderr, "Error logging touch released event.\n");
                break;
            }
        } else { // Touch detected
            if (log_touch_event("Touch Detected") != 0) {
                fprintf(stderr, "Error logging touch detected event.\n");
                break;
            }
        }

        nanosleep(&delay, NULL);
    }

    // Cleanup and exit
    cleanup();
    fprintf(stderr, "Touch sensor monitoring stopped.\n");
    return EXIT_SUCCESS;
}

