#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x08
#define MEASURE_COMMAND 0x3608
#define SAMPLE_INTERVAL_SEC 1
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define FLOW_CONVERSION_FACTOR 90.0
#define MIN_FLOW_RATE 0.0
#define MAX_FLOW_RATE 100.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_flow_sensor(int *raw_flow);
float convert_to_ml_min(int raw_flow);
int validate_crc(unsigned char data[], int len);
int log_data(float flow_rate, int raw_flow, int status);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the I2C connection
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Reads the flow sensor data
int read_flow_sensor(int *raw_flow) {
    char command[2] = {MEASURE_COMMAND >> 8, MEASURE_COMMAND & 0xFF};
    char buffer[3];
    int result;

    result = i2cWriteDevice(i2c_handle, command, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(2); // Wait at least 2 ms

    result = i2cReadDevice(i2c_handle, buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    *raw_flow = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Converts the raw flow value to ml/min
float convert_to_ml_min(int raw_flow) {
    return (float)raw_flow / FLOW_CONVERSION_FACTOR;
}

// Validates the CRC checksum
int validate_crc(unsigned char data[], int len) {
    unsigned char crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == data[len]);
}

// Logs the data to a CSV file
int log_data(float flow_rate, int raw_flow, int status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen("cooling_log.csv", "w");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file!\n");
            return -1;
        }
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, flow_rate, status);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    int raw_flow;
    float flow_rate;
    int status = 0; // 0: OK, 1: ERROR, 2: INVALID

    while (!terminate) {
        // Read flow sensor data
        if (read_flow_sensor(&raw_flow) == 0) {
            // Validate CRC
            if (validate_crc((unsigned char *)&raw_flow, sizeof(raw_flow))) {
                // Convert to ml/min
                flow_rate = convert_to_ml_min(raw_flow);

                // Validate flow rate
                if (flow_rate >= MIN_FLOW_RATE && flow_rate <= MAX_FLOW_RATE) {
                    status = 0; // OK
                } else {
                    status = 2; // INVALID
                }
            } else {
                status = 1; // ERROR
            }
        } else {
            status = 1; // ERROR
        }

        // Log the data
        if (log_data(flow_rate, raw_flow, status) != 0) {
            fprintf(stderr, "Error logging data!\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    i2cClose(i2c_handle);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

