#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 4
#define GPIO_LINE 0 // Line 0 on GPIO4
#define GPIO_DIRECTION_IN "in"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

int main() {
    struct timespec ts;
    char timestamp[30];
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for input
    ret = gpiod_line_request_input(line, GPIO_DIRECTION_IN);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for input: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    printf("Flame sensor monitoring started on GPIO%d (line %d). Press Ctrl+C to exit.\n", GPIO_PIN, GPIO_LINE);

    // Main loop
    while (!terminate) {
        // Read GPIO line value
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line value: %s\n", strerror(errno));
            break; // Exit loop on error
        }

        // Check for falling edge (flame detected)
        if (value == 0) {
            // Get timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                struct tm tm_info;
                localtime_r(&ts.tv_sec, &tm_info);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
                snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ld", ts.tv_nsec);
            } else {
                fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
                break;
            }

            // Print alert
            printf("Flame detected at %s\n", timestamp);

            // Log event to file
            FILE *fp = fopen("flame_events.txt", "a");
            if (fp) {
                fprintf(fp, "%s\n", timestamp);
                fclose(fp);
            } else {
                fprintf(stderr, "Error opening flame_events.txt for writing: %s\n", strerror(errno));
            }
        }

        // Small delay to avoid busy-waiting
        usleep(10000); // 10ms
    }

    // Release GPIO line and close chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Flame sensor monitoring stopped.\n");

    return 0;
}

