#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip4"
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 24

static struct gpiod_chip *chip;
static struct gpiod_line *touch_line;
static struct gpiod_line *led_line;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function to get the current timestamp in ISO-8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log the touch event with timestamp and LED state
void log_touch_event(int led_state) {
    char* timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp for logging.\n");
        return;
    }

    fprintf(log_file, "%s, LED State: %s\n", timestamp, led_state ? "ON" : "OFF");
    fflush(log_file); // Ensure the log is written immediately
    free(timestamp);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Function to toggle the LED state
int toggle_led(struct gpiod_line *led_line) {
    int current_value = gpiod_line_get_value(led_line);
    if (current_value < 0) {
        fprintf(stderr, "Error reading LED value: %s\n", strerror(errno));
        return -1;
    }

    int new_value = !current_value;
    if (gpiod_line_set_value(led_line, new_value) < 0) {
        fprintf(stderr, "Error writing LED value: %s\n", strerror(errno));
        return -1;
    }

    return new_value;
}

// Callback function for touch sensor events
void touch_callback(struct gpiod_line *line, int value, int event) {
    if (event == GPIOD_EVENT_RISING_EDGE) {
        int led_state = toggle_led(led_line);
        if (led_state < 0) {
            fprintf(stderr, "Error toggling LED.\n");
        }
        log_touch_event(led_state);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    // Request the touch sensor pin as an input
    touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (!touch_line) {
        fprintf(stderr, "Error getting touch sensor line %d: %s\n", TOUCH_SENSOR_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(touch_line, "touch_sensor") < 0) {
        fprintf(stderr, "Error requesting touch sensor line %d as input: %s\n", TOUCH_SENSOR_PIN, strerror(errno));
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the LED pin as an output
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting LED line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        fprintf(stderr, "Error requesting LED line %d as output: %s\n", LED_PIN, strerror(errno));
        gpiod_line_release(touch_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpiod_line_release(touch_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up event handling for the touch sensor line
    struct gpiod_line_event_consumer consumer;
    memset(&consumer, 0, sizeof(consumer));
    consumer.consumer = touch_callback;
    consumer.user_data = NULL;

    if (gpiod_line_event_consumer_add(touch_line, &consumer, 1, 1) < 0) {
        fprintf(stderr, "Error adding event consumer for touch sensor line %d: %s\n", TOUCH_SENSOR_PIN, strerror(errno));
        fclose(log_file);
        gpiod_line_release(touch_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        sleep(1);
    }

    // Cleanup
    printf("Cleaning up...\n");

    // Release GPIO resources
    gpiod_line_event_consumer_remove(touch_line, &consumer);
    gpiod_line_release(touch_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    // Close the log file
    fclose(log_file);

    printf("Exiting.\n");
    return 0;
}

