#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LOG_FILE "alert_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *flame_line;
static struct gpiod_line *buzzer_line;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    printf("Signal received, shutting down...\n");
}

// Function to initialize GPIO lines
int init_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_line) {
        fprintf(stderr, "Error getting flame sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Error getting buzzer line: %s\n", strerror(errno));
        gpiod_line_release(flame_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(flame_line, "flame_sensor") < 0) {
        fprintf(stderr, "Error requesting flame sensor line as input: %s\n", strerror(errno));
        gpiod_line_release(buzzer_line);
        gpiod_line_release(flame_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Error requesting buzzer line as output: %s\n", strerror(errno));
        gpiod_line_release(buzzer_line);
        gpiod_line_release(flame_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to read the flame sensor value
int read_flame_sensor() {
    int value = gpiod_line_get_value(flame_line);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Function to activate the buzzer for 2 seconds
void activate_buzzer() {
    if (gpiod_line_set_value(buzzer_line, 1) < 0) {
        fprintf(stderr, "Error setting buzzer value: %s\n", strerror(errno));
        return;
    }
    sleep(2);
    if (gpiod_line_set_value(buzzer_line, 0) < 0) {
        fprintf(stderr, "Error setting buzzer value: %s\n", strerror(errno));
    }
}

// Function to log the flame detection event
void log_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s: Flame detected!\n", timestamp);
    fflush(log_file); // Ensure the log is written immediately
}

// Function to release GPIO resources
void cleanup_gpio() {
    if (flame_line) {
        gpiod_line_release(flame_line);
    }
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Function to log the system start
void log_system_start() {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    fprintf(log_file, "System started\n");
    fclose(log_file);
}

// Function to log the system stop
void log_system_stop() {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    fprintf(log_file, "System stopped\n");
    fclose(log_file);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Log system start
    log_system_start();

    int previous_flame_state = 1; // Assume no flame initially (HIGH)

    // Main loop
    while (!terminate) {
        int flame_state = read_flame_sensor();
        if (flame_state < 0) {
            fprintf(stderr, "Error reading flame sensor, exiting.\n");
            break;
        }

        if (flame_state == 0 && previous_flame_state == 1) {
            log_event();
            activate_buzzer();
        }

        previous_flame_state = flame_state;
        usleep(100000); // 100 ms delay
    }

    // Cleanup GPIO resources
    cleanup_gpio();

    // Log system stop
    log_system_stop();

    return 0;
}

