#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TOUCH_SENSOR_GPIO 4
#define LED_GPIO 17
#define DEBOUNCE_DELAY_MS 200

static volatile int running = 1;
static volatile unsigned long last_touch_time = 0;

void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    FILE *log_file = NULL;
    int touch_state, led_state = 0;
    unsigned long current_time;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d to input\n", TOUCH_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d to output\n", LED_GPIO);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch sensor and LED control started. Press Ctrl+C to exit.\n");

    while (running) {
        current_time = gpioTick();
        touch_state = gpioRead(TOUCH_SENSOR_GPIO);

        if (touch_state == 1) {
            if (current_time - last_touch_time > DEBOUNCE_DELAY_MS * 1000) {
                led_state = !led_state;
                gpioWrite(LED_GPIO, led_state);

                // Get current timestamp
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[30];

                time(&rawtime);
                timeinfo = gmtime(&rawtime); // Use gmtime for UTC

                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

                // Log the event
                fprintf(log_file, "%s - Touch detected, LED toggled to %d\n", timestamp, led_state);
                fflush(log_file); // Ensure immediate write to file

                last_touch_time = current_time;
            }
        }

        gpioDelay(10); // Poll every 10 ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(LED_GPIO, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

