#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27

// Global variables for sensor states and log file
int sensor1_state = -1; // Initialize to an invalid state
int sensor2_state = -1;
int sensor3_state = -1;
FILE *log_file = NULL;

// Function prototypes
int read_sensor(int gpio_pin);
void log_state_change(int sensor_id, int state);
void signal_handler(int signal);

// Function to read the state of a sensor
int read_sensor(int gpio_pin) {
    int state = gpioRead(gpio_pin);
    if (state < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d: %d\n", gpio_pin, state);
        return -1; // Indicate an error
    }
    return state;
}

// Function to log a state change to a file
void log_state_change(int sensor_id, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,Sensor%d,%d\n", timestamp, sensor_id, state);
        fflush(log_file); // Ensure the data is written to the file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close the log file if it's open
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR1_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR2_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR2_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SENSOR3_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR3_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR3_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR3_PIN);
        gpioTerminate();
        return 1;
    }

    // Open the log file for appending
    log_file = fopen("magnet_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop to poll the sensors
    while (1) {
        // Read the state of each sensor
        int new_sensor1_state = read_sensor(SENSOR1_PIN);
        int new_sensor2_state = read_sensor(SENSOR2_PIN);
        int new_sensor3_state = read_sensor(SENSOR3_PIN);

        // Check for errors during sensor reading
        if (new_sensor1_state == -1 || new_sensor2_state == -1 || new_sensor3_state == -1) {
            // Handle the error, but continue the loop
            gpioDelay(100); // Wait 100ms before the next attempt
            continue;
        }

        // Log state changes for sensor 1
        if (sensor1_state == -1) {
            sensor1_state = new_sensor1_state;
        } else if (sensor1_state != new_sensor1_state) {
            log_state_change(1, new_sensor1_state);
            sensor1_state = new_sensor1_state;
        }

        // Log state changes for sensor 2
        if (sensor2_state == -1) {
            sensor2_state = new_sensor2_state;
        } else if (sensor2_state != new_sensor2_state) {
            log_state_change(2, new_sensor2_state);
            sensor2_state = new_sensor2_state;
        }

        // Log state changes for sensor 3
        if (sensor3_state == -1) {
            sensor3_state = new_sensor3_state;
        } else if (sensor3_state != new_sensor3_state) {
            log_state_change(3, new_sensor3_state);
            sensor3_state = new_sensor3_state;
        }

        // Wait 100ms before the next poll
        gpioDelay(100);
    }

    // The program should never reach here due to the infinite loop,
    // but the following lines are included for completeness.
    fclose(log_file);
    gpioTerminate();
    return 0;
}

