// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x4A
#define PART_ID_REG 0x00
#define HW_REV_REG 0x01
#define LED_CURRENT_REG 0x02
#define AVERAGING_REG 0x03
#define ENABLE_REG 0x04
#define HEART_RATE_REG 0x2A
#define RETRY_COUNT 3
#define MOVING_AVG_SIZE 5
#define MIN_BPM 30
#define MAX_BPM 220

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor configuration
typedef struct {
    int led_current;
    int averaging;
    int enable;
} sensor_config_t;

// Function prototypes
int initialize_sensor(int i2c_handle);
int read_heart_rate(int i2c_handle);
float convert_to_bpm(int raw_value);
float apply_moving_average(float bpm_values[], int size);
int validate_bpm(float bpm);
int log_data(float bpm);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the sensor
int initialize_sensor(int i2c_handle) {
    int status;
    sensor_config_t config = {0x3F, 0x04, 0x01};

    // Verify PART_ID
    status = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (status < 0) {
        fprintf(stderr, "Error reading PART_ID register: %d\n", status);
        return -1;
    }
    if (status != 0x02) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X\n", status);
        return -1;
    }

    // Verify HW_REV
    status = i2cReadByteData(i2c_handle, HW_REV_REG);
    if (status < 0) {
        fprintf(stderr, "Error reading HW_REV register: %d\n", status);
        return -1;
    }
    if (status != 0x01) {
        fprintf(stderr, "Incorrect HW_REV: 0x%02X\n", status);
        return -1;
    }

    // Configure the sensor
    status = i2cWriteByteData(i2c_handle, LED_CURRENT_REG, config.led_current);
    if (status < 0) {
        fprintf(stderr, "Error writing LED current register: %d\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, AVERAGING_REG, config.averaging);
    if (status < 0) {
        fprintf(stderr, "Error writing averaging register: %d\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, ENABLE_REG, config.enable);
    if (status < 0) {
        fprintf(stderr, "Error writing enable register: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read heart rate data
int read_heart_rate(int i2c_handle) {
    int raw_value;
    int status;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        status = i2cReadWordData(i2c_handle, HEART_RATE_REG);
        if (status >= 0) {
            raw_value = status;
            return raw_value;
        } else {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", retries + 1, status);
            retries++;
            gpioDelay(10000); // 10ms delay
        }
    }

    fprintf(stderr, "Failed to read heart rate after %d retries.\n", RETRY_COUNT);
    return -1; // Indicate failure
}

// Function to convert raw value to BPM
float convert_to_bpm(int raw_value) {
    return (float)raw_value * 0.5;
}

// Function to apply a moving average filter
float apply_moving_average(float bpm_values[], int size) {
    float sum = 0.0;
    for (int i = 0; i < size; i++) {
        sum += bpm_values[i];
    }
    return sum / size;
}

// Function to validate BPM value
int validate_bpm(float bpm) {
    return (bpm >= MIN_BPM && bpm <= MAX_BPM);
}

