    int status;
    int raw_heart_rate;
    float bpm;
    float bpm_values[MOVING_AVG_SIZE] = {0.0}; // Initialize to 0
    int value_index = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read heart rate
        raw_heart_rate = read_heart_rate(i2c_handle);
        if (raw_heart_rate >= 0) {
            // Convert to BPM
            bpm = convert_to_bpm(raw_heart_rate);

            // Apply moving average
            bpm_values[value_index] = bpm;
            value_index = (value_index + 1) % MOVING_AVG_SIZE;
            float filtered_bpm = apply_moving_average(bpm_values, MOVING_AVG_SIZE);

            // Validate BPM
            if (validate_bpm(filtered_bpm)) {
                // Log data
                log_data(filtered_bpm);
