            } else {
                fprintf(stderr, "Invalid BPM value: %.2f\n", filtered_bpm);
            }
        } else {
            fprintf(stderr, "Failed to read heart rate\n");
        }

        gpioDelay(1000000); // 1 second delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

