#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define LOG_FILE "flame_log.txt"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to get the current timestamp in YYYY-MM-DD HH:MM:SS format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log the flame detection event with timestamp
int log_flame_detection(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s: FLAME DETECTED\n", timestamp);
    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the GPIO line
int initialize_gpio(struct gpiod_chip *chip, int pin) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "flame_sensor";

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line %d: %s\n", pin, strerror(errno));
        return -1;
    }

    if (gpiod_line_request(line, &config, 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d: %s\n", pin, strerror(errno));
        gpiod_line_release(line);
        line = NULL;
        return -1;
    }

    if (gpiod_line_get_value(line) != 0) {
        fprintf(stderr, "Error: GPIO line %d is not high (initial value is %d)\n", pin, gpiod_line_get_value(line));
        gpiod_line_release(line);
        line = NULL;
        return -1;
    }

    return 0;
}

// Function to cleanup the GPIO line
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    struct timespec delay = {0, 100000000}; // 100 ms
    int prev_value = 1; // Assume initially no flame (HIGH)
    int current_value;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    // Initialize the GPIO line
    if (initialize_gpio(chip, GPIO_PIN) < 0) {
        cleanup_gpio(chip, line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup_gpio(chip, line);
        gpiod_chip_close(chip);
        return 1;
    }

    fprintf(stderr, "Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        current_value = gpiod_line_get_value(line);
        if (current_value < 0) {
            fprintf(stderr, "Error: Could not read GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
            break; // Exit loop on error
        }

        if (current_value < prev_value) {
            // Falling edge detected (flame detected)
            char *timestamp = get_timestamp();
            printf("FLAME DETECTED\n");
            if (log_flame_detection(timestamp) < 0) {
                fprintf(stderr, "Error: Could not log flame detection.\n");
            }
            prev_value = current_value; // Update previous value to current value
        }

        nanosleep(&delay, NULL);
    }

    // Cleanup
    cleanup_gpio(chip, line);
    if (log_file) {
        fclose(log_file);
    }
    gpiod_chip_close(chip);

    fprintf(stderr, "Exiting.\n");
    return 0;
}

