#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/time.h>
#include <gpiod.h>

// Define GPIO pins for TTP226 channels and display
const int ttp226_pins[] = {5, 6, 7, 8, 9, 10, 11, 12};
const int display_pins[] = {17, 24, 25, 26, 27, 22, 23, 21};
const int num_channels = 8;

// Global variables
struct gpiod_chip *chip;
struct gpiod_line *lines[num_channels];
struct gpiod_line *display_lines[8];
int counter = 0;
int touch_log_fd = -1;
int log_file_open_error = 0;

// Function prototypes
int initialize_gpio(void);
int read_ttp226_channel(int channel);
int update_display(int counter);
int log_touch_event(int channel, int counter);
void signal_handler(int sig);
void cleanup(void);

// Helper function to get current timestamp
void get_timestamp(char *timestamp)
{
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, 26, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
}

int main()
{
    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        for (int i = 0; i < num_channels; i++) {
            int touch = read_ttp226_channel(i);
            if (touch == 1) {
                counter++;
                if (counter > 255) {
                    counter = 0;
                }

                update_display(counter);
                log_touch_event(i + 1, counter);
                printf("Touch on channel %d | Counter: %d\n", i + 1, counter);

                // Debounce: Wait for a short period to avoid multiple counts
                usleep(200000); // 200 ms
            }
        }
        usleep(10000); // 10 ms delay
    }

    return 0;
}

int initialize_gpio(void)
{
    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Request TTP226 channels as inputs
    for (int i = 0; i < num_channels; i++) {
        lines[i] = gpiod_chip_get_line(chip, ttp226_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line %d: %s\n", ttp226_pins[i], strerror(errno));
            cleanup();
            return 1;
        }

        if (gpiod_line_request_input_pull_up(lines[i], "ttp226_channel") < 0) {
            fprintf(stderr, "Error requesting line %d as input: %s\n", ttp226_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
    }

    // Request display channels as outputs
    for (int i = 0; i < 8; i++) {
        display_lines[i] = gpiod_chip_get_line(chip, display_pins[i]);
        if (!display_lines[i]) {
            fprintf(stderr, "Error getting line %d: %s\n", display_pins[i], strerror(errno));
            cleanup();
            return 1;
        }

        if (gpiod_line_request_output(display_lines[i], "display_channel", 0) < 0) {
            fprintf(stderr, "Error requesting line %d as output: %s\n", display_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
    }

    // Wait for lines to stabilize
    usleep(200000); // 200 ms

    return 0;
}

int read_ttp226_channel(int channel)
{
    int value = -1;
    if (channel >= 0 && channel < num_channels) {
        value = gpiod_line_get_value(lines[channel]);
        if (value < 0) {
            fprintf(stderr, "Error reading line %d: %s\n", ttp226_pins[channel], strerror(errno));
            return -1; // Indicate error
        }
    }
    return value;
}

int update_display(int counter)
{
    for (int i = 0; i < 8; i++) {
        int bit = (counter >> i) & 1;
        if (gpiod_line_set_value(display_lines[i], bit) < 0) {
            fprintf(stderr, "Error setting line %d: %s\n", display_pins[i], strerror(errno));
        }
    }
    return 0;
}

int log_touch_event(int channel, int counter)
{
    char timestamp[26];
    get_timestamp(timestamp);

    if (touch_log_fd == -1) {
        fprintf(stderr, "Log file not opened. Using stderr.\n");
        fprintf(stderr, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter);
        return 1; // Logged to stderr
    }

    if (fprintf(touch_log_fd, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return 1; // Logged to stderr
    }
    fflush(touch_log_fd);
    return 0;
}

void signal_handler(int sig)
{
    printf("Caught signal %d. Cleaning up and exiting.\n", sig);
    cleanup();
    exit(0);
}

void cleanup(void)
{
    // Reset output pins to 0
    for (int i = 0; i < 8; i++) {
        gpiod_line_set_value(display_lines[i], 0);
    }

    // Release GPIO lines
    for (int i = 0; i < num_channels; i++) {
        gpiod_line_release(lines[i]);
    }

    // Close chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (touch_log_fd != -1) {
        fclose(touch_log_fd);
    }
}

