#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22

// Define the log file name
#define LOG_FILE "tracking_log.csv"

// Define the polling interval in milliseconds
#define POLLING_INTERVAL_MS 100

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;

// Structure to hold GPIO line information
struct gpio_line {
    struct gpiod_line *line;
    int pin;
};

// Function prototypes
int initialize_gpio(struct gpio_line *lines, int num_lines);
int read_sensor(struct gpio_line *lines, int num_lines, int *sensor_values);
int log_data(const char *timestamp, int sensor1, int sensor2, int sensor3, int sensor4, FILE *fp);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        terminate = 1;
        fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    }
}

// Function to initialize the GPIO lines
int initialize_gpio(struct gpio_line *lines, int num_lines) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int i;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Initialize the GPIO lines
    for (i = 0; i < num_lines; i++) {
        line = gpiod_chip_get_line(chip, lines[i].pin);
        if (!line) {
            fprintf(stderr, "Error getting GPIO line %d: %s\n", lines[i].pin, strerror(errno));
            gpiod_chip_close(chip);
            return -1;
        }

        lines[i].line = line;

        // Request the line as an input
        if (gpiod_line_request_input(line, "tracking_sensor") < 0) {
            fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", lines[i].pin, strerror(errno));
            gpiod_chip_close(chip);
            return -1;
        }
    }

    // Close the GPIO chip
    gpiod_chip_close(chip);
    return 0;
}

// Function to read the sensor values
int read_sensor(struct gpio_line *lines, int num_lines, int *sensor_values) {
    int i;

    for (i = 0; i < num_lines; i++) {
        int value = gpiod_line_get_value(lines[i].line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line %d: %s\n", lines[i].pin, strerror(errno));
            return -1;
        }
        sensor_values[i] = value;
    }
    return 0;
}

// Function to log the data to a CSV file
int log_data(const char *timestamp, int sensor1, int sensor2, int sensor3, int sensor4, FILE *fp) {
    if (fprintf(fp, "%s,%d,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3, sensor4) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    struct gpio_line lines[4];
    int sensor_values[4];
    FILE *fp;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    int init_result;

    // Initialize the sensor pins
    lines[0].pin = SENSOR1_PIN;
    lines[1].pin = SENSOR2_PIN;
    lines[2].pin = SENSOR3_PIN;
    lines[3].pin = SENSOR4_PIN;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the GPIO lines
    init_result = initialize_gpio(lines, 4);
    if (init_result != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open the log file
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        // Attempt to cleanup GPIO lines before exiting
        for (int i = 0; i < 4; i++) {
            if (lines[i].line) {
                gpiod_line_release(lines[i].line);
            }
        }
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,sensor1,sensor2,sensor3,sensor4\n");
        fflush(fp);
    }

    // Main loop
    while (!terminate) {
        // Read the sensor values
        if (read_sensor(lines, 4, sensor_values) == 0) {
            // Get the current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log the data
            if (log_data(timestamp, sensor_values[0], sensor_values[1], sensor_values[2], sensor_values[3], fp) != 0) {
                fprintf(stderr, "Error logging data. Continuing.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensors. Continuing.\n");
        }

        // Wait for the next polling interval
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = POLLING_INTERVAL_MS * 1000000; // Convert milliseconds to nanoseconds
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    printf("Cleaning up and exiting...\n");
    fclose(fp);
    for (int i = 0; i < 4; i++) {
        if (lines[i].line) {
            gpiod_line_release(lines[i].line);
        }
    }

    return 0;
}

