        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for input
    if (gpiod_line_request_input(sensor1_line, "sensor1") < 0) {
        fprintf(stderr, "Error requesting sensor1 line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_input(sensor2_line, "sensor2") < 0) {
        fprintf(stderr, "Error requesting sensor2 line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        fprintf(stderr, "Error requesting LED line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor values
        int sensor1_value = read_sensor(sensor1_line);
        int sensor2_value = read_sensor(sensor2_line);

        if (sensor1_value < 0 || sensor2_value < 0) {
            fprintf(stderr, "Error reading sensor values, exiting...\n");
            break;
        }

        // Control LED
        int led_state = 0;
        if (sensor1_value == 0 && sensor2_value == 0) {
            led_state = 1;
            if (control_led(led_line, led_state) < 0) {
                fprintf(stderr, "Error controlling LED, exiting...\n");
                break;
            }
        } else {
            led_state = 0;
            if (control_led(led_line, led_state) < 0) {
                fprintf(stderr, "Error controlling LED, exiting...\n");
                break;
            }
        }

        // Log data
        if (log_data(log_file, sensor1_value, sensor2_value, led_state) < 0) {
            fprintf(stderr, "Error logging data, exiting...\n");
            break;
        }

        // Wait 100 ms
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 100 * 1000 * 1000; // 100 ms
        nanosleep(&delay, NULL);
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (led_line) {
        control_led(led_line, 0); // Turn off LED
    }
    if (sensor1_line) {
        gpiod_line_release(sensor1_line);
    }
    if (sensor2_line) {
        gpiod_line_release(sensor2_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }

    printf("Exiting.\n");
    return 0;
}

