#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define MIC_PIN 4
#define LED_PIN 17

// Define sampling rate (Hz)
#define SAMPLING_RATE 8000

// Define LED on time (ms)
#define LED_ON_TIME 100

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_mic();
void control_led(int on);
void handle_sound_peak();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(MIC_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0; // Indicate success
}

// Read microphone input
int read_mic() {
    return gpioRead(MIC_PIN);
}

// Control LED state
void control_led(int on) {
    gpioWrite(LED_PIN, on);
}

// Handle sound peak detection
void handle_sound_peak() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    printf("%ld.%09ld: Sound peak detected!\n", ts.tv_sec, ts.tv_nsec);
    control_led(1); // Turn LED on
    gpioDelay(LED_ON_TIME * 1000); // Delay for 100 ms
    control_led(0); // Turn LED off
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Microphone sound peak detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        if (read_mic() == 1) {
            handle_sound_peak();
        }
        gpioDelay(1000 / SAMPLING_RATE); // Delay to achieve approximately 8 kHz sampling rate
    }

    // Clean up and exit
    gpioTerminate();
    printf("pigpio terminated.\n");
    return 0;
}

