void handle_sound_peak() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    printf("%ld.%09ld: Sound peak detected!\n", ts.tv_sec, ts.tv_nsec);
    control_led(1); // Turn LED on
    gpioDelay(LED_ON_TIME * 1000); // Delay for 100 ms
    control_led(0); // Turn LED off
}

