    // Main loop
    while (program_running) {
        if (read_mic() == 1) {
            handle_sound_peak();
        }
        gpioDelay(1000 / SAMPLING_RATE); // Delay to achieve approximately 8 kHz sampling rate
    }

    // Clean up and exit
    gpioTerminate();
    printf("pigpio terminated.\n");
    return 0;
}

