#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1175_ADDR 0x49
#define ALS_LSB_REG 0x24
#define ALS_MSB_REG 0x25

int i2c_fd;

void signal_handler(int sig);
int i2c_init(void);
int i2c_read_reg(int reg);
int i2c_write_reg(int reg, int val);
int read_als_data(void);

int main(void) {
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100 * 1000 * 1000; // 100 ms

    signal(SIGINT, signal_handler);

    if (i2c_init() < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    while (1) {
        int als_data = read_als_data();
        if (als_data >= 0) {
            printf("ALS Data: %d\n", als_data);
        } else {
            fprintf(stderr, "Failed to read ALS data.\n");
        }
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

int i2c_init(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int i2c_read_reg(int reg) {
    int val = i2c_smbus_read_byte_data(i2c_fd, reg);
    if (val < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, val);
        return -1;
    }
    return val;
}

int i2c_write_reg(int reg, int val) {
    int result = i2c_smbus_write_byte_data(i2c_fd, reg, val);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

int read_als_data(void) {
    int als_lsb = i2c_read_reg(ALS_LSB_REG);
    if (als_lsb < 0) {
        return -1;
    }

    int als_msb = i2c_read_reg(ALS_MSB_REG);
    if (als_msb < 0) {
        return -1;
    }

    return (als_msb << 8) | als_lsb;
}

void signal_handler(int sig) {
    printf("Ctrl+C pressed. Cleaning up and exiting.\n");
    close(i2c_fd);
    exit(0);
}

