#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins for the 8 channels
const int gpio_pins[] = {5, 6, 13, 19, 26, 12, 16, 20};
const int num_channels = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

// Global variables for GPIO chip and lines
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[8];

// Function prototypes
int initialize_gpio(void);
int read_sensor_data(int *sensor_data);
void log_sensor_data(int *sensor_data);
void cleanup_gpio(int signal);

// Signal handler for graceful shutdown
void cleanup_gpio(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Release GPIO lines
    for (int i = 0; i < num_channels; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }

    // Release GPIO chip
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Initializes the GPIO chip and requests the lines
int initialize_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    for (int i = 0; i < num_channels; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line %d: %s\n", gpio_pins[i], strerror(errno));
            // Attempt to release previously acquired lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return -1;
        }

        if (gpiod_line_request_input(lines[i], "sensor_input") < 0) {
            fprintf(stderr, "Error requesting line %d as input: %s\n", gpio_pins[i], strerror(errno));
            // Attempt to release previously acquired lines
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return -1;
        }
    }

    return 0;
}

// Reads the sensor data from the GPIO lines
int read_sensor_data(int *sensor_data) {
    for (int i = 0; i < num_channels; i++) {
        int value = gpiod_line_get_value(lines[i]);
        if (value < 0) {
            fprintf(stderr, "Error reading line %d: %s\n", gpio_pins[i], strerror(errno));
            return -1; // Indicate an error
        }
        sensor_data[i] = value;
    }
    return 0; // Indicate success
}

// Logs the sensor data to the console with a timestamp
void log_sensor_data(int *sensor_data) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    printf("[%.6f] ", timestamp);
    for (int i = 0; i < num_channels; i++) {
        printf("CH%d=%d ", i + 1, sensor_data[i]);
    }
    printf("\n");
}

int main(void) {
    // Install signal handlers for graceful shutdown
    signal(SIGINT, cleanup_gpio);
    signal(SIGTERM, cleanup_gpio);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    int sensor_data[8];

    // Main loop
    while (1) {
        if (read_sensor_data(sensor_data) == 0) {
            log_sensor_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying.\n");
        }

        // Delay for 200 ms
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 200 * 1000 * 1000; // 200 ms
        nanosleep(&delay, NULL);
    }

    return 0; // This line will never be reached due to the infinite loop
}

