#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define TCS34725_ADDR 0x29
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define RED_THRESHOLD 200

// TCS34725 Registers
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_AGAIN 0x8F
#define TCS34725_CDATA 0x94
#define TCS34725_RDATA 0x96
#define TCS34725_GDATA 0x98
#define TCS34725_BDATA 0x9A
#define TCS34725_ID 0x12

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Calibration parameters (example values, replace with actual sensor calibration)
static float red_gain = 1.0f;
static float red_offset = 0.0f;
static float green_gain = 1.0f;
static float green_offset = 0.0f;
static float blue_gain = 1.0f;
static float blue_offset = 0.0f;
static float clear_gain = 1.0f;
static float clear_offset = 0.0f;

// Function prototypes
int i2c_init(const char *bus, int addr);
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_reg(int fd, uint8_t reg, uint8_t data);
int tcs34725_init(int fd);
int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
void calibrate_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue, float *calibrated_red, float *calibrated_green, float *calibrated_blue);
void gpio_init(const char *chip, int pin);
void gpio_set_value(struct gpiod_line *line, int value);
void gpio_release(struct gpiod_line *line);
void signal_handler(int sig);

// I2C Initialization
int i2c_init(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C Read Register
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Error reading data");
        return -1;
    }
    return 0;
}

// I2C Write Register
int i2c_write_reg(int fd, uint8_t reg, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = data;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing data");
        return -1;
    }
    return 0;
}

// TCS34725 Initialization
int tcs34725_init(int fd) {
    uint8_t sensor_id;

    // Power on the sensor
    if (i2c_write_reg(fd, TCS34725_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error powering on sensor\n");
        return -1;
    }

    // Set integration time (ATIME)
    if (i2c_write_reg(fd, TCS34725_ATIME, 0x00) < 0) {
        fprintf(stderr, "Error setting integration time\n");
        return -1;
    }

    // Set gain (AGAIN)
    if (i2c_write_reg(fd, TCS34725_AGAIN, 0x00) < 0) {
        fprintf(stderr, "Error setting gain\n");
        return -1;
    }

    // Verify sensor ID
    if (i2c_read_reg(fd, TCS34725_ID, &sensor_id, 1) < 0) {
        fprintf(stderr, "Error reading sensor ID\n");
        return -1;
    }

    if (sensor_id != 0x44) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    return 0;
}

// TCS34725 Read Data
int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t data[8];

    if (i2c_read_reg(fd, TCS34725_CDATA, data, 8) < 0) {
        fprintf(stderr, "Error reading color data\n");
        return -1;
    }

    *clear = (data[1] << 8) | data[0];
    *red = (data[3] << 8) | data[2];
    *green = (data[5] << 8) | data[4];
    *blue = (data[7] << 8) | data[6];

    return 0;
}

// Calibrate Data
void calibrate_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue, float *calibrated_red, float *calibrated_green, float *calibrated_blue) {
    *calibrated_red = (float)red * red_gain + red_offset;
    *calibrated_green = (float)green * green_gain + green_offset;
    *calibrated_blue = (float)blue * blue_gain + blue_offset;
}

// GPIO Initialization
void gpio_init(const char *chip, int pin) {
    gpio_chip = gpiod_chip_open_by_name(chip);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        exit(EXIT_FAILURE);
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, pin);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(gpio_line, "color_sensor", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(gpio_chip);
        exit(EXIT_FAILURE);
    }
}

// GPIO Set Value
void gpio_set_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
    }
}

// GPIO Release
void gpio_release(struct gpiod_line *line) {
    if (gpiod_line_release(line) < 0) {
        perror("Error releasing GPIO line");
    }
}

// Signal Handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    uint16_t clear, red, green, blue;
    float calibrated_red, calibrated_green, calibrated_blue;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_init(I2C_BUS, TCS34725_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return EXIT_FAILURE;
    }

    // Initialize TCS34725
    if (tcs34725_init(i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    gpio_init(GPIO_CHIP, GPIO_PIN);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (tcs34725_read_data(i2c_fd, &clear, &red, &green, &blue) < 0) {
            fprintf(stderr, "Error reading sensor data, attempting re-initialization...\n");
            close(i2c_fd);
            sleep(1); // Wait before re-initializing
            i2c_fd = i2c_init(I2C_BUS, TCS34725_ADDR);
            if (i2c_fd < 0) {
                fprintf(stderr, "I2C re-initialization failed\n");
                terminate = 1; // Exit if re-initialization fails
                continue;
            }
            if (tcs34725_init(i2c_fd) < 0) {
                fprintf(stderr, "TCS34725 re-initialization failed\n");
                terminate = 1; // Exit if re-initialization fails
                continue;
            }
            continue; // Skip to the next iteration
        }

        // Calibrate data
        calibrate_data(clear, red, green, blue, &calibrated_red, &calibrated_green, &calibrated_blue);

        // Control LED based on red value
        gpio_set_value(gpio_line, (calibrated_red > RED_THRESHOLD) ? 1 : 0);

        // Print calibrated values
        printf("Clear: %d, Red: %d, Green: %d, Blue: %d, Calibrated Red: %.2f, Calibrated Green: %.2f, Calibrated Blue: %.2f\n",
