    gpio_chip = gpiod_chip_open_by_name(chip);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        exit(EXIT_FAILURE);
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, pin);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(gpio_line, "color_sensor", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(gpio_chip);
        exit(EXIT_FAILURE);
    }
}

// GPIO Set Value
void gpio_set_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
    }
}

// GPIO Release
void gpio_release(struct gpiod_line *line) {
    if (gpiod_line_release(line) < 0) {
        perror("Error releasing GPIO line");
    }
}

// Signal Handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    uint16_t clear, red, green, blue;
    float calibrated_red, calibrated_green, calibrated_blue;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_init(I2C_BUS, TCS34725_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return EXIT_FAILURE;
    }

