        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    gpio_init(GPIO_CHIP, GPIO_PIN);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (tcs34725_read_data(i2c_fd, &clear, &red, &green, &blue) < 0) {
            fprintf(stderr, "Error reading sensor data, attempting re-initialization...\n");
            close(i2c_fd);
            sleep(1); // Wait before re-initializing
            i2c_fd = i2c_init(I2C_BUS, TCS34725_ADDR);
            if (i2c_fd < 0) {
                fprintf(stderr, "I2C re-initialization failed\n");
                terminate = 1; // Exit if re-initialization fails
                continue;
            }
            if (tcs34725_init(i2c_fd) < 0) {
                fprintf(stderr, "TCS34725 re-initialization failed\n");
                terminate = 1; // Exit if re-initialization fails
                continue;
            }
            continue; // Skip to the next iteration
        }

        // Calibrate data
        calibrate_data(clear, red, green, blue, &calibrated_red, &calibrated_green, &calibrated_blue);

        // Control LED based on red value
        gpio_set_value(gpio_line, (calibrated_red > RED_THRESHOLD) ? 1 : 0);

        // Print calibrated values
