               clear, red, green, blue, calibrated_red, calibrated_green, calibrated_blue);

        // Wait before next reading
        usleep(200000); // 200 ms
    }

    // Cleanup
    close(i2c_fd);
    gpio_release(gpio_line);
    gpiod_chip_close(gpio_chip);

    return EXIT_SUCCESS;
}

