#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define I2C_BUS 1
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
void signal_handler(int signal);
int init_i2c();
float read_lux();
uint32_t map_lux_to_brightness(float lux);
void set_led_brightness(uint32_t brightness);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read lux value from BH1750 sensor
float read_lux() {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2cWriteByteData(i2c_handle, 0x00, BH1750_CONTINUOUS_HIGH_RES_MODE) < 0) {
            fprintf(stderr, "Error writing to I2C device (mode command): %d\n", i2c_handle);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        gpioDelay(180000); // Wait 180 ms

        int msb = i2cReadByteData(i2c_handle, 0x00);
        int lsb = i2cReadByteData(i2c_handle, 0x01);

        if (msb >= 0 && lsb >= 0) {
            float lux = (msb << 8 | lsb) / 1.2;
            return lux;
        } else {
            fprintf(stderr, "Error reading from I2C device: MSB=%d, LSB=%d\n", msb, lsb);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }
    fprintf(stderr, "Failed to read lux after %d retries\n", MAX_RETRIES);
    return -1.0; // Indicate error
}

// Map lux value to LED strip brightness using a logarithmic function
uint32_t map_lux_to_brightness(float lux) {
    // Clamp lux value to a reasonable range
    if (lux < 0) lux = 0;
    if (lux > 1000) lux = 1000;

    // Use a logarithmic function to map lux to brightness
    float brightness_float = 255.0 * log10(1.0 + lux / 100.0); // Scale lux to 0-1000, then log10, and scale to 0-1
    brightness_float = brightness_float / log10(1.0 + 1000.0 / 100.0); // Scale to 0-255

    // Convert float to uint32_t
    uint32_t brightness = (uint32_t)(brightness_float * 255.0);

    return brightness;
}

