        pulse[pulse_index].gpioOff = 1 << GPIO_PIN;
        pulse[pulse_index].usDelay = 450; // 450 us
        pulse_index++;

        // Red
        pulse[pulse_index].gpioOn = 1 << GPIO_PIN;
        pulse[pulse_index].gpioOff = 0;
        pulse[pulse_index].usDelay = 800; // 800 us
        pulse_index++;

        pulse[pulse_index].gpioOn = 0;
        pulse[pulse_index].gpioOff = 1 << GPIO_PIN;
        pulse[pulse_index].usDelay = 450; // 450 us
        pulse_index++;

        pulse[pulse_index].gpioOn = 1 << GPIO_PIN;
        pulse[pulse_index].gpioOff = 0;
        pulse[pulse_index].usDelay = 800; // 800 us
        pulse_index++;

        pulse[pulse_index].gpioOn = 0;
        pulse[pulse_index].gpioOff = 1 << GPIO_PIN;
        pulse[pulse_index].usDelay = 450; // 450 us
        pulse_index++;

        // Blue
        pulse[pulse_index].gpioOn = 1 << GPIO_PIN;
        pulse[pulse_index].gpioOff = 0;
        pulse[pulse_index].usDelay = 800; // 800 us
        pulse_index++;

        pulse[pulse_index].gpioOn = 0;
        pulse[pulse_index].gpioOff = 1 << GPIO_PIN;
        pulse[pulse_index].usDelay = 450; // 450 us
        pulse_index++;

        pulse[pulse_index].gpioOn = 1 << GPIO_PIN;
        pulse[pulse_index].gpioOff = 0;
        pulse[pulse_index].usDelay = 800; // 800 us
        pulse_index++;

        pulse[pulse_index].gpioOn = 0;
        pulse[pulse_index].gpioOff = 1 << GPIO_PIN;
        pulse[pulse_index].usDelay = 450; // 450 us
        pulse_index++;
    }

    gpioWaveAddGeneric(pulse_index, pulse);

    int wave_id = gpioWaveCreate();
    if (wave_id >= 0) {
        gpioWaveTxSend(wave_id, PI_WAVE_MODE_ONE_SHOT); // Send the wave once
        gpioWaveDelete(wave_id);
    } else {
        fprintf(stderr, "Error creating wave: %d\n", wave_id);
    }
}

// Cleanup resources before exiting
