#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdint.h>

// Define constants
#define I2C_BUS 1
#define SPI_CHANNEL 0
#define NUM_SENSORS 3
#define FADE_DURATION 500 // milliseconds
#define DELAY_BETWEEN_CYCLES 100 // milliseconds

// APA102 LED strip parameters
#define NUM_LEDS 10
#define START_FRAME_SIZE 4
#define END_FRAME_SIZE 4
#define FRAME_SIZE (START_FRAME_SIZE + NUM_LEDS * 4 + END_FRAME_SIZE)

// Global variables
int i2c_handles[NUM_SENSORS];
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c_sensors();
float read_lux(int i2c_handle);
float average_lux(float lux_values[], int num_sensors);
int map_lux_to_brightness(float average_lux);
int fade_brightness(int current_brightness, int target_brightness);
int init_spi();
void send_apu102_frame(int brightness);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// Initialize I2C sensors
int init_i2c_sensors() {
    int addresses[] = {0x23, 0x5C, 0x46}; // Example addresses
    int num_sensors_found = 0;

    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_handles[i] = i2cOpen(I2C_BUS, addresses[i], 0);
        if (i2c_handles[i] >= 0) {
            printf("BH1750 sensor found at address 0x%02X\n", addresses[i]);
            num_sensors_found++;
        } else {
            fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", addresses[i], i2c_handles[i]);
            i2c_handles[i] = -1; // Mark as invalid
        }
    }

    return num_sensors_found;
}

// Read lux value from BH1750 sensor
float read_lux(int i2c_handle) {
    if (i2c_handle < 0) return -1.0; // Invalid handle

    char config_cmd = 0x21; // One-Time High-Resolution Mode 2
    if (i2cWriteDevice(i2c_handle, &config_cmd, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1.0;
    }

    gpioDelay(180); // Wait for conversion (at least 180ms)

    char buffer[2];
    if (i2cReadDevice(i2c_handle, buffer, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1.0;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    float lux = (float)raw_value / 1.2; // BH1750 datasheet conversion

    return lux;
}

// Average lux readings
float average_lux(float lux_values[], int num_sensors) {
    float sum = 0.0;
    int valid_sensor_count = 0;

    for (int i = 0; i < num_sensors; i++) {
        if (lux_values[i] >= 0) { // Check for valid reading
            sum += lux_values[i];
            valid_sensor_count++;
        }
    }

    if (valid_sensor_count > 0) {
        return sum / valid_sensor_count;
    } else {
        return 0.0; // Return 0 if no valid readings
    }
}

// Map lux to brightness (0-31)
int map_lux_to_brightness(float average_lux) {
    // Inverse relationship: lower lux -> higher brightness
    // Clamp average_lux to [0, 1000] to prevent extreme values
    float clamped_lux = (average_lux < 0) ? 0 : (average_lux > 1000) ? 1000 : average_lux;
    int brightness = 31 - (int)(clamped_lux / 1000.0 * 31.0); // Map to 0-31
    return brightness;
}

// Fade brightness to target value
int fade_brightness(int current_brightness, int target_brightness) {
    int diff = target_brightness - current_brightness;
    int steps = 50; // Number of steps in the fade
    int increment = diff / steps;
    int current_step = 0;

    for (int i = 0; i < 500; i++) {
        if (i < diff) {
            current_brightness += increment;
        } else {
            current_brightness -= increment;
        }

        if (current_brightness < 0) current_brightness = 0;
        if (current_brightness > 31) current_brightness = 31;

        send_apu102_frame(current_brightness);
        gpioDelay(1); // Small delay for smoother fade
    }

    return current_brightness;
}

// Initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, 1000000, 0); // Channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Send APA102 frame
void send_apu102_frame(int brightness) {
    // Start frame
    uint8_t start_frame[START_FRAME_SIZE] = {0x00, 0x00, 0x00, 0x00};
    spiWrite(spi_handle, (char *)start_frame, START_FRAME_SIZE);

    // LED data
    for (int i = 0; i < NUM_LEDS; i++) {
        uint8_t led_data[4] = {0xE0 | brightness, 0x00, 0x00, 0xFF}; // Global brightness, blue, green, red
        spiWrite(spi_handle, (char *)led_data, 4);
    }

    // End frame
    uint8_t end_frame[END_FRAME_SIZE] = {0xFF, 0xFF, 0xFF, 0xFF};
    spiWrite(spi_handle, (char *)end_frame, END_FRAME_SIZE);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C sensors
    int num_sensors_found = init_i2c_sensors();
    if (num_sensors_found == 0) {
        fprintf(stderr, "No BH1750 sensors found. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        float lux_values[NUM_SENSORS];
        int valid_sensor_count = 0;

        // Read lux values from each sensor
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_handles[i] >= 0) {
                lux_values[i] = read_lux(i2c_handles[i]);
                if (lux_values[i] >= 0) {
                    valid_sensor_count++;
                }
            } else {
                lux_values[i] = 0.0; // Use a default value if the sensor is invalid
            }
        }

        // Average lux readings
        float average_lux_value = average_lux(lux_values, valid_sensor_count);

        // Map lux to brightness
        int target_brightness = map_lux_to_brightness(average_lux_value);

        // Fade brightness to target value
        fade_brightness(gpioGetGlobalData(0), target_brightness); // Use global data for brightness

        // Delay before next cycle
        gpioDelay(DELAY_BETWEEN_CYCLES);
    }

    // Clean up resources
    printf("Cleaning up resources.\n");
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_handles[i] >= 0) {
            i2cClose(i2c_handles[i]);
        }
    }
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

