#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

// Configuration
#define I2C_BUS 1
#define VEML7700_ADDR 0x10
#define WS2812B_GPIO 18
#define NUM_LEDS 1
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// VEML7700 Configuration
#define VEML7700_CONFIG_REG 0x00
#define VEML7700_CONFIG_DEFAULT 0x0000 // Integration time 100ms, Gain 1/8

// WS2812B Timing (800kHz)
#define WS2812B_BIT_DELAY 350  // us
#define WS2812B_RESET_DELAY 50  // us
#define WS2812B_START_FRAME 0x00
#define WS2812B_END_FRAME 0xFF

// Global Variables
int i2c_fd = -1;
int gpio_pin = WS2812B_GPIO;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int init_i2c(int bus, int addr);
int config_veml7700(int fd, uint16_t config);
int read_als(int fd);
float calculate_lux(int raw_als);
int gamma_correct(float lux);
int drive_led(int gpio, int brightness);
void signal_handler(int signal);

// I2C Initialization
int init_i2c(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// VEML7700 Configuration
int config_veml7700(int fd, uint16_t config) {
    uint8_t buf[3];
    buf[0] = VEML7700_CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    if (write(fd, buf, 3) != 3) {
        perror("Error writing to VEML7700 config register");
        return -1;
    }
    return 0;
}

// Read ALS Data
int read_als(int fd) {
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("Error reading ALS data");
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

// Calculate Lux
float calculate_lux(int raw_als) {
    return (float)raw_als * 0.0288;
}

// Gamma Correction
int gamma_correct(float lux) {
    float gamma = 1.0/2.2;
    float brightness_float = 255.0 * powf(lux / 120000.0, gamma);
    return (int)brightness_float;
}

// Drive LED (Bit-Banging)
int drive_led(int gpio, int brightness) {
    int i;
    int bit;
    int data = 0;

    // Start Frame
    gpioWrite(gpio, 0);
    gpioDelay(RESET_DELAY);
    for (i = 0; i < 8; i++) {
        gpioWrite(gpio, 1);
        gpioDelay(WS2812B_BIT_DELAY);
        gpioWrite(gpio, 0);
        gpioDelay(WS2812B_BIT_DELAY);
    }

    // LED Data
    for (i = 0; i < NUM_LEDS; i++) {
        bit = (brightness >> (NUM_LEDS - 1 - i)) & 1;
        data = data | (bit << (7 - i));
    }

    for (i = 0; i < 8; i++) {
        gpioWrite(gpio, 1);
        gpioDelay(WS2812B_BIT_DELAY);
        gpioWrite(gpio, 0);
        gpioDelay(WS2812B_BIT_DELAY);
    }

    // End Frame
    gpioWrite(gpio, 0);
    gpioDelay(RESET_DELAY);
    for (i = 0; i < 8; i++) {
        gpioWrite(gpio, 1);
        gpioDelay(WS2812B_BIT_DELAY);
        gpioWrite(gpio, 0);
        gpioDelay(WS2812B_BIT_DELAY);
    }

    return 0;
}

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, VEML7700_ADDR);
    if (i2c_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Configure VEML7700
    if (config_veml7700(i2c_fd, VEML7700_CONFIG_DEFAULT) < 0) {
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(gpio_pin, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int raw_als = -1;
        int retries = 0;
        int als_value = -1;

        // Read ALS data with retries
        while (retries < MAX_RETRIES && raw_als == -1) {
            raw_als = read_als(i2c_fd);
            if (raw_als == -1) {
                fprintf(stderr, "I2C read error, retrying (%d/%d)\n", retries + 1, MAX_RETRIES);
                retries++;
                usleep(RETRY_DELAY_MS * 1000); // Convert ms to us
            }
        }

        if (raw_als == -1) {
            fprintf(stderr, "Failed to read ALS after %d retries\n", MAX_RETRIES);
        } else {
            // Calculate Lux
            float lux = calculate_lux(raw_als);

            // Gamma Correct
            int brightness = gamma_correct(lux);

            // Drive LED
            drive_led(gpio_pin, brightness);

            // Print values
            printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        }

        // Delay
        usleep(200000); // 200 ms
    }

    // Cleanup
    drive_led(gpio_pin, 0); // Turn off LED
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

