#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

// Define constants
#define BUZZER_DURATION_MS 500
#define LED_BLINK_DURATION_MS 500
#define SELF_TEST_SAMPLE_COUNT 5
#define SELF_TEST_INTERVAL_MS 100
#define SELF_TEST_FAILURE_BLINK_DURATION_MS 100
#define SELF_TEST_FAILURE_BUZZER_DURATION_MS 200, 200, 600, 200
#define SELF_TEST_FAILURE_BLINK_COUNT 5
#define SELF_TEST_FAILURE_BUZZER_REPEAT_COUNT 3
#define POLLING_INTERVAL_MS 50

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *flame_line;
static struct gpiod_line *buzzer_line;
static struct gpiod_line *led_line;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int gpio_request(struct gpiod_chip *chip, unsigned int num, const char *consumer);
int gpio_set_value(struct gpiod_line *line, int value);
int gpio_release(struct gpiod_line *line);
int gpio_set_direction(struct gpiod_line *line, const char *direction);
int read_flame_sensor(struct gpiod_line *line);
void activate_buzzer(struct gpiod_line *line, int duration_ms);
void activate_led(struct gpiod_line *line, int duration_ms);
void self_test(void);
void log_event(const char *event_description);
void signal_handler(int sig);

// Function to request a GPIO line
int gpio_request(struct gpiod_chip *chip, unsigned int num, const char *consumer)
{
    struct gpiod_line *line = gpiod_chip_get_line(chip, num);
    if (!line) {
        fprintf(stderr, "Error: Could not get line %u: %s\n", num, strerror(errno));
        return -1;
    }

    int ret = gpiod_line_request_output(line, consumer, 0); // Initial value 0
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request line %u as output: %s\n", num, strerror(errno));
        gpiod_line_release(line);
        return -1;
    }
    return 0;
}

// Function to set the value of a GPIO line
int gpio_set_value(struct gpiod_line *line, int value)
{
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set line value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to release a GPIO line
int gpio_release(struct gpiod_line *line)
{
    int ret = gpiod_line_release(line);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not release line: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to set the direction of a GPIO line
int gpio_set_direction(struct gpiod_line *line, const char *direction)
{
    int ret = gpiod_line_request_input(line, direction);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request line as input: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read the flame sensor value
int read_flame_sensor(struct gpiod_line *line)
{
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error: Could not read line value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Function to activate the buzzer
void activate_buzzer(struct gpiod_line *line, int duration_ms)
{
    if (gpio_set_value(line, 1) < 0) return; // Set HIGH
    log_event("Buzzer activated");
    gpioDelay(duration_ms * 1000); // Delay in microseconds
    if (gpio_set_value(line, 0) < 0) return; // Set LOW
    log_event("Buzzer deactivated");
}

// Function to activate the LED
void activate_led(struct gpiod_line *line, int duration_ms)
{
    if (gpio_set_value(line, 1) < 0) return; // Set HIGH
    log_event("LED activated");
    gpioDelay(duration_ms * 1000); // Delay in microseconds
    if (gpio_set_value(line, 0) < 0) return; // Set LOW
    log_event("LED deactivated");
}

// Function to perform the self-test
void self_test(void)
{
    log_event("Starting self-test...");

    // LED blink test
    for (int i = 0; i < 2; ++i) {
        if (gpio_set_value(led_line, 1) < 0) return;
        log_event("LED ON");
        gpioDelay(LED_BLINK_DURATION_MS * 1000);
        if (gpio_set_value(led_line, 0) < 0) return;
        log_event("LED OFF");
        gpioDelay(LED_BLINK_DURATION_MS * 1000);
    }

    // Flame sensor consistency test
    int flame_detected = 1; // Assume no flame initially
    for (int i = 0; i < SELF_TEST_SAMPLE_COUNT; ++i) {
        int sensor_value = read_flame_sensor(flame_line);
        if (sensor_value < 0) return;
        if (sensor_value == 0) { // Active-low
            flame_detected = 1;
        } else {
            flame_detected = 0;
        }
        gpioDelay(SELF_TEST_INTERVAL_MS * 1000);
    }

    if (flame_detected) {
        log_event("Self-test passed.");
    } else {
        log_event("Self-test failed.");

        // Error pattern
        for (int i = 0; i < SELF_TEST_FAILURE_BLINK_COUNT; ++i) {
            if (gpio_set_value(led_line, 1) < 0) return;
            log_event("LED ON (rapid blink)");
            gpioDelay(SELF_TEST_FAILURE_BLINK_DURATION_MS * 1000);
            if (gpio_set_value(led_line, 0) < 0) return;
            log_event("LED OFF (rapid blink)");
            gpioDelay(SELF_TEST_FAILURE_BLINK_DURATION_MS * 1000);
        }

        // Buzzer error pattern
        for (int i = 0; i < SELF_TEST_FAILURE_BUZZER_REPEAT_COUNT; ++i) {
            activate_buzzer(buzzer_line, SELF_TEST_FAILURE_BUZZER_DURATION_MS[0]);
            gpioDelay(SELF_TEST_FAILURE_BUZZER_DURATION_MS[1] * 1000);
            activate_buzzer(buzzer_line, SELF_TEST_FAILURE_BUZZER_DURATION_MS[2]);
            gpioDelay(SELF_TEST_FAILURE_BUZZER_DURATION_MS[3] * 1000);
        }

        log_event("Self-test failed. Exiting.");
        exit(1);
    }
}

// Function to log events with timestamps
void log_event(const char *event_description)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stdout, "[%s] %s\n", timestamp, event_description);
}

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    if (sig == SIGINT) {
        log_event("Ctrl+C pressed. Exiting...");
        terminate = 1;
    }
}

int main(void)
{
    // Initialize signal handler
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Request GPIO lines
    if (gpio_request(chip, FLAME_SENSOR_PIN, "flame_sensor") < 0) return 1;
    if (gpio_request(chip, BUZZER_PIN, "buzzer") < 0) return 1;
    if (gpio_request(chip, LED_PIN, "led") < 0) return 1;

    // Set GPIO directions
    if (gpio_set_direction(flame_line, "in") < 0) return 1;
    if (gpio_set_direction(buzzer_line, "out") < 0) return 1;
    if (gpio_set_direction(led_line, "out") < 0) return 1;

    // Run self-test
    self_test();

    // Main loop
    int flame_detected = 0;
    while (!terminate) {
        int sensor_value = read_flame_sensor(flame_line);
        if (sensor_value < 0) {
            break; // Exit loop on error
        }

        if (sensor_value == 0) { // Flame detected (active-low)
            if (!flame_detected) {
                activate_buzzer(buzzer_line, BUZZER_DURATION_MS);
                activate_led(led_line, LED_BLINK_DURATION_MS);
                flame_detected = 1;
            }
        } else {
            if (flame_detected) {
                deactivate_buzzer(buzzer_line);
                deactivate_led(led_line);
                flame_detected = 0;
            }
        }

        gpioDelay(POLLING_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    log_event("Cleaning up...");
    gpio_release(flame_line);
    gpio_release(buzzer_line);
    gpio_release(led_line);
    gpiod_chip_close(chip);

    return 0;
}

