#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define LED_GPIO 17
#define BUFFER_SIZE 60
#define MAX_RETRIES 3

// Global variables
int i2c_fd = -1;
int gpio_fd = -1;
volatile sig_atomic_t program_running = 1;

// Circular buffer
float lux_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c(const char *bus, int addr);
int init_gpio(int gpio);
int read_bh1750(int fd, float *lux);
void update_led_rate(float avg_lux, float *rate);
void control_led(int gpio, float rate);
void add_to_buffer(float lux);
float calculate_average(void);
void signal_handler(int sig);
void cleanup(void);

// I2C initialization function
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// GPIO initialization function
int init_gpio(int gpio) {
    char buffer[64];
    int fd;

    // Export GPIO
    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        perror("Error opening /sys/class/gpio/export");
        return -1;
    }
    snprintf(buffer, sizeof(buffer), "%d", gpio);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        perror("Error writing to /sys/class/gpio/export");
        close(fd);
        return -1;
    }
    close(fd);

    // Set direction to output
    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d/direction", gpio);
    fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        perror("Error opening GPIO direction file");
        return -1;
    }
    if (write(fd, "out", 3) < 0) {
        perror("Error writing to GPIO direction file");
        close(fd);
        return -1;
    }
    close(fd);

    return 0;
}

// BH1750 reading function with retries
int read_bh1750(int fd, float *lux) {
    uint8_t cmd = CONTINUOUS_HIGH_RES_MODE;
    uint8_t data[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (write(fd, &cmd, 1) != 1) {
            perror("Error writing to I2C device");
            retries++;
            sleep(1); // Wait before retrying
            continue;
        }

        usleep(200000); // Wait for measurement (at least 180ms)

        if (read(fd, data, 2) != 2) {
            perror("Error reading from I2C device");
            retries++;
            sleep(1); // Wait before retrying
            continue;
        }

        unsigned int raw_value = (data[0] << 8) | data[1];
        *lux = (float)raw_value / 1.2;
        return 0; // Success
    }

    fprintf(stderr, "Failed to read BH1750 after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// LED rate calculation function
void update_led_rate(float avg_lux, float *rate) {
    *rate = 0.5 + (avg_lux / 1000.0) * 4.5;
    if (*rate < 0.5) *rate = 0.5;
    if (*rate > 5.0) *rate = 5.0;
}

// LED control function
void control_led(int gpio, float rate) {
    struct timespec on_time, off_time;
    long period_ns = 1000000000 / rate; // Period in nanoseconds
    long on_duration_ns = period_ns / 2;
    long off_duration_ns = period_ns / 2;

    on_time.tv_sec = 0;
    on_time.tv_nsec = on_duration_ns;
    off_time.tv_sec = 0;
    off_time.tv_nsec = off_duration_ns;

    if (write(gpio_fd, "1", 1) < 0) {
        perror("Error writing to GPIO");
    }
    nanosleep(&on_time, NULL);

    if (write(gpio_fd, "0", 1) < 0) {
        perror("Error writing to GPIO");
    }
    nanosleep(&off_time, NULL);
}

// Circular buffer functions
void add_to_buffer(float lux) {
    lux_buffer[buffer_index] = lux;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

float calculate_average(void) {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += lux_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", sig);
}

// Cleanup function
void cleanup(void) {
    printf("Cleaning up...\n");

    if (gpio_fd != -1) {
        close(gpio_fd);
    }

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Unexport GPIO
    int fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd >= 0) {
        char buffer[64];
        snprintf(buffer, sizeof(buffer), "%d", LED_GPIO);
        write(fd, buffer, strlen(buffer));
        close(fd);
    } else {
        perror("Error opening /sys/class/gpio/unexport");
    }
}

int main() {
    float lux, avg_lux, rate;
    struct timespec sleep_time;
    sleep_time.tv_sec = 1; // 1 second
    sleep_time.tv_nsec = 0;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, BH1750_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(LED_GPIO) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    gpio_fd = open("/sys/class/gpio/gpio%d/value", O_WRONLY);
    if (gpio_fd < 0) {
        perror("Error opening GPIO value file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read light sensor
        if (read_bh1750(i2c_fd, &lux) == 0) {
            // Update circular buffer
            add_to_buffer(lux);

            // Calculate average
            avg_lux = calculate_average();

            // Update LED rate
            update_led_rate(avg_lux, &rate);

            // Control LED
            control_led(LED_GPIO, rate);

            printf("Lux: %.2f, Average Lux: %.2f, Rate: %.2f Hz\n", lux, avg_lux, rate);
        } else {
            fprintf(stderr, "Failed to read lux. Skipping this iteration.\n");
        }

        // Sleep for 1 second
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

