#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

// Define GPIO pins
#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define GPIO line numbers
#define DATA_LINE 0
#define CLOCK_LINE 1
#define LATCH_LINE 2

// Define segment patterns for digits 0-9 (common cathode)
const unsigned char digits[] = {
    0b00111111, // 0
    0b00000110, // 1
    0b01011011, // 2
    0b01001111, // 3
    0b01100110, // 4
    0b01101101, // 5
    0b01111101, // 6
    0b00000111, // 7
    0b01111111, // 8
    0b01101111  // 9
};

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *data_line, *clock_line, *latch_line;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup();
    exit(0);
}

// Function to initialize the GPIO lines
int initialize_gpio() {
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    latch_line = gpiod_chip_get_line(chip, LATCH_PIN);

    if (!data_line || !clock_line || !latch_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(data_line, "display", 0) < 0) {
        perror("Error requesting data line as output");
        gpiod_line_release(data_line);
        gpiod_line_release(clock_line);
        gpiod_line_release(latch_line);
        gpiod_chip_close(chip);
        return -1;
    }

