#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

#define LED_CHIP 0
#define LED_PIN 17
#define BUTTON_CHIP 0
#define BUTTON_PIN 18

static struct gpiod_chip *led_chip = NULL;
static struct gpiod_line *led_line = NULL;
static struct gpiod_chip *button_chip = NULL;
static struct gpiod_line *button_line = NULL;
static volatile sig_atomic_t blinking = 1;

void signal_handler(int sig);
int setup_gpio(void);
int cleanup_gpio(void);
void blink_led(void);
int button_event_wait(void);

int main(void) {
    struct timespec sleep_time;
    sleep_time.tv_sec = 1;  // 1 second
    sleep_time.tv_nsec = 0;

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (setup_gpio() != 0) {
        fprintf(stderr, "GPIO setup failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (blinking) {
        blink_led();
        if (button_event_wait() == 0) {
            break; // Exit loop on button press
        }
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    return 0;
}

void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, stopping blinking and exiting.\n");
        blinking = 0;
    }
}

int setup_gpio(void) {
    int ret;

    // Open LED chip
    led_chip = gpiod_chip_open_by_name(LED_CHIP);
    if (!led_chip) {
        fprintf(stderr, "Error opening LED chip %s\n", LED_CHIP);
        return -1;
    }

    // Open LED line
    led_line = gpiod_chip_get_line(led_chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting LED line %d\n", LED_PIN);
        gpiod_chip_close(led_chip);
        return -1;
    }

    // Request LED line as output, initially low
    ret = gpiod_line_request(led_line, NULL, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Error requesting LED line %d as output: %d\n", LED_PIN, ret);
        gpiod_chip_close(led_chip);
        gpiod_line_release(led_line);
        return -1;
    }

    // Open Button chip
    button_chip = gpiod_chip_open_by_name(BUTTON_CHIP);
    if (!button_chip) {
        fprintf(stderr, "Error opening Button chip %s\n", BUTTON_CHIP);
        gpiod_chip_close(led_chip);
        gpiod_line_release(led_line);
        return -1;
    }

    // Open Button line
    button_line = gpiod_chip_get_line(button_chip, BUTTON_PIN);
    if (!button_line) {
        fprintf(stderr, "Error getting Button line %d\n", BUTTON_PIN);
        gpiod_chip_close(led_chip);
        gpiod_line_release(led_line);
        gpiod_chip_close(button_chip);
        return -1;
    }

    // Request Button line as input with pull-up resistor and falling edge events
    ret = gpiod_line_request(button_line, NULL, GPIOD_LINE_REQUEST_DIRECTION_INPUT | GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Error requesting Button line %d as input: %d\n", BUTTON_PIN, ret);
        gpiod_chip_close(led_chip);
        gpiod_line_release(led_line);
        gpiod_chip_close(button_chip);
        gpiod_line_release(button_line);
        return -1;
    }

    return 0;
}

int cleanup_gpio(void) {
    int ret;

    // Release LED line
    ret = gpiod_line_release(led_line);
    if (ret < 0) {
        fprintf(stderr, "Error releasing LED line %d: %d\n", LED_PIN, ret);
    }

    // Release Button line
    ret = gpiod_line_release(button_line);
    if (ret < 0) {
        fprintf(stderr, "Error releasing Button line %d: %d\n", BUTTON_PIN, ret);
    }

    // Close LED chip
    ret = gpiod_chip_close(led_chip);
    if (ret < 0) {
        fprintf(stderr, "Error closing LED chip %s: %d\n", LED_CHIP, ret);
    }

    // Close Button chip
    ret = gpiod_chip_close(button_chip);
    if (ret < 0) {
        fprintf(stderr, "Error closing Button chip %s: %d\n", BUTTON_CHIP, ret);
    }

    return 0;
}

void blink_led(void) {
    int ret;

    // Turn LED on
    ret = gpiod_line_set_value(led_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting LED value: %d\n", ret);
    }

    // Sleep for 1 second
    nanosleep(&sleep_time, NULL);

    // Turn LED off
    ret = gpiod_line_set_value(led_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting LED value: %d\n", ret);
    }

    // Sleep for 1 second
    nanosleep(&sleep_time, NULL);
}

int button_event_wait(void) {
    int ret;
    struct timespec timeout;
    timeout.tv_sec = 1;  // 1 second
    timeout.tv_nsec = 0;

    // Wait for a falling edge event on the button line
    ret = gpiod_line_event_wait(button_line, &timeout);
    if (ret < 0) {
        fprintf(stderr, "Error waiting for button event: %d\n", ret);
        return -1;
    }

    // Clear the event by reading the line value
    ret = gpiod_line_get_value(button_line);
    if (ret < 0) {
        fprintf(stderr, "Error getting button line value: %d\n", ret);
        return -1;
    }

    return 0;
}

