#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LED_GPIO 5

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        terminate = 1;
        printf("\nCaught SIGINT, exiting gracefully...\n");
    }
}

int main() {
    int result;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set GPIO5 as an output */
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    /* Set up signal handler for SIGINT */
    signal(SIGINT, signal_handler);

    printf("LED blinking on GPIO%d. Press Ctrl+C to exit.\n", LED_GPIO);

    /* Main loop */
    while (!terminate) {
        /* Turn LED on */
        gpioWrite(LED_GPIO, 1);
        printf("LED ON\n");
        fflush(stdout);

        /* Wait 750ms */
        time_sleep(0.75);

        /* Turn LED off */
        gpioWrite(LED_GPIO, 0);
        printf("LED OFF\n");
        fflush(stdout);

        /* Wait 750ms */
        time_sleep(0.75);
    }

    /* Clean up and exit */
    gpioWrite(LED_GPIO, 0); /* Ensure LED is off */
    gpioTerminate();
    return 0;
}

