#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIOCHIP "gpiochip0"
#define LED_PIN 24
#define BUTTON_PIN 22

static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static struct gpiod_line *button_line;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "led_button_app";

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIOCHIP, strerror(errno));
        return 1;
    }

    // Get LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting LED line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Get Button line
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        fprintf(stderr, "Error getting button line %d: %s\n", BUTTON_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request LED line as output
    if (gpiod_line_request(led_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting LED line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request Button line as input with pull-down
    if (gpiod_line_request(button_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting button line as input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Set initial LED state to off
    if (gpiod_line_set_value(led_line, 0) < 0) {
        fprintf(stderr, "Error setting initial LED state to off: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int button_value = gpiod_line_get_value(button_line);
        if (button_value < 0) {
            fprintf(stderr, "Error reading button value: %s\n", strerror(errno));
            break;
        }

        if (button_value == 0) { // Button is pressed (low)
            if (gpiod_line_set_value(led_line, 1) < 0) {
                fprintf(stderr, "Error setting LED on: %s\n", strerror(errno));
                break;
