#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

// Define GPIO pins for RGB LED
#define RED_PIN 24
#define GREEN_PIN 23
#define BLUE_PIN 18

// Define PWM frequency (100 Hz) and period (10 ms)
#define PWM_FREQUENCY 100
#define PWM_PERIOD_NS (1000000000 / PWM_FREQUENCY)

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *red_line, *green_line, *blue_line;

// Function prototypes
int initialize_gpio(void);
void cleanup_gpio(int signal);
void set_rgb_color(int red_value, int green_value, int blue_value);
int generate_random_color(int *red, int *green, int *blue);

// Signal handler for Ctrl+C
void cleanup_gpio(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Release GPIO lines
    if (red_line) {
        gpiod_line_release(red_line);
    }
    if (green_line) {
        gpiod_line_release(green_line);
    }
    if (blue_line) {
        gpiod_line_release(blue_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to initialize GPIO pins
int initialize_gpio(void) {
    // Open GPIO chip
    chip = gpiod_chip_open_by_number(0); // Assuming GPIO chip 0
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get GPIO lines for each color
    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);

    if (!red_line || !green_line || !blue_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(red_line, "red", 0) < 0) {
        perror("Error requesting red line for output");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_request_output(green_line, "green", 0) < 0) {
        perror("Error requesting green line for output");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_request_output(blue_line, "blue", 0) < 0) {
        perror("Error requesting blue line for output");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to set the RGB color using PWM
void set_rgb_color(int red_value, int green_value, int blue_value) {
    // Calculate PWM period in nanoseconds
    long period_ns = PWM_PERIOD_NS;

    // Calculate on-time in nanoseconds
    long on_time_ns = (long)((double)red_value / 100.0 * PWM_PERIOD_NS);

    // Set the value of each GPIO line
    gpiod_line_set_value(red_line, on_time_ns > period_ns);
    gpiod_line_set_value(green_line, on_time_ns > period_ns);
    gpiod_line_set_value(blue_line, on_time_ns > period_ns);
}

// Function to generate random RGB values
int generate_random_color(int *red, int *green, int *blue) {
    srand(time(NULL));
    *red = rand() % 101;
    *green = rand() % 101;
    *blue = rand() % 101;
    return 0;
}

int main(void) {
    // Install signal handler for Ctrl+C
    signal(SIGINT, cleanup_gpio);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("RGB LED control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int red, green, blue;

        // Generate random RGB values
        if (generate_random_color(&red, &green, &blue) != 0) {
            fprintf(stderr, "Error generating random color.\n");
            continue; // Skip to the next iteration
        }

        // Set the RGB color
        set_rgb_color(red, green, blue);

        // Wait for 100 ms
        struct timespec req = {0};
        req.tv_sec = 0;
        req.tv_nsec = 100000000; // 100 ms
        nanosleep(&req, NULL);
    }

    return 0;
}

