#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x19
#define GPIO_PIN 17
#define DEFAULT_THRESHOLD 2.0
#define SAMPLE_RATE 10 // Hz
#define SAMPLE_PERIOD 100 // ms
#define PULSE_DURATION 50 // ms
#define FULL_SCALE_2G 2.0
#define SENSITIVITY 16384.0

// Global variables
int i2c_handle;
double threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int init_lsm303();
int read_accelerometer(int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
int check_threshold(double magnitude, double threshold);
int log_data(int16_t x, int16_t y, int16_t z, double magnitude);
void pulse_gpio();
void signal_handler(int signal);

// Structure for sensor configuration
typedef struct {
    uint8_t ctrl_reg1_a;
    uint8_t ctrl_reg4_a;
} sensor_config_t;

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    return 0;
}

// Initialize LSM303DLHC
int init_lsm303() {
    // CTRL_REG1_A: Enable all axes, 100 Hz
    if (i2cWriteByteData(i2c_handle, 0x20, 0x27) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A\n");
        return -1;
    }

    // CTRL_REG4_A: +/- 2G full-scale, 16-bit output
    if (i2cWriteByteData(i2c_handle, 0x21, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4_A\n");
        return -1;
    }

    return 0;
}

// Read accelerometer data
int read_accelerometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, 0x28, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calculate G-force magnitude
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    double x_g = (double)x / SENSITIVITY;
    double y_g = (double)y / SENSITIVITY;
    double z_g = (double)z / SENSITIVITY;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Check if magnitude exceeds threshold
int check_threshold(double magnitude, double threshold) {
    return (magnitude > threshold) ? 1 : 0;
}

// Log data to file
int log_data(int16_t x, int16_t y, int16_t z, double magnitude) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, X: %d, Y: %d, Z: %d, Magnitude: %.2f\n", s, x, y, z, magnitude);
    fclose(fp);
    return 0;
}

// Pulse GPIO pin
void pulse_gpio() {
    gpioWrite(GPIO_PIN, 1); // Set HIGH
    gpioDelay(PULSE_DURATION * 1000); // Delay for pulse duration
    gpioWrite(GPIO_PIN, 0); // Set LOW
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        threshold = atof(argv[1]);
        if (threshold <= 0) {
            fprintf(stderr, "Invalid threshold value. Using default: %.2fG\n", DEFAULT_THRESHOLD);
            threshold = DEFAULT_THRESHOLD;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C and LSM303
    if (init_i2c() != 0 || init_lsm303() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    double magnitude;

    // Main loop
    while (!terminate) {
        // Read accelerometer data
        if (read_accelerometer(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check threshold
            if (check_threshold(magnitude, threshold)) {
                // Log data
                if (log_data(x, y, z, magnitude) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }

                // Pulse GPIO
                pulse_gpio();
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data. Retrying...\n");
        }

        // Delay for sampling rate
        gpioDelay(SAMPLE_PERIOD * 1000); // Delay in microseconds
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

