#define GYRO_ADDR 0x69
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define WHO_AM_I 0x0F
#define OUT_X_L 0x28
#define SENSITIVITY 0.00875
#define CALIBRATION_SAMPLES 100
#define LOG_INTERVAL_MS 50
#define ALERT_THRESHOLD 50.0

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Calibration offsets
float x_offset = 0.0;
float y_offset = 0.0;
float z_offset = 0.0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int init_gyro(int fd);
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z);
void calibrate_gyro(int fd, int samples);
void apply_calibration(int16_t x_raw, int16_t y_raw, int16_t z_raw, float *x_dps, float *y_dps, float *z_dps);
void log_data(float x_dps, float y_dps, float z_dps);
void check_alert(float x_dps, float y_dps, float z_dps);
void signal_handler(int sig);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register value");
        return -1;
    }
    return 0;
}

// Gyro initialization function
int init_gyro(int fd) {
    uint8_t who_am_i;

    // Check WHO_AM_I register
    if (i2c_read_reg(fd, WHO_AM_I, &who_am_i, 1) != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != 0xD3) {
        fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0xD3\n", who_am_i);
        return -1;
    }

    // Configure CTRL_REG1
    if (i2c_write_reg(fd, CTRL_REG1, 0x0F) != 0) {
        fprintf(stderr, "Error writing CTRL_REG1\n");
        return -1;
    }

    // Configure CTRL_REG4
    if (i2c_write_reg(fd, CTRL_REG4, 0x00) != 0) {
        fprintf(stderr, "Error writing CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Gyro data reading function
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    if (i2c_read_reg(fd, OUT_X_L, data, 6) != 0) {
        fprintf(stderr, "Error reading gyro data\n");
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Gyro calibration function
void calibrate_gyro(int fd, int samples) {
    int16_t x_raw, y_raw, z_raw;
    float x_sum = 0.0, y_sum = 0.0, z_sum = 0.0;

    printf("Calibrating gyro...\n");
    for (int i = 0; i < samples; i++) {
        if (read_gyro_data(fd, &x_raw, &y_raw, &z_raw) != 0) {
            fprintf(stderr, "Error during calibration\n");
            return;
        }
        x_sum += x_raw;
        y_sum += y_raw;
        z_sum += z_raw;
        usleep(10000); // 10 ms delay
    }

    x_offset = x_sum / samples;
    y_offset = y_sum / samples;
    z_offset = z_sum / samples;

    printf("Calibration complete. Offsets: X=%.2f, Y=%.2f, Z=%.2f\n", x_offset, y_offset, z_offset);
}

// Apply calibration function
void apply_calibration(int16_t x_raw, int16_t y_raw, int16_t z_raw, float *x_dps, float *y_dps, float *z_dps) {
    *x_dps = (float)(x_raw - x_offset) * SENSITIVITY;
    *y_dps = (float)(y_raw - y_offset) * SENSITIVITY;
    *z_dps = (float)(z_raw - z_offset) * SENSITIVITY;
}

// Data logging function
void log_data(float x_dps, float y_dps, float z_dps) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    fprintf(log_file, "%s, %.2f, %.2f, %.2f\n", timestamp, x_dps, y_dps, z_dps);
    fflush(log_file);
}

// Alert checking function
void check_alert(float x_dps, float y_dps, float z_dps) {
    if (fabs(x_dps) > ALERT_THRESHOLD || fabs(y_dps) > ALERT_THRESHOLD || fabs(z_dps) > ALERT_THRESHOLD) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

        fprintf(stderr, "ALERT: Axis(s) exceeding threshold at %s\n", timestamp);
        fprintf(log_file, "ALERT: Axis(s) exceeding threshold at %s\n", timestamp);
        fflush(log_file);
    }
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

int main() {
    int16_t x_raw, y_raw, z_raw;
    float x_dps, y_dps, z_dps;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize gyroscope
    if (init_gyro(i2c_fd) != 0) {
        fprintf(stderr, "Gyro initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Calibrate gyroscope
    calibrate_gyro(i2c_fd, CALIBRATION_SAMPLES);

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &x_raw, &y_raw, &z_raw) == 0) {
            // Apply calibration
            apply_calibration(x_raw, y_raw, z_raw, &x_dps, &y_dps, &z_dps);

            // Log data
            log_data(x_dps, y_dps, z_dps);

            // Check for alert
            check_alert(x_dps, y_dps, z_dps);
        } else {
            fprintf(stderr, "Failed to read gyro data\n");
        }

        usleep(LOG_INTERVAL_MS * 1000); // 50 ms delay
    }

    // Close I2C bus and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

