}

// Initialize accelerometer
int init_accelerometer() {
    accel_handle = i2cOpen(1, ACCEL_ADDR, 0);
    if (accel_handle < 0) {
        fprintf(stderr, "Error opening accelerometer I2C device: %d\n", accel_handle);
        return -1;
    }

    // Set CTRL_REG1_A to 0x27 (50 Hz, all axes enabled)
    if (i2cWriteByteData(accel_handle, CTRL_REG1_A, 0x27) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A\n");
        i2cClose(accel_handle);
        return -1;
    }

    // Set CTRL_REG4_A to 0x00 (Disable all interrupts)
    if (i2cWriteByteData(accel_handle, CTRL_REG4_A, 0x00) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG4_A\n");
        i2cClose(accel_handle);
        return -1;
    }

    return 0;
}

// Initialize magnetometer
int init_magnetometer() {
    mag_handle = i2cOpen(1, MAG_ADDR, 0);
    if (mag_handle < 0) {
        fprintf(stderr, "Error opening magnetometer I2C device: %d\n", mag_handle);
        return -1;
    }

    // Set MR_REG_M to 0x00 (Continuous-conversion mode)
    if (i2cWriteByteData(mag_handle, MR_REG_M, 0x00) != 0) {
        fprintf(stderr, "Error writing to MR_REG_M\n");
        i2cClose(mag_handle);
        return -1;
    }

    return 0;
}

// Read accelerometer data
int read_accelerometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(accel_handle, OUT_X_L_A | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Read magnetometer data
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(mag_handle, OUT_X_H_M, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Calculate tilt-compensated heading
void calculate_heading(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t mag_x, int16_t mag_y, int16_t mag_z, float *heading) {
    // Convert accelerometer data to g
    float accel_x_g = (float)accel_x / 16384.0f; // Assuming +/- 2g range
    float accel_y_g = (float)accel_y / 16384.0f;
    float accel_z_g = (float)accel_z / 16384.0f;

    // Convert magnetometer data to Gauss
    float mag_x_gauss = (float)mag_x / 1090.0f; // Assuming +/- 1.3 Gauss range
    float mag_y_gauss = (float)mag_y / 1090.0f;
    float mag_z_gauss = (float)mag_z / 1090.0f;

    // Calculate pitch and roll
    float pitch = atan2(accel_x_g, sqrt(accel_y_g * accel_y_g + accel_z_g * accel_z_g)) * 180 / M_PI;
    float roll = atan2(accel_y_g, sqrt(accel_x_g * accel_x_g + accel_z_g * accel_z_g)) * 180 / M_PI;

    // Calculate heading
    float heading_rad = atan2(mag_y_gauss * cos(pitch) + mag_z_gauss * sin(pitch), mag_x_gauss * cos(roll) - mag_y_gauss * sin(roll) + mag_z_gauss * cos(pitch) * cos(roll) + sin(pitch) * sin(roll)) * 180 / M_PI;

    // Adjust to 0-360 degrees
    if (heading_rad < 0) {
        heading_rad += 360;
    }

    *heading = heading_rad;
}

// Log data to file
void log_data(float heading, int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t mag_x, int16_t mag_y, int16_t mag_z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    fprintf(log_file, "%.6f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            timestamp, heading, accel_x / 16384.0f, accel_y / 16384.0f, accel_z / 16384.0f, mag_x / 1090.0f, mag_y / 1090.0f, mag_z / 1090.0f);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, shutting down...\n", signal);

    // Close I2C handles
    if (accel_handle >= 0) {
        i2cClose(accel_handle);
    }
    if (mag_handle >= 0) {
        i2cClose(mag_handle);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

