#include <time.h>
#include <signal.h>
#include <string.h>

// Define sensor I2C addresses
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69

// Define I2C bus
#define I2C_BUS 1

// Define control register value to enable continuous measurement
#define CONTROL_REG_VALUE 0x80

// Define sampling interval (10 ms)
#define SAMPLING_INTERVAL_US 10000

// Define the number of samples to read
#define NUM_SAMPLES 100

// Global variables for I2C handles and log file
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Close I2C handles if they are open
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }

    // Close log file if it is open
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to initialize the I2C bus and sensor
int initialize_sensor(int i2c_bus, int i2c_address) {
    int handle = i2cOpen(i2c_bus, i2c_address, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", i2c_address, handle);
        return -1;
    }

    // Write to control register to enable continuous measurement
    if (i2cWriteByteData(handle, 0x00, CONTROL_REG_VALUE) < 0) {
        fprintf(stderr, "Error writing to control register at address 0x%02x\n", i2c_address);
        i2cClose(handle);
        return -1;
    }

    return handle;
}

// Function to read a 16-bit signed audio sample from the sensor
int16_t read_audio_sample(int i2c_handle) {
    char buffer[2];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, 0x01, buffer, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Error reading audio sample: %d\n", bytes_read);
        return 0; // Return 0 on error
    }

    // Combine the two bytes into a 16-bit signed integer
    int16_t sample = (int16_t)((buffer[0] << 8) | buffer[1]);
    return sample;
}

// Function to calculate the Time Difference of Arrival (TDOA)
int16_t calculate_tdoa(int16_t sample1, int16_t sample2) {
    return sample1 - sample2;
}

// Function to log the data to a CSV file
void log_data(FILE *log_file, struct timespec ts, int16_t sensor1_sample, int16_t sensor2_sample, int16_t tdoa) {
    fprintf(log_file, "%ld.%09ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, sensor1_sample, sensor2_sample, tdoa);
    fflush(log_file); // Ensure data is written to disk immediately
}

