    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize the sensors
    i2c_handle1 = initialize_sensor(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = initialize_sensor(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("audio_log.dat", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        struct timespec ts;
        int16_t sensor1_sample, sensor2_sample, tdoa;

        // Read audio samples from both sensors
        sensor1_sample = read_audio_sample(i2c_handle1);
        sensor2_sample = read_audio_sample(i2c_handle2);

        // Calculate TDOA
        tdoa = calculate_tdoa(sensor1_sample, sensor2_sample);

        // Get timestamp
