#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// ADIS16488A Register Addresses
#define X_GYRO 0x04
#define Y_GYRO 0x06
#define Z_GYRO 0x08
#define X_ACCEL 0x0A
#define Y_ACCEL 0x0C
#define Z_ACCEL 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3
#define SPI_FLAGS 0b11000000000 // CPHA=1, CPOL=1, Aux SPI off

// Global Variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t running = 1;

// Structure to hold IMU data
typedef struct {
    float gyro_x;
    float gyro_y;
    float gyro_z;
    float accel_x;
    float accel_y;
    float accel_z;
} imu_data_t;

// Function Prototypes
int initialize();
int read_register(int reg_addr, int *data);
imu_data_t read_imu_data();
void log_data(imu_data_t data);
void cleanup();
void signal_handler(int signal);

// Helper function to get current timestamp in milliseconds
long long get_timestamp_ms() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (long long)(ts.tv_sec * 1000LL + ts.tv_nsec / 1000000);
}

int main() {
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return 1;
    }

    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    while (running) {
        imu_data_t data = read_imu_data();
        log_data(data);
        gpioDelay(100); // 100 ms delay
    }

    cleanup();
    return 0;
}

int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE | SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    fp = fopen("imu_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open imu_data.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to CSV file
    fprintf(fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");

    return 0;
}

int read_register(int reg_addr, int *data) {
    char tx_buf[2];
    char rx_buf[2];

    // Construct the transmit buffer
    tx_buf[0] = (reg_addr << 1) | 0x8000; // MSB = 0 for write, register address
    tx_buf[1] = 0x0000; // Dummy data for reading

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) < 0) {
        fprintf(stderr, "SPI transfer failed for register 0x%04X\n", reg_addr);
        return -1;
    }

    // The data is returned in the second 16-bit word of rx_buf
    *data = ((rx_buf[0] & 0xFF) << 8) | (rx_buf[1] & 0xFF);

    return 0;
}

imu_data_t read_imu_data() {
    imu_data_t data;
    int raw_gyro_x, raw_gyro_y, raw_gyro_z, raw_accel_x, raw_accel_y, raw_accel_z;

    // Read gyroscope data
    if (read_register(X_GYRO, &raw_gyro_x) != 0) {
        fprintf(stderr, "Error reading gyro X\n");
        data.gyro_x = 0.0;
    } else {
        data.gyro_x = (float)raw_gyro_x * 0.005; // Convert to degrees/second
    }

    if (read_register(Y_GYRO, &raw_gyro_y) != 0) {
        fprintf(stderr, "Error reading gyro Y\n");
        data.gyro_y = 0.0;
    } else {
        data.gyro_y = (float)raw_gyro_y * 0.005; // Convert to degrees/second
    }

    if (read_register(Z_GYRO, &raw_gyro_z) != 0) {
        fprintf(stderr, "Error reading gyro Z\n");
        data.gyro_z = 0.0;
    } else {
        data.gyro_z = (float)raw_gyro_z * 0.005; // Convert to degrees/second
    }

    // Read accelerometer data
    if (read_register(X_ACCEL, &raw_accel_x) != 0) {
        fprintf(stderr, "Error reading accel X\n");
        data.accel_x = 0.0;
    } else {
        data.accel_x = (float)raw_accel_x * 0.00025; // Convert to g's
    }

    if (read_register(Y_ACCEL, &raw_accel_y) != 0) {
        fprintf(stderr, "Error reading accel Y\n");
        data.accel_y = 0.0;
    } else {
        data.accel_y = (float)raw_accel_y * 0.00025; // Convert to g's
    }

    if (read_register(Z_ACCEL, &raw_accel_z) != 0) {
        fprintf(stderr, "Error reading accel Z\n");
        data.accel_z = 0.0;
    } else {
        data.accel_z = (float)raw_accel_z * 0.00025; // Convert to g's
    }

    return data;
}

void log_data(imu_data_t data) {
    long long timestamp = get_timestamp_ms();
    fprintf(fp, "%lld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            timestamp, data.gyro_x, data.gyro_y, data.gyro_z, data.accel_x, data.accel_y, data.accel_z);
    fflush(fp); // Ensure data is written to file immediately
}

void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

void signal_handler(int signal) {
    printf("Signal received (%d).  Stopping...\n", signal);
    running = 0;
}

