// ADIS16448 Register Addresses
#define X_GYRO_OUT 0x04
#define Y_GYRO_OUT 0x06
#define Z_GYRO_OUT 0x08
#define X_ACCL_OUT 0x0A
#define Y_ACCL_OUT 0x0C
#define Z_ACCL_OUT 0x0E

// Scaling factors
#define GYRO_SCALE 0.05 // deg/sec/LSB
#define ACCL_SCALE 0.00025 // g/LSB

int spi_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Cleaning up...\n");
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

// Function to read data from ADIS16448
int read_adis16448(int spi_handle, unsigned char reg_addr, float *gyro_x, float *gyro_y, float *gyro_z, float *accel_x, float *accel_y, float *accel_z) {
    char tx_buf[2];
    char rx_buf[2];
    int status;

    // Construct the transmit buffer (register address with bit 15 set)
    tx_buf[0] = reg_addr | 0x8000; // Set MSB for read operation
    tx_buf[1] = 0x0000; // Dummy byte for clocking out data

    // Perform the SPI transfer
    status = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (status != 0) {
        fprintf(stderr, "Error during SPI transfer: %d\n", status);
        return -1; // Indicate failure
    }

    // Extract the 16-bit data from the receive buffer
    int16_t raw_gyro_x = (rx_buf[0] << 8) | rx_buf[1];
    int16_t raw_gyro_y = (rx_buf[0] << 8) | rx_buf[1];
    int16_t raw_gyro_z = (rx_buf[0] << 8) | rx_buf[1];
    int16_t raw_accel_x = (rx_buf[0] << 8) | rx_buf[1];
    int16_t raw_accel_y = (rx_buf[0] << 8) | rx_buf[1];
    int16_t raw_accel_z = (rx_buf[0] << 8) | rx_buf[1];

    // Convert raw data to physical units
    *gyro_x = (float)raw_gyro_x * GYRO_SCALE;
    *gyro_y = (float)raw_gyro_y * GYRO_SCALE;
    *gyro_z = (float)raw_gyro_z * GYRO_SCALE;
    *accel_x = (float)raw_accel_x * ACCL_SCALE;
    *accel_y = (float)raw_accel_y * ACCL_SCALE;
    *accel_z = (float)raw_accel_z * ACCL_SCALE;

    return 0; // Indicate success
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure SPI clock
    gpioCfgClock(5, 1, 0); // 5us sample rate

    // Open SPI channel 0 (CE0/GPIO8) at 1 MHz, SPI Mode 0
    spi_handle = spiOpen(0, 1000000, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

    // Main loop
    while (1) {
        // Read gyroscope data
        if (read_adis16448(spi_handle, X_GYRO_OUT, &gyro_x, &gyro_y, &gyro_z, NULL, NULL, NULL) != 0) {
            fprintf(stderr, "Error reading gyro data\n");
        }

        // Read accelerometer data
        if (read_adis16448(spi_handle, X_ACCL_OUT, NULL, NULL, NULL, &accel_x, &accel_y, &accel_z) != 0) {
            fprintf(stderr, "Error reading accel data\n");
        }

        // Print the data
        printf("Gyro: X=%.2f, Y=%.2f, Z=%.2f  Accel: X=%.4f, Y=%.4f, Z=%.4f\n",
               gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        // Wait 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // The following lines will never be reached due to the infinite loop.
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

