#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <time.h>

// MPU-6886 I2C address
#define MPU6886_ADDR 0x68

// MPU-6886 Registers
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

// I2C device path
#define I2C_DEVICE "/dev/i2c-1"

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from an I2C register
int i2c_read_reg(int fd, unsigned char reg) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2c_smbus_read_byte_data(fd, reg);
        if (result >= 0) {
            return result;
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X): %s. Retrying...\n", reg, strerror(errno));
            retries--;
            usleep(10000); // 10ms delay
        }
    }
    fprintf(stderr, "I2C read failed after multiple retries (reg 0x%02X).\n", reg);
    return -1; // Indicate failure
}

// Function to write a single byte to an I2C register
int i2c_write_reg(int fd, unsigned char reg, unsigned char value) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2c_smbus_write_byte_data(fd, reg, value);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error (reg 0x%02X, value 0x%02X): %s. Retrying...\n", reg, value, strerror(errno));
            retries--;
            usleep(10000); // 10ms delay
        }
    }
    fprintf(stderr, "I2C write failed after multiple retries (reg 0x%02X, value 0x%02X).\n", reg, value);
    return -1; // Indicate failure
}

// Function to verify the sensor is present
int verify_sensor(int fd) {
    int who_am_i = i2c_read_reg(fd, WHO_AM_I);
    if (who_am_i != 0x86) {
        fprintf(stderr, "MPU-6886 not found. WHO_AM_I returned 0x%02X\n", who_am_i);
        return 0; // Sensor not found
    }
    return 1; // Sensor found
}

// Function to initialize the MPU-6886
int initialize_mpu6886(int fd) {
    // Wake up the sensor
    if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Failed to wake up MPU-6886\n");
        return 0;
    }
    usleep(100000); // Wait for sensor to wake up

    // Set accelerometer range to +-2g
    if (i2c_write_reg(fd, 0x1C, 0x00) != 0) {
        fprintf(stderr, "Failed to set accelerometer range\n");
        return 0;
    }

    // Set gyroscope range to +-250 dps
    if (i2c_write_reg(fd, 0x1B, 0x00) != 0) {
        fprintf(stderr, "Failed to set gyroscope range\n");
        return 0;
    }

    return 1;
}

// Function to read accelerometer and gyroscope data
