// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from an I2C register
int i2c_read_reg(int fd, unsigned char reg) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2c_smbus_read_byte_data(fd, reg);
        if (result >= 0) {
            return result;
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X): %s. Retrying...\n", reg, strerror(errno));
            retries--;
            usleep(10000); // 10ms delay
        }
    }
    fprintf(stderr, "I2C read failed after multiple retries (reg 0x%02X).\n", reg);
    return -1; // Indicate failure
}

// Function to write a single byte to an I2C register
int i2c_write_reg(int fd, unsigned char reg, unsigned char value) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2c_smbus_write_byte_data(fd, reg, value);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error (reg 0x%02X, value 0x%02X): %s. Retrying...\n", reg, value, strerror(errno));
            retries--;
            usleep(10000); // 10ms delay
