            fprintf(stderr, "Error reading acceleration data. Retrying...\n");
        }

        // Delay for 10 ms
        gpioDelay(10000); // Delay in microseconds
    }

    // Clean up resources
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

