#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MMA8451Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define WHO_AM_I_VALUE 0x1A
#define CTRL_REG1 0x2A
#define XYZ_DATA_CFG 0x0E
#define OUT_X_MSB 0x01
#define LED_CHIP "/dev/gpiochip0"
#define LED_PIN 17
#define THRESHOLD 2.0f
#define DEFAULT_RANGE 2.0f
#define DEFAULT_LOW_POWER 0x00
#define DEFAULT_HYSTERESIS 0x00

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *led_chip = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *bus, int addr);
int verify_sensor(int fd);
int init_accelerometer(int fd);
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
int init_gpio(const char *chip, int pin);
int set_led_state(int gpio, int state);
int log_impact(float x, float y, float z);
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Initialize I2C bus
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// Verify sensor identity
int verify_sensor(int fd) {
    uint8_t who_am_i;
    if (i2c_smbus_read_byte_data(fd, WHO_AM_I_REG) < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }
    who_am_i = i2c_smbus_read_byte_data(fd, WHO_AM_I_REG);
    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I value mismatch: expected 0x%02X, got 0x%02X\n", WHO_AM_I_VALUE, who_am_i);
        return -1;
    }
    return 0;
}

// Initialize accelerometer
int init_accelerometer(int fd) {
    uint8_t config = DEFAULT_HYSTERESIS; // Enable interrupt on X, Y, Z

    // Set CTRL_REG1: Active mode, 100 Hz ODR
    if (i2c_smbus_write_byte_data(fd, CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Set XYZ_DATA_CFG: +/- 2g range
    if (i2c_smbus_write_byte_data(fd, XYZ_DATA_CFG, 0x00) < 0) {
        fprintf(stderr, "Error writing to XYZ_DATA_CFG\n");
        return -1;
    }

    return 0;
}

// Read acceleration data
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    if (i2c_smbus_read_i2c_block_data(fd, OUT_X_MSB, 6, (char *)data) < 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    *x = (int16_t)((data[0] << 8) | data[1]);
    *y = (int16_t)((data[2] << 8) | data[3]);
    *z = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

// Calculate magnitude of acceleration
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / 1024.0f * DEFAULT_RANGE;
    float y_g = (float)y / 1024.0f * DEFAULT_RANGE;
    float z_g = (float)z / 1024.0f * DEFAULT_RANGE;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Initialize GPIO line
int init_gpio(const char *chip, int pin) {
    led_chip = gpiod_chip_open_by_name(chip);
    if (!led_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    led_line = gpiod_chip_get_line(led_chip, pin);
    if (!led_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(led_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "accelerometer_impact_detection";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(led_line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(led_chip);
        return -1;
    }

    return 0;
}

// Set LED state
int set_led_state(int gpio, int state) {
    if (gpiod_line_set_value(led_line, state) < 0) {
        perror("Error setting LED state");
        return -1;
    }
    return 0;
}

// Log impact to file
int log_impact(float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s - Impact detected: X=%.2f g, Y=%.2f g, Z=%.2f g\n", timestamp, x, y, z);
    fflush(log_file);
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, MMA8451Q_ADDR);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    // Verify sensor
    if (verify_sensor(i2c_fd) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize accelerometer
    if (init_accelerometer(i2c_fd) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    if (init_gpio(LED_CHIP, LED_PIN) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        set_led_state(led_pin, 0);
        gpiod_chip_close(led_chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    int16_t x, y, z;
    float magnitude;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check for impact
            if (magnitude > THRESHOLD) {
                // Turn on LED
                set_led_state(led_pin, 1);

                // Log impact
                log_impact((float)x / 1024.0f * DEFAULT_RANGE, (float)y / 1024.0f * DEFAULT_RANGE, (float)z / 1024.0f * DEFAULT_RANGE);

                // Wait for 500 ms
                struct timespec sleep_time;
                sleep_time.tv_sec = 0;
                sleep_time.tv_nsec = 500000000; // 500 ms
                nanosleep(&sleep_time, NULL);

                // Turn off LED
                set_led_state(led_pin, 0);
            }
        } else {
            fprintf(stderr, "Error reading acceleration data, retrying...\n");
        }

        // Wait 100 ms
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 100 ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    set_led_state(led_pin, 0);
    fclose(log_file);
    gpiod_chip_close(led_chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

