        close(fd);
        return -1;
    }

    return fd;
}

// I2C read register function
int i2c_read_reg(int fd, unsigned char reg) {
    unsigned char buf[1];
    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    if (read(fd, buf, 1) != 1) {
        perror("Error reading from I2C device");
        return -1;
