#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27
#define OUTX_L_XL 0x28
#define OUTX_H_XL 0x29
#define OUTY_L_XL 0x2A
#define OUTY_H_XL 0x2B
#define OUTZ_L_XL 0x2C
#define OUTZ_H_XL 0x2D

// Configuration values
#define ODR_104HZ 0x60  // 104 Hz for both accelerometer and gyroscope
#define FS_2G 0x00      // +/- 2g for accelerometer
#define FS_250DPS 0x00  // +/- 250 dps for gyroscope

// Fall detection thresholds
#define FREEFALL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 2.5f
#define FREEFALL_TIME_WINDOW 1.0f

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyroscope_data_t;

// Function prototypes
int initialize_imu();
accelerometer_data_t read_accelerometer_data();
gyroscope_data_t read_gyroscope_data();
void log_data(accelerometer_data_t accel_data, gyroscope_data_t gyro_data);
void fall_detection(accelerometer_data_t accel_data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the LSM6DSR IMU
int initialize_imu() {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x69) {
        fprintf(stderr, "WHO_AM_I returned 0x%X, expected 0x69\n", who_am_i);
        return -1;
    }

    // Configure accelerometer
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, FS_2G | 0x50) < 0) { // ODR = 104 Hz, FS = +/-2g
        fprintf(stderr, "Error writing to CTRL1_XL register\n");
        return -1;
    }

    // Configure gyroscope
    if (i2cWriteByteData(i2c_handle, CTRL2_G, FS_250DPS | 0x50) < 0) { // ODR = 104 Hz, FS = +/-250 dps
        fprintf(stderr, "Error writing to CTRL2_G register\n");
        return -1;
    }

    return 0;
}

// Read accelerometer data
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t accel_data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_XL, buffer, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        accel_data.x = 0.0f;
        accel_data.y = 0.0f;
        accel_data.z = 0.0f;
        return accel_data;
    }

    int16_t x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert to g (assuming +/- 2g range)
    accel_data.x = (float)x / 16384.0f;
    accel_data.y = (float)y / 16384.0f;
    accel_data.z = (float)z / 16384.0f;

    return accel_data;
}

// Read gyroscope data
gyroscope_data_t read_gyroscope_data() {
    gyroscope_data_t gyro_data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 6) < 0) {
        fprintf(stderr, "Error reading gyroscope data\n");
        gyro_data.x = 0.0f;
        gyro_data.y = 0.0f;
        gyro_data.z = 0.0f;
        return gyro_data;
    }

    int16_t x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert to dps (assuming +/- 250 dps range)
    gyro_data.x = (float)x / 131.0f;
    gyro_data.y = (float)y / 131.0f;
    gyro_data.z = (float)z / 131.0f;

    return gyro_data;
}

// Log data to CSV file
void log_data(accelerometer_data_t accel_data, gyroscope_data_t gyro_data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, accel_data.x, accel_data.y, accel_data.z, gyro_data.x, gyro_data.y, gyro_data.z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Fall detection state machine
void fall_detection(accelerometer_data_t accel_data) {
    static time_t freefall_start_time = 0;
    static int freefall_state = IDLE;
    float magnitude;

    magnitude = sqrt(accel_data.x * accel_data.x + accel_data.y * accel_data.y + accel_data.z * accel_data.z);

    switch (freefall_state) {
        case IDLE:
            if (magnitude < FREEFALL_THRESHOLD) {
                freefall_state = FREEFALL;
                freefall_start_time = time(NULL);
            }
            break;
        case FREEFALL:
            if (magnitude > FREEFALL_THRESHOLD) {
                freefall_state = IDLE;
            } else if (time(NULL) - freefall_start_time > FREEFALL_TIME_WINDOW) {
                freefall_state = IDLE;
            }
            break;
        case IMPACT:
            if (magnitude > IMPACT_THRESHOLD) {
                freefall_state = IDLE;
            }
            break;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize IMU
    if (initialize_imu() < 0) {
        fprintf(stderr, "IMU initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        accelerometer_data_t accel_data = read_accelerometer_data();
        gyroscope_data_t gyro_data = read_gyroscope_data();

        // Log data
        log_data(accel_data, gyro_data);

        // Fall detection
        fall_detection(accel_data);

        // Delay for 10 ms (104 Hz ODR)
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

