// ADIS16266 Register Addresses
#define X_GYRO_OUT 0x14
#define WHO_AM_I 0x02

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3
#define SPI_CE 8 // Chip Enable pin (GPIO8)

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t address, uint16_t *data);
int spi_write_register(int handle, uint8_t address, uint16_t data);
float scale_gyro_data(int16_t raw_data);
void log_data(float angular_rate);
void signal_handler(int signal);
int verify_device_id(int handle);

// Structure for SPI configuration (optional)
typedef struct {
    int channel;
    int speed;
    int mode;
    int ce_pin;
} spi_config_t;

// Function to read a register from the ADIS16266
int spi_read_register(int handle, uint8_t address, uint16_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = address | 0x80; // Set MSB for read
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;

    if (spiXfer(handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "SPI read failed\n");
        return -1;
    }

    *data = (rx_buf[1] << 8) | rx_buf[2];
    return 0;
}

// Function to write a register in the ADIS16266
int spi_write_register(int handle, uint8_t address, uint16_t data) {
    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = address & 0x7F; // Clear MSB for write
    tx_buf[1] = (data >> 8) & 0xFF;
    tx_buf[2] = data & 0xFF;

    if (spiXfer(handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "SPI write failed\n");
        return -1;
    }

    return 0;
}

// Function to scale the raw gyroscope data
float scale_gyro_data(int16_t raw_data) {
    return (float)raw_data * 0.0305;
}

// Function to log the angular rate data to a file
void log_data(float angular_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f\n", timestamp, angular_rate);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to verify the device ID
int verify_device_id(int handle) {
    uint16_t who_am_i_data;
    if (spi_read_register(handle, WHO_AM_I, &who_am_i_data) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i_data != 0x3F5A) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%X (expected 0x3F5A)\n", who_am_i_data);
        return -1;
    }

    printf("WHO_AM_I verification successful\n");
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure SPI
    spi_config_t spi_config = {
        .channel = SPI_CHANNEL,
        .speed = SPI_SPEED,
        .mode = SPI_MODE,
        .ce_pin = SPI_CE
    };

    spi_handle = spiOpen(spi_config.channel, spi_config.speed, spi_config.mode);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Verify device ID
    if (verify_device_id(spi_handle) != 0) {
        fprintf(stderr, "Device ID verification failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,AngularRate(deg/s)\n");
    }
    rewind(log_file);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        uint16_t raw_data;
        if (spi_read_register(spi_handle, X_GYRO_OUT, &raw_data) == 0) {
            int16_t scaled_data = (int16_t)raw_data; // Cast to signed 16-bit
            float angular_rate = scale_gyro_data(scaled_data);
            log_data(angular_rate);
        } else {
            fprintf(stderr, "Failed to read X_GYRO_OUT\n");
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

