#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// GY-50 L3G4200D I2C address
#define GYRO_ADDR 0x69

// GY-50 L3G4200D register addresses
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28

// Full-scale range and sensitivity
#define FULL_SCALE_250_DPS 0x00
#define SENSITIVITY 8.75f // mdps/LSB

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gyro();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
void convert_to_dps(int16_t x_raw, int16_t y_raw, int16_t z_raw, float *x_dps, float *y_dps, float *z_dps);
void log_data(float x_dps, float y_dps, float z_dps);
void signal_handler(int signal);

// Signal handler for graceful termination
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the GY-50 L3G4200D gyroscope
int init_gyro() {
    int retries = 3;
    int status;

    // Set CTRL_REG1 to normal mode with all axes enabled
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F);
        if (status >= 0) {
            break;
        } else {
            fprintf(stderr, "Error writing to CTRL_REG1 (attempt %d): %d\n", 4 - retries, status);
            gpioDelay(1000); // Wait 1 ms before retrying
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1 after multiple retries.\n");
        return -1;
    }

    // Set CTRL_REG4 to +-250 dps full-scale range
    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, CTRL_REG4, FULL_SCALE_250_DPS);
        if (status >= 0) {
            break;
        } else {
            fprintf(stderr, "Error writing to CTRL_REG4 (attempt %d): %d\n", 4 - retries, status);
            gpioDelay(1000); // Wait 1 ms before retrying
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4 after multiple retries.\n");
        return -1;
    }

    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, 0x0F);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0xD3) {
        fprintf(stderr, "WHO_AM_I register returned 0x%X, expected 0xD3\n", who_am_i);
        return -1;
    }

    return 0;
}

// Read gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading gyro data: %d\n", status);
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Convert raw data to degrees per second
void convert_to_dps(int16_t x_raw, int16_t y_raw, int16_t z_raw, float *x_dps, float *y_dps, float *z_dps) {
    *x_dps = (float)x_raw / 114.285f;
    *y_dps = (float)y_raw / 114.285f;
    *z_dps = (float)z_raw / 114.285f;
}

// Log data to file
void log_data(float x_dps, float y_dps, float z_dps) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ns = (long)ts.tv_sec * 1000000000LL + ts.tv_nsec;

    fprintf(log_file, "%ld,%.2f,%.2f,%.2f\n", timestamp_ns, x_dps, y_dps, z_dps);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, GYRO_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the gyroscope
    if (init_gyro() != 0) {
        fprintf(stderr, "Gyro initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,X,Y,Z\n");

    // Register signal handler for graceful termination
    signal(SIGINT, signal_handler);

    int16_t x_raw, y_raw, z_raw;
    float x_dps, y_dps, z_dps;

    // Main loop
    while (!terminate) {
        if (read_gyro_data(&x_raw, &y_raw, &z_raw) == 0) {
            convert_to_dps(x_raw, y_raw, z_raw, &x_dps, &y_dps, &z_dps);
            log_data(x_dps, y_dps, z_dps);
        } else {
            fprintf(stderr, "Failed to read gyro data. Retrying...\n");
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Clean up resources before exiting
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

