#define GPIO_PIN 17
#define LOG_FILE "flame_events.log"

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

int main() {
    FILE *log_file = NULL;
    int flame_detected;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read sensor value
        flame_detected = gpioRead(GPIO_PIN);

        if (flame_detected >= 0) {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log event to file
            fprintf(log_file, "%s - Flame detected: %s\n", timestamp, flame_detected == 0 ? "YES" : "NO");
            fflush(log_file); // Ensure immediate write

            // Print to console if flame detected
            if (flame_detected == 0) {
                printf("FLAME DETECTED!\n");
            }
        } else {
            // Log error to file
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "%s - ERROR: Failed to read sensor value\n", timestamp);
            fflush(log_file);
        }

        // Wait 500 ms
        gpioDelay(500);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

