#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define D7S_ADDR 0x53
#define SAMPLE_INTERVAL_MS 100

// Function pointer type for error handling
typedef void (*error_handler_t)(const char *message);

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

// Error handling function
void default_error_handler(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Signal handler for Ctrl+C
void signal_handler(int signum) {
    if (signum == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
    }
}

// Function to read acceleration data from the sensor
int read_acceleration(int fd, int reg, short *data) {
    unsigned char buf[2];
    int result;

    result = read(fd, buf, 2);
    if (result != 2) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1; // Indicate failure
    }

    *data = (short)((buf[1] << 8) | buf[0]);
    return 0; // Indicate success
}

// Function to log data to a CSV file
void log_data(FILE *fp, short x, short y, short z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(fp); // Ensure data is written to disk immediately
}

int main() {
    error_handler_t error_handler = default_error_handler; // Use default error handler

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        error_handler("Failed to open I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, D7S_ADDR) < 0) {
        error_handler("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.csv", "a");
    if (log_file == NULL) {
        error_handler("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    short x, y, z;

    // Main loop
    while (program_running) {
        // Read acceleration data
        if (read_acceleration(i2c_fd, 0x28, &x) != 0) {
            error_handler("Failed to read X acceleration");
            continue; // Skip to the next iteration
        }
        if (read_acceleration(i2c_fd, 0x2A, &y) != 0) {
            error_handler("Failed to read Y acceleration");
            continue;
        }
        if (read_acceleration(i2c_fd, 0x2C, &z) != 0) {
            error_handler("Failed to read Z acceleration");
            continue;
        }

        // Log data
        log_data(log_file, x, y, z);

        // Wait for the next sample
        usleep(SAMPLE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Close I2C bus and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

