#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIOCHIP "gpiochip0"
#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define LOG_FILE "conveyor_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *sensor1_line;
static struct gpiod_line *sensor2_line;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize the GPIO lines
int initialize_gpio() {
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!sensor1_line) {
        perror("Error getting sensor 1 line");
        gpiod_chip_close(chip);
        return -1;
    }

    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!sensor2_line) {
        perror("Error getting sensor 2 line");
        gpiod_chip_close(chip);
        gpiod_line_release(sensor1_line);
        return -1;
    }

    if (gpiod_line_request_input(sensor1_line, "conveyor_sensor1") < 0) {
        perror("Error requesting sensor 1 line as input");
        gpiod_chip_close(chip);
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        return -1;
    }

    if (gpiod_line_request_input(sensor2_line, "conveyor_sensor2") < 0) {
        perror("Error requesting sensor 2 line as input");
        gpiod_chip_close(chip);
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        return -1;
    }

    return 0;
}

// Function to read sensor values
int read_sensors(int *sensor1_value, int *sensor2_value) {
    int ret1, ret2;

    ret1 = gpiod_line_get_value(sensor1_line);
    if (ret1 < 0) {
        perror("Error reading sensor 1 value");
        return -1;
    }
    *sensor1_value = ret1;

    ret2 = gpiod_line_get_value(sensor2_line);
    if (ret2 < 0) {
        perror("Error reading sensor 2 value");
        return -1;
    }
    *sensor2_value = ret2;

    return 0;
}

// Function to log data to file
int log_data(int sensor1_value, int sensor2_value) {
    struct timespec ts;
    char timestamp[30];
    struct tm tm_info;

    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("Error getting current time");
        return -1;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    fprintf(log_file, "%s, Sensor1: %d, Sensor2: %d\n", timestamp, sensor1_value, sensor2_value);
    fflush(log_file);

    return 0;
}

// Function to check for both sensors being triggered
void check_sensors(int sensor1_value, int sensor2_value) {
    if (sensor1_value == 1 && sensor2_value == 1) {
        printf("Conveyor belt stopped!\n");
    }
}

// Function to cleanup resources
void cleanup() {
    if (sensor1_line) {
        gpiod_line_release(sensor1_line);
    }
    if (sensor2_line) {
        gpiod_line_release(sensor2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    int sensor1_value, sensor2_value;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (read_sensors(&sensor1_value, &sensor2_value) == 0) {
            log_data(sensor1_value, sensor2_value);
            check_sensors(sensor1_value, sensor2_value);
        } else {
            fprintf(stderr, "Error reading sensors. Retrying.\n");
        }

        usleep(50000); // 50 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

