// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int verify_sensor_id(int fd);
int initialize_sensor(int fd);
int read_accelerometer_data(int fd, int12_t *x, int12_t *y, int12_t *z);
float calculate_tilt_angle(int12_t x, int12_t y, int12_t z);
int log_data(FILE *fp, int12_t x, int12_t y, int12_t z);
void signal_handler(int sig);

// I2C read block function
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len) {
    if (ioctl(fd, I2C_SLAVE, reg) < 0) {
        perror("Error: i2c_slave");
        return -1;
    }

    int bytes_read = read(fd, data, len);
    if (bytes_read != len) {
        fprintf(stderr, "Error: i2c_read_block failed to read %d bytes, read %d\n", len, bytes_read);
        return -1;
    }
    return 0;
}

// I2C write byte function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Error: i2c_write_byte");
        return -1;
    }
    return 0;
}

// Verify sensor ID function
int verify_sensor_id(int fd) {
    uint8_t sensor_id;
    if (i2c_read_block(fd, WHO_AM_I_REG, &sensor_id, 1) != 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register\n");
        return -1;
    }

    if (sensor_id != 0x2A) {
        fprintf(stderr, "Error: Incorrect sensor ID: 0x%02X (expected 0x2A)\n", sensor_id);
        return -1;
    }

    printf("Sensor ID verified: 0x%02X\n", sensor_id);
    return 0;
}

// Initialize sensor function
int initialize_sensor(int fd) {
    // Set to standby mode
    if (i2c_write_byte(fd, CTRL_REG1, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to set standby mode\n");
        return -1;
    }
    usleep(10000); // Wait 10ms

    // Set data rate to 100 Hz
    if (i2c_write_byte(fd, CTRL_REG1, 0x02) != 0) {
        fprintf(stderr, "Error: Failed to set data rate\n");
        return -1;
    }
    usleep(10000); // Wait 10ms

    // Set to active mode
    if (i2c_write_byte(fd, CTRL_REG1, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to set active mode\n");
        return -1;
    }
    usleep(10000); // Wait 10ms

    return 0;
}

// Read accelerometer data function
int read_accelerometer_data(int fd, int12_t *x, int12_t *y, int12_t *z) {
    uint8_t data[6];
    if (i2c_read_block(fd, DATA_X_MSB, data, 6) != 0) {
        fprintf(stderr, "Error: Failed to read accelerometer data\n");
        return -1;
    }

    *x = (int12_t)((data[0] << 4) | (data[1] >> 4));
    *y = (int12_t)((data[2] << 4) | (data[3] >> 4));
    *z = (int12_t)((data[4] << 4) | (data[5] >> 4));

    return 0;
}

// Calculate tilt angle function
float calculate_tilt_angle(int12_t x, int12_t y, int12_t z) {
    float x_g = x * SENSITIVITY;
    float y_g = y * SENSITIVITY;
    float z_g = z * SENSITIVITY;

    float cos_theta = (x_g * x_g + y_g * y_g - z_g * z_g) / (x_g * x_g + y_g * y_g + z_g * z_g);
    float theta = acos(cos_theta);

    return theta * 180.0 / M_PI;
}

// Log data function
int log_data(FILE *fp, int12_t x, int12_t y, int12_t z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %d, %d, %d\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fflush(fp); // Ensure data is written to file immediately
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Failed to open I2C bus");
        return 1;
    }

    // Verify sensor ID
    if (verify_sensor_id(i2c_fd) != 0) {
        close(i2c_fd);
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor(i2c_fd) != 0) {
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error: Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    int12_t x, y, z;
    float tilt_angle;

    // Main loop
    while (program_running) {
        if (read_accelerometer_data(i2c_fd, &x, &y, &z) == 0) {
            tilt_angle = calculate_tilt_angle(x, y, z);

            if (fabs(tilt_angle) > 45.0) {
                log_data(log_file, x, y, z);
            }
        } else {
            fprintf(stderr, "Error: Failed to read accelerometer data in main loop\n");
        }

        usleep(10000); // 10 ms delay
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

