#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define LIS3MDL_ADDR 0x1E
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define CTRL_REG3 0x22
#define WHO_AM_I 0x0F
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define MAG_SENSITIVITY 0.146f // mG/LSB
#define METAL_THRESHOLD 800.0f  // mG

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;

// Calibration offsets (replace with your actual calibration values)
float x_offset = 0.0f;
float y_offset = 0.0f;
float z_offset = 0.0f;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int init_lis3mdl(int fd);
int read_magnetometer(int fd, float *x, float *y, float *z);
void log_data(float x, float y, float z);
void check_threshold(float x, float y, float z);
void signal_handler(int sig);

// I2C read function with retry
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    int retries = 3;
    int delay_ms = 10;
    int result;

    while (retries > 0) {
        result = ioctl(fd, I2C_SLAVE, reg);
        if (result < 0) {
            perror("I2C_SLAVE ioctl failed");
            retries--;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
            continue;
        }

        result = read(fd, data, len);
        if (result == len) {
            return 0; // Success
        } else {
            perror("I2C read failed");
            retries--;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
        }
    }

    fprintf(stderr, "Failed to read from I2C after multiple retries.\n");
    return -1; // Failure
}

// I2C write function with retry
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    int retries = 3;
    int delay_ms = 10;
    int result;

    while (retries > 0) {
        result = ioctl(fd, I2C_SLAVE, reg);
        if (result < 0) {
            perror("I2C_SLAVE ioctl failed");
            retries--;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
            continue;
        }

        uint8_t buf[2];
        buf[0] = reg;
        buf[1] = value;
        result = write(fd, buf, 2);
        if (result == 2) {
            return 0; // Success
        } else {
            perror("I2C write failed");
            retries--;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
        }
    }

    fprintf(stderr, "Failed to write to I2C after multiple retries.\n");
    return -1; // Failure
}

// Initialize LIS3MDL sensor
int init_lis3mdl(int fd) {
    uint8_t who_am_i;

    // Verify WHO_AM_I register
    if (i2c_read_bytes(fd, WHO_AM_I, &who_am_i, 1) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register.\n");
        return -1;
    }

    if (who_am_i != 0x3D) {
        fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0x3D.\n", who_am_i);
        return -1;
    }

    // Configure CTRL_REG1 (Continuous conversion, 80 Hz ODR, high-performance mode)
    if (i2c_write_byte(fd, CTRL_REG1, 0x70) != 0) {
        fprintf(stderr, "Failed to write CTRL_REG1.\n");
        return -1;
    }

    // Configure CTRL_REG4 (Continuous conversion mode)
    if (i2c_write_byte(fd, CTRL_REG4, 0x0C) != 0) {
        fprintf(stderr, "Failed to write CTRL_REG4.\n");
        return -1;
    }

    // Configure CTRL_REG3 (Continuous conversion mode)
    if (i2c_write_byte(fd, CTRL_REG3, 0x00) != 0) {
        fprintf(stderr, "Failed to write CTRL_REG3.\n");
        return -1;
    }

    return 0;
}

// Read magnetometer data
int read_magnetometer(int fd, float *x, float *y, float *z) {
    uint8_t data[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2c_read_bytes(fd, OUT_X_L, data, 6) != 0) {
        fprintf(stderr, "Failed to read magnetometer data.\n");
        return -1;
    }

    // Combine high and low bytes, convert to signed 16-bit integer
    raw_x = (int16_t)((data[1] << 8) | data[0]);
    raw_y = (int16_t)((data[3] << 8) | data[2]);
    raw_z = (int16_t)((data[5] << 8) | data[4]);

    // Apply calibration offsets
    *x = (float)raw_x - x_offset;
    *y = (float)raw_y - y_offset;
