        if (result < 0) {
            perror("I2C_SLAVE ioctl failed");
            retries--;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
            continue;
        }

        uint8_t buf[2];
        buf[0] = reg;
        buf[1] = value;
        result = write(fd, buf, 2);
        if (result == 2) {
            return 0; // Success
        } else {
            perror("I2C write failed");
            retries--;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
        }
    }

