#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADXL354B Register Addresses
#define ADXL354B_RESET_REG 0x1F
#define ADXL354B_POWER_CTL 0x2D
#define ADXL354B_STATUS 0x04
#define ADXL354B_PARTID 0x01
#define ADXL354B_XDATA_L 0x08
#define ADXL354B_XDATA_H 0x09
#define ADXL354B_XDATA_M 0x0A
#define ADXL354B_YDATA_L 0x0B
#define ADXL354B_YDATA_H 0x0C
#define ADXL354B_YDATA_M 0x0D
#define ADXL354B_ZDATA_L 0x0E
#define ADXL354B_ZDATA_H 0x0F
#define ADXL354B_ZDATA_M 0x10

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int adxl354b_read_register(int reg_addr, uint8_t *data, int len);
int adxl354b_write_register(int reg_addr, uint8_t data);
int adxl354b_reset();
int adxl354b_set_measurement_mode();
int adxl354b_read_acceleration(float *x, float *y, float *z);
int adxl354b_check_sensor_presence();
void log_data(float x, float y, float z);
void signal_handler(int signal);

// Function to read data from an ADXL354B register
int adxl354b_read_register(int reg_addr, uint8_t *data, int len) {
    char tx_buf[1];
    char rx_buf[len + 1];
    int retries = 3;

    tx_buf[0] = reg_addr | 0x80; // Set MSB for read operation

    while (retries > 0) {
        if (spiXfer(spi_handle, tx_buf, rx_buf, len + 1) == len + 1) {
            memcpy(data, rx_buf + 1, len);
            return 0; // Success
        }
        fprintf(stderr, "SPI read error, retrying...\n");
        gpioDelay(1000); // 1 ms delay
        retries--;
    }

    fprintf(stderr, "SPI read failed after multiple retries.\n");
    return -1; // Failure
}

// Function to write data to an ADXL354B register
int adxl354b_write_register(int reg_addr, uint8_t data) {
    char tx_buf[2];
    char rx_buf[2];
    int retries = 3;

    tx_buf[0] = reg_addr & 0x7F; // Clear MSB for write operation
    tx_buf[1] = data;

    while (retries > 0) {
        if (spiXfer(spi_handle, tx_buf, rx_buf, 2) == 2) {
            return 0; // Success
        }
        fprintf(stderr, "SPI write error, retrying...\n");
        gpioDelay(1000); // 1 ms delay
        retries--;
    }

    fprintf(stderr, "SPI write failed after multiple retries.\n");
    return -1; // Failure
}

// Function to reset the ADXL354B
int adxl354b_reset() {
    if (adxl354b_write_register(ADXL354B_POWER_CTL, 0x52) != 0) {
        fprintf(stderr, "Failed to write reset command.\n");
        return -1;
    }
    gpioDelay(1000); // 1 ms delay
    return 0;
}

// Function to set the measurement mode
int adxl354b_set_measurement_mode() {
    if (adxl354b_write_register(ADXL354B_POWER_CTL, 0x00) != 0) {
        fprintf(stderr, "Failed to clear RUN bit.\n");
        return -1;
    }
    gpioDelay(1000); // 1 ms delay

    while (adxl354b_read_register(ADXL354B_STATUS, (uint8_t*)NULL, 1) != 0) {
        fprintf(stderr, "Waiting for STABLE bit to set...\n");
        gpioDelay(1000); // 1 ms delay
    }

    if (adxl354b_write_register(ADXL354B_POWER_CTL, 0x01) != 0) {
        fprintf(stderr, "Failed to set RUN bit.\n");
        return -1;
    }
    gpioDelay(1000); // 1 ms delay
    return 0;
}

// Function to read acceleration data
int adxl354b_read_acceleration(float *x, float *y, float *z) {
    uint8_t data[6];
    int16_t raw_x, raw_y, raw_z;

    if (adxl354b_read_register(ADXL354B_XDATA_L, data, 6) != 0) {
        fprintf(stderr, "Failed to read acceleration data.\n");
        return -1;
    }

    raw_x = (int16_t)((data[2] << 12) | (data[1] << 4) | (data[0] >> 4));
    raw_y = (int16_t)((data[5] << 12) | (data[4] << 4) | (data[3] >> 4));
    raw_z = (int16_t)((data[8] << 12) | (data[7] << 4) | (data[6] >> 4));

    *x = (float)raw_x * 0.0039; // +-2g range, 20-bit resolution
    *y = (float)raw_y * 0.0039;
    *z = (float)raw_z * 0.0039;

    return 0;
}

// Function to check sensor presence
int adxl354b_check_sensor_presence() {
    uint8_t partid;

    if (adxl354b_read_register(ADXL354B_PARTID, &partid, 1) != 0) {
        fprintf(stderr, "Failed to read PARTID.\n");
        return -1;
    }

    if (partid != 0x1D) {
        fprintf(stderr, "Incorrect PARTID: 0x%02X\n", partid);
        return -1;
    }

    printf("ADXL354B Part ID: 0x%02X\n", partid);
    return 0;
}

// Function to log data to a file
void log_data(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %.6f g, Y: %.6f g, Z: %.6f g\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    float x, y, z;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Check sensor presence
    if (adxl354b_check_sensor_presence() != 0) {
        fprintf(stderr, "Sensor check failed, exiting.\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Reset the sensor
    if (adxl354b_reset() != 0) {
        fprintf(stderr, "Sensor reset failed, exiting.\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set measurement mode
    if (adxl354b_set_measurement_mode() != 0) {
        fprintf(stderr, "Measurement mode setup failed, exiting.\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (adxl354b_read_acceleration(&x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data.\n");
        }
        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

