    return 0;
}

// Function to read acceleration data
int adxl354b_read_acceleration(float *x, float *y, float *z) {
    uint8_t data[6];
    int16_t raw_x, raw_y, raw_z;

    if (adxl354b_read_register(ADXL354B_XDATA_L, data, 6) != 0) {
        fprintf(stderr, "Failed to read acceleration data.\n");
        return -1;
    }

    raw_x = (int16_t)((data[2] << 12) | (data[1] << 4) | (data[0] >> 4));
    raw_y = (int16_t)((data[5] << 12) | (data[4] << 4) | (data[3] >> 4));
    raw_z = (int16_t)((data[8] << 12) | (data[7] << 4) | (data[6] >> 4));

    *x = (float)raw_x * 0.0039; // +-2g range, 20-bit resolution
    *y = (float)raw_y * 0.0039;
    *z = (float)raw_z * 0.0039;

    return 0;
}

// Function to check sensor presence
int adxl354b_check_sensor_presence() {
    uint8_t partid;

    if (adxl354b_read_register(ADXL354B_PARTID, &partid, 1) != 0) {
        fprintf(stderr, "Failed to read PARTID.\n");
        return -1;
    }

    if (partid != 0x1D) {
        fprintf(stderr, "Incorrect PARTID: 0x%02X\n", partid);
        return -1;
    }

    printf("ADXL354B Part ID: 0x%02X\n", partid);
    return 0;
}

// Function to log data to a file
void log_data(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %.6f g, Y: %.6f g, Z: %.6f g\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    float x, y, z;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Check sensor presence
    if (adxl354b_check_sensor_presence() != 0) {
        fprintf(stderr, "Sensor check failed, exiting.\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Reset the sensor
    if (adxl354b_reset() != 0) {
        fprintf(stderr, "Sensor reset failed, exiting.\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set measurement mode
    if (adxl354b_set_measurement_mode() != 0) {
        fprintf(stderr, "Measurement mode setup failed, exiting.\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (adxl354b_read_acceleration(&x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data.\n");
        }
        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
