#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// ADIS16362 Register Addresses
#define X_GYRO 0x04
#define Y_GYRO 0x06
#define Z_GYRO 0x08
#define X_ACCL 0x0A
#define Y_ACCL 0x0C
#define Z_ACCL 0x0E

// Scaling factors
#define GYRO_SCALE 0.05  // deg/sec/LSB
#define ACCL_SCALE 0.0025 // g/LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    float gyro_x, gyro_y, gyro_z;
    float accel_x, accel_y, accel_z;
} imu_data_t;

// Function prototypes
int init_spi();
int read_register(uint8_t reg_addr, int16_t *data);
imu_data_t read_imu_data();
void log_data(imu_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize SPI interface
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from a specific register
int read_register(uint8_t reg_addr, int16_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the transmit buffer: register address (MSB set) + dummy byte
    tx_buf[0] = (reg_addr | 0x80) << 8; // MSB set, dummy byte
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    // Transfer the data
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error during SPI transfer: %d\n", result);
        return -1;
    }

    // Extract the data from the receive buffer
    *data = (rx_buf[1] << 8) | rx_buf[2];

    return 0;
}

// Read IMU data
imu_data_t read_imu_data() {
    imu_data_t data;
    int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z;
    int16_t raw_accel_x, raw_accel_y, raw_accel_z;

    // Read gyroscope data
    if (read_register(X_GYRO, &raw_gyro_x) != 0) {
        data.gyro_x = 0.0;
    } else {
        data.gyro_x = (float)raw_gyro_x * GYRO_SCALE;
    }

    if (read_register(Y_GYRO, &raw_gyro_y) != 0) {
        data.gyro_y = 0.0;
    } else {
        data.gyro_y = (float)raw_gyro_y * GYRO_SCALE;
    }

    if (read_register(Z_GYRO, &raw_gyro_z) != 0) {
        data.gyro_z = 0.0;
    } else {
        data.gyro_z = (float)raw_gyro_z * GYRO_SCALE;
    }

    // Read accelerometer data
    if (read_register(X_ACCL, &raw_accel_x) != 0) {
        data.accel_x = 0.0;
    } else {
        data.accel_x = (float)raw_accel_x * ACCL_SCALE;
    }

    if (read_register(Y_ACCL, &raw_accel_y) != 0) {
        data.accel_y = 0.0;
    } else {
        data.accel_y = (float)raw_accel_y * ACCL_SCALE;
    }

    if (read_register(Z_ACCL, &raw_accel_z) != 0) {
        data.accel_z = 0.0;
    } else {
        data.accel_z = (float)raw_accel_z * ACCL_SCALE;
    }

    return data;
}

// Log data to file
void log_data(imu_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    // Get UNIX epoch timestamp with nanosecond precision
    long long timestamp = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;

    // Write to log file
    fprintf(log_file, "%lld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            timestamp, data.gyro_x, data.gyro_y, data.gyro_z,
            data.accel_x, data.accel_y, data.accel_z);
    fflush(log_file); // Ensure data is written immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("imu_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        imu_data_t imu_data = read_imu_data();
        log_data(imu_data);
        gpioDelay(10000); // 10 ms delay (100 Hz sampling rate)
    }

    // Clean up
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

