#include <pigpio.h>

#define GPIO_PIN 17
#define POLL_INTERVAL_SEC 1

static volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_status;
    int obstacle_detected;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    printf("Obstacle detection program started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read the GPIO pin value
        obstacle_detected = gpioRead(GPIO_PIN);

        if (obstacle_detected == 0) {
            // Obstacle detected
            printf("Self-parking sequence started\n");

            // Simulate self-parking sequence
            time(&current_time);
            time_info = localtime(&current_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);
            printf("%s: Self-parking sequence completed\n", timestamp);

            // Wait for 5 seconds
            gpioDelay(5000000); // 5 seconds in microseconds
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second in microseconds
    }

    // Clean up and exit
    gpioTerminate();
    printf("pigpio terminated.\n");
    return 0;
}

