#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip0"
#define SENSOR1_PIN 17
#define SENSOR2_PIN 27

static struct gpiod_chip *chip;
static struct gpiod_line *line17;
static struct gpiod_line *line27;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

int main() {
    struct timespec ts;
    int ret;
    int sensor1_value, sensor2_value;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Request GPIO lines for input
    line17 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!line17) {
        perror("Error getting GPIO line 17");
        gpiod_chip_close(chip);
        return 1;
    }

    line27 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!line27) {
        perror("Error getting GPIO line 27");
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request lines for input
    ret = gpiod_line_request_input_values(line17, "ir_sensor_1");
    if (ret < 0) {
        perror("Error requesting line 17 for input");
        gpiod_line_release(line17);
        gpiod_line_release(line27);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_input_values(line27, "ir_sensor_2");
    if (ret < 0) {
        perror("Error requesting line 27 for input");
        gpiod_line_release(line17);
        gpiod_line_release(line27);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor values
        ret = gpiod_line_get_value(line17);
        if (ret < 0) {
            perror("Error reading sensor 1");
            break;
        }
        sensor1_value = ret;

        ret = gpiod_line_get_value(line27);
        if (ret < 0) {
            perror("Error reading sensor 2");
            break;
        }
        sensor2_value = ret;

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            break;
        }

        // Log sensor data
        printf("%ld.%09ld: Sensor 17: %d, Sensor 27: %d\n", ts.tv_sec, ts.tv_nsec, sensor1_value, sensor2_value);

        // Delay
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 100 * 1000 * 1000; // 100 ms
        nanosleep(&delay, NULL);
    }

    // Release resources
    gpiod_line_release(line17);
    gpiod_line_release(line27);
    gpiod_chip_close(chip);

    return 0;
}

