        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            break;
        }

        // Log sensor data
        printf("%ld.%09ld: Sensor 17: %d, Sensor 27: %d\n", ts.tv_sec, ts.tv_nsec, sensor1_value, sensor2_value);

        // Delay
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 100 * 1000 * 1000; // 100 ms
        nanosleep(&delay, NULL);
    }

    // Release resources
    gpiod_line_release(line17);
    gpiod_line_release(line27);
    gpiod_chip_close(chip);

    return 0;
}

