#include <string.h>

// ADIS16266 Register Addresses
#define ADIS16266_REG_XGYRO_OUT 0x04
#define ADIS16266_REG_YGYRO_OUT 0x06
#define ADIS16266_REG_ZGYRO_OUT 0x08
#define ADIS16266_REG_MSC_CTRL  0x24

// SPI Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 3
#define SPI_BITS_PER_WORD 8
#define SPI_CLOCK_SPEED 1000000 // 1 MHz

// CS Pin
#define CS_PIN 8

// Global Variables
int spi_handle;
int cs_gpio;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function Prototypes
int initialize_spi();
int initialize_gpio();
int configure_adis16266();
int read_register(uint8_t reg_addr, int16_t *value);
gyro_data_t convert_raw_data(int16_t x, int16_t y, int16_t z);
void log_data(gyro_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to initialize the SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to initialize the GPIO pin for chip select
int initialize_gpio() {
    cs_gpio = gpioSetMode(CS_PIN, PI_OUTPUT);
    if (cs_gpio < 0) {
        fprintf(stderr, "Error setting GPIO mode: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to configure the ADIS16266
int configure_adis16266() {
    char tx_buf[3];
    char rx_buf[3];
    int16_t data;

    // Enable Data Ready Mode (MSB first)
    tx_buf[0] = ADIS16266_REG_MSC_CTRL | 0x80; // MSB set for write
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "Error writing to MSC_CTRL register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read a register from the ADIS16266
int read_register(uint8_t reg_addr, int16_t *value) {
    char tx_buf[3];
    char rx_buf[3];

    // Set MSB for read operation
    tx_buf[0] = reg_addr | 0x80; // MSB set for read
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    gpioWrite(cs_gpio, 0); // Assert CS
    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg_addr, strerror(errno));
        gpioWrite(cs_gpio, 1); // De-assert CS
        return -1;
    }
    gpioWrite(cs_gpio, 1); // De-assert CS

    *value = (rx_buf[1] << 8) | rx_buf[2];
    return 0;
}

