gyro_data_t convert_raw_data(int16_t x, int16_t y, int16_t z) {
    gyro_data_t data;
    data.x = x * 0.02;
    data.y = y * 0.02;
    data.z = z * 0.02;
    return data;
}

// Function to log the gyroscope data
void log_data(gyro_data_t data) {
    printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", data.x, data.y, data.z);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    spiClose(spi_handle);
    gpioWrite(cs_gpio, 1); // De-assert CS
    gpioTerminate();
}

