    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Configure ADIS16266
    if (configure_adis16266() != 0) {
        cleanup();
        return 1;
    }

    int16_t x, y, z;
    gyro_data_t gyro_data;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_register(ADIS16266_REG_XGYRO_OUT, &x) == 0 &&
            read_register(ADIS16266_REG_YGYRO_OUT, &y) == 0 &&
            read_register(ADIS16266_REG_ZGYRO_OUT, &z) == 0) {

            // Convert raw data to angular rates
            gyro_data = convert_raw_data(x, y, z);

            // Log the data
            log_data(gyro_data);
        } else {
            fprintf(stderr, "Error reading gyroscope data. Retrying...\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

