#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

#define GPIO_PIN 17
#define SAMPLE_INTERVAL_MS 1
#define SAMPLE_DURATION_S 5
#define WINDOW_DURATION_S 5

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

int main(int argc, char *argv[]) {
    int threshold = 0;
    int high_count = 0;
    int i;

    // Parse command-line argument
    if (argc > 1) {
        char *endptr;
        long val = strtol(argv[1], &endptr, 10);

        if (*endptr == '\0' && val > 0) {
            threshold = (int)val;
        } else {
            fprintf(stderr, "Error: Invalid threshold value.  Must be a positive integer.\n");
            return 1;
        }
    } else {
        threshold = 1; // Default threshold
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Monitoring noise levels... Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Sample GPIO for 5 seconds
        for (i = 0; i < SAMPLE_DURATION_S * 1000; ++i) {
            if (gpioRead(GPIO_PIN) == 1) {
                high_count++;
            }
            gpioDelay(SAMPLE_INTERVAL_MS);
        }

        // Check if threshold is exceeded
        if (high_count > threshold) {
            printf("ALERT: High noise level detected!\n");
        } else {
            printf("Normal: Noise level below threshold.\n");
        }

        // Reset high count
        high_count = 0;

        // Wait for 1 second before next window
        gpioDelay(WINDOW_DURATION_S * 1000);
    }

    // Terminate pigpio
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

