#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define DOOR_A_GPIO 17
#define DOOR_B_GPIO 27

// Define log file path
#define LOG_FILE "access_log.txt"

// Define code length
#define CODE_LENGTH 6

// Define unlock duration (seconds)
#define UNLOCK_DURATION 5

// Global variables
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int generate_code(int *code);
int validate_code(int code, int *user_code);
int unlock_door(int gpio_pin);
int log_access(int code);
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(DOOR_A_GPIO, PI_OUTPUT);
    gpioSetMode(DOOR_B_GPIO, PI_OUTPUT);

    gpioWrite(DOOR_A_GPIO, 0); // Ensure doors are locked initially
    gpioWrite(DOOR_B_GPIO, 0);

    return 0;
}

// Generate a random 6-digit code
int generate_code(int *code) {
    srand(time(NULL)); // Seed the random number generator
    for (int i = 0; i < CODE_LENGTH; i++) {
        code[i] = (rand() % 10); // Generate a random digit (0-9)
    }
    return 0;
}

// Validate the user's input code
int validate_code(int code, int *user_code) {
    if (strlen(user_code) != CODE_LENGTH) {
        fprintf(stderr, "Invalid code length. Please enter a 6-digit code.\n");
        return -1;
    }

    for (int i = 0; i < CODE_LENGTH; i++) {
        if (user_code[i] < 0 || user_code[i] > 9) {
            fprintf(stderr, "Invalid code. Please enter only digits (0-9).\n");
            return -1;
        }
    }

    return 0;
}

// Unlock a door by setting the corresponding GPIO pin HIGH for a specified duration
int unlock_door(int gpio_pin) {
    gpioWrite(gpio_pin, 1); // Set GPIO pin HIGH
    gpioDelay(UNLOCK_DURATION * 1000000); // Delay for unlock duration (in microseconds)
    gpioWrite(gpio_pin, 0); // Set GPIO pin LOW
