#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x21
#define MAX_RETRIES 3

volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

int set_i2c_slave_address(int fd, int address) {
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    return 0;
}

int write_i2c_byte(int fd, unsigned char data) {
    unsigned char buf[1];
    buf[0] = data;
    if (write(fd, buf, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

int read_i2c_bytes(int fd, unsigned char *data, int len) {
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

float calculate_lux(unsigned int raw_value) {
    return (float)raw_value / 1.2;
}

int log_data(FILE *fp, time_t timestamp, float lux) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp_str, lux) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);

    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    if (set_i2c_slave_address(i2c_fd, BH1750_ADDR) < 0) {
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("light_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    unsigned char data[2];
    unsigned int raw_value;
    float lux;
    time_t current_time;

    while (program_running) {
        current_time = time(NULL);

        // Write the high-resolution mode command
        if (write_i2c_byte(i2c_fd, BH1750_CONTINUOUS_HIGH_RES_MODE) < 0) {
            fprintf(stderr, "Error writing mode command, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Wait for the conversion time (180ms)
        usleep(180000); // 180 ms

        // Read the data
        if (read_i2c_bytes(i2c_fd, data, 2) < 0) {
            fprintf(stderr, "Error reading data, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Combine the bytes to form the raw value
        raw_value = (data[0] << 8) | data[1];

        // Calculate the lux value
        lux = calculate_lux(raw_value);

        // Log the data
        if (log_data(log_file, current_time, lux) < 0) {
            fprintf(stderr, "Error logging data, retrying...\n");
        }

        printf("Lux: %.2f\n", lux);

        sleep(5);
    }

    // Cleanup
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

