#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define PWM_GPIO 18
#define PORT 12345
#define SECRET "MySecretKey"
#define SAMPLE_INTERVAL_MS 20
#define PLAYBACK_DURATION_S 5
#define PWM_FREQUENCY 4000 // Hz
#define PWM_RANGE 1000000  // PWM range (adjust as needed)

// Global variables
int i2c_handle;
int server_fd, new_socket;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpr121();
int read_mpr121_data(int *data);
double map_data_to_frequency(int max_filtered_value);
void play_tone(double frequency);
void handle_client(int socket);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize MPR121
int init_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset

    // Configure electrode sensitivity (example values)
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0A) < 0) return -1; // Electrode 0 touch threshold
    if (i2cWriteByteData(i2c_handle, 0x5F, 0x0A) < 0) return -1; // Electrode 0 release threshold
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x05) < 0) return -1; // Electrode 0 filter
    if (i2cWriteByteData(i2c_handle, 0x5F, 0x05) < 0) return -1; // Electrode 0 filter

    // Enable electrodes
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x0F) < 0) return -1; // Enable all electrodes

    // Configure baseline filtering
    if (i2cWriteByteData(i2c_handle, 0x5C, 0x01) < 0) return -1; // Baseline filter

    // Configure touch and release thresholds for all electrodes
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + 2 * i, 0x0A) < 0) return -1; // Touch threshold
        if (i2cWriteByteData(i2c_handle, 0x42 + 2 * i, 0x05) < 0) return -1; // Release threshold
    }

    return 0;
}

// Read MPR121 data
int read_mpr121_data(int *data) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read MPR121 data\n");
        return -1;
    }
    data[0] = buf[0];
    data[1] = buf[1];
    return 0;
}

// Map data to frequency using a logarithmic scale
double map_data_to_frequency(int max_filtered_value) {
    // Ensure max_filtered_value is within reasonable bounds
    if (max_filtered_value > 1000) max_filtered_value = 1000;
    if (max_filtered_value < 10) max_filtered_value = 10;

    // Logarithmic mapping
    double frequency = 220.0 * pow(max_filtered_value / 1000.0, 0.5); // Base frequency 220 Hz, exponent 0.5
    return frequency;
}

// Play tone using hardware PWM
void play_tone(double frequency) {
    int duty_cycle = (int)((frequency / PWM_FREQUENCY) * PWM_RANGE);
    gpioPWM(PWM_GPIO, duty_cycle);
}

// Handle client connection
void handle_client(int socket) {
    char buffer[1024];
    ssize_t bytes_received;

    bytes_received = recv(socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received > 0) {
        buffer[bytes_received] = '\0';
        printf("Received: %s\n", buffer);

        if (strncmp(buffer, "MOTION_DETECTED:", 18) == 0 && strstr(buffer, SECRET) != NULL) {
            printf("Secret key detected!\n");
            int max_filtered_value;
            if (read_mpr121_data(&max_filtered_value) == 0) {
                double frequency = map_data_to_frequency(max_filtered_value);
                printf("Frequency: %.2f Hz\n", frequency);
                play_tone(frequency);
                fprintf(log_file, "Frequency: %.2f Hz\n", frequency);
                fflush(log_file);
            } else {
                fprintf(stderr, "Error reading MPR121 data\n");
            }
        } else {
            fprintf(stderr, "Invalid message received\n");
        }
    } else if (bytes_received == 0) {
        printf("Client disconnected\n");
    } else {
        perror("recv failed");
    }
    close(socket);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (init_mpr121() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen("frequency_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        perror("socket failed");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        close(server_fd);
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d\n", PORT);

    // Main loop
    while (!terminate) {
        struct sockaddr_in client_address;
        int client_address_len = sizeof(client_address);
        new_socket = accept(server_fd, (struct sockaddr *)&client_address, (socklen_t*)&client_address_len);
        if (new_socket < 0) {
            perror("accept failed");
            continue; // Continue listening for new connections
        }

        handle_client(new_socket);
    }

    // Cleanup
    printf("Cleaning up...\n");
    close(new_socket);
    close(server_fd);
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioPWM(PWM_GPIO, 0); // Stop PWM
    gpioTerminate();

    return 0;
}

