#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define LSM303_ADDR 0x1E
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08
#define LED_GPIO 17
#define PWM_CHIP "gpiochip0"
#define PWM_NUM 0
#define PWM_PERIOD 1000000 // 1 kHz
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_fd = -1;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *led_line = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *bus, int addr);
int init_magnetometer(int fd);
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
int set_led_brightness(int gpio, float magnitude);
void signal_handler(int sig);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// I2C initialization
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Magnetometer initialization
int init_magnetometer(int fd) {
    uint8_t buf[2];
    buf[0] = CTRL_REG1_M;
    buf[1] = 0x70; // 10 Hz, continuous conversion, enable all axes

    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to CTRL_REG1_M: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Magnetometer data reading
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[7];
    buf[0] = OUT_X_L_M | 0x80; // Read multiple bytes starting from OUT_X_L_M

    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C for read: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, buf, 6) != 6) {
        fprintf(stderr, "Error reading from I2C: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Magnitude calculation
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z);
}

// LED brightness control
int set_led_brightness(int gpio, float magnitude) {
    int duty_cycle = (int)(magnitude * 255.0 / 1000.0); // Scale magnitude to 0-255
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 255) duty_cycle = 255;

    uint32_t value = 0;
    if (gpiod_line_get_value(led_line) == 0) {
        value = 1 << PWM_NUM;
    }
    value |= duty_cycle;

    if (gpiod_line_set_value(led_line, value) < 0) {
        fprintf(stderr, "Error setting LED value: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    if (led_line) {
        gpiod_line_set_value(led_line, 0); // Turn off LED
        gpiod_line_release(led_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name(PWM_CHIP);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", PWM_CHIP, strerror(errno));
        return 1;
    }

    led_line = gpiod_chip_get_line(gpio_chip, LED_GPIO);
    if (!led_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", LED_GPIO, strerror(errno));
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    if (gpiod_line_request_output(led_line, "magnetometer", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %s\n", strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Initialize PWM
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "magnetometer";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(led_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, LSM303_ADDR);
    if (i2c_fd < 0) {
        cleanup();
        return 1;
    }

    // Initialize magnetometer
    if (init_magnetometer(i2c_fd) < 0) {
        cleanup();
        return 1;
    }

    int16_t x, y, z;
    float magnitude;

    // Main loop
    while (!terminate) {
        if (read_magnetometer_data(i2c_fd, &x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);
            if (set_led_brightness(LED_GPIO, magnitude) < 0) {
                fprintf(stderr, "Error setting LED brightness.\n");
            }
        } else {
            fprintf(stderr, "Error reading magnetometer data.\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000); // Sleep for 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

