#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// I2C bus
#define I2C_BUS 1

// Hard-iron offset window size
#define HARD_IRON_WINDOW_SIZE 100

// Global variables
int i2c_handle;
int16_t x_offset = 0;
int16_t y_offset = 0;
int16_t z_offset = 0;
int offset_index = 0;

// Function prototypes
int initialize_hmc5883l();
int read_hmc5883l_data(int16_t *x, int16_t *y, int16_t *z);
void update_hard_iron_offsets(int16_t x, int16_t y, int16_t z);
void print_corrected_data(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Initializes the HMC5883L sensor
int initialize_hmc5883l() {
    // Configuration Register A (0x70): 8-sample averaging, 15 Hz output rate, Gain = 1.3 Gauss
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to Configuration Register A\n");
        return -1;
    }

    // Configuration Register B (0x20): Continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to Configuration Register B\n");
        return -1;
    }

    // Mode Register (0x00): Continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to Mode Register\n");
        return -1;
    }

    return 0;
}

// Reads raw magnetometer data from the HMC5883L
int read_hmc5883l_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Updates the running average of hard-iron offsets
void update_hard_iron_offsets(int16_t x, int16_t y, int16_t z) {
    x_offset -= (x_offset - x) / HARD_IRON_WINDOW_SIZE;
    y_offset -= (y_offset - y) / HARD_IRON_WINDOW_SIZE;
    z_offset -= (z_offset - z) / HARD_IRON_WINDOW_SIZE;
}

// Prints the offset-corrected magnetometer data
void print_corrected_data(int16_t x, int16_t y, int16_t z) {
    printf("X: %d, Y: %d, Z: %d\n", x - x_offset, y - y_offset, z - z_offset);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (initialize_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t x, y, z;
    int16_t x_corrected, y_corrected, z_corrected;

    // Main loop
    while (1) {
        // Read magnetometer data
        if (read_hmc5883l_data(&x, &y, &z) == 0) {
            // Update hard-iron offsets
            update_hard_iron_offsets(x, y, z);

            // Apply hard-iron offsets
            x_corrected = x - x_offset;
            y_corrected = y - y_offset;
