#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// LSM303D I2C address
#define LSM303D_ADDR 0x1D

// LSM303D register addresses
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define INT1_CFG 0x30
#define OUT_X_L_A 0x28

// GPIO chip and line
#define GPIOCHIP "gpiochip0"
#define GPIO_LINE 23

// Circular buffer size
#define BUFFER_SIZE 64

// Global variables
int i2c_fd = -1;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *gpio_line = NULL;

// Acceleration data circular buffer
int16_t acceleration_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int i2c_read_byte(int fd, uint8_t reg);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int lsm303d_init(int fd);
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z);
void interrupt_handler(struct gpiod_line *line, int value, uint32_t pos);
void print_samples(int16_t *buffer, int size);
void signal_handler(int sig);

// I2C read byte function
int i2c_read_byte(int fd, uint8_t reg) {
    uint8_t buf[1];
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("Failed to read byte");
        return -1;
    }
    return buf[0];
}

// I2C write byte function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write byte");
        return -1;
    }
    return 0;
}

// LSM303D initialization function
int lsm303d_init(int fd) {
    // Verify WHO_AM_I register
    int who_am_i = i2c_read_byte(fd, WHO_AM_I);
    if (who_am_i != 0x49) {
        fprintf(stderr, "Error: WHO_AM_I register returned 0x%02X, expected 0x49\n", who_am_i);
        return -1;
    }

    // Configure CTRL_REG1 for 50 Hz ODR and all axes enabled
    if (i2c_write_byte(fd, CTRL_REG1, 0x57) != 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG1\n");
        return -1;
    }

    // Configure CTRL_REG4 for +-2g full-scale
    if (i2c_write_byte(fd, CTRL_REG4, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG4\n");
        return -1;
    }

    // Configure INT1_CFG for any-axis-high interrupt
    if (i2c_write_byte(fd, INT1_CFG, 0x7D) != 0) {
        fprintf(stderr, "Error: Failed to write INT1_CFG\n");
        return -1;
    }

    return 0;
}

// Read acceleration data function
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];
    int retries = 3;

    while (retries > 0) {
        if (i2c_write_byte(fd, OUT_X_L_A | 0x80, 0) != 0) {
            fprintf(stderr, "Error: Failed to write OUT_X_L_A register address\n");
            retries--;
            usleep(10000); // Wait 10ms before retry
            continue;
        }

        if (read(fd, buffer, 6) != 6) {
            fprintf(stderr, "Error: Failed to read acceleration data\n");
            retries--;
            usleep(10000); // Wait 10ms before retry
            continue;
        }

        // Combine high and low bytes for each axis
        *x = (int16_t)((buffer[1] << 8) | buffer[0]);
        *y = (int16_t)((buffer[3] << 8) | buffer[2]);
        *z = (int16_t)((buffer[5] << 8) | buffer[4]);

        return 0; // Success
    }

    fprintf(stderr, "Error: Failed to read acceleration data after multiple retries\n");
    return -1; // Failure
}

// Interrupt handler function
void interrupt_handler(struct gpiod_line *line, int value, uint32_t pos) {
    if (value == 1) {
        printf("Interrupt detected!\n");
        print_samples(acceleration_buffer, BUFFER_SIZE);
    }
}

// Print samples function
void print_samples(int16_t *buffer, int size) {
    printf("Last 10 samples:\n");
    for (int i = 0; i < 10; i++) {
        int index = (buffer_index - 1 - i + size) % size; // Ensure positive index
        printf("  X: %6d, Y: %6d, Z: %6d\n", buffer[index], buffer[(index + 1) % size], buffer[(index + 2) % size]);
    }
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);

    // Disable accelerometer
    if (i2c_fd != -1) {
        i2c_write_byte(i2c_fd, CTRL_REG1, 0x00);
        close(i2c_fd);
    }

    // Close GPIO line
    if (gpio_line != NULL) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }

    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize LSM303D
    if (lsm303d_init(i2c_fd) != 0) {
        fprintf(stderr, "Error: LSM303D initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for input
    if (gpiod_line_request_input(gpio_line, "lsm303d_mon") != 0) {
        perror("Failed to request GPIO line for input");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request interrupt handler
    if (gpiod_line_request_rising_edge_events(gpio_line, "lsm303d_mon") != 0) {
        perror("Failed to request interrupt handler");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    int16_t x, y, z;
    struct timespec ts;
    while (1) {
        // Read acceleration data
        if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            // Store data in circular buffer
            acceleration_buffer[buffer_index] = x;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            // Get timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                // Print timestamp with data
                printf("Timestamp: %ld.%09ld, X: %6d, Y: %6d, Z: %6d\n", ts.tv_sec, ts.tv_nsec, x, y, z);
            } else {
                perror("Failed to get timestamp");
            }
        } else {
            fprintf(stderr, "Error: Failed to read acceleration data\n");
        }

        // Wait 10 ms
        usleep(10000);
    }

    return 0;
}

