#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the solenoids
#define SOLENOID_1_GPIO 17
#define SOLENOID_2_GPIO 27

// Global variable to track the current solenoid state
int current_solenoid = 0;

// Function to initialize a GPIO pin as output
int initialize_gpio(int gpio) {
    if (gpioSetMode(gpio, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", gpio);
        return -1;
    }
    return 0;
}

// Function to set the state of a GPIO pin (HIGH or LOW)
int set_gpio_state(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "Error writing state %d to GPIO %d\n", state, gpio);
        return -1;
    }
    return 0;
}

// Function to de-energize both solenoids
int de_energize_solenoids() {
    if (set_gpio_state(SOLENOID_1_GPIO, 0) != 0) return -1;
    if (set_gpio_state(SOLENOID_2_GPIO, 0) != 0) return -1;
    return 0;
}

// Function to energize a solenoid for a specified duration
int energize_solenoid(int gpio, int duration_ms) {
    if (set_gpio_state(gpio, 1) != 0) return -1;
    gpioDelay(duration_ms * 1000); // pigpioDelay takes microseconds
    if (set_gpio_state(gpio, 0) != 0) return -1;
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    de_energize_solenoids();
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO pins
    if (initialize_gpio(SOLENOID_1_GPIO) != 0) {
        gpioTerminate();
        return 1;
    }
    if (initialize_gpio(SOLENOID_2_GPIO) != 0) {
        gpioTerminate();
        return 1;
    }

    // Set initial state: both solenoids are off
    de_energize_solenoids();

    // Set up signal handlers for Ctrl+C
