#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>
#include <errno.h>

// Define GPIO pins for door locks
#define LOCK1_GPIO 17
#define LOCK2_GPIO 27

// Define UART ports
#define UART0_PORT "/dev/serial0"
#define UART1_PORT "/dev/serial1"

// Define baud rate
#define BAUD_RATE 9600

// Define timeout duration (seconds)
#define TIMEOUT_DURATION 5

// Define expected code
#define EXPECTED_CODE "123456"

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int open_uart(const char *port);
int read_code(int fd, char *code, int max_length);
int validate_code(const char *code, const char *expected_code);
void unlock_doors(int lock1_gpio, int lock2_gpio);
void lock_doors(int lock1_gpio, int lock2_gpio);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LOCK1_GPIO, PI_OUTPUT);
    gpioSetMode(LOCK2_GPIO, PI_OUTPUT);

    // Ensure locks are initially locked
    gpioWrite(LOCK1_GPIO, 0);
    gpioWrite(LOCK2_GPIO, 0);

    return 0;
}

// Function to open a UART port
int open_uart(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        fprintf(stderr, "Error opening UART %s: %s\n", port, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, B9600);
    cfsetispeed(&tty, B9600);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;     // 8-bit chars
    tty.c_iflag &= ~IGNBRK;         // disable break processing
    tty.c_lflag = 0;                // no signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;                // no remapping, no delays
    tty.c_cc[VMIN] = 0;              // read doesn't block
    tty.c_cc[VTIME] = 5;             // 0.5 seconds read timeout

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // shut off xon/xoff ctrl

    tty.c_cflag |= (CLOCAL | CREAD);   // ignore modem controls, enable reading
    tty.c_cflag &= ~(PARENB | PARODD); // shut off parity
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read a code from a UART port
int read_code(int fd, char *code, int max_length) {
    int i = 0;
    char ch;
    int timeout_start = time(NULL);

    while (i < max_length) {
        if (read(fd, &ch, 1) == 1) {
            if (ch >= '0' && ch <= '9') {
                code[i++] = ch;
                timeout_start = time(NULL); // Reset timeout on valid input
            } else {
                fprintf(stderr, "Invalid character received: %c\n", ch);
                // Reset the buffer
                code[0] = '\0';
                i = 0;
            }
        } else {
            // Check for timeout
            if (time(NULL) - timeout_start >= TIMEOUT_DURATION) {
                fprintf(stderr, "Timeout reading from UART\n");
                return -1;
            }
        }
    }

    code[i] = '\0';
    return 0;
}

// Function to validate a code
int validate_code(const char *code, const char *expected_code) {
    if (strlen(code) != strlen(expected_code)) {
        fprintf(stderr, "Invalid code length\n");
        return -1;
    }

    for (int i = 0; i < strlen(code); i++) {
        if (code[i] != expected_code[i]) {
            fprintf(stderr, "Code mismatch at position %d\n", i);
            return -1;
        }
    }

    return 0;
}

// Function to unlock the doors
void unlock_doors(int lock1_gpio, int lock2_gpio) {
    gpioWrite(lock1_gpio, 1);
    gpioWrite(lock2_gpio, 1);
    gpioDelay(2000); // 2 seconds
    lock_doors(lock1_gpio, lock2_gpio);
}

// Function to lock the doors
void lock_doors(int lock1_gpio, int lock2_gpio) {
    gpioWrite(lock1_gpio, 0);
    gpioWrite(lock2_gpio, 0);
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    // Ensure locks are locked
    lock_doors(LOCK1_GPIO, LOCK2_GPIO);

    // Close UART ports
    if (serial_fd0 != -1) close(serial_fd0);
    if (serial_fd1 != -1) close(serial_fd1);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open UART ports
    serial_fd0 = open_uart(UART0_PORT);
    if (serial_fd0 == -1) {
        cleanup();
        return 1;
    }

    serial_fd1 = open_uart(UART1_PORT);
    if (serial_fd1 == -1) {
        cleanup();
        return 1;
    }

    char code0[7]; // Maximum length of 6 digits + null terminator
    char code1[7];

    // Main loop
    while (!terminate) {
        // Read code from UART0
        if (read_code(serial_fd0, code0, 6) == 0) {
            printf("Received code from UART0: %s\n", code0);
        }

        // Read code from UART1
        if (read_code(serial_fd1, code1, 6) == 0) {
            printf("Received code from UART1: %s\n", code1);
        }

        // Validate codes
        if (validate_code(code0, EXPECTED_CODE) == 0 && validate_code(code1, EXPECTED_CODE) == 0) {
            printf("Codes match, unlocking doors...\n");
            unlock_doors(LOCK1_GPIO, LOCK2_GPIO);
            printf("Doors unlocked for 2 seconds.\n");
        }

        gpioDelay(100); // Check every 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

