#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins
#define PIR_PIN 4
#define RELAY_PIN 17

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define strike duration (seconds)
#define STRIKE_DURATION 1

// Define failsafe timeout (seconds)
#define FAILSAFE_TIMEOUT 10

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *pir_line;
static struct gpiod_line *relay_line;
static volatile sig_atomic_t terminate = 0;
static time_t motion_start_time = 0;

// Function prototypes
int gpio_init(const char *chip_name, int pir_pin, int relay_pin);
int pir_read(struct gpiod_line *line);
int relay_on(struct gpiod_line *line);
int relay_off(struct gpiod_line *line);
void failsafe_trigger(struct gpiod_line *line);
void signal_handler(int sig);
void cleanup(void);

// Signal handler for clean shutdown
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, cleaning up...");
    terminate = 1;
}

// Initialize GPIO lines
int gpio_init(const char *chip_name, int pir_pin, int relay_pin) {
    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", chip_name);
        return -1;
    }

    pir_line = gpiod_chip_get_line(chip, pir_pin);
    if (!pir_line) {
        syslog(LOG_ERR, "Failed to get PIR GPIO line: %d", pir_pin);
        gpiod_chip_close(chip);
        return -1;
    }

    relay_line = gpiod_chip_get_line(chip, relay_pin);
    if (!relay_line) {
        syslog(LOG_ERR, "Failed to get RELAY GPIO line: %d", relay_pin);
        gpiod_chip_close(chip);
        gpiod_line_release(pir_line);
        return -1;
    }

    // Request PIR line as input
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "motion_detector";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(pir_line, &config, 0) < 0) {
        syslog(LOG_ERR, "Failed to request PIR line as input: %d", pir_pin);
        gpiod_chip_close(chip);
        gpiod_line_release(pir_line);
        gpiod_line_release(relay_line);
        return -1;
    }

    // Request RELAY line as output
    config.consumer = "door_strike";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(relay_line, &config, 0) < 0) {
        syslog(LOG_ERR, "Failed to request RELAY line as output: %d", relay_pin);
        gpiod_chip_close(chip);
        gpiod_line_release(pir_line);
        gpiod_line_release(relay_line);
        return -1;
    }

    return 0;
}

// Read PIR sensor value
int pir_read(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        syslog(LOG_ERR, "Failed to read PIR value: %d", value);
        return -1;
    }
    return value;
}

// Turn relay on
int relay_on(struct gpiod_line *line) {
    int ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to turn relay on: %d", ret);
        return -1;
    }
    syslog(LOG_INFO, "Relay turned ON");
    return 0;
}

// Turn relay off
int relay_off(struct gpiod_line *line) {
    int ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to turn relay off: %d", ret);
        return -1;
    }
    syslog(LOG_INFO, "Relay turned OFF");
    return 0;
}

// Failsafe trigger
void failsafe_trigger(struct gpiod_line *line) {
    syslog(LOG_WARNING, "Failsafe triggered: PIR sensor continuously HIGH for %d seconds", FAILSAFE_TIMEOUT);
    relay_off(line);
}

// Cleanup function
void cleanup(void) {
    syslog(LOG_INFO, "Cleaning up GPIO resources...");
    if (relay_line) {
        relay_off(relay_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    syslog(LOG_INFO, "GPIO cleanup complete. Exiting.");
    closelog();
    exit(0);
}

int main() {
    // Open system log
    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init(GPIOCHIP, PIR_PIN, RELAY_PIN) < 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Motion detector started");

    // Main loop
    while (!terminate) {
        int pir_value = pir_read(pir_line);
        if (pir_value < 0) {
            syslog(LOG_ERR, "Failed to read PIR value, exiting");
            cleanup();
            return 1;
        }

        if (pir_value == 1) {
            if (motion_start_time == 0) {
                motion_start_time = time(NULL);
                syslog(LOG_INFO, "Motion detected");
            } else {
                time_t current_time = time(NULL);
                if (difftime(current_time, motion_start_time) > FAILSAFE_TIMEOUT) {
                    failsafe_trigger(relay_line);
                    motion_start_time = 0; // Reset the timer
                }
            }

            if (motion_start_time == 0) {
                relay_on(relay_line);
                motion_start_time = time(NULL);
            }
        } else {
            if (motion_start_time != 0) {
                motion_start_time = 0; // Reset the timer
            }
        }

        usleep(50000); // 50 ms delay
    }

    cleanup();
    return 0;
}

