#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define relay states
#define RELAY_ON 0
#define RELAY_OFF 1

// Define timer interval (60 seconds)
#define TIMER_INTERVAL 60

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void activate_relay(int relay_pin);
void deactivate_relay(int relay_pin);
void log_relay_state(int relay_pin, int state);
void timer_callback(int timer_id, void *user_data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    program_running = 0;
}

// Function to activate a relay
void activate_relay(int relay_pin) {
    int result = gpioWrite(relay_pin, RELAY_ON);
    if (result != 0) {
        syslog(LOG_ERR, "Failed to activate relay on pin %d: %d", relay_pin, result);
    } else {
        log_relay_state(relay_pin, RELAY_ON);
    }
}

// Function to deactivate a relay
void deactivate_relay(int relay_pin) {
    int result = gpioWrite(relay_pin, RELAY_OFF);
    if (result != 0) {
        syslog(LOG_ERR, "Failed to deactivate relay on pin %d: %d", relay_pin, result);
    } else {
        log_relay_state(relay_pin, RELAY_OFF);
    }
}

// Function to log relay state changes to syslog
void log_relay_state(int relay_pin, int state) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    syslog(LOG_INFO, "Relay %d: %s", relay_pin, (state == RELAY_ON) ? "ON" : "OFF");
}

// Timer callback function
void timer_callback(int timer_id, void *user_data) {
    int relay_pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    int num_relays = sizeof(relay_pins) / sizeof(relay_pins[0]);
    int current_relay_index = 0;
    int current_state = 0; // 0: pause, 1: activate, 2: deactivate

    if (current_state == 0) { // Pause state
        current_state = 1; // Activate next relay
        activate_relay(relay_pins[current_relay_index]);
    } else if (current_state == 1) { // Activate state
        current_state = 2; // Deactivate current relay
        deactivate_relay(relay_pins[current_relay_index]);
    } else if (current_state == 2) { // Deactivate state
        current_state = 0; // Pause
        gpioDelay(TIMER_INTERVAL * 1000000); // Delay for 60 seconds (microseconds)
    }
}

int main() {
    // Initialize syslog
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pins as outputs
    int result = gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    if (result != 0) {
        syslog(LOG_ERR, "Failed to set mode for relay1_pin %d: %d", RELAY1_PIN, result);
        gpioTerminate();
        closelog();
        return 1;
    }
    result = gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    if (result != 0) {
        syslog(LOG_ERR, "Failed to set mode for relay2_pin %d: %d", RELAY2_PIN, result);
        gpioTerminate();
        closelog();
        return 1;
    }
    result = gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    if (result != 0) {
        syslog(LOG_ERR, "Failed to set mode for relay3_pin %d: %d", RELAY3_PIN, result);
        gpioTerminate();
        closelog();
        return 1;
    }
    result = gpioSetMode(RELAY4_PIN, PI_OUTPUT);
    if (result != 0) {
        syslog(LOG_ERR, "Failed to set mode for relay4_pin %d: %d", RELAY4_PIN, result);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Initialize all relays to OFF (HIGH)
    gpioWrite(RELAY1_PIN, RELAY_OFF);
    gpioWrite(RELAY2_PIN, RELAY_OFF);
    gpioWrite(RELAY3_PIN, RELAY_OFF);
    gpioWrite(RELAY4_PIN, RELAY_OFF);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer callback function
    if (gpioSetTimerFuncEx(0, TIMER_INTERVAL, timer_callback, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set timer function");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Main loop to keep the program running
    while (program_running) {
        gpioDelay(1000000); // Sleep for 1 second (microseconds)
    }

    // Clean up and exit
    syslog(LOG_INFO, "Cleaning up and exiting...");
    gpioWrite(RELAY1_PIN, RELAY_OFF);
    gpioWrite(RELAY2_PIN, RELAY_OFF);
    gpioWrite(RELAY3_PIN, RELAY_OFF);
    gpioWrite(RELAY4_PIN, RELAY_OFF);
    gpioTerminate();
    closelog();
    return 0;
}

