#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/time.h>
#include <sys/timerfd.h>
#include <linux/i2c-dev.h>
#include <sys/epoll.h>
#include <sys/stat.h>
#include <sys/file.h>

// MPU6050 Registers
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_CONFIG 0x1C
#define ACCEL_SENSITIVITY 16384.0f

// Circular Buffer Size
#define BUFFER_SIZE 1024

// Global Variables
static int i2c_fd = -1;
static int timer_fd = -1;
static volatile sig_atomic_t terminate = 0;

// Circular Buffer Structure
typedef struct {
    float x[BUFFER_SIZE];
    float y[BUFFER_SIZE];
    float z[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static circular_buffer_t accel_buffer;

// Function Prototypes
int i2c_open(const char *device);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int mpu6050_init(int fd);
int read_acceleration(int fd, float *x, float *y, float *z);
void add_to_buffer(circular_buffer_t *buffer, float x, float y, float z);
int get_latest_data(circular_buffer_t *buffer, float *x, float *y, float *z);
void signal_handler(int sig);
int sysfs_export(const char *path);
int sysfs_unexport(const char *path);
int sysfs_create_file(const char *path, const char *value);
int sysfs_open_file(const char *path, const char *mode);

// I2C Open Function
int i2c_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    return fd;
}

// I2C Read Bytes Function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Error reading data");
        return -1;
    }
    return 0;
}

// I2C Write Byte Function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// MPU6050 Initialization Function
int mpu6050_init(int fd) {
    // Wake up the MPU6050
    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error waking up MPU6050\n");
        return -1;
    }

    // Set accelerometer range to +/- 2g
    if (i2c_write_byte(fd, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error setting accelerometer range\n");
        return -1;
    }

    return 0;
}

// Read Acceleration Data Function
int read_acceleration(int fd, float *x, float *y, float *z) {
    uint8_t data[6];
    if (i2c_read_bytes(fd, ACCEL_XOUT_H, data, 6) < 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    // Combine high and low bytes, and scale to g
    *x = (float)((int16_t)(data[0] << 8 | data[1])) / ACCEL_SENSITIVITY;
    *y = (float)((int16_t)(data[2] << 8 | data[3])) / ACCEL_SENSITIVITY;
    *z = (float)((int16_t)(data[4] << 8 | data[5])) / ACCEL_SENSITIVITY;

    return 0;
}

// Add to Circular Buffer Function
void add_to_buffer(circular_buffer_t *buffer, float x, float y, float z) {
    buffer->x[buffer->head] = x;
    buffer->y[buffer->head] = y;
    buffer->z[buffer->head] = z;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Get Latest Data from Circular Buffer Function
int get_latest_data(circular_buffer_t *buffer, float *x, float *y, float *z) {
    if (buffer->count == 0) {
        return -1; // Buffer is empty
    }
    int index = (buffer->head + BUFFER_SIZE - 1) % BUFFER_SIZE;
    *x = buffer->x[index];
    *y = buffer->y[index];
    *z = buffer->z[index];
    return 0;
}

// Signal Handler Function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Sysfs Export Function
int sysfs_export(const char *path) {
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        if (errno == EACCES) {
            fprintf(stderr, "Permission denied. Try running with sudo.\n");
        } else {
            perror("Error opening sysfs file for export");
        }
        return -1;
    }
    if (write(fd, "1", 1) != 1) {
        perror("Error exporting sysfs attribute");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Sysfs Unexport Function
int sysfs_unexport(const char *path) {
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Error opening sysfs file for unexport");
        return -1;
    }
    if (write(fd, "0", 1) != 1) {
        perror("Error unexporting sysfs attribute");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Sysfs Create File Function
int sysfs_create_file(const char *path, const char *value) {
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        perror("Error creating sysfs file");
        return -1;
    }
    if (write(fd, value, strlen(value)) != strlen(value)) {
        perror("Error writing to sysfs file");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Sysfs Open File Function
int sysfs_open_file(const char *path, const char *mode) {
    int fd = open(path, O_RDWR);
    if (fd < 0) {
        perror("Error opening sysfs file");
        return -1;
    }
    return fd;
}

int main() {
    // Initialize Circular Buffer
    accel_buffer.head = 0;
    accel_buffer.count = 0;

    // Signal Handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // I2C Initialization
    i2c_fd = i2c_open("/dev/i2c-1");
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    // MPU6050 Initialization
    if (mpu6050_init(i2c_fd) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Timer Initialization
    struct sigevent sev;
    struct itimerspec its;

    memset(&sev, 0, sizeof(sev));
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGALRM;
    sev.sigev_value.sival_ptr = &timer_fd;

    if (timer_fd == -1) {
        timer_fd = timerfd_create(CLOCK_REALTIME, 0);
        if (timer_fd == -1) {
            perror("Error creating timerfd");
            close(i2c_fd);
            return EXIT_FAILURE;
        }
    }

    if (timer_fd != -1) {
        if (timer_settime(timer_fd, 0, &sev, NULL) < 0) {
            perror("Error setting timer");
            close(i2c_fd);
            close(timer_fd);
            return EXIT_FAILURE;
        }
    }

    // Sysfs Export Path
    const char *export_path = "/sys/kernel/mpu6050_accel";

    // Export the sysfs attribute
    if (sysfs_export(export_path) < 0) {
        close(i2c_fd);
        close(timer_fd);
        return EXIT_FAILURE;
    }

    // Create the sysfs file
    char value[64];
    snprintf(value, sizeof(value), "%d", 0); // Initial value
    if (sysfs_create_file(export_path, value) < 0) {
        close(i2c_fd);
        close(timer_fd);
        sysfs_unexport(export_path);
        return EXIT_FAILURE;
    }

    // Main Loop
    float x, y, z;
    while (!terminate) {
        if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            add_to_buffer(&accel_buffer, x, y, z);
        } else {
            fprintf(stderr, "Error reading acceleration, retrying...\n");
        }

        if (timer_fd != -1) {
            its.it_value.tv_sec = 1; // 1 second interval
            its.it_value.tv_nsec = 0;
            its.it_interval.tv_sec = 1;
            its.it_interval.tv_nsec = 0;
            if (timer_settime(timer_fd, 0, &sev, &its, NULL) < 0) {
