// Define GPIO pins for the relays
#define RELAY1_PIN 18
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define the intervals for toggling the relays (in seconds)
#define INTERVAL1 2
#define INTERVAL2 3
#define INTERVAL3 5
#define INTERVAL4 7

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught SIGINT, exiting gracefully...\n");
}

// Signal handler for SIGTERM
void sigterm_handler(int signal)
{
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught SIGTERM, exiting gracefully...\n");
}

// Function to initialize a GPIO pin as an output
int initialize_gpio(int pin)
{
    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", pin);
        return -1;
    }
    return 0;
}

// Function to toggle a relay (turn on or off)
void toggle_relay(int pin)
{
    gpioWrite(pin, 1); // Turn the relay ON
    gpioDelay(1000);   // Wait for 1 second
    gpioWrite(pin, 0); // Turn the relay OFF
}

// Function to calculate the next toggle time for a relay based on its interval
void calculate_next_toggle_time(int pin, int interval, struct timespec *next_time)
{
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);
    long seconds = now.tv_sec;
    long nanoseconds = now.tv_nsec;

    // Calculate the next toggle time in seconds and nanoseconds
    long next_seconds = (seconds + interval) % 60; // Ensure the time stays within a minute
    long next_nanoseconds = (long)((double)nanoseconds / 1000000000.0 * interval * 1000000000.0) % 1000000000.0; // Calculate nanoseconds for the interval

    next_time->tv_sec = next_seconds;
    next_time->tv_nsec = next_nanoseconds;
}

int main()
{
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Initialize the GPIO pins
    if (initialize_gpio(RELAY1_PIN) != 0 ||
        initialize_gpio(RELAY2_PIN) != 0 ||
        initialize_gpio(RELAY3_PIN) != 0 ||
        initialize_gpio(RELAY4_PIN) != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop to toggle the relays
    struct timespec next_toggle_times[4];
    int relay_intervals[4] = {INTERVAL1, INTERVAL2, INTERVAL3, INTERVAL4};
    int relay_pins[4] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    int i;

    while (program_running) {
        // Calculate the next toggle time for each relay
        for (i = 0; i < 4; i++) {
            calculate_next_toggle_time(relay_pins[i], relay_intervals[i], &next_toggle_times[i]);
        }

        // Wait for the next toggle time for each relay
        for (i = 0; i < 4; i++) {
            while (next_toggle_times[i].tv_sec == 0 && next_toggle_times[i].tv_nsec == 0) {
                clock_gettime(CLOCK_MONOTONIC, &next_toggle_times[i]);
                gpioDelay(1000); // Check every 1ms to avoid busy-waiting
            }
        }

        // Toggle the relays that are due to be toggled
        for (i = 0; i < 4; i++) {
            if (next_toggle_times[i].tv_sec == 0 && next_toggle_times[i].tv_nsec == 0) {
                toggle_relay(relay_pins[i]);
                calculate_next_toggle_time(relay_pins[i], relay_intervals[i], &next_toggle_times[i]);
            }
        }
    }

    // Turn off all relays before exiting
    gpioWrite(RELAY1_PIN, 0);
    gpioWrite(RELAY2_PIN, 0);
    gpioWrite(RELAY3_PIN, 0);
    gpioWrite(RELAY4_PIN, 0);

    // Terminate the pigpio library
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

