#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27

// Define alarm duration (in seconds)
#define ALARM_DURATION 3

// Global variables
static volatile int running = 1;
static volatile int alarm_active = 0;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sound_sensor();
void activate_alarm();
void deactivate_alarm();
void log_alarm_event();
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0; // Indicate success
}

// Function to read the sound sensor
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Function to activate the alarm (turn on the relay)
void activate_alarm() {
    if (!alarm_active) {
        gpioWrite(RELAY_PIN, 1); // Turn on the relay
        alarm_active = 1;
        log_alarm_event();
        gpioDelay(ALARM_DURATION * 1000000); // Wait for alarm duration (in microseconds)
        deactivate_alarm();
    }
}

// Function to deactivate the alarm (turn off the relay)
void deactivate_alarm() {
    gpioWrite(RELAY_PIN, 0); // Turn off the relay
    alarm_active = 0;
}

// Function to log alarm events to a file
void log_alarm_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s: Alarm triggered\n", timestamp);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate(); // Terminate pigpio

    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Open the log file
    log_file = fopen("alarm_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup(); // Exit if log file cannot be opened
        return 1;
    }

    printf("Alarm system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        if (read_sound_sensor() == 1) {
            activate_alarm();
        }
        gpioDelay(100000); // Poll every 100 ms
    }

    // Cleanup and exit
    cleanup();

    return 0;
}

