#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define READ_COMMAND {0xFF,0x01,0x86,0x00,0x00,0x00,0x00,0x00,0x79}
#define CO2_DATA_LENGTH 9
#define CHECKSUM_LENGTH 8
#define CHECKSUM_ERROR_VALUE -1
#define CO2_PPM_MIN 0
#define CO2_PPM_MAX 5000
#define LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"
#define TIMEOUT_MS 1000

int uart_handle;
FILE *log_file;
FILE *error_log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold the sensor data
typedef struct {
    int co2_ppm;
    int error_flag;
} sensor_data_t;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the UART port
int open_uart() {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0); //0 for default flags
    if (uart_handle < 0) {
        fprintf(stderr, "Failed to open UART: %d\n", uart_handle);
        return -1;
    }
    return 0;
}

// Function to send data over UART
int send_uart_data(const unsigned char *data, int length) {
    int bytes_written = serWrite(uart_handle, data, length);
    if (bytes_written != length) {
        fprintf(stderr, "Failed to write to UART: %d\n", bytes_written);
        return -1;
    }
    return 0;
}

// Function to read data from UART with timeout
int read_uart_data(unsigned char *buffer, int length) {
    int bytes_read = 0;
    int start_time = time(NULL);

    while (bytes_read < length) {
        int available = serDataAvailable(uart_handle);
        if (available > 0) {
            int bytes_to_read = (available < length - bytes_read) ? available : length - bytes_read;
            if (serRead(uart_handle, buffer + bytes_read, bytes_to_read) == bytes_to_read) {
                bytes_read += bytes_to_read;
            } else {
                fprintf(stderr, "serRead failed, bytes read: %d\n", bytes_to_read);
                return -1; // Indicate failure
            }
        } else {
            // Check for timeout
            if (time(NULL) - start_time > 1) {
                fprintf(stderr, "Timeout reading from UART\n");
                return -1; // Indicate timeout failure
            }
            gpioDelay(1); // Small delay to avoid busy-waiting
        }
    }
    return 0; // Indicate success
}

// Function to calculate the checksum
unsigned char calculate_checksum(const unsigned char *data, int length) {
    unsigned char checksum = 0;
    for (int i = 0; i < length - 1; i++) {
        checksum += data[i];
    }
    return checksum;
}

// Function to validate the checksum
int validate_checksum(const unsigned char *data, int length) {
    unsigned char checksum = calculate_checksum(data, length - 1);
    if (checksum != data[length - 1]) {
        fprintf(error_log_file, "%ld: Checksum mismatch: calculated=%02X, received=%02X\n", time(NULL), checksum, data[length - 1]);
        fflush(error_log_file);
        return -1; // Indicate checksum failure
    }
    return 0; // Indicate checksum success
}

// Function to extract CO2 concentration from the response
int extract_co2_ppm(const unsigned char *response) {
    return (response[2] << 8) | response[3];
}

// Function to log data to JSON file
int log_co2_data(int co2_ppm, int error_flag) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "{\"timestamp\": \"%s\", \"co2_ppm\": %d, \"error_flag\": %d}\n", timestamp, co2_ppm, error_flag);
    fflush(log_file);

    // Simulate sending data to a remote server
    printf("{\"timestamp\": \"%s\", \"co2_ppm\": %d, \"error_flag\": %d}\n", timestamp, co2_ppm, error_flag);

    return 0;
}

// Function to log errors to file
void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(error_log_file, "%s: %s\n", timestamp, message);
    fflush(error_log_file);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open UART port
    if (open_uart() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        serClose(uart_handle);
        gpioTerminate();
        return 1;
    }

    // Open error log file
    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        fprintf(stderr, "Failed to open error log file\n");
        fclose(log_file);
        serClose(uart_handle);
        gpioTerminate();
        return 1;
    }

    unsigned char read_buffer[CO2_DATA_LENGTH];
    int co2_ppm;
    int error_flag;

    while (!terminate) {
        // Send read command
        if (send_uart_data(READ_COMMAND, sizeof(READ_COMMAND)) != 0) {
            log_error("Failed to send read command");
            error_flag = 1;
        } else {
            error_flag = 0;
        }

        // Read response with timeout
        if (read_uart_data(read_buffer, CO2_DATA_LENGTH) == 0) {
            // Validate checksum
            if (validate_checksum(read_buffer, CO2_DATA_LENGTH - 1) == 0) {
                // Extract CO2 concentration
                co2_ppm = extract_co2_ppm(read_buffer);

                // Data validation
                if (co2_ppm >= CO2_PPM_MIN && co2_ppm <= CO2_PPM_MAX) {
                    // Log data
                    log_co2_data(co2_ppm, error_flag);
                } else {
                    log_error("CO2 concentration out of range");
                    log_co2_data(CO2_PPM_MIN, error_flag); // Log with error flag
                }
            } else {
                log_error("Checksum validation failed");
                log_co2_data(0, error_flag); // Log with error flag
            }
        } else {
            log_error("Failed to read data from sensor");
            log_co2_data(0, error_flag); // Log with error flag
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Close UART port and log files
    serClose(uart_handle);
    fclose(log_file);
    fclose(error_log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

