#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define HMC5883L_ADDR 0x1E
#define CONFIG_A 0x00
#define CONFIG_B 0x01
#define MODE 0x02
#define DATA_START 0x03
#define NUM_SAMPLES 6
#define TARGET_HEADING 90.0f
#define HARD_IRON_X_OFFSET 100
#define HARD_IRON_Y_OFFSET -50
#define DEVIATION_THRESHOLD 10.0f
#define SAMPLE_INTERVAL_MS 100
#define BUFFER_SIZE 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for heading data
typedef struct {
    float heading;
    int gpio_state;
} heading_data_t;

// Circular buffer
heading_data_t heading_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_i2c();
int configure_hmc5883l();
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_heading(int16_t x, int16_t y);
float compensate_hard_iron(float heading, int16_t x, int16_t y);
void control_gpio(float compensated_heading);
void log_heading(float heading);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to configure HMC5883L
int configure_hmc5883l() {
    // CONFIG_A: 8-average, 15 Hz, normal measurement
    if (i2cWriteByteData(i2c_handle, CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Failed to write to CONFIG_A\n");
        return -1;
    }

    // CONFIG_B: Gain = 1.3 Gauss
    if (i2cWriteByteData(i2c_handle, CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Failed to write to CONFIG_B\n");
        return -1;
    }

    // MODE: Continuous measurement
    if (i2cWriteByteData(i2c_handle, MODE, 0x00) < 0) {
        fprintf(stderr, "Failed to write to MODE\n");
        return -1;
    }

    return 0;
}

// Function to read magnetometer data
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[NUM_SAMPLES];
    if (i2cReadI2CBlockData(i2c_handle, DATA_START, buffer, NUM_SAMPLES) != NUM_SAMPLES) {
        fprintf(stderr, "Failed to read magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to calculate heading
float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2((float)y, (float)x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Function to compensate for hard iron
float compensate_hard_iron(float heading, int16_t x, int16_t y) {
    float compensated_heading = heading - atan2((float)y - HARD_IRON_Y_OFFSET, (float)x - HARD_IRON_X_OFFSET) * 180 / M_PI;
    if (compensated_heading < 0) {
        compensated_heading += 360;
    }
    return compensated_heading;
}

// Function to control GPIO
void control_gpio(float compensated_heading) {
    if (fabs(compensated_heading - TARGET_HEADING) > DEVIATION_THRESHOLD) {
        gpioWrite(17, 1); // Set GPIO17 high
    } else {
        gpioWrite(17, 0); // Set GPIO17 low
    }
}

// Function to log heading
void log_heading(float heading) {
    heading_buffer[buffer_index].heading = heading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    gpioWrite(17, 0); // Ensure GPIO is low
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() < 0) {
        return 1;
    }

    // Configure HMC5883L
    if (configure_hmc5883l() < 0) {
        cleanup();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(17, PI_OUTPUT);

    int16_t x, y, z;
    float heading, compensated_heading;

    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(&x, &y, &z) == 0) {
            // Calculate heading
            heading = calculate_heading(x, y);

            // Compensate for hard iron
            compensated_heading = compensate_hard_iron(heading, x, y);

            // Control GPIO
            control_gpio(compensated_heading);

            // Log heading
            log_heading(compensated_heading);

            printf("Heading: %.2f, Compensated Heading: %.2f\n", heading, compensated_heading);
        } else {
            fprintf(stderr, "Error reading magnetometer data. Retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

