#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Define GPIO pins
#define RED_PIN 17
#define GREEN_PIN 27
#define BLUE_PIN 22

// Define I2C bus and address
#define I2C_BUS 1
#define BH1750_ADDR 0x23

// Define lux thresholds
#define LUX_THRESHOLD_RED 50
#define LUX_THRESHOLD_GREEN 150
#define LUX_THRESHOLD_BLUE 300

// Define log file name
#define LOG_FILE "lighting_log.txt"

// Global variables
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *red_line = NULL;
static struct gpiod_line *green_line = NULL;
static struct gpiod_line *blue_line = NULL;
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int init_i2c(void);
int read_bh1750(float *lux);
int control_relays(float lux);
int log_data(float lux, int red_state, int green_state, int blue_state);
void signal_handler(int sig);
void cleanup(void);

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize GPIO lines
int init_gpio(void) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "smart_lighting";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    red_line = gpiod_chip_get_line(gpio_chip, RED_PIN);
    if (!red_line) {
        perror("Failed to get RED_PIN line");
        return -1;
    }
    if (gpiod_line_request(red_line, &config, 0) < 0) {
        perror("Failed to request RED_PIN line");
        return -1;
    }

    green_line = gpiod_chip_get_line(gpio_chip, GREEN_PIN);
    if (!green_line) {
        perror("Failed to get GREEN_PIN line");
        return -1;
    }
    if (gpiod_line_request(green_line, &config, 0) < 0) {
        perror("Failed to request GREEN_PIN line");
        return -1;
    }

    blue_line = gpiod_chip_get_line(gpio_chip, BLUE_PIN);
    if (!blue_line) {
        perror("Failed to get BLUE_PIN line");
        return -1;
    }
    if (gpiod_line_request(blue_line, &config, 0) < 0) {
        perror("Failed to request BLUE_PIN line");
        return -1;
    }

    return 0;
}

// Initialize I2C bus
int init_i2c(void) {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return -1;
    }

    // Configure BH1750 for continuous high-resolution mode
    unsigned char config_cmd = 0x10; // Continuous high-resolution mode
    if (write(i2c_fd, &config_cmd, 1) != 1) {
        perror("Failed to write to I2C device");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Read lux value from BH1750 sensor
int read_bh1750(float *lux) {
    unsigned char buffer[2];
    int bytes_read;

    bytes_read = read(i2c_fd, buffer, 2);
    if (bytes_read != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Control relays based on lux value
int control_relays(float lux) {
    int red_state = 0, green_state = 0, blue_state = 0;

    if (lux < LUX_THRESHOLD_RED) {
        red_state = 1;
    } else if (lux < LUX_THRESHOLD_GREEN) {
        green_state = 1;
    } else if (lux < LUX_THRESHOLD_BLUE) {
        blue_state = 1;
    } else {
        red_state = 1;
        green_state = 1;
        blue_state = 1;
    }

    if (gpiod_line_set_value(red_line, red_state) < 0) {
        perror("Failed to set RED_PIN value");
        return -1;
    }
    if (gpiod_line_set_value(green_line, green_state) < 0) {
        perror("Failed to set GREEN_PIN value");
        return -1;
    }
    if (gpiod_line_set_value(blue_line, blue_state) < 0) {
        perror("Failed to set BLUE_PIN value");
        return -1;
    }

    return 0;
}

// Log data to file
int log_data(float lux, int red_state, int green_state, int blue_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, %.2f, %d, %d, %d\n", timestamp, lux, red_state, green_state, blue_state) < 0) {
        perror("Failed to write to log file");
        return -1;
    }

    fflush(log_file);

    return 0;
}

// Cleanup resources
void cleanup(void) {
    printf("Cleaning up resources...\n");

    // Turn off relays
    if (red_line) {
        gpiod_line_set_value(red_line, 0);
    }
    if (green_line) {
        gpiod_line_set_value(green_line, 0);
    }
    if (blue_line) {
        gpiod_line_set_value(blue_line, 0);
    }

    // Release GPIO lines
    if (red_line) {
        gpiod_line_release(red_line);
    }
    if (green_line) {
        gpiod_line_release(green_line);
    }
    if (blue_line) {
        gpiod_line_release(blue_line);
    }

    // Close I2C file descriptor
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

int main(void) {
    float lux;
    int red_state, green_state, blue_state;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    printf("Smart Lighting System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read lux value
        if (read_bh1750(&lux) < 0) {
            fprintf(stderr, "Failed to read lux value. Retrying.\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Control relays
        if (control_relays(lux) < 0) {
            fprintf(stderr, "Failed to control relays. Retrying.\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Log data
        red_state = gpiod_line_get_value(red_line);
        green_state = gpiod_line_get_value(green_line);
        blue_state = gpiod_line_get_value(blue_line);

        if (log_data(lux, red_state, green_state, blue_state) < 0) {
            fprintf(stderr, "Failed to log data. Retrying.\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup resources before exiting
    cleanup();

    printf("Smart Lighting System stopped.\n");

    return 0;
}

