    gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY);

    // Main loop
    while (program_running) {
        // Simulate sensor readings (replace with actual sensor readings)
        int distance_a = 30; // cm
        int distance_b = 70; // cm

        // Set motor speeds
        set_motor_speed(MOTOR_A_IN1, MOTOR_A_IN2, distance_a);
        set_motor_speed(MOTOR_B_IN3, MOTOR_B_IN4, distance_b);

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Stop motors
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 0);
    gpioWrite(MOTOR_B_IN3, 0);
    gpioWrite(MOTOR_B_IN4, 0);

