#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <sys/time.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47
#define SERVO_PIN 18
#define PWM_CHIP 2
#define PWM_NUM 0
#define PWM_PERIOD 20000 // 50Hz
#define PWM_DUTY_CYCLE 1500 // 50%
#define PWM_ENABLE_FILE "/sys/class/pwm/pwmchip2/pwm%d/enable"
#define PWM_PERIOD_FILE "/sys/class/pwm/pwmchip2/pwm%d/period"
#define PWM_DUTY_CYCLE_FILE "/sys/class/pwm/pwmchip2/pwm%d/duty_cycle"
#define PWM_ENABLE_VALUE 1
#define PWM_PERIOD_VALUE PWM_PERIOD
#define PWM_DUTY_CYCLE_VALUE PWM_DUTY_CYCLE
#define LOG_FILE "solar_tracker.log"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c(const char *bus, int addr);
int read_mpu6050_data(int fd, float *pitch, float *roll);
int set_servo_position(int pin, int duty_cycle);
int log_data(FILE *fp, float pitch, float roll, int servo_position);
void signal_handler(int signal);

// Helper function to write to I2C register
int write_i2c_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Helper function to read from I2C register
int read_i2c_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address to I2C device");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }

    // Wake up the MPU-6050
    if (write_i2c_reg(fd, PWR_MGMT_1, 0) < 0) {
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read MPU-6050 data
int read_mpu6050_data(int fd, float *pitch, float *roll) {
    uint8_t buf[6];
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;

    if (read_i2c_reg(fd, ACCEL_XOUT_H, &buf[0]) < 0) return -1;
    if (read_i2c_reg(fd, ACCEL_YOUT_H, &buf[1]) < 0) return -1;
    if (read_i2c_reg(fd, ACCEL_ZOUT_H, &buf[2]) < 0) return -1;
    if (read_i2c_reg(fd, GYRO_XOUT_H, &buf[3]) < 0) return -1;
    if (read_i2c_reg(fd, GYRO_YOUT_H, &buf[4]) < 0) return -1;
    if (read_i2c_reg(fd, GYRO_ZOUT_H, &buf[5]) < 0) return -1;

    accel_x = (buf[0] << 8) | buf[1];
    accel_y = (buf[2] << 8) | buf[3];
    accel_z = (buf[4] << 8) | buf[5];
    gyro_x = (buf[6] << 8) | buf[7];
    gyro_y = (buf[8] << 8) | buf[9];
    gyro_z = (buf[10] << 8) | buf[11];

    // Convert to g's and degrees/second
    float accel_x_g = accel_x / 16384.0;
    float accel_y_g = accel_y / 16384.0;
    float accel_z_g = accel_z / 16384.0;
    float gyro_x_dps = gyro_x / 131.0;
    float gyro_y_dps = gyro_y / 131.0;
    float gyro_z_dps = gyro_z / 131.0;

    // Calculate pitch and roll
    *pitch = atan2(accel_x_g, sqrt(accel_y_g * accel_y_g + accel_z_g * accel_z_g)) * 180 / M_PI;
    *roll = atan2(accel_y_g, sqrt(accel_x_g * accel_x_g + accel_z_g * accel_z_g)) * 180 / M_PI;

    return 0;
}

