        perror("Failed to write PWM duty cycle value");
        close(pwm_enable_fd);
        close(pwm_period_fd);
        close(pwm_duty_cycle_fd);
        return -1;
    }

    close(pwm_enable_fd);
    close(pwm_period_fd);
    close(pwm_duty_cycle_fd);

    return 0;
}

// Function to log data to file
int log_data(FILE *fp, float pitch, float roll, int servo_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

