#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the lamps
#define LAMP1_GPIO 4
#define LAMP2_GPIO 17
#define LAMP3_GPIO 27
#define LAMP4_GPIO 22

// Define PWM frequency and range
#define PWM_FREQUENCY 100
#define PWM_RANGE 100

// Define the schedule file name
#define SCHEDULE_FILE "lighting_schedule.txt"

// Global variables
static volatile int running = 1;
static int gpio_pins[] = {LAMP1_GPIO, LAMP2_GPIO, LAMP3_GPIO, LAMP4_GPIO};
static int num_relays = sizeof(gpio_pins) / sizeof(gpio_pins[0]);
static FILE *schedule_file = NULL;

// Function prototypes
int read_schedule(const char *filename, char *line, char *time_str, int *relay_number, char *state);
int parse_time(const char *time_str, int *hour, int *minute, int *second);
int is_sunrise(int hour, int minute, int second);
int is_sunset(int hour, int minute, int second);
int set_relay_state(int gpio_pin, int state);
int fade_lamp(int gpio_pin, int target_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);

    // Turn off all relays
    for (int i = 0; i < num_relays; i++) {
        set_relay_state(gpio_pins[i], 0);
    }

    // Release GPIO resources
    gpioTerminate();

    // Close the schedule file
    if (schedule_file != NULL) {
        fclose(schedule_file);
    }

    exit(0);
}

// Function to read the schedule from the file
int read_schedule(const char *filename, char *line, char *time_str, int *relay_number, char *state) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening schedule file");
        return -1;
    }

    char *current_line = NULL;
    size_t len = 0;
    ssize_t read;

    while ((read = getline(&current_line, &len, fp)) != -1) {
        if (sscanf(current_line, "%[^,],%d,%[^,],%s", time_str, relay_number, state, NULL) == 4) {
            free(current_line);
            fclose(fp);
            return 0; // Schedule entry found
        }
    }

    free(current_line);
    fclose(fp);
    return -1; // Schedule file read to end
}

// Function to parse the time string
int parse_time(const char *time_str, int *hour, int *minute, int *second) {
    if (sscanf(time_str, "%d:%d:%d", hour, minute, second) == 3) {
        return 0; // Parsing successful
    } else {
        return -1; // Parsing failed
    }
}

// Function to check if the current time is sunrise
int is_sunrise(int hour, int minute, int second) {
    return (hour == 6 && minute == 0 && second == 0);
}

// Function to check if the current time is sunset
int is_sunset(int hour, int minute, int second) {
    return (hour == 18 && minute == 0 && second == 0);
}

// Function to set the state of a relay
int set_relay_state(int gpio_pin, int state) {
    if (gpio_pin < 0 || gpio_pin > 31) {
        fprintf(stderr, "Invalid GPIO pin number: %d\n", gpio_pin);
        return -1;
    }

    if (gpio_pin != LAMP1_GPIO && gpio_pin != LAMP2_GPIO && gpio_pin != LAMP3_GPIO && gpio_pin != LAMP4_GPIO) {
        fprintf(stderr, "GPIO pin %d is not a valid lamp pin.\n", gpio_pin);
        return -1;
    }

    gpioWrite(gpio_pin, state);
    return 0;
}

// Function to fade the lamp brightness using PWM
int fade_lamp(int gpio_pin, int target_state) {
    int current_state = 0;
    int target_state_int = target_state; // Convert char to int
    int step;
    double delay_us = 1000000.0 / PWM_FREQUENCY; // Calculate delay in microseconds

    if (gpio_pin < 0 || gpio_pin > 31) {
        fprintf(stderr, "Invalid GPIO pin number: %d\n", gpio_pin);
        return -1;
    }

    if (gpio_pin != LAMP1_GPIO && gpio_pin != LAMP2_GPIO && gpio_pin != LAMP3_GPIO && gpio_pin != LAMP4_GPIO) {
        fprintf(stderr, "GPIO pin %d is not a valid lamp pin.\n", gpio_pin);
        return -1;
    }

    if (target_state_int < 0 || target_state_int > 100) {
        fprintf(stderr, "Invalid target state: %d. Must be between 0 and 100.\n", target_state_int);
        return -1;
    }

    for (step = current_state; step <= target_state_int; step += 10) {
        if (gpioPWM(gpio_pin, step) != 0) {
            fprintf(stderr, "Error setting PWM duty cycle for GPIO %d to %d\n", gpio_pin, step);
            return -1;
        }
        gpioDelay(delay_us);
    }

    if (gpioPWM(gpio_pin, target_state_int) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle for GPIO %d to %d\n", gpio_pin, target_state_int);
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the schedule file
    schedule_file = fopen(SCHEDULE_FILE, "r");
    if (schedule_file == NULL) {
        perror("Error opening schedule file");
        gpioTerminate();
        return 1;
    }

    // Set GPIO pins as outputs
    for (int i = 0; i < num_relays; i++) {
        gpioSetMode(gpio_pins[i], PI_OUTPUT);
        gpioPWM(gpio_pins[i], 0); // Initialize all relays to off
    }

    char time_str[6];
    int relay_number;
    char state;
    int hour, minute, second;
    int current_time[3];

    // Main loop
    while (running) {
