static int gpio_pins[] = {LAMP1_GPIO, LAMP2_GPIO, LAMP3_GPIO, LAMP4_GPIO};
static int num_relays = sizeof(gpio_pins) / sizeof(gpio_pins[0]);
static FILE *schedule_file = NULL;

// Function prototypes
int read_schedule(const char *filename, char *line, char *time_str, int *relay_number, char *state);
int parse_time(const char *time_str, int *hour, int *minute, int *second);
int is_sunrise(int hour, int minute, int second);
int is_sunset(int hour, int minute, int second);
int set_relay_state(int gpio_pin, int state);
int fade_lamp(int gpio_pin, int target_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);

    // Turn off all relays
    for (int i = 0; i < num_relays; i++) {
        set_relay_state(gpio_pins[i], 0);
    }

    // Release GPIO resources
    gpioTerminate();

    // Close the schedule file
    if (schedule_file != NULL) {
        fclose(schedule_file);
    }

    exit(0);
}

// Function to read the schedule from the file
int read_schedule(const char *filename, char *line, char *time_str, int *relay_number, char *state) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening schedule file");
        return -1;
    }

    char *current_line = NULL;
    size_t len = 0;
    ssize_t read;

    while ((read = getline(&current_line, &len, fp)) != -1) {
        if (sscanf(current_line, "%[^,],%d,%[^,],%s", time_str, relay_number, state, NULL) == 4) {
            free(current_line);
            fclose(fp);
            return 0; // Schedule entry found
        }
    }

    free(current_line);
    fclose(fp);
    return -1; // Schedule file read to end
}

// Function to parse the time string
int parse_time(const char *time_str, int *hour, int *minute, int *second) {
    if (sscanf(time_str, "%d:%d:%d", hour, minute, second) == 3) {
        return 0; // Parsing successful
    } else {
        return -1; // Parsing failed
    }
}

// Function to check if the current time is sunrise
int is_sunrise(int hour, int minute, int second) {
    return (hour == 6 && minute == 0 && second == 0);
}

// Function to check if the current time is sunset
int is_sunset(int hour, int minute, int second) {
    return (hour == 18 && minute == 0 && second == 0);
}

