        return -1;
    }

    if (gpio_pin != LAMP1_GPIO && gpio_pin != LAMP2_GPIO && gpio_pin != LAMP3_GPIO && gpio_pin != LAMP4_GPIO) {
        fprintf(stderr, "GPIO pin %d is not a valid lamp pin.\n", gpio_pin);
        return -1;
    }

    gpioWrite(gpio_pin, state);
    return 0;
}

