        fprintf(stderr, "Invalid GPIO pin number: %d\n", gpio_pin);
        return -1;
    }

    if (gpio_pin != LAMP1_GPIO && gpio_pin != LAMP2_GPIO && gpio_pin != LAMP3_GPIO && gpio_pin != LAMP4_GPIO) {
        fprintf(stderr, "GPIO pin %d is not a valid lamp pin.\n", gpio_pin);
        return -1;
    }

    if (target_state_int < 0 || target_state_int > 100) {
        fprintf(stderr, "Invalid target state: %d. Must be between 0 and 100.\n", target_state_int);
        return -1;
    }

    for (step = current_state; step <= target_state_int; step += 10) {
        if (gpioPWM(gpio_pin, step) != 0) {
            fprintf(stderr, "Error setting PWM duty cycle for GPIO %d to %d\n", gpio_pin, step);
            return -1;
        }
        gpioDelay(delay_us);
    }

    if (gpioPWM(gpio_pin, target_state_int) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle for GPIO %d to %d\n", gpio_pin, target_state_int);
