#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 2.0       // Minimum measurable distance (cm)
#define MAX_DISTANCE 30.0      // Maximum measurable distance (cm)
#define MIN_FREQUENCY 200.0    // Minimum frequency (Hz)
#define MAX_FREQUENCY 2000.0   // Maximum frequency (Hz)
#define TIMEOUT_US 50000        // Timeout for echo pulse (microseconds)

// Global variables
volatile int echo_start_tick = 0;
volatile int echo_end_tick = 0;
volatile int echo_valid = 0;

// Function prototypes
void trigger_sensor();
float get_distance();
float map_distance_to_frequency(float distance);
void set_buzzer_frequency(float frequency);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        gpioPWM(BUZZER_PIN, 0); // Stop the buzzer
        gpioTerminate();         // Terminate pigpio
        exit(0);
    }
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance using the HC-SR04 sensor
float get_distance() {
    echo_valid = 0; // Reset echo validity flag
    echo_start_tick = 0;
    echo_end_tick = 0;

    trigger_sensor();

    // Wait for echo to start
    int start_time = gpioTick();
    while (echo_start_tick == 0 && (gpioTick() - start_time) < TIMEOUT_US) {
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (echo_start_tick == 0) {
        fprintf(stderr, "Error: Timeout waiting for echo start.\n");
        return -1.0; // Indicate timeout error
    }

    // Wait for echo to end
    start_time = gpioTick();
    while (echo_end_tick == 0 && (gpioTick() - start_time) < TIMEOUT_US) {
        gpioDelay(1);
    }

    if (echo_end_tick == 0) {
        fprintf(stderr, "Error: Timeout waiting for echo end.\n");
        return -1.0; // Indicate timeout error
    }

    // Calculate pulse width in microseconds
    int pulse_width = echo_end_tick - echo_start_tick;

    // Calculate distance in centimeters
    float distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 1000000.0 to convert us to s and multiply by 100 to convert to cm

    return distance;
}

// Function to map distance to frequency
float map_distance_to_frequency(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        return MAX_FREQUENCY;
    } else {
        return MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

// Function to set the buzzer frequency
void set_buzzer_frequency(float frequency) {
    int duty_cycle = (int)((frequency / 1000.0) * 255.0); // Map frequency to duty cycle (0-255)
    gpioPWM(BUZZER_PIN, duty_cycle);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set PWM frequency for the buzzer
    gpioSetPWMfrequency(BUZZER_PIN, 1000); // Set PWM frequency to 1 kHz
    gpioSetPWMrange(BUZZER_PIN, 255);     // Set PWM range to 0-255

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        float distance = get_distance();

        if (distance < 0) {
            fprintf(stderr, "Error: Distance measurement failed.\n");
        } else {
            float frequency = map_distance_to_frequency(distance);
            set_buzzer_frequency(frequency);
            printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
        }

        gpioDelay(60000); // Wait 60 ms
    }

    return 0;
}

