#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to set the color of the RGB LED
void set_led_color(float red, float green, float blue)
{
    // Ensure values are within the range [0.0, 1.0]
    red = fmax(0.0, fmin(red, 1.0));
    green = fmax(0.0, fmin(green, 1.0));
    blue = fmax(0.0, fmin(blue, 1.0));

    // Calculate PWM duty cycle for each color
    int red_duty_cycle = (int)(red * 255.0);
    int green_duty_cycle = (int)(green * 255.0);
    int blue_duty_cycle = (int)(blue * 255.0);

    // Set the PWM duty cycle for each color
    gpioPWM(RED_PIN, red_duty_cycle);
    gpioPWM(GREEN_PIN, green_duty_cycle);
    gpioPWM(BLUE_PIN, blue_duty_cycle);
}

// Function to generate a sine wave value
float generate_sine_wave(float time)
{
    return sin(time * 2.0 * M_PI);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Register signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    float time = 0.0;
    while (!terminate)
    {
        // Generate sine wave value
        float proximity = generate_sine_wave(time);

        // Set LED color based on proximity value
        set_led_color(proximity, 1.0 - proximity, 0.0);

        // Increment time
        time += 0.01;

        // Delay for a short period
        gpioDelay(10000); // 10ms
    }

    // Turn off the LED
    set_led_color(0.0, 0.0, 0.0);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

