#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_SENSITIVITY 131.0

volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", signal);
}

int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

int write_i2c(int fd, int reg, int val) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = val;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

int read_i2c(int fd, int reg, unsigned char *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address for read");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    unsigned char buf[6];
    if (read_i2c(fd, GYRO_XOUT_H, buf, 6) < 0) {
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

int log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %d, %d, %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z);
    fflush(fp);
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = init_i2c(I2C_BUS, MPU6050_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    if (write_i2c(i2c_fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake up MPU6050. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    int16_t x, y, z;
    while (program_running) {
        if (read_gyro_data(i2c_fd, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Failed to read gyroscope data.\n");
        }
        usleep(100000); // 100 ms
    }

    fclose(log_file);
    close(i2c_fd);
    return 0;
}

