#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define BUTTON_PIN 17
#define BUZZER_PIN 18

// Define melody parameters
#define NUM_NOTES 8
const int melody[] = {262, 294, 330, 349, 392, 440, 494, 523}; // Frequencies (Hz)
const int noteDurations[] = {250, 250, 250, 250, 250, 250, 250, 250}; // Durations (ms)

// Debounce time (ms)
#define DEBOUNCE_TIME 50

// Global variables
volatile int melodyPlaying = 0; // Flag to indicate if a melody is currently playing
volatile int buttonPressed = 0; // Flag to indicate if the button is pressed

// Function prototypes
void playMelody();
void buttonInterruptHandler(int gpio, int level, uint32_t tick, void *user);
void signalHandler(int signal);

// Function to play a melody
void playMelody() {
    melodyPlaying = 1; // Set the flag to indicate melody playback

    for (int i = 0; i < NUM_NOTES; i++) {
        gpioHardwarePWM(BUZZER_PIN, 192, 1); // Set frequency and duty cycle
        gpioDelay(noteDurations[i] * 1000); // Delay for note duration (microseconds)
        gpioHardwarePWM(BUZZER_PIN, 0, 0); // Stop the PWM signal
    }

    melodyPlaying = 0; // Reset the flag after melody completion
}

// Interrupt handler for button press
void buttonInterruptHandler(int gpio, int level, uint32_t tick, void *user) {
    static uint32_t lastTick = 0;
    uint32_t currentTime = gpioTick();

    // Debounce the button
    if (currentTime - lastTick > DEBOUNCE_TIME * 1000) {
        if (!buttonPressed) {
            buttonPressed = 1; // Set the flag when the button is pressed
            playMelody(); // Play the melody
        }
        lastTick = currentTime;
    }
}

// Signal handler for clean shutdown
void signalHandler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioHardwarePWM(BUZZER_PIN, 0, 0); // Stop PWM
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Enable pull-up resistor on the button pin
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    // Set up interrupt handler for button press (active-low)
    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, buttonInterruptHandler, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for clean shutdown
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    printf("Musical doorbell running. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (melodyPlaying) {
            // Check if the button is pressed during melody playback
            if (gpioRead(BUTTON_PIN) == 0) {
                // Stop the melody
                melodyPlaying = 0;
                gpioHardwarePWM(BUZZER_PIN, 0, 0); // Stop PWM
                gpioDelay(100 * 1000); // Small delay to prevent immediate retrigger
            }
        }
        gpioDelay(1000); // Small delay to reduce CPU usage
    }

    return 0;
}

