#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/time.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define LOG_FILE "vibration_events.log"
#define WINDOW_SIZE 5

static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;

// Function to get ISO-8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log event to file
int log_event(int value) {
    char* timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp, skipping log entry.\n");
        return -1;
    }

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        free(timestamp);
        return -1;
    }

    fprintf(log_file, "%s %d\n", timestamp, value);
    fflush(log_file); // Ensure data is written to disk immediately
    free(timestamp);
    return 0;
}

// Function to check for earthquake alert
void check_earthquake_alert(int value) {
    static int event_window[WINDOW_SIZE] = {0}; // Initialize the window
    static int window_index = 0;

    event_window[window_index] = value;
    window_index = (window_index + 1) % WINDOW_SIZE;

    int high_count = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        if (event_window[i] == 1) {
            high_count++;
        }
    }

    if (high_count >= 3) {
        char* timestamp = get_iso8601_timestamp();
        if (timestamp != NULL) {
            printf("EARTHQUAKE ALERT: %s\n", timestamp);
            free(timestamp);
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        fprintf(stderr, "Received signal %d, terminating...\n", sig);
        terminate = 1;
    }
}

int main(int argc, char *argv[]) {
    int poll_timeout = 1000; // Default timeout

    if (argc > 1) {
        poll_timeout = atoi(argv[1]);
        if (poll_timeout <= 0) {
            fprintf(stderr, "Invalid timeout value. Using default timeout of 1000ms.\n");
            poll_timeout = 1000;
        }
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for input
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "vibration_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    int ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = poll_timeout * 1000000; // Convert milliseconds to nanoseconds

    int last_value = 0; // Store the last known value
    int current_value;
    int edge_detected = 0;

    while (!terminate) {
        ret = gpiod_line_event_wait(line, &sleep_time);
        if (ret < 0) {
            fprintf(stderr, "Error waiting for event: %s\n", strerror(errno));
            break;
        }

        ret = gpiod_line_event_read(line, &current_value);
        if (ret < 0) {
            fprintf(stderr, "Error reading line value: %s\n", strerror(errno));
            break;
        }

        if (current_value != last_value) {
            if (!edge_detected) {
                // Rising edge
                if (log_event(current_value) != 0) {
                    fprintf(stderr, "Error logging rising edge.\n");
                }
                edge_detected = 1;
            } else {
                // Falling edge
                if (log_event(current_value) != 0) {
                    fprintf(stderr, "Error logging falling edge.\n");
                }
                edge_detected = 0;
            }
            check_earthquake_alert(current_value);
        }

        last_value = current_value;
    }

    // Cleanup
    fprintf(stderr, "Releasing resources...\n");
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }

    fprintf(stderr, "Exiting.\n");
    return 0;
}

