    while (!terminate) {
        ret = gpiod_line_event_wait(line, &sleep_time);
        if (ret < 0) {
            fprintf(stderr, "Error waiting for event: %s\n", strerror(errno));
            break;
        }

        ret = gpiod_line_event_read(line, &current_value);
        if (ret < 0) {
            fprintf(stderr, "Error reading line value: %s\n", strerror(errno));
            break;
        }

        if (current_value != last_value) {
            if (!edge_detected) {
                // Rising edge
                if (log_event(current_value) != 0) {
                    fprintf(stderr, "Error logging rising edge.\n");
                }
                edge_detected = 1;
            } else {
                // Falling edge
                if (log_event(current_value) != 0) {
                    fprintf(stderr, "Error logging falling edge.\n");
                }
                edge_detected = 0;
            }
            check_earthquake_alert(current_value);
        }

        last_value = current_value;
    }

    // Cleanup
    fprintf(stderr, "Releasing resources...\n");
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }

    fprintf(stderr, "Exiting.\n");
    return 0;
}

