#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// LSM303DLHC I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC register addresses
#define MR_REG_M 0x02
#define CRA_REG_M 0x00
#define OUT_X_L_M 0x03
#define OUT_X_H_M 0x04
#define OUT_Y_L_M 0x05
#define OUT_Y_H_M 0x06
#define OUT_Z_L_M 0x07
#define OUT_Z_H_M 0x08

// Hard-iron calibration offsets
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

// Data rate (Hz)
#define DATA_RATE 15

// Compass directions
const char *directions[] = {"N", "NE", "E", "SE", "S", "SW", "W", "NW"};

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int16_t combine_registers(uint8_t msb, uint8_t lsb);
float calibrate_data(int16_t x, int16_t y, int16_t z);
float calculate_heading(float x, float y);
void log_data(float x, float y, float z, float heading);
void print_heading_direction(float heading);
void signal_handler(int signal);
int setup_i2c(int address);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// Combine MSB and LSB to form a 16-bit signed integer
int16_t combine_registers(uint8_t msb, uint8_t lsb) {
    return (int16_t)((msb << 8) | lsb);
}

// Calibrate the raw magnetometer data
float calibrate_data(int16_t x, int16_t y, int16_t z) {
    return (float)(x - X_OFFSET) + (float)(y - Y_OFFSET) + (float)(z - Z_OFFSET);
}

// Calculate the compass heading in degrees
float calculate_heading(float x, float y) {
    float heading_rad = atan2f(y, x);
    if (heading_rad < 0) {
        heading_rad += 2 * M_PI;
    }
    float heading_deg = heading_rad * 180 / M_PI;
    if (heading_deg < 0) {
        heading_deg += 360;
    }
    return heading_deg;
}

// Log the data to a CSV file
void log_data(float x, float y, float z, float heading) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f\n", timestamp, x, y, z, heading);
    fflush(log_file);
}

// Print the heading direction and numeric heading to the console
void print_heading_direction(float heading) {
    int index = (int)((heading / 45.0) % 8);
    if (index < 0) index += 8;
    printf("Heading: %.2f degrees, Direction: %s\n", heading, directions[index]);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Exiting...\n");
}

// Setup I2C communication
int setup_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }

    // Configure continuous-conversion mode
    if (i2c_write_reg(fd, MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Failed to set continuous-conversion mode\n");
        close(fd);
        return -1;
    }

    // Set data rate (optional)
    if (i2c_write_reg(fd, CRA_REG_M, 0x14) < 0) {
        fprintf(stderr, "Failed to set data rate\n");
        close(fd);
        return -1;
    }

    return fd;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup I2C communication
    i2c_fd = setup_i2c(LSM303_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to setup I2C communication\n");
        return 1;
    }

    // Check if the log file exists, and write the header if it doesn't
    log_file = fopen("mag_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n");
    }
    rewind(log_file);

    // Main loop
    while (program_running) {
        uint8_t data[6];
        int16_t x, y, z;
        float calibrated_x, calibrated_y, calibrated_z, heading;

        // Read magnetometer data
        if (i2c_read_reg(i2c_fd, OUT_X_L_M, data, 6) < 0) {
            fprintf(stderr, "Failed to read magnetometer data\n");
            continue; // Skip to the next iteration
        }

        // Combine MSB and LSB to form 16-bit signed integers
        x = combine_registers(data[1], data[0]);
        z = combine_registers(data[3], data[2]);
        y = combine_registers(data[5], data[4]);

        // Calibrate the data
        calibrated_x = calibrate_data(x, y, z);
        calibrated_y = calibrate_data(x, y, z);
        calibrated_z = calibrate_data(x, y, z);

        // Calculate the heading
        heading = calculate_heading(calibrated_x, calibrated_y);

        // Log the data
        log_data(calibrated_x, calibrated_y, calibrated_z, heading);

        // Print the heading direction and numeric heading
        print_heading_direction(heading);

        // Wait for 1 second
        sleep(1);
    }

    // Close I2C file descriptor and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

