#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Constants
#define TOUCH_SENSOR_GPIO 4
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY_MS 200
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345
#define LOG_FILE "relay_log.json"

// Global variables
static volatile int relay_state = 0; // 0 = OFF, 1 = ON
static volatile unsigned long last_touch_time = 0;
static int socket_desc;

// Function prototypes
void touch_callback(int gpio, int level, unsigned int tick, void *user);
int send_relay_state(const char *timestamp, const char *relay_state_str);
int log_relay_state(const char *timestamp, const char *relay_state_str);
void signal_handler(int signal);

// Function to format timestamp in ISO 8601 format
char* format_timestamp(char* timestamp_str, size_t timestamp_str_size) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp_str, timestamp_str_size, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp_str;
}

// Callback function for touch sensor
void touch_callback(int gpio, int level, unsigned int tick, void *user) {
    unsigned long current_time = gpioTick();

    // Debounce logic
    if (level == 1) { // Touch detected
        if (current_time - last_touch_time > DEBOUNCE_DELAY_MS * 1000) {
            relay_state = !relay_state; // Toggle relay state
            gpioWrite(RELAY_GPIO, relay_state);

            // Get current timestamp
            char timestamp[32];
            format_timestamp(timestamp, sizeof(timestamp));

            // Send relay state to server
            if (send_relay_state(timestamp, relay_state ? "ON" : "OFF") != 0) {
                fprintf(stderr, "Error sending relay state to server.\n");
            }

            // Log relay state to file
            if (log_relay_state(timestamp, relay_state ? "ON" : "OFF") != 0) {
                fprintf(stderr, "Error logging relay state to file.\n");
            }

            last_touch_time = current_time;
        }
    }
}

// Function to send relay state to the server
int send_relay_state(const char *timestamp, const char *relay_state_str) {
    char message[256];
    snprintf(message, sizeof(message), "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n", timestamp, relay_state_str);

    if (send(socket_desc, message, strlen(message), 0) < 0) {
        perror("Send failed");
        return -1;
    }
    return 0;
}

// Function to log relay state to a file
int log_relay_state(const char *timestamp, const char *relay_state_str) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n", timestamp, relay_state_str);
    fclose(fp);
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioWrite(RELAY_GPIO, 0); // Turn relay OFF
    send_relay_state(NULL, "OFF"); // Send OFF state to server
    log_relay_state(NULL, "OFF"); // Log OFF state to file
    close(socket_desc);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_GPIO, PI_PUD_DOWN); // Enable pull-down resistor

    // Set up interrupt on touch sensor
    if (gpioSetISRFuncEx(TOUCH_SENSOR_GPIO, RISING_EDGE, 0, touch_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Create socket
    socket_desc = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_desc == -1) {
        perror("Could not create socket");
        gpioTerminate();
        return 1;
    }

    struct sockaddr_in server;
    server.sin_addr.s_addr = inet_addr(SERVER_IP);
    server.sin_family = AF_INET;
    server.sin_port = htons(SERVER_PORT);

    // Connect to server
    if (connect(socket_desc, (struct sockaddr *)&server, sizeof(server)) < 0) {
        perror("Connect error");
        close(socket_desc);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        gpioDelay(100); // Reduce CPU usage
    }

    return 0;
}

