#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define chip name
#define CHIP_NAME "gpiochip0"

// Define log file name
#define LOG_FILE "irrigation_log.txt"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[4]; // Array to store line pointers
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int gpio_init(void);
int gpio_set_direction(int pin, const char *direction);
int gpio_write(int pin, int value);
int gpio_read(int pin);
int read_soil_moisture(void);
void activate_relay(int pin, int duration_ms);
void deactivate_relay(int pin);
void log_event(int relay_number, int moisture_level);
void signal_handler(int sig);
void cleanup(void);

// Function to initialize GPIO
int gpio_init(void) {
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", CHIP_NAME);
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, RELAY_PINS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting GPIO line %d\n", RELAY_PINS[i]);
            perror("gpiod_chip_get_line");
            cleanup();
            return -1;
        }

        if (gpiod_line_request_output(lines[i], "irrigation", 1) < 0) {
            fprintf(stderr, "Error requesting GPIO line %d as output\n", RELAY_PINS[i]);
            perror("gpiod_line_request_output");
            cleanup();
            return -1;
        }
    }

    return 0;
}

// Function to set GPIO direction
int gpio_set_direction(int pin, const char *direction) {
    if (!lines[pin]) {
        fprintf(stderr, "Error: GPIO line not initialized for pin %d\n", pin);
        return -1;
    }

    int ret = gpiod_line_request_output(lines[pin], direction, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO direction for pin %d: %s\n", pin, direction);
        perror("gpiod_line_request_output");
        return -1;
    }

    return 0;
}

// Function to write to GPIO
int gpio_write(int pin, int value) {
    if (!lines[pin]) {
        fprintf(stderr, "Error: GPIO line not initialized for pin %d\n", pin);
        return -1;
    }

    int ret = gpiod_line_set_value(lines[pin], value);
    if (ret < 0) {
        fprintf(stderr, "Error writing to GPIO line %d: %d\n", pin, value);
        perror("gpiod_line_set_value");
        return -1;
    }

    return 0;
}

// Function to read from GPIO
int gpio_read(int pin) {
    if (!lines[pin]) {
        fprintf(stderr, "Error: GPIO line not initialized for pin %d\n", pin);
        return -1;
    }

    int value = gpiod_line_get_value(lines[pin]);
    if (value < 0) {
        fprintf(stderr, "Error reading from GPIO line %d: %d\n", pin, value);
        perror("gpiod_line_get_value");
        return -1;
    }

    return value;
}

// Function to simulate soil moisture reading
int read_soil_moisture(void) {
    srand(time(NULL)); // Seed the random number generator
    return rand() % 101; // Returns a value between 0 and 100
}

// Function to activate a relay
void activate_relay(int pin, int duration_ms) {
    gpio_write(pin, 0); // Activate relay (LOW)
    usleep(duration_ms * 1000); // Wait for specified duration
    gpio_write(pin, 1); // Deactivate relay (HIGH)
}

// Function to deactivate a relay
void deactivate_relay(int pin) {
    gpio_write(pin, 1); // Deactivate relay (HIGH)
}

// Function to log an event
void log_event(int relay_number, int moisture_level) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s Relay %d, Moisture: %d\n", buf, relay_number, moisture_level);
        fflush(log_file); // Flush the buffer to ensure immediate write
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Cleanup function
void cleanup(void) {
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        perror("fopen");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int moisture_level = read_soil_moisture();
        if (moisture_level < 30) {
            printf("Moisture level below 30, activating relays...\n");
            for (int i = 0; i < 4; i++) {
                printf("Activating relay %d...\n", i + 1);
                activate_relay(RELAY_PINS[i], 5000); // Activate for 5 seconds
                log_event(i + 1, moisture_level);
            }
        } else {
            printf("Moisture level above 30, no irrigation needed.\n");
        }

        sleep(10); // Wait 10 seconds
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting cleanly.\n");
    return 0;
}

