#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define VALVE_SERVO_PIN 17
#define NOZZLE_SERVO_PIN 18

// Define servo pulse width limits
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

// Define moisture thresholds
#define MOISTURE_THRESHOLD_LOW 50
#define MOISTURE_THRESHOLD_HIGH 60

// Define watering cycle parameters
#define WATERING_DURATION 10 // seconds
#define WATERING_DELAY 5     // seconds

// Define servo angles
#define SERVO_ANGLE_CLOSED 0
#define SERVO_ANGLE_OPEN 90
#define SERVO_ANGLE_NOZZLE_0 0
#define SERVO_ANGLE_NOZZLE_45 45
#define SERVO_ANGLE_NOZZLE_90 90
#define SERVO_ANGLE_NOZZLE_135 135
#define SERVO_ANGLE_NOZZLE_180 180

// Global flag to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping...\n", signal);
}

// Function to set servo angle
int set_servo_angle(int gpio, int angle) {
    int pulse_width;

    if (angle < SERVO_MIN_PULSE_WIDTH) {
        pulse_width = SERVO_MIN_PULSE_WIDTH;
    } else if (angle > SERVO_MAX_PULSE_WIDTH) {
        pulse_width = SERVO_MAX_PULSE_WIDTH;
    } else {
        pulse_width = angle;
    }

    int result = gpioServo(gpio, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error setting servo %d to %d: %d\n", gpio, pulse_width, result);
        return -1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to water the plant
int water_plant(int valve_gpio, int nozzle_gpio) {
    printf("Watering plant...\n");

    // Open the valve
    if (set_servo_angle(valve_gpio, SERVO_ANGLE_OPEN) != 0) {
        fprintf(stderr, "Error opening valve servo.\n");
        return -1;
    }

    // Sweep the nozzle
    for (int i = 0; i < 5; i++) {
        int angle = (i * 45) + SERVO_ANGLE_NOZZLE_0;
        if (set_servo_angle(nozzle_gpio, angle) != 0) {
            fprintf(stderr, "Error setting nozzle servo to %d degrees.\n", angle);
            return -1; // Exit watering cycle on error
        }
        gpioDelay(2000000); // Wait 2 seconds
    }

    // Close the valve
    if (set_servo_angle(valve_gpio, SERVO_ANGLE_CLOSED) != 0) {
        fprintf(stderr, "Error closing valve servo.\n");
        return -1; // Exit watering cycle on error
    }

    gpioDelay(5000000); // Wait 5 seconds

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(VALVE_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(NOZZLE_SERVO_PIN, PI_OUTPUT);

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Simulate soil moisture readings
        int moisture_level = 20; // Cycle through 20, 40, 60, 80, 100
        if (moisture_level > 100) {
            moisture_level = 20;
        }

        // Check moisture level and water if needed
        if (moisture_level < MOISTURE_THRESHOLD_LOW) {
            printf("Moisture level low (%d), watering plant...\n", moisture_level);
            if (water_plant(VALVE_SERVO_PIN, NOZZLE_SERVO_PIN) != 0) {
                fprintf(stderr, "Watering failed.\n");
            }
        } else if (moisture_level > MOISTURE_THRESHOLD_HIGH) {
            printf("Moisture level high (%d), skipping watering.\n", moisture_level);
        }

        // Wait before next reading
        gpioDelay(WATERING_DELAY * 1000000); // Wait WATERING_DELAY seconds
    }

    // Stop servos
    set_servo_angle(VALVE_SERVO_PIN, SERVO_ANGLE_CLOSED);
    set_servo_angle(NOZZLE_SERVO_PIN, SERVO_ANGLE_CLOSED);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

