#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43

// Sensitivity scale factor (LSB/deg/s)
#define GYRO_SCALE_FACTOR 131.0

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *bus);
int init_mpu6050(int fd);
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z);
void convert_gyro_data(int16_t x, int16_t y, int16_t z, float *x_deg_per_sec, float *y_deg_per_sec, float *z_deg_per_sec);
int log_data(FILE *fp, float x, float y, float z);
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Initialize I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// Initialize MPU-6050
int init_mpu6050(int fd) {
    // Wake up the MPU-6050
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }

    if (i2c_smbus_write_byte_data(fd, PWR_MGMT_1, 0x00) < 0) {
        perror("Error writing to PWR_MGMT_1 register");
        return -1;
    }

    return 0;
}

// Read gyroscope data
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];

    if (i2c_smbus_read_i2c_block_data(fd, GYRO_XOUT_H, I2C_M_START | I2C_M_RD, (char *)buffer) < 0) {
        perror("Error reading gyroscope data");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
