#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 343.0  // Speed of sound in m/s
#define TIMEOUT_US 50000       // 50 ms timeout in microseconds
#define MIN_GUARD_TIME_MS 60    // Minimum guard time between measurements in milliseconds
#define LOG_FILE "distance_log.txt"

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int gpio_init(void);
int trigger_pulse(void);
int measure_pulse_width(void);
float calculate_distance(int pulse_width);
int log_distance(float distance);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// GPIO initialization function
int gpio_init(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get trigger line
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get echo line
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        return -1;
    }

    // Request trigger line as output
    ret = gpiod_line_request_output(trigger_line, "distance_sensor", 0);
    if (ret < 0) {
        perror("Error requesting trigger line as output");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request echo line as input
    ret = gpiod_line_request_input(echo_line, "distance_sensor");
    if (ret < 0) {
        perror("Error requesting echo line as input");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Trigger pulse function
int trigger_pulse(void) {
    int ret;

    // Set trigger line high
    ret = gpiod_line_set_value(trigger_line, 1);
    if (ret < 0) {
        perror("Error setting trigger line high");
        return -1;
    }

    // Wait 10 microseconds
    usleep(10000);

    // Set trigger line low
    ret = gpiod_line_set_value(trigger_line, 0);
    if (ret < 0) {
        perror("Error setting trigger line low");
        return -1;
    }

    return 0;
}

// Measure pulse width function
int measure_pulse_width(void) {
    struct timespec start, end;
    int timeout_counter;

    // Wait for echo line to go high
    timeout_counter = 0;
    while (gpiod_line_get_value(echo_line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &start);
        timeout_counter++;
        if (timeout_counter > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo high\n");
            return -1;
        }
        usleep(1); // Small delay to avoid busy-waiting
    }

    // Record start time
    clock_gettime(CLOCK_MONOTONIC, &start);

    // Wait for echo line to go low
    timeout_counter = 0;
    while (gpiod_line_get_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        timeout_counter++;
        if (timeout_counter > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo low\n");
            return -1;
        }
        usleep(1); // Small delay to avoid busy-waiting
    }

    // Record end time
    clock_gettime(CLOCK_MONOTONIC, &end);

    // Calculate pulse width in microseconds
    return (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
}

// Calculate distance function
float calculate_distance(int pulse_width) {
    return (float)pulse_width * 0.01715;
}

// Log distance function
int log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Cleanup function
void cleanup(void) {
    printf("Cleaning up resources...\n");

    // Release GPIO lines
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main(void) {
    int pulse_width;
    float distance;
    struct timespec sleep_time;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Trigger pulse
        if (trigger_pulse() < 0) {
            fprintf(stderr, "Trigger pulse failed. Logging -1.\n");
            log_distance(-1.0);
        } else {
            // Measure pulse width
            pulse_width = measure_pulse_width();
            if (pulse_width < 0) {
                fprintf(stderr, "Pulse width measurement failed. Logging -1.\n");
                log_distance(-1.0);
            } else {
                // Calculate distance
                distance = calculate_distance(pulse_width);

                // Log distance
                if (log_distance(distance) < 0) {
                    fprintf(stderr, "Logging distance failed.\n");
                } else {
                    printf("Distance: %.2f cm\n", distance);
                }
            }
        }

        // Sleep for 1 second
        sleep_time.tv_sec = 1;
        sleep_time.tv_nsec = 0;
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

