#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_RELAY 18
#define DISTANCE_THRESHOLD 50 // cm

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x0110
#define VL53L1X_REG_SYSRANGE_START 0x000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init(int i2c_handle);
int vl53l1x_read_distance(int i2c_handle, int *distance);
void control_relay(int gpio_pin, int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Shutting down gracefully...\n");
        terminate = 1;
    }
}

// VL53L1X initialization function
int vl53l1x_init(int i2c_handle) {
    // Check sensor ID
    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, data, 2) != 2) {
        fprintf(stderr, "Error reading sensor ID\n");
        return -1;
    }
    if (data[0] != 0xEA || data[1] != 0xAA) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X 0x%02X\n", data[0], data[1]);
        return -1;
    }

    // Reset sensor
    if (i2cWriteByteData(i2c_handle, 0x0000, 0x00) != 0) {
        fprintf(stderr, "Error resetting sensor\n");
        return -1;
    }
    gpioDelay(10000); // Wait 10 ms

    // Configure ranging mode (continuous)
    if (i2cWriteByteData(i2c_handle, 0x0080, 0x01) != 0) {
        fprintf(stderr, "Error setting ranging mode\n");
        return -1;
    }

    return 0;
}

// VL53L1X distance reading function
int vl53l1x_read_distance(int i2c_handle, int *distance) {
    char data[2];
    int range_status;

    // Read range status
    range_status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
    if (range_status < 0) {
        fprintf(stderr, "Error reading range status\n");
        return -1;
    }

    // Read distance (16-bit)
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 2) != 2) {
        fprintf(stderr, "Error reading distance\n");
        return -1;
    }

    *distance = (data[0] << 8) | data[1];

    return 0;
}

// Relay control function
void control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int distance;

    // Main loop
    while (!terminate) {
        // Read distance from VL53L1X
        if (vl53l1x_read_distance(i2c_handle, &distance) == 0) {
            // Log distance to stdout
            printf("Distance: %d mm\n", distance);

            // Control relay based on distance
            if (distance <= DISTANCE_THRESHOLD * 10) {
                control_relay(GPIO_RELAY, 1); // Open door
            } else {
                control_relay(GPIO_RELAY, 0); // Close door
            }
        } else {
            fprintf(stderr, "Error reading distance. Retrying...\n");
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    control_relay(GPIO_RELAY, 0); // Ensure relay is off
    gpioTerminate();

    return 0;
}

