#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for graceful shutdown
void signal_handler(int sig);

// Function to write a byte to an I2C register
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C register
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (address) failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];
    if (read(fd, buffer, 6) != 6) {
        perror("I2C read gyro data failed");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to convert raw gyroscope data to degrees/second
void convert_gyro_data(int16_t x, int16_t y, int16_t z, float *x_dps, float *y_dps, float *z_dps) {
    *x_dps = (float)x / 131.0;
    *y_dps = (float)y / 131.0;
    *z_dps = (float)z / 131.0;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Wake up the MPU-6050
    if (i2c_write_reg(i2c_fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake up MPU-6050\n");
        close(i2c_fd);
        return 1;
    }

    // Set gyroscope full-scale range to ±250 dps
    if (i2c_write_reg(i2c_fd, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to set gyroscope full-scale range\n");
        close(i2c_fd);
        return 1;
    }

    int16_t x, y, z;
    float x_dps, y_dps, z_dps;

    // Main loop
    while (1) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Failed to read gyroscope data\n");
            break;
        }

        // Convert gyroscope data to degrees/second
        convert_gyro_data(x, y, z, &x_dps, &y_dps, &z_dps);

        // Log the data to the console
        printf("X: %.2f dps, Y: %.2f dps, Z: %.2f dps\n", x_dps, y_dps, z_dps);

        // Delay for 100ms
        usleep(100000);
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, exiting gracefully...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

