#include <errno.h>

// Define GPIO pins
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define server address and port
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345

// Define watering cycle interval (seconds)
#define WATERING_INTERVAL 86400

// Define relay activation duration (seconds)
#define RELAY_DURATION 5

// Define polling interval (seconds)
#define POLLING_INTERVAL 60

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay1_line = NULL;
static struct gpiod_line *relay2_line = NULL;
static struct gpiod_line *relay3_line = NULL;
static struct gpiod_line *relay4_line = NULL;
static int running = 1;
static int socket_fd = -1;

// Function prototypes
int gpio_init(const char *chipname);
int gpio_set_direction(struct gpiod_line *line, const char *direction);
int gpio_write(struct gpiod_line *line, int value);
int log_watering_cycle(const char *timestamp);
int send_watering_event(const char *timestamp);
void cleanup(int signal);

// Signal handler
void cleanup(int signal) {
    printf("Cleaning up and exiting...\n");
    running = 0;

    // Release GPIO lines
    if (relay1_line) {
        gpiod_line_release(relay1_line);
    }
    if (relay2_line) {
        gpiod_line_release(relay2_line);
    }
    if (relay3_line) {
        gpiod_line_release(relay3_line);
    }
    if (relay4_line) {
        gpiod_line_release(relay4_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close socket
    if (socket_fd != -1) {
        close(socket_fd);
    }

    exit(0);
}

// Initialize GPIO chip
int gpio_init(const char *chipname) {
    chip = gpiod_chip_open_by_name(chipname);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s': %s\n", chipname, strerror(errno));
        return -1;
    }
    return 0;
}

// Set GPIO line direction (input/output)
int gpio_set_direction(struct gpiod_line *line, const char *direction) {
    int ret = gpiod_line_request_output(line, "watering_system", 0); // Initial value LOW
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set GPIO line direction: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Write value to GPIO line
int gpio_write(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not write value to GPIO line: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Log watering cycle to file
int log_watering_cycle(const char *timestamp) {
    FILE *fp = fopen("watering_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open watering_log.txt for writing: %s\n", strerror(errno));
        return -1;
    }
    fprintf(fp, "%s\n", timestamp);
    fclose(fp);
    return 0;
}

// Send watering event to server
int send_watering_event(const char *timestamp) {
    struct sockaddr_in server_addr;

    // Create socket
    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd < 0) {
        fprintf(stderr, "Error: Could not create socket: %s\n", strerror(errno));
        return -1;
    }

    // Configure server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Error: Invalid server IP address\n");
        close(socket_fd);
        socket_fd = -1;
        return -1;
    }

    // Connect to server
    if (connect(socket_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Error: Could not connect to server: %s\n", strerror(errno));
        close(socket_fd);
        socket_fd = -1;
        return -1;
    }

    // Send timestamp
    if (send(socket_fd, timestamp, strlen(timestamp), 0) < 0) {
        fprintf(stderr, "Error: Could not send data to server: %s\n", strerror(errno));
        close(socket_fd);
        socket_fd = -1;
        return -1;
    }

    close(socket_fd);
    socket_fd = -1; // Reset socket_fd after closing
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize GPIO
    if (gpio_init(GPIOCHIP) < 0) {
        return 1;
    }

    // Set GPIO line directions
    if (gpio_set_direction(relay1_line, "output") < 0 ||
        gpio_set_direction(relay2_line, "output") < 0 ||
