            gpio_write(relay1_line, 0);
            sleep(RELAY_DURATION);
            gpio_write(relay1_line, 1);

            // Activate relay 2
            printf("Activating relay 2\n");
            gpio_write(relay2_line, 0);
            sleep(RELAY_DURATION);
            gpio_write(relay2_line, 1);

            // Activate relay 3
            printf("Activating relay 3\n");
            gpio_write(relay3_line, 0);
            sleep(RELAY_DURATION);
            gpio_write(relay3_line, 1);

