            sleep(RELAY_DURATION);
            gpio_write(relay4_line, 1);

            // Update last watering time
            last_watering_time = current_time;
        }

        // Poll every 60 seconds
        sleep(POLLING_INTERVAL);
    }

    // Cleanup and exit
    cleanup(0);
    return 0;
}

