void signal_handler(int signal) {
    program_running = 0;
    log_event("Received signal, shutting down...");
}

// Initialize GPIO library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return 1; // Indicate failure
    }
    log_event("pigpio initialisation successful");
    return 0; // Indicate success
}

// Set GPIO pin mode
int set_gpio_mode(int pin, int mode) {
    if (gpioSetMode(pin, mode) != 0) {
        char message[100];
        sprintf(message, "Failed to set GPIO %d mode to %d", pin, mode);
        log_event(message);
        return 1; // Indicate failure
    }
    char message[100];
    sprintf(message, "GPIO %d mode set to %d", pin, mode);
    log_event(message);
    return 0; // Indicate success
}

// Set PWM frequency
int set_pwm_frequency(int pin, int frequency) {
    if (gpioSetPWMfrequency(pin, frequency) != frequency) {
        char message[100];
        sprintf(message, "Failed to set PWM frequency for GPIO %d to %d", pin, frequency);
        log_event(message);
        return 1; // Indicate failure
    }
    char message[100];
    sprintf(message, "PWM frequency set for GPIO %d to %d", pin, frequency);
    log_event(message);
    return 0; // Indicate success
}

// Set PWM range
int set_pwm_range(int pin, int range) {
    if (gpioSetPWMrange(pin, range) != range) {
        char message[100];
        sprintf(message, "Failed to set PWM range for GPIO %d to %d", pin, range);
        log_event(message);
        return 1; // Indicate failure
    }
    char message[100];
    sprintf(message, "PWM range set for GPIO %d to %d", pin, range);
    log_event(message);
    return 0; // Indicate success
}

// Set relay duty cycle
int set_relay_duty_cycle(int pin, int duty_cycle) {
    if (gpioPWM(pin, duty_cycle) != duty_cycle) {
        char message[100];
        sprintf(message, "Failed to set duty cycle for GPIO %d to %d", pin, duty_cycle);
        log_event(message);
        return 1; // Indicate failure
    }
    char message[100];
    sprintf(message, "Duty cycle set for GPIO %d to %d", pin, duty_cycle);
    log_event(message);
    return 0; // Indicate success
}

// Increment duty cycle
int increment_duty_cycle(int *duty_cycle, int increment) {
    *duty_cycle += increment;
    if (*duty_cycle > PWM_RANGE) {
        *duty_cycle = PWM_RANGE;
    }
    return 0;
}

// Log event to file
int log_event(const char *message) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file not initialized.\n");
        return 1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    if (set_gpio_mode(RELAY1_PIN, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY2_PIN, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY3_PIN, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY4_PIN, PI_OUTPUT) != 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency and range for all relays
    if (set_pwm_frequency(RELAY1_PIN, PWM_FREQUENCY) != 0 ||
        set_pwm_frequency(RELAY2_PIN, PWM_FREQUENCY) != 0 ||
        set_pwm_frequency(RELAY3_PIN, PWM_FREQUENCY) != 0 ||
        set_pwm_frequency(RELAY4_PIN, PWM_FREQUENCY) != 0 ||
        set_pwm_range(RELAY1_PIN, PWM_RANGE) != 0 ||
        set_pwm_range(RELAY2_PIN, PWM_RANGE) != 0 ||
        set_pwm_range(RELAY3_PIN, PWM_RANGE) != 0 ||
        set_pwm_range(RELAY4_PIN, PWM_RANGE) != 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Sunrise simulation loop
    int duty_cycle = 0;
    for (int i = 0; i < SUNRISE_DURATION && program_running; ++i) {
        if (set_relay_duty_cycle(RELAY1_PIN, duty_cycle) != 0 ||
            set_relay_duty_cycle(RELAY2_PIN, duty_cycle) != 0 ||
            set_relay_duty_cycle(RELAY3_PIN, duty_cycle) != 0 ||
            set_relay_duty_cycle(RELAY4_PIN, duty_cycle) != 0) {
            program_running = 0; // Stop the loop on error
            break;
        }

        if (increment_duty_cycle(&duty_cycle, 1) != 0) {
            program_running = 0; // Stop the loop on error
            break;
        }

        char message[100];
        sprintf(message, "Sunrise step %d: Duty cycle = %d", i + 1, duty_cycle);
        log_event(message);
        gpioDelay(1000); // Wait for 1 second
    }

    // Shutdown sequence
    log_event("Starting shutdown sequence...");
    for (int i = PWM_RANGE; i >= 0 && program_running; --i) {
        if (set_relay_duty_cycle(RELAY1_PIN, i) != 0 ||
            set_relay_duty_cycle(RELAY2_PIN, i) != 0 ||
            set_relay_duty_cycle(RELAY3_PIN, i) != 0 ||
            set_relay_duty_cycle(RELAY4_PIN, i) != 0) {
            program_running = 0; // Stop the loop on error
            break;
        }
        gpioDelay(1000); // Wait for 1 second
    }

    log_event("Shutdown complete.");

    // Clean up resources
    gpioPWM(RELAY1_PIN, 0);
    gpioPWM(RELAY2_PIN, 0);
    gpioPWM(RELAY3_PIN, 0);
    gpioPWM(RELAY4_PIN, 0);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

