#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43

// LED GPIO pin
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data and timestamp
typedef struct {
    float x;
    float y;
    float z;
    time_t timestamp;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_mpu6050();
int read_gyro_data(float *x, float *y, float *z);
void add_to_buffer(float x, float y, float z);
void check_threshold(float x, float y, float z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize MPU-6050
int init_mpu6050() {
    int result;
    int retries = 3;

    // Wake up the MPU-6050
    result = i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00);
    if (result < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %d\n", result);
        return -1;
    }
    gpioDelay(100); // Short delay after waking up

    // Set sample rate divider
    result = i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x07);
    if (result < 0) {
        fprintf(stderr, "Error writing to SMPLRT_DIV: %d\n", result);
        return -1;
    }
    gpioDelay(100);

    // Set gyroscope full-scale range
    result = i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00);
    if (result < 0) {
        fprintf(stderr, "Error writing to GYRO_CONFIG: %d\n", result);
        return -1;
    }
    gpioDelay(100);

    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, 0x75);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x68) {
        fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0x68\n", who_am_i);
        return -1;
    }

    return 0;
}

// Read gyroscope data
int read_gyro_data(float *x, float *y, float *z) {
    char buf[6];
    int result = i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading gyro data: %d\n", result);
        return -1;
    }

    // Convert big-endian to little-endian
    *x = (float)((int16_t)((buf[0] << 8) | buf[1])) / 131.0f;
    *y = (float)((int16_t)((buf[2] << 8) | buf[3])) / 131.0f;
    *z = (float)((int16_t)((buf[4] << 8) | buf[5])) / 131.0f;

    return 0;
}

// Add data to circular buffer
void add_to_buffer(float x, float y, float z) {
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    gyro_buffer[buffer_index].timestamp = time(NULL);
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Check if any axis exceeds the threshold
void check_threshold(float x, float y, float z) {
    if (abs(x) > 250 || abs(y) > 250 || abs(z) > 250) {
        gpioWrite(LED_PIN, 1); // Turn on LED
    } else {
        gpioWrite(LED_PIN, 0); // Turn off LED
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Initially turn off LED

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z;
    time_t start_time, current_time;
    double elapsed_time;

    // Main loop
    while (!terminate) {
        start_time = time(NULL);
        while (1) {
            if (read_gyro_data(&x, &y, &z) == 0) {
                add_to_buffer(x, y, z);
                check_threshold(x, y, z);
                break; // Exit the inner loop after successful read
            } else {
                fprintf(stderr, "Retrying I2C initialization...\n");
                i2cClose(i2c_handle);
                gpioTerminate();
                if (gpioInitialise() < 0) {
                    fprintf(stderr, "pigpio initialisation failed again\n");
                    return 1;
                }
                i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
                if (i2c_handle < 0) {
                    fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
                    return 1;
                }
                if (init_mpu6050() != 0) {
                    fprintf(stderr, "MPU-6050 initialisation failed again\n");
                    return 1;
                }
                gpioWrite(LED_PIN, 0); // Turn off LED before retrying
                gpioDelay(100); // Short delay before retrying
            }
            gpioDelay(10); // Small delay before retrying
        }

        current_time = time(NULL);
        elapsed_time = difftime(current_time, start_time);

        if (elapsed_time < 0.05) {
            gpioDelay((int)(0.05 - elapsed_time)); // Wait for 50ms
        }
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

