#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define CE0_CHIP 0
#define CE0_CHIP_PIN 8
#define CE0_CHIP_LINE 8
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48
#define GYRO_CONFIG 0x1B
#define GYRO_FULL_SCALE_250_DPS 0x00
#define GYRO_SCALE_FACTOR 131.0
#define LOG_FILE "gyro_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 1
#define SAMPLE_INTERVAL_MS 10

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z);
float convert_to_dps(int16_t raw_data);
int log_data(FILE *fp, float x_rate, float y_rate, float z_rate);
void signal_handler(int sig);
int setup_gpio(int chip, int pin);
int cleanup_gpio(int chip, int pin);

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    int ret = ioctl(fd, SPI_IOC_MESSAGE(1), &transfer);
    if (ret < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

// Read gyroscope data function
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t tx_buf[7] = {GYRO_XOUT_H, GYRO_XOUT_L, GYRO_YOUT_H, GYRO_YOUT_L, GYRO_ZOUT_H, GYRO_ZOUT_L, 0x00};
    uint8_t rx_buf[7];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (spi_transfer(fd, tx_buf, rx_buf, 7) == 0) {
            *x = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);
            *y = (int16_t)((rx_buf[2] << 8) | rx_buf[3]);
            *z = (int16_t)((rx_buf[4] << 8) | rx_buf[5]);
            return 0; // Success
        } else {
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Error: Failed to read gyro data after multiple retries.\n");
    return -1; // Failure
}

// Convert raw data to degrees per second
float convert_to_dps(int16_t raw_data) {
    return (float)raw_data / GYRO_SCALE_FACTOR;
}

// Log data to file
int log_data(FILE *fp, float x_rate, float y_rate, float z_rate) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return -1;
    }

    char timestamp[30];
    snprintf(timestamp, sizeof(timestamp), "%ld.%09ld", ts.tv_sec, ts.tv_nsec);

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, x_rate, y_rate, z_rate) < 0) {
        perror("fprintf");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Setup GPIO chip and line
int setup_gpio(int chip, int pin) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, pin);
    if (!gpio_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "mpu9250_ce0";
