int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t tx_buf[7] = {GYRO_XOUT_H, GYRO_XOUT_L, GYRO_YOUT_H, GYRO_YOUT_L, GYRO_ZOUT_H, GYRO_ZOUT_L, 0x00};
    uint8_t rx_buf[7];
    int retries = RETRY_COUNT;

    while (retries > 0) {
