#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Constants
#define SPI_BUS 0
#define SPI_CHIP_SELECT 0
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 3900000 // 3.9 MHz
#define GYRO_X_REG 0x43
#define GYRO_Y_REG 0x45
#define GYRO_Z_REG 0x47
#define SENSITIVITY 131.0
#define LED_GPIO 17
#define BUFFER_SIZE 64

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    struct timespec timestamp;
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;

// Function prototypes
int spi_init(int bus, int chip_select, int mode, int bits_per_word, int max_speed_hz);
int spi_read_register(int fd, uint8_t reg_addr, uint8_t *data, int len);
int spi_write_register(int fd, uint8_t reg_addr, uint8_t data);
int16_t read_gyro_axis(int fd, uint8_t reg_addr);
void add_to_buffer(gyro_data_t data);
void print_buffer_to_csv(gyro_data_t *buffer, int size);
void signal_handler(int sig);
int gpio_init(int gpio_pin);
int gpio_set_value(int gpio_pin, int value);
int gpio_uninit(int gpio_pin);

// SPI initialization function
int spi_init(int bus, int chip_select, int mode, int bits_per_word, int max_speed_hz) {
    int fd;
    char spi_dev[20];

    snprintf(spi_dev, sizeof(spi_dev), "/dev/spidev%d.%d", bus, chip_select);

    fd = open(spi_dev, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word) < 0) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &max_speed_hz) < 0) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI read register function
int spi_read_register(int fd, uint8_t reg_addr, uint8_t *data, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = 0,
        .rx_buf = (unsigned long)data,
        .len = len,
        .speed_hz = SPI_MAX_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    struct spi_ioc_transfer *transfer_ptr = &transfer;
    if (ioctl(fd, SPI_IOC_MESSAGE(1), transfer_ptr) < 0) {
        perror("Error reading from SPI");
        return -1;
    }

    return 0;
}

// SPI write register function
int spi_write_register(int fd, uint8_t reg_addr, uint8_t data) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = &data,
        .rx_buf = 0,
        .len = 1,
        .speed_hz = SPI_MAX_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    struct spi_ioc_transfer *transfer_ptr = &transfer;
    if (ioctl(fd, SPI_IOC_MESSAGE(1), transfer_ptr) < 0) {
        perror("Error writing to SPI");
        return -1;
    }

    return 0;
}

// Read gyroscope axis function
int16_t read_gyro_axis(int fd, uint8_t reg_addr) {
    uint8_t data[2];
    if (spi_read_register(fd, reg_addr, data, 2) < 0) {
        fprintf(stderr, "Error reading gyro axis from register 0x%02X\n", reg_addr);
        return 0; // Return 0 on error
    }
    return (int16_t)((data[0] << 8) | data[1]);
}

// Add data to circular buffer
void add_to_buffer(gyro_data_t data) {
    gyro_buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Print buffer to CSV
void print_buffer_to_csv(gyro_data_t *buffer, int size) {
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < size; i++) {
        char timestamp_str[30];
        struct tm *tm_info;
        tm_info = localtime(&buffer[i].timestamp.tv_sec);
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", tm_info);
        printf("%s.%09ld,%d,%d,%d\n", timestamp_str, buffer[i].timestamp.tv_nsec, buffer[i].x, buffer[i].y, buffer[i].z);
    }
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// GPIO initialization function
int gpio_init(int gpio_pin) {
    char chipname[20];
    snprintf(chipname, sizeof(chipname), "gpiochip0");

    gpio_chip = gpiod_chip_open_by_name(chipname);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, gpio_pin);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gyro_led";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(gpio_line);
        return -1;
    }

    return 0;
}

// GPIO set value function
int gpio_set_value(int gpio_pin, int value) {
    if (gpiod_line_set_value(gpio_line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// GPIO uninit function
int gpio_uninit(int gpio_pin) {
    if (gpiod_line_release(gpio_line) < 0) {
        perror("Error releasing GPIO line");
        return -1;
    }
    if (gpiod_chip_close(gpio_chip) < 0) {
        perror("Error closing GPIO chip");
        return -1;
    }
    return 0;
}

int main() {
    struct timespec ts;
    int16_t x, y, z;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 10000000; // 10 ms

    // Signal handling
    signal(SIGINT, signal_handler);

    // SPI initialization
    spi_fd = spi_init(SPI_BUS, SPI_CHIP_SELECT, SPI_MODE, SPI_BITS_PER_WORD, SPI_MAX_SPEED_HZ);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // GPIO initialization
    if (gpio_init(LED_GPIO) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        x = read_gyro_axis(spi_fd, GYRO_X_REG);
        y = read_gyro_axis(spi_fd, GYRO_Y_REG);
        z = read_gyro_axis(spi_fd, GYRO_Z_REG);

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            break;
        }

        // Add data to circular buffer
        gyro_data_t data;
        data.timestamp = ts;
        data.x = x;
        data.y = y;
        data.z = z;
        add_to_buffer(data);

        // Check for out-of-range values
        if (x > 200 || x < -200 || y > 200 || y < -200 || z > 200 || z < -200) {
            // Blink LED
            gpio_set_value(LED_GPIO, 1);
            nanosleep(&sleep_time, NULL);
            gpio_set_value(LED_GPIO, 0);
            nanosleep(&sleep_time, NULL);
        }

        // Sleep for 10 ms
        nanosleep(&sleep_time, NULL);
    }

    // Print buffer to CSV
    print_buffer_to_csv(gyro_buffer, BUFFER_SIZE);

    // Cleanup
    close(spi_fd);
    gpio_uninit(LED_GPIO);

    return 0;
}

