#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B
#define LED_GPIO 21
#define SAMPLE_RATE_MS 100
#define ROLL_THRESHOLD 45.0
#define PITCH_THRESHOLD 45.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_mpu6050();
int read_raw_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z);
void process_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *roll, float *pitch);
void control_led(float roll, float pitch);
void log_data(float roll, float pitch);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize MPU6050
int init_mpu6050() {
    // Wake up the sensor
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1\n");
        return -1;
    }
    gpioDelay(100); // Wait for the sensor to wake up

    // Set accelerometer full-scale range to ±2g
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to ACCEL_CONFIG\n");
        return -1;
    }
    return 0;
}

// Read raw accelerometer data
int read_raw_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    *accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    *accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    *accel_z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Process accelerometer data and calculate roll and pitch
void process_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *roll, float *pitch) {
    float x = (float)accel_x;
    float y = (float)accel_y;
    float z = (float)accel_z;

    *roll = atan2(y, z) * 180.0 / M_PI;
    *pitch = atan2(-x, sqrt(y * y + z * z)) * 180.0 / M_PI;
}

// Control LED based on roll and pitch
void control_led(float roll, float pitch) {
    if (fabs(roll) > ROLL_THRESHOLD || fabs(pitch) > PITCH_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Log data to file
void log_data(float roll, float pitch) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Initially turn LED off

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("tilt_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    int16_t accel_x, accel_y, accel_z;
    float roll, pitch;

    // Main loop
    while (!terminate) {
        // Read raw data
        if (read_raw_data(&accel_x, &accel_y, &accel_z) == 0) {
            // Process data
            process_data(accel_x, accel_y, accel_z, &roll, &pitch);

            // Control LED
            control_led(roll, pitch);

            // Log data
            log_data(roll, pitch);

            // Print to console
            printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        gpioDelay(SAMPLE_RATE_MS); // Sample every 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioTerminate();
    fclose(log_file);

    return 0;
}

