#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x5A
#define AMBIENT_LIGHT_REG 0x20
#define PROXIMITY_REG 0x22
#define GPIO_PIN 17
#define GPIO_CHIP "gpiochip0"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define LOG_FILE "biometric_log.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *gpio_line = NULL;

// Function prototypes
int i2c_read_register(int fd, unsigned char reg, unsigned char *value);
int i2c_write_register(int fd, unsigned char reg, unsigned char value);
int read_sensor_data(int fd, int *ambient_light, int *proximity);
void log_data(int ambient_light, int proximity);
void control_led(int proximity);
void signal_handler(int sig);
int gpio_init(void);
void gpio_cleanup(void);

// I2C read register function with retry
int i2c_read_register(int fd, unsigned char reg, unsigned char *value) {
    int retries = RETRY_COUNT;
    int result;

    while (retries > 0) {
        result = ioctl(fd, I2C_SLAVE, SI1145_ADDR);
        if (result < 0) {
            perror("I2C_SLAVE ioctl failed");
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        if (write(fd, &reg, 1) != 1) {
            perror("I2C write failed");
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        if (read(fd, value, 1) != 1) {
            perror("I2C read failed");
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }
        return 0; // Success
    }
    fprintf(stderr, "Failed to read register 0x%02X after %d retries\n", reg, RETRY_COUNT);
    return -1; // Failure
}

// I2C write register function with retry
int i2c_write_register(int fd, unsigned char reg, unsigned char value) {
    int retries = RETRY_COUNT;
    int result;

    while (retries > 0) {
        unsigned char buf[2];
        buf[0] = reg;
        buf[1] = value;

        result = ioctl(fd, I2C_SLAVE, SI1145_ADDR);
        if (result < 0) {
            perror("I2C_SLAVE ioctl failed");
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        if (write(fd, buf, 2) != 2) {
            perror("I2C write failed");
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }
        return 0; // Success
    }
    fprintf(stderr, "Failed to write register 0x%02X after %d retries\n", reg, RETRY_COUNT);
    return -1; // Failure
}

// Read sensor data function
int read_sensor_data(int fd, int *ambient_light, int *proximity) {
    unsigned char ambient_light_val, proximity_val;

    if (i2c_read_register(fd, AMBIENT_LIGHT_REG, &ambient_light_val) != 0) {
        fprintf(stderr, "Failed to read ambient light data\n");
        return -1;
    }

    if (i2c_read_register(fd, PROXIMITY_REG, &proximity_val) != 0) {
        fprintf(stderr, "Failed to read proximity data\n");
        return -1;
    }

    *ambient_light = (ambient_light_val << 8) | proximity_val;
    *proximity = (proximity_val << 8) | (ambient_light_val >> 8); // Little-endian conversion

    return 0;
}

// Log data function
void log_data(int ambient_light, int proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,AmbientLight:%d,Proximity:%d\n", timestamp, ambient_light, proximity);
    fflush(log_file); // Ensure data is written to file immediately
}

// Control LED function
void control_led(int proximity) {
    if (proximity > 100) {
        gpiod_line_set_value(gpio_line, 1); // Turn LED on
    } else {
        gpiod_line_set_value(gpio_line, 0); // Turn LED off
    }
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);

    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (gpio_line != NULL) {
        gpiod_line_set_value(gpio_line, 0); // Turn off LED
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }

    exit(0);
}

// GPIO initialization function
int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("gpiod_chip_open_by_name failed");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("gpiod_chip_get_line failed");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "si1145_led";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("gpiod_line_request failed");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// GPIO cleanup function
void gpio_cleanup(void) {
    if (gpio_line != NULL) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }
}

int main() {
    int ambient_light, proximity;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
