#include <string.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 0
#define SPI_FLAGS 0

// Define ADXRS290 register addresses
#define ADXRS290_X_RATE_REG 0x02
#define ADXRS290_Y_RATE_REG 0x04

// Define sensitivity
#define SENSITIVITY 200.0 // LSB/deg/s

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyro data
typedef struct {
    long timestamp;
    int16_t x_rate;
    int16_t y_rate;
} gyro_data_t;

// Function prototypes
int initialize_spi();
int read_gyro_data(int16_t *x_rate, int16_t *y_rate);
void log_data(gyro_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read gyro data
int read_gyro_data(int16_t *x_rate, int16_t *y_rate) {
    char tx_buf[3];
    char rx_buf[3];

    // Read X axis data
    tx_buf[0] = (ADXRS290_X_RATE_REG | 0x80) << 4; // Set read bit
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "Error reading X axis data\n");
        return -1;
    }

    *x_rate = ((rx_buf[1] << 8) | rx_buf[2]);

    // Read Y axis data
    tx_buf[0] = (ADXRS290_Y_RATE_REG | 0x80) << 4; // Set read bit
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "Error reading Y axis data\n");
        return -1;
    }

    *y_rate = ((rx_buf[1] << 8) | rx_buf[2]);

    return 0;
}

// Function to log data to file
void log_data(gyro_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp = (ts.tv_sec * 1000000) + (ts.tv_nsec / 1000);

    fprintf(fp, "%ld,%d,%d\n", timestamp, data.x_rate, data.y_rate);
    fflush(fp); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open data file
    fp = fopen("gyro_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening data file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to data file
    fprintf(fp, "timestamp,x_rate,y_rate\n");

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t x_rate, y_rate;
    gyro_data_t gyro_data;

    // Main loop
    while (!terminate) {
        if (read_gyro_data(&x_rate, &y_rate) == 0) {
            gyro_data.timestamp = (long)(time_time() * 1000000); // Seconds since epoch, microsecond precision
            gyro_data.x_rate = x_rate;
            gyro_data.y_rate = y_rate;
            log_data(gyro_data);
        } else {
            fprintf(stderr, "Error reading gyro data, attempting re-initialization...\n");
            spiClose(spi_handle);
            if (initialize_spi() != 0) {
                fprintf(stderr, "Failed to re-initialize SPI, exiting...\n");
                break; // Exit loop if re-initialization fails
            }
        }

        gpioDelay(10000); // 10 ms delay (100 Hz sampling rate)
    }

    // Clean up
    fclose(fp);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

