#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define ALERT_PIN 17

// Define server address and port
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345

// Define seismic event duration (in milliseconds)
#define SEISMIC_DURATION 500

// Global variables
FILE *log_file = NULL;
int alert_active = 0;

// Function prototypes
void sensor1_callback(int gpio, int level, uint32_t tick);
void sensor2_callback(int gpio, int level, uint32_t tick);
void seismic_event_detected(void);
void send_alert(void);
void signal_handler(int signal);

// Callback function for sensor 1
void sensor1_callback(int gpio, int level, uint32_t tick) {
    if (gpio == SENSOR1_PIN) {
        if (level == 1) { // Rising edge
            if (gpioRead(SENSOR2_PIN) == 1) {
                seismic_event_detected();
            }
        }
    }
}

// Callback function for sensor 2
void sensor2_callback(int gpio, int level, uint32_t tick) {
    if (gpio == SENSOR2_PIN) {
        if (level == 1) { // Rising edge
            if (gpioRead(SENSOR1_PIN) == 1) {
                seismic_event_detected();
            }
        }
    }
}

// Function to detect seismic event
void seismic_event_detected(void) {
    if (!alert_active) {
        gpioWrite(ALERT_PIN, 1); // Set alert pin HIGH
        alert_active = 1;
        send_alert();
        gpioDelay(2000); // Wait for 2 seconds
        gpioWrite(ALERT_PIN, 0); // Set alert pin LOW
        alert_active = 0;
    }
}

// Function to send alert to server
void send_alert(void) {
    int sockfd;
    struct sockaddr_in servaddr;
    char message[100];
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        return;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &servaddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        return;
    }

    snprintf(message, sizeof(message), "%04d-%02d-%02d %02d:%02d:%02d - Seismic event detected!",
             timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
             timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);

    if (sendto(sockfd, (const char *)message, strlen(message), 0, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("sendto failed");
    }

    close(sockfd);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioWrite(ALERT_PIN, 0); // Ensure alert pin is LOW
    gpioTerminate(); // Terminate pigpio

    exit(0);
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    // Set pull-down resistors (optional, but recommended for stability)
    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_DOWN);

    // Open log file
    log_file = fopen("seismic_events.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Register callbacks for sensor 1
    if (gpioSetAlertFuncEx(SENSOR1_PIN, sensor1_callback, NULL) != 0) {
        fprintf(stderr, "Failed to register callback for sensor 1\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Register callbacks for sensor 2
    if (gpioSetAlertFuncEx(SENSOR2_PIN, sensor2_callback, NULL) != 0) {
        fprintf(stderr, "Failed to register callback for sensor 2\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Seismic activity detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        gpioDelay(100); // Reduce CPU usage
    }

    return 0;
}

