#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 0
#define SPI_CE 8 // CE0
#define LED_GPIO 17
#define BUFFER_SIZE 100
#define THRESHOLD 20.0 // deg/s
#define SENSITIVITY 0.02 // 200 LSB/deg/s

// Structure for storing gyroscope data
typedef struct {
    struct timespec timestamp;
    int16_t x_rate;
    int16_t y_rate;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// SPI handle
int spi_handle;

// Function prototypes
int init_spi();
int read_gyro_data(int16_t *x_rate, int16_t *y_rate);
void add_to_buffer(struct timespec timestamp, int16_t x_rate, int16_t y_rate);
void check_threshold(int16_t x_rate, int16_t y_rate);
void signal_handler(int signal);
void cleanup();

// Function to initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int16_t *x_rate, int16_t *y_rate) {
    char tx_buf[2];
    char rx_buf[2];

    // X-axis rate (RATE_XL and RATE_XH)
    tx_buf[0] = 0x02 | 0x80; // Read command, X-axis rate address
    tx_buf[1] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error reading X-axis rate\n");
        return -1;
    }
    *x_rate = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);

    // Y-axis rate (RATE_YL and RATE_YH)
    tx_buf[0] = 0x04 | 0x80; // Read command, Y-axis rate address
    tx_buf[1] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error reading Y-axis rate\n");
        return -1;
    }
    *y_rate = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);

    return 0;
}

// Function to add data to the circular buffer
void add_to_buffer(struct timespec timestamp, int16_t x_rate, int16_t y_rate) {
    gyro_buffer[buffer_index].timestamp = timestamp;
    gyro_buffer[buffer_index].x_rate = x_rate;
    gyro_buffer[buffer_index].y_rate = y_rate;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to check the threshold
void check_threshold(int16_t x_rate, int16_t y_rate) {
    if (abs(x_rate) > THRESHOLD || abs(y_rate) > THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn on LED
    } else {
        gpioWrite(LED_GPIO, 0); // Turn off LED
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function
void cleanup() {
    spiClose(spi_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Initially off

    // Initialize SPI
    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x_rate, y_rate;
    struct timespec ts;

    printf("Starting data acquisition...\n");

    while (1) {
        if (read_gyro_data(&x_rate, &y_rate) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &ts);
            add_to_buffer(ts, x_rate, y_rate);
            check_threshold(x_rate, y_rate);
        } else {
            fprintf(stderr, "Error reading gyro data, retrying...\n");
        }
        gpioDelay(10); // 10 ms delay
    }

    return 0;
}

