#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the lamps
#define LAMP1_PIN 17
#define LAMP2_PIN 18
#define LAMP3_PIN 27

// Define PWM frequency and range
#define PWM_FREQUENCY 100
#define PWM_RANGE 255

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, shutting down gracefully...\n", signal);
}

// Function to set the PWM duty cycle for a given GPIO pin
int set_pwm_duty_cycle(int gpio_pin, int duty_cycle) {
    if (gpioPWM(gpio_pin, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle for GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to fade a lamp from full brightness to off
void fade_lamp(int gpio_pin, int duration_seconds) {
    int i;
    int duty_cycle;

    // Calculate the number of steps for the fade
    int num_steps = duration_seconds * 10; // 10 steps per second

    // Calculate the duty cycle for each step
    duty_cycle = 255;
    for (i = 0; i < num_steps; i++) {
        if (set_pwm_duty_cycle(gpio_pin, duty_cycle) != 0) {
            fprintf(stderr, "Error setting PWM duty cycle during fade for GPIO %d\n", gpio_pin);
            return;
        }
        duty_cycle -= 10; // Decrease duty cycle by 10 each step
        if (duty_cycle < 0) duty_cycle = 0; // Ensure duty cycle doesn't go negative
        gpioDelay(1000000 / PWM_FREQUENCY); // Delay for 10ms (100Hz)
    }

    // Turn off the lamp after the fade
    if (set_pwm_duty_cycle(gpio_pin, 0) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle to 0 for GPIO %d\n", gpio_pin);
    }
}

int main(int argc, char *argv[]) {
    int fade_duration;

    // Check for the correct number of command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <fade_duration_seconds>\n", argv[0]);
        return 1;
    }

    // Parse the fade duration from the command-line argument
    fade_duration = atoi(argv[1]);

    // Validate the fade duration
    if (fade_duration < 1 || fade_duration > 3600) {
        fprintf(stderr, "Error: Fade duration must be between 1 and 3600 seconds\n");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set the PWM frequency for all lamps
    gpioSetPWMfrequency(LAMP1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP3_PIN, PWM_FREQUENCY);

    // Set the PWM range for all lamps
    gpioSetPWMrange(LAMP1_PIN, PWM_RANGE);
    gpioSetPWMrange(LAMP2_PIN, PWM_RANGE);
    gpioSetPWMrange(LAMP3_PIN, PWM_RANGE);

    // Fade each lamp sequentially
    printf("Starting sunset simulation with fade duration: %d seconds\n", fade_duration);
    fade_lamp(LAMP1_PIN, fade_duration);
    printf("Lamp 1 faded to off\n");

    fade_lamp(LAMP2_PIN, fade_duration);
    printf("Lamp 2 faded to off\n");

    fade_lamp(LAMP3_PIN, fade_duration);
    printf("Lamp 3 faded to off\n");

    printf("Sunset simulation complete\n");

    // Turn off all lamps and release resources before exiting
    gpioPWM(LAMP1_PIN, 0);
    gpioPWM(LAMP2_PIN, 0);
    gpioPWM(LAMP3_PIN, 0);

    gpioTerminate();

    printf("Program terminated gracefully\n");
    return 0;
}

