#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the traffic light
#define RED_LIGHT_PIN 17
#define YELLOW_LIGHT_PIN 22
#define GREEN_LIGHT_PIN 23
#define OFF_LIGHT_PIN 24

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the state of a GPIO pin
int set_gpio_state(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error setting GPIO %d to state %d\n", pin, state);
        return -1;
    }
    return 0;
}

// Function to turn on a relay (active-low)
int turn_on_relay(int pin) {
    return set_gpio_state(pin, 0);
}

// Function to turn off a relay (active-low)
int turn_off_relay(int pin) {
    return set_gpio_state(pin, 1);
}

// Function to simulate the traffic light sequence
void traffic_light_sequence() {
    printf("Starting traffic light sequence...\n");

    // Red light
    if (turn_on_relay(RED_LIGHT_PIN) != 0) return;
    if (turn_on_relay(YELLOW_LIGHT_PIN) != 0) return;
    printf("Red light for 10 seconds\n");
    gpioDelay(10000000); // 10 seconds

    // Red + Yellow
    if (turn_on_relay(GREEN_LIGHT_PIN) != 0) return;
    if (turn_on_relay(YELLOW_LIGHT_PIN) != 0) return;
    printf("Red + Yellow for 2 seconds\n");
    gpioDelay(2000000); // 2 seconds

    // Green light
    if (turn_on_relay(GREEN_LIGHT_PIN) != 0) return;
    if (turn_off_relay(RED_LIGHT_PIN) != 0) return;
    if (turn_off_relay(YELLOW_LIGHT_PIN) != 0) return;
    printf("Green light for 10 seconds\n");
    gpioDelay(10000000); // 10 seconds

    // Yellow light
    if (turn_on_relay(YELLOW_LIGHT_PIN) != 0) return;
    if (turn_off_relay(GREEN_LIGHT_PIN) != 0) return;
    if (turn_off_relay(RED_LIGHT_PIN) != 0) return;
    printf("Yellow light for 3 seconds\n");
    gpioDelay(3000000); // 3 seconds

    // Turn off all lights
    turn_off_relay(GREEN_LIGHT_PIN);
    turn_off_relay(YELLOW_LIGHT_PIN);
    turn_off_relay(RED_LIGHT_PIN);
    printf("All lights off\n");
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_LIGHT_PIN, PI_OUTPUT);
    gpioSetMode(YELLOW_LIGHT_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_LIGHT_PIN, PI_OUTPUT);
    gpioSetMode(OFF_LIGHT_PIN, PI_OUTPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Traffic light simulation started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        traffic_light_sequence();
    }

    // Clean up and exit
    printf("Cleaning up and exiting...\n");
    turn_off_relay(GREEN_LIGHT_PIN);
    turn_off_relay(YELLOW_LIGHT_PIN);
    turn_off_relay(RED_LIGHT_PIN);
    gpioTerminate();

    return 0;
}

