        return 1;
    }

    // Configure MPR121
    if (configure_mpr121() != 0) {
        log_message("MPR121 configuration failed, exiting");
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    int last_touch_status = 0;
