            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
        }

        last_touch_status = current_touch_status;
        gpioDelay(10000); // Check every 10ms
    }

    // The program should never reach here due to the infinite loop,
    // but include cleanup code for completeness.
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

