int read_flame_sensor(int gpio_pin);
void activate_buzzer(int gpio_pin);
void deactivate_buzzer(int gpio_pin);
void activate_led(int gpio_pin);
void deactivate_led(int gpio_pin);
void log_flame_detection(const char *filename);
void signal_handler(int signal);

// Function to read the flame sensor with debouncing
int read_flame_sensor(int gpio_pin) {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_READS; i++) {
        if (gpioRead(gpio_pin) == 0) {
            low_count++;
        }
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Delay in microseconds
    }
    return (low_count == DEBOUNCE_READS) ? 0 : 1; // Return 0 if flame detected, 1 otherwise
}

// Function to activate the buzzer
void activate_buzzer(int gpio_pin) {
    gpioWrite(gpio_pin, 1); // Set GPIO high
}

// Function to deactivate the buzzer
void deactivate_buzzer(int gpio_pin) {
    gpioWrite(gpio_pin, 0); // Set GPIO low
}

// Function to activate the LED
void activate_led(int gpio_pin) {
    gpioWrite(gpio_pin, 1); // Set GPIO high
}

// Function to deactivate the LED
void deactivate_led(int gpio_pin) {
    gpioWrite(gpio_pin, 0); // Set GPIO low
}

// Function to log flame detection to a file
void log_flame_detection(const char *filename) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s Flame Detected\n", timestamp);
        fflush(log_file); // Ensure the data is written to the file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

