    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Initialize log file
    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fire alarm system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        if (read_flame_sensor(FLAME_SENSOR_PIN) == 0) {
            activate_buzzer(BUZZER_PIN);
            activate_led(LED_PIN);
            log_flame_detection("flame_log.txt");
        } else {
            deactivate_buzzer(BUZZER_PIN);
            deactivate_led(LED_PIN);
        }
        gpioDelay(100000); // Check every 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    deactivate_buzzer(BUZZER_PIN);
    deactivate_led(LED_PIN);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

