#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for solenoids
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Define dispense duration (in milliseconds)
#define DISPENSE_DURATION 1000

// Define delay between dispenses (in seconds)
#define DISPENSE_DELAY 5

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int dispense_cycle(int solenoid_pin1, int solenoid_pin2, int duration_ms);
int log_dispense_event(int solenoid_pin1, int solenoid_pin2, int duration_ms);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0; // Set the flag to exit the main loop

        // Deactivate both solenoids
        gpioWrite(SOLENOID_1_PIN, 0);
        gpioWrite(SOLENOID_2_PIN, 0);

        // Terminate pigpio
        gpioTerminate();

        // Exit the program
        exit(0);
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO17 as output
    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_1_PIN);
        gpioTerminate();
        return 1; // Indicate failure
    }

    // Set GPIO27 as output
    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_2_PIN);
        gpioTerminate();
        return 1; // Indicate failure
    }

    return 0; // Indicate success
}

// Function to perform a single dispense cycle
int dispense_cycle(int solenoid_pin1, int solenoid_pin2, int duration_ms) {
    // Activate solenoid 1 for half the duration
    if (gpioWrite(solenoid_pin1, 1) != 0) {
        fprintf(stderr, "Failed to activate solenoid on GPIO%d\n", solenoid_pin1);
        return 1; // Indicate failure
    }
    gpioDelay(duration_ms / 2);

    // Activate solenoid 2 for the remaining half the duration
    if (gpioWrite(solenoid_pin2, 1) != 0) {
        fprintf(stderr, "Failed to activate solenoid on GPIO%d\n", solenoid_pin2);
        return 1; // Indicate failure
    }
    gpioDelay(duration_ms / 2);

    // Deactivate both solenoids
    if (gpioWrite(solenoid_pin1, 0) != 0) {
        fprintf(stderr, "Failed to deactivate solenoid on GPIO%d\n", solenoid_pin1);
        return 1; // Indicate failure
    }
    if (gpioWrite(solenoid_pin2, 0) != 0) {
        fprintf(stderr, "Failed to deactivate solenoid on GPIO%d\n", solenoid_pin2);
        return 1; // Indicate failure
    }

    return 0; // Indicate success
}

// Function to log dispense events to a file
int log_dispense_event(int solenoid_pin1, int solenoid_pin2, int duration_ms) {
    FILE *fp = fopen("dispense_log.txt", "a");
