#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>

// Motor A
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18

// Motor B
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23

// Enable Pins
#define ENA_PIN 24
#define ENB_PIN 25

// Ultrasonic Sensor
#define TRIGGER_PIN 4
#define ECHO_PIN 12

// PID Constants
#define Kp 1.0
#define Ki 0.01
#define Kd 0.1

// Obstacle Avoidance Threshold
#define OBSTACLE_THRESHOLD 20.0

// Global Variables
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function Prototypes
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
float generate_tilt_error();
float generate_distance();
int calculate_motor_speeds(float tilt_error, float distance, int *motor_a_speed, int *motor_b_speed);
void set_motor_speed(int motor_a_speed, int motor_b_speed);

// Signal Handler
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Stopping motors and cleaning up...\n");
        program_running = 0;
    }
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set motor control pins as output
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);

    // Set enable pins as output
    gpioSetMode(ENA_PIN, PI_OUTPUT);
    gpioSetMode(ENB_PIN, PI_OUTPUT);

    // Set ultrasonic sensor pins
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Enable PWM on enable pins
    gpioSetPWMfrequency(ENA_PIN, 1000); // 1 kHz
    gpioSetPWMfrequency(ENB_PIN, 1000);

    gpioPWM(ENA_PIN, 128); // 50% duty cycle
    gpioPWM(ENB_PIN, 128);

    return 0;
}

// Cleanup GPIO
void cleanup_gpio() {
    // Stop motors
    gpioWrite(MOTOR_A_FORWARD, 0);
    gpioWrite(MOTOR_A_BACKWARD, 0);
    gpioWrite(MOTOR_B_FORWARD, 0);
    gpioWrite(MOTOR_B_BACKWARD, 0);

    // Disable PWM on enable pins
    gpioPWM(ENA_PIN, 0);
    gpioPWM(ENB_PIN, 0);

    gpioTerminate();
}

// Log Data
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

// Generate Tilt Error
float generate_tilt_error() {
    return (float)(rand() % 200 - 100) / 10.0; // -10.0 to 10.0
}

// Generate Distance
float generate_distance() {
    return (float)(rand() % 381 + 2); // 2 to 400
}

// Calculate Motor Speeds
int calculate_motor_speeds(float tilt_error, float distance, int *motor_a_speed, int *motor_b_speed) {
    float error = tilt_error;
    float distance_error = distance - 30.0; // Target distance is 30cm

    // Proportional term
    float proportional = Kp * error;

    // Integral term
    static float integral = 0.0;
    integral += error;
    if (integral > 100) integral = 100; // Clamp integral term
    if (integral < -100) integral = -100;

    float integral_term = Ki * integral;

    // Derivative term
    static float previous_error = 0.0;
    float derivative = Kd * (error - previous_error);
    previous_error = error;

    // Calculate motor speeds
    float motor_a_speed_cmd = proportional + integral_term + derivative;
    float motor_b_speed_cmd = proportional - integral_term - derivative;

    // Clamp motor speeds to +/- 255
    if (motor_a_speed_cmd > 255) motor_a_speed_cmd = 255;
    if (motor_a_speed_cmd < -255) motor_a_speed_cmd = -255;
    if (motor_b_speed_cmd > 255) motor_b_speed_cmd = 255;
    if (motor_b_speed_cmd < -255) motor_b_speed_cmd = -255;

    *motor_a_speed = (int)motor_a_speed_cmd;
    *motor_b_speed = (int)motor_b_speed_cmd;

    return 0;
}

// Set Motor Speed
void set_motor_speed(int motor_a_speed, int motor_b_speed) {
    // Motor A
    gpioWrite(MOTOR_A_FORWARD, (motor_a_speed > 0));
    gpioWrite(MOTOR_A_BACKWARD, (motor_a_speed < 0));
    if (motor_a_speed > 0) gpioPWM(ENA_PIN, abs(motor_a_speed));
    if (motor_a_speed < 0) gpioPWM(ENA_PIN, abs(motor_a_speed));

    // Motor B
    gpioWrite(MOTOR_B_FORWARD, (motor_b_speed > 0));
    gpioWrite(MOTOR_B_BACKWARD, (motor_b_speed < 0));
    if (motor_b_speed > 0) gpioPWM(ENB_PIN, abs(motor_b_speed));
    if (motor_b_speed < 0) gpioPWM(ENB_PIN, abs(motor_b_speed));
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Open log file
    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fclose(log_file);
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int motor_a_speed, motor_b_speed;
    float tilt_error, distance;

    // Main loop
    while (program_running) {
        // Generate tilt error and distance
        tilt_error = generate_tilt_error();
        distance = generate_distance();

        // Calculate motor speeds
        if (calculate_motor_speeds(tilt_error, distance, &motor_a_speed, &motor_b_speed) != 0) {
            fprintf(stderr, "Error calculating motor speeds!\n");
        }

        // Set motor speeds
        set_motor_speed(motor_a_speed, motor_b_speed);

        // Log data
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        // Obstacle avoidance
        if (distance < OBSTACLE_THRESHOLD) {
            // Reverse motors at 50% speed
            motor_a_speed = -128;
            motor_b_speed = -128;
            set_motor_speed(motor_a_speed, motor_b_speed);
            log_data(tilt_error, distance, motor_a_speed, motor_b_speed);
        }

        // Delay
        gpioDelay(50000); // 50 ms
    }

    // Stop motors
    set_motor_speed(0, 0);

    // Close log file
    fclose(log_file);

    // Cleanup GPIO
    cleanup_gpio();

    return 0;
}

