#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to store the relay state
static volatile int relay_state = 0;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void toggle_relay(int current_state);
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Initializes the pigpio library and configures GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Configure touch sensor pin as input with pull-down resistor
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);

    // Configure relay pin as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Initialize relay to OFF state

    return 0; // Indicate success
}

// Reads the touch sensor state
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Toggles the relay state
void toggle_relay(int current_state) {
    relay_state = !current_state;
    gpioWrite(RELAY_PIN, relay_state);
    printf("Relay toggled to %d\n", relay_state);
}

// Cleans up GPIO resources
void cleanup_gpio() {
    gpioWrite(RELAY_PIN, 0); // Ensure relay is OFF
    gpioTerminate();
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Smart Light Switch started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int touch_detected = read_touch_sensor();

        if (touch_detected) {
            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY * 1000); // Convert ms to microseconds

            // Re-read the sensor to confirm the touch
            if (read_touch_sensor()) {
                toggle_relay(relay_state);
            }
        }

        gpioDelay(1000); // Check every 1 ms
    }

    return 0; // This line will not be reached due to the infinite loop
}

