#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// TCS34725 I2C address
#define TCS34725_ADDR 0x29

// TCS34725 register addresses
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int signal)
{
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the TCS34725 sensor
int init_tcs34725()
{
    // Enable power-on and RGBC enable
    if (i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error writing to ENABLE register\n");
        return -1;
    }

    // Set integration time (ATIME)
    if (i2cWriteByteData(i2c_handle, TCS34725_ATIME, 0xD5) < 0) {
        fprintf(stderr, "Error writing to ATIME register\n");
        return -1;
    }

    return 0;
}

// Function to read color data from the TCS34725 sensor
int read_color_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue)
{
    unsigned char data[8];

    // Read all color data registers in one go
    if (i2cReadI2CBlockData(i2c_handle, TCS34725_CDATA, (char *)data, 8) < 0) {
        fprintf(stderr, "Error reading color data\n");
        return -1;
    }

    // Combine the bytes to form 16-bit color values
    *clear = (data[1] << 8) | data[0];
    *red   = (data[3] << 8) | data[2];
    *green = (data[5] << 8) | data[4];
    *blue  = (data[7] << 8) | data[6];

    return 0;
}

// Function to log color data to a CSV file
void log_color_data(time_t timestamp, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue)
{
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp_str, clear, red, green, blue);
    fflush(fp); // Ensure data is written to file immediately
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_tcs34725() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the CSV file for appending
    fp = fopen("color_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening color_data.csv\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Clear,Red,Green,Blue\n");
    }
    rewind(fp);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    uint16_t clear, red, green, blue;
    time_t current_time;

    while (!terminate) {
        // Read color data
        if (read_color_data(&clear, &red, &green, &blue) == 0) {
            // Get current timestamp
            current_time = time(NULL);

            // Log the color data
            log_color_data(current_time, clear, red, green, blue);
        } else {
            // Set sensor values to 0 for this cycle
            clear = 0;
            red = 0;
            green = 0;
            blue = 0;
            log_color_data(time(NULL), clear, red, green, blue);
        }

        // Delay for 500 ms
        gpioDelay(500);
    }

    // Close the I2C handle and terminate pigpio
    i2cClose(i2c_handle);
    fclose(fp);
    gpioTerminate();

    return 0;
}

