#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

// Define GPIO pins for the PIR motion sensors
#define PIR1_PIN 4
#define PIR2_PIN 17
#define PIR3_PIN 27
#define PIR4_PIN 22

// Define the number of lamps
#define NUM_LAMPS 4

// Define the duration of each phase in seconds
#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 14400

// Define the number of steps for the sunrise/sunset simulation
#define SUNRISE_SUNSET_STEPS 60

// Global variables
static volatile int running = 1;
static int current_phase = 0; // 0: Nighttime, 1: Sunset, 2: Daytime, 3: Sunrise
static int current_step = 0;
static int motion_detected = 0;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void signal_handler(int signal);
void set_relay_state(int relay_pin, int state);
void simulate_sunrise();
void simulate_daytime();
void simulate_sunset();
void simulate_nighttime();
void motion_detection_callback(int gpio, int level, uint32_t tick);

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set relay pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set PIR pins as inputs with pull-down resistors
    gpioSetMode(PIR1_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR1_PIN, PI_PUD_DOWN);
    gpioSetMode(PIR2_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR2_PIN, PI_PUD_DOWN);
    gpioSetMode(PIR3_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR3_PIN, PI_PUD_DOWN);
    gpioSetMode(PIR4_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR4_PIN, PI_PUD_DOWN);

    // Set initial relay states to OFF (active-low)
    set_relay_state(RELAY1_PIN, 1);
    set_relay_state(RELAY2_PIN, 1);
    set_relay_state(RELAY3_PIN, 1);
    set_relay_state(RELAY4_PIN, 1);

    return 0;
}

// Function to cleanup the GPIO pins
void cleanup_gpio() {
    // Turn off all relays
    set_relay_state(RELAY1_PIN, 1);
    set_relay_state(RELAY2_PIN, 1);
    set_relay_state(RELAY3_PIN, 1);
    set_relay_state(RELAY4_PIN, 1);

    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Function to set the state of a relay
void set_relay_state(int relay_pin, int state) {
    gpioWrite(relay_pin, state);
}

// Function to simulate the sunrise phase
void simulate_sunrise() {
    current_phase = 0;
    for (int i = 0; i < SUNRISE_SUNSET_STEPS; i++) {
        current_step = i;
        if (motion_detected) {
            printf("Motion detected during sunrise, increasing brightness to 100%%\n");
            set_relay_state(RELAY1_PIN, 0);
            set_relay_state(RELAY2_PIN, 0);
            set_relay_state(RELAY3_PIN, 0);
            set_relay_state(RELAY4_PIN, 0);
            motion_detected = 0; // Reset motion detection flag
            return;
        }
        int duty_cycle = (int)(((float)i / SUNRISE_SUNSET_STEPS) * 100);
        set_relay_state(RELAY1_PIN, 0);
        set_relay_state(RELAY2_PIN, 0);
        set_relay_state(RELAY3_PIN, 0);
        set_relay_state(RELAY4_PIN, 0);
        gpioDelay(1000000 / 100); // Delay for 1 second (1000000 microseconds / duty cycle)
    }
    printf("Sunrise complete, transitioning to daytime\n");
    current_phase = 1;
}

// Function to simulate the daytime phase
void simulate_daytime() {
    current_phase = 2;
    for (int i = 0; i < DAYTIME_DURATION / 1000; i++) {
        if (motion_detected) {
            printf("Motion detected during daytime, increasing brightness to 100%%\n");
            set_relay_state(RELAY1_PIN, 0);
            set_relay_state(RELAY2_PIN, 0);
            set_relay_state(RELAY3_PIN, 0);
            set_relay_state(RELAY4_PIN, 0);
            motion_detected = 0; // Reset motion detection flag
            return;
        }
        set_relay_state(RELAY1_PIN, 0);
        set_relay_state(RELAY2_PIN, 0);
        set_relay_state(RELAY3_PIN, 0);
        set_relay_state(RELAY4_PIN, 0);
        gpioDelay(1000000); // Delay for 1 second
    }
    printf("Daytime complete, transitioning to sunset\n");
    current_phase = 3;
}

// Function to simulate the sunset phase
void simulate_sunset() {
    current_phase = 3;
    for (int i = SUNRISE_SUNSET_STEPS - 1; i >= 0; i--) {
        current_step = i;
        if (motion_detected) {
            printf("Motion detected during sunset, decreasing brightness to 0%%\n");
            set_relay_state(RELAY1_PIN, 1);
            set_relay_state(RELAY2_PIN, 1);
            set_relay_state(RELAY3_PIN, 1);
            set_relay_state(RELAY4_PIN, 1);
            motion_detected = 0; // Reset motion detection flag
            return;
        }
        int duty_cycle = (int)(((float)i / SUNRISE_SUNSET_STEPS) * 100);
        set_relay_state(RELAY1_PIN, 0);
        set_relay_state(RELAY2_PIN, 0);
        set_relay_state(RELAY3_PIN, 0);
        set_relay_state(RELAY4_PIN, 0);
        gpioDelay(1000000 / 100); // Delay for 1 second (1000000 microseconds / duty cycle)
    }
    printf("Sunset complete, transitioning to nighttime\n");
    current_phase = 0;
}

// Function to simulate the nighttime phase
void simulate_nighttime() {
    current_phase = 0;
    for (int i = 0; i < NIGHTTIME_DURATION / 1000; i++) {
        if (motion_detected) {
            printf("Motion detected during nighttime, increasing brightness to 100%%\n");
            set_relay_state(RELAY1_PIN, 0);
            set_relay_state(RELAY2_PIN, 0);
            set_relay_state(RELAY3_PIN, 0);
            set_relay_state(RELAY4_PIN, 0);
            motion_detected = 0; // Reset motion detection flag
            return;
        }
        set_relay_state(RELAY1_PIN, 1);
        set_relay_state(RELAY2_PIN, 1);
        set_relay_state(RELAY3_PIN, 1);
        set_relay_state(RELAY4_PIN, 1);
        gpioDelay(1000000); // Delay for 1 second
    }
    printf("Nighttime complete, transitioning to sunrise\n");
    current_phase = 1;
}

// Callback function for motion detection
void motion_detection_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge detected (motion detected)
        printf("Motion detected on GPIO %d\n", gpio);
        motion_detected = 1;
    }
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set up motion detection callbacks
    gpioSetAlertFuncEx(PIR1_PIN, motion_detection_callback, NULL);
    gpioSetAlertFuncEx(PIR2_PIN, motion_detection_callback, NULL);
    gpioSetAlertFuncEx(PIR3_PIN, motion_detection_callback, NULL);
    gpioSetAlertFuncEx(PIR4_PIN, motion_detection_callback, NULL);

    // Main loop
    while (running) {
        switch (current_phase) {
            case 0: // Nighttime
                simulate_nighttime();
                break;
            case 1: // Sunset
                simulate_sunset();
                break;
            case 2: // Daytime
                simulate_daytime();
                break;
            case 3: // Sunrise
                simulate_sunrise();
                break;
        }
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    return 0;
}

