        set_relay_state(RELAY4_PIN, 0);
        gpioDelay(1000000); // Delay for 1 second
    }
    printf("Daytime complete, transitioning to sunset\n");
    current_phase = 3;
}

// Function to simulate the sunset phase
void simulate_sunset() {
    current_phase = 3;
    for (int i = SUNRISE_SUNSET_STEPS - 1; i >= 0; i--) {
        current_step = i;
        if (motion_detected) {
            printf("Motion detected during sunset, decreasing brightness to 0%%\n");
            set_relay_state(RELAY1_PIN, 1);
            set_relay_state(RELAY2_PIN, 1);
            set_relay_state(RELAY3_PIN, 1);
            set_relay_state(RELAY4_PIN, 1);
            motion_detected = 0; // Reset motion detection flag
            return;
        }
        int duty_cycle = (int)(((float)i / SUNRISE_SUNSET_STEPS) * 100);
        set_relay_state(RELAY1_PIN, 0);
        set_relay_state(RELAY2_PIN, 0);
        set_relay_state(RELAY3_PIN, 0);
        set_relay_state(RELAY4_PIN, 0);
        gpioDelay(1000000 / 100); // Delay for 1 second (1000000 microseconds / duty cycle)
    }
    printf("Sunset complete, transitioning to nighttime\n");
    current_phase = 0;
}

// Function to simulate the nighttime phase
void simulate_nighttime() {
    current_phase = 0;
    for (int i = 0; i < NIGHTTIME_DURATION / 1000; i++) {
        if (motion_detected) {
            printf("Motion detected during nighttime, increasing brightness to 100%%\n");
            set_relay_state(RELAY1_PIN, 0);
            set_relay_state(RELAY2_PIN, 0);
            set_relay_state(RELAY3_PIN, 0);
            set_relay_state(RELAY4_PIN, 0);
            motion_detected = 0; // Reset motion detection flag
            return;
        }
        set_relay_state(RELAY1_PIN, 1);
        set_relay_state(RELAY2_PIN, 1);
        set_relay_state(RELAY3_PIN, 1);
        set_relay_state(RELAY4_PIN, 1);
        gpioDelay(1000000); // Delay for 1 second
    }
    printf("Nighttime complete, transitioning to sunrise\n");
    current_phase = 1;
}

// Callback function for motion detection
void motion_detection_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge detected (motion detected)
        printf("Motion detected on GPIO %d\n", gpio);
        motion_detected = 1;
    }
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set up motion detection callbacks
    gpioSetAlertFuncEx(PIR1_PIN, motion_detection_callback, NULL);
    gpioSetAlertFuncEx(PIR2_PIN, motion_detection_callback, NULL);
    gpioSetAlertFuncEx(PIR3_PIN, motion_detection_callback, NULL);
    gpioSetAlertFuncEx(PIR4_PIN, motion_detection_callback, NULL);

    // Main loop
    while (running) {
        switch (current_phase) {
            case 0: // Nighttime
                simulate_nighttime();
                break;
            case 1: // Sunset
                simulate_sunset();
                break;
            case 2: // Daytime
                simulate_daytime();
                break;
            case 3: // Sunrise
                simulate_sunrise();
                break;
        }
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    return 0;
}

