#include <sys/types.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define VIDEO_DURATION_SEC 5
#define LOG_FILE_PATH "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to generate ISO 8601 timestamp
void generate_iso8601_timestamp(char *timestamp)
{
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, 21, "%Y%m%dT%H%M%SZ", timeinfo);
}

// Function to log motion event to file
int log_motion_event(const char *timestamp)
{
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s\n", timestamp);
    fflush(log_file); // Ensure immediate write to disk
    return 0;
}

// Function to record video using raspivid
int record_video()
{
    char filename[50];
    char timestamp[21];
    generate_iso8601_timestamp(timestamp);
    snprintf(filename, sizeof(filename), "%s%s.h264", VIDEO_DIR, timestamp);

    char command[100];
    snprintf(command, sizeof(command), "raspivid -o %s -t %d", filename, VIDEO_DURATION_SEC * 1000);

    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error: Failed to execute raspivid command.\n");
        return -1;
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: raspivid command failed with exit status %d.\n", WEXITSTATUS(status));
        return -1;
    }

    return 0;
}

