void motion_detected_callback(int gpio, int level, uint32_t tick)
{
    if (level == 0) { // Active-low
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce
        char timestamp[21];
        generate_iso8601_timestamp(timestamp);

        if (log_motion_event(timestamp) != 0) {
            fprintf(stderr, "Error: Failed to log motion event.\n");
        }

        if (record_video() != 0) {
            fprintf(stderr, "Error: Failed to record video.\n");
        }
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal)
{
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Open log file
    log_file = fopen(LOG_FILE_PATH, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Set up callback function for motion detection
    gpioSetAlertFunc(GPIO_PIN, motion_detected_callback);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    // Keep the program running until interrupted
    while (running) {
        sleep(1); // Reduce CPU usage
    }

    return 0;
}

