#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// Gyroscope sensitivity (LSB/°/s)
#define GYRO_SENSITIVITY 131.0

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Function prototypes
int init_mpu6050(int i2c_handle);
int read_gyro_data(int i2c_handle, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void convert_gyro_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float *gyro_x_dps, float *gyro_y_dps, float *gyro_z_dps);
int log_data(FILE *log_file, float gyro_x_dps, float gyro_y_dps, float gyro_z_dps);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Initialize MPU-6050
int init_mpu6050(int i2c_handle) {
    // Wake up the MPU-6050
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }

    // Set sample rate divider
    if (i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error: Could not set sample rate divider\n");
        return -1;
    }

    // Set gyroscope full-scale range
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set gyroscope full-scale range\n");
        return -1;
    }

    return 0;
}

// Read gyroscope data
int read_gyro_data(int i2c_handle, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) < 0) {
        fprintf(stderr, "Error: Could not read gyroscope data\n");
        return -1;
    }

    *gyro_x = (int16_t)((buf[0] << 8) | buf[1]);
    *gyro_y = (int16_t)((buf[2] << 8) | buf[3]);
    *gyro_z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Convert raw data to degrees per second
void convert_gyro_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float *gyro_x_dps, float *gyro_y_dps, float *gyro_z_dps) {
    *gyro_x_dps = (float)gyro_x / GYRO_SENSITIVITY;
    *gyro_y_dps = (float)gyro_y / GYRO_SENSITIVITY;
    *gyro_z_dps = (float)gyro_z / GYRO_SENSITIVITY;
}

// Log data to file
int log_data(FILE *log_file, float gyro_x_dps, float gyro_y_dps, float gyro_z_dps) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    if (fprintf(log_file, "%ld,%.2f,%.2f,%.2f\n", timestamp_ms, gyro_x_dps, gyro_y_dps, gyro_z_dps) < 0) {
        fprintf(stderr, "Error: Could not write data to log file\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050(i2c_handle) < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int retry_count = 0;
    int16_t gyro_x, gyro_y, gyro_z;
    float gyro_x_dps, gyro_y_dps, gyro_z_dps;

    // Main loop
    while (1) {
        // Read gyroscope data
        if (read_gyro_data(i2c_handle, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Convert gyroscope data
            convert_gyro_data(gyro_x, gyro_y, gyro_z, &gyro_x_dps, &gyro_y_dps, &gyro_z_dps);

            // Log data
            if (log_data(log_file, gyro_x_dps, gyro_y_dps, gyro_z_dps) != 0) {
                fprintf(stderr, "Error: Failed to log data, but continuing...\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read gyro data, retrying...\n");
            retry_count++;
            if (retry_count > 3) {
                fprintf(stderr, "Error: Max retries reached, exiting...\n");
                break;
            }
            // Attempt to re-initialize the sensor
            if (init_mpu6050(i2c_handle) < 0) {
                fprintf(stderr, "Error: MPU-6050 re-initialisation failed\n");
                break;
            }
        }

        // Delay for 10 ms
        gpioDelay(10000); // 10 ms = 10000 µs
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

