#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 registers
#define DATA_FORMAT 0x31
#define POWER_CTL   0x2D
#define DATAX0      0x32

// GPIO pin for alarm
#define ALARM_PIN 27

// Freefall threshold (g)
#define FREEFALL_THRESHOLD 0.2

// Freefall duration (seconds)
#define FREEFALL_DURATION 0.5

// Freefall detection window (seconds)
#define FREEFALL_WINDOW 0.5

// Scale factor (LSB/g)
#define SCALE_FACTOR 256.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int adxl345_init();
int read_adxl345_data(int16_t *x, int16_t *y, int16_t *z);
float convert_to_g(int16_t raw_value);
int detect_freefall(int16_t x, int16_t y, int16_t z);
void trigger_alarm();
void log_freefall(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// ADXL345 initialization function
int adxl345_init() {
    // Set DATA_FORMAT register to 0x0B (Full resolution, +/- 2g range)
    if (i2cWriteByteData(i2c_handle, DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error writing to DATA_FORMAT register.\n");
        return -1;
    }

    // Enable measurement mode
    if (i2cWriteByteData(i2c_handle, POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register.\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
int read_adxl345_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, DATAX0, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data.\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to convert raw data to g-force
float convert_to_g(int16_t raw_value) {
    return (float)raw_value / SCALE_FACTOR;
}

// Function to detect freefall
int detect_freefall(int16_t x, int16_t y, int16_t z) {
    float x_g = convert_to_g(x);
    float y_g = convert_to_g(y);
    float z_g = convert_to_g(z);

    if (fabs(x_g) < FREEFALL_THRESHOLD &&
        fabs(y_g) < FREEFALL_THRESHOLD &&
        fabs(z_g) < FREEFALL_THRESHOLD) {
        return 1;
    } else {
        return 0;
    }
}

// Function to trigger the alarm
void trigger_alarm() {
    gpioWrite(ALARM_PIN, 1); // Set GPIO high
    gpioDelay(5000);         // Wait for 5 seconds
    gpioWrite(ALARM_PIN, 0); // Set GPIO low
}

// Function to log freefall event
void log_freefall(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    int16_t x, y, z;
    int freefall_count = 0;
    time_t start_time = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0); // Bus 1, address 0x53, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init() < 0) {
        fprintf(stderr, "ADXL345 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO27 as output
    gpioSetMode(ALARM_PIN, PI_OUTPUT);
    gpioWrite(ALARM_PIN, 0); // Ensure it starts low

    // Open log file
    log_file = fopen("freefall.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Freefall detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read accelerometer data
        if (read_adxl345_data(&x, &y, &z) == 0) {
            // Detect freefall
            if (detect_freefall(x, y, z)) {
                freefall_count++;
                if (freefall_count >= (int)(FREEFALL_DURATION / (FREEFALL_WINDOW / 100.0))) { // Check if freefall duration has been met
                    time_t current_time;
                    time(&current_time);

                    if (start_time == 0) {
                        start_time = current_time;
                    }

                    if (difftime(current_time, start_time) >= FREEFALL_WINDOW) {
                        // Trigger alarm
                        trigger_alarm();

                        // Log freefall event
                        log_freefall(x, y, z);

                        // Reset freefall count and start time
                        freefall_count = 0;
                        start_time = 0;
                    }
                }
            } else {
                freefall_count = 0; // Reset freefall count if not in freefall
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data. Retrying...\n");
        }

        gpioDelay(100); // Delay 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(ALARM_PIN, 0); // Ensure alarm is off
    gpioTerminate();
    fclose(log_file);

    printf("Exiting.\n");
    return 0;
}

