#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <pthread.h>

// Define GPIO pins
#define TRIG_PIN 4
#define ECHO_PIN 18

// Define constants
#define TIMEOUT_US 100000 // 100 ms
#define MAX_RANGE_US 23200000 // 4 meters
#define MAX_DISTANCE_CM 400 // 4 meters
#define MEASUREMENT_INTERVAL_MS 200

// Global variables
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void trigger_pulse(int gpio, int level, uint32_t tick);
void echo_rising(int gpio, int level, uint32_t tick);
void echo_falling(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t pulse_width);
void log_distance(double distance);
void signal_handler(int signal);

// Trigger pulse callback function
void trigger_pulse(int gpio, int level, uint32_t tick)
{
    if (level == 1) // Rising edge
    {
        gpioWrite(ECHO_PIN, 1); // Set ECHO high
        gpioDelay(10); // 10 us pulse
        gpioWrite(ECHO_PIN, 0); // Set ECHO low
        echo_received = 1; // Indicate that echo is expected
    }
}

// Rising edge callback function
void echo_rising(int gpio, int level, uint32_t tick)
{
    pthread_mutex_lock(&pulse_mutex);
    start_tick = tick;
    echo_received = 1; // Indicate that start tick is set
    pthread_mutex_unlock(&pulse_mutex);
}

// Falling edge callback function
void echo_falling(int gpio, int level, uint32_t tick)
{
    pthread_mutex_lock(&pulse_mutex);
    if (echo_received)
    {
        end_tick = tick;
        echo_received = 0; // Reset the flag
    }
    pthread_mutex_unlock(&pulse_mutex);
}

// Calculate distance in centimeters
double calculate_distance(uint32_t pulse_width)
{
    // Speed of sound in air (343 m/s) converted to cm/us
    // Distance = (Time * Speed of Sound) / 2
    // Speed of sound = 0.0343 cm/us
    return (double)pulse_width * 0.0343 / 2.0;
}

// Log distance to file
void log_distance(double distance)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ns = (long)ts.tv_sec * 1000000000LL + ts.tv_nsec;

    if (log_file != NULL)
    {
        fprintf(log_file, "%ld,%.2f\n", timestamp_ns, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    }
    else
    {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;

    // Cancel callbacks
    gpioSetAlertFuncEx(TRIG_PIN, NULL, NULL);
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);

    // Close log file
    if (log_file != NULL)
    {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    // Destroy mutex
