void log_distance(double distance)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ns = (long)ts.tv_sec * 1000000000LL + ts.tv_nsec;

    if (log_file != NULL)
    {
        fprintf(log_file, "%ld,%.2f\n", timestamp_ns, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    }
    else
    {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

