void signal_handler(int signal)
{
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;

    // Cancel callbacks
    gpioSetAlertFuncEx(TRIG_PIN, NULL, NULL);
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);

    // Close log file
    if (log_file != NULL)
    {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    // Destroy mutex
    pthread_mutex_destroy(&pulse_mutex);

    exit(0);
}

