#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Motor 1 (X-axis) GPIO pins
#define MOTOR1_IN1 4
#define MOTOR1_IN2 17
#define MOTOR1_IN3 27
#define MOTOR1_IN4 22

// Motor 2 (Y-axis) GPIO pins
#define MOTOR2_IN1 5
#define MOTOR2_IN2 6
#define MOTOR2_IN3 13
#define MOTOR2_IN4 19

// Steps per revolution (28BYJ-48 with 1/64 gear ratio)
#define STEPS_PER_REV 2048

// Steps per mm (10 steps/mm)
#define STEPS_PER_MM 10

// Square side length (mm)
#define SQUARE_SIDE 50

// Delay between steps (us)
#define STEP_DELAY 1000

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCtrl+C pressed. Stopping motors and exiting...\n");
}

// Function to set the GPIO pins for a motor step
void set_motor_step(int motor, int step) {
    int in1, in2, in3, in4;

    if (motor == 1) {
        in1 = MOTOR1_IN1;
        in2 = MOTOR1_IN2;
        in3 = MOTOR1_IN3;
        in4 = MOTOR1_IN4;
    } else if (motor == 2) {
        in1 = MOTOR2_IN1;
        in2 = MOTOR2_IN2;
        in3 = MOTOR2_IN3;
        in4 = MOTOR2_IN4;
    } else {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor);
        return;
    }

    switch (step) {
        case 0:
            gpioWrite(in1, 1);
            gpioWrite(in2, 0);
            gpioWrite(in3, 0);
            gpioWrite(in4, 0);
            break;
        case 1:
            gpioWrite(in1, 0);
            gpioWrite(in2, 1);
            gpioWrite(in3, 0);
            gpioWrite(in4, 0);
            break;
        case 2:
            gpioWrite(in1, 0);
            gpioWrite(in2, 0);
            gpioWrite(in3, 1);
            gpioWrite(in4, 0);
            break;
        case 3:
            gpioWrite(in1, 0);
            gpioWrite(in2, 0);
            gpioWrite(in3, 0);
            gpioWrite(in4, 1);
            break;
        default:
            fprintf(stderr, "Error: Invalid step number: %d\n", step);
            return;
    }
}

// Function to move a motor a specified number of steps
void move_motor(int motor, int steps, int direction) {
    int i, current_step = 0;

    if (direction == 1) { // Clockwise
        for (i = 0; i < steps; i++) {
            set_motor_step(motor, current_step);
            current_step = (current_step + 1) % 4;
            gpioDelay(STEP_DELAY);
        }
    } else if (direction == -1) { // Counter-clockwise
        for (i = 0; i < steps; i++) {
            set_motor_step(motor, current_step);
            current_step = (current_step + 3) % 4; // Subtract 1, wrapping around
            gpioDelay(STEP_DELAY);
        }
    } else {
        fprintf(stderr, "Error: Invalid direction: %d\n", direction);
        return;
    }
}

// Function to move the X-axis
void move_x(int steps) {
    move_motor(1, steps, 1); // Clockwise
}

// Function to move the Y-axis
void move_y(int steps) {
    move_motor(2, steps, 1); // Clockwise
}

// Function to draw a square
void draw_square(int side_length) {
    move_x(side_length);
    move_y(side_length);
    move_x(-side_length);
    move_y(-side_length);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    int pins[] = {MOTOR1_IN1, MOTOR1_IN2, MOTOR1_IN3, MOTOR1_IN4, MOTOR2_IN1, MOTOR2_IN2, MOTOR2_IN3, MOTOR2_IN4};
    int num_pins = sizeof(pins) / sizeof(pins[0]);
    for (int i = 0; i < num_pins; i++) {
        int pin = pins[i];
        if (gpioSetMode(pin, PI_OUTPUT) != 0) {
            fprintf(stderr, "Error setting GPIO %d as output\n", pin);
            gpioTerminate();
            return 1;
        }
    }

    // Set up signal handler for Ctrl+C
