#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LIS3DH I2C address
#define LIS3DH_ADDR 0x18

// LIS3DH register addresses
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// Configuration values
#define CTRL_REG1_VALUE 0x57  // 0x08 | 0x04 | 0x02 | 0x01
#define CTRL_REG4_VALUE 0x88  // 0x10 | 0x08 | 0x04 | 0x02

// Global variables
int i2c_handle;
double threshold = 2.0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int i2c_bus, int i2c_address);
int configure_sensor(int i2c_handle);
int read_acceleration(int i2c_handle, int16_t *x, int16_t *y, int16_t *z);
double convert_to_g(int16_t raw_value);
void log_event(int16_t x, int16_t y, int16_t z);
void shutdown_system();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c(int i2c_bus, int i2c_address) {
    i2c_handle = i2cOpen(i2c_bus, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return i2c_handle;
}

// Configure the LIS3DH sensor
int configure_sensor(int i2c_handle) {
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, CTRL_REG1_VALUE) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, CTRL_REG4_VALUE) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }
    return 0;
}

// Read acceleration data from the LIS3DH
int read_acceleration(int i2c_handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Convert raw acceleration data to g-force units
double convert_to_g(int16_t raw_value) {
    return (double)raw_value * 0.0009765625;
}

// Log high acceleration event to file
void log_event(int16_t x, int16_t y, int16_t z) {
    FILE *fp = fopen("/var/log/high_acceleration.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - High acceleration detected: X=%d, Y=%d, Z=%d g\n", s, x, y, z);
    fclose(fp);
}

// Shutdown the system
void shutdown_system() {
    printf("Shutting down system...\n");
    system("sudo shutdown -h now");
}

int main(int argc, char *argv[]) {
    int i2c_bus = 1; // Default I2C bus
    int i2c_address = LIS3DH_ADDR;

    // Parse command-line arguments
    if (argc > 1) {
        i2c_address = strtol(argv[1], NULL, 16);
        if (i2c_address < 0x08 || i2c_address > 0x77) {
            fprintf(stderr, "Invalid I2C address: 0x%02X. Must be between 0x08 and 0x77.\n", i2c_address);
            return 1;
        }
    }
    if (argc > 2) {
        threshold = strtod(argv[2], NULL);
        if (threshold <= 0) {
            fprintf(stderr, "Invalid threshold value: %f. Must be greater than 0.\n", threshold);
            return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c(i2c_bus, i2c_address) < 0) {
        gpioTerminate();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t x, y, z;
    double x_g, y_g, z_g;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            // Convert to g-force units
            x_g = convert_to_g(x);
            y_g = convert_to_g(y);
            z_g = convert_to_g(z);

            // Check for high acceleration
            if (abs(x_g) > threshold || abs(y_g) > threshold || abs(z_g) > threshold) {
                log_event(x, y, z);
                shutdown_system();
            }
        } else {
            fprintf(stderr, "Error reading acceleration, retrying...\n");
        }

        gpioDelay(100000); // 10 Hz (100 ms)
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

