#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LEFT_SENSOR 4
#define CENTER_SENSOR 17
#define RIGHT_SENSOR 27
#define ALERT_PIN 22

// Circular buffer size
#define BUFFER_SIZE 5

// Global variables
volatile sig_atomic_t program_running = 1;

// Structure for circular buffer
typedef struct {
    int buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} CircularBuffer;

// Function prototypes
int read_sensor(int gpio_pin);
void add_to_buffer(CircularBuffer *cb, int value);
int get_from_buffer(CircularBuffer *cb);
void line_following_logic(int left, int center, int right);
void alert_user(int alert_pin);
void motor_forward(void);
void motor_left(void);
void motor_right(void);
void motor_stop(void);
void signal_handler(int signal);

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
}

// Add a value to the circular buffer
void add_to_buffer(CircularBuffer *cb, int value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count == BUFFER_SIZE) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    } else {
        cb->count++;
    }
}

// Get the oldest value from the circular buffer
int get_from_buffer(CircularBuffer *cb) {
    if (cb->count == 0) {
        return -1; // Indicate empty buffer
    }
    int value = cb->buffer[cb->tail];
    cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    cb->count--;
    return value;
}

// Read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Line-following logic
void line_following_logic(int left, int center, int right) {
    if (center == 0) {
        motor_forward();
    } else if (left == 0) {
        motor_left();
    } else if (right == 0) {
        motor_right();
    } else {
        motor_stop();
    }
}

// Alert user
void alert_user(int alert_pin) {
    gpioWrite(alert_pin, 1); // Set HIGH
    gpioDelay(2000);         // Wait 2 seconds
    gpioWrite(alert_pin, 0); // Set LOW
}

// Motor control functions (placeholders)
void motor_forward(void) {
    printf("Motor Forward\n");
}

void motor_left(void) {
    printf("Motor Left\n");
}

void motor_right(void) {
    printf("Motor Right\n");
}

void motor_stop(void) {
    printf("Motor Stop\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(CENTER_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    // Initialize circular buffer
    CircularBuffer line_buffer;
    init_circular_buffer(&line_buffer);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Line-following robot started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int left = read_sensor(LEFT_SENSOR);
        int center = read_sensor(CENTER_SENSOR);
        int right = read_sensor(RIGHT_SENSOR);

        // Add sensor readings to circular buffer
        add_to_buffer(&line_buffer, center);

        // Check for no-line condition
        if (center == 1) {
            int oldest_center = get_from_buffer(&line_buffer);
            if (oldest_center == 1) {
                // No line detected for 5 consecutive readings
                alert_user(ALERT_PIN);
                // Debounce: Wait a bit before checking again
                gpioDelay(500); // Wait 0.5 seconds
            }
        }

        // Line-following logic
        line_following_logic(left, center, right);

        // Delay
        gpioDelay(10); // 10 ms delay
    }

    // Clean up
    gpioTerminate();
    return 0;
}

