#define CONVERSION_VALUE 0x01
#define POLL_ATTEMPTS 50
#define TIMEOUT_MS 50

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int start_conversion();
int read_field_data(int16_t *field_raw);
float convert_to_mT(int16_t field_raw);
int check_threshold(float field_mT, float threshold_mT);
void control_relay(int state);
void log_event(const char *event_type, float field_mT, int relay_state);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

