        fprintf(stderr, "Error setting GPIO mode.\n");
        return -1;
    }
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is off initially
    return 0;
}

// Start conversion
int start_conversion() {
    if (i2cWriteByteData(i2c_handle, CONVERSION_REG, CONVERSION_VALUE) != 0) {
        fprintf(stderr, "Error starting conversion.\n");
        return -1;
    }
    return 0;
}

// Read field data
int read_field_data(int16_t *field_raw) {
    int retries = 0;
    while (retries < POLL_ATTEMPTS) {
        if (i2cWriteByte(i2c_handle, CONVERSION_REG) != 0) {
            fprintf(stderr, "Error writing to conversion register.\n");
            return -1;
        }
        gpioDelay(1); // Small delay after write

        int data = i2cReadByteData(i2c_handle, DATA_REG);
        if (data >= 0) {
