        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    int relay_state = 0; // 0 = off, 1 = on
    int16_t field_raw;
    float field_mT;

    // Main loop
    while (!terminate) {
        // Start conversion
        if (start_conversion() != 0) {
            fprintf(stderr, "Error starting conversion, retrying in %d ms.\n", SAMPLE_INTERVAL_MS);
            log_event("Error", 0.0, relay_state);
            gpioDelay(SAMPLE_INTERVAL_MS);
            continue;
