        field_mT = convert_to_mT(field_raw);

        // Check threshold
        int threshold_exceeded = check_threshold(field_mT, THRESHOLD_MT);

        // Control relay
        if (threshold_exceeded && !relay_state) {
            control_relay(1);
            relay_state = 1;
            log_event("Threshold Exceeded", field_mT, relay_state);
        } else if (!threshold_exceeded && relay_state) {
            control_relay(0);
