#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PORT 5000
#define BUFFER_SIZE 1024

int server_fd, new_socket;
FILE *log_file;

// Function to log events with timestamp
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        log_event("Received signal, shutting down...");
        if (new_socket > 0) {
            close(new_socket);
        }
        if (server_fd > 0) {
            close(server_fd);
        }
        if (log_file != NULL) {
            fclose(log_file);
        }
        gpioWrite(GPIO_PIN, 0); // Turn off relay
        gpioTerminate();
        exit(0);
    }
}

// Function to parse the command
int parse_command(char *command, char *action) {
    char *token = strtok(command, " ");
    if (token != NULL) {
        if (strcmp(token, "on") == 0 || strcmp(token, "ON") == 0) {
            strcpy(action, "ON");
            return 0; // Success
        } else if (strcmp(token, "off") == 0 || strcmp(token, "OFF") == 0) {
            strcpy(action, "OFF");
            return 0; // Success
        }
    }
    return -1; // Invalid command
}

// Function to control the relay
int control_relay(const char *action) {
    if (strcmp(action, "ON") == 0) {
        gpioWrite(GPIO_PIN, 1);
        log_event("Relay turned ON");
        return 0;
    } else if (strcmp(action, "OFF") == 0) {
        gpioWrite(GPIO_PIN, 0);
        log_event("Relay turned OFF");
        return 0;
    } else {
        log_event("Invalid command");
        return -1;
    }
}

int main() {
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);
    char buffer[BUFFER_SIZE] = {0};
    char command[BUFFER_SIZE] = {0};
    char action[4] = {0}; // Buffer to store "ON" or "OFF"

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    log_event("Starting relay control server...");

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        fclose(log_file);
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        log_event("Socket creation failed");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Set socket options to reuse address
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        log_event("Setsockopt failed");
        close(server_fd);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Bind socket to address
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_event("Bind failed");
        close(server_fd);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        log_event("Listen failed");
        close(server_fd);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    log_event("Listening for connections...");

    // Accept connection
    if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
        log_event("Accept failed");
        close(server_fd);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    log_event("Connection accepted");

    // Receive and process commands
    while (1) {
        ssize_t bytes_received = recv(new_socket, buffer, BUFFER_SIZE - 1, 0);
        if (bytes_received > 0) {
            buffer[bytes_received] = '\0';
            log_event("Received command");
            if (parse_command(buffer, action) == 0) {
                if (control_relay(action) == 0) {
                    // Send response
                    const char *response = (strcmp(action, "ON") == 0) ? "ON" : "OFF";
                    send(new_socket, response, strlen(response), 0);
                } else {
                    send(new_socket, "Invalid command", strlen("Invalid command"), 0);
                }
            } else {
                send(new_socket, "Invalid command", strlen("Invalid command"), 0);
            }
        } else if (bytes_received == 0) {
            log_event("Client disconnected");
            break;
        } else {
            log_event("Receive failed");
            break;
        }
    }

    // Clean up
    close(new_socket);
    close(server_fd);
    gpioWrite(GPIO_PIN, 0); // Turn off relay
    gpioTerminate();
    fclose(log_file);

    log_event("Server shut down");

    return 0;
}

