#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define START_MEASUREMENT_CMD 0x3608
#define SCALE_FACTOR 1.0 / 1500.0
#define FLOW_THRESHOLD 5.0
#define RELAY_GPIO 18
#define POLLING_INTERVAL_MS 100

// Global variables
volatile sig_atomic_t terminate = 0;
int i2c_handle1 = -1;
int i2c_handle2 = -1;

// Function prototypes
int initialize_pigpio();
int open_i2c_handle(int bus, int addr);
int write_i2c_bytes(int handle, uint16_t command);
int read_i2c_bytes(int handle, char *buffer, int count);
int validate_crc(const char *data, int len);
float convert_to_ml_min(int16_t raw_value);
void control_relay(float flow1, float flow2);
void log_flow_data(float flow1, float flow2);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
}

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C handle
int open_i2c_handle(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    return handle;
}

// Write I2C bytes
int write_i2c_bytes(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read I2C bytes
int read_i2c_bytes(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Validate CRC-8
int validate_crc(const char *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31; // Polynomial 0x31
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == 0);
}

// Convert raw value to ml/min
float convert_to_ml_min(int16_t raw_value) {
    return (float)raw_value * SCALE_FACTOR;
}

// Control relay based on flow rates
void control_relay(float flow1, float flow2) {
    if (flow1 < FLOW_THRESHOLD || flow2 < FLOW_THRESHOLD) {
        gpioWrite(RELAY_GPIO, 1); // Energize relay
    } else {
        gpioWrite(RELAY_GPIO, 0); // De-energize relay
    }
}

// Log flow data to file
void log_flow_data(float flow1, float flow2) {
    FILE *fp = fopen("flow_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long milliseconds = ts.tv_nsec / 1000000;

    fprintf(fp, "%ld,%.2f,%.2f\n", milliseconds, flow1, flow2);
    fflush(fp);
    fclose(fp);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    gpioWrite(RELAY_GPIO, 0); // De-energize relay
    gpioTerminate();
    printf("Shutdown complete.\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C handles
    i2c_handle1 = open_i2c_handle(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        cleanup();
        return 1;
    }

    i2c_handle2 = open_i2c_handle(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        cleanup();
        return 1;
    }

    // Configure relay GPIO
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to de-energized state

    // Start measurement on both sensors
    if (write_i2c_bytes(i2c_handle1, START_MEASUREMENT_CMD) != 0) {
        cleanup();
        return 1;
    }
    if (write_i2c_bytes(i2c_handle2, START_MEASUREMENT_CMD) != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        char buffer1[3];
        char buffer2[3];
        int16_t raw_flow1, raw_flow2;
        float flow1, flow2;

        // Read data from sensor 1
        if (read_i2c_bytes(i2c_handle1, buffer1, 3) == 0) {
            if (validate_crc(buffer1, 2)) {
                raw_flow1 = (buffer1[0] << 8) | buffer1[1];
                flow1 = convert_to_ml_min(raw_flow1);
            } else {
                fprintf(stderr, "Sensor 1 CRC check failed\n");
            }
        } else {
            fprintf(stderr, "Sensor 1 read failed\n");
        }

        // Read data from sensor 2
        if (read_i2c_bytes(i2c_handle2, buffer2, 3) == 0) {
            if (validate_crc(buffer2, 2)) {
                raw_flow2 = (buffer2[0] << 8) | buffer2[1];
                flow2 = convert_to_ml_min(raw_flow2);
            } else {
                fprintf(stderr, "Sensor 2 CRC check failed\n");
            }
        } else {
            fprintf(stderr, "Sensor 2 read failed\n");
        }

        // Control relay and log data
        control_relay(flow1, flow2);
        log_flow_data(flow1, flow2);

        gpioDelay(POLLING_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

