// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define constants
#define POLL_INTERVAL_MS 200
#define MOTOR_RUN_TIME_S 5
#define DEBOUNCE_TIME_MS 600

// Global variables
static volatile int running = 1;
static volatile int dry_count = 0;
static volatile int motor_active = 0;

// Function prototypes
int initialize_gpio();
int read_rain_sensor();
void start_motor();
void stop_motor();
void debounce_check();
void signal_handler(int signal);
void log_message(int priority, const char *message);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return 1; // Indicate failure
    }

    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP);

    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    log_message(LOG_INFO, "GPIO initialisation complete");
    return 0; // Indicate success
}

// Function to read the rain sensor
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

// Function to start the motor
void start_motor() {
    if (!motor_active) {
        log_message(LOG_INFO, "Starting motor");
        gpioWrite(MOTOR_ENA_PIN, 1);
        gpioWrite(MOTOR_IN1_PIN, 1);
        gpioWrite(MOTOR_IN2_PIN, 0);
        motor_active = 1;
    }
}

// Function to stop the motor
void stop_motor() {
    if (motor_active) {
        log_message(LOG_INFO, "Stopping motor");
        gpioWrite(MOTOR_ENA_PIN, 0);
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 0);
        motor_active = 0;
    }
}

// Function to perform debouncing check
void debounce_check() {
    if (read_rain_sensor() == 1) {
        dry_count++;
        if (dry_count >= DEBOUNCE_TIME_MS / POLL_INTERVAL_MS) {
            log_message(LOG_INFO, "Debounced: Sensor dry for 600ms");
            stop_motor();
            dry_count = 0; // Reset dry count after debouncing
        }
    } else {
        dry_count = 0; // Reset dry count if sensor is wet
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_message(LOG_INFO, "Received signal, shutting down...");
    stop_motor();
    gpioTerminate();
    closelog();
    exit(0);
}

// Function to log messages using syslog
void log_message(int priority, const char *message) {
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, message);
    closelog();
}

