    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    log_message(LOG_INFO, "Rain-activated window controller started");

    // Main loop
    while (running) {
        int sensor_value = read_rain_sensor();
        log_message(LOG_INFO, "Sensor value: %d", sensor_value);

        if (sensor_value == 0) {
            // Rain detected
            if (!motor_active) {
                start_motor();
            }
        } else {
            // No rain detected
            debounce_check();
            if (motor_active && dry_count >= DEBOUNCE_TIME_MS / POLL_INTERVAL_MS) {
                stop_motor();
            }
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // Delay for 200ms
    }

    return 0;
}

