#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define servo pulse widths
#define LOCK_PULSE_WIDTH 2000
#define UNLOCK_PULSE_WIDTH 1000

// Define debounce delay (in milliseconds)
#define DEBOUNCE_DELAY 50

// Global variable to track servo position
int servo_position = 0;

// Function prototypes
int initialize_gpio();
void lock_servo();
void unlock_servo();
void handle_button_press(int gpio_pin);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    // Stop the servo
    gpioServo(SERVO_PIN, 0);
    // Terminate pigpio
    gpioTerminate();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set servo pin as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set button pins as input with pull-up resistors
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);

    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    return 0; // Indicate success
}

// Lock the servo
void lock_servo() {
    printf("Locking servo...\n");
    if (gpioServo(SERVO_PIN, LOCK_PULSE_WIDTH) != 0) {
        fprintf(stderr, "Error setting servo pulse width for lock\n");
    }
    servo_position = 1; // Update servo position
}

// Unlock the servo
void unlock_servo() {
    printf("Unlocking servo...\n");
    if (gpioServo(SERVO_PIN, UNLOCK_PULSE_WIDTH) != 0) {
        fprintf(stderr, "Error setting servo pulse width for unlock\n");
    }
    servo_position = 0; // Update servo position
}

// Handle button press
void handle_button_press(int gpio_pin) {
    int current_state = gpioRead(gpio_pin);
    int last_state = current_state;
    int debounce_count = 0;

    // Debounce loop
    while (current_state == 0 && debounce_count < DEBOUNCE_DELAY) {
