#define LOG_FILE "security_log.txt"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int control_relay(int state);
int log_event(const char *event_type, const char *message);
void signal_handler(int signal);

