#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Define constants
#define RELAY_GPIO 17
#define MPR121_ADDR 0x5A
#define I2C_BUS 1
#define MHD_REG 0x2B
#define NHD_REG 0x2C
#define NCL_REG 0x2D
#define FDL_REG 0x2E
#define DEBOUNCE_REG 0x5B
#define FFI_REG 0x2C
#define SFI_REG 0x2D
#define CDT_REG 0x2E
#define ELE_EN_REG 0x5E
#define TOUCH_STATUS_REG 0x00

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init(int i2c_handle);
int read_touch_status(int i2c_handle);
void toggle_relay(int gpio_pin);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// MPR121 initialization function
int mpr121_init(int i2c_handle) {
    int status;

    // Soft reset
    status = i2cWriteByteData(i2c_handle, 0x80, 0x63); // Reset command
    if (status < 0) {
        fprintf(stderr, "Error: Soft reset failed (I2C error): %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10000); // Wait for reset to complete

    // Configure baseline filtering
    status = i2cWriteByteData(i2c_handle, MHD_REG, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error: MHD config failed (I2C error): %s\n", strerror(errno));
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, NHD_REG, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error: NHD config failed (I2C error): %s\n", strerror(errno));
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, NCL_REG, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error: NCL config failed (I2C error): %s\n", strerror(errno));
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, FDL_REG, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error: FDL config failed (I2C error): %s\n", strerror(errno));
        return -1;
    }

    // Set debounce
    status = i2cWriteByteData(i2c_handle, DEBOUNCE_REG, 0x10); // Debounce value
    if (status < 0) {
        fprintf(stderr, "Error: Debounce config failed (I2C error): %s\n", strerror(errno));
        return -1;
    }

    // Set FFI/SFI/CDT
    status = i2cWriteByteData(i2c_handle, FFI_REG, 0x05); // FFI
    if (status < 0) {
        fprintf(stderr, "Error: FFI config failed (I2C error): %s\n", strerror(errno));
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, SFI_REG, 0x05); // SFI
    if (status < 0) {
        fprintf(stderr, "Error: SFI config failed (I2C error): %s\n", strerror(errno));
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, CDT_REG, 0x05); // CDT
    if (status < 0) {
        fprintf(stderr, "Error: CDT config failed (I2C error): %s\n", strerror(errno));
        return -1;
    }

    // Enable exactly 12 electrodes
    status = i2cWriteByteData(i2c_handle, ELE_EN_REG, 0x0C); // Enable electrodes 0-11
    if (status < 0) {
        fprintf(stderr, "Error: Electrode enable config failed (I2C error): %s\n", strerror(errno));
        return -1;
    }

    // Auto-configuration
    status = i2cWriteByteData(i2c_handle, 0x7B, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error: Auto-config 0x7B failed (I2C error): %s\n", strerror(errno));
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, 0x7C, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error: Auto-config 0x7C failed (I2C error): %s\n", strerror(errno));
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, 0x7D, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error: Auto-config 0x7D failed (I2C error): %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read touch status function
int read_touch_status(int i2c_handle) {
    int status;
    unsigned char buffer[2];

    status = i2cReadI2CBlockData(i2c_handle, TOUCH_STATUS_REG, (char *)buffer, 2);
    if (status < 0) {
        fprintf(stderr, "Error: Touch status read failed (I2C error): %s\n", strerror(errno));
        return -1;
    }

    return ((unsigned int)buffer[1] << 8) | buffer[0];
}

// Toggle relay function
void toggle_relay(int gpio_pin) {
    int current_level = gpioRead(gpio_pin);
    gpioWrite(gpio_pin, !current_level);
}

int main() {
    int touch_status;
    int last_touch_status = 0;
    int debounce_counter = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to OFF state

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("MPR121 and Relay control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        touch_status = read_touch_status(i2c_handle);
        if (touch_status < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            gpioDelay(100000); // Wait before retrying
            continue;
        }

        // Check for rising edge on electrode 0
        if (touch_status & (1 << 0)) {
            debounce_counter = 200; // Start debounce timer
        }

        if (debounce_counter > 0) {
            debounce_counter--;
        } else {
            // No rising edge detected or debounce complete
            if ((touch_status & (1 << 0)) && !(last_touch_status & (1 << 0))) {
                toggle_relay(RELAY_GPIO);
                printf("Relay toggled!\n");
            }
        }

        last_touch_status = touch_status;
        gpioDelay(10000); // Delay for 10ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is OFF on exit
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

