#include <pthread.h>
#include <errno.h>
#include <gpiod.h>
#include <stdarg.h>

// Configuration
#define SERVO_GPIO 17
#define PIR_GPIO 4
#define PORT 5000
#define PWM_FREQUENCY 50 // Hz
#define PWM_PERIOD_US (1000000 / PWM_FREQUENCY) // Period in microseconds
#define SERVO_MIN_PULSE_WIDTH 1000 // us
#define SERVO_MAX_PULSE_WIDTH 2000 // us
#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180
#define LOG_FILE "security.log"

// Global variables (minimize usage)
static volatile int running = 1;
static int server_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *servo_line = NULL;
static struct gpiod_line *pir_line = NULL;

// Function prototypes
void signal_handler(int sig);
int setup_gpio(void);
int setup_socket(void);
void *servo_control_thread(void *arg);
int parse_command(const char *command, int *angle);
int set_servo_angle(int angle);
int read_pir_sensor(void);
void log_event(const char *format, ...);
void log_error(const char *format, ...);

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        running = 0;
        log_event("Received signal %d, shutting down...", sig);
    }
}

// Setup GPIO
int setup_gpio(void) {
    char chipname[20];
    snprintf(chipname, sizeof(chipname), "gpiochip0");

    chip = gpiod_chip_open_by_name(chipname);
    if (!chip) {
        log_error("Failed to open GPIO chip: %s", chipname);
        return -1;
    }

    servo_line = gpiod_chip_get_line(chip, SERVO_GPIO);
    if (!servo_line) {
        log_error("Failed to get servo GPIO line: %d", SERVO_GPIO);
        gpiod_chip_close(chip);
        return -1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_GPIO);
    if (!pir_line) {
        log_error("Failed to get PIR GPIO line: %d", PIR_GPIO);
        gpiod_chip_close(chip);
        gpiod_line_release(servo_line);
        return -1;
    }

    if (gpiod_line_request_output(servo_line, "servo_control", 0) < 0) {
        log_error("Failed to request servo GPIO line for output");
        gpiod_line_release(pir_line);
        gpiod_line_release(servo_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(pir_line, "pir_sensor") < 0) {
        log_error("Failed to request PIR GPIO line for input");
        gpiod_line_release(pir_line);
        gpiod_line_release(servo_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Setup socket
int setup_socket(void) {
    struct sockaddr_in address;
    int opt = 1;

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        log_error("Socket creation failed");
        return -1;
    }

    // Forcefully attaching socket to the port 5000
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        log_error("setsockopt failed");
        close(server_fd);
        return -1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Forcefully attaching socket to the port 5000
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_error("Bind failed");
        close(server_fd);
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        log_error("Listen failed");
        close(server_fd);
        return -1;
    }
    log_event("Listening on port %d", PORT);

    return 0;
}

// Servo control thread
void *servo_control_thread(void *arg) {
    int angle = 90; // Initial angle
    int client_fd;
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    char buffer[1024] = {0};
    int pulse_width;
    struct timespec ts;

    while (running) {
        if ((client_fd = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            log_error("Accept failed");
            continue; // Continue listening
        }

        log_event("Client connected");

        while (running) {
            ssize_t bytes_received = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
            if (bytes_received < 0) {
                log_error("Receive failed");
                break;
            }
            buffer[bytes_received] = '\0';

            if (strncmp(buffer, "SERVO", 5) == 0) {
                int new_angle;
                if (parse_command(buffer, &new_angle) == 0) {
                    if (set_servo_angle(new_angle) == 0) {
                        char response[100];
                        snprintf(response, sizeof(response), "SERVO: %d", new_angle);
                        send(client_fd, response, strlen(response), 0);
                        log_event("Servo angle set to %d", new_angle);
                    } else {
                        log_error("Failed to set servo angle");
                        send(client_fd, "SERVO: FAILURE", strlen("SERVO: FAILURE"), 0);
                    }
                } else {
                    log_error("Invalid command format");
                    send(client_fd, "Invalid command", strlen("Invalid command"), 0);
                }
            } else if (strcmp(buffer, "PIR") == 0) {
                int pir_value = read_pir_sensor();
                char response[50];
                snprintf(response, sizeof(response), "PIR: %d", pir_value);
                send(client_fd, response, strlen(response), 0);
                log_event("PIR sensor read: %d", pir_value);
            } else {
                log_error("Unknown command");
                send(client_fd, "Unknown command", strlen("Unknown command"), 0);
            }

            usleep(100000); // Small delay to prevent busy-waiting
        }

        close(client_fd);
        log_event("Client disconnected");
    }

    pthread_exit(NULL);
}

// Parse command
int parse_command(const char *command, int *angle) {
    if (strncmp(command, "SERVO", 5) == 0) {
        if (sscanf(command, "SERVO %d", angle) == 1) {
            if (*angle >= SERVO_MIN_ANGLE && *angle <= SERVO_MAX_ANGLE) {
                return 0;
            } else {
                log_error("Angle out of range (0-180)");
                return -1;
            }
        } else {
            log_error("Invalid angle format");
            return -1;
        }
    } else {
        return -1;
    }
}

// Set servo angle
int set_servo_angle(int angle) {
    if (angle < SERVO_MIN_ANGLE) {
        angle = SERVO_MIN_ANGLE;
    } else if (angle > SERVO_MAX_ANGLE) {
        angle = SERVO_MAX_ANGLE;
    }

    pulse_width = SERVO_MIN_PULSE_WIDTH + (int)(((float)(angle - SERVO_MIN_ANGLE) / (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE)) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));

    // Toggle the line with the calculated pulse width
    gpiod_line_set_value(servo_line, 1);
    usleep(pulse_width);
    gpiod_line_set_value(servo_line, 0);
    usleep(PWM_PERIOD_US - pulse_width);

    return 0;
}

// Read PIR sensor
int read_pir_sensor(void) {
    int value = gpiod_line_get_value(pir_line);
    if (value < 0) {
        log_error("Failed to read PIR sensor value");
        return -1; // Indicate error
    }
    return value;
}

// Log event
void log_event(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vsyslog(LOG_USER, format, args);
    va_end(args);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] ", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec);
        va_list args2;
        va_start(args2, format);
        vfprintf(fp, format, args2);
        va_end(args2);
        fclose(fp);
    }
}

// Log error
void log_error(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vsyslog(LOG_ERR, format, args);
    va_end(args);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] ERROR: ", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec);
        va_list args2;
        va_start(args2, format);
        vfprintf(fp, format, args2);
        va_end(args2);
        fclose(fp);
    }
}

int main(void) {
    // Initialize syslog
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (setup_gpio() < 0) {
        log_error("GPIO setup failed, exiting");
        closelog();
        return 1;
    }

    // Set up socket
    if (setup_socket() < 0) {
        log_error("Socket setup failed, exiting");
        gpiod_line_release(servo_line);
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        closelog();
        return 1;
    }

    // Create servo control thread
    pthread_t servo_thread;
    if (pthread_create(&servo_thread, NULL, servo_control_thread, NULL) != 0) {
        log_error("Failed to create servo control thread");
        close(server_fd);
        gpiod_line_release(servo_line);
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        closelog();
        return 1;
    }

    // Main loop (wait for signals)
    while (running) {
        sleep(1);
    }

    // Cleanup
    pthread_join(servo_thread, NULL);
    close(server_fd);
    gpiod_line_release(servo_line);
    gpiod_line_release(pir_line);
    gpiod_chip_close(chip);
    closelog();

    return 0;
}

