#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_S 2

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int init_logging();
int read_bh1750(float *lux);
int control_relay(int state);
int log_data(float lux);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is off initially
    return 0;
}

// Initialize logging
int init_logging() {
    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }
    return 0;
}

// Read BH1750 sensor
int read_bh1750(float *lux) {
    char config_cmd = 0x20; // One-Time High-Resolution Mode
    char buffer[2];
    int retry = 0;

    while (retry < I2C_RETRY_COUNT) {
        if (i2cWriteByte(i2c_handle, config_cmd) != 0) {
            fprintf(stderr, "Error writing config command: %d\n", i2c_handle);
            retry++;
            gpioDelay(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
