#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <getopt.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins
#define HX711_DOUT 23
#define HX711_SCK 24
#define SOLENOID_PIN 25

// Default values
#define DEFAULT_THRESHOLD 1000.0
#define DEFAULT_SCALE 1000.0
#define DEFAULT_DURATION 200

// Global variables
static volatile int running = 1;
static int tare_offset = 0.0;
static float scale = DEFAULT_SCALE;
static int threshold = DEFAULT_THRESHOLD;
static int solenoid_duration = DEFAULT_DURATION;
static int num_readings = 5;
static int retry_count = 0;
static int retry_limit = 3;

// Function prototypes
int read_hx711();
float calculate_weight(int raw_value, float tare_offset, float scale);
void control_solenoid(int state);
void tare_load_cell();
void signal_handler(int signal);
void log_message(int priority, const char *message);
void cleanup();

// HX711 read function
int read_hx711() {
    int data = 0;
    int i;

    // Wait for DOUT to go LOW
    int timeout_count = 0;
    while (gpioRead(HX711_DOUT) == 1 && timeout_count < 1000) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        timeout_count++;
    }

    if (timeout_count >= 1000) {
        log_message(LOG_ERR, "Timeout waiting for HX711 data ready.");
        return -1; // Indicate error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(HX711_DOUT)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Small delay
    }

    // Send one additional clock pulse to select Channel A / Gain 128
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Small delay

    // Convert to signed 32-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Weight calculation function
float calculate_weight(int raw_value, float tare_offset, float scale) {
    return (float)(raw_value - tare_offset) / scale;
}

// Solenoid control function
void control_solenoid(int state) {
    gpioWrite(SOLENOID_PIN, state);
    log_message(LOG_INFO, "Solenoid set to state: " (state ? "HIGH" : "LOW"));
}

// Tare load cell function
void tare_load_cell() {
    int i, raw_value;
    float sum = 0.0;

    log_message(LOG_INFO, "Starting tare procedure...");

    for (i = 0; i < 10; i++) {
        raw_value = read_hx711();
        if (raw_value == -1) {
            log_message(LOG_ERR, "Error reading HX711 during tare.");
            return;
        }
        sum += raw_value;
        gpioDelay(100); // Small delay between readings
    }

    tare_offset = sum / 10.0;
    log_message(LOG_INFO, "Tare offset set to: " tare_offset);
}

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    log_message(LOG_INFO, "Signal received, exiting...");
}

// Logging function
void log_message(int priority, const char *message) {
    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, message);
    closelog();
}

// Cleanup function
void cleanup() {
    log_message(LOG_INFO, "Cleaning up...");
    control_solenoid(0); // Ensure solenoid is off
    gpioTerminate();
    log_message(LOG_INFO, "pigpio terminated.");
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:s:d:n:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 's':
                scale = atof(optarg);
                break;
            case 'd':
                solenoid_duration = atoi(optarg);
                break;
            case 'n':
                num_readings = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-s scale] [-d duration] [-n num_readings]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HX711_DOUT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Set initial solenoid state to LOW
    control_solenoid(0);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Perform startup tare
    tare_load_cell();

    // Main loop
    while (running) {
        int raw_value;
        float weight;
        int sum = 0;
        int count = 0;

        // Average multiple readings
        for (int i = 0; i < num_readings; i++) {
            raw_value = read_hx711();
            if (raw_value == -1) {
                log_message(LOG_ERR, "Error reading HX711, retrying...");
                retry_count++;
                if (retry_count > retry_limit) {
                    log_message(LOG_ERR, "Max retries reached, exiting.");
                    running = 0;
                    break;
                }
                gpioDelay(100); // Small delay before retry
                continue; // Skip to the next iteration of the loop
            }
            sum += raw_value;
            count++;
        }

        if (count > 0) {
            weight = calculate_weight(sum / count, tare_offset, scale);
            char log_buffer[100];
            snprintf(log_buffer, sizeof(log_buffer), "Weight: %.2f grams", weight);
            log_message(LOG_INFO, log_buffer);

            // Control solenoid if weight exceeds threshold
            if (weight > threshold) {
                control_solenoid(1);
                gpioDelay(solenoid_duration);
                control_solenoid(0);
            }
        } else {
            log_message(LOG_ERR, "No valid readings, skipping weight calculation.");
        }

        gpioDelay(500); // Poll every 500 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

