#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <mosquitto.h>
#include <pigpio.h>

#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define GPIO_PIN 17
#define KEEP_ALIVE 60
#define QOS 0

static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize relay to OFF
    syslog(LOG_INFO, "pigpio initialised and GPIO %d set to output", GPIO_PIN);
    return 0;
}

// Function to connect to the MQTT broker
int connect_mqtt(struct mosquitto **mosq_ptr) {
    mosquitto_lib_init();
    *mosq_ptr = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!*mosq_ptr) {
        syslog(LOG_ERR, "Failed to create mosquitto instance");
        return -1;
    }

    mosquitto_connect_callback_set(*mosq_ptr, NULL);
    mosquitto_message_callback_set(*mosq_ptr, NULL);
    mosquitto_subscribe_callback_set(*mosq_ptr, NULL);
    mosquitto_disconnect_callback_set(*mosq_ptr, NULL);
    mosquitto_error_return_callback_set(*mosq_ptr, NULL);

    int rc = mosquitto_connect(*mosq_ptr, MQTT_HOST, MQTT_PORT, KEEP_ALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        mosquitto_destroy(*mosq_ptr);
        mosquitto_lib_cleanup();
        return -1;
    }

    syslog(LOG_INFO, "Connected to MQTT broker");
    return 0;
}

// Function to subscribe to the MQTT topic
int subscribe_mqtt(struct mosquitto *mosq_ptr, const char *topic) {
    int rc = mosquitto_subscribe(mosq_ptr, NULL, topic, QOS);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to subscribe to topic: %s", mosquitto_strerror(rc));
        return -1;
    }
    syslog(LOG_INFO, "Subscribed to topic: %s", topic);
    return 0;
}

// Function to handle MQTT messages
void message_callback(struct mosquitto *mosq_ptr, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char payload[message->payloadlen + 1];
        strncpy(payload, message->payload, message->payloadlen);
        payload[message->payloadlen] = '\0';
        syslog(LOG_INFO, "Received message on topic %s: %s", message->topic, payload);

        if (strcmp(payload, "ON") == 0) {
            gpioWrite(GPIO_PIN, 1);
            syslog(LOG_INFO, "Relay ON");
        } else if (strcmp(payload, "OFF") == 0) {
