    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize relay to OFF
    syslog(LOG_INFO, "pigpio initialised and GPIO %d set to output", GPIO_PIN);
    return 0;
}

