    gpioSetPWMrange(SERVO4, PWM_RANGE);
    gpioSetPWMfrequency(SERVO5, PWM_FREQUENCY);
    gpioSetPWMrange(SERVO5, PWM_RANGE);

    // Set servo positions
    gpioPWM(SERVO1, 1000);
    gpioPWM(SERVO2, 1500);
    gpioPWM(SERVO3, 2000);
    gpioPWM(SERVO4, 500);
    gpioPWM(SERVO5, 2500);

    // Hold for 3 seconds
    sleep(3);

    // Stop PWM and terminate pigpio
