    gpioPWM(SERVO2, 0);
    gpioPWM(SERVO3, 0);
    gpioPWM(SERVO4, 0);
    gpioPWM(SERVO5, 0);

    gpioTerminate();

    printf("Servo control program finished.\n");
    return 0;
}

