#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Motor A
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_A_PWM 17 // IN1 is PWM

// Motor B
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23
#define MOTOR_B_PWM 22 // IN3 is PWM

// Encoder A
#define ENCODER_A_A 4
#define ENCODER_A_B 5

// Encoder B
#define ENCODER_B_A 6
#define ENCODER_B_B 12

// PWM Frequency
#define PWM_FREQUENCY 10000 // 10 kHz

// Target Speed (RPM)
#define TARGET_SPEED 50.0

// PI Controller Gains
#define Kp 0.5
#define Ki 0.05

// Anti-windup limits
#define PWM_MIN 0
#define PWM_MAX 255

// Encoder Stall Timeout (seconds)
#define STALL_TIMEOUT 2

// Global Variables
volatile int encoder_a_ticks = 0;
volatile int encoder_b_ticks = 0;

// PI Controller Variables
double integral = 0.0;
double last_error = 0.0;

// Function Prototypes
void motor_a_forward(int speed);
void motor_b_forward(int speed);
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user);
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_rpm(int ticks);
double pi_controller(double target_speed, double current_speed, double *integral, double last_error);
void signal_handler(int signal);

// Motor Control Functions
void motor_a_forward(int speed) {
    gpioWrite(MOTOR_A_IN1, 1);
    gpioPWM(MOTOR_A_PWM, speed);
    gpioWrite(MOTOR_A_IN2, 0);
}

void motor_b_forward(int speed) {
    gpioWrite(MOTOR_B_IN3, 1);
    gpioPWM(MOTOR_B_PWM, speed);
    gpioWrite(MOTOR_B_IN4, 0);
}

// Encoder ISR Functions
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    if (gpioRead(ENCODER_A_B) == 0) { // A-phase low, B-phase high
        encoder_a_ticks++;
    }
}

void encoder_b_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    if (gpioRead(ENCODER_B_A) == 0) { // A-phase low, B-phase high
        encoder_b_ticks++;
    }
}

// RPM Calculation Function
double calculate_rpm(int ticks) {
    // Assuming 64 ticks per revolution
    return (double)ticks / 64.0 * 60.0;
}

// PI Controller Function
double pi_controller(double target_speed, double current_speed, double *integral, double last_error) {
    double error = target_speed - current_speed;
    *integral += error;
    double output = Kp * error + Ki * (*integral);

    // Anti-windup
    if (output > PWM_MAX) {
        output = PWM_MAX;
    } else if (output < PWM_MIN) {
        output = PWM_MIN;
    }

    return output;
}

// Signal Handler Function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    motor_a_forward(0);
    motor_b_forward(0);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_A_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);
    gpioSetMode(MOTOR_B_PWM, PI_OUTPUT);
    gpioSetMode(ENCODER_A_A, PI_INPUT);
    gpioSetMode(ENCODER_A_B, PI_INPUT);
    gpioSetMode(ENCODER_B_A, PI_INPUT);
    gpioSetMode(ENCODER_B_B, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_PWM, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_PWM, PWM_FREQUENCY);

    // Set ISR functions
    gpioSetISRFuncEx(ENCODER_A_A, RISING_EDGE, 0, encoder_a_isr, NULL);
    gpioSetISRFuncEx(ENCODER_B_A, RISING_EDGE, 0, encoder_b_isr, NULL);

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize encoder ticks
    encoder_a_ticks = 0;
    encoder_b_ticks = 0;
    integral = 0.0;
    last_error = 0.0;

    // Main loop
    while (1) {
        // Read encoder ticks
        int current_a_ticks = encoder_a_ticks;
        int current_b_ticks = encoder_b_ticks;

        // Calculate RPM
        double rpm_a = calculate_rpm(current_a_ticks);
        double rpm_b = calculate_rpm(current_b_ticks);

        // Calculate average RPM
        double average_rpm = (rpm_a + rpm_b) / 2.0;

        // PI Controller
        double pid_output = pi_controller(TARGET_SPEED, average_rpm, &integral, last_error);

        // Motor control
        motor_a_forward((int)pid_output);
        motor_b_forward((int)pid_output);

        // Stall detection
        time_t start_time = time(NULL);
        while (current_a_ticks == 0 && current_b_ticks == 0) {
            time_t current_time = time(NULL);
            if (difftime(current_time, start_time) > STALL_TIMEOUT) {
                fprintf(stderr, "Warning: Stall detected on both motors!\n");
                break;
            }
            gpioDelay(1000); // Check every 1 ms
        }

        // Print RPM and PWM duty cycle
        printf("Motor A RPM: %.2f, Motor B RPM: %.2f, PWM: %d\n", rpm_a, rpm_b, (int)pid_output);

        // Update last error
        last_error = TARGET_SPEED - average_rpm;

        // Wait for 100 ms
        gpioDelay(100000); // 100 ms
    }

    return 0;
}

