#define LUX_THRESHOLD_DUSK 50
#define LUX_THRESHOLD_DAWN 200
#define HYSTERESIS_DELAY 180 // milliseconds
#define POLL_INTERVAL 5       // seconds
#define LOG_FILE "chicken_coop_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_lux();
void control_relay(int state);
void log_data(int lux, int relay_state);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is off initially
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read lux value from BH1750 sensor
int read_lux() {
    char cmd = 0x21; // High Resolution Mode 2
    char buf[2];
    int lux = -1; // Default to error value

    if (i2cWriteByte(i2c_handle, cmd) != 0) {
        fprintf(stderr, "I2C write failed\n");
        return -1;
    }

    gpioDelay(HYSTERESIS_DELAY * 1000); // Delay in microseconds

    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "I2C read failed\n");
        return -1;
    }

    lux = (buf[0] << 8 | buf[1]) / 1.2;
    return lux;
}

// Control the relay
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Log data to file
void log_data(int lux, int relay_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: Lux = %d, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    control_relay(0); // Turn off relay
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    int relay_state = 0; // 0 = off, 1 = on
    int lux;

    printf("Chicken coop lighting system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        lux = read_lux();
        if (lux < 0) {
            fprintf(stderr, "Error reading lux value, turning off relay and logging error.\n");
            log_data(-1, 0); // Log error
            control_relay(0);
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        log_data(lux, relay_state);

        if (lux < LUX_THRESHOLD_DUSK && !relay_state) {
            control_relay(1);
            relay_state = 1;
            printf("Dusk, turning on relay.\n");
        } else if (lux > LUX_THRESHOLD_DAWN && relay_state) {
            control_relay(0);
            relay_state = 0;
            printf("Dawn, turning off relay.\n");
        }

        gpioDelay(POLL_INTERVAL * 1000000); // Delay in microseconds
    }

    cleanup();
    return 0;
}

