#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TOUCH_SENSOR_GPIO 4
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY_MS 50

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int result;
    int relay_state = 0; // 0 = OFF, 1 = ON
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO 4 as input
    result = gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT);
    if (result != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %d\n", TOUCH_SENSOR_GPIO, result);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO 17 as output
    result = gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %d\n", RELAY_GPIO, result);
        gpioTerminate();
        return 1;
    }

    // Set initial relay state to OFF
    gpioWrite(RELAY_GPIO, 0);
    relay_state = 0;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read touch sensor
        int touch_detected = gpioRead(TOUCH_SENSOR_GPIO);

        // Debouncing and state change logic
        if (touch_detected == 1) {
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Delay for 50ms
            if (gpioRead(TOUCH_SENSOR_GPIO) == 1) {
                // Toggle relay state
                relay_state = !relay_state;
                gpioWrite(RELAY_GPIO, relay_state);

                // Get current timestamp
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

                // Log relay state change
                printf("%s Relay is now %s\n", timestamp, relay_state ? "ON" : "OFF");

                // Wait for touch sensor to return LOW before next toggle
                while (gpioRead(TOUCH_SENSOR_GPIO) == 1 && program_running) {
                    gpioDelay(1000); // Check every 1ms
                }
            }
        }

        // Small delay to reduce CPU usage
        gpioDelay(10000); // 10ms
    }

    // Turn relay OFF before exiting
    gpioWrite(RELAY_GPIO, 0);

    // Release pigpio resources
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

