#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO 27
#define PULSES_PER_LITER 450.0
#define LPM_THRESHOLD_HIGH 5.0
#define LPM_THRESHOLD_LOW 4.5
#define SAMPLE_INTERVAL_SEC 1
#define DEBOUNCE_TIMEOUT_US 1000 // 1 ms
#define PULSE_COUNT_MAX 1000000 // Maximum pulse count to prevent overflow

// Global variables
volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
double lpm = 0.0;
int solenoid_state = 1; // 1 = open, 0 = closed
FILE *log_file = NULL;

// Function prototypes
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data);
double calculate_lpm(int pulses);
void control_solenoid(double lpm);
void log_data(double lpm, int solenoid_state);
void signal_handler(int signal);

// Interrupt service routine for the flow sensor
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data)
{
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused

    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    if (pulse_count > PULSE_COUNT_MAX) {
        pulse_count = PULSE_COUNT_MAX; // Prevent overflow
    }
    pthread_mutex_unlock(&pulse_mutex);
}

// Function to calculate LPM from pulse count
double calculate_lpm(int pulses)
{
    return (double)pulses / PULSES_PER_LITER * 60.0;
}

// Function to control the solenoid valve
void control_solenoid(double lpm)
{
    if (lpm > LPM_THRESHOLD_HIGH && solenoid_state == 1)
    {
        gpioWrite(SOLENOID_GPIO, 0); // Close the valve
        solenoid_state = 0;
        printf("Solenoid closed (LPM: %.2f)\n", lpm);
    }
    else if (lpm < LPM_THRESHOLD_LOW && solenoid_state == 0)
    {
        gpioWrite(SOLENOID_GPIO, 1); // Open the valve
        solenoid_state = 1;
        printf("Solenoid opened (LPM: %.2f)\n", lpm);
    }
}

// Function to log data to a file
void log_data(double lpm, int solenoid_state)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL)
    {
        fprintf(log_file, "%s, LPM: %.2f, Solenoid: %s\n", timestamp, lpm, solenoid_state ? "OPEN" : "CLOSED");
        fflush(log_file); // Ensure data is written to disk immediately
    }
    else
    {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close the solenoid valve
    gpioWrite(SOLENOID_GPIO, 1); // Open the valve

    // Close the log file
    if (log_file != NULL)
    {
        fclose(log_file);
    }

    // Destroy the mutex
    pthread_mutex_destroy(&pulse_mutex);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0)
    {
        fprintf(stderr, "Failed to set FLOW_SENSOR_GPIO to input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SOLENOID_GPIO, PI_OUTPUT) != 0)
    {
        fprintf(stderr, "Failed to set SOLENOID_GPIO to output\n");
        gpioTerminate();
        return 1;
    }

    // Set up interrupt service routine
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, DEBOUNCE_TIMEOUT_US, flow_sensor_isr, NULL) != 0)
    {
        fprintf(stderr, "Failed to set up ISR\n");
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("water_flow.log", "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1)
    {
        // Sample the pulse count
        int pulses = 0;
        pthread_mutex_lock(&pulse_mutex);
        pulses = pulse_count;
        pulse_count = 0; // Reset the pulse count
        pthread_mutex_unlock(&pulse_mutex);

        // Calculate LPM
        lpm = calculate_lpm(pulses);

        // Control the solenoid valve
        control_solenoid(lpm);

        // Log the data
        log_data(lpm, solenoid_state);

        // Wait for the next sample interval
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Convert seconds to microseconds
    }

    return 0;
}

