#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <errno.h>

// Configuration file path
#define CONFIG_FILE "config.ini"

// Default values
#define DEFAULT_CALIBRATION_FACTOR 1000.0
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT 12345
#define DEFAULT_SERVO_MIN_PULSE_WIDTH 1000
#define DEFAULT_SERVO_MAX_PULSE_WIDTH 2000

// HX711 GPIO pins
#define HX711_DATA_PIN 23
#define HX711_CLOCK_PIN 24

// Servo GPIO pin
#define SERVO_PIN 18

// Timeout settings
#define HX711_TIMEOUT_ATTEMPTS 1000
#define HX711_TIMEOUT_US 1000 // 1 ms

// Global variables
static volatile int running = 1;
static int calibration_factor = DEFAULT_CALIBRATION_FACTOR;
static char server_ip[INET_ADDRSTRLEN] = DEFAULT_SERVER_IP;
static int server_port = DEFAULT_SERVER_PORT;
static int servo_min_pulse_width = DEFAULT_SERVO_MIN_PULSE_WIDTH;
static int servo_max_pulse_width = DEFAULT_SERVO_MAX_PULSE_WIDTH;
static int socket_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int read_config(const char *filename);
int read_hx711(int data_pin, int clock_pin);
double calibrate_weight(int raw_value, double calibration_factor);
int set_servo_pulse_width(int gpio_pin, int pulse_width_us);
int map_weight_to_pulse_width(double target_weight, int servo_min_pulse_width, int servo_max_pulse_width);
int handle_client(int client_socket);
void log_dispensing_event(double target_weight, double actual_weight, const char *error_message);
void signal_handler(int signal);

// HX711 read function
int read_hx711(int data_pin, int clock_pin) {
    int i;
    int data = 0;

    gpioSetMode(data_pin, PI_INPUT);
    gpioSetMode(clock_pin, PI_OUTPUT);

    // Wait for DOUT to go low
    int timeout_counter = 0;
    while (gpioRead(data_pin) == 1 && timeout_counter < HX711_TIMEOUT_ATTEMPTS) {
        gpioDelay(1); // Wait 1 us
        timeout_counter++;
    }

    if (timeout_counter >= HX711_TIMEOUT_ATTEMPTS) {
        fprintf(stderr, "HX711 timeout error: DOUT pin stuck high\n");
        return -1; // Indicate timeout error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1); // Clock pulse width
        data = data << 1;
        if (gpioRead(data_pin)) {
            data++;
        }
        gpioWrite(clock_pin, 0);
        gpioDelay(1); // Clock pulse width
    }

    // 25th pulse for gain setting (channel A, gain 128)
    gpioWrite(clock_pin, 1);
    gpioDelay(1); // Clock pulse width
    gpioWrite(clock_pin, 0);
    gpioDelay(1); // Clock pulse width

    data = data ^ 0x800000; // Convert to signed 2's complement

    return data;
}

// Calibration function
double calibrate_weight(int raw_value, double calibration_factor) {
    return (double)raw_value / calibration_factor;
}

// Servo control function
int set_servo_pulse_width(int gpio_pin, int pulse_width_us) {
    if (pulse_width_us < servo_min_pulse_width || pulse_width_us > servo_max_pulse_width) {
        fprintf(stderr, "Error: Pulse width out of range (%d - %d)\n", servo_min_pulse_width, servo_max_pulse_width);
        return -1;
    }

    gpioServo(gpio_pin, pulse_width_us);
    return 0;
}

// Weight mapping function
int map_weight_to_pulse_width(double target_weight, int servo_min_pulse_width, int servo_max_pulse_width) {
    if (target_weight <= 0) {
        return servo_min_pulse_width; // Min pulse width if weight is zero or negative
    }

    if (target_weight >= 1000) {
        return servo_max_pulse_width; // Max pulse width if weight is very high
    }

    // Linear mapping
    return (int)((target_weight / 1000.0) * (servo_max_pulse_width - servo_min_pulse_width) + servo_min_pulse_width);
}

// Client handling function
int handle_client(int client_socket) {
    char buffer[1024];
    int read_size;
    double target_weight;
    int raw_value;
    double actual_weight;
    int pulse_width;
    int dispensing_attempts = 0;
    const int max_dispensing_attempts = 5;

    // Receive target weight from client
    read_size = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (read_size < 0) {
        perror("recv failed");
        return -1;
    }
    buffer[read_size] = '\0';
    if (sscanf(buffer, "%lf", &target_weight) != 1) {
        fprintf(stderr, "Invalid target weight received\n");
        return -1;
    }

    // Dispense ingredient
    pulse_width = map_weight_to_pulse_width(target_weight, servo_min_pulse_width, servo_max_pulse_width);
    if (set_servo_pulse_width(SERVO_PIN, pulse_width) != 0) {
        fprintf(stderr, "Failed to set servo pulse width\n");
        return -1;
    }

    // Wait for load cell to stabilize
    time_sleep(1.0);

    // Read actual weight
    raw_value = read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN);
    if (raw_value == -1) {
        fprintf(stderr, "Failed to read HX711 value\n");
        return -1;
    }

    actual_weight = calibrate_weight(raw_value, calibration_factor);

    // Send actual weight back to client
    char response[1024];
    snprintf(response, sizeof(response), "%.2f", actual_weight);
    send(client_socket, response, strlen(response), 0);

    // Log dispensing event
    log_dispensing_event(target_weight, actual_weight, NULL);

    return 0;
}

// Logging function
void log_dispensing_event(double target_weight, double actual_weight, const char *error_message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "{\"timestamp\": \"%s\", \"target_weight\": %.2f, \"actual_weight\": %.2f, \"error\": \"%s\"}\n",
            timestamp, target_weight, actual_weight, error_message);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Read configuration from file
int read_config(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open config file %s, using default values\n", filename);
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Skip comments and empty lines
        if (line[0] == '#' || line[0] == '\0') continue;

        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (key != NULL && value != NULL) {
            if (strcmp(key, "calibration_factor") == 0) {
                calibration_factor = atof(value);
            } else if (strcmp(key, "server_ip") == 0) {
                strncpy(server_ip, value, INET_ADDRSTRLEN - 1);
                server_ip[INET_ADDRSTRLEN - 1] = '\0';
            } else if (strcmp(key, "server_port") == 0) {
                server_port = atoi(value);
            } else if (strcmp(key, "servo_min_pulse_width") == 0) {
                servo_min_pulse_width = atoi(value);
            } else if (strcmp(key, "servo_max_pulse_width") == 0) {
                servo_max_pulse_width = atoi(value);
            }
        }
    }

    fclose(fp);
    return 0;
}

int main() {
    int client_socket;
    struct sockaddr_in server_address, client_address;
    socklen_t client_address_len = sizeof(client_address);

    // Read configuration
    if (read_config(CONFIG_FILE) != 0) {
        fprintf(stderr, "Warning: Failed to read config file, using default values\n");
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("dispensing_log.json", "a");
    if (log_file == NULL) {
        perror("fopen");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd < 0) {
        perror("socket");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Configure server address
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = inet_addr(server_ip);
    server_address.sin_port = htons(server_port);

    // Bind socket to address
    if (bind(socket_fd, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        perror("bind");
        close(socket_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(socket_fd, 5) < 0) {
        perror("listen");
        close(socket_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Listening on %s:%d...\n", server_ip, server_port);

    // Accept connections
    while (running) {
        client_socket = accept(socket_fd, (struct sockaddr *)&client_address, &client_address_len);
        if (client_socket < 0) {
            perror("accept");
            continue; // Continue listening for other connections
        }

        printf("Connection accepted from %s:%d\n", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));

        // Handle client
        if (handle_client(client_socket) != 0) {
            fprintf(stderr, "Error handling client\n");
        }

        // Close client socket
        close(client_socket);
    }

    // Clean up
    close(socket_fd);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting cleanly.\n");
    return 0;
}

