#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Default debounce delay in milliseconds
#define DEFAULT_DEBOUNCE_DELAY 50

// Global variables
static volatile int running = 1;
static int debounce_delay = DEFAULT_DEBOUNCE_DELAY;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void toggle_relay(int state);
void log_relay_state(int state);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function to release resources
void cleanup() {
    gpioWrite(RELAY_PIN, 0); // Turn off the relay
    gpioTerminate();        // Terminate pigpio
    printf("pigpio terminated.\n");
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    return 0; // Indicate success
}

// Read the touch sensor state
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Toggle the relay state
void toggle_relay(int state) {
    gpioWrite(RELAY_PIN, state);
    log_relay_state(state);
}

// Log the relay state with a timestamp
void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (state == 1) {
        printf("%s Relay: ON\n", timestamp);
    } else {
        printf("%s Relay: OFF\n", timestamp);
    }
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        debounce_delay = atoi(argv[1]);
        if (debounce_delay <= 0) {
            fprintf(stderr, "Invalid debounce delay. Using default value (%d ms).\n", DEFAULT_DEBOUNCE_DELAY);
            debounce_delay = DEFAULT_DEBOUNCE_DELAY;
        }
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    int last_touch_state = 0; // Store the last touch sensor state

    printf("Touch-controlled relay switch started. Debounce delay: %d ms\n", debounce_delay);

    // Main loop
    while (running) {
        int current_touch_state = read_touch_sensor();

        // Detect rising edge (LOW to HIGH)
        if (current_touch_state == 1 && last_touch_state == 0) {
            // Debounce delay
            gpioDelay(debounce_delay * 1000); // Convert ms to microseconds

            // Confirm stable HIGH level
            if (read_touch_sensor() == 1) {
                toggle_relay(1); // Turn on the relay
            }
        }

        last_touch_state = current_touch_state;
        gpioDelay(1000); // Check every 1 ms
    }

    return 0;
}

