#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <termios.h>

#define SERVO_PIN 18
#define PWM_FREQUENCY 50
#define PWM_PERIOD_US 20000 // 1/50 Hz
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180

static volatile int running = 1;
static struct termios original_termios;

void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int angle = 90;
    int pulse_width;
    char input;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 to output mode
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(SERVO_PIN, 20000); // Set range to PWM period

    // Save original terminal settings
    if (tcgetattr(STDIN_FILENO, &original_termios) != 0) {
        perror("tcgetattr failed");
        gpioTerminate();
        return 1;
    }

    // Configure terminal for raw input
    struct termios new_termios;
    new_termios = original_termios;
    new_termios.c_lflag &= ~(ICANON | ECHO);
    new_termios.c_iflag &= ~(IXON | IXOFF | IXANY);
    new_termios.c_cflag |= (CLOCAL | CREAD);
    if (tcsetattr(STDIN_FILENO, TCSANOW, &new_termios) != 0) {
        perror("tcsetattr failed");
        gpioTerminate();
        return 1;
    }

    printf("Servo control program. Press '+' or '-' to change angle, 'q' to quit.\n");

    while (running) {
        // Read input without waiting for Enter
        input = getchar();

        switch (input) {
            case '+':
                angle = (angle + 10) > MAX_ANGLE ? MAX_ANGLE : (angle + 10);
                break;
            case '-':
                angle = (angle - 10) < MIN_ANGLE ? MIN_ANGLE : (angle - 10);
                break;
            case 'q':
                running = 0;
                break;
            default:
                // Ignore other inputs
                continue;
        }

        // Calculate pulse width
        pulse_width = (int)(((float)angle / 180.0) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) + MIN_PULSE_WIDTH);

        // Validate pulse width
        if (pulse_width < MIN_PULSE_WIDTH) {
            pulse_width = MIN_PULSE_WIDTH;
        } else if (pulse_width > MAX_PULSE_WIDTH) {
            pulse_width = MAX_PULSE_WIDTH;
        }

        // Set servo pulse width
        gpioServo(SERVO_PIN, pulse_width);

        // Print current angle
        printf("Angle: %d\n", angle);

        // Small delay to avoid busy-waiting
        usleep(10000); // 10 ms
    }

    // Stop PWM and terminate pigpio
    gpioServo(SERVO_PIN, 0); // Stop PWM
    gpioTerminate();

    // Restore terminal settings
    if (tcsetattr(STDIN_FILENO, TCSANOW, &original_termios) != 0) {
        perror("tcsetattr failed");
    }

    return 0;
}

