#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define SAMPLE_INTERVAL_SEC 5
#define DEBOUNCE_WINDOW_NS 2000000 // 2 ms

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile unsigned int pulseCount = 0;
static FILE *logFile = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signalHandler(int signum) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signum);
}

// Function to initialize the GPIO line
int initializeGPIO(struct gpiod_chip *chip, int pin) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "conveyor-belt-monitor";

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", pin, strerror(errno));
        return -1;
    }

    int ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", pin, strerror(errno));
        gpiod_line_release(line);
        return -1;
    }

    // Enable pull-up resistor
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting pull-up resistor on GPIO line %d: %s\n", pin, strerror(errno));
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Function to initialize the log file
int initializeLogFile(const char *filename) {
    logFile = fopen(filename, "a");
    if (!logFile) {
        fprintf(stderr, "Error opening log file %s: %s\n", filename, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read the pulse count and calculate RPM
void readPulseCountAndCalculateRPM(struct gpiod_line *line, unsigned int *pulseCount, float *rpm) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    unsigned long long startTime = ts.tv_sec * 1000000000LL + ts.tv_nsec;

    int ret = gpiod_line_event_wait(line, 0, DEBOUNCE_WINDOW_NS);
    if (ret < 0) {
        fprintf(stderr, "Error waiting for event: %s\n", strerror(errno));
        return;
    }

    struct timespec endTime;
    clock_gettime(CLOCK_MONOTONIC, &endTime);
    unsigned long long endTimeNs = endTime.tv_sec * 1000000000LL + endTime.tv_nsec;

    if ((endTimeNs - startTime) > DEBOUNCE_WINDOW_NS) {
        pulseCount++;
    }
}

// Function to log the RPM data to a file
int logRPMData(FILE *logFile, float rpm) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    int ret = fprintf(logFile, "%s,%.2f\n", buf, rpm);
    if (ret < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(logFile);
    return 0;
}

// Function to print the RPM to stdout
void printRPM(float rpm) {
    printf("RPM: %.2f\n", rpm);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    // Initialize the GPIO line
    if (initializeGPIO(chip, GPIO_PIN) < 0) {
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize the log file
    if (initializeLogFile("motor_rpm.log") < 0) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    unsigned int currentPulseCount = pulseCount;
    float currentRPM;
    time_t lastPrintTime = 0;

    // Main loop
    while (!terminate) {
        readPulseCountAndCalculateRPM(line, &pulseCount, &currentRPM);

        time_t now = time(NULL);
        if (now - lastPrintTime >= SAMPLE_INTERVAL_SEC) {
            if (logRPMData(logFile, currentRPM) < 0) {
                terminate = 1; // Stop on log error
            }
            printRPM(currentRPM);
            lastPrintTime = now;
        }

        struct timespec sleepTime;
        sleepTime.tv_sec = 0;
        sleepTime.tv_nsec = 100000000; // 100 ms
        nanosleep(&sleepTime, NULL);
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    if (logFile) {
        fclose(logFile);
    }

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

