#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define TOUCH_SENSOR_GPIO 4
#define RELAY_GPIO 17

// Define constants
#define TOUCH_TIMEOUT 10000 // 10 seconds in milliseconds
#define POLLING_INTERVAL 50 // milliseconds

// Global variables
volatile sig_atomic_t program_running = 1;
volatile sig_atomic_t relay_state = 0; // 0 = OFF, 1 = ON
volatile sig_atomic_t touch_start_time = 0;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void toggle_relay();
void failsafe_timeout();
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    if (gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d to input mode\n", TOUCH_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d to output mode\n", RELAY_GPIO);
        gpioTerminate();
        return 1;
    }

    return 0; // Indicate success
}

// Read the touch sensor
int read_touch_sensor() {
    int touch_value = gpioRead(TOUCH_SENSOR_GPIO);
    if (touch_value < 0) {
        fprintf(stderr, "Error reading GPIO%d: %d\n", TOUCH_SENSOR_GPIO, touch_value);
        return -1; // Indicate error
    }
    return touch_value;
}

// Toggle the relay state
void toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_GPIO, relay_state);
    printf("Relay toggled to state: %d\n", relay_state);
}

// Failsafe timeout function
void failsafe_timeout() {
    printf("Touch sensor continuously HIGH for %dms, forcing relay OFF.\n", TOUCH_TIMEOUT);
    gpioWrite(RELAY_GPIO, 0); // Turn relay OFF
    relay_state = 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is OFF
    gpioTerminate();
    printf("pigpio terminated.\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int touch_value = read_touch_sensor();
        if (touch_value < 0) {
            fprintf(stderr, "Error reading touch sensor, exiting.\n");
            cleanup();
            return 1;
        }

        if (touch_value == 1) {
            if (touch_start_time == 0) {
                touch_start_time = time_time(); // Use time_time for milliseconds
            }
            if (time_time() - touch_start_time > TOUCH_TIMEOUT) {
                failsafe_timeout();
            }
        } else {
            touch_start_time = 0; // Reset timeout
        }

        if (touch_value == 1) {
            toggle_relay();
        }

        gpioDelay(POLLING_INTERVAL); // Wait 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

