void failsafe_timeout() {
    printf("Touch sensor continuously HIGH for %dms, forcing relay OFF.\n", TOUCH_TIMEOUT);
    gpioWrite(RELAY_GPIO, 0); // Turn relay OFF
    relay_state = 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is OFF
    gpioTerminate();
    printf("pigpio terminated.\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int touch_value = read_touch_sensor();
        if (touch_value < 0) {
            fprintf(stderr, "Error reading touch sensor, exiting.\n");
            cleanup();
            return 1;
        }

        if (touch_value == 1) {
            if (touch_start_time == 0) {
                touch_start_time = time_time(); // Use time_time for milliseconds
            }
            if (time_time() - touch_start_time > TOUCH_TIMEOUT) {
                failsafe_timeout();
            }
        } else {
            touch_start_time = 0; // Reset timeout
        }

        if (touch_value == 1) {
            toggle_relay();
        }

        gpioDelay(POLLING_INTERVAL); // Wait 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

