#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define VALVE_PWM_PIN 18
#define VALVE_ENABLE_PIN 23
#define FLOW_SENSOR_PIN 24

// Define constants
#define PULSES_PER_LITER 450.0
#define TARGET_FLOW_RATE_MIN 0.0
#define TARGET_FLOW_RATE_MAX 20.0
#define PWM_FREQUENCY 1000 // Hz
#define SAMPLE_INTERVAL_MS 100

// Global variables
volatile int pulse_count = 0;
FILE *log_file = NULL;
double target_flow_rate = 0.0;
int running = 1;

// Function prototypes
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data);
double calculate_flow_rate(int pulse_count);
double proportional_control(double target_flow_rate, double current_flow_rate, double Kp);
void set_valve_position(int duty_cycle);
void log_data(double timestamp_ms, double flow_rate, int valve_position);
void signal_handler(int signal);

// Interrupt service routine for flow sensor
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data)
{
    pulse_count++;
}

// Calculate flow rate from pulse count
double calculate_flow_rate(int pulse_count)
{
    return (double)pulse_count / PULSES_PER_LITER * 60.0; // L/min
}

// Proportional control algorithm
double proportional_control(double target_flow_rate, double current_flow_rate, double Kp)
{
    double error = target_flow_rate - current_flow_rate;
    double duty_cycle = Kp * error;
    return duty_cycle;
}

// Set valve position using PWM
void set_valve_position(int duty_cycle)
{
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 255) duty_cycle = 255;
    gpioPWM(VALVE_PWM_PIN, duty_cycle);
}

// Log data to CSV file
void log_data(double timestamp_ms, double flow_rate, int valve_position)
{
    if (log_file != NULL)
    {
        fprintf(log_file, "%.0f,%.2f,%d\n", timestamp_ms, flow_rate, valve_position);
        fflush(log_file); // Ensure data is written to disk immediately
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

int main(int argc, char *argv[])
{
    // Check command-line arguments
    if (argc != 2)
    {
        fprintf(stderr, "Usage: %s <target_flow_rate_L/min>\n", argv[0]);
        return 1;
    }

    char *endptr;
    target_flow_rate = strtod(argv[1], &endptr);

    if (*endptr != '\0' || target_flow_rate < TARGET_FLOW_RATE_MIN || target_flow_rate > TARGET_FLOW_RATE_MAX)
    {
        fprintf(stderr, "Error: Invalid target flow rate. Must be a float between %.2f and %.2f L/min.\n", TARGET_FLOW_RATE_MIN, TARGET_FLOW_RATE_MAX);
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT);
    gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT);
    gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT);

    // Enable the valve
    gpioWrite(VALVE_ENABLE_PIN, 1);

    // Set PWM frequency
    gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY);

    // Register interrupt service routine
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_sensor_isr, NULL) != 0)
    {
        fprintf(stderr, "Error: Failed to register ISR\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.csv", "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Error: Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0)
    {
        fprintf(log_file, "timestamp_ms,flow_rate,valve_position\n");
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (running)
    {
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        double timestamp_ms = (current_time.tv_sec - start_time.tv_sec) * 1000.0 + (current_time.tv_nsec - start_time.tv_nsec) / 1000000.0;

        // Sample flow rate
        int pulse_count_local = pulse_count;
        pulse_count = 0; // Reset pulse count for the next interval
        double flow_rate = calculate_flow_rate(pulse_count_local);

        // Proportional control
        double duty_cycle = proportional_control(target_flow_rate, flow_rate, 1.0);
        int valve_position = (int)duty_cycle;
        set_valve_position(valve_position);

        // Log data
        log_data(timestamp_ms, flow_rate, valve_position);

        // Wait for the next sample interval
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    gpioWrite(VALVE_ENABLE_PIN, 0); // Disable valve
    gpioPWM(VALVE_PWM_PIN, 0); // Set PWM to 0
    if (log_file != NULL)
    {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

