#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LOCK1_PIN 17
#define LOCK2_PIN 27
#define BUTTON_PIN 22

// Define SPI channel and speed
#define SPI_CHANNEL 0
#define SPI_SPEED 100000 // 100 kHz

// Define valid RFID tag
const unsigned char valid_tag[] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A};

// Define log file path
#define LOG_FILE "/var/log/door_access.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_rfid_tag(unsigned char *tag);
int validate_tag(const unsigned char *tag);
int read_button_state();
void control_lock(int lock_pin, int state);
void log_event(const char *event_type, const char *message);
void signal_handler(int signal);

// Function to read RFID tag via SPI
int read_rfid_tag(unsigned char *tag) {
    char tx_buf[1] = {0x00}; // Dummy data to send to the RFID reader
    char rx_buf[10];
    int result;

    result = spiXfer(spi_handle, tx_buf, rx_buf, 10);
    if (result != 10) {
        log_event("RFID Read Failure", "SPI transfer failed.");
        return -1; // Indicate failure
    }

    memcpy(tag, rx_buf, 10);
    return 0; // Indicate success
}

// Function to validate RFID tag
int validate_tag(const unsigned char *tag) {
    if (tag == NULL) return -1; // Handle null pointer
    for (int i = 0; i < 10; i++) {
        if (tag[i] != valid_tag[i]) {
            return -1; // Invalid tag
        }
    }
    return 0; // Valid tag
}

// Function to read button state with debouncing
int read_button_state() {
    int button_state = gpioRead(BUTTON_PIN);
    gpioDelay(50000); // 50 ms debounce
    return button_state;
}

// Function to control the lock
void control_lock(int lock_pin, int state) {
    gpioWrite(lock_pin, state);
}

// Function to log events with ISO-8601 timestamp
void log_event(const char *event_type, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, shutting down...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK1_PIN, PI_OUTPUT);
    gpioSetMode(LOCK2_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP); // Enable pull-up resistor

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned char rfid_tag[10];
    int button_pressed = 0;

    // Main loop
    while (!terminate) {
        // Read RFID tag
        if (read_rfid_tag(rfid_tag) == 0) {
            // Validate RFID tag
            int tag_valid = validate_tag(rfid_tag);
            if (tag_valid == 0) {
                // Button press required
                if (read_button_state() == 0) {
                    // Disengage locks
                    control_lock(LOCK1_PIN, 0);
                    control_lock(LOCK2_PIN, 0);
                    gpioDelay(5000000); // 5 seconds
                    control_lock(LOCK1_PIN, 1);
                    control_lock(LOCK2_PIN, 1);
                    log_event("Access Granted", "RFID and button authentication successful.");
                    button_pressed = 1;
                } else {
                    log_event("Invalid Button Press", "Button pressed without valid RFID tag.");
                }
            } else {
                log_event("Invalid RFID Tag", "RFID tag validation failed.");
            }
        } else {
            log_event("RFID Read Failure", "RFID read failed.");
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Clean up
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

