        fprintf(stderr, "Error: Failed to reset MPR121\n");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    // Configure Electrode Filtering
    if (i2cWriteByteData(i2c_handle, MPR121_CONFIG1, 0x20) < 0) {
        fprintf(stderr, "Error: Failed to configure Electrode Filtering\n");
        return -1;
    }

    // Set Touch and Release Thresholds for all 12 electrodes
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + (i * 2), 0x30) < 0) { // Touch Threshold
            fprintf(stderr, "Error: Failed to set touch threshold for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + (i * 2), 0x10) < 0) { // Release Threshold
            fprintf(stderr, "Error: Failed to set release threshold for electrode %d\n", i);
            return -1;
        }
    }

    // Enable Run Mode
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x8F) < 0) {
        fprintf(stderr, "Error: Failed to enable run mode\n");
        return -1;
    }

    return 0;
}

// Function to read the touch status from the MPR121
int read_touch_status(unsigned char *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }
    *touch_status = buf[1];
    return 0;
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Function to log the relay state to a file
void log_relay_state(int state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d Relay: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            state ? "ON" : "OFF");
    fflush(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    unsigned char touch_status;
    int relay_state = 0; // 0 = OFF, 1 = ON

    printf("MPR121 Relay Control Program\n");

    // Main loop
    while (program_running) {
        if (read_touch_status(&touch_status) == 0) {
            for (int i = 0; i < 12; i++) {
                if (touch_status & (1 << i)) {
                    relay_state = 1;
                    break;
                }
            }

            control_relay(relay_state);
            log_relay_state(relay_state);
        } else {
            fprintf(stderr, "Error: Failed to read touch status, retrying...\n");
        }

        gpioDelay(50000); // 50ms delay
    }

    // Cleanup
    control_relay(0); // Turn off relay before exiting
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program finished.\n");
    return 0;
}

