#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins for the valves
#define VALVE_1_GPIO 17
#define VALVE_2_GPIO 18

// Define GPIO chip name (usually "gpiochip0" for Raspberry Pi)
#define GPIO_CHIP_NAME "gpiochip0"

// Define log file name
#define LOG_FILE "valve_log.txt"

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *valve1_line;
struct gpiod_line *valve2_line;

// Function prototypes
int initialize_gpio(void);
int set_valve_state(struct gpiod_line *line, int state);
int log_event(const char *event_description);
void cleanup_gpio(void);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Initialize GPIO chip and lines
int initialize_gpio(void) {
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get the line for Valve 1
    valve1_line = gpiod_chip_get_line(chip, VALVE_1_GPIO);
    if (!valve1_line) {
        perror("Error getting Valve 1 line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get the line for Valve 2
    valve2_line = gpiod_chip_get_line(chip, VALVE_2_GPIO);
    if (!valve2_line) {
        perror("Error getting Valve 2 line");
        gpiod_chip_close(chip);
        gpiod_line_release(valve1_line);
        return -1;
    }

    // Request the lines for output
    ret = gpiod_line_request_output(valve1_line, "valve1", 0);
    if (ret < 0) {
        perror("Error requesting Valve 1 line for output");
        gpiod_chip_close(chip);
        gpiod_line_release(valve1_line);
        gpiod_line_release(valve2_line);
        return -1;
    }

    ret = gpiod_line_request_output(valve2_line, "valve2", 0);
    if (ret < 0) {
        perror("Error requesting Valve 2 line for output");
        gpiod_chip_close(chip);
        gpiod_line_release(valve1_line);
        gpiod_line_release(valve2_line);
        gpiod_line_release(valve1_line);
        return -1;
    }

    return 0;
}

// Set the state of a valve (1 for ON, 0 for OFF)
int set_valve_state(struct gpiod_line *line, int state) {
    int ret;

    ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        perror("Error setting valve state");
        return -1;
    }

    return 0;
}

// Log an event to the log file
int log_event(const char *event_description) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    // Format the timestamp in ISO 8601 format
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    // Open the log file in append mode
    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    // Write the event description to the log file
    fprintf(fp, "%s: %s\n", timestamp, event_description);

    // Close the log file
    fclose(fp);

    return 0;
}

// Cleanup GPIO resources
void cleanup_gpio(void) {
    int ret;

    // Release the GPIO lines
    ret = gpiod_line_release(valve1_line);
    if (ret < 0) {
        perror("Error releasing Valve 1 line");
    }

    ret = gpiod_line_release(valve2_line);
    if (ret < 0) {
        perror("Error releasing Valve 2 line");
    }

    // Close the GPIO chip
    ret = gpiod_chip_close(chip);
    if (ret < 0) {
        perror("Error closing GPIO chip");
    }
}

