#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPR121 I2C address
#define MPR121_ADDR 0x5A

// MPR121 register addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42
#define MPR121_FILTERTH_0 0x5B
#define MPR121_ELE_CFG 0x5C
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_ECR 0x5E

// GPIO pin for relay control
#define RELAY_PIN 17

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int read_touch_status(unsigned short *touch_status);
void toggle_relay();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// MPR121 initialization function
int mpr121_init() {
    // Stop mode
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set stop mode\n");
        return -1;
    }
    gpioDelay(100000); // 100ms delay

    // Set touch and release thresholds for all electrodes
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, MPR121_TOUCHTH_0 + 2 * i, 0x10) < 0) {
            fprintf(stderr, "Error: Failed to set touch threshold for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, MPR121_RELEASETH_0 + 2 * i, 0x0A) < 0) {
            fprintf(stderr, "Error: Failed to set release threshold for electrode %d\n", i);
            return -1;
        }
    }

    // Set filter/charge time
    if (i2cWriteByteData(i2c_handle, MPR121_FILTERTH_0, 0x20) < 0) {
        fprintf(stderr, "Error: Failed to set filter/charge time\n");
        return -1;
    }

    // Set electrode current
    if (i2cWriteByteData(i2c_handle, MPR121_ELE_CFG, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set electrode current\n");
        return -1;
    }

    // Enter run mode
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x20) < 0) {
        fprintf(stderr, "Error: Failed to enter run mode\n");
        return -1;
    }
    gpioDelay(100000); // 100ms delay

    return 0;
}

// Function to read touch status from MPR121
int read_touch_status(unsigned short *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }
    *touch_status = (buf[1] << 8) | buf[0];
    return 0;
}

// Function to toggle the relay
void toggle_relay() {
    int current_level = gpioRead(RELAY_PIN);
    gpioWrite(RELAY_PIN, !current_level);
    printf("Relay toggled to %d\n", !current_level);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set relay pin as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Initially off

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned short touch_status;
    int relay_state = 0; // 0 = off, 1 = on

    // Main loop
    while (!terminate) {
        if (read_touch_status(&touch_status) == 0) {
            if (touch_status > 0) {
                toggle_relay();
                relay_state = !relay_state;
                gpioWrite(RELAY_PIN, relay_state);
            }
        } else {
            fprintf(stderr, "Error: Failed to read touch status, retrying...\n");
        }
        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off on exit
    gpioTerminate();

    return 0;
}

