#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 17
#define RELAY_PIN 18

// Define constants
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_DURATION_S 2
#define POLLING_INTERVAL_MS 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static time_t last_unlock_time = 0;

// Function prototypes
void signal_handler(int signal);
void log_event(const char *event_type, const char *event_description);
void unlock_door();
void rate_limit_check(time_t current_time);
void motion_detected_callback(int gpio, int level, uint32_t tick);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to log events with millisecond precision
void log_event(const char *event_type, const char *event_description) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s.%03d: %s: %s\n", buf, (int)(now % 1000), event_type, event_description);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to unlock the door
void unlock_door() {
    log_event("Door Unlock", "Door unlocked.");
    gpioWrite(RELAY_PIN, 1); // Activate relay
    gpioDelay(UNLOCK_DURATION_MS * 1000); // Delay for unlock duration
    gpioWrite(RELAY_PIN, 0); // Deactivate relay
    log_event("Door Lock", "Door locked.");
}

// Function to check rate limiting
void rate_limit_check(time_t current_time) {
    if (difftime(current_time, last_unlock_time) < RATE_LIMIT_DURATION_S) {
        log_event("Rate Limit", "Rate limit exceeded. Ignoring motion event.");
    }
}

// Callback function for motion detection
void motion_detected_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge detected
        time_t now = time(NULL);
        log_event("Motion Detected", "Motion detected.");
        unlock_door();
        rate_limit_check(now);
    }
}

