#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the vibration motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 100

// Define the range for the number of steps in a pattern
#define MIN_STEPS 5
#define MAX_STEPS 15

// Define the range for the duration of each step (ms)
#define MIN_DURATION 50
#define MAX_DURATION 200

// Define the range for the PWM duty cycle (0-255)
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 255

// Global variables
volatile sig_atomic_t shutdown_flag = 0;

// Function prototypes
void signal_handler(int signal);
void generate_pattern(int *motor1_duty_cycle, int *motor2_duty_cycle, int *duration, int *num_steps);
void play_pattern(int motor1_duty_cycle, int motor2_duty_cycle, int duration, int num_steps);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, shutting down gracefully...\n");
        shutdown_flag = 1;
    }
}

// Function to generate a random haptic feedback pattern
void generate_pattern(int *motor1_duty_cycle, int *motor2_duty_cycle, int *duration, int *num_steps) {
    // Seed the random number generator with the current time
    srand(time(NULL));

    // Generate random values for each parameter
    *motor1_duty_cycle = rand() % (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE + 1) + MIN_DUTY_CYCLE;
    *motor2_duty_cycle = rand() % (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE + 1) + MIN_DUTY_CYCLE;
    *duration = rand() % (MAX_DURATION - MIN_DURATION + 1) + MIN_DURATION;
    *num_steps = rand() % (MAX_STEPS - MIN_STEPS + 1) + MIN_STEPS;
}

// Function to play a haptic feedback pattern
void play_pattern(int motor1_duty_cycle, int motor2_duty_cycle, int duration, int num_steps) {
    for (int i = 0; i < num_steps; i++) {
        gpioPWM(MOTOR1_GPIO, motor1_duty_cycle);
        gpioPWM(MOTOR2_GPIO, motor2_duty_cycle);
        gpioDelay(duration * 1000); // Convert ms to microseconds
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    if (gpioSetMode(MOTOR1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode\n", MOTOR1_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode\n", MOTOR2_GPIO);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency for both motors
    if (gpioSetPWMfrequency(MOTOR1_GPIO, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", MOTOR1_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(MOTOR2_GPIO, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", MOTOR2_GPIO);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Haptic feedback generator running. Press Ctrl+C to exit.\n");

    // Main loop
    while (!shutdown_flag) {
        int motor1_duty_cycle, motor2_duty_cycle, duration, num_steps;

        // Generate a random pattern
        generate_pattern(&motor1_duty_cycle, &motor2_duty_cycle, &duration, &num_steps);

        // Play the generated pattern
        play_pattern(motor1_duty_cycle, motor2_duty_cycle, duration, num_steps);
    }

    // Stop the motors and release resources before exiting
    gpioPWM(MOTOR1_GPIO, 0); // Stop motor 1
    gpioPWM(MOTOR2_GPIO, 0); // Stop motor 2
    gpioTerminate();

    printf("Haptic feedback generator stopped.\n");

    return 0;
}

