#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define DEFAULT_SCALE_FACTOR 1.0
#define DEFAULT_OFFSET 0.0
#define THRESHOLD_WEIGHT 10.0
#define TIMEOUT_MS 500

// Global variables
double scale_factor = DEFAULT_SCALE_FACTOR;
double offset = DEFAULT_OFFSET;
int solenoid_state = 0; // 0 = unlocked, 1 = locked
FILE *log_file = NULL;

// Function prototypes
int read_hx711();
double convert_to_weight(int raw_value);
int control_solenoid(double weight);
int load_calibration_data();
int save_calibration_data();
void signal_handler(int signal);

// Function to read from HX711
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for data pin to go low
    int timeout = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout < TIMEOUT_MS) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout++;
    }

    if (timeout >= TIMEOUT_MS) {
        fprintf(stderr, "Error: HX711 timeout\n");
        return -1; // Indicate timeout error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock pulse width
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock pulse width
    }

    // 25th pulse for gain selection (channel A, gain 128)
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Sign extend if negative
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to convert raw value to weight
double convert_to_weight(int raw_value) {
    return (double)(raw_value - offset) / scale_factor;
}

// Function to control the solenoid
int control_solenoid(double weight) {
    if (weight > THRESHOLD_WEIGHT) {
        if (solenoid_state == 0) {
            gpioWrite(SOLENOID_PIN, 1); // Lock
            solenoid_state = 1;
            printf("Locking solenoid\n");
        }
    } else {
        if (solenoid_state == 1) {
            gpioWrite(SOLENOID_PIN, 0); // Unlock
            solenoid_state = 0;
            printf("Unlocking solenoid\n");
        }
    }
    return solenoid_state;
}

// Function to load calibration data from file
int load_calibration_data() {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file %s. Using default values.\n", CALIBRATION_FILE);
        return -1; // Indicate failure to open file
    }

    if (fscanf(fp, "%lf %lf", &scale_factor, &offset) != 2) {
        fprintf(stderr, "Error: Could not read calibration data from file. Using default values.\n");
        fclose(fp);
        return -1; // Indicate failure to read data
    }

    fclose(fp);
    printf("Calibration data loaded: scale_factor=%.2f, offset=%.2f\n", scale_factor, offset);
    return 0; // Indicate success
}

// Function to save calibration data to file
int save_calibration_data() {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file %s for writing.\n", CALIBRATION_FILE);
        return -1; // Indicate failure to open file
    }

    fprintf(fp, "%.2f %.2f", scale_factor, offset);
    fclose(fp);
    printf("Calibration data saved: scale_factor=%.2f, offset=%.2f\n", scale_factor, offset);
    return 0; // Indicate success
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioWrite(SOLENOID_PIN, 0); // Unlock solenoid
    gpioTerminate(); // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Load calibration data
    if (load_calibration_data() != 0) {
        // Use default values if loading fails
        scale_factor = DEFAULT_SCALE_FACTOR;
        offset = DEFAULT_OFFSET;
    }

    // Perform startup calibration
    printf("Performing startup calibration...\n");
    int sum = 0;
    for (int i = 0; i < 100; i++) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error: HX711 read failed during startup calibration. Using default offset.\n");
            offset = DEFAULT_OFFSET;
            break;
        }
        sum += raw_value;
        gpioDelay(10); // Small delay between readings
    }
    offset = (double)sum / 100.0;
    printf("Startup calibration complete. New offset: %.2f\n", offset);

    // Save calibration data
    if (save_calibration_data() != 0) {
        fprintf(stderr, "Error: Failed to save calibration data.\n");
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        int raw_value = read_hx711();
        if (raw_value != -1) {
            double weight = convert_to_weight(raw_value);
            control_solenoid(weight);

            // Log data
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

            if (log_file != NULL) {
                fprintf(log_file, "%s, %.2f\n", timestamp, weight);
                fflush(log_file); // Flush to ensure data is written
            } else {
                printf("%s, %.2f\n", timestamp, weight);
            }
        }
        gpioDelay(500); // Wait 500 ms
    }

    return 0;
}

