    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    closelog();
    exit(0);
}

int main() {
