    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    // Open log file
    log_file = fopen("/var/log/window_control.log", "a");
    if (log_file == NULL) {
        syslog(LOG_ERR, "Failed to open log file, using syslog only");
    }

    log_event("Starting window control program");

    // Main loop
    while (running) {
        int rain_detected = read_rain_sensor();
        if (rain_detected == 0) {
            log_event("Rain detected");
            control_motor(1); // Close window
            gpioDelay(MOTOR_DURATION * 1000000); // Wait for motor duration
            control_motor(0); // Stop motor
            gpioDelay(CHECK_INTERVAL * 1000000); // Wait before next check
        } else {
            gpioDelay(CHECK_INTERVAL * 1000000); // Wait before next check
        }
    }

    // Cleanup and exit
    cleanup();

    return 0;
}

