// Define GPIO pins
#define HX711_DT 23
#define HX711_SCK 24
#define SOLENOID_PIN 17

// Define weight threshold
#define WEIGHT_THRESHOLD 100.0 // grams

// Define solenoid activation time
#define SOLENOID_ACTIVATION_TIME 5 // seconds

// Define timeout duration
#define TIMEOUT_DURATION 1000000 // microseconds (1 second)

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_hx711();
float convert_to_grams(int raw_value);
void control_solenoid(int activate);
void log_event(const char *event);
void signal_handler(int signal);

// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(HX711_DT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);

    // Wait for DT to go low
    int timeout_counter = 0;
    while (gpioRead(HX711_DT) == 1 && timeout_counter < TIMEOUT_DURATION) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_counter++;
    }

    if (timeout_counter >= TIMEOUT_DURATION) {
        log_event("Error: HX711 DT line stuck high.");
        return -1; // Indicate error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Short delay
        data = data << 1;
        if (gpioRead(HX711_DT)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Short delay
    }

    // Pulse SCK 25th time to set gain to 128
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Short delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Short delay

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= ~0xffffff;
    }

    return data;
}

// Function to convert raw value to grams
float convert_to_grams(int raw_value) {
    // Calibration factor (adjust this value based on your setup)
    // This is an example value.  You MUST calibrate your system.
    const float calibration_factor = 100.0; // Example: 100 raw units = 1 gram
    return (float)raw_value / calibration_factor;
}

// Function to control the solenoid
void control_solenoid(int activate) {
    gpioWrite(SOLENOID_PIN, activate);
    gpioDelay(SOLENOID_ACTIVATION_TIME * 1000000); // Convert seconds to microseconds
    gpioWrite(SOLENOID_PIN, 0);
}

// Function to log events to a file
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
    log_event("Program terminated.");

    // Release GPIO resources
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
    gpioSetMode(SOLENOID_PIN, PI_INPUT); // Set to input to avoid spurious signals

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("stock_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Kitchen Stock Monitoring System started.\n");
    log_event("System started.");

    // Main loop
    while (running) {
        int raw_value = read_hx711();
        if (raw_value != -1) {
            float weight_grams = convert_to_grams(raw_value);
            printf("Weight: %.2f g\n", weight_grams);

            if (weight_grams < WEIGHT_THRESHOLD) {
                log_event("Weight below threshold. Activating solenoid.");
                control_solenoid(1); // Activate solenoid
                log_event("Solenoid activated.");
            }
        } else {
            log_event("Error reading HX711.");
        }

        gpioDelay(1000000); // Wait 1 second
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(SOLENOID_PIN, 0);
    gpioSetMode(SOLENOID_PIN, PI_INPUT);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

