#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG_FILE "security.log"
#define WEIGHT_THRESHOLD 5.0 // kg
#define HX711_TIMEOUT_US 100000 // 100 ms timeout

// Global variables
static volatile int running = 1;
static double calibration_factor = 1.0; // Default calibration factor
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_hx711();
double convert_to_kg(int raw_value);
int calibrate_hx711();
int log_security_event(double weight);
void control_solenoid(int state);
void signal_handler(int signal);
void cleanup();

// HX711 read function
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for data line to go low
    int timeout_counter = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout_counter < HX711_TIMEOUT_US) {
        gpioDelay(1); // Wait 1 us
        timeout_counter++;
    }

    if (timeout_counter >= HX711_TIMEOUT_US) {
        fprintf(stderr, "Error: HX711 timeout waiting for data line to go low.\n");
        return -1; // Indicate timeout error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock high delay
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock low delay
    }

    // Pulse the clock pin 1 more time to set the HX711 for the next reading
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// HX711 calibration function
int calibrate_hx711() {
    double known_weight;
    int raw_value;

    printf("Place a known weight on the load cell (in kg): ");
    if (scanf("%lf", &known_weight) != 1) {
        fprintf(stderr, "Error: Invalid input for known weight.\n");
        return -1;
    }

    raw_value = read_hx711();
    if (raw_value == -1) {
        fprintf(stderr, "Error: HX711 read failed during calibration.\n");
        return -1;
    }

    calibration_factor = (double)raw_value / known_weight;

    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file for writing.\n");
        return -1;
    }

    fprintf(fp, "%lf", calibration_factor);
    fclose(fp);

    printf("Calibration factor saved to %s: %lf\n", CALIBRATION_FILE, calibration_factor);
    return 0;
}

// Convert raw value to kilograms
double convert_to_kg(int raw_value) {
    return (double)raw_value / calibration_factor;
}

// Log security event to file
int log_security_event(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s - Weight: %.2f kg - Security event triggered.\n", timestamp, weight);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Control solenoid lock
void control_solenoid(int state) {
    gpioWrite(SOLENOID_PIN, state);
    printf("Solenoid set to %s\n", state ? "HIGH" : "LOW");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
