#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define SENSOR_GPIO 16
#define RELAY_GPIO 20
#define LOG_FILE "relay_events.log"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor_line = NULL;
static struct gpiod_line *relay_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize GPIO lines
int initialize_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_GPIO);
    if (!sensor_line) {
        fprintf(stderr, "Error getting sensor GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        fprintf(stderr, "Error getting relay GPIO line: %s\n", strerror(errno));
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(sensor_line, "sensor_input") < 0) {
        fprintf(stderr, "Error requesting sensor line as input: %s\n", strerror(errno));
        gpiod_line_release(relay_line);
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(relay_line, "relay_output", 0) < 0) {
        fprintf(stderr, "Error requesting relay line as output: %s\n", strerror(errno));
        gpiod_line_release(relay_line);
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to read the sensor value
int read_sensor() {
    int value = gpiod_line_get_value(sensor_line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Function to toggle the relay state
int toggle_relay(struct gpiod_line *relay_line) {
    int current_value = gpiod_line_get_value(relay_line);
    if (current_value < 0) {
        fprintf(stderr, "Error reading relay value: %s\n", strerror(errno));
        return -1;
    }

    int new_value = (current_value == 0) ? 1 : 0;
    if (gpiod_line_set_value(relay_line, new_value) < 0) {
        fprintf(stderr, "Error setting relay value: %s\n", strerror(errno));
        return -1;
    }

    return new_value;
}

// Function to log the relay event
int log_relay_event(int relay_state) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s Relay: %s\n", buf, (relay_state == 1) ? "ON" : "OFF") < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_file); // Ensure the data is written to the file immediately
    return 0;
}

// Function to release GPIO resources
void cleanup_gpio() {
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    int relay_state = 0; // Initial relay state: OFF

    // Main loop
    while (!terminate) {
        int sensor_value = read_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting.\n");
            break;
        }

        if (sensor_value == 0) { // Obstacle detected (active-low)
            relay_state = toggle_relay(relay_line);
            if (relay_state < 0) {
                fprintf(stderr, "Error toggling relay, exiting.\n");
                break;
            }
            if (log_relay_event(relay_state) < 0) {
                fprintf(stderr, "Error logging relay event, exiting.\n");
                break;
            }
        }

        struct timespec delay = {0, 100000000}; // 100ms
        nanosleep(&delay, NULL);
    }

    // Cleanup and exit
    cleanup_gpio();
    if (log_file) {
        fclose(log_file);
    }
    return EXIT_SUCCESS;
}

