    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log motion event to file
void log_motion(const char *timestamp) {
    if (log_file != NULL) {
        fprintf(log_file, "%s: Motion detected\n", timestamp);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to activate the buzzer for 2 seconds
void activate_buzzer() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 2;  // 2 seconds
    sleep_time.tv_nsec = 0; // 0 nanoseconds

    if (gpiod_line_set_value(buzzer_line, 1) < 0) {
        fprintf(stderr, "Error setting buzzer value: %s\n", strerror(errno));
    }
    usleep(sleep_time.tv_nsec); // Convert to microseconds

    if (gpiod_line_set_value(buzzer_line, 0) < 0) {
        fprintf(stderr, "Error resetting buzzer value: %s\n", strerror(errno));
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, cleaning up...\n", sig);
        terminate = 1;
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        fclose(log_file);
        return 1;
    }

    // Request PIR sensor pin as input
    pir_line = gpiod_chip_get_line(chip, PIR_SENSOR_PIN);
    if (!pir_line) {
        fprintf(stderr, "Error getting PIR sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    if (gpiod_line_request_input(pir_line, "motion_sensor") < 0) {
        fprintf(stderr, "Error requesting PIR sensor line as input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    // Request buzzer pin as output
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Error getting buzzer line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Error requesting buzzer line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int pir_value = gpiod_line_get_value(pir_line);
        if (pir_value < 0) {
            fprintf(stderr, "Error reading PIR sensor value: %s\n", strerror(errno));
            break; // Exit loop on error
        }

        if (pir_value == 1) {
            char *timestamp = get_timestamp();
            printf("Motion detected at %s\n", timestamp);
            log_motion(timestamp);
            activate_buzzer();
        }

        usleep(100000); // Check every 100ms
    }

    // Cleanup
    printf("Cleaning up GPIO resources...\n");
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0); // Ensure buzzer is off
        gpiod_line_release(buzzer_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }

    printf("Exiting.\n");
    return 0;
}

