#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 18
#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_NUMBER 18

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
}

// Function to read watering duration from configuration file
int read_watering_duration(const char *filename, int *duration) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening configuration file: %s\n", strerror(errno));
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading from configuration file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);

    char *token = strtok(line, "=");
    if (token == NULL) {
        fprintf(stderr, "Error: Invalid configuration file format\n");
        return -1;
    }

    char *endptr;
    long parsed_duration = strtol(token, &endptr, 10);

    if (*endptr != '\0' && *endptr != '\n') {
        fprintf(stderr, "Error: Invalid duration value\n");
        return -1;
    }

    if (parsed_duration <= 0 || parsed_duration > 3600) {
        fprintf(stderr, "Error: Duration must be between 1 and 3600 seconds\n");
        return -1;
    }

    *duration = (int)parsed_duration;
    return 0;
}

// Function to initialize the GPIO line
int initialize_gpio(struct gpiod_chip *chip, struct gpiod_line *line) {
    int ret = gpiod_line_request_output(line, "watering_system", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to turn the valve on
int turn_valve_on(struct gpiod_line *line) {
    int ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to turn the valve off
int turn_valve_off(struct gpiod_line *line) {
    int ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to sleep for a specified duration
void sleep_duration(int duration) {
    struct timespec req = {0};
    req.tv_sec = duration;
    req.tv_nsec = 0;
    nanosleep(&req, NULL);
}

// Function to release the GPIO line and close the chip
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line) {
    int ret = gpiod_line_release(line);
    if (ret < 0) {
        fprintf(stderr, "Error releasing GPIO line: %s\n", strerror(-ret));
    }

    ret = gpiod_chip_close(chip);
    if (ret < 0) {
        fprintf(stderr, "Error closing GPIO chip: %s\n", strerror(-ret));
    }
}

int main() {
    int duration;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP_NAME);
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE_NUMBER);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_LINE_NUMBER);
        cleanup_gpio(chip, NULL);
        return 1;
    }

    // Initialize GPIO line
    if (initialize_gpio(chip, line) < 0) {
        cleanup_gpio(chip, line);
        return 1;
    }

    // Read watering duration from configuration file
    if (read_watering_duration("watering.conf", &duration) < 0) {
        cleanup_gpio(chip, line);
        return 1;
    }

    printf("Watering duration: %d seconds\n", duration);

    // Main loop
    while (!terminate) {
        // Turn valve on
        if (turn_valve_on(line) < 0) {
            break;
        }
        printf("Valve turned ON\n");

        // Sleep for the specified duration
        sleep_duration(duration);

        // Turn valve off
        if (turn_valve_off(line) < 0) {
            break;
        }
        printf("Valve turned OFF\n");
    }

    // Cleanup and exit
    cleanup_gpio(chip, line);
    return 0;
}

