    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LEFT_MOTOR_IN1, PI_OUTPUT);
    gpioSetMode(LEFT_MOTOR_IN2, PI_OUTPUT);
    gpioSetMode(LEFT_MOTOR_PWM, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_IN3, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_IN4, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LEFT_MOTOR_PWM, MOTOR_PWM_FREQ);
    gpioSetPWMfrequency(RIGHT_MOTOR_PWM, MOTOR_PWM_FREQ);

    // Open log file
    log_file = fopen("trace_log.txt", "a");
