        int right_speed = 150;

        if (middle_sensor == 0) {
            // Straight
            left_speed = 150;
            right_speed = 150;
        } else if (left_sensor == 0) {
            // Turn right
            left_speed = 75;
            right_speed = 150;
        } else if (right_sensor == 0) {
            // Turn left
            left_speed = 150;
            right_speed = 75;
        } else {
            // Stop
            left_speed = 0;
            right_speed = 0;
        }

        set_motor_speed(left_speed, right_speed);
        log_data(left_sensor, middle_sensor, right_sensor, left_speed, right_speed);

        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    set_motor_speed(0, 0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

