#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define servo pulse width limits
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Define servo pulse width for locked position
#define LOCKED_PULSE_WIDTH 1000

// Define servo pulse width for unlocked position
#define UNLOCKED_PULSE_WIDTH 2000

// Global variable to track servo position
int servo_position = 0;

// Function prototypes
int initialize_gpio();
void lock_door();
void unlock_door();
void handle_button_press(int gpio_pin);
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    // Enable pull-up resistors for the buttons
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    return 0; // Indicate success
}

// Lock the door
void lock_door() {
    gpioServo(SERVO_PIN, LOCKED_PULSE_WIDTH);
    servo_position = 0; // Update servo position
    printf("Door locked\n");
}

// Unlock the door
void unlock_door() {
    gpioServo(SERVO_PIN, UNLOCKED_PULSE_WIDTH);
    servo_position = 1; // Update servo position
    printf("Door unlocked\n");
}

// Handle button press
void handle_button_press(int gpio_pin) {
    int button_state = gpioRead(gpio_pin);
    if (button_state == 0) {
        gpioDelay(100); // Debounce
        if (gpioRead(gpio_pin) == 0) {
            if (gpio_pin == LOCK_BUTTON_PIN) {
                lock_door();
            } else if (gpio_pin == UNLOCK_BUTTON_PIN) {
                unlock_door();
            }
        }
    }
}

// Cleanup GPIO resources
void cleanup_gpio() {
    gpioServo(SERVO_PIN, 0); // Stop servo pulses
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        handle_button_press(LOCK_BUTTON_PIN);
        handle_button_press(UNLOCK_BUTTON_PIN);
        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    return 0;
}

