#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for motor 1 and motor 2
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define pulse duration in milliseconds
#define PULSE_DURATION_MS 200

// Define delay between pulses in milliseconds
#define DELAY_MS 300

// Global variables for GPIO chip and line
struct gpiod_chip *chip;
struct gpiod_line *motor1_line, *motor2_line;

// Function prototypes
int motor_on(struct gpiod_line *line);
int motor_off(struct gpiod_line *line);
void cleanup(int signum);

// Signal handler function
void cleanup(int signum) {
    printf("\nCaught signal %d, cleaning up...\n", signum);

    // Turn off motors
    motor_off(motor1_line);
    motor_off(motor2_line);

    // Release GPIO lines
    if (motor1_line) {
        gpiod_line_release(motor1_line);
    }
    if (motor2_line) {
        gpiod_line_release(motor2_line);
    }

    // Release chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to turn a motor on
int motor_on(struct gpiod_line *line) {
    int ret;
    struct gpiod_line_request_config config;

    memset(&config, 0, sizeof(config));
    config.consumer = "motor_on";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting line for output: %d\n", ret);
        return ret;
    }

    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting line value to 1: %d\n", ret);
        gpiod_line_release(line);
        return ret;
    }

    return 0;
}

// Function to turn a motor off
int motor_off(struct gpiod_line *line) {
    int ret;

    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting line value to 0: %d\n", ret);
        return ret;
    }

    return 0;
}

int main() {
    int ret;

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %d\n", chip);
        return 1;
    }

    // Get line for motor 1
    motor1_line = gpiod_chip_get_line(chip, MOTOR1_GPIO);
    if (!motor1_line) {
        fprintf(stderr, "Error getting line for motor 1: %d\n", motor1_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Get line for motor 2
    motor2_line = gpiod_chip_get_line(chip, MOTOR2_GPIO);
    if (!motor2_line) {
        fprintf(stderr, "Error getting line for motor 2: %d\n", motor2_line);
        gpiod_line_release(motor1_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Turn motor 1 on
        if (motor_on(motor1_line) < 0) {
            fprintf(stderr, "Error turning motor 1 on, exiting.\n");
            cleanup(SIGTERM);
        }

        // Delay
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = PULSE_DURATION_MS * 1000000; // Convert ms to ns
        nanosleep(&delay, NULL);

        // Turn motor 1 off
        if (motor_off(motor1_line) < 0) {
            fprintf(stderr, "Error turning motor 1 off, exiting.\n");
            cleanup(SIGTERM);
        }

        // Delay
        delay.tv_sec = 0;
        delay.tv_nsec = DELAY_MS * 1000000; // Convert ms to ns
        nanosleep(&delay, NULL);

        // Turn motor 2 on
        if (motor_on(motor2_line) < 0) {
            fprintf(stderr, "Error turning motor 2 on, exiting.\n");
            cleanup(SIGTERM);
        }

        // Delay
        delay.tv_sec = 0;
        delay.tv_nsec = PULSE_DURATION_MS * 1000000; // Convert ms to ns
        nanosleep(&delay, NULL);

        // Turn motor 2 off
        if (motor_off(motor2_line) < 0) {
            fprintf(stderr, "Error turning motor 2 off, exiting.\n");
            cleanup(SIGTERM);
        }
    }

    return 0;
}

