        gpiod_chip_close(chip);
        gpiod_line_release(sound_sensor_line);
        return -1;
    }

    if (gpiod_line_request_input(sound_sensor_line, "sound_sensor") < 0) {
        fprintf(stderr, "Error requesting sound sensor line as input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(sound_sensor_line);
        gpiod_line_release(alarm_led_line);
        return -1;
    }

    if (gpiod_line_request_output(alarm_led_line, "alarm_led", 0) < 0) {
        fprintf(stderr, "Error requesting alarm LED line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(sound_sensor_line);
        gpiod_line_release(alarm_led_line);
        return -1;
    }

    return 0;
}

// ZeroMQ initialization function
int init_zeromq(void) {
    context = zmq_ctx_new();
    if (!context) {
        fprintf(stderr, "Error creating ZeroMQ context: %s\n", zmq_strerror(errno));
        return -1;
    }

    subscriber = zmq_socket(context, ZMQ_SUB);
    if (!subscriber) {
        fprintf(stderr, "Error creating ZeroMQ socket: %s\n", zmq_strerror(errno));
        zmq_ctx_destroy(context);
        return -1;
    }

    int rc = zmq_connect(subscriber, ZMQ_ENDPOINT);
    if (rc != 0) {
        fprintf(stderr, "Error connecting ZeroMQ socket: %s\n", zmq_strerror(errno));
        zmq_close(subscriber);
        zmq_ctx_destroy(context);
        return -1;
    }

    rc = zmq_setsockopt(subscriber, ZMQ_SUBSCRIBE, ZMQ_TOPIC, strlen(ZMQ_TOPIC));
    if (rc != 0) {
        fprintf(stderr, "Error setting ZeroMQ subscribe option: %s\n", zmq_strerror(errno));
        zmq_close(subscriber);
        zmq_ctx_destroy(context);
        return -1;
    }

    return 0;
}

// GPIO cleanup function
void cleanup_gpio(void) {
    if (sound_sensor_line) {
        gpiod_line_release(sound_sensor_line);
    }
    if (alarm_led_line) {
        gpiod_line_release(alarm_led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

