        zmq_ctx_destroy(context);
    }
}

// Sound sensor callback function
void sound_sensor_callback(const struct gpiod_line *line, int value) {
    if (value == 0) { // Active low
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 10000000; // 10 ms
        nanosleep(&ts, NULL);

        // Publish alert via ZeroMQ
        char buffer[100];
        snprintf(buffer, sizeof(buffer), "{\"timestamp\": %ld, \"event\": \"SOUND_DETECTED\"}", time(NULL));
        int rc = zmq_send(subscriber, buffer, strlen(buffer), 0);
        if (rc == -1) {
            fprintf(stderr, "Error sending ZeroMQ message: %s\n", zmq_strerror(errno));
        }
    }
}

// Alarm node main function
void alarm_node_main(void) {
    struct zmq_msg_t zmq_msg;
    zmq_msg_init(&zmq_msg);

    while (1) {
        // Receive message from ZeroMQ
        int rc = zmq_msg_recv(&zmq_msg, subscriber, 0);
        if (rc == -1) {
            if (errno == EINTR) {
                // Interrupted by signal, exit loop
                break;
            }
            fprintf(stderr, "Error receiving ZeroMQ message: %s\n", zmq_strerror(errno));
            zmq_msg_close(&zmq_msg);
            continue; // Try again
        }

        // Process message
        char *message = (char *)zmq_msg_data(&zmq_msg);
        int message_size = zmq_msg_size(&zmq_msg);
        char topic[100];
        char event[100];

        if (sscanf(message, "{\"timestamp\": %ld, \"event\": \"%99[^\"]\"}", &time_t timestamp, topic, sizeof(topic), event, sizeof(event)) == 3) {
            printf("Received message: %s\n", message);

            // Activate alarm LED
            if (strcmp(event, "SOUND_DETECTED") == 0) {
                if (gpiod_line_set_value(alarm_led_line, 1) < 0) {
                    fprintf(stderr, "Error setting alarm LED value: %s\n", strerror(errno));
                }
                struct timespec ts;
