#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <math.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define NUM_SENSORS 4
#define SENSOR_ADDRESSES {0x23, 0x24, 0x25, 0x26}
#define CONVERSION_TIME_MS 180
#define MAX_RETRIES 3

volatile sig_atomic_t program_running = 1;
int i2c_fds[NUM_SENSORS];

void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

float read_bh1750(int fd, int address) {
    unsigned char buf[2];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        if (ioctl(fd, I2C_SLAVE, address) < 0) {
            fprintf(stderr, "Error setting I2C slave address for sensor 0x%02x: %s\n", address, strerror(errno));
            return NAN;
        }

        if (write(fd, "\x20", 1) != 1) {
            fprintf(stderr, "Error writing to I2C device for sensor 0x%02x: %s\n", address, strerror(errno));
            close(fd);
            return NAN;
        }

        usleep(CONVERSION_TIME_MS * 1000); // Convert ms to microseconds

        result = read(fd, buf, 2);
        if (result != 2) {
            fprintf(stderr, "Error reading from I2C device for sensor 0x%02x: %s\n", address, strerror(errno));
            close(fd);
            return NAN;
        }

        float lux = ((buf[0] << 8) | buf[1]) / 1.2;
        return lux;
    }

    fprintf(stderr, "Failed to read sensor 0x%02x after %d retries.\n", address, MAX_RETRIES);
    return NAN;
}

int main() {
    int sockfd;
    struct sockaddr_in addr;
    char buffer[256];
    int i;
    float lux_values[NUM_SENSORS];

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C file descriptors
    for (i = 0; i < NUM_SENSORS; i++) {
        i2c_fds[i] = open(I2C_BUS, O_RDWR);
        if (i2c_fds[i] < 0) {
            fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
            return 1;
        }
    }

    while (program_running) {
        // Read sensor data
        for (i = 0; i < NUM_SENSORS; i++) {
            lux_values[i] = read_bh1750(i2c_fds[i], SENSOR_ADDRESSES[i]);
        }

        // Format data into a string
        snprintf(buffer, sizeof(buffer), "1,%.2f;2,%.2f;3,%.2f;4,%.2f",
                 lux_values[0], lux_values[1], lux_values[2], lux_values[3]);

        // Send data via UDP multicast
        sockfd = socket(AF_INET, SOCK_DGRAM, 0);
        if (sockfd < 0) {
            fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
            continue; // Try again next loop
        }

        memset(&addr, 0, sizeof(addr));
        addr.sin_family = AF_INET;
        addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
        addr.sin_port = htons(MULTICAST_PORT);

        if (sendto(sockfd, buffer, strlen(buffer), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
            fprintf(stderr, "Error sending data: %s\n", strerror(errno));
        }

        close(sockfd);

        sleep(1);
    }

    // Close I2C file descriptors
    for (i = 0; i < NUM_SENSORS; i++) {
        close(i2c_fds[i]);
    }

    return 0;
}

