#define I2C_BUS "/dev/i2c-1"
#define AWM7300V_ADDR 0x28
#define FLOW_LOG_FILE "airflow_log.txt"

volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

void signal_handler(int sig) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
}

int i2c_read_retry(int fd, unsigned char reg, unsigned char *buf, int len) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = read(fd, buf, len);
        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (errno %d): %s. Retrying...\n", errno, strerror(errno));
            usleep(100000); // 100 ms delay
            retries--;
        }
    }
    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1; // Failure
}

int i2c_write_retry(int fd, unsigned char reg, unsigned char *buf, int len) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = write(fd, buf, len);
        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write failed (errno %d): %s. Retrying...\n", errno, strerror(errno));
            usleep(100000); // 100 ms delay
            retries--;
        }
    }
    fprintf(stderr, "I2C write failed after multiple retries.\n");
    return -1; // Failure
}

int read_airflow(int fd, float *flow_rate) {
    unsigned char buf[2];
    int raw_flow;

    if (i2c_write_retry(fd, 0, NULL, 0) != 0) {
        fprintf(stderr, "Failed to send start condition.\n");
        return -1;
    }

    if (i2c_read_retry(fd, 0, buf, 2) != 0) {
        fprintf(stderr, "Failed to read flow data.\n");
        return -1;
    }

    raw_flow = (buf[0] << 8) | buf[1];
    raw_flow &= 0x3FFF; // Mask to 14 bits

    *flow_rate = (raw_flow - 3277) * 0.1;

    return 0;
}

int log_airflow(FILE *fp, float flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, %.2f SLPM\n", timestamp, flow_rate) < 0) {
        fprintf(stderr, "Failed to write to log file.\n");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    int retries = 3;
    int result;
    float flow_rate;

    signal(SIGINT, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AWM7300V_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire bus access and/or talk to slave: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(FLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    fprintf(stdout, "Airflow monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        if (read_airflow(i2c_fd, &flow_rate) == 0) {
            if (log_airflow(log_file, flow_rate) != 0) {
                fprintf(stderr, "Failed to log airflow data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read airflow data.\n");
        }
        sleep(1);
    }

    fprintf(stdout, "Closing I2C connection and log file.\n");

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }

    fprintf(stdout, "Airflow monitoring stopped.\n");

    return 0;
}

