#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// AS7341 I2C address
#define AS7341_ADDR 0x39

// AS7341 Register Addresses
#define AS7341_WHO_AM_I 0x24
#define AS7341_ENABLE 0x80
#define AS7341_CFG6 0xAF
#define AS7341_F1_DATA_HIGH 0x60
#define AS7341_F1_DATA_LOW 0x61
#define AS7341_F2_DATA_HIGH 0x62
#define AS7341_F2_DATA_LOW 0x63
#define AS7341_F3_DATA_HIGH 0x64
#define AS7341_F3_DATA_LOW 0x65
#define AS7341_F4_DATA_HIGH 0x66
#define AS7341_F4_DATA_LOW 0x67
#define AS7341_F5_DATA_HIGH 0x68
#define AS7341_F5_DATA_LOW 0x69
#define AS7341_F6_DATA_HIGH 0x6A
#define AS7341_F6_DATA_LOW 0x6B
#define AS7341_F7_DATA_HIGH 0x6C
#define AS7341_F7_DATA_LOW 0x6D
#define AS7341_F8_DATA_HIGH 0x6E
#define AS7341_F8_DATA_LOW 0x6F
#define AS7341_CLEAR_DATA_HIGH 0x70
#define AS7341_CLEAR_DATA_LOW 0x71
#define AS7341_NIR_DATA_HIGH 0x72
#define AS7341_NIR_DATA_LOW 0x73

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int as7341_init(int fd);
int as7341_read_spectral_data(int fd, uint16_t *spectral_data);
float calculate_lux(uint16_t spectral_data[10]);
int log_data(float lux);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", signal);
}

// AS7341 Initialization function
int as7341_init(int fd) {
    uint8_t who_am_i;
    uint8_t enable_value = 0x00; // Default enable value
    uint8_t cfg6_value = 0x00;  // Default CFG6 value

    // Verify WHO_AM_I register
    if (i2c_smbus_read_byte_data(fd, AS7341_WHO_AM_I) < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    who_am_i = i2c_smbus_read_byte_data(fd, AS7341_WHO_AM_I);

    if (who_am_i != 0x19) {
        fprintf(stderr, "WHO_AM_I value mismatch: expected 0x19, got 0x%02X\n", who_am_i);
        return -1;
    }

    // Power on the sensor
    if (i2c_smbus_write_byte_data(fd, AS7341_ENABLE, enable_value | 0x01) < 0) {
        fprintf(stderr, "Error writing to ENABLE register: %s\n", strerror(errno));
        return -1;
    }

    // Configure SMUX for spectral readings
    if (i2c_smbus_write_byte_data(fd, AS7341_CFG6, cfg6_value) < 0) {
        fprintf(stderr, "Error writing to CFG6 register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// AS7341 Spectral Data Reading function
int as7341_read_spectral_data(int fd, uint16_t *spectral_data) {
    uint8_t high_byte, low_byte;

    // Read F1-F8 data
    for (int i = 0; i < 8; i++) {
        high_byte = i2c_smbus_read_byte_data(fd, AS7341_F1_DATA_HIGH + 2 * i);
        low_byte = i2c_smbus_read_byte_data(fd, AS7341_F1_DATA_LOW + 2 * i);

        if (high_byte < 0 || low_byte < 0) {
            fprintf(stderr, "Error reading spectral data: %s\n", strerror(errno));
            return -1;
        }

        spectral_data[i] = (high_byte << 8) | low_byte;
    }

    // Read Clear data
    high_byte = i2c_smbus_read_byte_data(fd, AS7341_CLEAR_DATA_HIGH);
    low_byte = i2c_smbus_read_byte_data(fd, AS7341_CLEAR_DATA_LOW);

    if (high_byte < 0 || low_byte < 0) {
        fprintf(stderr, "Error reading clear data: %s\n", strerror(errno));
        return -1;
    }

    spectral_data[8] = (high_byte << 8) | low_byte;

    // Read NIR data
    high_byte = i2c_smbus_read_byte_data(fd, AS7341_NIR_DATA_HIGH);
    low_byte = i2c_smbus_read_byte_data(fd, AS7341_NIR_DATA_LOW);

    if (high_byte < 0 || low_byte < 0) {
        fprintf(stderr, "Error reading NIR data: %s\n", strerror(errno));
        return -1;
    }

    spectral_data[9] = (high_byte << 8) | low_byte;

    return 0;
}

// Lux Calculation function
float calculate_lux(uint16_t spectral_data[10]) {
    // Simplified lux calculation (replace with actual formula from datasheet)
    float lux = spectral_data[0] + spectral_data[1] + spectral_data[2] + spectral_data[3] + spectral_data[4] + spectral_data[5] + spectral_data[6] + spectral_data[7] + spectral_data[8] + spectral_data[9];
    return lux;
}

// Data Logging function
int log_data(float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

int main() {
    uint16_t spectral_data[10];
    float lux;

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, AS7341_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize the AS7341 sensor
    if (as7341_init(i2c_fd) < 0) {
        fprintf(stderr, "AS7341 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("spectral_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read spectral data
        if (as7341_read_spectral_data(i2c_fd, spectral_data) == 0) {
            // Calculate lux
            lux = calculate_lux(spectral_data);

            // Log data
            if (log_data(lux) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading spectral data.\n");
        }

        sleep(5);
    }

    // Close I2C bus and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

