void log_error(const char *message);
void signal_handler(int signal);

// Function to initialize I2C
int initialize_i2c(int address) {
    int handle = i2cOpen(I2C_BUS, address, 0);
    if (handle < 0) {
        log_error("Failed to open I2C device.");
        return -1;
    }
    return handle;
}

// Function to read sensor data
int read_sensor_data(int handle, int address, int *x_raw, int *y_raw, int *z_raw) {
    char buf[6];
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadI2CBlockData(handle, 0x28, buf, 6);
        if (result == 6) {
            // Success
            *x_raw = (buf[1] << 8) | buf[0];
            *y_raw = (buf[3] << 8) | buf[2];
            *z_raw = (buf[5] << 8) | buf[4];
            return 0; // Success
        } else {
            log_error("I2C read failed. Retrying...");
            gpioDelay(10000); // 10 ms delay
            retries--;
        }
    }

    log_error("I2C read failed after multiple retries.");
    return -1; // Failure
}

