                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 'i':
                interval = atoi(optarg);
                break;
            case 'f':
                output_file = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i interval] [-f output_file]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

