#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define TTL 1

int i2c_fd = -1;
int udp_socket = -1;

void signal_handler(int sig);
int init_i2c(void);
int init_sensor(int fd);
int read_sensor(int fd, unsigned short *raw_value);
float convert_to_lux(unsigned short raw_value);
int send_udp_multicast(float lux_value);

int main()
{
    struct sockaddr_in addr;
    struct ip_mreq mreq;
    char lux_str[20];

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_i2c() < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    if (init_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize sensor. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("socket");
        close(i2c_fd);
        return 1;
    }

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    mreq.imr_multiaddr.s_addr = inet_addr(MULTICAST_ADDR);
    mreq.imr_multiaddr.s_addr = inet_addr(MULTICAST_ADDR);
    mreq.imr_interface.s_addr = htonl(INADDR_ANY);

    if (setsockopt(udp_socket, IPPROTO_IP, IP_ADD_MEMBERSHIP, &mreq, sizeof(mreq)) < 0) {
        perror("setsockopt (IP_ADD_MEMBERSHIP)");
        close(i2c_fd);
        close(udp_socket);
        return 1;
    }

    while (1) {
        unsigned short raw_value;
        if (read_sensor(i2c_fd, &raw_value) < 0) {
            fprintf(stderr, "Failed to read sensor data. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        float lux_value = convert_to_lux(raw_value);
        snprintf(lux_str, sizeof(lux_str), "%.2f", lux_value);

        if (send_udp_multicast(lux_value) < 0) {
            fprintf(stderr, "Failed to send UDP multicast. Retrying in 1 second.\n");
        }

        sleep(1);
    }

    return 0;
}

int init_i2c(void)
{
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl (I2C_SLAVE)");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int init_sensor(int fd)
{
    unsigned char power_on_cmd = 0x01;
    unsigned char high_res_mode_cmd = CONTINUOUS_HIGH_RES_MODE;

    if (write(fd, &power_on_cmd, 1) != 1) {
        perror("write (power-on command)");
        return -1;
    }

    if (write(fd, &high_res_mode_cmd, 1) != 1) {
        perror("write (high-res mode command)");
        return -1;
    }

    return 0;
}

int read_sensor(int fd, unsigned short *raw_value)
{
    unsigned char buffer[2];
    ssize_t bytes_read;

    bytes_read = read(fd, buffer, 2);
    if (bytes_read != 2) {
        perror("read");
        return -1;
    }

    *raw_value = (buffer[0] << 8) | buffer[1];
    return 0;
}

float convert_to_lux(unsigned short raw_value)
{
    return (float)raw_value / 1.2;
}

int send_udp_multicast(float lux_value)
{
    char buffer[20];
    snprintf(buffer, sizeof(buffer), "%.2f", lux_value);

    if (sendto(udp_socket, buffer, strlen(buffer), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto");
        return -1;
    }

    return 0;
}

void signal_handler(int sig)
{
    printf("Caught signal %d. Cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (udp_socket != -1) {
        close(udp_socket);
    }
    exit(0);
}

