#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <sys/select.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/file.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define BUFFER_SIZE 256
#define TIMEOUT_SEC 2
#define TIMEOUT_USEC (TIMEOUT_SEC * 1000000)

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int sig) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
}

int setup_uart(int fd) {
    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_lflag &= ~ICANON;
    tty.c_lflag &= ~ECHO;
    tty.c_lflag &= ~ECHOE;
    tty.c_lflag &= ~ECHONL;
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK|BRKINT|PARMRK|ISTRIP|INLCR|IGNCR|ICRNL);
    tty.c_oflag &= ~OPOST;
    tty.c_oflag &= ~ONLCR;

    tty.c_cc[VMIN] = 0;  // Non-blocking read
    tty.c_cc[VTIME] = 5; // Timeout of 0.5 seconds (5 * 0.1s intervals)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int read_uart_data(int fd, char *buffer, size_t buffer_size) {
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = TIMEOUT_SEC;
    timeout.tv_usec = TIMEOUT_USEC;

    int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        fprintf(stderr, "Error from select: %s\n", strerror(errno));
        return -1;
    } else if (retval == 0) {
        // Timeout occurred
        return 0;
    } else {
        // Data is available
        ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
        if (bytes_read == -1) {
            fprintf(stderr, "Error from read: %s\n", strerror(errno));
            return -1;
        } else {
            buffer[bytes_read] = '\0';
            return bytes_read;
        }
    }
}

int parse_radar_data(const char *data, float *range) {
    char *token;
    char *data_copy = strdup(data); // Duplicate the string for strtok
    if (data_copy == NULL) {
        fprintf(stderr, "Error duplicating string: %s\n", strerror(errno));
        return -1;
    }

    token = strtok(data_copy, ",");
    if (token == NULL) {
        fprintf(stderr, "Error parsing timestamp\n");
        free(data_copy);
        return -1;
    }

    char *endptr;
    long timestamp = strtol(token, &endptr, 10);
    if (*endptr != '\0' || timestamp < 0) {
        fprintf(stderr, "Error parsing timestamp: %s\n", token);
        free(data_copy);
        return -1;
    }

    token = strtok(NULL, ",");
    if (token == NULL) {
        fprintf(stderr, "Error parsing range\n");
        free(data_copy);
        return -1;
    }

    char *endptr_range;
    *range = strtof(token, &endptr_range);
    if (*endptr_range != '\0') {
        fprintf(stderr, "Error parsing range: %s\n", token);
        free(data_copy);
        return -1;
    }

    free(data_copy);
    return 0;
}

int log_detection(float range) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Timestamp: %s, Range: %.2f meters\n", timestamp, range);
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd == -1) {
        fprintf(stderr, "Error opening UART: %s\n", strerror(errno));
        return 1;
    }

    if (setup_uart(uart_fd) != 0) {
        close(uart_fd);
        return 1;
    }

    char buffer[BUFFER_SIZE];
    float range;

    while (program_running) {
        int bytes_read = read_uart_data(uart_fd, buffer, BUFFER_SIZE);
        if (bytes_read > 0) {
            if (parse_radar_data(buffer, &range) == 0) {
                log_detection(range);
            }
        }
    }

    close(uart_fd);
    return 0;
}

