#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR 4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR 27

// Define serial port and baud rate
#define SERIAL_PORT "/dev/ttyAMA0"
#define BAUD_RATE 115200

// Global variable for serial port handle
int serial_handle = -1;

// Function prototypes
int read_sensor(int gpio_pin);
void log_sensor_data(int left, int middle, int right);
void check_emergency_stop(int left, int middle, int right);
void send_emergency_stop_signal(void);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (serial_handle != -1) {
        serClose(serial_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read sensor data
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log sensor data with timestamp
void log_sensor_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
}

// Function to check for emergency stop condition
void check_emergency_stop(int left, int middle, int right) {
    if (left == 0 && middle == 0 && right == 0) {
        send_emergency_stop_signal();
    }
}

// Function to send emergency stop signal over serial port
void send_emergency_stop_signal(void) {
    char message[] = "EMERGENCY STOP!\n";
    int bytes_written = serWrite(serial_handle, message, strlen(message));

    if (bytes_written < 0) {
        fprintf(stderr, "Error writing to serial port: %d\n", bytes_written);
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR, PI_PUD_UP);
    gpioSetMode(MIDDLE_SENSOR, PI_INPUT);
    gpioSetPullUpDown(MIDDLE_SENSOR, PI_PUD_UP);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR, PI_PUD_UP);

    // Open serial port
    serial_handle = serOpen(SERIAL_PORT, BAUD_RATE, 0); // 0 for no flags
    if (serial_handle < 0) {
        fprintf(stderr, "Error opening serial port: %d\n", serial_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read sensor data
        int left_value = read_sensor(LEFT_SENSOR);
        int middle_value = read_sensor(MIDDLE_SENSOR);
